INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 17, '');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 1, 'Heureux l\'homme qui ne suit pas les conseils des méchants Qui ne se tient pas dans la voie des pécheurs, Et qui ne s\'assied pas dans la compagnie des moqueurs;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 2, 'Mais qui prend son plaisir dans la loi de l\'Éternel, Et qui médite cette loi jour et nuit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 3, 'Il sera comme un arbre planté près des eaux courantes, Qui donne ses fruits en leur saison, Et dont le feuillage ne se flétrit point: Tout ce qu\'il entreprend lui réussira.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 4, 'Il n\'en sera pas ainsi des méchants; Mais ils seront comme la paille emportée par le vent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 5, 'C\'est pourquoi les méchants ne pourront pas subsister Au jour du jugement. Ni les pécheurs dans l\'assemblée des justes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 6, 'Car l\'Eternel veille sur la voie des justes, Mais la voie des méchants mène à la ruine.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 1, 'Pourquoi les nations s\'agitent-elles? Pourquoi les peuples forment-ils de vains projets?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 2, 'Les rois de la terre se sont soulevés, Et les princes conspirent ensemble Contre l\'Éternel et contre son Oint.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 3, '— Rompons leurs liens, disent-ils. Et jetons loin de nous leurs chaînes!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 4, '— Celui qui habite dans les deux en rira; Le Seigneur se moquera d\'eux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 5, 'Alors il leur parlera dans sa colère; Il les épouvantera par son courroux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 6, '— Et moi, dira-t-il, j\'ai sacré mon roi Sur Sion, ma montagne sainte.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 7, '— Je publierai le décret. L\'Éternel m\'a dit: «Tu es mon Fils; Aujourd\'hui je t\'ai engendré.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 8, 'Demande-moi, et je te donnerai pour héritage les nations. Pour possession les extrémités de la terre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 9, 'Tu les briseras avec un sceptre de fer; Tu les mettras en pièces comme un vase de potier.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 10, 'Maintenant donc, ô rois, ayez de l\'intelligence; Laissez-vous instruire, juges de la terre!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 11, 'Servez l\'Éternel avec crainte. Et réjouissez-vous avec tremblement.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 12, 'Rendez hommage au Fils, de peur qu\'il ne s\'irrite, Et que vous ne périssiez dans la voie que vous suivez; Car sa colère est prompte à s\'enflammer. Heureux tous ceux qui cherchent leur refuge en lui!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 1, 'Psaume de David, lorsqu\'il fuyait devant Absalom, son fils, Éternel, que mes ennemis sont nombreux! Que de gens se lèvent contre moi!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 2, 'Combien disent à mon sujet: «Point de salut pour lui auprès de Dieu!» Pause');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 3, 'Mais toi, ô Éternel, tu es mon bouclier; Tu es ma gloire, tu es celui qui me fait redresser la tête.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 4, 'Ma voix invoque l\'Éternel, Et il me répond de sa montagne sainte. Pause');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 5, 'Je me suis couché et je me suis endormi. Je me suis réveillé car l\'Éternel me soutient.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 6, 'Je ne crains point les milliers d\'hommes Qui m\'assiègent de toutes parts.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 7, 'Lève-toi, ô Éternel! Sauve-moi, ô mon Dieu! Tu as frappé à la joue tous mes ennemis; Tu as brisé les dents des méchants.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 8, 'Le salut vient de l\'Éternel. Que ta bénédiction soit sur ton peuple! Pause');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 1, 'Au Maître-chantre. — Avec instruments à cordes. — Psaume de David. Quand je crie, réponds-moi, ô Dieu de ma justice! Toi qui, à l\'heure de l\'angoisse, mets mon coeur au large, Aie pitié de moi et entends ma prière!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 2, 'Fils des hommes, jusques à quand ma gloire sera-t-elle outragée? Jusques à quand aimerez-vous la vanité, Et rechercherez-vous le mensonge? Pause');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 3, 'Sachez que l\'Éternel s\'est choisi un homme qui l\'aime: L\'Éternel m\'entend, quand je crie vers lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 4, 'Si vous êtes irrités, ne péchez point! Parlez en vos coeurs sur votre couche, et gardez le silence!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 5, 'Offrez vos sacrifices d\'un coeur sincère, Pause Et confiez-vous en l\'Éternel.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 6, 'Nombreux sont ceux qui disent: «Qui nous fera voir le bonheur?» Fais lever sur nous la lumière de ta face, ô Éternel!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 7, 'Tu as mis dans mon coeur plus de joie qu\'ils n\'en éprouvent. Quand ils ont en abondance du blé et du vin.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 8, 'Je me coucherai et je m\'endormirai en paix; Car même quand je suis seul, ô Éternel. Tu me fais reposer en sécurité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 1, 'Au maître-chantre. — Avec les flûtes. Psaume de David. Prête l\'oreille à mes paroles, ô Éternel; Sois attentif à mes soupirs!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 2, 'Écoute ma voix qui t\'implore, ô mon Roi et mon Dieu; Car c\'est à toi que s\'adresse ma prière.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 3, 'Éternel, dès le matin daigne entendre ma voix; Dès le matin je t\'offre ma requête, et j\'attends!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 4, 'Car tu n\'es pas un Dieu qui prenne plaisir au mal: Le méchant ne peut séjourner chez toi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 5, 'Les orgueilleux ne subsistent pas devant tes yeux; Tu hais tous les ouvriers d\'iniquité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 6, 'Tu feras périr ceux qui profèrent le mensonge. L\'Éternel a horreur de l\'homme de sang et de fraude.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 7, 'Mais moi, par ta grande bonté, j\'entrerai dans ta maison; Je me prosternerai dans ton sanctuaire, Avec la crainte qui t\'est due.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 8, 'Éternel, dirige-moi dans les sentiers de ta justice, A cause de ceux qui épient ma conduite. Aplanis la voie devant moi!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 9, 'Car il n\'y a point de sincérité dans leur bouche; Leur coeur ne pense qu\'à détruire; Leur gosier est un sépulcre ouvert; Leur langue est pleine de flatterie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 10, 'Châtie-les, ô Dieu! Qu\'ils échouent dans leurs desseins! Repousse-les à cause de la multitude de leurs crimes; Car ils se sont révoltés contre toi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 11, 'Mais tous ceux qui se confient en toi se réjouiront; Ils pousseront des cris d\'allégresse, à jamais. Tu étendras sur eux ta protection. Et ceux qui aiment ton nom Triompheront en toi!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 12, 'C\'est toi, ô Éternel, qui bénis le juste; Tu l\'entoures de ta bienveillance comme d\'un bouclier.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 1, 'Au maître-chantre. — Avec instruments à cordes, pour voix de basse. — Psaume de David. Éternel, ne me punis pas, dans ta colère, Et ne me châtie pas, dans l\'ardeur de ton courroux!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 2, 'Aie pitié de moi, ô Éternel; car je suis défaillant. Guéris-moi, ô Éternel; car mes os sont tout tremblants.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 3, 'Mon âme aussi est troublée; Et toi, ô Éternel, jusques à quand?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 4, 'Reviens, ô Éternel, délivre mon âme; Sauve-moi, dans ta bonté!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 5, 'Car, dans la mort il n\'est plus fait mention de toi; Qui te glorifiera dans le Séjour des morts?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 6, 'Je m\'épuise à gémir; Chaque nuit, je baigne ma couche de pleurs; Je trempe mon lit de mes larmes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 7, 'Mon oeil se consume de chagrin; Il se flétrit à cause de tous ceux qui m\'oppriment.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 8, 'Éloignez-vous de moi, vous tous, ouvriers d\'iniquité; Car l\'Éternel a entendu mes cris et mes pleurs.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 9, 'L\'Éternel a entendu ma supplication; L\'Éternel accueille ma prière.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 10, 'Tous mes ennemis seront saisis de honte et d\'effroi; Ils reculeront, ils seront soudain couverts de honte.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 1, 'Hymne lyrique de David, qu\'il chanta en l\'honneur de l\'Éternel, au sujet de Cus, le Benjamite. O Éternel, mon Dieu, je cherche en toi mon refuge; Sauve-moi de tous ceux qui me poursuivent, et délivre-moi;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 2, 'De peur que l\'ennemi ne me déchire comme un lion Et ne me mette en pièces sans que personne me délivre!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 3, 'Éternel, mon Dieu, si je suis coupable, Si mes mains ont commis l\'iniquité,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 4, 'Si j\'ai fait du mal à celui qui était en paix avec moi, Si même j\'ai dépouillé celui qui m\'opprimait sans motif,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 5, 'Que l\'ennemi me poursuive et m\'atteigne; Qu\'il foule aux pieds ma vie, Et couche ma gloire dans la poussière! Pause');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 6, 'Lève-toi, ô Éternel, dans ta colère! Élève-toi contre les fureurs de ceux qui m\'oppriment; Réveille-toi! Viens à moi! Déjà, tu as préparé le jugement!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 7, 'L\'assemblée des peuples t\'environne; Reprends ta place au-dessus d\'elle dans les lieux très hauts!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 8, 'L\'Éternel juge les peuples! Rends-moi justice, ô Éternel, Selon mon droit, selon mon intégrité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 9, 'Que la malice des méchants prenne fin! Mais affermis le juste. Toi qui sondes les coeurs et les reins, ô Dieu juste!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 10, 'Dieu est mon bouclier; Il sauve ceux qui ont le coeur droit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 11, 'Dieu est un juste juge. Un Dieu fort qui fait sentir sa colère en tout temps.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 12, 'Si le méchant ne se convertit pas. Dieu aiguise son épée; Il bande son arc, et il le tient prêt.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 13, 'Il prépare contre lui des armes mortelles; Il apprête des flèches enflammées.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 14, 'Voici que le méchant est en travail pour enfanter le crime; Il a conçu l\'iniquité, et il enfante le mensonge.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 15, 'Il a creusé un trou profond; Mais il tombera dans la fosse qu\'il a préparée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 16, 'Sa malice retournera sur sa tête; Sa violence retombera sur son front.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 17, 'Je glorifierai l\'Éternel à cause de sa justice; Je chanterai le nom de l\'Éternel, le nom du Très-Haut.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 1, 'Au maître-chantre. — Sur la Guittith. — Psaume de David. Éternel, notre Seigneur, Que ton nom est magnifique sur toute la terre! Ta majesté s\'élève au-dessus des cieux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 2, 'De la bouche des petits enfants, Même de ceux qu\'on allaite, Tu tires ta louange pour confondre tes adversaires, Pour réduire au silence l\'ennemi et le rebelle.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 3, 'Quand je contemple les cieux, oeuvre de tes mains, La lune et les étoiles que tu y as placées,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 4, 'Je dis: Qu\'est-ce que l\'homme, pour que tu te souviennes de lui? Et le fils de l\'homme, pour que tu prennes garde à lui?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 5, 'Tu l\'as créé à peine inférieur à un dieu! Tu l\'as couronné de gloire et de magnificence.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 6, 'Tu lui as donné l\'empire sur les oeuvres de tes mains; Tu as mis toutes choses sous ses pieds:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 7, 'Les brebis comme les boeufs, Et même les bêtes sauvages,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 8, 'Les oiseaux du ciel et les poissons de l\'océan, Tout ce qui parcourt les sentiers des mers.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 9, 'Éternel, notre Seigneur, Que ton nom est magnifique sur toute la terre!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 1, 'Au maître-chantre. — Sur «Meurs pour le fils». — Psaume de David. Je glorifierai l\'Éternel de tout mon coeur; Je raconterai toutes ses merveilles.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 2, 'Je m\'égaierai, je me réjouirai en toi; Je chanterai ton nom, ô Dieu Très-Haut!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 3, 'Car mes ennemis reculent; Ils tombent et périssent devant ta face.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 4, 'Oui, tu as soutenu mon droit, tu as défendu ma cause; Tu t\'es assis sur ton trône en juste juge.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 5, 'Tu as réprimandé les nations, tu as fait périr les méchants; Tu as effacé leur nom pour toujours, à perpétuité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 6, 'Plus d\'ennemis. Des ruines éternelles! Tu as détruit leurs villes, Et leur souvenir a péri avec eux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 7, 'L\'Éternel règne à jamais; Il a dressé son trône pour le jugement.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 8, 'Il jugera le monde avec justice; Il jugera les peuples avec équité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 9, 'L\'Éternel sera le refuge de l\'opprimé, Son refuge au temps de la détresse.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 10, 'Ceux qui connaissent ton nom se confieront en toi; Car tu n\'abandonnes jamais ceux qui te cherchent, ô Éternel.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 11, 'Chantez en l\'honneur de l\'Éternel qui habite en Sion; Annoncez parmi les peuples ses actions glorieuses!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 12, 'Car il se souvient du sang versé, pour en tirer vengeance; Il n\'oublie pas le cri des affligés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 13, 'Aie pitié de moi, ô Éternel! Vois la détresse où m\'ont réduit mes ennemis, toi qui me fais remonter des portes de la mort,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 14, 'Afin que je publie toutes tes louanges Aux portes de la fille de Sion, Et que je me réjouisse du salut que tu m\'as accordé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 15, 'Les nations sont tombées dans la fosse qu\'elles avaient creusées; Leur pied s\'est pris au piège qu\'elles avaient caché.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 16, 'L\'Éternel s\'est fait connaître, il a manifesté sa justice: Le méchant a été enlacé dans son propre filet. — Jeu d\'instruments. Pause');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 17, 'Les méchants s\'en vont au Séjour des morts, Avec toutes les nations qui oublient Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 18, 'Le malheureux ne sera pas toujours oublié, Et l\'espoir des opprimés ne sera pas éternellement trompé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 19, 'Lève-toi, ô Éternel! Que l\'homme ne triomphe pas. Que les nations soient jugées devant ta face!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 20, 'Éternel, répands sur elles la frayeur: Que les peuples sachent qu\'ils ne sont que des hommes! Pause');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 1, 'Pourquoi, ô Éternel, te tiens-tu éloigné. Et te caches-tu au temps de la détresse?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 2, 'L\'orgueil des méchants est un feu qui consume le malheureux Il se laisse prendre aux pièges qu\'ils lui ont tendus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 3, 'Car le méchant se glorifie des convoitises de son âme: Spoliateur avide, il maudit l\'Éternel et l\'outrage.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 4, 'Le méchant dit dans son orgueil: «Dieu ne punira pas! Il n\'y a pas de Dieu!» — Voilà toute sa pensée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 5, 'Ses entreprises réussissent en tout temps. Tes jugements sont au-dessus de sa portée; Il dédaigne tous ses adversaires.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 6, 'Il dit en son coeur: «Je ne serai point ébranlé; Jamais le malheur ne m\'atteindra!»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 7, 'Sa bouche est pleine de malédiction, de fraude et de violence; Sous sa langue se cachent le crime et la méchanceté.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 8, 'Il se tient aux aguets près des villages; Il tue l\'innocent dans les lieux écartés; Ses yeux épient le malheureux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 9, 'Il s\'embusque dans un lieu caché, Comme un lion dans son repaire; Il se tient aux aguets pour surprendre le malheureux: Il le surprend en l\'attirant dans son filet.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 10, 'Il se tapit, il se baisse. Et les malheureux tombent entre ses griffes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 11, 'Il dit en son coeur: «Dieu oublie. Il a caché sa face; il ne regarde jamais!»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 12, 'Lève-toi, ô Éternel! Dieu, lève ta main! N\'oublie pas les malheureux!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 13, 'Pourquoi le méchant t\'outrage-t-il, ô Dieu, Et dit-il en son coeur que tu ne le puniras pas?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 14, 'Et pourtant, tu vois tout! Tu suis du regard ceux qui sont dans la peine et la souffrance, Afin de prendre leur cause en main. A toi s\'abandonne le malheureux; Tu es le secours de l\'orphelin!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 15, 'Brise la puissance du méchant; Poursuis l\'iniquité de l\'injuste. Afin qu\'on n\'en trouve plus la trace!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 16, 'L\'Éternel est Roi pour toujours et à perpétuité; Les nations ont disparu de son empire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 17, 'Éternel, tu entends les souhaits des malheureux; Tu affermiras leur coeur! Tu leur prêteras une oreille attentive,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 18, 'Pour faire droit à l\'orphelin et à l\'opprimé, Afin que l\'homme, tiré de la poussière, cesse de te braver!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 1, 'Au maître-chantre. — De David. J\'ai cherché mon refuge en l\'Éternel. Comment dites-vous à mon âme: «Fuis vers tes montagnes, comme l\'oiseau!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 2, 'Car voici que les méchants bandent l\'arc; Ils ont ajusté leur flèche sur la corde, Pour tirer, dans l\'ombre, sur ceux qui ont le coeur droit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 3, 'Quand les fondements sont renversés, Le juste, que fera-t-il?»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 4, 'L\'Éternel est dans sa demeure sainte: L\'Éternel a son trône dans les cieux. Ses yeux observent; Ses regards sondent les fils des hommes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 5, 'L\'Éternel sonde le juste; Mais il hait le méchant et celui qui se plaît à la violence.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 6, 'Il fera pleuvoir sur les méchants Des charbons ardents, du feu et du soufre. Un vent brûlant, tel est le sort qu\'ils auront en partage!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 7, 'Oui, l\'Éternel est juste; il aime la justice. Les hommes droits contempleront sa face.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 1, 'Au maître-chantre. — Pour voix de basse. — Psaume de David. Sauve-nous, ô Éternel! Car les hommes pieux disparaissent; Il n\'y a plus de fidèles parmi les fils des hommes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 2, 'Ils s\'adressent l\'un à l\'autre des paroles mensongères; Ils parlent avec des lèvres flatteuses, Avec un coeur double.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 3, 'Que l\'Éternel détruise toutes les lèvres flatteuses, La langue qui parle avec orgueil,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 4, 'Et tous ceux qui disent: «Notre langue nous assure la victoire; Nos lèvres sont notre force: Qui serait notre maître?»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 5, 'A cause de l\'oppression des malheureux Et du gémissement des pauvres, Maintenant, dit l\'Éternel, je me lèverai; Je leur donnerai le salut après lequel ils soupirent!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 6, 'Les paroles de l\'Éternel sont des paroles pures; C\'est un argent affiné au creuset, dans l\'argile, Et qui est épuré par sept fois.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 7, 'Toi, ô Éternel, tu garderas les justes; Tu nous défendras contre cette génération, à perpétuité!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 8, 'Les méchants s\'agitent de toutes parts, Quand la bassesse règne parmi les fils des hommes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 1, 'Au maître-chantre. — Psaume de David. Jusques à quand, ô Éternel, m\'oublieras-tu sans cesse? Jusques à quand me cacheras-tu ta face?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 2, 'Jusques à quand aurai-je des soucis dans l\'âme, Et le chagrin dans le coeur, tout le jour? Jusques à quand mon ennemi s\'élèvera-t-il contre moi?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 3, 'Regarde, exauce-moi, ô Éternel, mon Dieu! Répands dans mes yeux ta lumière. De peur que je ne m\'endorme du sommeil de la mort;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 4, 'De peur que mon ennemi ne dise: «Je l\'ai vaincu!» — Et que mes adversaires ne se réjouissent, si j\'étais ébranlé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 5, 'Pour moi, je me confie en ta bonté; Ton salut remplira mon coeur de joie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 6, 'Je chanterai à la gloire de l\'Éternel; car il m\'a fait du bien!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 1, 'Au maître-chantre. — De David. L\'insensé a dit en son coeur: «Il n\'y a pas de Dieu!» Les hommes se sont corrompus: leur conduite est abominable; Il n\'y a personne qui fasse le bien.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 2, 'Des cieux l\'Éternel abaisse son regard sur les fils des hommes, Pour voir s\'il y a quelque homme intelligent, Et qui cherche Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 3, 'Ils se sont tous détournés, ils se sont pervertis tous ensemble; Il n\'y en a pas qui fasse le bien, Non, pas même un seul!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 4, 'Sont-ils donc sans intelligence, tous ces ouvriers d\'iniquité? Ils dévorent mon peuple comme on mange du pain; Ils n\'invoquent point l\'Éternel.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 5, 'Ils seront saisis d\'une terreur soudaine; Car Dieu est au milieu de la race juste.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 6, 'Vous voudriez faire échouer les desseins du malheureux; Mais l\'Éternel est son refuge!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 7, 'Oh! Qui apportera de Sion la délivrance d\'Israël? Quand l\'Éternel ramènera les captifs de son peuple, Jacob sera dans l\'allégresse, Israël sera dans la joie!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 1, 'Psaume de David. Éternel, qui séjournera dans ton tabernacle? Qui habitera sur ta montagne sainte?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 2, 'C\'est celui qui marche dans l\'intégrité, qui pratique la justice, Qui dit la vérité telle qu\'elle est dans son coeur;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 3, 'Celui dont la langue ne sème point la calomnie, Qui ne fait pas de mal à son semblable. Et qui ne jette pas l\'opprobre sur son prochain.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 4, 'Lui-même se sent indigne et méprisable; Mais il honore ceux qui craignent l\'Éternel. S\'il a juré, fût-ce à son préjudice, Il ne change rien à son serment.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 5, 'Il ne prête pas son argent à usure; Il n\'accepte pas de présent contre l\'innocent. Celui qui agit ainsi ne sera jamais ébranlé!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 1, 'Poème de David. Garde-moi, ô Dieu; car je cherche en toi mon refuge.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 2, 'J\'ai dit à l\'Éternel: «Tu es le Seigneur; Toi seul, tu es mon bien suprême!»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 3, 'Et j\'ai dit aux saints qui sont dans le pays: «Vous êtes les nobles âmes en qui je prends tout mon plaisir.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 4, 'Les douleurs se multiplient Pour ceux qui courent après d\'autres dieux. Je n\'offrirai pas leurs libations de sang, Et les noms qu\'ils invoquent ne seront pas sur mes lèvres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 5, 'L\'Éternel est ma part et mon breuvage: C\'est lui qui me garde mon lot.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 6, 'Ma portion m\'est échue dans des lieux agréables; Oui, j\'ai un bel héritage!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 7, 'Je bénirai l\'Éternel, qui est mon conseiller: Mon coeur m\'y invite, même pendant la nuit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 8, 'J\'ai l\'Éternel constamment présent devant moi: Puisqu\'il est à ma droite, je ne serai point ébranlé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 9, 'C\'est pourquoi mon coeur se réjouit, Et mon âme tressaille de joie; Mon corps même reposera en toute sécurité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 10, 'Car tu n\'abandonneras pas mon âme dans le Séjour des morts. Tu ne permettras pas que celui qui t\'aime voie la corruption.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 11, 'Tu me feras connaître le chemin de la vie. L\'âme est rassasiée de joie en ta présence; Il y a des délices à ta droite, pour toujours!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 1, 'Prière de David. Éternel, écoute ma juste cause! Sois attentif à mon cri! Prête l\'oreille à ma prière: elle sort de lèvres sans fraude!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 2, 'Que ta présence fasse éclater mon droit; Que tes yeux reconnaissent mon intégrité!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 3, 'Tu as sondé mon coeur, tu m\'as visité pendant la nuit; Tu m\'as éprouvé, tu ne trouves rien; Ma parole ne va pas au-delà de ma pensée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 4, 'J\'ai vu les actions des hommes; Mais, pour obéir à la parole de ta bouche. Je me suis éloigné des voies de l\'homme violent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 5, 'Affermis mes pas dans tes sentiers, Afin que mes pieds ne chancellent point.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 6, 'Je t\'invoque; car tu m\'exauces, ô Dieu! Incline ton oreille vers moi; écoute ma prière!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 7, 'Fais-nous admirer tes bontés, Toi qui sauves ceux qui cherchent leur refuge Auprès de toi, contre leurs adversaires!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 8, 'Garde-moi comme la prunelle de l\'oeil! Cache-moi à l\'ombre de tes ailes,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 9, 'Loin de ces méchants qui m\'oppriment, De mes ennemis acharnés qui m\'enveloppent!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 10, 'Ils ferment leur coeur à la pitié; Leur bouche tient des discours hautains.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 11, 'A chaque pas, ils nous circonviennent; Ils nous épient pour nous terrasser.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 12, 'Ils ressemblent au lion avide de déchirer. Au lionceau qui se tient aux aguets dans son repaire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 13, 'Lève-toi, ô Éternel! Marche à la rencontre du méchant; renverse-le! Que ton épée me délivre de lui!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 14, 'Que ta main, ô Éternel, me délivre de ces hommes, Des hommes de ce siècle, Dont tout le bonheur est dans cette vie, Et dont le ventre est gorgé de tes biens: Leurs enfants ont tout à satiété, Et ils laissent encore leur superflu à leurs petits-enfants.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 15, 'Mais moi, grâce à ma droiture, je pourrai voir ta face. A mon réveil, je me rassasierai de ta vue.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 1, 'Au maître-chantre. — De David, serviteur de l\'Éternel, qui prononça, à la louange de l\'Éternel, les paroles de ce cantique, lorsque l\'Éternel l\'eut délivré de la main de tous ses ennemis et de la main de Saül. Il dit: Je t\'aime, ô Éternel, toi qui es ma force!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 2, 'L\'Éternel est mon rocher, ma forteresse et mon libérateur! Mon Dieu est le roc où je trouve un refuge, Mon bouclier, mon puissant sauveur, mon rempart!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 3, 'Je m\'écrie: «Loué soit l\'Éternel!» — Et je suis délivré de mes ennemis.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 4, 'Les liens de la mort m\'avaient enveloppé; Les torrents de la destruction m\'avaient épouvanté.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 5, 'Oui, les liens du Sépulcre m\'avaient entouré; Les filets de la mort m\'avaient surpris.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 6, 'Dans ma détresse, j\'invoquai l\'Éternel, Je criai vers mon Dieu. De son palais, il entendit ma voix; Les cris que je poussais vers lui parvinrent à ses oreilles.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 7, 'Alors la terre fut ébranlée, et elle trembla; Les fondements des montagnes chancelèrent. Ils s\'ébranlèrent, parce que l\'Éternel était courroucé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 8, 'La fumée montait de ses narines, Et de sa bouche sortait un feu dévorant: en faisait jaillir des charbons embrasés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 9, 'Il inclina les cieux et il descendit, Ayant sous ses pieds une sombre nuée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 10, 'Il était monté sur un chérubin, et il volait; Il était porté sur les ailes du vent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 11, 'Il fit des ténèbres sa retraite; déploya autour de lui, comme une tente, Des masses liquides, de sombres nuages.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 12, 'Du sein de la splendeur qui le précédait, S\'échappaient des nuées, de la grêle et des charbons de feu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 13, 'L\'Éternel tonna dans les cieux; Le Très-Haut fit retentir sa voix, Au milieu de la grêle et des charbons de feu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 14, 'Il lança ses flèches, et il dispersa mes ennemis; Il lança des éclairs nombreux, et ils furent mis en déroute.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 15, 'Alors le lit de la mer apparut, Et les fondements du monde furent mis à découvert, A ta voix menaçante, ô Éternel, Au souffle du vent de ta colère.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 16, 'Dieu étendit sa main d\'en haut, et il me saisit; Il me retira des grandes eaux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 17, 'Il me délivra de mon puissant ennemi, De mes adversaires qui étaient plus forts que moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 18, 'Ils m\'avaient surpris au jour de ma détresse; Mais l\'Éternel a été mon appui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 19, 'Il m\'a mis au large; Il m\'a délivré à cause de son amour pour moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 20, 'L\'Éternel m\'a traité selon ma justice; Il a récompensé la pureté de mes mains.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 21, 'Car j\'ai suivi avec soin les voies de l\'Éternel, Et je n\'ai pas été infidèle à mon Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 22, 'Tous ses commandements sont présents devant moi, Et je ne m\'écarte point de ses préceptes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 23, 'J\'ai été sans reproche envers lui, Et je me suis mis en garde contre mon penchant au mal.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 24, 'Oui, l\'Éternel m\'a traité selon ma justice, Selon la pureté de mes mains, que ses yeux ont reconnue.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 25, 'Avec celui qui est, fidèle, tu es fidèle; Avec l\'homme intègre, tu es intègre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 26, 'Avec celui qui est pur, tu te montres pur; Mais avec le pervers, tu te joues de sa perversité!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 27, 'Car c\'est toi qui sauves le peuple des humbles, Et, qui abaisses les regards des superbes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 28, 'C\'est toi qui allumes mon flambeau; C\'est l\'Éternel, mon Dieu, qui fait resplendir mes ténèbres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 29, 'Avec toi j\'attaque une troupe armée; Avec mon Dieu je franchis le rempart.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 30, 'Les voies du Dieu fort sont parfaites. La parole de l\'Éternel est éprouvée: Il est le bouclier de tous ceux qui cherchent leur refuge en lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 31, 'Qui donc est Dieu, sinon l\'Éternel? Qui est un rocher, sinon notre Dieu?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 32, 'C\'est ce Dieu qui me ceint de force, Et qui aplanit mon chemin.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 33, 'Il rend mes pieds agiles comme ceux des biches, Et il m\'affermit sur les sommets.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 34, 'Il exerce mes mains au combat, Et mes bras bandent un arc, d\'airain.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 35, 'Tu me donnes pour bouclier ton puissant secours. Ta main droite me soutient, Et ta bonté me rend fort.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 36, 'Tu élargis le chemin sous mes pas, Et mes pieds ne chancellent point.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 37, 'Je poursuis mes ennemis, je les atteins, Et je ne reviens qu\'après les avoir exterminés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 38, 'Je les écrase, et ils ne peuvent se relever: Ils tombent sous mes pieds.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 39, 'Tu m\'as ceint de force pour le combat; Tu fais plier sous moi mes adversaires.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 40, 'Tu fais fuir devant moi mes ennemis; J\'extermine ceux qui me haïssent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 41, 'Ils crient, mais personne ne vient les délivrer! Ils crient vers l\'Eternel, mais il ne leur répond pas.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 42, 'Je les broie comme la poussière livrée au vent; Je les balaie comme la boue des rues.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 43, 'Tu me fais triompher des attaques de mon peuple; Tu me places à la tête des nations. Des peuples inconnus deviennent mes sujets;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 44, 'Dès qu\'ils entendent parler de moi, ils se soumettent. Les fils de l\'étranger me rendent hommage.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 45, 'Les fils de l\'étranger sont abattus, Et ils sortent tremblants de leurs retraites.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 46, 'L\'Éternel est vivant! Béni soit mon rocher! Que Dieu, mon libérateur, soit exalté!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 47, 'Ce Dieu m\'assure la vengeance; Il m\'assujettit les peuples.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 48, 'Tu me délivres de mes ennemis; Tu m\'élèves au-dessus de mes adversaires; Tu me sauves de l\'homme violent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 49, 'C\'est pourquoi je te louerai, ô Éternel, parmi les nations, Et je psalmodierai à la gloire de ton nom.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 50, 'L\'Éternel accorde au roi, son élu, de grandes victoires; Il exerce sa miséricorde en faveur de son oint, De David et de sa postérité, à jamais.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 1, 'Au maître-chantre. — Psaume de David. Les cieux racontent la gloire de Dieu, Et le firmament proclame l\'oeuvre de ses mains.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 2, 'Le jour en parle au jour, Et la nuit en donne connaissance à la nuit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 3, 'Ce n\'est pas un langage, ce ne sont pas des paroles: On n\'entend pas leur voix.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 4, 'Cependant, leurs accords parcourent la terre entière, Et leurs accents vont jusqu\'aux extrémités du monde. Là, Dieu a dressé un pavillon pour le soleil,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 5, 'Qui, semblable à un époux sortant de sa chambre nuptiale, Se réjouit, comme un héros, de parcourir sa carrière.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 6, 'Il part de l\'une des extrémités du ciel, Et, sa course s\'achève à l\'autre extrémité: Rien ne se dérobe à sa chaleur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 7, 'La loi de l\'Éternel est parfaite: elle restaure l\'âme. Les enseignements de l\'Éternel sont vrais: Ils donnent de la sagesse aux simples.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 8, 'Les préceptes de l\'Éternel sont droits: Ils réjouissent le coeur. Les commandements de l\'Éternel sont une lumière: Ils éclairent les yeux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 9, 'La crainte de l\'Éternel purifie: Elle subsiste à perpétuité. Les jugements de l\'Éternel ne sont que vérité: Ils sont tous également justes;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 10, 'Ils sont plus désirables que l\'or, même que beaucoup d\'or fin, Plus doux que le miel, que le suc même des rayons de miel.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 11, 'Aussi ton serviteur est-il éclairé par eux; Grande est la récompense de ceux qui les observent!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 12, 'Qui peut connaître ses erreurs? Pardonne-moi les fautes que j\'ignore!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 13, 'Préserve aussi ton serviteur des péchés volontaires: Que je ne sois pas leur esclave! Alors je serai sans reproche et pur de grands péchés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 14, 'Que les paroles de ma bouche Et la méditation de mon coeur te soient agréables, O Éternel, mon rocher, mon rédempteur!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 1, 'Au maître-chantre. — Psaume de David. Que l\'Éternel te réponde au jour de la détresse;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 2, 'Que le nom du Dieu de Jacob soit pour toi une forteresse! Qu\'il t\'envoie son secours du saint lieu, Et que de Sion il te soutienne!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 3, 'Qu\'il se rappelle toutes tes offrandes, Et, qu\'il ait pour agréables tes holocaustes!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 4, 'Qu\'il t\'accorde le désir de ton coeur, Et qu\'il accomplisse tous tes desseins!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 5, 'Nous nous réjouirons de ta victoire, Et nous élèverons l\'étendard au nom de notre Dieu. L\'Éternel exaucera toutes tes prières.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 6, 'Déjà je sais que l\'Éternel a délivré son oint. Il lui répondra du haut des cieux, de sa demeure sainte, Par le secours puissant de sa main droite.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 7, 'Les uns se glorifient de leurs chars, d\'autres de leurs chevaux; Mais nous, c\'est du nom de l\'Éternel, notre Dieu, Que nous nous glorifions!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 8, 'Ceux-là ont plié et sont tombés; Mais nous restons debout et nous tenons ferme.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 9, 'O Éternel, accorde-nous la victoire! Que le Roi nous réponde au jour où nous l\'invoquons! Pause');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 1, 'Au maître-chantre. — Psaume de David. O Éternel, le roi se réjouit de ta force. Quelle allégresse lui donne ta délivrance!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 2, 'Tu as répondu au désir de son coeur, Et tu ne lui as pas refusé ce que ses lèvres avaient demandé. Pause');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 3, 'Car tu l\'as prévenu par des bienfaits excellents; Tu as mis sur sa tête une couronne d\'or fin.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 4, 'Il te demandait la vie: tu la lui as accordée, Une vie dont les jours dureront à perpétuité, à jamais.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 5, 'Sa gloire est grande, grâce à ton secours victorieux; Tu le revêts de splendeur et de majesté.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 6, 'Tu fais de lui l\'objet de tes bénédictions pour toujours; Tu le combles de joie devant ta face.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 7, 'Car le roi met sa confiance en l\'Éternel, Et, par la bonté du Très-Haut, il ne chancellera point.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 8, 'Ta main atteindra tous tes ennemis; Ta main droite atteindra ceux qui te haïssent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 9, 'Tu les consumeras comme dans une fournaise ardente, Aussitôt que tu te montreras. L\'Éternel les engloutira dans sa colère, Et le feu les dévorera.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 10, 'Tu feras disparaître de la terre leur postérité, Et leur race du milieu des fils des hommes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 11, 'Ils ont projeté du mal contre toi; Ils ont formé de méchants desseins: ils ne pourront les exécuter;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 12, 'Car tu les mettras en fuite. Tu dirigeras ton arc contre eux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 13, 'Lève-toi, ô Éternel, dans ta force! Nous chanterons et nous célébrerons tes exploits.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 1, 'Au maître-chantre. — Sur «Biche de l\'aurore». — Psaume de David. Mon Dieu, mon Dieu, pourquoi m\'as-tu abandonné Pourquoi restes-tu loin, sans me secourir, Sans écouter mon gémissement?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 2, 'Mon Dieu, je crie le jour, — et tu ne réponds pas; La nuit — et je n\'ai point de repos.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 3, 'Cependant, tu es le Saint, Dont le trône est environné des louanges d\'Israël.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 4, 'C\'est en toi que se sont confiés nos pères; Ils ont eu confiance, et tu les as délivrés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 5, 'Ils ont crié vers toi, et ils ont été sauvés. Ils se sont confiés en toi, et ils n\'ont pas été déçus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 6, 'Mais moi, je suis un ver de terre et non un homme, L\'opprobre des hommes et le méprisé du peuple.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 7, 'Tous ceux qui me voient se moquent de moi; Ils ricanent, ils hochent la tête en disant:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 8, '«Qu\'il se repose sur l\'Éternel, et l\'Éternel le délivrera; Il le sauvera, puisqu\'il a mis en lui son affection!»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 9, 'Oui, c\'est toi qui m\'as tiré du sein de ma mère, Et qui m\'as fait reposer en paix dans ses bras.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 10, 'J\'ai été remis entre tes mains dès ma naissance; Dès le sein de ma mère, tu as été mon Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 11, 'Ne t\'éloigne pas de moi, quand la détresse est proche, Quand il n\'y a personne pour me secourir!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 12, 'De nombreux taureaux sont autour de moi; Les robustes taureaux de Basan m\'enveloppent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 13, 'Mes ennemis ouvrent leur bouche contre moi, Comme un lion qui déchire et rugit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 14, 'Je suis comme l\'eau qui s\'écoule, Et tous mes os se sont disjoints; Mon coeur est comme la cire: Il se fond dans mes entrailles.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 15, 'Ma vigueur est desséchée comme la brique; Ma langue s\'attache à mon palais, Et tu m\'as couché dans la poussière de la mort.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 16, 'Car des chiens m\'ont environné; Une bande de malfaiteurs m\'a entouré; Ils ont percé mes mains et mes pieds.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 17, 'Je pourrais compter tous mes os! Mes ennemis me regardent et m\'observent:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 18, 'Ils partagent entre eux mes vêtements, Et ils tirent ma robe au sort.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 19, 'Toi donc, ô Éternel, ne t\'éloigne pas! Toi qui es ma force, accours à mon aide!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 20, 'Délivre mon âme de l\'épée, Ma vie, de la dent des chiens!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 21, 'Sauve-moi de la gueule du lion Et des cornes des buffles! Oui, tu m\'as exaucé!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 22, 'J\'annoncerai ton nom à mes frères; Je te louerai au milieu de l\'assemblée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 23, 'Vous qui craignez l\'Éternel, louez-le; Vous tous, race de Jacob, glorifiez-le; Craignez-le, vous tous, race d\'Israël!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 24, 'Car il n\'a point méprisé, il n\'a pas dédaigné la misère de l\'affligé. Il n\'a pas détourné de lui son visage; Mais il l\'a exaucé quand il criait vers lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 25, 'Tu seras loué par moi dans la grande assemblée; J\'accomplirai mes voeux en présence de ceux qui te craignent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 26, 'Les malheureux mangeront et seront rassasiés; Ceux qui recherchent l\'Éternel le loueront. Que leur coeur revienne à la vie pour toujours!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 27, 'Tous les peuples de la terre se souviendront de l\'Éternel, Et ils reviendront à lui; Toutes les familles des nations se prosterneront devant sa face;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 28, 'Car le règne appartient à l\'Éternel, Et il domine sur les nations.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 29, 'Oui, tous les puissants de la terre se prosterneront devant lui. Tous ceux qui descendent dans la poussière, Ceux qui sont près d\'expirer, s\'inclineront devant lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 30, 'La postérité le servira; On parlera du Seigneur aux générations futures:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 31, 'Elles viendront et proclameront sa justice. Au peuple qui naîtra, elles annonceront ce qu\'il a fait!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 1, 'Psaume de David. L\'Éternel est mon berger; je n\'aurai point de disette.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 2, 'Il me fait reposer dans de verts pâturages; Il me mène le long des eaux tranquilles.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 3, 'Il restaure mon âme; Il me conduit dans des sentiers unis, Pour l\'amour de son nom.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 4, 'Même quand je marcherais dans la vallée de l\'ombre de la mort, Je ne craindrais aucun mal! Car tu es avec moi: C\'est ton bâton et ta houlette qui me consolent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 5, 'Tu dresses la table devant moi, A la vue de ceux qui me persécutent. Tu oins ma tête d\'huile; ma coupe déborde.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 6, 'Oui, le bonheur et la grâce m\'accompagneront Tous les jours de ma vie, Et je passerai de longs jours dans la maison de l\'Éternel.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 1, 'Psaume de David. La terre est à l\'Éternel, et tout ce qu\'elle contient. Ainsi que le monde et ceux qui l\'habitent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 2, 'C\'est Lui qui l\'a établie sur les rives des mers Et qui en a jeté les fondements sur les bords des fleuves.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 3, 'Qui pourra monter à la montagne de l\'Éternel, Et qui pourra subsister dans son saint lieu?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 4, 'C\'est l\'homme qui a les mains nettes et le coeur pur, Dont l\'âme ne se porte pas vers le mensonge. Et qui ne jure pas pour tromper.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 5, 'Il obtiendra de l\'Éternel la bénédiction. Et, du Dieu de son salut, la miséricorde.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 6, 'Telle est la race de ceux qui te cherchent. De ceux qui recherchent ta face; telle est la race de Jacob! Pause');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 7, 'Portes, élevez vos voûtes! Ouvrez-vous toutes grandes, portes éternelles, Et le Roi de gloire entrera.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 8, 'Qui est ce Roi de gloire? C\'est l\'Éternel, le fort, le puissant, L\'Éternel, puissant dans les batailles.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 9, 'Portes, élevez vos voûtes! Élevez-les, portes éternelles. Et le Roi de gloire entrera.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 10, 'Qui est-il, ce Roi de gloire? C\'est l\'Éternel des armées; C\'est lui qui est le Roi de gloire! Pause');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 1, 'De David. O Éternel, j\'élève mon âme à toi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 2, 'Mon Dieu, je mets en toi ma confiance: Que je ne sois pas couvert de confusion! Que mes ennemis ne se réjouissent pas à mon sujet!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 3, 'Non, aucun de ceux qui s\'attendent à toi Ne sera couvert de honte; Mais ils rougiront tous de honte, Ceux qui se révoltent injustement contre toi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 4, 'Éternel, fais-moi connaître tes voies; Enseigne-moi tes sentiers!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 5, 'Fais-moi marcher dans la voie de ta vérité, et instruis-moi; Car tu es le Dieu de mon salut: Je m\'attends à toi chaque jour.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 6, 'Éternel, souviens-toi de tes compassions et de tes bontés; Car elles sont de tout temps.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 7, 'Ne te souviens pas des fautes de ma jeunesse, ni de mes péchés; Souviens-toi de moi, dans ta bonté, A cause de ta bienveillance, ô Éternel!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 8, 'L\'Éternel est bon et droit; C\'est pourquoi il montrera le chemin aux pécheurs.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 9, 'Il fera marcher les humbles dans la justice; Il enseignera sa voie aux humbles.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 10, 'Tous les sentiers de l\'Éternel ne sont que bonté et fidélité, Pour ceux qui gardent son alliance et ses commandements.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 11, 'Pour l\'amour de ton nom, ô Éternel, Tu pardonneras mon iniquité, bien qu\'elle soît grande!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 12, 'Quel est l\'homme qui craint l\'Éternel? L\'Éternel lui enseignera le chemin qu\'il doit choisir.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 13, 'Son âme reposera au sein du bonheur. Et sa postérité possédera la terre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 14, 'Le secret de l\'Éternel est pour ceux qui le craignent. Et il leur fait connaître son alliance.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 15, 'Mes yeux regardent sans cesse vers l\'Éternel; Car il dégagera mes pieds du filet.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 16, 'Tourne-toi vers moi, prends pitié de moi; Car je suis seul et misérable!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 17, 'La détresse de mon coeur augmente: Délivre-moi de mes angoisses!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 18, 'Vois ma misère et mon tourment. Et pardonne tous mes péchés!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 19, 'Vois combien mes ennemis sont nombreux Et de quelle violente haine ils sont animés contre moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 20, 'Garde mon âme et délivre-moi! Que je ne sois pas couvert de honte; Car j\'ai cherché un refuge auprès de toi!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 21, 'Que l\'intégrité et la droiture me protègent; Car j\'ai mis mon espoir en toi!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 22, 'Dieu, délivre Israël De toutes ses détresses!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 1, 'De David. Fais-moi justice, ô Éternel! Car je marche dans l\'intégrité. Je mets ma confiance en l\'Éternel: je ne serai pas ébranlé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 2, 'Sonde-moi, ô Éternel, éprouve-moi; Fais passer au creuset mes reins et mon coeur!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 3, 'Car ta bonté est devant mes yeux. Et je prends pour modèle ta fidélité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 4, 'Je ne m\'assieds pas avec les hommes de mensonge; Je ne vais point avec les gens dissimulés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 5, 'Je hais l\'assemblée des pervers, Et je ne m\'assieds pas avec les méchants.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 6, 'Je lave mes mains, parce que je suis pur, Et je me tiens auprès de ton autel, ô Éternel,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 7, 'Pour éclater en actions de grâces, Et pour raconter toutes tes merveilles.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 8, 'Éternel, j\'aime à séjourner dans ta maison, Dans le lieu où réside ta gloire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 9, 'N\'entraîne pas mon âme dans la ruine des pécheurs, Ni ma vie dans celle des hommes sanguinaires,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 10, 'Qui ont les mains souillées de crimes. Et dont la main droite est pleine de présents.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 11, 'Mais moi, je marche dans l\'intégrité; Délivre-moi, aie pitié de moi!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 12, 'Mon pied reste dans le droit chemin. Je bénirai l\'Éternel dans les assemblées!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 1, 'De David. L\'Éternel est ma lumière et ma délivrance; De qui aurais-je peur? L\'Éternel est le rempart de ma vie; De qui aurais-je de la crainte?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 2, 'Quand les méchants sont venus contre moi Pour dévorer ma chair, Ce sont eux, mes adversaires et mes ennemis. Qui ont bronché et qui sont tombés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 3, 'Quand même une armée camperait contre moi, Mon coeur n\'aurait aucune crainte. Quand la guerre s\'élèverait contre moi, Même alors j\'aurais confiance.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 4, 'J\'ai demandé une chose à l\'Éternel, et je la rechercherai: C\'est d\'habiter dans la maison de l\'Éternel Tous les jours de ma vie, Pour contempler la beauté de l\'Éternel Et pour visiter son sanctuaire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 5, 'Car il m\'abritera dans sa tente au jour du malheur; Il me cachera dans le lieu le plus secret de son tabernacle. Il m\'élèvera sur un rocher.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 6, 'Déjà ma tête s\'élève au-dessus des ennemis qui m\'entourent. J\'offrirai dans son tabernacle des sacrifices, avec des cris de joie; Je chanterai et je psalmodierai à la gloire de l\'Éternel.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 7, 'O Éternel, écoute ma voix, je t\'invoque; Aie pitié de moi et daigne m\'exaucer!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 8, 'Mon coeur dit de ta part: «Cherchez ma face!» Je cherche ta face, ô Éternel!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 9, 'Ne me cache pas ta face! Ne rejette pas ton serviteur, dans ta colère! Tu as été mon aide; ne me délaisse pas, ne m\'abandonne point, Dieu de mon salut!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 10, 'Quand mon père et ma mère m\'auraient abandonné, L\'Éternel me recueillera.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 11, 'O Éternel, enseigne-moi ta voie, Et conduis-moi dans le droit chemin, A cause de mes ennemis.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 12, 'Ne me livre pas à la merci de mes adversaires: Car de faux témoins, des gens qui ne respirent que violence, Se sont élevés contre moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 13, 'Ah! si je n\'avais l\'assurance de voir la bonté de l\'Éternel Sur la terre des vivants!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 14, 'Mets ton espoir en l\'Éternel! Demeure ferme; que ton coeur se fortifie. Oui, mets ton espoir en l\'Éternel!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 1, 'De David. Je crie vers toi, ô Éternel! Mon rocher, ne sois pas sourd à ma prière, De peur que, si tu t\'éloignes sans me répondre, Je ne devienne semblable à ceux qui descendent dans la tombe.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 2, 'Écoute ma voix suppliante, quand je crie vers toi, Quand j\'élève mes mains vers ton sanctuaire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 3, 'Ne m\'entraîne pas dans la ruine des méchants Et des ouvriers d\'iniquité, Qui parlent de paix avec leur prochain. Quand la malice est dans leur coeur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 4, 'Traite-les selon leurs oeuvres, Selon la méchanceté de leurs actions; Traite-les selon l\'ouvrage de leurs mains. Rends-leur ce qu\'ils ont mérité!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 5, 'Puisqu\'ils ne prennent pas garde aux oeuvres de l\'Éternel, Ni à l\'ouvrage de ses mains, Il les détruira, et il ne les relèvera point!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 6, 'Béni soit l\'Éternel! Car il a entendu ma voix suppliante.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 7, 'L\'Éternel est ma force et mon bouclier. Mon coeur s\'est confié en lui, et j\'ai été secouru; Aussi mon coeur est-il plein d\'allégresse, Et je loue l\'Éternel dans mes cantiques.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 8, 'L\'Éternel est la force des siens; Il est un rempart de salut pour son oint.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 9, 'Sauve ton peuple, et bénis ton héritage! Sois leur berger, et soutiens-les éternellement.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 1, 'Psaume de David. Rendez à l\'Éternel, ô vous, fils de Dieu. Rendez à l\'Éternel gloire et louange!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 2, 'Rendez à l\'Éternel la gloire due à son nom; Prosternez-vous devant l\'Éternel, parés de vos ornements sacrés!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 3, 'La voix de l\'Éternel retentit sur les eaux; Le Dieu de gloire, l\'Éternel, fait gronder le tonnerre Sur les grandes eaux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 4, 'La voix de l\'Éternel est puissante; La voix de l\'Éternel est pleine de majesté;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 5, 'La voix de l\'Éternel brise les cèdres; L\'Éternel brise les cèdres du Liban.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 6, 'Il les fait bondir comme de jeunes taureaux. Il ébranle le Liban et le Sirion comme les petits du buffle.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 7, 'La voix de l\'Éternel fait jaillir des flammes de feu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 8, 'La voix de l\'Éternel fait trembler le désert. L\'Éternel fait trembler le désert de Kadès.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 9, 'La voix de l\'Éternel fait faonner les biches; Elle dépouille les forêts. Dans son palais tout s\'écrie: «Gloire!»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 10, 'L\'Éternel présidait au déluge, Et sur son trône l\'Éternel régnera éternellement.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 11, 'L\'Éternel donnera la force à son peuple; L\'Éternel bénira son peuple en lui accordant la paix.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 1, 'Psaume. — Cantique pour la dédicace de la Maison de Dieu. — De David. Je t\'exalte, ô Éternel; car tu m\'as relevé! Tu n\'as pas permis à mes ennemis de se réjouir à mon sujet.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 2, 'Éternel, ô mon Dieu, J\'ai crié vers toi, et tu m\'as guéri.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 3, 'Éternel, tu as fait remonter mon âme du Séjour des morts; Tu m\'as fait revivre, pour que je ne descende pas dans la tombe.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 4, 'Chantez à la gloire de l\'Éternel, vous, ses fidèles, Et célébrez la mémoire de sa sainteté!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 5, 'Car sa colère dure un instant, Mais sa faveur, toute une vie: Le soir amène les pleurs, Et le matin, des chants joyeux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 6, 'Pour moi, je disais dans ma sécurité: «Je ne serai jamais ébranlé!»?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 7, 'Éternel, grâce à ta bienveillance J\'avais pu m\'établir dans une forte citadelle; Mais tu cachas ta face, et je fus éperdu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 8, 'Alors, ô Éternel, je criai vers toi. J\'adressai ma supplication à l\'Éternel:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 9, '«Que gagneras-tu à verser mon sang, A me voir descendre dans la tombe? La poussière te célébrera-t-elle? Proclamera-t-elle ta fidélité?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 10, 'Écoute, ô Éternel, aie pitié de moi! Éternel, viens à mon aide!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 11, 'Tu as changé mon deuil en allégresse; Tu as délié le sac dont j\'étais couvert; tu m\'as ceint de joie,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 12, 'Afin que mon âme chante tes louanges et ne se taise point. Éternel, ô mon Dieu, je te célébrerai à perpétuité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 1, 'Au maître-chantre. — Psaume de David. Éternel, je cherche mon refuge en toi; Que mon espoir ne soit jamais déçu! Délivre-moi, dans ta justice!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 2, 'Incline ton oreille vers moi; hâte-toi de me délivrer. Sois le rocher où je trouve un asile, La forteresse où je puisse me réfugier!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 3, 'Car tu es mon rocher et ma forteresse. A cause de ton nom, tu me conduiras et me guideras.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 4, 'Tu me tireras du piège qu\'on m\'a tendu; Car tu es mon asile.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 5, 'Je remets mon esprit entre tes mains. Tu m\'as racheté, ô Éternel, Dieu de vérité!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 6, 'Je hais les adorateurs de vaines idoles; Pour moi, je me confie en l\'Éternel.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 7, 'Je serai plein de joie et d\'allégresse, à cause de ta bonté; Car tu as vu ma misère, tu as connu les détresses de mon âme.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 8, 'Tu ne m\'as pas livré aux mains de l\'ennemi; Tu as ouvert largement la voie devant mes pas.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 9, 'Éternel, aie pitié de moi, car je suis dans la détresse! Ma vue est usée par le chagrin. Ainsi que mon âme et mes entrailles.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 10, 'Ma vie se consume dans la douleur. Et mes années dans les soupirs. Ma vigueur s\'épuise, à cause de mon iniquité, Et mon corps dépérit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 11, 'Mes ennemis ont fait de moi un objet d\'opprobre, De grand opprobre pour mes voisins, Un objet d\'horreur pour mes amis. Ceux qui me voient dans la rue s\'enfuient loin de moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 12, 'Je suis oublié comme un mort, banni des coeurs; Je suis comme un vase brisé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 13, 'Car j\'entends les méchants propos de beaucoup de gens. La frayeur m\'environne, Quand ils se concertent ensemble contre moi, Et forment des complots pour m\'ôter la vie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 14, 'Mais moi, ô Éternel, je me confie en toi. J\'ai dit:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 15, 'Mes destinées sont dans ta main; Délivre-moi du pouvoir de mes ennemis et de mes persécuteurs.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 16, 'Fais resplendir ta face sur ton serviteur; Sauve-moi, dans ta bonté.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 17, 'Éternel, que je n\'aie pas à rougir de t\'avoir invoqué. Que les méchants soient couverts de honte; Qu\'ils soient réduits au silence du Séjour des Morts!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 18, 'Oui, qu\'elles soient muettes, les lèvres menteuses Qui profèrent contre le juste des paroles impudentes, Pleines d\'orgueil et de mépris!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 19, 'Combien est grande la bonté Que tu tiens en réserve pour ceux qui te craignent, Que tu fais éprouver, en présence des fils des hommes, A ceux qui cherchent en toi leur refuge!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 20, 'Tu les caches à l\'abri de ta face, Loin des complots des hommes; Tu les abrites dans ta tente contre les langues qui les attaquent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 21, 'Béni soit l\'Éternel; Car sa bonté s\'est montrée admirable envers moi: Je suis comme dans une ville forte.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 22, 'Je disais dans mon trouble: «Je suis rejeté loin de ta vue!» Mais tu as exaucé ma voix suppliante. Quand j\'ai crié vers toi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 23, 'Aimez l\'Éternel, vous tous, ses bien-aimés! L\'Éternel veille sur les fidèles, Mais il rend avec usure à l\'orgueilleux ce qu\'il a mérité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 24, 'Demeurez fermes; que votre coeur se fortifie. Vous tous qui espérez en l\'Éternel!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 1, 'De David. — Hymne. Heureux celui dont la transgression est remise, Et dont les péchés sont pardonnés!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 2, 'Heureux l\'homme à qui l\'Éternel n\'impute pas l\'iniquité. Et dans l\'esprit duquel il n\'y a point de fraude!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 3, 'Tant que je gardais le silence, mon corps dépérissait. Je gémissais tout le jour;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 4, 'Car, jour et nuit, ta main s\'appesantissait sur moi. Pause Ma vigueur avait fait place à la sécheresse de l\'été.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 5, 'Je t\'ai fait connaître mon péché; Je ne t\'ai point caché mon iniquité. J\'ai dit: «Je confesserai mes transgressions à l\'Éternel!» Alors tu as ôté la peine de mon péché. Pause');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 6, 'C\'est pourquoi tout fidèle t\'invoquera Au temps où l\'on te trouve; Et quand même les grandes eaux viendraient à déborder, Lui seul n\'en serait pas atteint.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 7, 'Tu es pour moi un asile; tu me préserves de la détresse; Tu m\'environnes de chants de délivrance. Pause');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 8, '«Je te rendrai intelligent. Je te montrerai le chemin que tu dois suivre; Je serai ton conseiller; mon oeil sera sur toi».');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 9, 'Ne soyez pas sans intelligence, comme le cheval et le mulet, Dont il faut serrer la bouche avec un mors et un frein, Pour s\'en faire obéir!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 10, 'Beaucoup de douleurs attendent le méchant; Mais celui qui se confie en l\'Éternel Est environné de miséricorde.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 11, 'Justes, réjouissez-vous en l\'Éternel, tressaillez de joie! Poussez des cris d\'allégresse, vous tous qui avez le coeur droit!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 1, 'Justes, réjouissez-vous en l\'Éternel! La louange convient aux hommes droits.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 2, 'Célébrez l\'Éternel avec la harpe; Louez-le sur la lyre à dix cordes!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 3, 'Chantez en son honneur un cantique nouveau; Faites retentir avec art vos instruments et vos voix!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 4, 'Car la parole de l\'Éternel est juste. Et sa fidélité se montre dans toutes ses oeuvres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 5, 'Il aime la justice et l\'équité. La terre est pleine de la bonté de l\'Éternel.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 6, 'Les cieux ont été créés par la parole de l\'Éternel, Et toute leur armée par le souffle de sa bouche.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 7, 'Il rassemble comme en un monceau les eaux de la mer; Il amasse les flots dans ses réservoirs.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 8, 'Que toute la terre craigne l\'Éternel! Que tous les habitants du monde le redoutent!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 9, 'Car il parle, et la chose existe; Il commande, et elle paraît.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 10, 'L\'Éternel déjoue les desseins des nations; Il anéantit les projets des peuples.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 11, 'Mais les desseins de l\'Éternel subsistent à perpétuité; Les projets de son coeur durent d\'âge en âge.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 12, 'Heureuse la nation dont l\'Éternel est le Dieu! Heureux le peuple qu\'il s\'est choisi pour héritage!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 13, 'L\'Éternel regarde du haut des cieux; Il voit tous les enfants des hommes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 14, 'Du lieu de sa demeure il observe Tous les habitants de la terre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 15, 'C\'est lui qui a formé le coeur de chacun d\'eux. Et qui observe toutes leurs actions.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 16, 'Ce n\'est pas au nombre de ses soldats Que le roi doit sa victoire; Ce n\'est pas à sa grande vigueur que le guerrier doit son salut.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 17, 'Pour triompher, on compte en vain sur le cheval: Sa grande vigueur n\'assure pas le salut.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 18, 'Mais l\'Éternel a les yeux sur ceux qui le craignent. Sur ceux qui espèrent en sa grâce.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 19, 'Aussi les délivre-t-il de la mort: Il les fait vivre, même en temps de famine.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 20, 'Notre âme espère en l\'Éternel: Il est notre aide et notre bouclier.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 21, 'C\'est en lui que notre coeur se réjouit; C\'est en son saint nom que nous avons mis notre confiance.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 22, 'Que ta grâce, ô Éternel, repose sur nous, Puisque nous avons mis notre espérance en toi!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 1, 'De David, lorsqu\'il contrefit l\'insensé en présence d\'Abimélec, et que, chassé par lui, il s\'éloigna. Je bénirai l\'Éternel en tout temps; Sa louange sera continuellement dans ma bouche.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 2, 'Mon âme mettra sa gloire en l\'Éternel; Les humbles m\'entendront et ils se réjouiront.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 3, 'Oui, glorifiez l\'Éternel avec moi; Exaltons son nom tous ensemble!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 4, 'J\'ai recherché l\'Éternel, et il m\'a répondu; Il m\'a affranchi de toutes mes frayeurs.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 5, 'Ceux qui tournent leurs yeux vers lui ont le visage rayonnant, Et ils n\'ont pas à rougir de honte.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 6, 'Cet affligé a crié, et l\'Éternel l\'a exaucé: Il l\'a délivré de toutes ses détresses.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 7, 'L\'ange de l\'Éternel campe autour de ceux qui le craignent, Et il les arrache au danger.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 8, 'Goûtez et voyez combien l\'Éternel est bon! Heureux l\'homme qui cherche en Lui son refuge!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 9, 'Craignez l\'Éternel, vous ses saints; Car rien ne manque à ceux qui le craignent!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 10, 'Les lionceaux connaissent la disette et la faim; Mais ceux qui recherchent l\'Éternel ne manquent d\'aucun bien.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 11, 'Venez, enfants, écoutez-moi: Je vous enseignerai la crainte de l\'Éternel.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 12, 'Quel est l\'homme qui prend plaisir à la vie. Qui souhaite de longs jours pour goûter le bonheur?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 13, 'Garde ta langue du mal, Et tes lèvres des paroles trompeuses.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 14, 'Détourne-toi du mal, et fais le bien; Recherche la paix, et poursuis-la.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 15, 'Les yeux de l\'Éternel sont sur les justes, Et ses oreilles sont attentives à leur cri.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 16, 'L\'Éternel tourne sa face contre ceux qui font le mal, Pour effacer de la terre leur souvenir.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 17, 'Quand les justes crient, l\'Éternel les exauce, Et il les délivre de toutes leurs détresses.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 18, 'L\'Éternel est près de ceux qui ont le coeur brisé, Et il sauve ceux dont l\'âme est abattue.,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 19, 'Le juste a des maux en grand nombre; Mais l\'Éternel le délivre de tous,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 20, 'Il veille sur tous ses os; Aucun d\'eux ne sera brisé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 21, 'La méchanceté fera périr le méchant, Et ceux qui haïssent le juste recevront leur châtiment.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 22, 'L\'Éternel rachète l\'âme de ses serviteurs; Et tous ceux qui cherchent en lui leur refuge Sont à l\'abri du châtiment.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 1, 'De David. Éternel, sois l\'adversaire de mes adversaires; Combats ceux qui me combattent!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 2, 'Prends le petit et le grand bouclier. Et lève-toi pour me secourir!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 3, 'Brandis ta lance, barre le passage à ceux qui me poursuivent; Dis à mon âme: «Je suis ton salut!»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 4, 'Qu\'ils soient honteux et confus, ceux qui en veulent à ma vie; Qu\'ils reculent et qu\'ils rougissent, ceux qui méditent ma perte!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 5, 'Qu\'ils soient comme la paille emportée par le vent. Et que l\'ange de l\'Éternel les chasse devant lui!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 6, 'Que leur chemin soit ténébreux et glissant. Et que l\'ange de l\'Éternel les poursuive!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 7, 'Car, sans motif, ils ont caché leur filet sous mes pas; Sans motif, ils ont creusé une fosse pour m\'ôter la vie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 8, 'Qu\'une ruine imprévue les atteigne! Qu\'ils soient pris dans le filet qu\'ils ont caché! Qu\'ils y tombent, et qu\'ils périssent!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 9, 'Alors mon âme frémira d\'allégresse en l\'Éternel, Et elle se réjouira de son salut.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 10, 'Tous mes os diront,: «Éternel, qui est semblable à toi, Toi qui délivres le malheureux du puissant qui l\'opprime, Le malheureux et le pauvre de celui qui les dépouille?»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 11, 'Des témoins criminels se lèvent; Ils m\'accusent de fautes que j\'ignore.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 12, 'Ils me rendent le mal pour le bien; Mon âme est dans l\'abandon.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 13, 'Mais moi, quand ils étaient malades, je me couvrais d\'un sac. J\'affligeais mon âme par le jeûne, Et je priais, la tête penchée sur ma poitrine.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 14, 'Je marchais lentement. Comme si j\'avais perdu un ami, un frère; J\'allais en habits de deuil, Comme accablé par la mort d\'une mère.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 15, 'Mais, si je viens à chanceler, Ils se rassemblent pour se réjouir. Ils se rassemblent contre moi, ils me calomnient à mon insu; Ils me déchirent sans relâche.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 16, 'Pareils à d\'impurs bouffons de table, Ils grincent des dents contre moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 17, 'Seigneur, jusques à quand supporteras-tu ce spectacle? Délivre mon âme de leurs violences; Arrache ma vie à ces lions!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 18, 'Alors je te célébrerai dans la grande assemblée; Je te louerai au milieu d\'un peuple nombreux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 19, 'Puissent mes perfides ennemis N\'avoir pas à se réjouir de mon sort! Que ceux qui me haïssent sans motif Ne me lancent pas des regards méprisants!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 20, 'Car jamais ils ne prononcent des paroles de paix; Mais ils trament de noirs complots Contre les gens tranquilles du pays.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 21, 'Ils ouvrent toute grande leur bouche contre moi, Disant: «Ah! ah! Notre oeil l\'a vu!» —');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 22, 'Tu l\'as vu, toi aussi, ô Éternel; ne te tais point! Seigneur, ne t\'éloigne point de moi!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 23, 'Réveille-toi, lève-toi, ô mon Dieu, mon Seigneur, Pour me rendre justice, pour défendre ma cause!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 24, 'Juge-moi selon la justice, ô Éternel, mon Dieu, Et qu\'ils ne se réjouissent pas à mon sujet!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 25, 'Qu\'ils ne disent pas en leur coeur: «Ah! voilà ce que nous désirions!» Qu\'ils ne puissent pas dire: «Nous l\'avons anéanti!»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 26, 'Qu\'ils soient honteux et qu\'ils rougissent. Tous ceux qui se réjouissent de mon malheur! Qu\'ils soient couverts d\'opprobre et d\'infamie, Ceux qui s\'élèvent orgueilleusement contre moi!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 27, 'Puissent-ils chanter et se réjouir, Ceux qui souhaitent le triomphe de ma juste cause, Et puissent-ils dire sans cesse: «Gloire soit à l\'Éternel, Qui veut le bien de son serviteur!»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 28, 'Alors ma langue proclamera ta justice, Et tous les jours elle redira tes louanges.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 1, 'Au maître-chantre. — De David, serviteur de l\'Éternel. Un esprit de révolte anime le coeur de l\'impie: Toute crainte de Dieu est bannie de sa vue.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 2, 'Ainsi est flatté son désir De consommer son crime, d\'assouvir sa haine.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 3, 'Les paroles de sa bouche ne sont que malice et que fraude; Il renonce à être sage, à faire le bien.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 4, 'Il médite l\'iniquité sur son lit; Il s\'engage dans une voie qui n\'est pas bonne; Il n\'a pas le mal en aversion!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 5, 'Éternel, ta bonté atteint jusqu\'aux cieux, Et ta fidélité jusqu\'aux nues.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 6, 'Ta justice est pareille aux montagnes de Dieu; Tes jugements sont comme l\'immense abîme. Eternel, tu accordes ta protection aux hommes et aux bêtes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 7, 'Dieu, que ta bonté est précieuse! Aussi les fils des hommes se réfugient-ils à l\'ombre de tes ailes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 8, 'Ils se rassasient des mets savoureux de ta maison. Et tu les abreuves au fleuve de tes délices.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 9, 'Car la source de la vie est en toi; C\'est par ta lumière que nous voyons la lumière.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 10, 'Étends ta bonté sur ceux qui te connaissent, Et ta justice sur les hommes qui ont le coeur droit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 11, 'Que le pied de l\'orgueilleux ne vienne pas m\'écraser, Et que la main des méchants ne me mette pas en fuite!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 12, 'Les voilà tombés, les ouvriers d\'iniquité; Ils ont été renversés et n\'ont pu se relever!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 1, 'De David. Ne t\'irrite pas au sujet des méchants; Ne porte pas envie à ceux qui font le mal.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 2, 'Car ils seront fauchés soudain comme l\'herbe; Ils se faneront comme l\'herbe verte.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 3, 'Confie-toi en l\'Éternel, et fais le bien; Habite en paix le pays, et mets ton plaisir dans la fidélité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 4, 'Fais de l\'Éternel tes délices. Et il t\'accordera ce que ton coeur demande.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 5, 'Remets ton sort à l\'Éternel; Confie-toi en lui, et il agira.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 6, 'Il fera éclater ta justice comme la lumière. Et ton droit comme le soleil en plein midi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 7, 'Abandonne-toi en paix à l\'Éternel, et mets ton espoir en lui. Ne t\'irrite point. Quand tu vois un homme réussir dans ses entreprises, Et venir à bout de ses mauvais desseins.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 8, 'Réprime la colère, et renonce au dépit; Ne t\'irrite point: cela t\'entraînerait au mal!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 9, 'En effet, les méchants seront exterminés; Mais ceux qui mettent leur confiance en l\'Éternel, Ceux-là posséderont la terre!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 10, 'Encore un peu de temps, et le méchant ne sera plus; Tu regarderas la place où il était, et il aura disparu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 11, 'Mais les humbles posséderont la terre, Et ils jouiront d\'une grande prospérité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 12, 'Le méchant suscite des complots contre le juste, Et il grince des dents contre lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 13, 'Le Seigneur se rit du méchant; Car il voit que le jour de son châtiment approche.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 14, 'Les méchants ont tiré l\'épée et bandé leur arc. Pour abattre l\'affligé et le pauvre, Pour égorger ceux qui suivent la voie droite.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 15, 'Leur épée entrera dans leur propre coeur, Et leurs arcs seront brisés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 16, 'Le peu qui appartient au juste Vaut mieux que l\'abondance de beaucoup de méchants.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 17, 'Car la puissance des méchants sera brisée; Mais l\'Éternel soutient les justes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 18, 'L\'Éternel veille sur les jours des hommes intègres, Et leur héritage subsiste à perpétuité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 19, 'Ils ne seront pas confus au temps du malheur; Ils seront rassasiés au jour de la famine.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 20, 'Car les méchants périront; Les ennemis de l\'Éternel passeront comme la parure des prés; Ils périront, ils disparaîtront comme une fumée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 21, 'Le méchant emprunte, et il ne rend pas; Mais le juste a compassion, et il donne.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 22, 'Ceux que Dieu bénit possèderont la terre; Mais ceux qu\'il maudit seront exterminés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 23, 'Les pas de l\'homme de bien sont affermis par l\'Éternel, Qui prend plaisir à lui montrer sa voie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 24, 'S\'il trébuche, il ne sera pas renversé; Car l\'Éternel le soutient par la main.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 25, 'J\'ai été jeune, et je suis devenu vieux; Mais je n\'ai pas vu le juste abandonné, Ni ses enfants mendiant leur pain.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 26, 'Tous les jours il a compassion et il prête. Et sa postérité est bénie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 27, 'Détourne-toi du mal et fais le bien. Et tu seras pour toujours en sécurité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 28, 'Car l\'Éternel aime la justice: Il n\'abandonne pas ses fidèles, qui sont gardés pour toujours; Mais la race des méchants sera exterminée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 29, 'Les justes posséderont la terre. Et ils y demeureront à perpétuité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 30, 'La bouche du juste annonce la sagesse. Et sa langue proclame la justice.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 31, 'La loi de son Dieu est dans son coeur; Ses pas ne chancelleront point.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 32, 'Le méchant épie le juste, Et il cherche à le faire périr.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 33, 'L\'Éternel ne le laissera pas en son pouvoir; Il ne le condamnera pas à l\'heure du jugement.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 34, 'Mets ta confiance en l\'Éternel, et marche dans ses voies: Il t\'élèvera et te fera posséder la terre. Et tu verras les méchants exterminés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 35, 'J\'ai vu le méchant au comble de la puissance, Et s\'étendant comme un arbre vigoureux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 36, 'Il n\'a fait que passer et voici qu\'il n\'est plus! Je l\'ai cherché: je n\'ai pu le trouver.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 37, 'Observe l\'homme intègre, et regarde l\'homme droit; Car il y a un avenir pour l\'homme de paix!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 38, 'Mais les pécheurs seront entièrement détruits: L\'espoir des méchants sera anéanti.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 39, 'La délivrance des justes vient de l\'Éternel: Il est leur rempart au temps de la détresse.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 40, 'L\'Éternel les secourt et les délivre; Il les délivre des méchants et les sauve. Parce qu\'ils cherchent auprès de lui leur refuge.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 1, 'Psaume de David. — Pour servir de mémorial. Éternel, ne me châtie pas, dans ta colère. Et ne me punis pas, dans ton courroux!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 2, 'Car tes flèches m\'ont atteint, Et ta main s\'est appesantie sur moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 3, 'Ton courroux n\'a épargné aucune partie de mon corps; Mon péché ne laisse aucun répit à mon corps.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 4, 'Car mes iniquités s\'élèvent au-dessus de ma tête; Elles sont comme un lourd fardeau, trop pesant pour moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 5, 'Mes plaies sont fétides et purulentes, A cause de mes égarements.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 6, 'Je suis courbé, abattu jusqu\'au dernier point; Je marche en habit de deuil tout le jour.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 7, 'Un feu ardent consume mes reins; Aucune partie de mon corps n\'a été épargnée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 8, 'Je suis accablé et tout brisé; Je rugis dans le frémissement de mon coeur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 9, 'Seigneur, tous mes désirs sont devant toi, Et mes soupirs ne te sont point cachés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 10, 'Mon coeur palpite, ma force m\'abandonne, Et la lumière même de mes yeux me fait défaut.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 11, 'Mes amis, mes compagnons s\'éloignent de ma plaie, Et mes proches se tiennent à distance.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 12, 'Ceux qui en veulent à ma vie me tendent des pièges; Ceux qui cherchent ma perte tiennent des propos meurtriers; Ils ne songent qu\'à dresser contre moi leurs embûches.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 13, 'Mais moi, comme un sourd, je n\'entends pas; Comme un muet, je n\'ouvre pas la bouche.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 14, 'Je suis comme un homme qui n\'entend pas. Et qui n\'a point de réplique sur les lèvres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 15, 'C\'est en toi, ô Éternel, que je mets mon espérance: Tu m\'exauceras, ô Seigneur, mon Dieu!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 16, 'J\'ai dit: Ne permets pas qu\'ils triomphent à mon sujet. Ceux qui me traitent avec mépris, quand mon pied chancelle!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 17, 'Car je suis près de tomber. Et ma douleur est toujours devant moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 18, 'Je confesse mon iniquité; Je suis dans la crainte, à cause de mon péché.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 19, 'Cependant, mes ennemis sont pleins de vie et de force; Ceux qui me haïssent sans motif sont nombreux,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 20, 'Et, me rendant le mal pour le bien. Ils se font mes adversaires, parce que je m\'attache au bien.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 21, 'Ne m\'abandonne pas, ô Éternel! Mon Dieu, ne t\'éloigne pas de moi!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 22, 'Hâte-toi, viens à mon secours. Seigneur, toi qui es ma délivrance!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 1, 'Au maître-chantre, à Jéduthun. — Psaume de David. Je disais: «Je veillerai sur ma conduite. Afin que ma langue ne commette aucun péché. Je mettrai un frein à mes lèvres, Tant que le méchant sera en ma présence.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 2, 'Je suis resté muet; j\'ai gardé le silence; Je me suis tu, alors que j\'étais privé de tout bien, Et ma douleur n\'a fait qu\'augmenter.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 3, 'Mon coeur brûlait au dedans de moi; Mes pensées étaient comme un feu ardent. Alors, ma langue a parlé!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 4, '«Éternel, fais-moi connaître ma fin. Et quelle est la mesure de mes jours; Que je sache combien courte est ma durée!»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 5, 'La largeur de la main. Telle est la mesure que tu accordes à mes jours, Et ma vie est comme un rien devant toi. Tout homme, si vigoureux soit-il, n\'est qu\'un souffle! Pause');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 6, 'Oui, l\'homme passe comme une ombre; Oui, tout le bruit qu\'il fait n\'est que vanité; Il amasse, et il ne sait qui recueillera.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 7, 'Et maintenant, que puis-je espérer, Seigneur? Mon espérance est en toi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 8, 'Délivre-moi de toutes mes transgressions, Et ne m\'expose pas aux outrages de l\'insensé!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 9, 'Je me tais, je n\'ouvre plus la bouche. Parce que c\'est toi qui agis.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 10, 'Détourne de moi tes châtiments! Je succombe sous les coups de ta main.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 11, 'Lorsque tu châties l\'homme En lui faisant porter le poids de sa faute. Tu consumes comme la teigne ce qu\'il a de plus cher. Oui, tout homme n\'est qu\'un souffle! Pause');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 12, 'Éternel, écoute ma requête, prête l\'oreille à mon cri; Ne sois pas insensible à mes larmes! Car je ne suis chez toi qu\'un étranger. Qu\'un passant, comme tous mes pères.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 13, 'Détourne de moi ton regard, et que je reprenne mes forces, Avant que je m\'en aille, et que je ne sois plus!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 1, 'Au maître-chantre. — Psaume de David. J\'ai fermement attendu l\'Éternel; Il s\'est incliné vers moi, il a entendu mes cris.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 2, 'Il m\'a fait remonter de la fosse de destruction. Du bourbier fangeux. Il a posé mes pieds sur le roc, Il a affermi mes pas.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 3, 'Il a mis dans ma bouche un chant nouveau, Un hymne à la louange de notre Dieu. Bien des hommes, témoins de ces délivrances. Craindront l\'Éternel et se confieront en lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 4, 'Heureux l\'homme qui place en l\'Éternel sa confiance, Qui ne se tourne pas vers les orgueilleux Et vers ceux que le mensonge égare!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 5, 'Éternel, mon Dieu, tu as multiplié Tes merveilles et tes dispensations en notre faveur: Impossible d\'en faire le compte devant toi! Je voudrais les proclamer et les publier: Elles sont trop nombreuses pour que je puisse les énumérer.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 6, 'Tu ne prends plaisir ni aux sacrifices ni aux offrandes; Mais tu m\'as donné des oreilles attentives: Tu ne demandes pas d\'holocauste, ni de sacrifice pour le péché.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 7, 'Alors j\'ai dit: «Me voici, je viens. Avec le rouleau du livre qui est écrit pour moi.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 8, 'Mon Dieu, je prends plaisir à faire ta volonté. Et ta loi est au fond de mon coeur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 9, 'J\'annonce ta justice devant la foule assemblée. Je ne tiens pas mes lèvres fermées, Tu le sais, ô Éternel!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 10, 'Je ne fais pas de ta justice un secret caché dans mon coeur; Je proclame ta fidélité et tes délivrances; Je ne tais point ta bonté ni ta vérité. Devant la foule assemblée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 11, 'Toi donc, ô Éternel, ne me refuse pas ta miséricorde! Que ta bonté et ta fidélité veillent constamment sur moi!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 12, 'Car des maux sans nombre m\'environnent. Mes iniquités m\'accablent; Ma vue en est obscurcie; Elles surpassent en nombre les cheveux de ma tête, Et mon coeur défaille.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 13, 'Éternel, daigne me délivrer! Éternel, accours à mon aide!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 14, 'Qu\'ils soient confus et qu\'ils rougissent Tous ceux qui cherchent à m\'ôter la vie! Qu\'ils reculent et soient couverts de honte Tous ceux qui prennent plaisir à ma perte!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 15, 'Que leur ignominie les fasse frémir d\'épouvante. Ceux qui disent de moi: «Ah! Ah!»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 16, 'Que tous ceux qui te recherchent S\'égaient et se réjouissent en toi! Que ceux qui espèrent en ton secours Disent sans cesse: «Gloire soit à l\'Éternel!»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 17, 'Je suis affligé et misérable; Le Seigneur aura soin de moi. Tu es mon aide et mon libérateur: mon Dieu, ne tarde pas!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 1, 'Au maître-chantre. — Psaume de David. Heureux celui qui sait avoir souci du misérable: L\'Éternel le délivrera au jour du malheur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 2, 'L\'Éternel le gardera et lui conservera la vie; Il le rendra heureux sur la terre; Il ne le livrera pas à la merci de ses ennemis.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 3, 'L\'Éternel le soutiendra sur son lit de douleur. L\'Éternel viendra l\'assister, quand il sera malade.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 4, 'J\'ai dit: «Éternel, aie pitié de moi! Guéris mon âme, car j\'ai péché contre toi!»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 5, 'Mes ennemis tiennent sur moi des propos malveillants! «Quand mourra-t-il? Quand périra son nom?»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 6, 'Si l\'un d\'eux vient me voir, il tient un langage faux. Il amasse dans son coeur un monceau de calomnies; Et, aussitôt, sorti, il s\'empresse de les divulguer.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 7, 'Tous ceux qui me haïssent chuchotent entre eux contre moi; Ils ne songent qu\'à me nuire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 8, '«Quelque crime pèse sur lui, disent-ils; Le voilà couché, il ne se relèvera plus!»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 9, 'Mon ami même. Celui qui avait ma confiance et mangeait mon pain, A levé le talon contre moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 10, 'Mais toi, ô Éternel, aie pitié de moi, et relève-moi. Et je traiterai mes adversaires comme ils le méritent!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 11, 'Si mon ennemi ne triomphe pas de moi, Je reconnaîtrai à ce signe que je te suis agréable.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 12, 'Oui, tu me soutiendras, à cause de mon intégrité; Tu me feras subsister en ta présence pour toujours.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 13, 'BÉNI SOIT l\'Éternel, le Dieu d\'Israël, D\'ÉTERNITÉ en éternité! Amen! Amen!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 1, 'Au maître-chantre. — Hymne des enfants de Goré. Comme un cerf brame après les eaux courantes, Ainsi mon âme soupire après toi, ô Dieu!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 2, 'Mon âme a soif de Dieu, du Dieu vivant. Quand entrerai-je et me présenterai-je devant sa face?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 3, 'Les larmes sont jour et nuit ma nourriture, Depuis qu\'on me dit sans cesse: «Où est ton Dieu?»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 4, 'Je me souviens — et mon coeur se brise à ce souvenir! — Que je marchais avec la foule, Et m\'avançais à sa tête jusqu\'à la maison de Dieu, Au milieu des cris de joie et de louange D\'une multitude en fête.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 5, 'Pourquoi t\'abats-tu, mon âme, et pourquoi frémis-tu en moi? Espère en Dieu; car je le célébrerai encore: Il est mon salut et mon Dieu!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 6, 'Mon âme est abattue en moi, Parce que je pense à toi, ô Dieu, dans le pays du Jourdain, Et dans les montagnes de l\'Hermon et de Mitséar.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 7, 'La vague appelle la vague, quand mugit la tempête; Tous les flots, tous les torrents ont passé sur moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 8, 'Pendant le jour, l\'Éternel répandait sur moi sa grâce. Et la nuit sa louange était sur ma bouche. Je prie le Dieu qui est ma vie;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 9, 'Je dis à Dieu, mon rocher: «Pourquoi m\'as-tu oublié?» Pourquoi marcherais-je en vêtements de deuil, Sous l\'oppression de l\'ennemi?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 10, 'Je sens mes os se briser, quand mes oppresseurs m\'outragent, En me disant chaque jour: «Où est ton Dieu?»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 11, 'Pourquoi t\'abats-tu, mon âme, et pourquoi frémis-tu en moi? Espère en Dieu; car je le célébrerai encore: Il est mon salut et mon Dieu!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 1, 'Rends-moi justice, ô Dieu, défends ma cause Contre une nation infidèle! Délivre-moi de l\'homme trompeur et pervers!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 2, 'Tu es mon Dieu, mon rempart. Pourquoi m\'as-tu rejeté? Pourquoi dois-je marcher en vêtements de deuil, Sous l\'oppression de l\'ennemi?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 3, 'Envoie ta lumière et ta vérité: qu\'elles me guident; Qu\'elles me ramènent sur ta montagne sainte. Dans ta demeure!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 4, 'Alors je m\'avancerai vers l\'autel de Dieu,» Du Dieu qui est ma joie et mon allégresse. Puis je te célébrerai sur la harpe, ô Dieu, mon Dieu!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 5, 'Pourquoi t\'abats-tu, mon âme, et pourquoi frémis-tu en moi? Espère en Dieu, car je le célébrerai encore: Il est mon salut et mon Dieu!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 1, 'Au maître-chantre. — Hymne des enfants de Coré. Dieu, nous avons entendu de nos oreilles, Nos pères nous ont raconté L\'oeuvre que tu as faite de leur temps, Aux jours d\'autrefois.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 2, 'De ta main tu les as établis, en dépossédant les nations; Tu as détruit des peuples pour leur faire une place.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 3, 'Car ce n\'est pas leur épée qui leur a conquis le pays; Ce n\'est pas leur bras qui les a sauvés: C\'est ta main droite, c\'est ton bras, C\'est la lumière de ta face. Parce que tu leur étais favorable!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 4, 'Dieu, toi qui es mon roi. Donne à Jacob la victoire!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 5, 'Par toi nous repousserons nos ennemis; En ton nom nous écraserons nos adversaires.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 6, 'Car ce n\'est pas en mon arc que je mets ma confiance; Ce n\'est pas mon épée qui me sauvera.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 7, 'C\'est toi qui nous as délivrés de nos oppresseurs. Et qui as couvert de honte nos ennemis.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 8, 'C\'est en Dieu que nous nous glorifions chaque jour; Nous célébrerons son nom éternellement. Pause');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 9, 'Cependant, tu nous as rejetés et couverts d\'opprobre, Et tu ne sors plus avec nos armées.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 10, 'Tu nous fais reculer devant l\'oppresseur. Et nos ennemis se partagent nos dépouilles.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 11, 'Tu nous livres comme des brebis à dévorer; Tu nous as dispersés parmi les nations.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 12, 'Tu vends ton peuple pour rien. Et tu le mets à vil prix.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 13, 'Tu fais de nous un objet d\'opprobre pour nos voisins; Nous sommes la risée, le jouet de ceux qui nous entourent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 14, 'Oui, tu fais de nous la fable des nations; En nous voyant, les peuples hochent la tête.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 15, 'La honte m\'accable tous les jours, Et la confusion couvre mon visage,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 16, 'A la voix de celui qui m\'insulte et m\'outrage, Sous les regards de mon ennemi, De celui qui s\'acharne à ma perte.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 17, 'Tous ces malheurs nous sont arrivés. Cependant nous ne t\'avions pas oublié. Nous n\'avions pas violé ton alliance.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 18, 'Notre coeur ne s\'était pas détourné de toi; Nos pas ne s\'étaient point écartés de ton sentier.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 19, 'Et pourtant, tu nous as refoulés parmi les chacals; Tu nous as couverts de l\'ombre de la mort.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 20, 'Si nous eussions oublié le nom de notre Dieu, Si nous eussions étendu nos mains vers un Dieu étranger,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 21, 'Dieu n\'en serait-il pas informé, Lui qui connaît les secrets du coeur?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 22, 'Mais c\'est à cause de toi Que nous sommes sans cesse livrés à la mort. Et traités comme des brebis destinées à la boucherie!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 23, 'Réveille-toi! Pourquoi dors-tu, Seigneur? Lève-toi, ne nous rejette pas pour toujours!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 24, 'Pourquoi caches-tu ta face? Pourquoi oublies-tu notre misère et notre détresse?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 25, 'Car notre âme est abattue dans la poussière; Notre corps reste attaché à la terre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 26, 'Lève-toi, viens à notre aide, Et délivre-nous, à cause de ta bonté!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 1, 'Au maître-chantre. — Sur «les lis.» — Hymne des enfants de Goré. — Cantique nuptial. De mon coeur débordent des paroles excellentes. Je me dis: «Mon oeuvre est pour le roi!» Ma langue sera comme la plume d\'un habile écrivain.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 2, 'Tu es beau, plus beau qu\'aucun des fils des hommes. La grâce est répandue sur tes lèvres; C\'est pourquoi Dieu t\'a béni à jamais.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 3, 'Vaillant guerrier, ceins sur tes flancs ton épée, — Ta parure et ta magnificence,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 4, 'Oui, ta magnificence! — Cours à la victoire, monte sur ton char. Pour le triomphe de la vérité, de la clémence et de la justice. Que ta main droite te fasse accomplir des exploits redoutables!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 5, 'Tes flèches sont aiguës: Elles feront tomber les peuples sous tes pieds; Elles frapperont au coeur les ennemis du roi!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 6, 'Ton trône, ô Dieu, est établi pour toujours, à perpétuité; Le sceptre de ta royauté est un sceptre de justice.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 7, 'Tu aimes la justice et tu hais la méchanceté; C\'est pourquoi, ô Dieu, ton Dieu t\'a oint D\'une huile d\'allégresse, de préférence à tous tes égaux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 8, 'La myrrhe, l\'aloès et la casse parfument tous tes vêtements; Dans les palais d\'ivoire, le jeu des instruments te réjouit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 9, 'Des filles de rois sont parmi tes dames d\'honneur; A ta droite se tient la reine, parée de l\'or d\'Ophir.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 10, 'Écoute, ma fille, vois et prête l\'oreille; Oublie ton peuple et la maison de ton père.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 11, 'Le roi désire pour lui ta beauté; Puisqu\'il est ton seigneur, prosterne-toi devant lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 12, 'La fille de Tyr, chargée de présents, Ainsi que les plus riches du peuple, Viendront te rendre hommage.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 13, 'Elle s\'avance rayonnante de gloire, la fille du roi; Son vêtement est tissé d\'or.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 14, 'Elle est présentée au roi, revêtue d\'habits brodés. A sa suite, des vierges, ses compagnes, Sont amenées en sa présence.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 15, 'Elles sont introduites, Au milieu des chants de joie et d\'allégresse; Elles entrent dans le palais du roi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 16, 'Tes fils, ô roi, occuperont la place de tes pères; Tu les établiras princes sur toute la terre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 17, 'Je rendrai ton nom célèbre dans tous les âges; Aussi les peuples te loueront-ils éternellement, à perpétuité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 1, 'Au maître-chantre. — Des enfants de Coré. — Cantique pour voix de jeunes filles. Dieu est pour nous un refuge, un rempart. Un secours dans nos détresses: On trouve aisément accès auprès de lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 2, 'C\'est pourquoi nous ne craindrons rien, Quand même la terre serait bouleversée, Et que les montagnes seraient ébranlées au sein de la mer,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 3, 'Quand même les flots mugiraient en bouillonnant. Et que leur furie ferait trembler les montagnes. Pause');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 4, 'Il est un fleuve, dont les flots réjouissent la cité de Dieu, Le sanctuaire de la Demeure du Très-Haut.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 5, 'Dieu est au milieu d\'elle: elle ne sera point ébranlée. Dieu lui donne son secours dès l\'aube du matin.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 6, 'Les nations s\'agitent, les nations s\'ébranlent: Il fait entendre sa voix, et la terre tremble.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 7, 'L\'Éternel des armées est avec nous; Le Dieu de Jacob est notre haute retraite. Pause');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 8, 'Venez, contemplez les oeuvres de l\'Éternel, Les étonnants prodiges qu\'il accomplit sur la terre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 9, 'Il fait cesser les combats jusqu\'aux extrémités du monde; Il rompt les arcs et brise les lances; Il brûle les chars au feu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 10, '«Arrêtez, dit-il, et sachez que c\'est moi qui suis Dieu. Je domine sur les nations, je domine sur la terre!»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 11, 'L\'Éternel des armées est avec nous; Le Dieu de Jacob est notre haute retraite. Pause');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 1, 'Au maître-chantre. — Psaume des enfants de Coré. Vous tous, peuples, battez des mains; Faites monter vers Dieu des cris de joie!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 2, 'Car l\'Éternel est le Très-Haut, le redoutable, Le grand roi de toute la terre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 3, 'Il range les peuples sous nos lois, Et il met les nations sous nos pieds.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 4, 'Il a choisi pour nous ce pays, qui est l\'héritage Et la gloire de Jacob, son bien-aimé. Pause');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 5, 'Dieu s\'avance au milieu des cris de triomphe. L\'Éternel s\'avance au son de la trompette.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 6, 'Chantez à la gloire de Dieu, chantez! Chantez à la gloire de notre Roi, chantez!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 7, 'Car Dieu est roi de toute la terre: Chantez un cantique!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 8, 'Dieu règne sur les nations; Dieu siège sur son trône saint.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 9, 'Les princes des peuples se rassemblent, Pour former aussi le peuple du Dieu d\'Abraham; Car à Dieu appartiennent les puissants de la terre: Il est élevé au-dessus de tous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 1, 'Cantique. — Psaume des enfants de Coré. L\'Éternel est grand et digne de toute louange. Dans la ville de notre Dieu, sur sa montagne sainte.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 2, 'Elle s\'élève avec grâce, du côté du Septentrion, La montagne de Sion, joie de toute la terre: C\'est la cité du grand roi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 3, 'Dans ses palais, Dieu se révèle à nous Comme un rempart.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 4, 'Les rois s\'étaient donné rendez-vous; Ils s\'avançaient, ensemble.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 5, 'Ils virent Jérusalem; ils furent frappés d\'étonnement, Terrifiés, mis en déroute.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 6, 'Soudain, ils furent saisis d\'un tremblement, D\'une angoisse pareille à celle de la femme qui enfante.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 7, 'Au souffle du vent de l\'Orient, Tu brises les navires de Tarsis.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 8, 'Ce que nous avions entendu dire, nous l\'avons vu Dans la ville de l\'Éternel des armées, Dans la cité de notre Dieu: Dieu fera subsister Jérusalem à jamais. Pause');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 9, 'Dieu, nous avons contemplé ta bonté Au milieu de ton temple.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 10, 'Ainsi que ton nom, ô Dieu, Ta louange retentit jusqu\'aux extrémités de la terre. Ta main droite est pleine de justice.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 11, 'Que la montagne de Sion se réjouisse; Que les filles de Juda tressaillent d\'allégresse, A cause de tes jugements.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 12, 'Faites le tour de Sion, parcourez son enceinte, Comptez ses tours,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 13, 'Considérez ses remparts, Examinez ses palais, Pour dire à la génération future:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 14, '«Ce Dieu est notre Dieu, pour toujours, à perpétuité; Il nous fera surmonter la mort!»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 1, 'Au maître-chantre. — Psaume des enfants de Coré. O peuples, écoutez tous; Prêtez tous l\'oreille, habitants du monde,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 2, 'Enfants du peuple et enfants des grands, Le riche aussi bien que le pauvre!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 3, 'Ma bouche prononcera des paroles sages: Les pensées de mon coeur sont pleines de sens.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 4, 'Je prêterai l\'oreille aux sentences qu\'il m\'inspire; J\'expliquerai mon énigme au son de la harpe.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 5, 'Pourquoi aurais-je peur aux jours de l\'infortune, Quand la méchanceté de mes adversaires m\'environne?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 6, 'Ils se confient en leurs biens; Ils se glorifient de la grandeur de leurs richesses.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 7, 'Mais l\'homme ne saurait racheter son frère, Ni payer à Dieu sa rançon:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 8, 'Le rachat d\'une âme est trop cher; On ne saurait en payer le prix!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 9, 'Ils ne vivront pas toujours; Ils n\'éviteront pas la vue du tombeau;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 10, 'Oui, ils le verront! Les sages meurent; Le fou et l\'insensé périssent également, Et ils laissent leurs biens à d\'autres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 11, 'Ils pensent que leurs maisons dureront éternellement, Que leurs demeures subsisteront d\'âge en âge; Et ils donnent leurs noms à leurs terres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 12, 'Mais l\'homme, même le plus opulent, n\'a point de durée; Il est semblable aux bêtes vouées à la destruction.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 13, 'La voie qu\'ils suivent est celle de la folie: Pourtant, ceux qui viennent après eux Approuvent leurs discours. Pause');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 14, 'Ils sont poussés vers le Séjour des morts comme un troupeau; La mort les conduit comme un berger. Quand vient le matin, les justes les foulent aux pieds; Leur beauté disparaîtra dans le tombeau! Ils n\'auront pas d\'autre demeure!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 15, 'Mais Dieu délivrera mon âme de l\'étreinte du Séjour des morts; Car il me prendra sous sa garde.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 16, 'Ne crains point, quand un homme s\'enrichit, Quand l\'opulence de sa maison s\'accroît.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 17, 'Car, en mourant, il n\'emportera rien; Son opulence ne le suivra pas dans la tombe.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 18, 'Tu as beau te proclamer heureux pendant ta vie, Ou t\'attirer des louanges pour les joies que tu as en partage.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 19, 'Tu t\'en iras pourtant vers la génération de tes pères. Qui ne reverront jamais la lumière.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 20, 'L\'homme, même le plus opulent, qui n\'a point d\'intelligence, Est semblable aux bêtes vouées à la destruction!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 1, 'Psaume d\'Asaph. Le Dieu fort, Dieu, l\'Éternel, a parlé: il a convoqué la terre, Du soleil levant au soleil couchant.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 2, 'De Sion, parfaite en beauté, Dieu fait rayonner sa splendeur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 3, 'Il vient, notre Dieu, et il ne se tait point; Devant lui est un feu dévorant. Autour de lui une tempête furieuse.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 4, 'Il convoque les cieux d\'en haut. Ainsi que la terre, pour juger son peuple:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 5, '«Rassemblez-moi mes fidèles, Qui ont scellé leur alliance avec moi par un sacrifice»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 6, 'Et les cieux proclament sa justice; Car c\'est Dieu lui-même qui va juger! Pause');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 7, 'Écoute, ô mon peuple, et je parlerai. Écoute, ô Israël! Je te ferai entendre mes avertissements: Je suis Dieu, ton Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 8, 'Ce n\'est pas pour tes sacrifices que je te ferai des reproches, Ni pour tes holocaustes, qui sont continuellement devant moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 9, 'Je ne prendrai point de taureau dans ta maison, Ni de bouc dans tes bergeries;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 10, 'Car c\'est à moi qu\'appartiennent tous les animaux des forêts. Ainsi que les bêtes des montagnes, par milliers.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 11, 'Je connais tous les oiseaux des montagnes, Et tout ce qui se meut dans les champs m\'appartient.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 12, 'Si j\'avais faim, je ne t\'en dirais rien; Car à moi est le monde et tout ce qu\'il renferme.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 13, 'Ai-je besoin de manger la chair des taureaux, Ou de boire le sang des boucs?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 14, 'Pour sacrifice, offre à Dieu tes louanges, Et accomplis tes voeux envers le Très-Haut!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 15, 'Puis, invoque-moi au jour de la détresse: Je te délivrerai, et tu me glorifieras.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 16, 'Mais Dieu dit au méchant: «A quoi bon réciter mes commandements Et célébrer des lèvres mon alliance,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 17, 'Quand tu hais la réprimande Et quand tu repousses mes paroles loin de toi?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 18, 'Lorsque tu vois un voleur, tu te plais avec lui; Tu fais cause commune avec les adultères.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 19, 'Tu livres ta bouche à la calomnie, Et ta langue ourdit la fraude.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 20, 'Tu t\'assieds et tu parles contre ton frère; Tu diffames le fils de ta mère.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 21, 'Voilà ce que tu as fait; et parce que j\'ai gardé le silence, Tu t\'es imaginé que j\'étais pareil à toi! Je vais te reprendre et mettre ton iniquité sous tes yeux.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 22, 'Comprenez donc cela, vous qui oubliez Dieu, De peur que je ne vous mette en pièces. Sans que personne puisse vous délivrer!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 23, 'Celui qui offre pour sacrifice la louange, me glorifie; Et à celui qui veille sur sa conduite Je ferai contempler le salut de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 1, 'Au maître-chantre. — Psaume de David, lorsque Nathan le prophète vint le trouver, après que David fut allé auprès de Bath-Séba. O Dieu, aie pitié de moi, dans ta miséricorde! Dans tes grandes compassions, efface mes forfaits!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 2, 'Lave-moi entièrement de mon iniquité, Et purifie-moi de mon péché!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 3, 'Car je connais mes transgressions, Et mon péché est toujours devant moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 4, 'J\'ai péché contre toi, contre toi seul, Et j\'ai fait ce qui est mal à tes yeux. De sorte que tu seras reconnu juste quand tu parleras, Et sans reproche quand tu jugeras.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 5, 'Hélas! Je suis né dans l\'iniquité. Et ma mère m\'a conçu dans le péché.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 6, 'Et toi, tu aimes la sincérité du coeur: Fais-moi donc connaître la sagesse dans le secret de mon âme.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 7, 'Purifie-moi avec l\'hysope, et je serai sans tache; Lave-moi, et je serai plus blanc que la neige.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 8, 'Fais-moi entendre les chants de joie et d\'allégresse. Et que les os que tu as brisés se réjouissent!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 9, 'Détourne de mes péchés tes regards; Efface toutes mes iniquités!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 10, 'Dieu, crée en moi un coeur pur. Et renouvelle en moi un esprit bien disposé!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 11, 'Ne me rejette pas loin de ta face, Et ne me retire pas ton esprit saint!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 12, 'Rends-moi la joie que donne ton salut; Fortifie-moi, afin que j\'aie le coeur prompt à bien faire!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 13, 'J\'enseignerai tes voies aux transgresseurs. Et les pécheurs se convertiront à toi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 14, 'Délivre-moi du sang versé, ô Dieu, Dieu de mon salut! Alors ma langue célébrera ta justice.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 15, 'Seigneur, ouvre mes lèvres, Et ma bouche proclamera tes louanges.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 16, 'Car tu ne prends pas plaisir aux sacrifices, Autrement j\'en offrirais. L\'holocauste ne t\'est point agréable.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 17, 'Le sacrifice agréable à Dieu, c\'est un esprit brisé. Dieu, tu ne méprises pas le coeur contrit et brisé!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 18, 'Fais du bien à Sion, dans ta grâce; Édifie les murs de Jérusalem.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 19, 'Alors tu prendras plaisir aux sacrifices prescrits par la loi, A l\'holocauste et aux victimes entières; Alors on immolera des taureaux sur ton autel.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 1, 'Au maître-chantre. — Hymne de David, lorsque Doëg, l\'Édomite, vint avertir Saül, et lui dit: «David est entré dans la maison d\'Ahimélec.» Pourquoi te glorifies-tu de ta méchanceté, homme puissant? La bonté de Dieu dure éternellement.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 2, 'Ta langue est pareille au rasoir affilé: Elle ne médite que des ruines, ô artisan de fraudes!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 3, 'Tu aimes mieux le mal que le bien; Tu préfères le mensonge à la sincérité. Pause');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 4, 'Tu n\'aimes que les paroles pernicieuses, Langue perfide!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 5, 'C\'est pourquoi, Dieu te détruira pour toujours; Il te saisira et t\'arrachera de ta tente. Il te déracinera de la terre des vivants. Pause');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 6, 'Les justes verront ta ruine, et ils auront de la crainte. Ils riront à ton sujet:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 7, '«Le voilà, l\'homme qui n\'a point pris Dieu pour rempart, Qui s\'est confié dans ses grandes richesses. Et qui s\'est prévalu de sa méchanceté!»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 8, 'Mais moi, je suis comme un olivier verdoyant Dans la maison de Dieu; Je me confie en la bonté de Dieu, éternellement, à perpétuité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 9, 'Je te célébrerai toujours, parce que tu auras fait ton oeuvre. Et j\'espérerai en ton nom, en présence de tes fidèles; Car tu es bon!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 1, 'Au maître-chantre. — Sur un mode triste. — Hymne de David. L\'insensé a dit en son coeur: «Il n\'y a point de Dieu!» Les hommes sont corrompus: leur conduite est abominable; Il n\'y a personne qui fasse le bien.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 2, 'Dieu abaisse des cieux son regard sur les fils des hommes, Pour voir s\'il y a quelque homme intelligent Et qui cherche Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 3, 'Ils se sont tous égarés, ils se sont pervertis tous ensemble: Il n\'y en a pas qui fasse le bien. Non, pas même un seul!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 4, 'Sont-ils donc sans intelligence, ces ouvriers d\'iniquité? Ils dévorent mon peuple comme on mange du pain; Ils n\'invoquent point Dieu!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 5, 'Ils seront saisis d\'une terreur soudaine. Sans avoir aucun sujet de crainte; Car Dieu dispersera les os de ceux qui t\'assiègent. Tu les couvriras de honte; car Dieu les a rejetés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 6, 'Oh! Qui apportera de Sion la délivrance d\'Israël? Quand Dieu ramènera les captifs de son peuple, Jacob sera dans l\'allégresse, Israël sera dans la joie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 1, 'Au maître-chantre. — Avec instruments à cordes. Hymne de David, lorsque les Ziphiens vinrent dire à Saül: «David se tient caché parmi nous.» Dieu, sauve-moi par la vertu de ton nom, Et fais-moi justice par ta puissance!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 2, 'Dieu, écoute ma prière! Prête l\'oreille aux paroles de ma bouche!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 3, 'Car des étrangers se sont levés contre moi. Et des hommes violents en veulent à ma vie: Ils éloignent Dieu de leurs pensées. Pause');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 4, 'Oui, Dieu est mon secours; Le Seigneur est parmi ceux qui soutiennent mon âme.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 5, 'Il fera retomber le mal sur mes ennemis. Dans ta fidélité, détruis-les!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 6, 'Je t\'offrirai des sacrifices volontaires; Je célébrerai ton nom, ô Éternel; car tu es bon:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 7, 'Tu m\'as délivré de toutes mes détresses, Et mon oeil a contemplé la confusion de mes ennemis.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 1, 'Au maître-chantre. — Avec instruments à cordes. — Hymne de David. Dieu, prête l\'oreille à ma prière. Et ne te dérobe pas à ma supplication!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 2, 'Ecoute-moi et réponds-moi! J\'erre çà et là dans ma douleur, et je gémis');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 3, 'Devant les menaces de l\'ennemi et l\'oppression du méchant. Car ils font tomber le malheur sur moi. Et ils me persécutent avec fureur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 4, 'Mon coeur est tourmenté en moi. Et les terreurs de la mort m\'ont assailli.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 5, 'La crainte et l\'épouvante s\'emparent de moi; L\'horreur m\'enveloppe.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 6, 'Alors j\'ai dit: «Oh! Qui me donnera les ailes de la colombe? Je m\'envolerais et je me reposerais!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 7, 'Oui, je m\'enfuirais bien loin. Je me réfugierais dans le désert! Pause');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 8, 'Je me hâterais de chercher un abri Contre le vent violent, contre la tempête»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 9, 'Anéantis les méchants. Seigneur, déjoue leurs complots; Car je ne vois que violences et discordes dans la ville.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 10, 'Ils font la ronde, jour et nuit, sur ses remparts; Le crime et l\'injustice règnent dans son sein.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 11, 'Elle est pleine d\'iniquités; L\'oppression et la fraude ne quittent pas ses places.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 12, 'Car ce n\'est pas un ennemi qui m\'outrage: Je pourrais le supporter! Ce n\'est pas mon adversaire qui m\'accable: Je me cacherais loin de lui!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 13, 'Mais c\'est toi, un autre moi-même, Mon intime et mon confident!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 14, 'Nous avions ensemble de doux entretiens; Ensemble nous allions avec la foule à la maison de Dieu!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 15, 'Que la mort les surprenne! Qu\'ils descendent vivants dans le Sépulcre; Car la malice habite dans leur demeure, dans leur coeur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 16, 'Pour moi, je crie vers Dieu, Et l\'Éternel me sauvera.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 17, 'Le soir, le matin, à midi, je gémis et je soupire: Il entendra ma voix.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 18, 'Il délivrera mon âme et la mettra en sûreté. Loin de leurs atteintes. Si nombreux que soient mes adversaires.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 19, 'Dieu m\'entendra; il leur répondra, Lui qui règne dès l\'éternité. Pause En effet, ils ne veulent pas revenir au bien. Et ils n\'ont pas la crainte de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 20, 'Ils s\'attaquent à leurs meilleurs amis Dont ils trahissent la confiance.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 21, 'Leur langage a plus de douceur que la crème; Mais la guerre est dans leur coeur. Leurs paroles sont plus onctueuses que l\'huile; Mais elles sont acérées comme des glaives.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 22, 'Décharge-toi de ton fardeau sur l\'Éternel, et il te soutiendra; Il ne permettra pas toujours que le juste chancelle.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 23, 'C\'est toi, ô Dieu, qui les précipiteras au fond de la fosse, Ces hommes de sang et de fraude! Ils n\'arriveront pas à la moitié de leurs jours; Mais moi, je mets en toi ma confiance.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 1, 'Au maître-chantre. — Sur «Colombe des térébinthes lointains.»!!- Poème de David, lorsque les Philistins le prirent dans Gath. Aie pitié de moi, ô Dieu! Car des hommes s\'acharnent à ma perte; Tout le jour ils m\'assaillent et me persécutent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 2, 'Tout le jour mes adversaires s\'acharnent à me perdre; Car ils sont nombreux, ceux qui me provoquent avec insolence.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 3, 'Aux jours d\'alarme, Je me confierai en toi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 4, 'Avec le secours de Dieu, j\'exalterai sa parole. En Dieu je me confie, je ne crains rien; Que pourrait me faire l\'homme mortel?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 5, 'Sans cesse ils tordent mes paroles; Toutes leurs pensées tendent à me nuire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 6, 'Ils s\'assemblent, ils s\'embusquent, ils observent mes pas; Car ils en veulent à ma vie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 7, 'La méchanceté les sauvera-t-elle? Dieu, précipite les peuples dans ta colère!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 8, 'Tu comptes mes pas dans ma vie d\'exil; Recueille mes larmes dans tes urnes: Ne sont-elles pas inscrites dans ton livre?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 9, 'Au jour où je crierai, mes ennemis reculeront; Je sais que Dieu est pour moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 10, 'Avec le secours de Dieu, j\'exalterai sa parole; Oui, avec le secours de l\'Eternel, j\'exalterai sa parole.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 11, 'En Dieu je me confie; je ne crains rien; Que pourrait me faire l\'homme mortel?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 12, 'Dieu, je me souviens des promesses que je t\'ai faites. Je te rendrai des actions de grâces!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 13, 'Car tu as délivré mon âme de la mort, Et tu préserveras mes pieds de toute chute. Afin que je marche devant toi, ô Dieu, Dans la lumière de la vie!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 1, 'Au maître-chantre. — «Ne détruis pas.» — Poème de David, lorsqu\'il s\'enfuit dans la caverne, poursuivi par Saül. Aie pitié, ô Dieu, aie pitié de moi; Car mon âme cherche en toi son refuge. Je me réfugie à l\'ombre de tes ailes. Jusqu\'à ce que la calamité soit passée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 2, 'Je crie vers le Dieu Très-Haut, Vers le Dieu fort qui agira pour moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 3, 'Il m\'enverra des cieux sa délivrance. Tandis que mon persécuteur me couvre d\'outrages. Pause Oui, Dieu m\'enverra sa grâce et son secours fidèle.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 4, 'Mon âme est au milieu des lions; J\'habite avec des hommes qui vomissent des flammes Dont les dents sont des lances et des flèches, Et dont la langue est un glaive acéré.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 5, 'Dieu, élève-toi au-dessus des cieux! Que ta gloire couvre toute la terre!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 6, 'Ils avaient tendu un piège sous mes pas; Mon âme chancelait; Ils avaient creusé une fosse devant moi: Ils y sont tombés! Pause');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 7, 'Mon coeur est bien disposé, ô Dieu! Oui, mon coeur est bien disposé Pour chanter, pour psalmodier.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 8, 'Réveille-toi, mon âme; réveillez-vous, mon luth et ma harpe: Je veux devancer l\'aurore.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 9, 'Je te célébrerai parmi les peuples. Seigneur! Je te louerai parmi les nations;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 10, 'Car ta bonté atteint jusqu\'aux cieux. Et ta fidélité jusqu\'aux nues.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 11, 'O Dieu, élève-toi au-dessus des cieux! Que ta gloire couvre toute la terre!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 1, 'Au maître-chantre. — «Ne détruis pas.» — Poème de David. Est-ce bien la justice que vous rendez, ô puissants? Jugez-vous avec droiture les enfants des hommes?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 2, 'Loin de là! Vous commettez sciemment des iniquités; Dans tout le pays, vos mains criminelles Font fléchir la balance de la justice.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 3, 'Les méchants se sont éloignés de Dieu dès le sein maternel; Les menteurs se sont pervertis dès leur naissance.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 4, 'Ils ont un venin semblable au venin du serpent; Ils sont comme un aspic sourd, qui ferme l\'oreille,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 5, 'Qui n\'écoute pas la voix des enchanteurs. Du charmeur expert dans son art.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 6, 'Dieu, brise dans leur bouche les dents des méchants! Éternel, romps les mâchoires de ces lionceaux!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 7, 'Qu\'ils se dissipent comme l\'eau qui s\'écoule! Que les flèches lancées par eux soient émoussées!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 8, 'Qu\'ils soient semblables au limaçon qui se dissout quand il rampe! Que, pareils à l\'avorton, ils ne voient pas le soleil!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 9, 'Avant que leurs chaudières aient senti le feu des épines. Encore vertes ou embrasées, — que le tourbillon les emporte!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 10, 'Le juste se réjouira lorsqu\'il aura vu la vengeance; Il baignera ses pieds dans le sang du méchant.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 11, 'Et l\'on dira: «Oui, il y a une récompense pour le juste; Oui, il y a un Dieu qui fait justice sur la terre.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 1, 'Au maître-chantre. — «Ne détruis pas.» — Poème de David, lorsque Saül envoya cerner sa maison pour le faire mourir. Délivre-moi de mes ennemis, ô mon Dieu! Mets-moi hors de l\'atteinte de mes adversaires!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 2, 'Délivre-moi des ouvriers d\'iniquité; Sauve-moi des hommes sanguinaires!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 3, 'Voici qu\'ils sont aux aguets pour m\'ôter la vie; Des hommes violents se rassemblent contre moi, Sans que je sois coupable, sans que j\'aie péché, ô Éternel!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 4, 'Sans que j\'aie fait aucun mal, Ils accourent, ils se préparent à m\'assaillir. Réveille-toi, viens à moi, et regarde!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 5, 'Toi donc, ô Éternel, Dieu des armées. Dieu d\'Israël, Lève-toi pour châtier toutes les nations; Ne fais grâce à aucun de ces hommes perfides et impies! Pause');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 6, 'Ils reviennent chaque soir; ils hurlent comme des chiens, En parcourant la ville.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 7, 'Leur bouche vomit l\'injure; Leurs paroles blessent comme des épées. Ils disent: «Qui peut nous entendre?»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 8, 'Mais toi, ô Éternel, tu te moques d\'eux; Tu te ris de tous ces orgueilleux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 9, 'O toi qui es ma force, c\'est à toi que je regarde! Car Dieu est ma haute retraite.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 10, 'Le Dieu qui m\'est propice viendra à mon aide. Dieu me fera contempler la ruine de mes ennemis.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 11, 'Ne les anéantis pas tout à fait. De peur que mon peuple n\'oublie leur châtiment. Disperse-les par ta puissance et détruis-les, Seigneur, toi qui es notre bouclier.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 12, 'Chaque parole sortant de leurs lèvres est un nouveau péché. Qu\'ils soient pris au piège de leur propre orgueil. Eux qui ne profèrent que malédictions et que mensonges!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 13, 'Consume-les dans ta fureur, consume-les; Qu\'ils disparaissent à jamais. Et qu\'on sache que le Dieu qui règne en Jacob Domine jusqu\'aux extrémités de la terre! Pause');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 14, 'Qu\'ils reviennent le soir, qu\'ils hurlent comme des chiens En parcourant la ville.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 15, 'Qu\'ils rôdent pour trouver à manger, Et qu\'ils errent sans pouvoir se rassasier!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 16, 'Mais moi, je chanterai ta puissance. Je célébrerai dès le matin ta bonté; Car tu as été ma haute retraite. Mon refuge au jour de la détresse.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 17, 'toi qui es ma force, je chanterai en ton honneur! Car Dieu est ma haute retraite, le Dieu qui m\'est propice.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 1, 'Au maître-chantre. — Sur «Le lys du témoignage».!!- Poème didactique de David, lorsqu\'il fit la guerre aux Syriens de Mésopotamie et aux Syriens de Tsoba, et que Joab revint et défit douze mille Édomites dans la Vallée du Sel. O Dieu, tu nous as rejetés, tu nous as dispersés; Tu t\'es irrité: relève-nous!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 2, 'Tu as fait trembler la terre, tu l\'as déchirée: Répare ses brèches; car elle est ébranlée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 3, 'Tu as fait voir à ton peuple de dures épreuves. Tu nous as abreuvés d\'un vin qui donne le vertige;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 4, 'Mais tu as donné, à ceux qui te craignent, un étendard. Afin qu\'ils se lèvent au nom de la vérité. Pause');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 5, 'Pour que tes bien-aimés soient délivrés. Sauve-nous par ta main droite, et exauce-nous!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 6, 'Dieu l\'a déclaré dans son sanctuaire: «Je triompherai: Sichem sera ma part; Je mesurerai au cordeau la vallée de Succoth;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 7, 'Galaad est à moi; à moi Manassé; Éphraïm est le rempart de ma tête; Juda est mon sceptre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 8, 'Moab est le bassin dans lequel je me lave; Sur Édom je jette ma sandale. Terre des Philistins, pousse des cris en mon honneur!»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 9, 'Qui me conduira dans la ville forte? Qui me mènera jusqu\'au pays d\'Édom?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 10, 'N\'est-ce pas toi, ô Dieu, qui nous avais rejetés. Toi-même, ô Dieu, qui ne sortais plus à la tête de nos armées?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 11, 'Viens à notre secours, Pour que nous puissions échapper à la détresse! Le secours de l\'homme n\'est que vanité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 12, 'Avec Dieu nous accomplirons des exploits. Et c\'est lui qui écrasera nos adversaires.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 1, 'Au maître-chantre. — Avec instruments à cordes. — De David. O Dieu, écoute ma supplication; Sois attentif à ma prière!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 2, 'Des extrémités de la terre, je crie vers toi, le coeur défaillant. Conduis-moi sur le rocher, inaccessible pour moi!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 3, 'Car tu as été pour moi un refuge, Une forte citadelle contre l\'ennemi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 4, 'Je séjournerai dans ta tente à perpétuité; Je me retirerai à l\'abri de tes ailes. Pause');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 5, 'C\'est toi, ô Dieu, qui as entendu mes voeux, Et qui m\'as donné l\'héritage de ceux qui craignent ton nom.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 6, 'Ajoute des jours aux jours du roi; Que ses années durent d\'âge en âge!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 7, 'Qu\'il siège à toujours devant Dieu! Donne-lui ta grâce et ta fidélité pour sauvegarde!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 8, 'Alors, en chantant ton nom à perpétuité. Je m\'acquitterai chaque jour de mes voeux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 1, 'Au maître-chantre. — Selon Jéduthun. — Psaume de David. Mon âme se repose en paix sur Dieu seul; C\'est de lui que vient mon salut.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 2, 'Seul il est mon rocher, mon salut, Ma haute retraite; je ne serai pas beaucoup ébranlé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 3, 'Jusques à quand vous jetterez-vous sur un homme. Pour l\'abattre tous ensemble. Comme un mur qui penche. Comme une clôture qu\'on renverse?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 4, 'Ils ne pensent qu\'à le faire tomber du poste où il s\'est élevé; Ils se plaisent au mensonge. De leur bouche ils bénissent. Mais au fond du coeur ils maudissent. Pause');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 5, 'Oui, sur Dieu seul mon âme se repose en paix; Car mon espoir est en lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 6, 'Seul, il est mon rocher, mon salut. Ma haute retraite: je ne serai point ébranlé!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 7, 'C\'est de Dieu que j\'attends mon salut et ma gloire: Dieu est mon rocher protecteur; mon refuge est en lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 8, 'Peuples, confiez-vous en lui en tout temps! Répandez devant lui votre coeur: Dieu est notre refuge! Pause');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 9, 'Les petits ne sont que néant; Les grands ne sont que mensonge: Placés dans la balance, Ils pèseraient tous ensemble moins que le néant même.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 10, 'Ne mettez pas votre confiance dans la violence; Ne mettez pas un vain espoir dans la rapine. Si vos richesses abondent, N\'y attachez pas votre coeur!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 11, 'Dieu a dit une fois. Et j\'ai entendu sa voix redire encore: «La force appartient à Dieu!»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 12, 'A toi aussi, Seigneur, la miséricorde! Tu rendras à chacun selon ses oeuvres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 1, 'Psaume de David, lorsqu\'il était dans le désert de Juda. Dieu, tu es mon Dieu! Je te cherche dès l\'aurore; Mon âme a soif de toi, ma chair languit après toi. Dans une terre aride, desséchée, sans eau!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 2, 'Aussi t\'ai-je contemplé dans le sanctuaire, Pour voir ta force et ta gloire;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 3, 'Car ta bonté vaut mieux que la vie. Mes lèvres chanteront tes louanges.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 4, 'Oui, je te bénirai toute ma vie; C\'est en invoquant ton nom que j\'élèverai les mains.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 5, 'Mon âme est rassasiée comme de moelle et de graisse. Et c\'est par des chants joyeux Que ma bouche célèbre tes louanges,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 6, 'Quand je me souviens de toi sur ma couche. Et que tu occupes mes pensées pendant les veilles de la nuit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 7, 'Car tu as été mon secours: Aussi entonnerai-je des chants joyeux à l\'ombre de tes ailes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 8, 'Mon âme s\'attache à toi pour te suivre. Et ta main droite me soutient.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 9, 'Ils courent à leur perte, ceux qui en veulent à ma vie. Ils descendront dans les abîmes les plus profonds de la terre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 10, 'Ils seront livrés au tranchant de l\'épée; Ils seront la proie des chacals.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 11, 'Mais le roi se réjouira en Dieu; Tous ceux qui l\'invoquent dans leurs serments Seront dans l\'allégresse, Tandis que la bouche des menteurs sera fermée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 1, 'Au maître-chantre. — Psaume de David. Dieu, écoute ma voix, quand je gémis; Protège ma vie contre l\'ennemi qui m\'épouvante!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 2, 'Mets-moi à l\'abri des complots des méchants, De la foule bruyante des ouvriers d\'iniquité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 3, 'Ils aiguisent leur langue comme une épée; Ils ajustent comme une flèche leur parole amère,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 4, 'Pour tirer en cachette sur l\'innocent. Ils tirent sur lui à l\'improviste: aucune crainte ne les retient.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 5, 'Ils s\'affermissent dans leur mauvais dessein; Ils ne parlent que de tendre des pièges. Ils disent: «Qui nous verra?»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 6, 'Ils ne songent qu\'à commettre des crimes: «Nous voilà prêts, disent-ils; l\'embûche est bien dressée!» Oui, les pensées secrètes, le coeur de l\'homme, sont un abîme.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 7, 'Mais Dieu leur lance un trait; Soudain les voilà frappés!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 8, 'Ils chancellent; leur calomnie retombe sur eux. Tous ceux qui les voient hochent la tête.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 9, 'Les hommes sont tous saisis de crainte; Ils racontent l\'oeuvre de Dieu, Et ils comprennent ce qu\'il a fait.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 10, 'Le juste se réjouira en l\'Éternel, Et il cherchera son refuge en lui. Tous ceux qui ont le coeur droit seront pleins d\'allégresse.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 1, 'Au maître-chantre. — Psaume de David. — Cantique. Une paisible confiance en toi, ô Dieu, Voilà ta louange en Sion; C\'est pour ta gloire Que nous voulons nous acquitter de nos voeux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 2, 'toi qui entends la prière. Toutes les créatures viendront à toi!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 3, 'Le poids des iniquités m\'accable; Mais toi, tu pardonnes nos transgressions.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 4, 'Heureux celui que tu choisis et que tu prends avec toi, Pour le faire habiter dans tes parvis! Nous nous rassasierons des biens de ta maison. Des biens de ton saint temple!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 5, 'Tu nous réponds par les oeuvres redoutables de ta justice, Dieu de notre salut, Espoir des extrémités de la terre et des mers lointaines!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 6, 'C\'est Dieu qui soutient les montagnes par sa force; Il est ceint de puissance.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 7, 'Il apaise le grondement des mers, Le grondement de leurs flots, Et le tumulte des peuples.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 8, 'Ceux qui habitent aux extrémités de la terre Sont remplis de crainte, A la vue de tes prodiges. Tu fais tressaillir d\'allégresse et le Levant et le Couchant.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 9, 'Tu visites la terre, tu l\'arroses, Tu l\'enrichis abondamment. Les ruisseaux de Dieu sont pleins d\'eau. Tu prépares le blé lorsque, pour fertiliser la terre,.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 10, 'Tu en abreuves les sillons, tu en aplanis les mottes. Tu la détrempes par les pluies et tu bénis ses fruits.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 11, 'Tu couronnes l\'année de tes biens, Et, sur sa route, ton char répand l\'abondance.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 12, 'Les pâturages du désert sont abondamment arrosés, Et les collines ont la joie pour parure.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 13, 'Les campagnes se revêtent de troupeaux, Et les vallées se couvrent de froment: Partout des cris et des chants d\'allégresse!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 1, 'Au maître-chantre. — Cantique. — Psaume. Poussez vers Dieu des cris de joie. Vous tous, habitants de la terre!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 2, 'Chantez la gloire de son nom; Louez-le et rendez-lui gloire!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 3, 'Dites à Dieu: «Que tes oeuvres sont redoutables! A cause de la grandeur de ta force. Tes ennemis viendront te flatter.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 4, 'Toute la terre se prosternera devant toi. Elle entonnera tes louanges; Elle célébrera ton nom.» Pause');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 5, 'Venez et voyez les grandes oeuvres de Dieu: Il accomplit les prodiges les plus redoutables Parmi les fils des hommes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 6, 'Il a changé la mer en terre ferme: Dans le fleuve on passait à pied sec; C\'est là que nous nous sommes réjouis en lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 7, 'Il domine éternellement par sa puissance; Ses yeux observent les nations: Que les rebelles ne relèvent pas la tête! Pause');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 8, 'Peuples, bénissez notre Dieu, Et faites entendre le chant de ses louanges;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 9, 'C\'est lui qui nous a conservé la vie, Et il n\'a pas permis que notre pied vînt à chanceler.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 10, 'Car tu nous as éprouvés, ô Dieu; Tu nous as fait passer au creuset comme l\'argent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 11, 'Tu nous avais amenés dans le filet; Tu avais mis un lourd fardeau sur nos reins.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 12, 'Tu avais permis à nos ennemis De passer à cheval sur nos têtes. Nous étions entrés dans le feu et dans l\'eau; Mais tu nous en as retirés pour nous combler de biens.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 13, 'J\'entrerai dans ton temple avec des holocaustes. Et je m\'acquitterai envers toi de mes voeux,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 14, 'Des voeux que mes lèvres ont exprimés. Et que ma bouche a prononcés dans ma détresse.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 15, 'Je t\'offrirai des bêtes grasses en holocauste, Avec la fumée des béliers; J\'immolerai des taureaux et des boucs. Pause');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 16, 'Venez, écoutez, vous tous qui craignez Dieu, Et je raconterai ce qu\'il a fait à mon âme.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 17, 'Mes lèvres l\'ont invoqué. Et ma langue a chanté sa louange.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 18, 'Si j\'avais eu dans le coeur quelque intention coupable, Le Seigneur ne m\'aurait point exaucé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 19, 'Mais Dieu m\'a écouté; Il a prêté l\'oreille à ma voix suppliante.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 20, 'Béni soit Dieu, Qui n\'a point rejeté ma prière, Et qui ne m\'a pas retiré sa miséricorde!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 1, 'Au maître-chantre. — Avec instruments à cordes. — Psaume. — Cantique. Que Dieu ait pitié de nous et nous bénisse! Que l\'éclat de ta face resplendisse parmi nous, Pause');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 2, 'Afin que l\'on connaisse tes desseins sur la terre, Et ton salut parmi toutes les nations.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 3, 'Les peuples te célébreront, ô Dieu; Tous les peuples te célébreront.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 4, 'Les nations se réjouiront et entonneront des chants de joie; Car tu jugeras les peuples avec droiture. Et tu seras sur la terre le conducteur des nations.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 5, 'Les peuples te célébreront, ô Dieu; Oui, tous les peuples te célébreront.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 6, 'La terre a donné son fruit; Dieu, notre Dieu, nous bénira.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 7, 'Oui, Dieu nous bénira. Et toutes les extrémités de la terre le craindront.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 1, 'Au maître-chantre. — Psaume de David. — Cantique. Que Dieu se lève, et ses ennemis seront dispersés; Ceux qui le haïssent fuiront devant sa face;,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 2, 'Comme la fumée se dissipe, tu les dissiperas; Comme la cire fond au feu, Ainsi périront les méchants devant Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 3, 'Mais les justes se réjouiront; Ils triompheront en présence de Dieu; Ils seront transportés d\'allégresse.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 4, 'Chantez à la gloire de Dieu, célébrez son nom. Préparez le chemin A celui dont le char s\'avance à travers les plaines! L\'Éternel est son nom; réjouissez-vous en sa présence!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 5, 'Il est le père des orphelins et le défenseur des veuves, Le Dieu qui réside dans sa demeure sainte.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 6, 'Dieu donne un foyer aux isolés; Il délivre les captifs et les met dans l\'abondance; Mais les rebelles auront pour séjour le désert aride.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 7, 'Dieu, quand tu sortis à la tête de ton peuple, Quand tu t\'avanças dans le désert. Pause');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 8, 'La terre trembla, les cieux se fondirent devant Dieu; Le Sinaï même trembla devant Dieu, le Dieu d\'Israël.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 9, 'Tu fis tomber, ô Dieu, une pluie de bienfaits sur ton héritage: Il était épuisé; tu restauras ses forces.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 10, 'Ton troupeau habita dans ce pays. Que dans ta bonté, ô Dieu, tu avais préparé pour le malheureux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 11, 'Le Seigneur donne un ordre. Aussitôt les messagères de bonnes nouvelles Se réunissent en une troupe nombreuse.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 12, 'Les rois des armées s\'enfuient; ils s\'enfuient. Et celle qui gardait la maison partage le butin.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 13, 'Tandis que vous reposez au milieu des bercails. Les ailes de la colombe se couvrent d\'argent, Et son plumage de reflets d\'or.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 14, 'Quand le Tout-Puissant dispersa les rois, Il y eut sur le Tsalmon comme des flocons de neige.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 15, 'Montagnes de Dieu, montagnes de Basan, Montagnes aux cimes nombreuses, montagnes de Basan,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 16, 'Montagnes aux cimes nombreuses, Pourquoi êtes-vous jalouses De la montagne que Dieu a choisie pour demeure? Oui, l\'Éternel y demeurera toujours.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 17, 'Les chars de Dieu se comptent par vingt mille. Par milliers de milliers. Le Seigneur vient du Sinaï dans son sanctuaire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 18, 'Tu es monté sur la hauteur, tu as emmené des captifs; Tu as reçu les dons des hommes, même ceux des rebelles, Pour établir là ta demeure, ô Éternel Dieu!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 19, 'Béni soit le Seigneur! Chaque jour il porte nos fardeaux, Le Dieu de notre salut. Pause');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 20, 'Dieu est pour nous le Dieu qui nous sauve; C\'est l\'Éternel, le Seigneur, qui délivre de la mort.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 21, 'Oui, Dieu écrasera la tête de ses ennemis. Le crâne chevelu de celui qui se plaît à marcher dans le crime.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 22, 'Le Seigneur a dit: «De Basan je ramènerai mon peuple. Je le ramènerai des profondeurs de la mer,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 23, 'Afin que tu plonges tes pieds dans le sang, Et que la langue de tes chiens ait part Au carnage de l\'ennemi!»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 24, 'On a vu ta marche, ô Dieu, La marche de mon Dieu, de mon Roi, dans le sanctuaire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 25, 'En tête venaient les chanteurs; En arrière, les joueurs d\'instruments; Au milieu, les jeunes filles battant du tambourin.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 26, 'Bénissez Dieu dans vos assemblées; Bénissez le Seigneur, vous, descendants d\'Israël!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 27, 'Voici Benjamin, le plus jeune, qui marche en tête; Puis, les princes de Juda et leur troupe. Les princes de Zabulon et les princes de Nephthali.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 28, 'Ton Dieu a décrété ta puissance. Affermis, ô Dieu, ce que tu as fait pour nous,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 29, 'Du haut de ton palais qui domine Jérusalem! Que les rois t\'offrent des présents!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 30, 'Tance la bête des roseaux, La troupe des taureaux Qu\'entoure la multitude de leurs vassaux, Afin que tous se prosternent en t\'offrant des lingots d\'argent. Disperse les peuples qui veulent la guerre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 31, 'Les grands viendront de l\'Egypte; L\'Ethiopie s\'empressera de tendre les mains vers Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 32, 'Royaumes de la terre, chantez un cantique à la gloire de Dieu! Pause Chantez en l\'honneur du Seigneur,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 33, 'En l\'honneur de celui qui s\'avance. Porté sur les cieux, les cieux éternels! Il fait retentir sa voix, sa voix puissante.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 34, 'Rendez hommage à Dieu! Sa majesté resplendit sur Israël; sa force éclate dans les nuées.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 35, 'Dieu, du fond de tes sanctuaires, tu te rends redoutable! C\'est lui, le Dieu d\'Israël, Qui donne force et puissance à son peuple. Béni soit Dieu!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 1, 'Au maître-chantre. — De David. — Sur «Les lis». Sauve-moi, ô Dieu; Car les eaux menacent ma vie!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 2, 'J\'enfonce dans la fange d\'un gouffre, Où je ne puis prendre pied. Je suis entré dans les eaux profondes; les flots me submergent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 3, 'Je suis las de crier, ma gorge est desséchée; Mes yeux se consument à attendre mon Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 4, 'Ceux qui me haïssent sans motif Sont plus nombreux que les cheveux de ma tête. Ils sont puissants, les ennemis Qui veulent injustement me détruire; Je dois restituer ce que je n\'ai pas ravi!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 5, 'Dieu, tu connais mes égarements. Et mes fautes ne te sont point cachées.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 6, 'Qu\'ils n\'aient pas à rougir à cause de moi. Ceux qui se confient en toi, Seigneur, Éternel des armées! Qu\'ils ne soient pas confus à mon sujet. Ceux qui te recherchent, Dieu d\'Israël!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 7, 'Car c\'est pour toi que je supporte l\'opprobre, Et que la honte a couvert mon visage.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 8, 'Je suis devenu un étranger pour mes frères, Un inconnu pour les fils de ma mère!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 9, 'Car le zèle de ta maison me dévore, Et les outrages de ceux qui t\'outragent sont tombés sur moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 10, 'J\'ai pleuré, j\'ai jeûné. Et l\'on m\'en a fait un opprobre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 11, 'J\'ai pris un sac comme vêtement de deuil, Et je suis devenu leur risée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 12, 'Ceux qui sont assis à la porte de la ville parlent contre moi. Ceux qui boivent des liqueurs enivrantes Me raillent dans leurs chansons.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 13, 'Mais moi, je t\'adresse ma prière, ô Éternel! Voici le moment favorable: Dieu, dans ta grande miséricorde. Réponds-moi, en m\'accordant ton fidèle secours!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 14, 'Retire-moi du bourbier; Ne permets pas que j\'y reste enfoncé. Délivre-moi de mes ennemis et des eaux profondes!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 15, 'Ne me laisse pas submerger par les flots en fureur, Ni engloutir par l\'abîme, Et que le gouffre béant ne se referme pas sur moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 16, 'Réponds-moi, ô Éternel; car ta grâce est bienfaisante. Dans tes compassions infinies, tourne-toi vers moi!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 17, 'Ne cache pas ta face à ton serviteur, Quand il est dans la détresse. Hâte-toi de me répondre!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 18, 'Approche-toi de mon âme et sauve-la; Délivre-moi, pour couvrir mes ennemis de confusion.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 19, 'Toi, tu vois mon opprobre, ma honte, mon ignominie: Mes oppresseurs sont tous devant tes yeux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 20, 'Leurs outrages m\'ont brisé le coeur, et je suis anéanti. J\'attendais un ami qui eût pitié de moi, mais en vain; Des consolateurs, mais je n\'en ai pas trouvé!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 21, 'Mes adversaires mettent du fiel dans ma nourriture, Et pour apaiser ma soif, ils m\'abreuvent de vinaigre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 22, 'Que la table, dressée devant eux, leur soit un piège, Un filet au sein de leur sécurité!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 23, 'Que leurs yeux s\'obscurcissent et ne voient plus la lumière! Fais chanceler continuellement leurs pas!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 24, 'Répands sur eux ton indignation, Et que l\'ardeur de ton courroux les atteigne!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 25, 'Que leur demeure soit déserte, Et que personne n\'habite dans leurs tentes!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 26, 'Car ils persécutent celui que tu as frappé; Ils se plaisent à railler les souffrances de ceux que tu as blessés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 27, 'Qu\'ils commettent iniquités sur iniquités, Et qu\'ils n\'aient point de part à ton salut!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 28, 'Qu\'ils soient effacés du livre de vie. Et qu\'ils ne soient pas inscrits au nombre des justes!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 29, 'Pour moi, je suis affligé et je souffre. Que ton secours, ô Dieu, soit pour moi une haute retraite!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 30, 'Je louerai le nom de Dieu dans mes cantiques; Je le glorifierai dans mes actions de grâces;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 31, 'Et cela sera plus agréable à l\'Éternel Que le sacrifice d\'un boeuf aux cornes et aux sabots vigoureux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 32, 'Les humbles verront ma délivrance, et ils se réjouiront. Vous qui recherchez Dieu, que votre coeur revive!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 33, 'Car l\'Eternel écoute les misérables, Et il ne dédaigne point son peuple captif.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 34, 'Que les cieux et la terre entonnent ses louanges. Ainsi que les mers et tout ce qui vit dans leurs eaux!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 35, 'Car Dieu sauvera Sion et rebâtira les villes de Juda: Nos enfants viendront s\'y établir. Et ils en posséderont le territoire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 36, 'La postérité de ses serviteurs aura ce pays pour héritage; Ceux qui aiment son nom y établiront leur demeure.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 1, 'Au maître-chantre. — De David. — Pour servir de mémorial. O Dieu, daigne me délivrer! Éternel, accours à mon aide!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 2, 'Qu\'ils soient confus et qu\'ils rougissent, Ceux qui en veulent à ma vie. Qu\'ils reculent et soient couverts d\'ignominie, Ceux qui souhaitent ma ruine!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 3, 'Que le juste châtiment de leur honte Fasse reculer ceux qui disent: «Ah! Ah!»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 4, 'Que tous ceux qui te recherchent, Tressaillent d\'allégresse et se réjouissent en toi! Et que ceux qui espèrent en ton secours Disent sans cesse: «Gloire soit à Dieu!»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 5, 'Je suis affligé et misérable: O Dieu, hâte-toi de venir à mon secours! Tu es mon aide et mon libérateur: Éternel, ne tarde pas!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 1, 'J\'ai cherché en toi mon refuge, ô Éternel; Que mon espoir ne soit jamais déçu!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 2, 'Dans ta justice, délivre-moi, retire-moi du danger; Incline ton oreille vers moi, et sauve-moi!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 3, 'Sois mon rocher, la retraite Où je puisse me réfugier en tout temps! Tu as donné des ordres pour que je sois sauvé; Car tu es mon rocher et ma forteresse.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 4, 'Mon Dieu, délivre-moi des mains du méchant, Des mains de l\'homme inique et de l\'oppresseur!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 5, 'Car tu es mon espérance, ô Seigneur, Éternel! C\'est en toi que je me confie depuis ma jeunesse.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 6, 'Je me suis appuyé sur toi dès ma naissance; C\'est toi qui m\'as tiré du sein de ma mère! Tu es l\'objet de mes louanges en tout temps.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 7, 'Je suis, pour plusieurs, un sujet d\'étonnement; Mais toi, tu es ma forte citadelle.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 8, 'Que ma bouche soit pleine de ta louange. Et qu\'elle te glorifie chaque jour!»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 9, 'Ne me rejette pas au temps de ma vieillesse; Quand ma force s\'en va, ne m\'abandonne point!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 10, 'Car mes ennemis parlent de moi; Ceux qui guettent ma vie conspirent ensemble,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 11, 'Disant: «Dieu l\'a abandonné; Poursuivez-le, saisissez-le; Car il n\'y a personne pour le délivrer!»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 12, 'Dieu! Ne t\'éloigne pas de moi! Mon Dieu, accours à mon aide!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 13, 'Que ceux qui en veulent à ma vie Rougissent de honte et qu\'ils périssent! Que ceux qui cherchent ma perte Soient couverts d\'opprobre et de confusion!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 14, 'Mais moi, j\'espérerai en tout temps, Et je te louerai toujours davantage.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 15, 'Ma bouche célébrera chaque jour Ta justice et tes délivrances. Sans jamais parvenir à énumérer tes bienfaits.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 16, 'Je raconterai partout tes grandes oeuvres, Seigneur, Éternel! C\'est ta justice seule que je célébrerai.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 17, 'Dieu, tu m\'as instruit dès ma jeunesse. Et jusqu\'à ce jour j\'ai fait connaître tes oeuvres merveilleuses,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 18, 'C\'est pourquoi, jusqu\'à la vieillesse. Jusqu\'à la blanche vieillesse, Dieu, ne m\'abandonne pas, Afin que je révèle la vigueur de ton bras à la génération nouvelle, Et ta puissance à tous ceux qui naîtront!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 19, 'Ta justice, ô Dieu, atteint jusqu\'au ciel! Tu as accompli de grandes oeuvres. Dieu, qui est semblable à toi?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 20, 'Après m\'avoir fait passer par des détresses Et des maux sans nombre. Tu m\'as de nouveau rendu la vie, Et tu m\'as fait remonter des abîmes de la terre!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 21, 'Tu accroîtras ma grandeur, Et tu me consoleras encore.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 22, 'Aussi, je te célébrerai sur les cordes de la lyre; Je chanterai ta fidélité, ô mon Dieu! Je psalmodierai en ton honneur sur la harpe, ô Saint d\'Israël!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 23, 'Mes lèvres, et mon âme que tu as rachetée, Entonneront des chants de joie. Quand je psalmodierai à ta gloire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 24, 'Ma langue aussi, chaque jour, redira ta justice; Car ils seront confus, ils rougiront. Ceux qui souhaitent ma ruine!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 1, 'De Salomon. O Dieu, confie au roi le soin d\'exercer en ton nom la justice. Et donne au fils du roi ton esprit d\'équité!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 2, 'Qu\'il juge ton peuple avec justice, Et tes humbles serviteurs avec droiture!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 3, 'Que les montagnes et les coteaux Procurent au peuple les fruits de la paix, Sous le règne de la justice!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 4, 'Il fera droit aux opprimés de son peuple; Il portera secours aux enfants du pauvre. Et il écrasera l\'oppresseur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 5, 'On te craindra tant que durera le soleil, Tant que luira la lune, d\'âge en âge.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 6, 'Le roi sera semblable à la pluie Qui tombe sur la prairie fraîchement coupée. Semblable à une ondée qui arrose la terre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 7, 'Sous son règne, le juste prospérera Au sein d\'une paix profonde, tant que la lune répandra sa clarté.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 8, 'Il dominera d\'une mer à l\'autre, Depuis l\'Euphrate jusqu\'aux extrémités de la terre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 9, 'Devant lui se courberont les habitants du désert, Et ses ennemis lécheront la poussière.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 10, 'Les rois de Tarsis et des îles lui offriront des présents; Les rois de Saba et de Séba lui apporteront leurs tributs.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 11, 'Tous les rois se prosterneront devant lui; Toutes les nations le serviront.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 12, 'Car il délivrera le malheureux qui l\'implore, Et l\'affligé qui n\'a pas d\'appui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 13, 'Il aura pitié du faible et de l\'indigent; Il sauvera l\'âme des malheureux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 14, 'Il rachètera leur âme de l\'oppression et de la violence. Et leur sang aura un grand prix à ses yeux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 15, 'Que le roi vive et qu\'on lui donne de l\'or de Saba! Qu\'on prie pour lui, en tout temps. Qu\'on le bénisse chaque jour!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 16, 'Que les blés abondent dans le pays. Sur le sommet des montagnes! Que leurs épis ondoient comme le Liban! Que la population des villes fleurisse comme l\'herbe de la terre!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 17, 'Que son nom subsiste à toujours! Que son nom se perpétue tant que brillera le soleil! Que l\'on se bénisse mutuellement en son nom; Que toutes les nations le proclament heureux!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 18, 'BÉNI SOIT l\'Éternel Dieu, le Dieu d\'Israël, Qui seul accomplit des oeuvres merveilleuses!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 19, 'Béni soit a jamais son nom glorieux. Et que toute la terre soit remplie de sa gloire! Amen! Amen!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 20, 'Fin des prières de David, fils d\'Isaï.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 1, 'Psaume d\'Asaph. Oui, Dieu est bon pour Israël, Pour ceux qui ont le coeur pur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 2, 'Cependant, mes pieds ont failli broncher: Il s\'en est fallu de peu que j\'aie glissé!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 3, 'En effet, j\'ai porté envie aux orgueilleux, Quand j\'ai vu la prospérité des méchants!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 4, 'Car ils sont exempts de souffrance; Leur corps demeure vigoureux et robuste.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 5, 'Ils n\'ont aucune part aux peines des mortels; Ils ne sont point frappés avec les autres humains.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 6, 'C\'est pourquoi, ils se parent d\'orgueil comme d\'un collier; La violence les couvre comme un vêtement.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 7, 'Ils sont bouffis de graisse, pleins d\'iniquité, Et leur coeur déborde de mauvaises pensées.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 8, 'Ils ricanent, ils se vantent méchamment de leurs violences; Leurs paroles sont hautaines.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 9, 'Leur bouche s\'élève contre le ciel, Et leur langue sème la calomnie sur la terre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 10, 'Aussi attirent-ils à leur cause une foule de gens Qui boivent avidement leurs paroles,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 11, 'Et qui disent: «Comment le Dieu fort pourrait-il savoir? Comment le Très-Haut connaîtrait-il?»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 12, 'Tels sont les méchants: Toujours heureux, ils amassent des richesses.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 13, 'C\'est donc en vain que j\'ai gardé mon coeur pur, Et que j\'ai lavé mes mains dans l\'innocence;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 14, 'Car je suis frappé tous les jours, Et le châtiment tombe chaque matin sur moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 15, 'Si j\'avais dit: «Je parlerai comme eux» — Alors, j\'aurais été infidèle à la race de tes enfants.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 16, 'J\'ai donc cherché à comprendre ces choses; Mais la tâche a été trop pénible pour moi,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 17, 'Jusqu\'au moment où je suis entré Dans les sanctuaires du Dieu fort, Et où j\'ai fait attention à la fin de ces gens-là.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 18, 'Oui, tu les mets sur un terrain glissant; Tu les fais tomber, et ils s\'écroulent!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 19, 'Comme ils sont détruits en un moment. Enlevés et consumés par une destruction soudaine!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 20, 'Tel un songe, quand on s\'éveille. Ainsi, Seigneur, quand tu te lèves, Tu les dissipes comme de vains fantômes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 21, 'Quand l\'amertume remplissait mon coeur, Et que je me tourmentais en moi-même,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 22, 'Alors j\'étais sans raison et sans intelligence; J\'étais à tes yeux comme un animal stupide.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 23, 'Cependant, je resterai toujours avec toi: Tu m\'as pris par la main droite.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 24, 'Tu me guideras par ta sagesse. Et puis, tu m\'introduiras dans la gloire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 25, 'Quel autre que toi ai-je au ciel? Sur la terre aussi, je ne prends plaisir qu\'en toi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 26, 'Quand même ma chair et mon coeur seraient consumés, Dieu est le rocher de mon coeur, et mon partage pour toujours.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 27, 'Oui, ceux qui s\'éloignent de toi périront; Tu détruis tous ceux qui se détournent de toi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 28, 'Pour moi, m\'approcher de Dieu, c\'est mon bonheur; Je mets ma confiance dans le Seigneur, l\'Éternel, Afin de raconter toutes ses oeuvres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 1, 'Hymne d\'Asaph. Pourquoi, ô Dieu, persistes-tu à nous rejeter? Pourquoi ta colère s\'enflamme-t-elle Contre le troupeau dont tu es le berger?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 2, 'Souviens-toi de ton peuple, que tu as acquis autrefois, Et que tu as racheté pour faire de lui la nation qui t\'appartient. Souviens-toi de cette montagne de Sion, Dont tu as fait ta demeure!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 3, 'Dirige tes pas vers ces lieux toujours en ruines: L\'ennemi a tout détruit dans le sanctuaire!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 4, 'Tes adversaires ont rugi au milieu de tes parvis; Ils y ont mis pour signes leurs emblèmes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 5, 'On les voit pareils à des gens qui lèvent la cognée Dans une épaisse forêt.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 6, 'Déjà, ils ont brisé toutes les sculptures du temple, A coups de haches et de marteaux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 7, 'Ils ont mis le feu à ton sanctuaire; Ils ont profané, jeté à terre la demeure de ton nom.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 8, 'Ils ont dit en leur coeur: «Saccageons tout à la fois!» Ils ont brûlé dans le pays tous les lieux Où se rassemble le peuple de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 9, 'Nous ne voyons plus nos emblèmes; Il n\'y a plus de prophète, Ni personne parmi nous qui sache jusques à quand.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 10, 'Jusques à quand, ô Dieu, l\'adversaire vomira-t-il l\'outrage? L\'ennemi blasphémera-t-il toujours ton nom?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 11, 'Pourquoi retiens-tu ta main, ta main droite? Tire-la de ton sein, et anéantis l\'adversaire!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 12, 'Mais, de tout temps. Dieu est mon roi. Celui qui opère des délivrances sur toute la terre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 13, 'Oui, c\'est toi qui, par ta puissance, as fendu la mer. Toi qui as brisé la tête des monstres sur les eaux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 14, 'C\'est toi qui écrasas la tête du Léviathan, Qui le donnas en pâture aux habitants du désert.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 15, 'C\'est toi qui fis jaillir des sources et des ruisseaux. Toi qui mis à sec les fleuves intarissables.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 16, 'A toi est le jour, à toi aussi la nuit; Tu as créé la lumière et le soleil.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 17, 'C\'est toi qui as fixé toutes les limites de la terre. L\'été et l\'hiver sont ton oeuvre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 18, 'Rappelle-toi que l\'ennemi lance l\'outrage, ô Éternel; Un peuple insensé blasphème ton nom!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 19, 'Ne livre pas aux bêtes sauvages la vie de ta tourterelle. N\'oublie pas pour toujours ton malheureux troupeau.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 20, 'Souviens-toi de ton alliance; Car les lieux ténébreux de la terre Sont pleins de repaires de crimes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 21, 'Que l\'opprimé ne s\'en retourne pas couvert de honte; Que le misérable et le pauvre puissent louer ton nom!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 22, 'Lève-toi, ô Dieu, défends ta cause! Souviens-toi des affronts que l\'insensé t\'inflige tous les jours.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 23, 'N\'oublie pas les cris de tes adversaires, La clameur toujours grandissante De ceux qui s\'élèvent contre toi!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 1, 'Au maître-chantre. — «Ne détruis pas». — Psaume d\'Asaph. — Cantique. Nous te louons, ô Dieu, nous célébrons tes louanges. Et ton nom est présent parmi nous. Tous racontent tes merveilles.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 2, '«Quand viendra le jour fixé par moi, dit le Seigneur, Je jugerai avec équité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 3, 'La terre chancelait avec tous ses habitants; Moi, j\'en affermis les colonnes.» Pause');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 4, 'Je dis aux orgueilleux: «Ne vous enorgueillissez pas. Et aux méchants: «Ne levez pas la tête;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 5, 'Ne levez pas si haut votre tête; Ne parlez pas avec insolence en raidissant le cou!»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 6, 'Car ce n\'est pas de l\'Orient, ni de l\'Occident, Ni du désert, que vient la prospérité;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 7, 'Mais c\'est Dieu qui juge: Il abaisse l\'un, et il élève l\'autre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 8, 'L\'Éternel tient dans sa main une coupe, Où écume un vin mélangé d\'aromates; Il verse à boire à tous les méchants de la terre: Ils videront la coupe jusqu\'à la lie!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 9, 'Voilà ce que je ne cesserai pas de redire. En chantant à la gloire du Dieu de Jacob.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 10, 'Je briserai entièrement la puissance des méchants; Mais le juste verra grandir sa puissance.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 1, 'Au maître-chantre. — Avec instruments à cordes. — Psaume d\'Asaph — Cantique. Dieu s\'est fait connaître en Juda; Son nom est grand en Israël.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 2, 'Son tabernacle est à Salem, Et sa résidence à Sion.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 3, 'Là il a brisé les flèches rapides comme l\'éclair. Le bouclier, le glaive et les armes de guerre. Pause');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 4, 'O Tout-Puissant, tu surpasses en majesté Les conquérants les plus glorieux!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 5, 'Ils ont été dépouillés, les hommes au coeur fort; Et tous ces hommes vaillants n\'ont plus retrouvé La vigueur de leurs bras.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 6, 'A ta seule menace, ô Dieu de Jacob, Conducteurs de chars et coursiers ont été frappés de torpeur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 7, 'Mais toi, tu es redoutable! Qui peut tenir devant toi, dès que ta colère éclate?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 8, 'Du haut des cieux, tu fais entendre; La terre est effrayée, et elle se tait,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 9, 'Quand tu te lèves, ô Dieu, pour juger. Pour délivrer tous les opprimés de la terre. Pause');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 10, 'La fureur même de l\'homme tourne à ta louange, Et ton propre courroux est le glaive dont tu restes armé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 11, 'Faites des voeux, acquittez-les envers l\'Éternel, votre Dieu; Que tous les peuples d\'alentour viennent offrir Des présents à ce Dieu Redoutable!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 12, 'Dieu abat l\'orgueil des princes; Il est redouté par les rois de la terre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 1, 'Au maître-chantre. — Selon Jéduthun. — Psaume d\'Asaph. Ma voix s\'adresse à Dieu, et je crie; Ma voix s\'adresse à Dieu, afin qu\'il m\'écoute.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 2, 'Au jour de ma détresse, je cherche le Seigneur; La nuit, ma main est tendue vers lui et ne se lasse point; Mon âme refuse d\'être consolée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 3, 'Je me souviens de Dieu, et je gémis; Je médite, et mon esprit est abattu. Pause');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 4, 'Tu tiens mes paupières ouvertes; Je suis troublé, je ne puis parler.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 5, 'Je pense aux jours d\'autrefois. Aux années des temps passés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 6, 'Je me souviens de mes cantiques pendant la nuit; Je médite en mon coeur. Mon esprit se demande:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 7, '«Le Seigneur nous rejettera-t-il éternellement? Ne sera-t-il plus jamais propice?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 8, 'Sa bonté est-elle à jamais épuisée? Sa promesse est-elle anéantie pour toujours?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 9, 'Dieu a-t-il oublié d\'avoir pitié? A-t-il, dans sa colère, mis un terme à ses compassions?» Pause');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 10, 'Puis je me dis: «Voici la cause de ma souffrance: C\'est que la main droite du Très-Haut a changé»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 11, 'Je me rappellerai donc les actions glorieuses de l\'Éternel. Oui, je me souviendrai de tes merveilles d\'autrefois;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 12, 'Je penserai à toutes tes oeuvres, Et j\'évoquerai le souvenir de tes prodiges!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 13, 'Ô Dieu, tes voies sont saintes! Quel Dieu est grand comme notre Dieu?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 14, 'Tu es le Dieu qui accomplit des merveilles; Tu as fait connaître parmi les peuples ta puissance.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 15, 'Par ton bras, tu as délivré ton peuple, Les enfants de Jacob et de Joseph. Pause');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 16, 'Les eaux t\'ont vu, ô Dieu! Les eaux t\'ont vu, elles ont frémi; Même les abîmes furent ébranlés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 17, 'Les nuées se répandirent en torrents d\'eau; Les nuages lancèrent la foudre Et tes flèches volèrent de toutes parts.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 18, 'Ton tonnerre gronda dans le tourbillon; Les éclairs illuminèrent le monde; La terre fut ébranlée et trembla.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 19, 'Tu te fis un chemin dans la mer, Un sentier dans les grandes eaux, Sans qu\'on pût reconnaître tes traces.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 20, 'Tu as conduit ton peuple comme un troupeau, Par la main de Moïse et d\'Aaron.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 1, 'Hymne d\'Asaph. Mon peuple, écoute mes instructions! Prête l\'oreille aux paroles de ma bouche!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 2, 'J\'ouvrirai ma bouche pour prononcer des sentences; Je dirai les mystères des temps anciens.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 3, 'Ce que nous avons entendu et appris à connaître. Ce que nos pères nous ont raconté,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 4, 'Nous ne le cacherons point à leurs descendants. Nous raconterons à la génération future les oeuvres glorieuses de l\'Éternel, Et sa puissance, et les merveilles qu\'il a accomplies.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 5, 'Il se fit de Jacob le dépositaire de ses révélations; Il établit en Israël une loi. Qu\'il ordonna à nos pères d\'enseigner à leurs enfants,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 6, 'Pour qu\'elle fût connue de la génération suivante, Des enfants qui naîtraient. Et qui viendraient à leur tour la raconter à leurs enfants.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 7, 'Ils apprendraient ainsi à mettre en Dieu leur confiance, A ne pas oublier les oeuvres du Dieu fort, A garder ses commandements,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 8, 'Et à ne pas devenir, comme leurs pères. Une génération indocile et rebelle. Une génération au coeur inconstant. Et dont l\'esprit fut infidèle à Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 9, 'Les fils d\'Éphraïm, archers habiles à lancer la flèche. Ont tourné le dos le jour du combat.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 10, 'Ils n\'ont point observé l\'alliance de Dieu, Et ils ont refusé de suivre sa loi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 11, 'Ils ont oublié ses oeuvres. Et les prodiges dont il les avait rendus témoins.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 12, 'En présence de leurs pères, il avait accompli des merveilles Dans le pays d\'Egypte, dans les campagnes de Tsoan.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 13, 'Il entr\'ouvrit la mer pour leur livrer passage; Il dressa les eaux, pareilles à une digue.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 14, 'Il conduisit son peuple, le jour, par la nuée, Et toute la nuit par l\'éclat du feu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 15, 'Il fendit des rochers dans le désert, Et il en fit couler des torrents pour le désaltérer.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 16, 'De la pierre, il fit jaillir des ruisseaux; Il en fit sortir des eaux, abondantes comme des fleuves.,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 17, 'Mais ils continuèrent à pécher contre lui, A se révolter dans le désert contre le Très-Haut.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 18, 'Ils tentèrent Dieu dans leur coeur. En demandant une nourriture conforme à leur désir.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 19, 'Ils parlèrent contre Dieu, Et ils dirent: «Dieu pourrait-il Dresser une table dans le désert?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 20, 'Voici qu\'il a frappé le rocher, et les eaux ont coulé, Et des torrents se sont répandus. Mais pourra-t-il donner du pain. Procurer de la viande à son peuple?»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 21, 'L\'Éternel entendit ces murmures, et il en fut indigné; Son brûlant courroux s\'alluma contre Jacob; Sa colère s\'éleva contre Israël,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 22, 'Parce qu\'ils n\'avaient pas cru en Dieu Et qu\'ils ne s\'étaient pas confiés en son secours.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 23, 'Alors il donna ses ordres aux nuées d\'en haut, Et il ouvrit les portes des cieux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 24, 'Il fit pleuvoir sur eux la manne pour les nourrir, Et il leur donna le froment des cieux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 25, 'Tous mangèrent le pain des forts; Il leur envoya des vivres à satiété.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 26, 'Il fit souffler le vent d\'Orient dans les cieux. Et il fit lever par sa puissance le vent du Midi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 27, 'Il fit pleuvoir sur eux de la chair, comme de la poussière. Et des oiseaux, nombreux comme le sable de la mer.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 28, 'Il les fit tomber au milieu de leur camp, Et tout autour de leurs tentes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 29, 'Ils mangèrent et se rassasièrent abondamment; Il leur accorda tout ce qu\'ils avaient désiré.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 30, 'Ils avaient à peine assouvi leur convoitise, La nourriture était encore dans leur bouche,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 31, 'Que la colère de Dieu s\'éleva contre eux: Il fit périr les hommes les plus robustes. Et il abattit l\'élite d\'Israël.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 32, 'Cependant ils péchèrent encore contre Dieu, Et ils ne se laissèrent pas convaincre Par ses oeuvres merveilleuses.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 33, 'Alors il fit disparaître leurs jours comme une ombre: Il emporta leurs années dans une ruine soudaine.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 34, 'Quand il les faisait mourir, ils le recherchaient; Ils revenaient et s\'empressaient de se tourner vers Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 35, 'Ils se souvenaient que Dieu était leur rocher, Et le Dieu Très-Haut leur rédempteur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 36, 'Mais leurs lèvres le trompaient, Et leur langue lui mentait.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 37, 'Leur coeur ne lui était pas fermement attaché, Et ils n\'étaient pas fidèles à son alliance.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 38, 'Mais lui, plein de compassion, pardonnait aux pécheurs Et il ne les détruisait point. Il retint souvent sa colère Et il ne laissa pas se déchaîner son courroux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 39, 'Il se souvint qu\'ils n\'étaient que chair, Un souffle qui passe et ne revient plus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 40, 'Que de fois ils se révoltèrent contre lui dans le désert, Et l\'irritèrent dans la solitude!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 41, 'Ils recommencèrent à tenter Dieu, Et à offenser le Saint d\'Israël.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 42, 'Ils ne se souvinrent plus de ce qu\'avait accompli sa main, Le jour où il les délivra de l\'oppresseur,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 43, 'Quand il fit éclater ses prodiges parmi les Égyptiens, Et ses miracles dans les campagnes de Tsoan.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 44, 'Il changea leurs fleuves en sang. Et ils ne purent plus boire à leurs ruisseaux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 45, 'Il envoya contre eux des moustiques qui les dévoraient. Et des grenouilles qui infectaient le pays.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 46, 'Il abandonna leurs récoltes aux sauterelles. Et le fruit de leur travail à leurs essaims.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 47, 'Il fit périr leurs vignes par la grêle, Et leurs sycomores par la gelée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 48, 'Il livra leur bétail à la grêle, Et leurs troupeaux à la foudre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 49, 'Il déchaîna contre eux l\'ardeur de son courroux, La fureur, l\'indignation, la colère. Toute une armée d\'anges de malheur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 50, 'Il donna libre cours à sa colère, Et, loin de les préserver de la mort, Il livra leur vie à la destruction.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 51, 'Il frappa tous les premiers-nés de l\'Egypte, Ces prémices de la virilité dans les tentes de Gham,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 52, 'Puis il emmena son peuple comme un troupeau de brebis; Il le conduisit comme un troupeau à travers le désert.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 53, 'Il dirigea les pas des Israélites, Les préservant de tout danger et de toute crainte. Tandis que la mer engloutissait leurs ennemis.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 54, 'Il les fit parvenir jusqu\'à sa frontière sainte, Jusqu\'à la montagne que sa main droite a conquise.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 55, 'Il chassa des nations devant eux; Il leur en partagea le territoire par le sort, Et il fit habiter les tribus d\'Israël sous les tentes de l\'ennemi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 56, 'Mais les Israélites tentèrent le Dieu Très-Haut; Ils se révoltèrent contre lui, Et ils n\'observèrent pas ses commandements.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 57, 'Ils firent défection et furent infidèles comme leurs pères; Ils se détournèrent, pareils à un arc perfide.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 58, 'Ils l\'irritèrent par le culte des hauts-lieux; Et ils excitèrent sa jalousie par leurs idoles.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 59, 'A cette vue, Dieu fut indigné; Il prit Israël en profonde aversion.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 60, 'Il abandonna le tabernacle de Silo, La tente dont il avait fait sa demeure parmi les hommes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 61, 'Il laissa emmener en captivité le siège de sa puissance; Il livra sa gloire aux mains de l\'ennemi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 62, 'Il abandonna son peuple à l\'épée, Et s\'irrita contre son héritage.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 63, 'Le feu dévora ses jeunes gens. Et ses vierges furent privées de chants nuptiaux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 64, 'Ses sacrificateurs tombèrent sous les coups de l\'épée. Et ses veuves ne purent pas pleurer les morts.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 65, 'Alors le Seigneur se réveilla, Comme un homme qui vient de dormir. Comme un guerrier à qui le vin ferait pousser des cris de joie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 66, 'Il refoula ses adversaires; Il leur infligea un opprobre éternel.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 67, 'Mais il prit en aversion la tente de Joseph, Et il répudia la tribu d\'Éphraïm.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 68, 'Il choisit la tribu de Juda, La montagne de Sion qu\'il chérit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 69, 'Il y bâtit son sanctuaire, indestructible comme les cieux, Et comme la terre, dont il a posé les fondements pour l\'éternité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 70, 'Il choisit David, son serviteur; Il le prit dans les bergeries.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 71, 'Il alla le chercher auprès des brebis qui allaitent. Pour faire de lui le berger de Jacob, son peuple. Et d\'Israël, son héritage.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 72, 'Ainsi David fut pour eux un berger au coeur intègre. Et il les conduisit d\'une main prudente.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 1, 'Psaume d\'Asaph. Dieu, les nations ont envahi ton héritage; Elles ont profané ton saint temple, Elles ont mis Jérusalem en ruines!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 2, 'Elles ont donné les cadavres de tes serviteurs En pâture aux oiseaux du ciel, La chair de tes fidèles aux bêtes de la terre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 3, 'Elles ont répandu leur sang comme de l\'eau, Autour de Jérusalem, Sans qu\'il y eût personne pour les ensevelir.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 4, 'Nous avons été pour nos voisins un objet de mépris, La risée et le jouet de ceux qui nous entourent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 5, 'Jusques à quand, ô Éternel, t\'irriteras-tu sans relâche. Et ta jalousie brûlera-t-elle comme la flamme?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 6, 'Répands ton courroux sur les nations Qui ne te connaissent pas, Sur les royaumes qui n\'invoquent pas ton nom!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 7, 'Car ils ont dévoré Jacob, Ils ont désolé sa demeure.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 8, 'Ne nous tiens pas compte de nos iniquités passées. Hâte-toi! Que ta compassion nous vienne en aide! Nous sommes extrêmement misérables!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 9, 'Aide-nous, ô Dieu de notre salut, pour la gloire de ton nom! Délivre-nous! Pardonne nos péchés pour l\'amour de ton nom!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 10, 'Pourquoi les nations diraient-elles: «Où est leur Dieu?» Fais éclater à nos yeux ta vengeance contre les nations Qui ont répandu le sang de tes serviteurs!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 11, 'Que le gémissement des captifs parvienne jusqu\'à toi! Par la force de ton bras, sauve ceux qui sont voués à la mort!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 12, 'Fais retomber sept fois sur la tête de nos voisins, L\'outrage qu\'ils t\'ont infligé, ô Seigneur!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 13, 'Mais nous, ton peuple, le troupeau dont tu es le berger. Nous te célébrerons à perpétuité. D\'âge en âge, nous redirons tes louanges.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 1, 'Au maître-chantre. — Sur «Les lis rendent témoignage». — Psaume d\'Asaph. Prête l\'oreille, berger d\'Israël! Toi qui conduis Joseph comme un troupeau. Toi dont le trône est au-dessus des chérubins, Fais rayonner ta splendeur!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 2, 'Devant Éphraïm, Benjamin et Manassé, réveille ta puissance, Et viens nous sauver.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 3, 'Dieu, relève-nous; Fais resplendir ta face, et nous serons sauvés!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 4, 'Éternel, Dieu des armées, Jusques à quand répondras-tu par la colère A la prière de ton peuple?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 5, 'Tu nous fais manger un pain trempé de nos pleurs; Tu nous abreuves sans mesure de nos larmes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 6, 'Tu nous livres aux outrages de nos voisins, Et nos ennemis se raillent de nous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 7, 'Dieu des armées, relève-nous; Fais resplendir ta face, et nous serons sauves!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 8, 'Tu tiras de l\'Egypte une vigne, Et, pour la planter, tu chassas des nations.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 9, 'Tu déblayas le sol devant elle; Elle jeta ses racines et couvrit la terre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 10, 'Les montagnes furent couvertes de son ombre. Et ses rameaux ombrageaient les cèdres de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 11, 'Elle étendait ses pampres jusqu\'à la mer, Et ses rejetons jusqu\'au fleuve.,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 12, 'Pourquoi as-tu rompu ses clôtures. En sorte que tous les passants la dépouillent,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 13, 'Que le sanglier des forêts la dévaste. Et que les bêtes des champs en font leur pâture?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 14, 'Dieu des armées, reviens! Regarde des cieux, vois, et visite cette vigne!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 15, 'Protège le cep que ta main droite a planté, Et le rejeton que tu t\'es choisi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 16, 'Ta vigne est brûlée; elle est saccagée; Tout périt devant l\'éclat de ton courroux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 17, 'Étends ta protection sur le peuple Que ta main droite a choisi, Sur les fils des hommes que tu as élus!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 18, 'Alors, nous ne nous détournerons plus de toi. Rends-nous la vie, et nous invoquerons ton nom.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 19, 'Éternel, Dieu des armées, relève-nous! Fais resplendir ta face, et nous serons sauvés!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 1, 'Au maître-chantre. — D\'Asaph. — Sur la Guittith. Chantez avec allégresse en l\'honneur de Dieu, notre force; Jetez des cris de joie à la gloire du Dieu de Jacob!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 2, 'Entonnez un cantique, faites résonner le tambourin, La douce harpe, avec la lyre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 3, 'Sonnez de la trompette, à la nouvelle lune, A la pleine lune, le jour de notre fête;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 4, 'Car c\'est une loi pour Israël, Un commandement du Dieu de Jacob.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 5, 'C\'est la règle qu\'il établit parmi les fils de Joseph, Quand il exerça ses jugements contre le pays d\'Egypte. J\'entendis alors un langage que je ne connaissais pas:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 6, '«J\'ai déchargé de son fardeau ton épaule; Tes mains ne sont plus asservies à de durs labeurs.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 7, 'Dans ta détresse, tu as crié et je t\'ai délivré. Du sein de la tempête dont j\'étais enveloppé, J\'ai exaucé tes prières; Je t\'ai éprouvé aux eaux de Mériba. Pause');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 8, 'Écoute, ô mon peuple, et je t\'instruirai! O Israël, si tu m\'écoutais!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 9, 'Qu\'il n\'y ait au milieu de toi aucun dieu étranger; Ne te prosterne pas devant un autre dieu!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 10, 'Je suis l\'Éternel, ton Dieu: Je t\'ai fait remonter du pays d\'Egypte. Ouvre ta bouche, et je la remplirai.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 11, 'Mais mon peuple n\'a pas écouté ma voix; Les enfants d\'Israël n\'ont pas voulu m\'obéir.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 12, 'Alors je les ai abandonnés à la dureté de leur coeur, Et ils ont marché au gré de leurs désirs.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 13, 'Oh! si mon peuple voulait m\'écouter, Si les enfants d\'Israël marchaient dans mes voies!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 14, 'J\'aurais bientôt abattu leurs ennemis; Je ferais peser ma main sur leurs adversaires!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 15, 'Ceux qui haïssent l\'Éternel viendraient flatter son peuple; Sa prospérité durerait éternellement.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 16, 'Je vous nourrirais de la moelle du froment; Je vous rassasierais encore du miel du rocher.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 1, 'Psaume d\'Asaph. Dieu se tient dans l\'assemblée divine; Il juge au milieu des dieux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 2, '«Jusques à quand rendrez-vous des jugements iniques Et prendrez-vous parti pour les méchants? Pause');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 3, 'Faites droit au faible et à l\'orphelin; Rendez justice au misérable et à l\'indigent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 4, 'Délivrez le faible et le pauvre; Sauvez-les de la main des méchants!»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 5, 'Mais ils ne veulent rien entendre, rien comprendre. Ils marchent dans les ténèbres; Tous les fondements de la terre sont ébranlés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 6, 'J\'avais dit: «Vous êtes des dieux; Vous êtes tous des fils du Très-Haut!»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 7, 'Néanmoins, vous mourrez comme les autres hommes; Vous succomberez comme tous les grands de ce monde!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 8, 'Lève-toi, ô Dieu; juge la terre! Car tous les peuples font partie de ton héritage.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 1, 'Cantique. — Psaume d\'Asaph. Dieu, ne garde pas le silence! Ne reste pas sourd et inactif, ô Dieu fort!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 2, 'Car voici que tes ennemis s\'agitent; Ceux qui te haïssent lèvent la tête.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 3, 'Ils trament contre ton peuple de perfides complots, Et ils se concertent contre ceux que tu protèges.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 4, '«Venez, disent-ils, faisons-les disparaître Du nombre des nations, Et qu\'on ne se souvienne plus du nom d\'Israël!»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 5, 'Ils ont conspiré d\'un commun accord; Ils forment une alliance contre toi:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 6, 'Les tentes d\'Édom et les Ismaélites, Moab et les Hagaréniens,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 7, 'Guébal, Ammon, les Amalécites, Les Philistins et les habitants de Tyr.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 8, 'L\'Assyrien se joint aussi à eux; Ils prêtent leurs bras aux enfants de Lot. Pause');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 9, 'Traite-les comme tu traitas jadis les Madianites, Comme tu traitas Sisera et Jabin au torrent de Kison!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 10, 'Ils furent détruits à Endor, Et ils servirent de fumier à la terre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 11, 'Rends-les, rends leurs chefs semblables à Oreb et Zéeb, Et tous leurs princes, à Zébach et à Tsalmuna.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 12, 'Car tes ennemis disent: «Emparons-nous Des demeures où Dieu réside!»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 13, 'mon Dieu, rends-les semblables au tourbillon, Au chaume emporté par le vent!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 14, 'Comme le feu dévore la forêt. Comme la flamme embrase les montagnes,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 15, 'De même aussi, mets-les en fuite au souffle de ta tempête; Que ton ouragan les frappe d\'épouvante!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 16, 'Couvre leur face d\'ignominie. Et qu\'ils recherchent ton nom, ô Éternel!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 17, 'Qu\'ils rougissent, qu\'ils soient épouvantés à jamais; Qu\'ils soient couverts de honte et qu\'ils périssent,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 18, 'Et qu\'ils sachent que toi seul, dont le nom est l\'Éternel, Tu es le Souverain de toute la terre!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 1, 'Au maître-chantre. — Des enfants de Coré. — Sur la Guittith. — Psaume. Que tes demeures sont aimables, Éternel des armées!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 2, 'Mon âme se consume, elle languit Après les parvis de l\'Éternel. Mon coeur et ma chair font monter leurs cris de joie Vers le Dieu vivant.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 3, 'Le passereau même trouve bien un asile, Et l\'hirondelle un nid où elle met ses petits! Tes autels, ô Éternel des armées, Mon Roi et mon Dieu!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 4, 'Heureux ceux qui habitent dans ta maison: Ils peuvent te louer sans cesse! Pause');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 5, 'Heureux l\'homme dont la force est en toi; Heureux ceux qui aiment le chemin de ta maison!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 6, 'Quand ils traversent la vallée de Baca. Ils la changent en fontaines, Et les pluies la couvrent de bénédictions.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 7, 'Leurs forces augmentent, à mesure qu\'ils s\'avancent Pour se présenter devant Dieu, en Sion.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 8, 'Éternel, Dieu des armées, écoute ma prière! Dieu de Jacob, prête l\'oreille! Pause');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 9, 'Toi, ô Dieu, qui es notre bouclier, regarde. Et jette les yeux sur ton oint!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 10, 'Car un jour dans tes parvis vaut mieux que mille ailleurs. J\'aime mieux me tenir sur le seuil de la maison de mon Dieu, Que demeurer dans les tentes des méchants.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 11, 'Oui, l\'Éternel Dieu est un soleil et un boucher; L\'Éternel donne la grâce et la gloire; Il ne refuse aucun bien à ceux qui marchent dans l\'intégrité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 12, 'Éternel des armées. Heureux l\'homme qui se confie en toi!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 1, 'Au maître-chantre. — Des enfants de Coré. — Psaume. Éternel, tu avais accordé ta faveur à ton pays; Tu avais ramené les captifs de Jacob;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 2, 'Tu avais pardonné l\'iniquité de ton peuple; Tu avais effacé tous leurs péchés. Pause');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 3, 'Tu avais entièrement apaisé ton courroux; Tu étais revenu de l\'ardeur de ta colère.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 4, 'Relève-nous, ô Dieu de notre salut, Et fais cesser ton indignation contre nous!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 5, 'Seras-tu toujours courroucé contre nous? Feras-tu durer ta colère éternellement?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 6, 'Ne reviendras-tu pas nous rendre la vie. Afin que ton peuple se réjouisse en toi?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 7, 'Fais-nous contempler ta grâce, ô Éternel, Et accorde-nous ton salut!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 8, 'J\'écouterai ce que dit le Dieu fort, l\'Éternel; Car il parle de paix à son peuple et à ses bien-aimés. Toutefois, qu\'ils ne retombent plus dans leur égarement!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 9, 'Oui, son salut est près de ceux qui le craignent, Et la gloire de notre pays va refleurir.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 10, 'La bonté et la vérité se sont rencontrées; La justice et la paix se sont embrassées.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 11, 'La vérité germera de la terre, Et la justice regardera du haut des cieux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 12, 'L\'Éternel donnera ses biens. Et notre terre produira ses fruits.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 13, 'La justice marchera devant lui, Et elle suivra la trace de ses pas.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 1, 'Prière de David. Prête l\'oreille ô Éternel, exauce-moi; Car je suis affligé et misérable.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 2, 'Protège mon âme; car je suis de ceux qui t\'aiment. Mon Dieu, sauve ton serviteur qui se confie en toi!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 3, 'Aie pitié de moi, Seigneur; Car je crie vers toi tout le jour.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 4, 'Réjouis l\'âme de ton serviteur: C\'est à toi. Seigneur, que j\'élève mon âme!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 5, 'Car tu es bon et clément. Seigneur, Et riche en grâce pour tous ceux qui t\'invoquent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 6, 'Écoute ma prière, ô Éternel, Et sois attentif à ma voix suppliante!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 7, 'Je t\'invoque au jour de ma détresse, Parce que tu m\'exauces.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 8, 'Nul parmi les dieux n\'est comme toi. Seigneur, Et il n\'est point d\'oeuvres comme les tiennes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 9, 'Toutes les nations que tu as faites Viendront se prosterner devant toi. Seigneur, Et elles glorifieront ton nom.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 10, 'Car tu es grand, et tu accomplis des miracles: Toi seul, tu es Dieu!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 11, 'Eternel, apprends-moi à marcher dans tes voies: Je suivrai le chemin de ta vérité. Dispose mon coeur à la crainte de ton nom.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 12, 'Je te louerai, Seigneur, mon Dieu, de tout mon coeur. Et je glorifierai ton nom à toujours;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 13, 'Car ta bonté est grande envers moi, Et tu as retiré mon âme du fond du Sépulcre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 14, 'O Dieu, des orgueilleux se lèvent contre moi. Des bandes d\'hommes violents en veulent à ma vie; Ils ne pensent jamais à toi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 15, 'Mais toi, Seigneur, tu es un Dieu Compatissant et miséricordieux. Lent à la colère, riche en grâce et en fidélité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 16, 'Tourne-toi vers moi et prends-moi en pitié. Donne ta force à ton serviteur. Et sauve le fils de ta servante.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 17, 'Accorde-moi un signe de ta faveur, Afin que mes ennemis soient couverts de confusion, Et qu\'ils voient que c\'est toi, ô Éternel, Qui me secours et me consoles!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 1, 'Psaume des enfants de Coré. — Cantique. Les fondements de Jérusalem reposent Sur les montagnes saintes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 2, 'L\'Éternel aime les portes de Sion; Il la préfère à toutes les demeures de Jacob.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 3, 'Un avenir de gloire t\'est destiné, cité de Dieu! Pause');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 4, 'Je mentionnerai l\'Egypte et Babylone Parmi ceux qui me connaissent. Ainsi que les Philistins, et Tyr, et l\'Ethiopie: C\'est ici que sera leur lieu de naissance!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 5, 'Oui, on dira de Sion: «Chacun d\'eux est né dans cette ville, Et le Très-Haut lui-même l\'a fondée!»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 6, 'L\'Éternel passe en revue les peuples, et il écrit: «Celui-là aussi est un enfant de Sion!» Pause');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 7, 'Alors chanteurs et joueurs de flûte disent de concert: En toi se trouvent toutes mes sources de vie!»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 1, 'Cantique. Psaume des enfants de Coré. — Au maître-chantre; à chanter sur un mode triste. — Hymne d\'Héman, l\'Ézrahite. Éternel, Dieu de mon salut, Jour et nuit, je crie en ta présence.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 2, 'Que ma prière parvienne jusqu\'à toi; Prête l\'oreille à ma supplication!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 3, 'Car mon âme est rassasiée de maux, Et ma vie penche vers le Sépulcre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 4, 'On me compte parmi ceux qui descendent vers le tombeau; Je suis comme un homme qui a perdu sa force.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 5, 'Je suis abandonné parmi les morts. Pareil à ceux dont le cadavre est couché dans la tombe. A ceux dont tu ne te souviens plus, Et qui sont exclus de ta protection.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 6, 'Tu m\'as mis au plus profond de la fosse. Dans les ténèbres, dans les abîmes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 7, 'Ta colère pèse sur moi, Et tu m\'accables de tous tes flots. Pause');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 8, 'Tu as éloigné de moi ceux qui me connaissent; Tu as fait de moi un objet d\'horreur pour eux. Je suis enfermé et ne puis sortir;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 9, 'Mon oeil dépérit dans la douleur. Je t\'invoque, ô Éternel, tous les jours; Je tends les mains vers toi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 10, 'Est-ce pour les morts que tu fais des miracles? Ou bien, les trépassés se lèvent-ils pour te louer? Pause');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 11, 'Annonce-t-on ta bonté dans le tombeau. Et ta fidélité dans l\'abîme?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 12, 'Tes merveilles sont-elles connues dans les ténèbres, Et ta justice dans la terre d\'oubli?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 13, 'Mais moi, ô Éternel, je crie vers toi; Ma prière te prévient dès le matin.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 14, 'Éternel, pourquoi rejettes-tu mon âme Et me caches-tu ta face?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 15, 'Je suis misérable, presque mourant depuis ma jeunesse; Sous le poids de ta colère, je suis éperdu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 16, 'Les flots de ton courroux passent sur moi; Tes fureurs m\'anéantissent:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 17, 'Elles m\'environnent chaque jour comme un fleuve; Elles m\'enveloppent toutes à la fois.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 18, 'Tu as éloigné de moi amis et compagnons; Je n\'ai pour compagnie que les ténèbres!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 1, 'Hymne d\'Éthan l\'Ézrahite. Je chanterai toujours les bontés de l\'Éternel; D\'âge en âge, ma bouche proclamera sa fidélité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 2, 'J\'ai dit: «Ta grâce est un édifice éternel; Tu as établi dans les cieux les fondements de ta fidélité.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 3, '— «J\'ai conclu, dit l\'Éternel, cette alliance avec mon élu; J\'ai fait ce serment à David, mon serviteur:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 4, 'J\'affermirai ta postérité pour toujours; J\'ai fondé ton trône à jamais.» Pause');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 5, 'Les cieux, ô Éternel, célèbrent tes merveilles. Ainsi que ta fidélité, dans l\'assemblée des saints.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 6, 'Qui, dans les cieux, est comparable à l\'Éternel? Qui ressemble à l\'Éternel parmi les fils de Dieu?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 7, 'Dieu est très redoutable dans l\'assemblée des saints. Plus terrible que tous ceux qui l\'entourent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 8, 'Éternel, Dieu des armées. Qui est puissant comme toi? Éternel, ton amour fidèle Rayonne autour de toi!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 9, 'Tu domptes l\'orgueil de la mer: Quand ses vagues s\'élèvent, c\'est toi qui les apaises.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 10, 'Tu as écrasé l\'Egypte, tu l\'as blessée à mort; Par la force de ton bras, tu as dispersé tes ennemis.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 11, 'A toi sont les cieux, à toi aussi la terre; Tu as fondé le monde et tout ce qu\'il renferme.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 12, 'Le Nord et le Midi, c\'est toi qui les as créés; Le Thabor et l\'Hermon sont dans l\'allégresse A cause de ton nom.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 13, 'Ton bras est armé de puissance. Ta main est forte; ta main droite exerce l\'autorité suprême.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 14, 'La justice et le droit sont la base de ton trône; La bonté et la vérité marchent devant ta face.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 15, 'Heureux le peuple qui connaît les chants de triomphe: Il s\'avance à la clarté de ta face, ô Éternel!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 16, 'Il se réjouit en célébrant ton nom chaque jour, Et il se glorifie de ta justice.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 17, 'Car c\'est toi qui es la splendeur de notre puissance. Et c\'est ta faveur qui nous fait relever la tête.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 18, 'Oui, notre bouclier protecteur Est dans les mains de l\'Éternel: Notre roi appartient au Saint d\'Israël!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 19, 'Tu parlas jadis dans une vision à tes bien-aimés, Et tu dis: J\'ai prêté mon appui à un héros; J\'ai choisi dans les rangs du peuple un élu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 20, 'J\'ai trouvé David, mon serviteur; Je l\'ai oint de mon huile sainte.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 21, 'Ma main le soutiendra, Et mon bras le fortifiera.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 22, 'L\'ennemi ne pourra le surprendre, Et le méchant ne l\'opprimera point.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 23, 'Je briserai devant lui ses adversaires. Et je frapperai ceux qui le haïssent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 24, 'Ma fidélité et ma bonté seront avec lui, Et par la puissance de mon nom, il pourra relever la tête.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 25, 'J\'étendrai sa main puissante sur la mer. Et son empire sur les fleuves.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 26, 'Il m\'invoquera, disant: «Tu es mon Père, Mon Dieu, mon rocher protecteur.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 27, 'Aussi ferai-je de lui le premier-né, Le souverain des rois de la terre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 28, 'Je lui conserverai ma faveur éternellement, Et mon alliance avec lui sera inébranlable.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 29, 'Je lui donnerai une postérité éternelle. Et son trône durera autant que les cieux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 30, 'Si ses fils abandonnent ma loi Et n\'obéissent pas à mes ordres,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 31, 'S\'ils violent mes commandements Et s\'ils n\'observent pas mes préceptes,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 32, 'Je châtierai leurs transgressions en les frappant de la verge, Et leurs iniquités en leur envoyant des fléaux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 33, 'Mais je ne leur retirerai pas ma faveur; Je ne mentirai pas à mes promesses.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 34, 'Je ne violerai pas mon alliance. Et je ne changerai pas la parole sortie de mes lèvres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 35, 'J\'en ai fait le serment, au nom de ma sainteté: Je ne mentirai pas à David.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 36, 'Sa postérité durera éternellement; Son trône subsistera devant moi aussi longtemps que le soleil.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 37, 'Comme la lune, il sera inébranlable à jamais; Le témoin qui est dans les cieux est fidèle. Pause');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 38, 'Cependant, tu as repoussé ton oint; tu l\'as rejeté, Tu t\'es indigné contre lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 39, 'Tu as rompu l\'alliance conclue avec ton serviteur; Tu as traîné sa couronne dans la poussière.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 40, 'Tu as renversé toutes ses forteresses: Tu as mis en ruines ses remparts.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 41, 'Tous les passants le mettent au pillage; Il est couvert d\'opprobre par ses voisins.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 42, 'Tu as fortifié le bras de ses adversaires; Tu as rempli de joie tous ses ennemis.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 43, 'Tu as émoussé le tranchant de son épée. Et tu ne l\'as pas soutenu dans le combat.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 44, 'Tu as mis fin à sa splendeur, Et tu as jeté son trône à terre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 45, 'Tu as abrégé les jours de sa jeunesse. Et tu l\'as couvert de honte. Pause');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 46, 'Jusques à quand, ô Éternel, te cacheras-tu sans cesse. Et ta colère brûlera-t-elle comme un feu?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 47, 'Rappelle-toi quelle est la durée de ma vie. Pour quel néant tu as créé tous les fils des hommes!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 48, 'Quel homme pourrait vivre et ne pas voir la mort? Qui sauvera son âme de la puissance du Sépulcre? Pause');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 49, 'Seigneur, où sont tes bontés premières, Que toi, le Dieu fidèle, tu avais promises à David par serment?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 50, 'Souviens-toi, Seigneur, de l\'opprobre de tes serviteurs; Je porte en mon sein l\'injure de tant de grands peuples!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 51, 'Car tes ennemis ont jeté l\'outrage, ô Éternel, Tes ennemis ont jeté l\'outrage sur les pas de ton oint.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 52, 'Béni soit l\'Éternel a perpétuité! Amen, Amen!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 1, 'Prière de Moïse, homme de Dieu. Seigneur, tu as été pour nous une retraite D\'âge en âge.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 2, 'Avant que les montagnes fussent nées, Et que tu eusses formé la terre et le monde. D\'éternité en éternité, tu es Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 3, 'Tu réduis l\'homme en poussière. Et tu dis: Fils d\'Adam, retournez à la terre!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 4, 'Car mille ans sont à tes yeux Comme le jour d\'hier qui est passé, Comme une veille dans la nuit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 5, 'Tu les emportes; ils sont comme un songe. Ils sont comme une herbe qui naît le matin:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 6, 'Elle fleurit le matin, et elle pousse; Le soir, on la coupe et elle sèche.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 7, 'Nous sommes consumés par ta colère Et anéantis par ton courroux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 8, 'Tu as fait passer devant toi nos iniquités. Et devant la lumière de ta face nos fautes cachées.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 9, 'Tous nos jours s\'évanouissent devant ton courroux; Nos années disparaissent comme un souffle.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 10, 'Les jours de nos années s\'élèvent à soixante et dix ans Et, pour les plus robustes, à quatre-vingts; Et ce qui en fait l\'orgueil n\'est que peine et tourment: Tout cela passe vite, et nous nous envolons!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 11, 'Qui connaît la force de ta colère et l\'ardeur de ton courroux? Oui ressent la crainte qui t\'est due?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 12, 'Enseigne-nous à bien compter nos jours. Afin que notre coeur s\'ouvre aux leçons de la sagesse!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 13, 'Reviens, ô Éternel! Jusques à quand.? Aie compassion de tes serviteurs!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 14, 'Dès le matin, rassasie-nous de ta bonté, Et nous serons dans l\'allégresse et dans la joie Tout le long de nos jours.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 15, 'Donne-nous autant de jours de joie Que tu nous as donné de jours d\'épreuves, Et d\'années où nous avons connu le malheur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 16, 'Que ta puissance éclate aux yeux de tes serviteurs, Et que ta gloire resplendisse sur leurs enfants!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 17, 'Que la bienveillance de l\'Éternel, notre Dieu, repose sur nous! Affermis notre oeuvre entre nos mains. Oui, affermis l\'oeuvre de nos mains!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 1, 'Celui qui habite dans la retraite du Très-Haut Repose à l\'ombre du Tout-Puissant.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 2, 'Je dis à l\'Éternel: «Tu es mon refuge et ma forteresse, Mon Dieu en qui je mets ma confiance!»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 3, 'C\'est lui qui te délivrera du filet de l\'oiseleur Et de la peste meurtrière.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 4, 'Il te couvrira de ses ailes. Et sous sa protection tu trouveras un refuge; Sa fidélité sera ton bouclier protecteur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 5, 'Tu ne craindras ni les terreurs de la nuit. Ni la flèche qui vole pendant le jour,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 6, 'Ni la peste qui se glisse à travers les ténèbres, Ni la mortalité qui sévit en plein midi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 7, 'Quand il tomberait mille hommes à ton côté Et dix mille à ta droite. Tu ne serais pas atteint.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 8, 'Mais toi, tu contempleras de tes yeux Et tu verras le châtiment des méchants.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 9, 'Oui, tu es mon refuge, ô Éternel! Tu as pris le Très-Haut pour ton asile.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 10, 'Aucun mal ne t\'atteindra; Aucun fléau n\'approchera de ta tente.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 11, 'Car il ordonnera à ses anges De te garder dans toutes tes entreprises.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 12, 'Ils te porteront sur leurs mains, De peur que ton pied ne heurte contre une pierre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 13, 'Tu marcheras sur le lion et sur l\'aspic; Tu écraseras le lionceau et le dragon.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 14, '«Puisqu\'il s\'est attaché à moi, je le délivrerai; Je le mettrai en sûreté, puisqu\'il connaît mon nom.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 15, 'Il m\'invoquera, et je l\'exaucerai; Je serai avec lui dans la détresse, Je l\'en retirerai et je le glorifierai.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 16, 'Je le rassasierai de longs jours. Et je lui ferai contempler mon salut.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 1, 'Psaume. — Cantique pour le jour du Sabbat. Il est bon de célébrer l\'Éternel, Et de psalmodier à la gloire de ton nom, ô Très-Haut,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 2, 'D\'annoncer dès le matin ta bonté. Et pendant la nuit, ta fidélité,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 3, 'Au son de la lyre, aux accords du luth Et de la harpe!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 4, 'Éternel, tu m\'as rempli de joie Par la grandeur de tes oeuvres; Je célèbre avec allégresse les ouvrages de tes mains.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 5, 'Que tes oeuvres sont grandes, ô Éternel! Tes pensées sont merveilleusement profondes!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 6, 'L\'homme dépourvu de sens ne peut les connaître; L\'insensé ne saurait les comprendre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 7, 'Si les méchants croissent comme l\'herbe, Et si tous les ouvriers d\'iniquité fleurissent, C\'est pour être détruits à jamais.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 8, 'Mais toi, ô Éternel, tu es éternellement le Très-Haut.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 9, 'Tes ennemis, ô Éternel, Tes ennemis périront! Tous les ouvriers d\'iniquité seront dispersés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 10, 'Mais tu me donnes la force du buffle; Je suis oint d\'une huile fraîche.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 11, 'Mon oeil pourra contempler ceux qui m\'épient; Mes oreilles entendront sans crainte Les méchants qui s\'élèvent contre moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 12, 'Les justes croîtront comme le palmier; Ils s\'élèveront comme le cèdre du Liban.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 13, 'Plantés dans la maison de l\'Éternel, Dans les parvis de notre Dieu, ils se couvriront de fleurs.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 14, 'Ils porteront encore des fruits dans la blanche vieillesse; Ils seront vigoureux et verdoyants,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 15, 'Pour annoncer que l\'Éternel juge avec équité. C\'est lui qui est mon rocher, et il n\'y a point en lui d\'injustice.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 1, 'L\'Éternel règne, il est revêtu de majesté! L\'Éternel a pour vêtement, pour ceinture la puissance; Aussi la terre est-elle ferme, et elle ne chancelle pas.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 2, 'Ton trône est affermi dès les temps anciens. Tu es de toute éternité!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 3, 'Les fleuves, ô Éternel, Les fleuves ont élevé leur voix; Oui, les fleuves font retentir le grondement de leurs flots.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 4, 'Plus que la voix des grandes eaux, Des vagues puissantes de la mer, L\'Éternel est puissant dans les lieux très hauts.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 5, 'Tu es inébranlablement fidèle à tes promesses. La sainteté sert de parure à ta maison. Éternel, pour toute la durée des siècles!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 1, 'Dieu des vengeances, ô Éternel, Dieu des vengeances, fais rayonner ta splendeur!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 2, 'Lève-toi, juge de la terre. Châtie les orgueilleux comme ils le méritent!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 3, 'Jusques à quand les méchants, ô Éternel, Jusques à quand les méchants triompheront-ils?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 4, 'Jusques à quand se répandront-ils en discours insolents. Et se glorifieront-ils, tous les ouvriers d\'iniquité?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 5, 'Éternel, ils écrasent ton peuple. Et ils oppriment ton héritage.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 6, 'Ils tuent la veuve et l\'étranger. Et ils mettent à mort les orphelins.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 7, 'Puis ils disent: «L\'Éternel ne le voit pas; Le Dieu de Jacob n\'y fait pas attention!»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 8, 'Prenez garde, hommes stupides! Insensés, quand donc ferez-vous preuve d\'intelligence?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 9, 'Celui qui a planté l\'oreille n\'entendra-t-il pas? Celui qui a formé l\'oeil ne verra-t-il pas?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 10, 'Celui qui châtie les nations ne punira-t-il pas. Lui qui enseigne aux hommes la science?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 11, 'L\'Éternel connaît les pensées de l\'homme: Il sait qu\'elles sont vaines!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 12, 'Heureux, ô Éternel, l\'homme que tu instruis, Et à qui tu enseignes ta loi,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 13, 'Pour le remplir de paix pendant les mauvais jours. Tandis que se creuse la tombe sous les pas du méchant!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 14, 'L\'Éternel ne délaissera pas son peuple, Et il n\'abandonnera pas son héritage.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 15, 'Ses jugements se montreront un jour conformes à la justice. Et tous ceux qui ont le coeur droit s\'en réjouiront.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 16, 'Qui se lèvera pour moi contre les méchants? Qui prendra ma défense contre les ouvriers d\'iniquité?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 17, 'Si l\'Éternel n\'eût été mon secours. Bientôt mon âme eût habité le séjour du silence.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 18, 'Quand je disais: «Mon pied chancelle» — Ta bonté, ô Éternel, m\'a soutenu!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 19, 'Quand mon coeur était assiégé de soucis. Tes consolations ont réjoui mon âme.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 20, 'Comment pourrais-tu te faire le complice des juges iniques, Qui commettent des crimes au nom de la loi?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 21, 'Ils attaquent la vie du juste, Et ils condamnent le sang innocent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 22, 'Mais l\'Éternel est ma haute retraite; Mon Dieu est le rocher où je trouve un refuge.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 23, 'Il fera retomber sur eux leur crime, Et leur perversité même consommera leur ruine. Oui, l\'Éternel, notre Dieu, les fera périr.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 1, 'Venez, chantons avec allégresse en l\'honneur de l\'Éternel; Jetons des cris de joie Vers celui qui est notre rocher, notre salut.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 2, 'Présentons-nous devant lui avec des louanges; Faisons retentir des cantiques en son honneur!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 3, 'Car l\'Éternel est le Dieu suprême, Le Roi dont la grandeur s\'élève au-dessus de tous les dieux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 4, 'En sa main sont les abîmes de la terre; A lui, les montagnes les plus élevées.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 5, 'A lui appartient la mer, — car c\'est lui qui l\'a créée — Ainsi que la terre, qui est l\'oeuvre de ses mains.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 6, 'Venez, prosternons-nous, inclinons-nous; Fléchissons les genoux devant l\'Éternel qui nous a créés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 7, 'Car il est notre Dieu. Nous sommes le peuple dont il est le berger. Le troupeau que sa main conduit. Aujourd\'hui, si vous entendez sa voix,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 8, 'N\'endurcissez pas vos coeurs, comme à Mériba, Comme au jour de Massa, dans le désert.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 9, 'Là, vos pères m\'ont tenté Et ils m\'ont mis à l\'épreuve. Aussi ont-ils vu mes oeuvres!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 10, 'Pendant quarante ans, j\'eus cette génération en dégoût, Et je dis: «C\'est un peuple dont le coeur s\'égare; Il ne veut pas connaître mes desseins.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 11, 'C\'est pourquoi j\'ai fait ce serment dans ma colère: «Ils n\'entreront pas dans mon repos!»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 1, 'Chantez en l\'honneur de l\'Éternel un cantique nouveau! Habitants de toute la terre, chantez en son honneur!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 2, 'Chantez en l\'honneur de l\'Éternel; bénissez son nom; Annoncez de jour en jour son oeuvre de salut!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 3, 'Racontez sa gloire parmi les nations, Et ses merveilles parmi tous les peuples.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 4, 'Car l\'Éternel est grand et infiniment digne de louanges; Il est redoutable par-dessus tous les dieux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 5, 'Oui, tous les dieux des peuples sont des idoles; Mais l\'Éternel a créé les cieux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 6, 'La splendeur et la majesté l\'environnent; La force et la magnificence remplissent son sanctuaire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 7, 'Rendez à l\'Éternel, familles des peuples. Rendez à l\'Éternel la gloire et l\'honneur!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 8, 'Rendez à l\'Éternel la gloire due à son nom; Apportez des offrandes, et entrez dans ses parvis.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 9, 'Prosternez-vous devant l\'Éternel, Revêtus d\'ornements sacrés. Tremblez devant lui, vous tous, habitants de la terre!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 10, 'Dites parmi les nations: «L\'Éternel est Roi; Aussi le monde est-il ferme, et il ne chancellera point. L\'Éternel jugera les peuples avec équité.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 11, 'Que les cieux se réjouissent, et que la terre tressaille de joie! Que la mer retentisse, avec tout ce qu\'elle contient!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 12, 'Que les campagnes frémissent d\'allégresse Avec tout ce qu\'elles renferment; Que tous les arbres des forêts tressaillent de joie,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 13, 'En présence de l\'Éternel! Car il vient, il vient pour juger la terre! Il jugera le monde avec justice; Il jugera les nations, parce qu\'il est fidèle à ses promesses.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 1, 'L\'Éternel règne! Que la terre tressaille de joie; Que les îles nombreuses se réjouissent!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 2, 'La nuée et l\'obscurité l\'environnent; La justice et le droit sont la base de son trône.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 3, 'Le feu marche devant lui Et embrase de tous côtés ses ennemis.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 4, 'Ses éclairs illuminent le monde: A cette vue, la terre tremble.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 5, 'Les montagnes se fondent, comme la cire, En présence de l\'Éternel, du Seigneur de toute la terre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 6, 'Les cieux annoncent sa justice. Et tous les peuples voient sa gloire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 7, 'Ils sont couverts de confusion, tous les adorateurs d\'images, Ceux qui mettent leur gloire dans les idoles! Tous les dieux se prosternent devant l\'Éternel.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 8, 'A cette nouvelle, Sion a été remplie de joie; Les filles de Juda ont tressailli d\'allégresse, A cause de tes jugements, ô Éternel!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 9, 'Car c\'est toi, ô Éternel, qui es le souverain de toute la terre. Tu es infiniment élevé au-dessus de tous les dieux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 10, 'Vous qui aimez l\'Éternel, ayez en horreur le mal: Il protège la vie de ses fidèles. Et il les délivre de la main des méchants.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 11, 'La lumière se lève pour le juste. Et la joie pour ceux qui ont le coeur droit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 12, 'Justes, réjouissez-vous en l\'Éternel, Et célébrez sa sainteté par vos louanges!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 1, 'Psaume. Chantez à la gloire de l\'Éternel un cantique nouveau! Car il a accompli des choses merveilleuses: Sa main droite et son bras saint lui ont donné la victoire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 2, 'L\'Éternel a fait connaître son salut; Il a manifesté sa justice aux yeux des nations.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 3, 'Il s\'est souvenu de sa bonté et de sa fidélité Envers la maison d\'Israël. Toutes les extrémités de la terre Ont vu l\'oeuvre de salut de notre Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 4, 'Habitants de la terre, Faites tous monter vos acclamations jusqu\'à l\'Éternel; Éclatez en cris de joie, et psalmodiez!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 5, 'Chantez en l\'honneur de l\'Éternel avec la harpe, Avec la harpe et au son des cantiques!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 6, 'Au son du cor et de la trompette. Poussez des acclamations devant le Roi, l\'Éternel!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 7, 'Que la mer frémisse, avec tout ce qu\'elle contient, Le monde, avec ceux qui l\'habitent!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 8, 'Que les fleuves battent des mains; Que toutes les montagnes éclatent en cris de joie,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 9, 'En présence de l\'Éternel! Car il vient pour juger la terre: Il jugera le monde avec justice, Et les peuples avec équité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 1, 'L\'Éternel règne; les peuples tremblent! Il a son trône au-dessus des chérubins; la terre est ébranlée!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 2, 'L\'Éternel est grand dans Sion; Il est élevé au-dessus de tous les peuples.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 3, 'Qu\'on célèbre son nom grand et redoutable: Dieu est saint!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 4, 'Qu\'on célèbre la puissance du Roi qui aime la justice. C\'est toi, ô Dieu, qui établis le droit; C\'est toi qui exerces en Jacob le jugement et la justice.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 5, 'Exaltez l\'Éternel, notre Dieu; Prosternez-vous devant son marchepied: Dieu est saint!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 6, 'Moïse et Aaron étaient parmi ses sacrificateurs. Et Samuel parmi ceux qui invoquaient son nom. Ils invoquaient l\'Éternel, et il leur répondait;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 7, 'Il leur parlait dans la colonne de nuée. Ils ont gardé ses enseignements, Et la loi qu\'il leur avait donnée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 8, 'Éternel, notre Dieu, tu leur as répondu; Tu fus pour eux un Dieu qui savait leur pardonner. Tout en les punissant de leurs fautes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 9, 'Exaltez l\'Éternel, notre Dieu, Et prosternez-vous devant sa montagne sainte; Car l\'Éternel, notre Dieu, est saint.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 1, 'Psaume d\'actions de grâces. Vous tous, habitants de la terre, Faites monter vos cris d\'allégresse jusqu\'à l\'Éternel!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 2, 'Servez l\'Éternel avec joie; Venez devant lui avec des cris d\'allégresse.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 3, 'Sachez que l\'Éternel est Dieu: C\'est lui qui nous a créés; nous sommes à lui! Nous sommes son peuple, et le troupeau dont il est le berger.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 4, 'Entrez dans son temple avec des actions de grâces, Dans ses parvis avec la louange; Célébrez-le, bénissez son nom;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 5, 'Car l\'Éternel est bon; sa bonté demeure à toujours, Et sa fidélité subsiste d\'âge en âge.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 1, 'Psaume de David. Je veux chanter la bonté et la justice; C\'est toi, ô Éternel, que je célébrerai.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 2, 'Je m\'appliquerai à suivre la voie de l\'intégrité. Quand viendras-tu à moi? Je donnerai l\'exemple d\'une conduite intègre. Au sein de ma famille.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 3, 'Je chasserai de mon esprit toute pensée coupable. J\'ai en horreur les actes d\'iniquité: Ils n\'ont aucun attrait pour moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 4, 'Le coeur pervers s\'éloignera de moi; Je ne connaîtrai point le mal.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 5, 'J\'anéantirai celui qui parle en secret contre son prochain. Je ne supporterai pas le regard hautain. Ni le coeur enflé d\'orgueil.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 6, 'J\'aurai les yeux sur les fidèles du pays, Pour les faire demeurer avec moi. Celui qui marche dans l\'intégrité, celui-là me servira.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 7, 'Celui qui use de tromperie n\'habitera pas dans ma maison; Celui qui profère le mensonge Ne subsistera pas devant mes yeux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 8, 'Chaque matin, je détruirai tous les méchants du pays, Afin que tous les ouvriers d\'iniquité Disparaissent de la cité de l\'Éternel.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 1, 'Prière de l\'affligé, lorsqu\'il est abattu et qu\'il exhale sa plainte devant l\'Éternel. Éternel, écoute ma prière, Et que mon cri parvienne jusqu\'à toi!,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 2, 'Ne me cache pas ta face, au jour de ma détresse; Incline vers moi ton oreille! Au jour où je t\'invoque, hâte-toi de me répondre!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 3, 'Car mes jours s\'évanouissent comme une fumée, Et mes os se consument comme un brasier.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 4, 'Mon coeur a été frappé, et il se dessèche comme l\'herbe; J\'oublie même de manger mon pain.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 5, 'Je pousse de tels gémissements. Que mes os s\'attachent à ma chair.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 6, 'Je ressemble au pélican du désert; Je suis comme le hibou des ruines.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 7, 'Je n\'ai plus de sommeil, Et je suis comme le passereau solitaire sur un toit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 8, 'Tous les jours, mes ennemis m\'outragent. Et mes adversaires en fureur prononcent mon nom Comme un nom maudit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 9, 'Je fais de la cendre ma nourriture. Et je mêle des larmes à mon breuvage,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 10, 'A cause de ton indignation et de ton courroux; Car tu m\'as saisi et rejeté au loin.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 11, 'Mes jours s\'inclinent comme l\'ombre du soir Et je me dessèche comme l\'herbe.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 12, 'Mais toi, ô Éternel, tu règnes à perpétuité. Et ta mémoire subsiste d\'âge en âge.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 13, 'Tu te lèveras, tu auras pitié de Sion. Il est temps de lui faire grâce: L\'heure est venue!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 14, 'Car tes serviteurs en chérissent les pierres; Ils aiment jusqu\'à sa poussière.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 15, 'Alors les peuples craindront le nom de l\'Éternel. Tous les rois de la terre, ô Dieu, verront ta gloire,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 16, 'Parce que l\'Éternel aura rebâti Sion, Qu\'il aura paru dans sa gloire,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 17, 'Qu\'il aura écouté la requête des misérables, Et n\'aura pas méprisé leur supplication.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 18, 'Cela sera écrit pour la génération future. Et le peuple qui sera créé, louera l\'Éternel.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 19, 'Car l\'Éternel abaissera ses regards, Du haut de sa demeure sainte. Et, du haut des cieux, l\'Éternel jettera les yeux sur la terre,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 20, 'Pour écouter les gémissements du captif, Pour délivrer ceux qui sont voués à la mort.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 21, 'Alors on célébrera le nom de l\'Éternel dans Sion, Et ses louanges dans Jérusalem,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 22, 'Quand tous les peuples, ainsi que les royaumes, Se rassembleront pour servir l\'Eternel.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 23, 'Dieu a brisé ma force au milieu de ma course; Il a abrégé mes jours.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 24, 'J\'ai dit: mon Dieu, ne m\'enlève pas à la fleur de l\'âge, Toi dont les années subsistent de siècle en siècle!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 25, 'Tu as jadis fondé la terre, Et les cieux sont l\'oeuvre de tes mains.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 26, 'Ils périront; mais toi, tu subsisteras. Ils s\'useront tous comme un vêtement; Tu les changeras comme un habit, et ils passeront.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 27, 'Mais toi, tu es toujours le même. Et tes années ne finiront point.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 28, 'Les enfants de tes serviteurs auront une demeure assurée, Et leur postérité se perpétuera sous tes yeux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 1, 'Psaume de David. Mon âme, bénis l\'Éternel, Et que tout ce qui est en moi bénisse son saint nom!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 2, 'Mon âme, bénis l\'Éternel, Et n\'oublie aucun de ses bienfaits!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 3, 'C\'est lui qui pardonne toutes tes iniquités. Qui guérit toutes tes infirmités,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 4, 'Qui arrache ta vie au tombeau. Qui te couronne de bonté et de miséricorde.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 5, 'C\'est lui qui comble de biens ta vieillesse. Et qui renouvelle ta jeunesse comme celle de l\'aigle.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 6, 'L\'Éternel fait justice Et droit à tous les opprimés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 7, 'Il a révélé ses desseins à Moïse, Et il a montré sa puissance aux enfants d\'Israël.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 8, 'L\'Éternel est compatissant et miséricordieux. Lent à la colère et riche en bonté.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 9, 'Il n\'accuse pas toujours; Il ne garde pas son courroux à perpétuité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 10, 'Il ne nous a pas traités selon nos péchés. Et il ne nous a pas punis selon nos iniquités.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 11, 'En effet, autant les cieux sont élevés au-dessus de la terre. Autant sa bonté est grande pour ceux qui le craignent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 12, 'Il a éloigné de nous nos transgressions. Autant que l\'Orient est éloigné de l\'Occident.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 13, 'Comme un père est ému de compassion envers ses enfants, L\'Éternel est ému de compassion envers ceux qui le craignent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 14, 'Car il sait bien de quoi nous sommes faits: Il se souvient que nous ne sommes que poussière!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 15, 'Les jours de l\'homme sont comme l\'herbe; Il fleurit comme la fleur des champs:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 16, 'Que le vent souffle sur elle, et voici qu\'elle n\'est plus; La place où elle était ne la connaît plus!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 17, 'Mais la bonté de l\'Éternel, pour ceux qui le craignent, Subsiste de tout temps et à toujours; Et il accorde sa délivrance aux enfants de leurs enfants,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 18, 'A tous ceux qui gardent son alliance Et se rappellent ses commandements, Afin de les mettre en pratique.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 19, 'L\'Éternel a établi son trône dans les cieux, Et tout est soumis à son empire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 20, 'Bénissez l\'Éternel, vous, ses anges forts et vaillants, Qui exécutez son commandement, Et qui obéissez à sa voix!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 21, 'Bénissez l\'Éternel, vous, toutes ses armées. Qui êtes à son service et qui faites sa volonté!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 22, 'Bénissez l\'Éternel, vous, toutes ses oeuvres. Dans tous les lieux de son empire! Mon âme, bénis l\'Éternel!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 1, 'Mon âme, bénis l\'Éternel! Éternel, ô mon Dieu, tu es merveilleusement grand; Tu es revêtu de splendeur et de majesté.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 2, 'L\'Éternel s\'enveloppe de lumière comme d\'un manteau; Il déploie les cieux comme une tente.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 3, 'Il construit au-dessus des eaux sa demeure inaccessible; Les nuages lui servent de char; Il s\'avance sur les ailes du vent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 4, 'Il fait des vents ses messagers. Et des flammes de feu ses serviteurs.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 5, 'Il a posé la terre sur ses fondements: Elle ne sera jamais ébranlée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 6, 'Tu l\'avais enveloppée de l\'abîme comme d\'un vêtement; Les eaux s\'étaient arrêtées sur les montagnes:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 7, 'A ta menace, elles reculèrent! Au bruit de ton tonnerre, elles s\'enfuirent épouvantées.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 8, 'Les montagnes s\'élevèrent et les vallées s\'abaissèrent, A la place que tu leur avais assignée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 9, 'Tu as fixé à la mer une limite qu\'elle ne franchira pas Elle ne reviendra plus couvrir la terre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 10, 'Dieu envoie des sources dans les vallons, Et elles coulent entre les montagnes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 11, 'Elles abreuvent toutes les bêtes des champs; Les ânes sauvages y étanchent leur soif.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 12, 'Les oiseaux du ciel habitent sur leurs bords, Et font retentir leurs chants dans le feuillage.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 13, 'Du haut de sa demeure, Dieu abreuve les montagnes; La terre se rassasie du fruit de ses oeuvres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 14, 'Il fait germer l\'herbe pour le bétail, Et les plantes pour l\'usage de l\'homme, Qui tire ainsi de la terre sa nourriture:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 15, 'Le vin qui réjouit le coeur de l\'homme, Et qui, mieux que l\'huile, fait resplendir son visage, Ainsi que le pain qui fortifie le coeur de l\'homme.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 16, 'Les arbres de l\'Éternel, les cèdres du Liban Qu\'il a plantés, sont gonflés de sève.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 17, 'Les oiseaux y bâtissent leurs nids; La cigogne fait des cyprès sa demeure.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 18, 'Les hautes montagnes sont l\'asile des chamois, Et les rochers servent de retraite aux gerboises.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 19, 'L\'Éternel a fait la lune pour marquer les temps, Ainsi que le soleil qui connaît l\'heure de son déclin.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 20, 'Tu répands les ténèbres, et la nuit vient: Alors tous les animaux des forêts se mettent en mouvement.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 21, 'Les jeunes lions rugissent après leur proie Et demandent à Dieu leur pâture.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 22, 'Puis le soleil se lève: ils se retirent, Et vont se coucher dans leurs tanières.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 23, 'Alors l\'homme sort, pour se rendre à son ouvrage Et se livrer à son travail jusqu\'au soir.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 24, 'Éternel, combien tes oeuvres sont nombreuses! Tu les as toutes faites avec sagesse; La terre est pleine de tes richesses.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 25, 'Voici encore la grande et vaste mer! Là fourmillent, sans nombre. Des animaux petits et grands.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 26, 'Là se promènent les navires. Et ce monstre marin que tu as créé pour se jouer dans les flots,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 27, 'Tous ces êtres attendent de toi Que tu leur donnes, en temps opportun, leur nourriture.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 28, 'Tu la leur donnes, et ils la recueillent; Tu ouvres ta main, et ils sont rassasiés de biens.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 29, 'Si tu caches ta face, ils sont éperdus; Si tu leur retires le souffle, ils expirent Et retournent dans leur poussière.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 30, 'S\'ils reçoivent de nouveau ton souffle, ils revivent. Et tu renouvelles la face de la terre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 31, 'Que la gloire de l\'Éternel dure à toujours! Que l\'Éternel se réjouisse de ses oeuvres!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 32, 'Il regarde la terre, et la voilà qui tremble; Il touche les montagnes, et elles se couvrent de fumée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 33, 'Je chanterai à la gloire de l\'Éternel, tant que je vivrai; Je psalmodierai en l\'honneur de mon Dieu, tant que j\'existerai.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 34, 'Puisse mon cantique lui être agréable! Je me réjouirai en l\'Éternel.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 35, 'Que les pécheurs disparaissent de la terre. Et que les méchants n\'existent plus! Mon âme, bénis l\'Éternel! Louez l\'Éternel!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 1, 'Célébrez l\'Éternel, invoquez son nom; Faites connaître parmi les nations ses grandes oeuvres!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 2, 'Chantez, psalmodiez en son honneur; Parlez de toutes ses merveilles!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 3, 'Glorifiez-vous de son saint nom; Que ceux dont le coeur recherche l\'Éternel se réjouissent!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 4, 'Implorez l\'Éternel et son puissant secours; Recherchez continuellement sa présence!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 5, 'Souvenez-vous des merveilles qu\'il a faites, De ses miracles, et des jugements que sa bouche a prononcés,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 6, 'vous, descendants d\'Abraham, son serviteur, Enfants de Jacob, ses élus!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 7, 'C\'est lui, l\'Éternel, qui est notre Dieu; Ses jugements s\'exercent sur toute la terre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 8, 'Il se souvient à jamais de son alliance, De la parole qu\'il a donnée pour mille générations,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 9, 'De la promesse qu\'il a faite à Abraham, Du serment qu\'il a fait à Isaac,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 10, 'Et qu\'il a confirmé à Jacob comme une loi, A Israël comme une alliance éternelle,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 11, 'En disant: «Je te donnerai le pays de Canaan; C\'est là votre part d\'héritage.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 12, 'Ils n\'étaient alors qu\'une poignée d\'hommes. Peu nombreux et étrangers dans le pays,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 13, 'Allant de nation en nation. Et d\'un royaume à un autre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 14, 'L\'Éternel ne permit à personne de les opprimer; Il châtia des rois à cause d\'eux:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 15, '«Ne touchez pas à ceux que j\'ai oints, dit-il. Et ne faites pas de mal à mes prophètes!»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 16, 'Il appela sur la terre la famine, Et priva son peuple de toute subsistance.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 17, 'Il envoya un homme pour précéder Israël: Joseph fut vendu comme esclave.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 18, 'On lui serra les pieds dans des entraves, Et il fut jeté dans les fers,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 19, 'Jusqu\'au jour où ce qu\'il avait dit arriva, Et où la parole de l\'Eternel montra ce qu\'il était.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 20, 'Alors le roi envoya délivrer Joseph; Le dominateur des peuples le fit élargir.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 21, 'Il l\'établit seigneur de sa maison Et gouverneur de tous ses biens,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 22, 'Pour commander en maître à ses princes Et enseigner à ses anciens la sagesse.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 23, 'Alors Israël vint en Egypte; Jacob séjourna dans le pays de Cham.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 24, 'Dieu multiplia son peuple d\'une façon prodigieuse, Et le rendit plus puissant que ses oppresseurs.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 25, 'Puis il changea le coeur des Égyptiens, qui haïrent son peuple Et traitèrent avec perfidie ses serviteurs.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 26, 'Il envoya Moïse, son serviteur, Et Aaron qu\'il avait élu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 27, 'Sur son ordre, ils accomplirent au milieu d\'eux des prodiges Et des miracles dans le pays de Cham.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 28, 'Ils firent surgir les ténèbres de la nuit, Pour ne pas désobéir à sa parole.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 29, 'Dieu changea, leurs fleuves en sang. Et il en fit mourir les poissons.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 30, 'Leur terre fourmilla de grenouilles. Jusque dans les chambres de leurs rois.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 31, 'Il dit; et l\'on vit paraître des insectes. Des moustiques, dans tout leur territoire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 32, 'Au lieu de pluie, il leur envoya de la grêle. Et des flammes de feu dans tout leur pays.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 33, 'Il frappa leurs vignes et leurs figuiers, Et il mit en pièces les arbres de leur territoire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 34, 'Il dit; et l\'on vit des sauterelles, Des criquets sans nombre,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 35, 'Qui dévorèrent toute l\'herbe de leurs champs, Qui ravagèrent les fruits de leur sol.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 36, 'Il frappa dans leur pays tous les premiers-nés, Prémices de leur virilité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 37, 'Puis Dieu fit sortir les Israélites, chargés d\'argent et d\'or. Et aucun d\'eux, parmi les tribus, ne resta en arrière.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 38, 'Les Égyptiens se réjouirent de leur départ; Car la frayeur s\'était emparée d\'eux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 39, 'L\'Éternel étendit la nuée pour couvrir les enfants d\'Israël, Ainsi que la colonne de feu pour les éclairer pendant la nuit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 40, 'A leur demande, il fit venir des cailles, Et il les rassasia du pain des cieux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 41, 'Il ouvrit le rocher, et les eaux en jaillirent: Elles coulèrent à travers le désert, comme un fleuve;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 42, 'Car il se souvenait de sa parole sainte. Et d\'Abraham, son serviteur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 43, 'Il fit avancer son peuple au milieu des cris d\'allégresse, Et ses élus au milieu des chants de triomphe.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 44, 'Il leur donna les terres des nations, Et il leur abandonna les fruits du labeur des peuples,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 45, 'A condition qu\'ils garderaient ses commandements Et pratiqueraient ses lois. Louez l\'Éternel!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 1, 'Et elle se referma sur la troupe d\'Abiram.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 2, 'Qui pourrait raconter les victoires de l\'Éternel, Et publier toutes ses louanges?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 3, 'Heureux ceux qui observent la justice, Qui font en tout temps ce qui est droit!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 4, 'Éternel, souviens-toi de moi, Toi qui es plein de bienveillance pour ton peuple. Viens, accorde-moi ton salut,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 5, 'Afin que j\'aie part au bonheur de tes élus, Que je me réjouisse de la joie de ton peuple. Et que je me glorifie avec ceux qui t\'appartiennent!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 6, 'Nous et nos pères, nous avons péché. Nous avons mal agi; nous sommes coupables!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 7, 'Nos pères, en Egypte, ne furent pas attentifs à tes miracles; Ils ne se souvinrent pas de la multitude de tes bontés; Mais ils se révoltèrent près de la mer, Sur les bords de la mer Rouge.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 8, 'Dieu les sauva, pour l\'amour de son nom, Afin de manifester sa puissance.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 9, 'Il menaça la mer Rouge, et elle fut mise à sec; Il les conduisit à travers les abîmes comme à travers le désert.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 10, 'Il les délivra des mains de l\'adversaire, Et les sauva des mains de l\'ennemi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 11, 'Les flots recouvrirent leurs oppresseurs: Aucun de ces derniers ne put échapper.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 12, 'Alors ils crurent aux promesses de Dieu, Et ils chantèrent ses louanges.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 13, 'Bientôt, ils oublièrent ses oeuvres; Ils n\'eurent pas confiance en ses desseins.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 14, 'Ils se laissèrent gagner par la convoitise dans le désert. Et ils tentèrent Dieu dans la solitude.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 15, 'Alors il accueillit favorablement leur demande, Mais il envoya parmi eux la mortalité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 16, 'Pendant qu\'ils campaient, ils furent jaloux de Moïse Et d\'Aaron, le saint de l\'Éternel.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 17, 'La terre s\'ouvrit; elle engloutit Dathan,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 18, 'Le feu dévora leur troupe; La flamme consuma les méchants.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 19, 'Ils firent un veau d\'or au pied de l\'Horeb, Et ils se prosternèrent devant une image de fonte.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 20, 'Ils échangèrent le Dieu qui était leur gloire, Contre l\'image d\'un boeuf qui broute l\'herbe.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 21, 'Ils oublièrent Dieu, leur libérateur. Qui avait accompli des prodiges en Egypte,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 22, 'Des merveilles dans le pays de Cham, Et des oeuvres redoutables sur la mer Rouge.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 23, 'Dieu parlait même de les anéantir; Mais Moïse, son élu, se tint sur la brèche en face de lui, Pour détourner sa colère et pour empêcher leur destruction.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 24, 'Ils méprisèrent une terre pleine de délices, Ne voulant pas croire à la promesse divine.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 25, 'Ils murmurèrent dans leurs tentes; Ils n\'écoutèrent pas la voix de l\'Éternel.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 26, 'Alors il leur fit le serment De les laisser périr dans le désert,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 27, 'De laisser périr leur postérité parmi les nations. De les disperser dans tous les pays.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 28, 'Ils s\'attachèrent à Baal-Péor, Et mangèrent les sacrifices offerts à des dieux sans vie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 29, 'Ils irritèrent Dieu par leurs crimes, Et la mortalité fondit sur eux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 30, 'Mais Phinées se leva; il intervint, Et le fléau fut arrêté.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 31, 'Son zèle lui fut imputé comme un acte de justice. Dans tous les âges, à perpétuité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 32, 'Ils excitèrent aussi le courroux de l\'Éternel Près des eaux de Mériba, Et Moïse fut affligé à cause d\'eux;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 33, 'Car ils aigrirent son esprit. De sorte qu\'il prononça des paroles imprudentes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 34, 'Ils ne détruisirent pas les peuples Que l\'Éternel leur avait ordonné d\'anéantir.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 35, 'Mais ils se mêlèrent aux autres nations. Et ils apprirent à faire comme elles.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 36, 'Ils servirent leurs idoles. Qui furent pour eux un piège,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 37, 'Et ils sacrifièrent aux démons leurs fils, Ainsi que leurs filles.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 38, 'Ils répandirent le sang innocent, Le sang de leurs fils et de leurs filles, Qu\'ils sacrifièrent aux idoles de Canaan; Et le pays fut profané par ces meurtres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 39, 'Ils se souillèrent par leurs actes impies, Et se déshonorèrent par leur conduite infâme.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 40, 'La colère de l\'Éternel s\'enflamma contre son peuple; Il prit en aversion son héritage.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 41, 'Il livra les Israélites entre les mains des nations; Ceux qui les haïssaient dominèrent sur eux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 42, 'Leurs ennemis les opprimèrent Et les firent plier sous leur pouvoir.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 43, 'Maintes fois, il les délivra; Mais eux se révoltaient, N\'obéissant qu\'à leurs mauvaises pensées, Et ils consommaient leur perte par leurs propres fautes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 44, 'Toutefois, il les regarda dans leur détresse, Quand il entendit leur cri.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 45, 'Il se souvint en leur faveur de son alliance. Et il les prit en pitié, dans sa grande miséricorde.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 46, 'Il leur fit trouver grâce Auprès de tous ceux qui les retenaient captifs.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 47, 'Sauve-nous, ô Éternel, notre Dieu, Et rassemble-nous du sein des nations. Afin que nous célébrions ton saint nom. Et que nous mettions notre gloire à te louer!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 48, 'Béni soit l\'Éternel, le Dieu d\'Israël, De siècle en siècle, Et que tout le peuple dise: Amen! Louez l\'Éternel!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 1, 'Célébrez l\'Éternel; car il est bon, Et sa miséricorde dure éternellement!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 2, 'Ainsi parleront les rachetés de l\'Éternel, Ceux qu\'il a rachetés de la main de l\'oppresseur,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 3, 'Et qu\'il a rassemblés de tous les pays, De l\'Orient et de l\'Occident, du Nord et du Midi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 4, 'Ils erraient dans le désert, sur un chemin solitaire; Ils ne trouvaient aucune ville qui pût leur servir de refuge.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 5, 'Ils étaient affamés et altérés; Leur âme défaillait en eux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 6, 'Alors ils ont crié vers l\'Éternel, dans leur détresse, Et il les a délivrés de leurs angoisses.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 7, 'Il les a conduits par le droit chemin, Jusque dans une ville qu\'ils ont habitée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 8, 'Qu\'ils célèbrent donc la bonté de l\'Éternel, Et ses miracles en faveur des enfants des hommes!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 9, 'Car il a rassasié l\'âme altérée. Et comblé de biens l\'âme affamée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 10, 'D\'autres habitaient dans les ténèbres Et dans l\'ombre de la mort; Ils étaient captifs et gémissaient dans les chaînes,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 11, 'Pour avoir été rebelles aux paroles de Dieu, Et avoir méprisé le conseil du Très-Haut.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 12, 'Il avait humilié leur coeur par la souffrance: Ils succombaient, sans que personne ne les secourût.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 13, 'Alors ils ont crié vers l\'Éternel, dans leur détresse, Et il les a délivrés de leurs angoisses.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 14, 'Il les a tirés des ténèbres et de l\'ombre de la mort; Il a brisé leurs chaînes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 15, 'Qu\'ils célèbrent donc la bonté de l\'Éternel, Et ses miracles en faveur des enfants des hommes!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 16, 'Car il a brisé les portes d\'airain, Et rompu les barreaux de fer.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 17, 'Insensés qu\'ils étaient! Ils portaient la peine De leurs transgressions et de leurs iniquités;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 18, 'Ils avaient en horreur toute nourriture; Ils touchaient aux portes de la mort.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 19, 'Alors ils ont crié vers l\'Éternel, dans leur détresse, Et il les a délivrés de leurs angoisses.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 20, 'Il a envoyé sa parole; il les a guéris, Et il les a retirés de leurs tombeaux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 21, 'Qu\'ils célèbrent donc la bonté de l\'Éternel, Et ses miracles en faveur des enfants des hommes!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 22, 'Qu\'ils offrent des sacrifices d\'actions de grâces Et racontent ses oeuvres avec des chants de triomphe!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 23, 'Ceux qui descendent sur la mer, dans des navires. Et qui trafiquent sur les grandes eaux,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 24, 'Ceux-là voient les oeuvres de l\'Éternel, Et ses merveilles dans les profondeurs de l\'abîme.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 25, 'Il parle, et il fait lever un vent de tempête, Qui soulève les vagues de la mer.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 26, 'Ils montent aux cieux; ils descendent aux abîmes; Leur âme se fond d\'angoisse.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 27, 'Ils ensemencent des champs, et ils plantent des vignes, Qui portent des fruits abondants.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 28, 'Alors ils ont crié vers l\'Éternel, dans leur détresse, Et il les a délivrés de leurs angoisses.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 29, 'Il fait succéder le calme à la tempête, Et les vagues s\'apaisent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 30, 'Ils se réjouissent de ce qu\'elles sont calmées. Et Dieu les conduit au port qu\'ils désiraient.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 31, 'Qu\'ils célèbrent donc la bonté de l\'Éternel, Et ses miracles en faveur des enfants des hommes!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 32, 'Qu\'ils l\'exaltent dans l\'assemblée du peuple! Qu\'ils le louent dans le conseil des anciens!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 33, 'L\'Éternel change les fleuves en désert, Les sources d\'eau en un sol aride,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 34, 'Et la terre fertile en lande salée, A cause de la méchanceté de ses habitants.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 35, 'Il change aussi le désert en étang, Et la terre aride en sources d\'eau.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 36, 'Il y fait habiter ceux qui étaient affamés: Ils fondent une ville pour y demeurer.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 37, 'Ils ensemencent des champs, et ils plantent des vignes, Qui portent des fruits abondants.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 38, 'Dieu les bénit: ils deviennent très nombreux, Et il ne laisse pas diminuer leur bétail.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 39, 'D\'autres sont amoindris et humiliés Par l\'oppression, le malheur et la souffrance.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 40, 'L\'Éternel répand le mépris sur les grands. Et les fait errer dans un désert sans route.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 41, 'Mais il délivre de leur affliction les malheureux, Et rend leurs familles nombreuses Comme de grands troupeaux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 42, 'A cette vue, les justes sont remplis de joie; Mais tous les injustes ont la bouche fermée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 43, 'Que celui qui est sage prenne garde à ces choses. Et qu\'il sache comprendre les bontés de l\'Éternel!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 1, 'Cantique. — Psaume de David. Mon coeur est bien disposé, ô Dieu! Mon âme est bien disposée pour chanter tes louanges!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 2, 'Réveillez-vous, ô mon luth et ma harpe! Je veux devancer l\'aurore.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 3, 'Je te célébrerai parmi les peuples, ô Éternel, Et je te louerai parmi les nations;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 4, 'Car ta bonté s\'élève au-dessus des cieux, Et ta fidélité jusqu\'aux nues.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 5, 'Dieu, élève-toi au-dessus des cieux, Et que ta gloire éclate sur toute la terre,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 6, 'Afin que tes bien-aimés soient délivrés! Sauve-moi par ta main droite, et exauce-moi!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 7, 'Dieu l\'a déclaré dans son sanctuaire: «Je triompherai! Sichem sera ma part; je mesurerai au cordeau La vallée de Succoth.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 8, 'Galaad est à moi; à moi Manassé! Éphraïm est le rempart de ma tête; Juda est mon sceptre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 9, 'Moab est le bassin dans lequel je me lave; Sur Édom je jette ma sandale. Au sujet du pays des Philistins Je pousse des cris de triomphe!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 10, 'Qui me conduira dans la ville forte? Qui me mènera jusqu\'au pays d\'Édom?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 11, 'N\'est-ce pas toi, ô Dieu, qui nous avais rejetés. Toi, ô Dieu, qui ne sortais plus à la tête de nos armées?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 12, 'Viens à notre secours! Délivre-nous de la détresse! Le secours de l\'homme n\'est que vanité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 13, 'Avec Dieu, nous aurons la victoire. Et c\'est lui qui écrasera nos adversaires.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 1, 'Au maître-chantre. — Psaume de David. Dieu, toi que célèbrent mes louanges, ne te tais point!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 2, 'Car le méchant et le perfide Ont ouvert la bouche contre moi; Ils me tiennent des discours mensongers.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 3, 'Ils m\'environnent de paroles de haine; Ils me font la guerre sans motif.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 4, 'En échange de mon affection, ils me traitent en ennemi, Et moi, je ne fais que prier.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 5, 'Ils m\'ont rendu le mal pour le bien, Et la haine pour l\'amour.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 6, 'Soumets mon adversaire au pouvoir du méchant; Qu\'un accusateur se dresse à sa droite!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 7, 'Quand on le jugera, qu\'il soit déclaré coupable, Et que sa prière lui soit comptée comme un péché!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 8, 'Que ses jours soient peu nombreux; Qu\'un autre prenne sa charge!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 9, 'Que ses fils soient orphelins, Et que sa femme devienne veuve!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 10, 'Que ses enfants soient vagabonds et mendiants; Qu\'ils aillent quêter loin de leurs maisons en ruines!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 11, 'Que le créancier jette le filet sur tout ce qu\'il possède; Que le produit de son travail soit la proie de l\'étranger.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 12, 'Qu\'aucun ami ne lui demeure fidèle; Que nul n\'ait pitié de ses orphelins.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 13, 'Que sa postérité soit exterminée; Que, dès la génération prochaine, son nom soit éteint! Que l\'iniquité de ses pères soit rappelée En présence de l\'Éternel,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 14, 'Et que le péché de sa mère ne soit point effacé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 15, 'Que leurs crimes soient toujours présents devant l\'Éternel, Et que l\'Éternel anéantisse leur mémoire sur la terre!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 16, 'Car cet homme ne s\'est pas souvenu D\'exercer la miséricorde; Il a persécuté le misérable, le pauvre. Celui qui a le coeur brisé, pour le faire mourir!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 17, 'Il a aimé la malédiction: qu\'elle tombe sur lui! Il n\'a point pris plaisir à la bénédiction: Qu\'elle s\'éloigne de lui!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 18, 'Qu\'il soit enveloppé de cette malédiction Comme d\'un manteau; Qu\'elle pénètre dans son corps comme de l\'eau, Et dans ses os comme de l\'huile!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 19, 'Qu\'elle soit comme l\'habit dont il se couvre, Comme une ceinture dont il soit toujours ceint!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 20, 'Tel sera, de la part de l\'Éternel, le salaire de mes ennemis, Et de ceux qui profèrent contre moi des paroles meurtrières.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 21, 'Mais toi, ô Éternel, mon Seigneur, agis en ma faveur, Pour l\'honneur de ton nom. Toi dont la grâce est si bienfaisante, délivre-moi!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 22, 'Car je suis misérable et pauvre, Et mon coeur est meurtri au dedans de moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 23, 'Je m\'en vais comme l\'ombre du soir qui s\'allonge; Je suis emporté comme la sauterelle.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 24, 'Mes genoux chancellent, affaiblis par le jeûne; Mon corps s\'épuise et s\'amaigrit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 25, 'Je suis pour mes ennemis un objet d\'opprobre; Dès qu\'ils m\'aperçoivent, ils hochent la tête!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 26, 'Aide-moi, ô Éternel, mon Dieu! Sauve-moi, dans ta bonté,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 27, 'Afin qu\'ils sachent que c\'est ta main, Que c\'est toi, ô Éternel, qui m\'as délivré.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 28, 'Ils maudissent; toi, tu béniras. Ils se dressent contre moi; mais ils seront couverts de honte. Et ton serviteur sera comblé de joie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 29, 'Que mes adversaires soient revêtus de confusion, Et enveloppés de leur honte comme d\'un manteau!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 30, 'Ma bouche célébrera hautement l\'Éternel: Je le louerai au milieu de la multitude;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 31, 'Car il se tient à la droite du pauvre, Pour le délivrer de ceux qui le condamnent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 1, 'Psaume de David. L\'Éternel a dit à mon Seigneur: «Assieds-toi à ma droite, Jusqu\'à ce que j\'aie contraint tes ennemis A te servir de marchepied.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 2, 'L\'Éternel étendra loin de Sion le sceptre de ta puissance: Tu exerceras ta domination sur tes ennemis!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 3, 'Ton peuple accourt plein d\'ardeur, Le jour où tu rassembles ton armée. Revêtue d\'ornements sacrés, Ta jeune milice vient à toi Comme une rosée qui naît du sein de l\'aurore.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 4, 'L\'Éternel en a fait le serment, et il ne s\'en repentira point: «Tu es sacrificateur pour toujours, A la façon de Melchisédec.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 5, 'Le Seigneur est à ta droite; Il écrasera les rois au jour de sa colère.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 6, 'Il jugera les nations; tout sera plein de cadavres. Il écrasera le chef qui domine sur un vaste pays.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 7, 'Il boira, sur la route, de l\'eau du torrent; Puis il marchera la tête haute.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 1, 'Louez l\'Éternel! Je célébrerai l\'Éternel de tout mon coeur. Dans le conseil et l\'assemblée des hommes droits.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 2, 'Les oeuvres de l\'Éternel sont grandes; Elles font l\'admiration de tous ceux qui les aiment.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 3, 'Ses actes font éclater sa splendeur et sa magnificence. Et sa justice demeure éternellement.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 4, 'Il a perpétué le souvenir de ses oeuvres merveilleuses. L\'Éternel est miséricordieux et compatissant:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 5, 'Il donne leur nourriture à ceux qui le craignent; Il se souvient toujours de son alliance.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 6, 'Il a montré à son peuple la puissance de ses oeuvres, En lui donnant l\'héritage des nations.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 7, 'Les oeuvres de ses mains ne sont que vérité et que justice. Et tous ses commandements sont immuables.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 8, 'Ils sont inébranlables pour toujours, à perpétuité; Car ils ont pour fondement la vérité et la droiture.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 9, 'Il a envoyé la délivrance à son peuple; Il a établi son alliance pour toujours. Son nom est saint et redoutable.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 10, 'La crainte de l\'Éternel est le commencement de la sagesse: Ceux qui observent ses lois sont vraiment sages. Sa louange subsiste éternellement.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 1, 'Louez l\'Éternel! Heureux l\'homme qui craint l\'Éternel, Qui trouve tout son plaisir dans ses commandements!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 2, 'Sa postérité sera puissante sur la terre; La race des hommes droits sera bénie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 3, 'L\'abondance et la richesse sont dans la maison du juste, Et sa justice demeure éternellement.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 4, 'La lumière se lève, même au sein des ténèbres, Pour l\'homme droit, Pour celui qui est compatissant, miséricordieux et juste.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 5, 'Heureux l\'homme compatissant. Celui qui prête aux malheureux: Il gagnera sa cause en justice;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 6, 'Car il ne sera jamais ébranlé. La mémoire du juste vivra éternellement.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 7, 'Il n\'a pas à craindre les bruits malveillants; Son coeur est ferme, plein de confiance en l\'Éternel.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 8, 'Son coeur est inébranlable, inaccessible à la crainte: Il verra un jour la confusion de ses ennemis.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 9, 'Il a distribué, il a donné ses biens aux pauvres; Sa justice demeure éternellement: Honoré de tous, il peut lever la tête.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 10, 'Le méchant voit avec envie le bonheur du juste; Il grince des dents et se consume: Ainsi sont frappés d\'impuissance les souhaits des méchants.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 1, 'Louez l\'Éternel! Serviteurs de l\'Éternel, louez, Louez le nom de l\'Éternel!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 2, 'Que le nom de l\'Éternel soit béni. Dès maintenant et à perpétuité!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 3, 'Du soleil levant au soleil couchant, Loué soit le nom de l\'Éternel!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 4, 'L\'Éternel est élevé au-dessus de tous les peuples; Sa gloire dépasse la hauteur des cicux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 5, 'Qui est semblable à l\'Éternel, notre Dieu? Il habite dans les lieux très hauts,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 6, 'Et il abaisse ses regards Sur le ciel et sur la terre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 7, 'Il relève le petit de la poussière, Et il retire le pauvre de la fange,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 8, 'Pour le faire asseoir avec les grands, Avec les grands de son peuple.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 9, 'A la femme qui était stérile, il donne la joie De se voir, dans sa maison, entourée de ses fils. Louez l\'Éternel!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 1, 'Quand Israël sortit de l\'Egypte, Quand la maison de Jacob se sépara d\'un peuple barbare,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 2, 'Juda devint le sanctuaire de l\'Éternel, Et Israël son empire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 3, 'A la vue du peuple de Dieu, la mer s\'enfuit; Le Jourdain retourna en arrière.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 4, 'Les montagnes bondirent comme des béliers, Et les collines comme des agneaux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 5, 'Qu\'avais-tu, ô mer, pour t\'enfuir, Et toi, Jourdain, pour retourner en arrière?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 6, 'Pourquoi bondir comme des béliers, ô montagnes. Et vous, collines, comme des agneaux?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 7, 'Terre, tremble devant le Seigneur, Devant le Dieu de Jacob,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 8, 'Qui change le rocher en nappe d\'eau, Le granit en source jaillissante.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 1, 'Non point à nous, ô Éternel, non point à nous. Mais à ton nom donne gloire; Car toi seul tu es bon et fidèle!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 2, 'Pourquoi les nations diraient-elles: «Où est donc leur Dieu?»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 3, 'Notre Dieu est dans les cieux; Il fait tout ce qui lui plaît!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 4, 'Leurs idoles sont des ouvrages d\'argent et d\'or, Des oeuvres faites par la main des hommes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 5, 'Elles ont une bouche, et elles ne parlent pas; Elles ont des yeux, et elles ne voient pas.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 6, 'Elles ont des oreilles, et elles n\'entendent pas; Elles ont un nez, et elles ne sentent pas;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 7, 'Des mains, et elles ne touchent pas; Des pieds, et elles ne marchent pas. Leur gosier ne fait entendre aucun son.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 8, 'Ceux qui les fabriquent et tous ceux qui se confient en elles Leur deviendront semblables.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 9, 'Israël, confie-toi en l\'Éternel! — Il est ton aide et ton bouclier. —');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 10, 'Maison d\'Aaron, confiez-vous en l\'Éternel! — Il est ton aide et ton bouclier. —');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 11, 'Vous qui craignez l\'Éternel, confiez-vous en l\'Éternel! — Il est votre aide et votre bouclier. —');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 12, 'L\'Éternel s\'est souvenu de nous: il bénira, Oui, il bénira la maison d\'Israël; Il bénira la maison d\'Aaron.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 13, 'Il bénira ceux qui craignent l\'Éternel, Tant les petits que les grands.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 14, 'L\'Éternel vous multipliera ses bénédictions. A vous et à vos enfants.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 15, 'Vous êtes bénis de l\'Éternel, Celui qui a fait les cieux et la terre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 16, 'Les cieux appartiennent à l\'Éternel; Mais il a donné la terre aux enfants des hommes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 17, 'Ce ne sont pas les morts qui loueront l\'Éternel, Ni aucun de ceux qui descendent dans le lieu du silence.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 18, 'Mais nous, nous bénirons l\'Éternel, Dès maintenant et à perpétuité. Louez l\'Éternel!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 1, 'J\'aime l\'Éternel, parce qu\'il a entendu Ma voix et mes supplications.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 2, 'Il a incliné son oreille vers moi; Aussi l\'invoquerai-je tous les jours de ma vie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 3, 'Les liens de la mort m\'avaient enveloppé. Les angoisses du Sépulcre m\'avaient saisi; J\'étais étreint par la souffrance et la douleur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 4, 'Alors j\'invoquai le nom de l\'Éternel: «Éternel, délivre mon âme!»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 5, 'L\'Éternel est miséricordieux et juste; Notre Dieu est plein de compassion.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 6, 'L\'Éternel garde les humbles: J\'étais misérable, et il m\'a sauvé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 7, 'Retrouve, ô mon âme, ta sérénité; Car l\'Éternel t\'a fait du bien.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 8, 'Oui, tu as préservé mon âme de la mort, Mes yeux, des pleurs, Et mes pieds de, toute chute.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 9, 'Je marcherai devant la face de l\'Éternel, Sur la terre des vivants.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 10, 'J\'ai cru, c\'est pourquoi j\'ai parlé! J\'ai été extrêmement affligé;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 11, 'Je disais dans mon trouble: «Tout homme est menteur!»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 12, 'Que rendrai-je à l\'Éternel? Tous ses bienfaits sont sur moi!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 13, 'Je lèverai la coupe d\'actions de grâces, Et j\'invoquerai le nom de l\'Éternel.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 14, 'Je m\'acquitterai de mes voeux envers l\'Éternel, En présence de tout son peuple.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 15, 'Elle a du prix aux yeux de l\'Éternel, La vie de ses bien-aimés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 16, 'Écoute, ô Éternel; car je suis ton serviteur, Ton serviteur, fils de ta servante. Tu as dénoué mes liens.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 17, 'Je t\'offrirai le sacrifice d\'actions de grâces, Et j\'invoquerai le nom de l\'Éternel.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 18, 'Je m\'acquitterai de mes voeux envers l\'Éternel, En présence de tout son peuple,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 19, 'Dans les parvis de la maison de l\'Éternel, Au milieu de toi, ô Jérusalem! Louez l\'Éternel!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 117, 1, 'Nations, louez toutes l\'Éternel. Peuples, célébrez-le tous!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 117, 2, 'Car sa bonté envers nous est grande. Et la fidélité de l\'Éternel demeure à perpétuité. Louez l\'Éternel!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 1, 'Célébrez l\'Éternel; car il est bon, Et sa miséricorde dure éternellement!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 2, 'Qu\'Israël dise: «Oui, sa miséricorde dure éternellement!»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 3, 'Que la maison d\'Aaron dise: «Sa miséricorde dure éternellement!»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 4, 'Que ceux qui craignent l\'Éternel disent: «Sa miséricorde dure éternellement!»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 5, 'Du sein de la détresse, j\'ai invoqué l\'Éternel; Il m\'a exaucé et m\'a mis au large.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 6, 'L\'Éternel est pour moi, je ne craindrai rien: Que pourraient me faire les hommes?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 7, 'L\'Éternel est pour moi, il est parmi mes défenseurs; Je verrai la confusion de mes ennemis!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 8, 'Mieux vaut se réfugier auprès de l\'Éternel, Que mettre sa confiance en l\'homme;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 9, 'Mieux vaut se réfugier auprès de l\'Éternel, Que mettre sa confiance dans les grands de la terre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 10, 'Toutes les nations m\'avaient assiégé; Au nom de l\'Éternel, je les ai détruites.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 11, 'Oui, elles m\'avaient assiégé, Elles m\'avaient cerné de toutes parts; Au nom de l\'Éternel, je les ai détruites.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 12, 'Elles m\'avaient entouré comme un essaim d\'abeilles; Elles ont été consumées comme un feu d\'épines. C\'est au nom de l\'Éternel que je les ai détruites.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 13, 'Mes ennemis s\'étaient jetés sur moi pour me faire tomber; Mais l\'Éternel m\'a secouru.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 14, 'L\'Éternel est ma force et le sujet de mes louanges; Il a été mon libérateur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 15, 'Un chant de triomphe et de délivrance S\'élève dans les tentes des justes. «La main de l\'Éternel agit avec puissance!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 16, 'La main de l\'Éternel est victorieuse; La main de l\'Éternel agit avec puissance!»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 17, 'Je ne mourrai point, mais je vivrai. Et je raconterai les oeuvres de l\'Éternel.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 18, 'L\'Éternel m\'a châtié sévèrement; Mais il ne m\'a pas livré à la mort.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 19, 'Ouvrez-moi les portes du Dieu de justice; J\'entrerai dans le temple et je célébrerai l\'Éternel.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 20, 'Voici la porte de l\'Éternel; Les justes entreront.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 21, 'Je te célébrerai, car tu m\'as exaucé, Et tu as été mon libérateur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 22, 'La pierre qu\'avaient rejetée ceux qui bâtissaient Est devenue la maîtresse pierre de l\'angle.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 23, 'Cela vient de l\'Éternel, Et c\'est une merveille à nos yeux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 24, 'Voici la journée que l\'Éternel a faite: Livrons-nous à la joie et à l\'allégresse!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 25, 'Éternel, délivre-nous! Éternel, donne-nous la prospérité!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 26, 'Béni soit celui qui vient au nom de l\'Éternel! Du seuil de la maison de l\'Éternel, nous vous bénissons.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 27, 'L\'Éternel est le Dieu fort, et il nous a éclairés. Liez les victimes avec des cordes, Et amenez-les jusqu\'aux angles de l\'autel.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 28, 'Tu es mon Dieu fort, je te célébrerai; Tu es mon Dieu, je t\'exalterai.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 29, 'Louez l\'Éternel; car il est bon, Et sa miséricorde dure éternellement!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 1, 'Heureux ceux dont la conduite est intègre, Et qui suivent la loi de l\'Éternel!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 2, 'Heureux ceux qui obéissent à ses enseignements, Qui le recherchent de tout leur coeur,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 3, 'Et qui ne commettent pas d\'iniquité, Mais qui marchent dans les voies de l\'Éternel!...');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 4, 'Tu as donné tes commandements, ô Dieu, Pour qu\'on les observe avec soin.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 5, 'Daigne diriger ma conduite, Afin que j\'observe tes préceptes!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 6, 'Alors je n\'aurai point à rougir, Quand je fixerai les regards sur tous tes commandements.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 7, 'Je te célébrerai dans la droiture de mon coeur. Quand j\'aurai appris tes justes jugements.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 8, 'Je veux observer tes préceptes; Ne m\'abandonne pas entièrement!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 9, 'Comment le jeune homme rendra-t-il pure sa conduite? C\'est en restant fidèle à ta parole.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 10, 'Je te cherche de tout mon coeur; Ne permets pas que je m\'égare loin de tes commandements!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 11, 'J\'ai serré ta parole dans mon coeur. Afin de ne pas pécher contre toi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 12, 'Béni sois-tu, ô Éternel! Enseigne-moi tes préceptes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 13, 'Mes lèvres énumèrent Tous les jugements que ta bouche a prononcés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 14, 'Je trouve autant de joie à suivre tes enseignements, Qu\'à posséder tous les trésors du monde.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 15, 'Je méditerai tes commandements, Et je fixerai mes regards sur tes sentiers.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 16, 'Je ferai mes délices de tes préceptes, Et je n\'oublierai point tes paroles.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 17, 'Accorde ce bienfait à ton serviteur: que je vive. Et que je garde ta parole!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 18, 'Dessille mes yeux. Afin que je contemple les merveilles de ta loi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 19, 'Je suis étranger sur la terre; Ne me cache pas tes commandements!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 20, 'Mon âme est consumée par l\'amour Que lui inspirent tes lois, en tout temps.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 21, 'Tu menaces les orgueilleux, Ces maudits qui s\'écartent de tes commandements.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 22, 'Éloigne de moi l\'opprobre et le mépris; Car j\'obéis à tes enseignements.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 23, 'Les puissants eux-mêmes se sont assis, Et ils ont parlé contre moi; Mais ton serviteur médite tes préceptes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 24, 'Oui, tes enseignements font mes délices: Ils sont mes meilleurs conseillers.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 25, 'Mon âme est abattue dans la poussière; Fais-moi revivre, selon ta parole!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 26, 'Je t\'ai fait connaître ma conduite, et tu m\'as approuvé; Enseigne-moi tes préceptes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 27, 'Montre-moi la voie que tu m\'ordonnes de suivre. Et je méditerai tes merveilles.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 28, 'Mon âme attristée se fond en larmes; Relève-moi, selon ta parole!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 29, 'Éloigne-moi de la voie du mensonge; Accorde-moi comme une grâce la connaissance de ta loi!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 30, 'J\'ai choisi la voie de la fidélité; J\'ai mis tes jugements devant mes yeux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 31, 'Je me suis attaché à tes enseignements: Éternel, ne me rends pas confus!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 32, 'Je m\'élancerai dans la voie de tes commandements, Quand tu auras mis mon coeur au large.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 33, 'Éternel, apprends-moi à suivre tes préceptes, Et je les observerai jusqu\'à la fin.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 34, 'Donne-moi l\'intelligence, et j\'observerai ta loi: Je la pratiquerai de tout mon coeur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 35, 'Conduis-moi dans les sentiers de tes commandements; Car mon bonheur est de les suivre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 36, 'Incline mon coeur vers tes enseignements. Et non pas vers le gain.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 37, 'Détourne mes yeux de la contemplation des choses vaines; Que je trouve la vie en marchant dans tes voies.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 38, 'Accomplis envers ton serviteur ta promesse: Tu l’as donnée pour qu’on te craigne.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 39, 'Détourne de moi l\'opprobre que je redoute; Car tes jugements sont pleins de bonté.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 40, 'J\'ai un ardent amour pour tes commandements! Fais-moi revivre par ta justice!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 41, 'Éternel, que tes bontés et ton salut Descendent sur moi, selon ta promesse!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 42, 'Alors je saurai comment répondre à celui qui m\'outrage; Car je me confie en ta parole.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 43, 'Ne me refuse pas entièrement la faveur De rendre témoignage à la vérité; Car je mets mon attente en tes jugements.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 44, 'Alors j\'observerai ta loi constamment. Sans l\'abandonner jamais.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 45, 'Je marcherai d\'un pas libre; Car j\'ai à coeur de suivre tes commandements.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 46, 'Je proclamerai tes volontés devant les rois. Et je n\'en aurai aucune honte.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 47, 'Je ferai mes délices de tes commandements: Ils sont l\'objet de mon amour.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 48, 'J\'élèverai mes mains vers tes commandements que j\'aime. Et je méditerai tes préceptes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 49, 'Souviens-toi de la parole donnée à ton serviteur C\'est sur elle que tu as fondé mon espérance.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 50, 'Ce qui me console dans mon affliction, C\'est que ta parole me rend la vie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 51, 'Des orgueilleux me couvrent de railleries; Mais je ne m\'écarte pas de ta loi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 52, 'Je me rappelle tes jugements d\'autrefois, ô Éternel, Et j\'y trouve ma consolation.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 53, 'L\'indignation me saisit, à cause des méchants Qui abandonnent ta loi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 54, 'Tes préceptes sont le sujet de mes cantiques, Dans la maison où j\'habite en étranger.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 55, 'La nuit, je me rappelle ton nom, ô Éternel, Et j\'observe ta loi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 56, 'Le bien qui m\'est échu en partage. C\'est de garder tes commandements.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 57, 'Tu es ma part, ô Éternel. C\'est pourquoi j\'ai promis de garder tes paroles.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 58, 'Je t\'ai imploré de tout mon coeur: Aie pitié de moi, selon ta promesse!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 59, 'J\'ai fait l\'examen de ma conduite, Et j\'ai dirigé mes pas dans la voie de tes enseignements.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 60, 'Je me hâte, je ne diffère point D\'observer tes commandements.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 61, 'Les pièges des méchants m\'ont environné; Je n\'ai point oublié ta loi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 62, 'Au milieu de la nuit, je me lève pour te célébrer, A cause de tes justes jugements.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 63, 'Je suis le compagnon de tous ceux qui te craignent Et qui observent tes commandements.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 64, 'Éternel, la terre est pleine de ta bonté! Enseigne-moi tes préceptes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 65, 'Tu as fait du bien à ton serviteur, Éternel, selon ta parole.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 66, 'Donne-moi un sens droit, ainsi que la vraie sagesse; Car j\'ai foi en tes commandements.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 67, 'Avant d\'être affligé, je m\'égarais; Mais, maintenant, j\'observe ta parole.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 68, 'Tu es bon, et tu manifestes ta bonté: Enseigne-moi tes préceptes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 69, 'Des orgueilleux ont ourdi contre moi des mensonges; Mais moi, j\'obéis de tout mon coeur à tes ordres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 70, 'Leur coeur est épaissi comme de la graisse; Moi, je trouve mes délices dans ta loi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 71, 'Il m\'est bon d\'avoir été affligé: C\'est ainsi que j\'ai appris à connaître ta volonté.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 72, 'Les enseignements de ta bouche sont plus précieux pour moi Que des milliers de pièces d\'or et d\'argent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 73, 'Toi dont les mains m\'ont formé et créé, Donne-moi l\'intelligence, afin que je puisse apprendre tes lois.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 74, 'Ceux qui te craignent me verront, et ils se réjouiront; Car j\'espère en ta parole.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 75, 'Je sais, ô Éternel, que tes jugements ne sont que justice: C\'est dans ta fidélité que tu m\'as affligé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 76, 'Que ta bonté soit donc ma consolation. Comme tu l\'as promis à ton serviteur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 77, 'Que tes compassions s\'étendent sur moi, et je vivrai; Car ta loi fait mes délices.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 78, 'Que les orgueilleux soient confus. Eux qui m\'oppriment sans motif; Et moi, je méditerai tes commandements.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 79, 'Qu\'ils reviennent à moi, ceux qui te craignent Et qui connaissent tes enseignements!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 80, 'Que mon coeur soit sincèrement attaché à tes préceptes, Afin que je n\'aie pas à rougir de honte!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 81, 'Mon âme languit après son salut; J\'espère en ta parole.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 82, 'Mes yeux se consument dans l\'attente de ta promesse; Je dis: «Quand me consoleras-tu?»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 83, 'Je suis comme une outre dans un nuage de fumée; Mais je n\'oublie pas tes préceptes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 84, 'Combien courte est la vie de ton serviteur! Quand donc feras-tu justice de ceux qui me persécutent?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 85, 'Les orgueilleux ont creusé des pièges sous mes pas; Car jamais ils n\'agissent selon ta loi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 86, 'Tous tes commandements témoignent de ta fidélité. Mes ennemis me persécutent sans motif; aide-moi!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 87, 'Encore un peu, et ils me faisaient disparaître de la terre! Mais je n\'abandonne pas tes commandements.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 88, 'Fais-moi revivre, toi qui es plein de bonté. Et j\'obéirai aux enseignements de ta bouche.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 89, 'Éternel, ta parole subsiste à jamais dans les cieux;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 90, 'Ta fidélité dure d\'âge en âge! Tu as fondé la terre, et elle demeure ferme.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 91, 'Tout subsiste aujourd\'hui selon tes lois; Car toutes choses te servent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 92, 'Si ta loi n\'eût fait mes délices. J\'aurais déjà péri dans ma misère.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 93, 'Jamais je n\'oublierai tes commandements; Car c\'est par eux que tu m\'as fait revivre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 94, 'Je suis à toi, sauve-moi; Car je m\'applique à suivre tes commandements.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 95, 'Les méchants m\'ont épié pour me faire périr; Mais je suis attentif à tes enseignements.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 96, 'J\'ai vu des bornes à tout ce qui est parfait; Mais ta loi est d\'une étendue sans fin.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 97, 'Combien j\'aime ta loi! Tout le jour, je m\'applique à la méditer.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 98, 'Tes commandements me rendent plus sage Que mes ennemis, Parce qu\'ils sont toujours présents à mon esprit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 99, 'J\'ai surpassé en sagesse tous ceux qui m\'avaient instruit; Car tes enseignements sont l\'objet de mes méditations.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 100, 'Je suis plus intelligent que les vieillards eux-mêmes; Car j\'ai gardé tes commandements.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 101, 'J\'ai détourné mes pas de tout mauvais chemin, Afin d\'observer ta parole.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 102, 'Je ne m\'écarte point de tes lois, Parce que c\'est toi qui m\'as instruit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 103, 'Combien tes paroles sont douces à mon palais, Plus douces que le miel à ma bouche!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 104, 'Tes commandements m\'instruisent; C\'est pourquoi je hais tous les sentiers trompeurs.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 105, 'Ta parole est un flambeau qui guide mes pas, Une lumière sur mon sentier.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 106, 'J\'ai juré — et je tiendrai ma promesse. — D\'observer tes justes lois.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 107, 'Je suis extrêmement affligé: Éternel, fais-moi revivre, selon ta parole!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 108, 'Agrée les chants de louange Que t\'offre ma bouche, ô Eternel, Et enseigne-moi tes commandements!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 109, 'Ma vie est continuellement en danger; Mais je n\'oublie point ta loi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 110, 'Les méchants m\'ont tendu des pièges; Mais je ne me suis pas écarté de tes commandements.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 111, 'Tes enseignements sont pour toujours mon héritage; Ils sont la joie de mon coeur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 112, 'J\'ai rendu mon coeur docile à l\'observation de tes préceptes, Pour toujours, jusqu\'à la fin.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 113, 'Je hais les hommes au coeur double; Mais j\'aime ta loi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 114, 'Tu es mon refuge et mon bouclier; J\'espère en ta parole.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 115, 'Retirez-vous de moi, méchants! Je veux garder les commandements de mon Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 116, 'Soutiens-moi, selon ta promesse, Afin que je vive, Et ne me fais pas rougir d\'avoir mis en toi mon espérance!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 117, 'Soutiens-moi: je serai sauvé. Et j\'aurai toujours les yeux sur tes préceptes!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 118, 'Tu traites avec mépris tous ceux qui s\'écartent de tes lois; Car toutes leurs machinations sont frappées d\'impuissance.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 119, 'Tu rejettes, comme de l\'écume. Tous les méchants de la terre. C\'est pourquoi j\'aime tes enseignements.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 120, 'Ma chair tremble de frayeur en ta présence. Et je crains tes jugements.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 121, 'J\'ai pratiqué ce qui est droit et juste; Ne m\'abandonne pas à mes oppresseurs!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 122, 'Prends sous ta garde le bonheur de ton serviteur; Que les orgueilleux ne m\'oppriment pas!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 123, 'Mes yeux se consument dans l\'attente de ton salut Et de tes promesses, ô Dieu juste.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 124, 'Agis envers ton serviteur selon ta bonté, Et enseigne-moi tes préceptes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 125, 'Je suis ton serviteur; donne-moi l\'intelligence, Afin que je puisse comprendre tes enseignements.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 126, 'Le temps est venu d\'agir en ta faveur, ô Éternel; Car on viole ta loi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 127, 'C\'est pourquoi j\'aime tes commandements Plus que l\'or, même que l\'or fin.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 128, 'Ainsi je proclame que tous tes commandements sont droits, Et je hais tout sentier trompeur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 129, 'Tes enseignements sont admirables; Aussi mon âme les met-elle en pratique.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 130, 'Tes paroles sont une révélation qui éclaire; Elles donnent de l\'intelligence aux simples.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 131, 'J\'ouvre la bouche et je soupire; Car j\'ai un grand amour pour tes commandements.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 132, 'Regarde-moi et prends pitié de moi, Comme tu le fais pour ceux qui aiment ton nom.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 133, 'Que ta parole affermisse mes pas. Et ne permets point que le péché domine sur moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 134, 'Délivre-moi de l\'oppression des hommes. Afin que j\'observe tes commandements!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 135, 'Fais resplendir ta face sur ton serviteur, Et enseigne-moi tes préceptes!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 136, 'Des ruisseaux de larmes coulent de mes yeux. Parce que personne n\'observe ta loi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 137, 'Tu es juste, ô Éternel, Et tes jugements sont droits.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 138, 'Tu prescris avec force, dans tes enseignements, La justice et la fidélité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 139, 'Mon zèle me consume, Parce que mes ennemis ont oublié tes paroles.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 140, 'Ta parole est parfaitement pure; Aussi est-elle chère à ton serviteur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 141, 'Je suis petit et méprisé; Mais je n\'oublie pas tes commandements.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 142, 'Ta justice est une justice éternelle, Et ta loi n\'est que vérité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 143, 'La détresse et l\'angoisse m\'ont atteint; Mais tes commandements font mes délices.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 144, 'Tes enseignements sont éternellement justes; Donne-m\'en l\'intelligence, afin que je vive!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 145, 'Je t\'invoque de tout mon coeur; réponds-moi, ô Éternel, Et je garderai tes préceptes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 146, 'Je crie vers toi; sauve-moi, Et je suivrai tes enseignements.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 147, 'Je devance l\'aurore, et je t\'invoque: Je mets mon espoir en ta parole.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 148, 'Mes yeux devancent les veilles de la nuit, Pour méditer ta promesse.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 149, 'Dans ta bonté, ô Éternel, écoute ma voix; Dans ta justice, fais-moi revivre!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 150, 'Les voilà près de moi, ceux qui se précipitent dans le crime Et qui se détournent de ta loi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 151, 'Mais toi aussi, ô Éternel, tu t\'approches de moi. Et tous tes commandements m\'assurent de ta fidélité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 152, 'Depuis longtemps j\'ai appris à connaître tes enseignements; Car tu les as établis pour toujours.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 153, 'Regarde mon affliction, et délivre-moi; Car je n\'ai pas oublié ta loi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 154, 'Défends ma cause, et délivre-moi; Fais-moi revivre, selon ta promesse!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 155, 'Le salut est loin des méchants. Parce qu\'ils ne se soucient pas de tes préceptes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 156, 'Tes compassions sont en grand nombre, ô Éternel: Fais-moi revivre, suivant les arrêts de ta justice!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 157, 'Mes persécuteurs et mes adversaires sont nombreux; Mais je ne me détourne pas de tes enseignements.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 158, 'J\'ai vu les infidèles, et j\'en ai horreur: Ils n\'observent pas ta parole.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 159, 'Vois combien j\'aime tes commandements; Éternel, fais-moi revivre, dans ta bonté!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 160, 'Ta parole tout entière n\'est que vérité, Et tous les arrêts de ta justice sont éternels.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 161, 'Les grands m\'ont persécuté sans motif; Mais mon coeur n\'a craint que tes paroles.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 162, 'Je me réjouis de ta promesse. Comme celui qui a trouvé un grand trésor.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 163, 'Je hais, j\'ai en horreur le mensonge. Et j\'aime ta loi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 164, 'Je te loue sept fois le jour. Pour les arrêts de ta justice.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 165, 'Grande est la paix de ceux qui aiment ta loi: Rien ne peut les faire chanceler.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 166, 'Éternel, j\'attends ta délivrance, Et je pratique tes commandements.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 167, 'Mon âme obéit à tes enseignements, Et je les aime d\'un grand amour.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 168, 'J\'observe tes commandements et tes lois; Car toute ma conduite est présente à tes yeux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 169, 'Éternel, que mon cri parvienne jusqu\'à toi! Donne-moi l\'intelligence, conformément à ta parole!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 170, 'Que ma supplication s\'élève jusqu\'à toi! Délivre-moi, suivant ta promesse!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 171, 'Mes lèvres proclameront ta louange, Quand tu m\'auras enseigné tes préceptes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 172, 'Ma langue célébrera ta parole; Car tous tes commandements sont justes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 173, 'Étends ta main pour me venir en aide; Car je veux obéir à tes commandements.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 174, 'Je soupire après ton salut, ô Éternel, Et ta loi fait mes délices.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 175, 'Que mon âme vive, afin qu\'elle te loue, Et que tes jugements soient mon appui!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 176, 'Je suis errant comme une brebis perdue: Viens à la recherche de ton serviteur! Car je n\'ai pas oublié tes commandements!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 1, 'Cantique des pèlerinages. J\'ai invoqué l\'Éternel dans ma détresse, Et il m\'a exaucé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 2, 'Éternel, délivre mon âme des lèvres menteuses, De la langue perfide!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 3, 'Quelle sera ta rétribution, Quel sera ton profit, langue perfide?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 4, '— Les flèches aiguës du guerrier, Avec les charbons ardents du genêt! —');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 5, 'Malheureux que je suis, de séjourner dans Mésec, De demeurer sous les tentes de Kédar!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 6, 'Trop longtemps mon âme a demeuré Parmi ceux qui haïssent la paix.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 7, 'Je veux la paix; mais, dès que j\'ouvre la bouche, Ils veulent la guerre!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 1, 'Cantique pour les pèlerinages. Je lève mes yeux vers les montagnes: D\'où me viendra le secours? —');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 2, '— Mon secours vient de l\'Éternel, Qui a fait les cieux et la terre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 3, 'Il ne permettra pas que ton pied chancelle; Celui qui te garde ne sommeillera point.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 4, 'Oui, celui qui garde Israël, Ne sommeillera pas; il ne s\'endormira point.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 5, 'l\'Éternel est celui qui te garde. l\'Éternel est ton ombre; il se tient à ta droite.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 6, 'Le soleil ne te frappera point pendant le jour, Ni la lune pendant la nuit,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 7, 'L\'Éternel te gardera de tout mal; Il gardera ton âme.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 8, 'L\'Éternel veillera sur ton départ comme sur ton arrivée. Dès maintenant et à toujours.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 1, 'Cantique des pèlerinages. — De David. Je me réjouis quand on me dit: «Allons à la maison de l\'Éternel!»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 2, 'Nos pas s\'arrêtent Dans tes portes, ô Jérusalem,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 3, 'Jérusalem, ville rebâtie. Dont les murailles n\'ont plus de brèche!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 4, 'C\'est là que montent les tribus, les tribus de l\'Éternel, Selon la loi donnée à Israël, Pour célébrer le nom de l\'Éternel.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 5, 'C\'est là que sont dressés les trônes de la justice. Les trônes de la maison de David.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 6, 'Priez pour la paix de Jérusalem! Que ceux qui t\'aiment vivent en sécurité!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 7, 'Que la paix soit dans tes murs. Et la sécurité dans tes palais!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 8, 'Pour l\'amour de mes frères et de mes amis, J\'invoque la paix sur toi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 9, 'Par amour pour la maison de l\'Éternel, notre Dieu, Je demande pour toi le bonheur!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 1, 'Cantique des pèlerinages. C\'est vers toi que je lève les yeux. Vers toi qui habites dans les cieux!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 2, 'De même que les yeux des serviteurs Sont fixés sur la main de leurs maîtres, Et les yeux de la servante sur la main de sa maîtresse. Ainsi nos regards se tournent vers l\'Éternel, notre Dieu, Jusqu\'à ce qu\'il ait pitié de nous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 3, 'Aie pitié de nous, ô Éternel, aie pitié de nous; Car nous avons été trop abreuvés de mépris!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 4, 'Trop longtemps notre âme a été abreuvée Des railleries des superbes, du mépris des orgueilleux!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 1, 'Cantique des pèlerinages. — De David. Si l\'Éternel n\'eût été pour nous — Israël peut bien le dire. —');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 2, 'Si l\'Éternel n\'eût été pour nous, Quand les hommes se levaient contre nous,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 3, 'Ils nous auraient engloutis tout vivants, Quand leur colère s\'enflammait contre nous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 4, 'Alors les eaux nous auraient submergés; Un torrent eût passé sur notre âme.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 5, 'Alors auraient passé sur notre âme Les flots orgueilleux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 6, 'Béni soit l\'Éternel, Qui ne nous a pas livrés en pâture aux dents de nos ennemis!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 7, 'Notre âme s\'est échappée, comme l\'oiseau, Du filet de l\'oiseleur; Le filet s\'est rompu, et nous nous sommes échappés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 8, 'Notre aide est dans le nom de l\'Éternel, Qui a fait les cieux et la terre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 1, 'Cantique des pèlerinages. Ceux qui se confient en l\'Éternel Sont comme la montagne de Sion, qui ne peut être ébranlée, Qui subsiste éternellement.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 2, 'Jérusalem est entourée de montagnes, Et l\'Éternel entoure son peuple. Dès maintenant et à perpétuité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 3, 'Car le sceptre des impies ne restera pas toujours étendu Sur l\'héritage des justes. De peur que les justes n\'en viennent eux-mêmes A prêter leurs mains à l\'iniquité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 4, 'Éternel, répands tes bienfaits sur les hommes de bien. Sur ceux qui ont le coeur droit!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 5, 'Mais ceux qui s\'écartent pour suivre des voies tortueuses, L\'Éternel les rejettera avec les ouvriers d\'iniquité. Que la paix soit sur Israël!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 1, 'Cantique des pèlerinages. Quand l\'Éternel ramena les captifs de Sion, Nous étions comme dans un rêve.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 2, 'Alors notre bouche remplit l\'air de cris joyeux, Et notre langue, de chants de triomphe. Alors on disait parmi les nations: L\'Éternel a accompli pour eux de grandes choses!»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 3, 'Oui, l\'Éternel a fait pour nous de grandes choses. Et nous sommes dans l\'allégresse.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 4, 'Éternel, ramène nos captifs, Comme la pluie ramène les ruisseaux dans la terre du Midi!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 5, 'Ceux qui sèment avec larmes Moissonneront avec des chants de triomphe.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 6, 'Il marche en pleurant Celui qui porte la semence pour la répandre; Mais il reviendra en poussant des cris de joie, Quand il portera ses gerbes!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 1, 'Cantique des pèlerinages. — De Salomon. Si l\'Éternel ne bâtit la maison. Ceux qui la bâtissent travaillent en vain. Si l\'Éternel ne garde la ville, Celui qui la garde veille en vain.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 2, 'C\'est en vain que vous vous levez matin ou vous couchez tard; En vain vous mangez le pain de la douleur; Dieu en donne autant à ses bien-aimés pendant leur sommeil!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 3, 'Oui, les enfants sont un héritage donné par l\'Éternel; Le fruit des entrailles est une récompense.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 4, 'Telles des flèches dans la main d\'un guerrier: Tels sont les fils que l\'homme a eus dans sa jeunesse.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 5, 'Heureux l\'homme qui en a rempli son carquois! Il ne rougira pas de honte. Quand il plaidera contre ses adversaires à la porte de la ville.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 1, 'Cantique des pèlerinages. Heureux l\'homme qui craint l\'Éternel, Et qui suit les voies qu\'il a tracées!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 2, 'Tu jouiras alors du travail de tes mains; Tu seras heureux et tu prospéreras.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 3, 'Ta femme sera comme une vigne fertile Dans l\'intérieur de ta maison, Et tes enfants comme des plants d\'olivier Autour de ta table.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 4, 'Oui, c\'est ainsi que sera béni L\'homme qui craint l\'Éternel.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 5, 'De Sion, l\'Éternel te bénira. Et tu verras le bonheur de Jérusalem, Tous les jours de ta vie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 6, 'Tu verras les enfants de tes enfants. Que la paix repose sur Israël!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 1, 'Cantique des pèlerinages. Mes ennemis m\'ont assez opprimé dès ma jeunesse, — Israël peut bien le dire! —');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 2, 'Ils m\'ont assez opprimé dès ma jeunesse; Mais ils ne m\'ont pas vaincu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 3, 'Des laboureurs ont labouré mon dos; Ils y ont tracé tout au long leurs sillons.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 4, 'Mais l\'Éternel est juste; Il a brisé les chaînes qu\'avaient préparées les méchants.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 5, 'Tous ceux qui haïssent Sion Seront couverts de honte et jetés au rebut.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 6, 'Ils seront comme l\'herbe des toits, Qui sèche avant de se former en tiges.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 7, 'Le moissonneur n\'en remplit pas sa main, Ni le lieur de gerbes ses bras.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 8, 'Aussi les passants ne leur disent-ils point: «La bénédiction de l\'Éternel soit sur vous! Nous vous bénissons au nom de l\'Éternel!»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 1, 'Cantique des pèlerinages. Du fond de l\'abîme, je t\'invoque, ô Éternel!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 2, 'Seigneur, écoute ma voix! Que tes oreilles soient attentives A ma voix suppliante!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 3, 'Éternel, si tu tiens compte des iniquités, Seigneur, qui subsistera?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 4, 'Mais le pardon se trouve auprès de toi. Afin qu\'on te craigne!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 5, 'J\'ai mis mon espoir en l\'Éternel; mon âme espère en lui, Et j\'ai confiance en sa parole.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 6, 'Mon âme attend le Seigneur, Plus que les sentinelles n\'attendent le matin, Oui, plus que les sentinelles n\'attendent le matin.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 7, 'Israël, mets ton espoir en l\'Éternel; Car en l\'Éternel se trouve la miséricorde, Et la rédemption abonde auprès de lui!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 8, 'C\'est lui qui délivrera Israël De toutes ses iniquités.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 1, 'Cantique des pèlerinages. — De David. Éternel, mon coeur ne s\'enfle pas d\'orgueil. Je n\'ai pas le regard altier; Je ne recherche pas les grandeurs; Je n\'aspire pas aux choses trop élevées pour moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 2, 'J\'impose à mon âme le calme et le silence. Comme l\'enfant gorgé de lait dort tranquille près de sa mère: Tel est l\'enfant rassasié, telle est mon âme.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 3, 'Israël, mets ton espoir en l\'Éternel, Dès maintenant et pour toujours!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 1, 'Cantique des pèlerinages. Éternel, souviens-toi de David Et de ses pénibles labeurs,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 2, 'Lui qui fit ce serment à l\'Éternel Et ce voeu au Puissant de Jacob:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 3, '«Je n\'entrerai pas dans la tente où j\'habite, Et je ne monterai pas sur le lit où je repose;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 4, 'Je ne donnerai pas de sommeil à mes yeux. Ni de repos à, mes paupières,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 5, 'Avant d\'avoir trouvé une résidence pour l\'Éternel, Une demeure pour le Puissant de Jacob!»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 6, 'Nous avions entendu dire que l\'arche était à Éphrath, Et nous l\'avons trouvée dans les champs de Jaar.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 7, 'Entrons dans la demeure de l\'Éternel; Prosternons-nous devant son marchepied;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 8, 'Lève-toi, ô Éternel, viens dans ton lieu de repos, Toi et l\'arche où ta majesté réside!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 9, 'Que tes sacrificateurs se parent de leurs vêtements sacrés, Et que tes fidèles poussent des cris de joie!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 10, 'Pour l\'amour de David, ton serviteur, Ne repousse pas la face de ton Oint!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 11, 'L\'Éternel a fait à David ce serment immuable, Et il ne le révoquera point: «Je mettrai sur ton trône un fils issu de toi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 12, 'Si tes enfants gardent mon alliance Et les enseignements que je leur donnerai, Leurs fils aussi, à perpétuité, Seront assis sur ton trône.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 13, 'L\'Éternel a fait choix de Jérusalem: Il a désiré en faire son séjour.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 14, '«Cette ville est le lieu de mon repos, à perpétuité; Elle est la résidence que j\'ai désirée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 15, 'Je remplirai de provisions ses greniers; Je rassasierai de pain ses indigents.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 16, 'Je donnerai pour vêtements à ses sacrificateurs Le salut qui vient de moi, Et ses fidèles pousseront des cris d\'allégresse.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 17, 'C\'est là que je ferai croître la puissance de David; C\'est là que j\'ai préparé un flambeau pour mon Oint.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 18, 'Je couvrirai de honte ses ennemis. Et sur sa tête brillera son diadème!»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 1, 'Cantique des pèlerinages. — De David. Oh! qu\'il est bon, qu\'il est doux Pour des frères, de se trouver réunis ensemble!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 2, 'C\'est comme l\'huile précieuse, répandue sur la tête. Qui coule sur la barbe, sur la barbe d\'Aaron, Qui coule jusqu\'au bord de ses vêtements.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 3, 'C\'est comme la rosée de l\'Hermon, Qui descend sur les collines de Sion; Car c\'est là que l\'Éternel envoie la bénédiction Et la vie, pour toujours!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 1, 'Cantique des pèlerinages. Bénissez l\'Éternel, vous tous, serviteurs de l\'Éternel, Qui vous tenez pendant la nuit dans la maison de l\'Éternel!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 2, 'Élevez vos mains vers le sanctuaire. Et bénissez l\'Éternel!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 3, 'Oui, que l\'Éternel te bénisse de Sion, Lui qui a fait les cieux et la terre!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 1, 'Louez l\'Éternel! Louez le nom de l\'Éternel; Louez-le, serviteurs de l\'Éternel,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 2, 'Qui vous tenez dans la maison de l\'Éternel, Dans les parvis de la maison de notre Dieu!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 3, 'Louez l\'Éternel; car l\'Éternel est bon! Psalmodiez à la gloire de son nom; car il est clément:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 4, 'L\'Éternel a choisi pour lui Jacob; Il a pris Israël pour son partage.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 5, 'Oui, je sais que l\'Éternel est grand, Et que notre Seigneur est au-dessus de tous les dieux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 6, 'L\'Éternel fait tout ce qui lui plaît, Dans les cieux et sur la terre. Dans les mers et dans tous les abîmes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 7, 'Il fait monter des extrémités de la terre les nuées; Il fait briller les éclairs au milieu même de la pluie; Il fait sortir le vent de ses réservoirs.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 8, 'C\'est lui qui a frappé les premiers-nés de l\'Egypte, Depuis les hommes jusqu\'aux bêtes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 9, 'Il a fait paraître au milieu de toi, ô Egypte, Des signes et des prodiges, Pour châtier Pharaon et tous ses serviteurs.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 10, 'Il a frappé de grandes nations. Et mis à mort de puissants rois:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 11, 'Sihon, roi des Amoréens. Og, roi de Basan, Et tous les rois de Canaan.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 12, 'Il a fait de leur territoire le patrimoine, Oui, le patrimoine d\'Israël, son peuple.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 13, 'Éternel, ton nom demeure à perpétuité; Éternel, ta mémoire dure d\'âge en âge!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 14, 'L\'Éternel fera droit à son peuple. Et il aura compassion de ses serviteurs.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 15, 'Les idoles des nations ne sont que de l\'argent et de l\'or. Oeuvres des mains de l\'homme,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 16, 'Elles ont une bouche, et elles ne parlent pas; Elles ont des yeux, et elles ne voient pas;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 17, 'Elles ont des oreilles, et elles n\'entendent pas, Et il n\'y a point de souffle dans leur bouche.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 18, 'Ceux qui les fabriquent, Et tous ceux qui mettent leur confiance en elles, Leur deviendront semblables!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 19, 'Maison d\'Israël, bénis l\'Éternel! Maison d\'Aaron, bénis l\'Éternel!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 20, 'Maison de Lévi, bénis l\'Éternel! Vous qui craignez l\'Éternel, bénissez l\'Éternel!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 21, 'Béni soit, de Sion, l\'Éternel Qui fait de Jérusalem sa demeure! Louez l\'Éternel!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 1, 'Célébrez l\'Éternel; car il est bon, Et sa miséricorde dure éternellement!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 2, 'Célébrez le Dieu des dieux; Car sa miséricorde dure éternellement!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 3, 'Célébrez le Seigneur des seigneurs; Car sa miséricorde dure éternellement!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 4, 'Lui seul accomplit de grandes merveilles; Car sa miséricorde dure éternellement!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 5, 'Il a créé les cieux avec sagesse; Car sa miséricorde dure éternellement!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 6, 'Il a étendu la terre sur les eaux; Car sa miséricorde dure éternellement!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 7, 'Il a fait les grands luminaires: — Car sa miséricorde dure éternellement! —');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 8, 'Le soleil pour régner sur le jour, — Car sa miséricorde dure éternellement! —');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 9, 'Ainsi que la lune et les étoiles pour régner sur la nuit; Car sa miséricorde dure éternellement!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 10, 'C\'est lui qui a frappé les premiers-nés des Égyptiens; Car sa miséricorde dure éternellement!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 11, 'Il a fait sortir Israël du\' milieu d\'eux; Car sa miséricorde dure éternellement!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 12, 'Grâce à sa main puissante, à son bras protecteur; Car sa miséricorde dure éternellement!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 13, 'Il a coupé en deux la mer Rouge; Car sa miséricorde dure éternellement!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 14, 'Il a fait passer Israël au milieu d\'elle; Car sa miséricorde dure éternellement!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 15, 'Il a renversé Pharaon et son armée dans la mer Rouge; Car sa miséricorde dure éternellement!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 16, 'Il a conduit son peuple par le désert; Car sa miséricorde dure éternellement!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 17, 'Il a frappé de grands rois; Car sa miséricorde dure éternellement!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 18, 'Il a mis à mort des rois puissants: — Car sa miséricorde dure éternellement! —');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 19, 'Sihon, roi des Amoréens, — Car sa miséricorde dure éternellement! —');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 20, 'Et Og, roi de Basan; Car sa miséricorde dure éternellement!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 21, 'Il a fait de leur territoire un patrimoine — Car sa miséricorde dure éternellement —');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 22, 'Le patrimoine d\'Israël, son serviteur; Car sa miséricorde dure éternellement!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 23, 'C\'est lui qui, dans notre abaissement, s\'est souvenu de nous; Car sa miséricorde dure éternellement!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 24, 'Il nous a délivrés de nos ennemis; Car sa miséricorde dure éternellement!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 25, 'Il donne la nourriture à tous les êtres vivants; Car sa miséricorde dure éternellement!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 26, 'Célébrez le Dieu des cieux; Car sa miséricorde dure éternellement!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 1, 'Sur les bords des fleuves de Babylone Nous étions assis et nous pleurions, En nous souvenant de Sion.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 2, 'Nous avions suspendu nos harpes Aux saules du rivage.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 3, 'Là, ceux qui nous avaient emmenés captifs Nous demandaient des cantiques, Et nos oppresseurs nous demandaient des chants joyeux: «Chantez-nous, disaient-ils, un cantique de Sion!»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 4, 'Comment chanterions-nous les cantiques de l\'Éternel, Sur la terre étrangère?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 5, 'Si je t\'oublie, Jérusalem, Que ma main droite soit frappée d\'impuissance!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 6, 'Que ma langue s\'attache à mon palais, Si je ne me souviens de toi. Si je ne mets pas Jérusalem Au-dessus de toutes mes joies!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 7, 'Souviens-toi, ô Éternel, des fils d\'Édom, Qui, le jour de la prise de Jérusalem, S\'écriaient: «Rasez, rasez Jusqu\'à ses fondements!»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 8, 'Fille de Babylone, vouée à la destruction, Heureux celui qui te rendra Le mal que tu nous as fait!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 9, 'Heureux celui qui saisira tes enfants. Et les écrasera contre le rocher!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 1, 'Psaume de David. Je te célébrerai de tout mon coeur; En présence des dieux, je chanterai tes louanges.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 2, 'Je me prosternerai devant ton saint temple, Et je célébrerai ton nom, à cause de ta bonté et de ta fidélité; Car tu as magnifiquement accompli ta promesse, Au-delà de ce que ton nom même faisait espérer.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 3, 'Le jour où je t\'ai invoqué, tu m\'as exaucé; Tu as rendu le courage et la force à mon âme.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 4, 'Tous les rois de la terre te célébreront, ô Éternel, Dès qu\'ils auront entendu les paroles de ta bouche.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 5, 'Ils glorifieront les desseins de l\'Éternel; Car la gloire de l\'Éternel est grande.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 6, 'Oui, l\'Éternel, qui est le Très-Haut, sait voir les humbles. Et il reconnaît de loin les superbes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 7, 'Si je passe par l\'adversité, tu me rendras la vie; Tu étendras ta main contre la fureur de mes ennemis, Et ta main droite me délivrera.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 8, 'L\'Éternel achèvera ce qu\'il a commencé en ma faveur. Éternel, ta bonté dure à toujours! N\'abandonne pas l\'oeuvre de tes mains!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 1, 'Au maître-chantre. — Psaume de David. Éternel, tu m\'as sondé, et tu m\'as connu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 2, 'Tu sais quand je m\'assieds et quand je me lève; Tu découvres de loin ma pensée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 3, 'Tu m\'observes, soit que je marche, soit que je me couche; Tu as une parfaite connaissance de toutes mes actions.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 4, 'Même avant que la parole soit sur ma langue, Déjà, ô Éternel, tu la connais tout entière.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 5, 'Tu es à mes côtés, et par derrière et par devant; Tu poses ta main sur moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 6, 'Une telle science est trop merveilleuse pour moi. Trop élevée pour que je puisse y atteindre!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 7, 'Où irais-je loin de ton Esprit, Où fuirais-je loin de ta face?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 8, 'Si je monte aux cieux, tu y es; Si je me couche dans le Sépulcre, t\'y voilà!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 9, 'Si je prenais les ailes de l\'aurore. Et si j\'allais demeurer à l\'extrémité de la mer,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 10, 'Là même, ta main me conduirait. Ta main droite me saisirait!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 11, 'Si je dis: «Seules les ténèbres pourront me cacher.» — Alors, la nuit même devient lumière autour de moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 12, 'Pour toi les ténèbres ne sont pas obscures: La nuit resplendit comme le jour, Et les ténèbres comme la lumière!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 13, 'Car c\'est toi qui as formé mes reins, Qui m\'as tissé dans le sein de ma mère.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 14, 'Je te loue de ce que tu as fait de mon corps Une oeuvre si étonnante et si merveilleuse. Oui, tes oeuvres sont merveilleuses, Et mon âme ne se lasse pas de le reconnaître.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 15, 'La structure de mon corps n\'était pas ignorée de toi, Lorsque j\'étais formé dans le secret, Et tissé comme dans des entrailles souterraines,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 16, 'Tes yeux m\'ont vu, lorsque je n\'étais qu\'un peloton. Et sur ton livre étaient inscrits Tous les jours qui m\'étaient réservés, Avant qu\'un seul de ces jours existât.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 17, 'Que tes pensées me sont précieuses, ô Dieu, Et combien leur nombre est immense!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 18, 'Pourrais-je les compter? Elles sont plus nombreuses que les grains de sable! Quand je me réveille, elles occupent encore mon esprit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 19, 'Dieu, ne feras-tu pas mourir le méchant? Hommes de sang, éloignez-vous de moi!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 20, 'Ils se servent de ton nom pour mal faire; Tes ennemis l\'invoquent pour mentir.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 21, 'Éternel, comment ne haïrais-je pas ceux qui te haïssent, Et n\'aurais-je pas en horreur ceux qui s\'élèvent contre toi?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 22, 'Je les hais d\'une parfaite haine; Je les tiens pour mes ennemis.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 23, 'Sonde-moi, ô Dieu fort, et connais mon coeur; Éprouve-moi, et connais mes pensées.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 24, 'Regarde si je suis sur une voie funeste. Et conduis-moi dans la voie de l\'éternité!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 1, 'Au maître-chantre. — Psaume de David. Éternel, délivre-moi de l\'homme méchant. Et préserve-moi de l\'homme violent,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 2, 'De ceux qui méditent le mal dans leur coeur. Et qui suscitent tous les jours des querelles;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 3, 'De ceux qui ont la langue affilée comme celle du serpent. Qui ont un venin d\'aspic sous leurs lèvres. Pause');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 4, 'Éternel, sauve-moi des mains du méchant; Préserve-moi de l\'homme violent. De ceux qui ne pensent qu\'à me faire tomber.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 5, 'Les orgueilleux ont dressé contre moi des pièges et des lacets; Ils ont tendu des filets sur le bord du chemin; Ils ont posé contre moi des embûches. Pause');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 6, 'J\'ai dit à l\'Éternel: Tu es mon Dieu! Prête l\'oreille, ô Éternel, à ma voix suppliante!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 7, 'Seigneur, Éternel, mon puissant libérateur, Tu protèges ma tête au jour de la bataille.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 8, 'Éternel, n\'exauce pas les souhaits du méchant; Ne laisse pas réussir ses desseins, De peur qu\'il n\'en tire vanité! Pause');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 9, 'Fais tomber sur la tête de ceux qui m\'assiègent Les maux dont leurs lèvres m\'ont menacé!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 10, 'Qu\'on jette sur eux des charbons embrasés! Qu\'on les précipite dans le feu, Dans les flots profonds d\'où ils ne pourront plus s\'échapper.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 11, 'Le calomniateur ne fera que passer sur la terre; Le malheur poursuivra sans relâche l\'homme violent;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 12, 'Mais je sais que l\'Éternel fera droit au misérable. Qu\'il fera justice au malheureux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 13, 'Oui, les justes célébreront ton nom; Les hommes droits seront en sécurité. En ta présence.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 1, 'Psaume de David. Éternel, je t\'invoque! Accours à mon aide; Prête l\'oreille à ma voix, quand je crie vers toi!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 2, 'Que ma prière te soit agréable comme l\'encens, Et mes mains tendues vers toi, comme l\'oblation du soir!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 3, 'Éternel, garde ma bouche; Veille sur mes lèvres quand elles s\'ouvrent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 4, 'Ne permets pas que mon coeur soit entraîné au mal, Et qu\'il commette des crimes avec les ouvriers d\'iniquité. Que je ne prenne aucune part à leurs festins!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 5, 'Que le juste me frappe, ce sera une faveur pour moi; Qu\'il me reprenne, ce sera de l\'huile sur ma tête; Ma tête ne se détournera pas! Car, même en face des persécutions des méchants. Je ne fais que prier.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 6, 'Leurs chefs seront précipités sur les flancs des rochers! Alors on écoutera mes paroles; Car elles sont pleines de douceur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 7, 'Comme la terre labourée et fendue par la charrue, Nos os sont dispersés à l\'entrée du Sépulcre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 8, 'C\'est vers toi, Éternel, ô Seigneur, Que se tournent mes regards. Je cherche un refuge auprès de toi: N\'abandonne pas mon âme!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 9, 'Garde-moi du piège qu\'ils m\'ont tendu, Et des embûches des ouvriers d\'iniquité!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 10, 'Puissent les méchants tomber dans leurs propres filets, Pendant que moi, je parviendrai à m\'enfuir!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 1, 'Hymne de David, lorsqu\'il était dans la caverne. — Prière. Ma voix crie vers l\'Éternel; Ma voix implore l\'Éternel.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 2, 'Je répands ma plainte devant lui; J\'expose ma détresse en sa présence.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 3, 'Quand je sens mon esprit défaillir en moi. Toi, tu connais le sentier où je marche. Dans le chemin où je m\'avance. On m\'a tendu un piège.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 4, 'Regarde à ma droite, et vois! Personne ne me reconnaît. Tout refuge me manque; Personne ne prend souci de moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 5, 'Je crie vers toi, ô Éternel, Et je dis: Tu es mon asile. Mon partage sur la terre des vivants.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 6, 'Sois attentif à mon cri; Car je suis extrêmement misérable. Délivre-moi de ceux qui me poursuivent; Car ils sont plus forts que moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 7, 'Retire mon âme de sa prison, Afin que je puisse célébrer ton nom! Les justes viendront triompher avec moi De ce que tu m\'auras comblé de tes bienfaits.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 1, 'Psaume de David. Éternel, écoute ma requête; prête l\'oreille à mes supplications. Réponds-moi, dans ta fidélité, dans ta justice!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 2, 'N\'entre pas en jugement avec ton serviteur; Car nul homme vivant ne peut être trouvé juste devant toi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 3, 'L\'ennemi en veut à ma vie; Il m\'a déjà terrassé; Il m\'a plongé dans les ténèbres. Comme ceux qui sont morts depuis longtemps.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 4, 'Je sens mon esprit défaillir en moi; Mon coeur est tout troublé au dedans de moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 5, 'Je me souviens des jours d\'autrefois; Je médite tout ce que tu as fait; Je pense aux oeuvres de tes mains.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 6, 'J\'étends mes mains vers toi; Mon âme a soif de toi; elle est comme une terre altérée. Pause');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 7, 'Éternel, hâte-toi de me répondre! Mon esprit se consume. Ne me cache pas ta face, Afin que je ne devienne pas semblable A ceux qui descendent dans la tombe!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 8, 'Fais-moi éprouver dès le matin ta bonté; Car j\'ai mis en toi ma confiance. Montre-moi le chemin où je dois marcher; Car j\'ai élevé mon âme vers toi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 9, 'Éternel, délivre-moi de mes ennemis; Je cherche un asile auprès de toi!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 10, 'Enseigne-moi à faire ta volonté; Car tu es mon Dieu. Que ton bon Esprit me conduise dans un chemin facile!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 11, 'Éternel, rends-moi la vie pour l\'amour de ton nom; Dans ta justice, retire mon âme de la détresse.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 12, 'Dans ta bonté, extermine mes ennemis, Et détruis tous ceux qui me persécutent; Car je suis ton serviteur!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 1, 'De David. Béni soit l\'Éternel, qui est mon rocher: Il exerce mes mains au combat. Et mes doigts à la bataille!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 2, 'Il est mon bienfaiteur et ma forteresse, Ma haute retraite et mon libérateur, Mon bouclier et mon refuge. Celui qui range mon peuple sous ma loi!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 3, 'Éternel, qu\'est-ce que l\'homme, Pour que tu prennes soin de lui, Et le fils de l\'homme, pour que tu en tiennes compte?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 4, 'L\'homme est semblable à un souffle; Ses jours sont comme l\'ombre qui passe.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 5, 'Éternel, abaisse tes cieux et descends; Touche les montagnes, et qu\'elles soient couvertes de fumée!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 6, 'Fais briller l\'éclair, et disperse mes ennemis: Lance tes flèches, et mets-les en déroute!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 7, 'Étends tes mains d\'en haut; Délivre-moi, et retire-moi des grandes eaux, De la main des fils de l\'étranger,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 8, 'Dont la bouche profère le mensonge, Dont la main droite est une main trompeuse.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 9, 'Dieu, je chanterai à ta gloire un cantique nouveau. Je te célébrerai sur la lyre à dix cordes,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 10, 'Toi qui donnes la délivrance aux rois, Qui sauves David, ton serviteur, de l\'épée meurtrière.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 11, 'Délivre-moi, et arrache-moi au joug des fils de l\'étranger, Dont la bouche ne profère que le mensonge. Dont la main droite est une main trompeuse!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 12, 'Que nos fils, dans leur jeune âge. Croissent comme des plants vigoureux. Que nos filles soient comme des colonnes sculptées. Qui ornent les angles d\'un palais!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 13, 'Que nos celliers soient pleins, Regorgeant de toutes sortes de biens. Que nos brebis se multiplient par milliers, par dix milliers. Dans nos campagnes!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 14, 'Que nos génisses soient fécondes! Qu\'il n\'y ait ni brèches dans nos murs, ni attaque, Ni cris d\'alarme dans nos places.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 15, 'Heureux le peuple dont tel est le partage! Heureux le peuple dont l\'Éternel est le Dieu!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 1, 'Louange. — De David. Mon Dieu, mon Roi, je t\'exalterai; Je bénirai ton nom éternellement, à perpétuité!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 2, 'Chaque jour je te bénirai; Je louerai ton nom éternellement, à perpétuité!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 3, 'L\'Eternel est grand et digne de toute louange, Et l\'on ne peut sonder sa grandeur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 4, 'Une génération dira la gloire de tes oeuvres A l\'autre génération, Et elles proclameront ta puissance.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 5, 'Je méditerai la splendeur glorieuse de ta majesté Et de tes actions merveilleuses.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 6, 'On célébrera tes oeuvres puissantes et redoutables, Et je raconterai ta grandeur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 7, 'On publiera la mémoire de ta grande bonté Et l\'on proclamera ta justice.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 8, 'L\'Eternel est miséricordieux et compatissant. Lent à la colère et riche en bonté.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 9, 'L\'Éternel est bon envers tous. Et ses compassions s\'étendent sur toutes ses oeuvres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 10, 'Éternel, toutes tes oeuvres te célébreront. Et tes fidèles te béniront.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 11, 'Ils diront la gloire de ton règne, Et ils raconteront ta puissance,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 12, 'Pour faire connaître aux fils des hommes tes prodiges Et la glorieuse majesté de ton règne.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 13, 'Ton règne est un règne de tous les siècles, Et ta domination dure d\'âge en âge.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 14, 'L\'Éternel soutient tous ceux qui tombent, Et il redresse tous ceux qui sont courbés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 15, 'Toutes les créatures ont les regards tournés vers toi, Et tu leur donnes, en temps opportun, leur nourriture.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 16, 'Tu ouvres ta main. Et tu rassasies à souhait tout être vivant.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 17, 'L\'Éternel est juste dans tous ses actes, Et miséricordieux dans toutes ses oeuvres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 18, 'L\'Éternel est près de tous ceux qui l\'invoquent, De tous ceux qui l\'invoquent avec sincérité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 19, 'Il accomplit les désirs de ceux qui le craignent; Il entend leur cri, et il les délivre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 20, 'L\'Éternel garde tous ceux qui l\'aiment; Mais il fera périr tous les méchants.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 21, 'Ma bouche publiera la louange de l\'Éternel, Et toute créature bénira son saint nom. Éternellement, à perpétuité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 1, 'Louez l\'Éternel! Mon âme, loue l\'Éternel!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 2, 'Je louerai l\'Éternel tant que je vivrai; Je célébrerai mon Dieu, tant que j\'existerai.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 3, 'Ne mettez pas votre confiance dans les grands de la terre, Ni dans les hommes mortels, qui ne sauraient délivrer.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 4, 'Leur souffle s\'en va: ils retournent à la poussière. Et ce jour-là, leurs desseins sont anéantis.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 5, 'Heureux l\'homme qui a le Dieu de Jacob pour appui, Et qui met son espoir en l\'Éternel, son Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 6, 'C\'est le Dieu qui a fait les cieux et la terre, La mer et tout ce qui s\'y trouve; Qui demeure fidèle éternellement;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 7, 'Qui fait droit aux opprimés; Qui donne de la nourriture à ceux qui ont faim.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 8, 'L\'Éternel rend la liberté aux captifs; L\'Éternel ouvre les yeux des aveugles; L\'Éternel redresse ceux qui sont courbés; L\'Éternel aime les justes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 9, 'L\'Éternel protège les étrangers; Il soutient l\'orphelin et la veuve; Mais il rend tortueuse la voie suivie par les méchants.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 10, 'L\'Éternel régnera éternellement. Sion, ton Dieu subsiste d\'âge en âge! Louez l\'Éternel!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 1, 'Louez l\'Éternel! Car il est bon de chanter à la gloire de notre Dieu! Oui, il est doux, il est beau de le louer!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 2, 'C\'est l\'Éternel qui rebâtit Jérusalem, Qui rassemble les dispersés d\'Israël;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 3, 'Qui guérit ceux qui ont le coeur brisé, Et qui bande leurs plaies.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 4, 'Il compte le nombre des étoiles; Il les appelle toutes par leur nom.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 5, 'Notre Seigneur est grand, et grande est sa puissance; Son intelligence est infinie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 6, 'L\'Éternel soutient les humbles. Et il abaisse les méchants jusqu\'à terre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 7, 'Célébrez les louanges de l\'Éternel; Psalmodiez sur la harpe en l\'honneur de notre Dieu!.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 8, 'C\'est lui qui couvre les cieux de nuées. Qui prépare la pluie pour la terre, Qui fait germer l\'herbe sur les montagnes,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 9, 'Qui donne leur nourriture aux troupeaux Et aux petits du corbeau, que la faim fait crier.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 10, 'Ce n\'est pas la vigueur du cheval qui lui est agréable; Ce n\'est pas l\'agilité à la course qui lui plaît.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 11, 'L\'Éternel a de l\'affection pour ceux qui le craignent. Pour ceux qui mettent leur espoir dans sa bonté.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 12, 'Jérusalem, loue l\'Éternel! Sion, célèbre ton Dieu!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 13, 'Car il a renforcé les verrous de, tes portes; Il a béni tes enfants au milieu de toi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 14, 'Il donne la paix à ton territoire; Il te rassasie de la fleur du froment.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 15, 'Il envoie ses ordres sur la terre. Et sa parole court avec rapidité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 16, 'Il fait tomber la neige comme de la laine. Et répand le givre comme de la cendre;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 17, 'Il jette les glaçons comme par morceaux: Qui peut résister à ses frimas?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 18, 'Dès qu\'il en a donné l\'ordre, la glace fond aussitôt; Dès que son souffle a passé, les eaux recommencent à couler.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 19, 'Il a révélé sa parole à Jacob, Ses préceptes et ses commandements à Israël.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 20, 'Il n\'a fait cela pour aucune des autres nations: Elles ne connaissent pas ses lois. Louez l\'Éternel!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 1, 'Louez l\'Éternel! Louez l\'Éternel du haut des cieux; Louez-le dans les lieux très hauts!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 2, 'Louez-le, vous, tous ses anges! Louez-le, vous, toutes ses armées!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 3, 'Louez-le, soleil et lune; Louez-le, vous toutes, étoiles brillantes!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 4, 'Louez-le, cieux des cieux, Et vous aussi, océans suspendus au-dessus des cieux!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 5, 'Que toutes ces choses louent le nom de l\'Éternel; Car il a commandé, et elles ont été créées.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 6, 'Il les a établies pour toujours, à perpétuité; Il leur a donné une loi qu\'elles ne violeront point.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 7, 'Louez l\'Éternel, du sein de la terre, Vous, monstres marins, et vous tous, abîmes,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 8, 'Foudre et grêle, neige et vapeurs. Vents de tempête qui exécutez sa parole,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 9, 'Montagnes et collines. Arbres à fruits et vous tous, cèdres,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 10, 'Bêtes sauvages et animaux de toute espèce. Reptiles, et vous, oiseaux qui volez dans l\'espace,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 11, 'Rois de la terre, et vous tous, peuples, Princes et juges de la terre,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 12, 'Jeunes hommes, et vous, jeunes filles, Vieillards et enfants!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 13, 'Qu\'ils louent le nom de l\'Éternel; Car son nom seul est grand: Sa majesté dépasse la terre et les cieux!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 14, 'Il a relevé la puissance de son peuple; Aussi montent vers lui les louanges de tous ses fidèles, Des enfants d\'Israël, du peuple qui lui appartient. Louez l\'Éternel!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 1, 'Louez l\'Éternel! Chantez à la gloire de l\'Éternel un cantique nouveau; Chantez ses louanges dans l\'assemblée de ses fidèles!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 2, 'Qu\'Israël se réjouisse en celui qui l\'a créé! Que les enfants de Sion tressaillent d\'allégresse en leur Roi!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 3, 'Qu\'ils louent son nom avec des danses; Qu\'ils le chantent avec le tambourin et la harpe!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 4, 'Car l\'Éternel prend plaisir en son peuple; Il donne aux humbles le salut pour parure.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 5, 'Que ses fidèles triomphent, comblés de gloire; Qu\'ils poussent des cris de joie, jusque sur leur lit de repos!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 6, 'Les louanges de Dieu sont dans leur bouche. Et l\'épée à deux tranchants dans leur main,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 7, 'Pour exercer la vengeance parmi les nations, Et pour châtier les peuples;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 8, 'Pour lier les rois avec des chaînes. Et les grands avec des entraves de fer;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 9, 'Pour exécuter le jugement qui a été prononcé contre eux! Telle est la gloire que Dieu réserve à tous ses fidèles. Louez l\'Éternel!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 1, 'Louez l\'Éternel! Louez Dieu dans son sanctuaire. Louez-le dans le firmament, où éclate sa puissance!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 2, 'Louez-le pour ses oeuvres merveilleuses; Louez-le pour sa grandeur infinie!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 3, 'Louez-le au son de là trompette; Louez-le avec la lyre et la harpe!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 4, 'Louez-le avec le tambourin et les danses; Louez-le avec les instruments à cordes et avec la flûte!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 5, 'Louez-le avec les cymbales sonores; Louez-le avec les cymbales retentissantes!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 6, 'Que tout ce qui respire loue l\'Éternel! Louez l\'Éternel!');
