INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 1, 'Généalogie de Jésus-Christ, fils de David, fils d\'Abraham:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 2, 'Abraham fut père d\'Isaac; Isaac, de Jacob; Jacob, de Juda et de ses frères.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 3, 'Juda eut de Thamar Pharez et Zara. Pharez fut père d\'Esrom; Esrom, d\'Aram;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 4, 'Aram, d\'Aminadab; Aminadab, de Naasson; Naasson, de Salmon.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 5, 'Salmon eut de Rahab Booz. Booz eut de Ruth Obed.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 6, 'Obed fut père de Jessé; Jessé, du roi David. David fut père de Salomon, qu\'il eut de la femme d\'Urie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 7, 'Salomon fut père de Roboam; Roboam, d\'Abia; Abia, d\'Asa;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 8, 'Asa, de Josaphat; Josaphat, de Joram; Joram, d\'Ozias.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 9, 'Ozias fut père de Joatham; Joatham, d\'Achaz; Achaz, d\'Ézéchias.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 10, 'Ezéchias fut père de Manassé; Manassé, d\'Amos; Amos, de Josias.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 11, 'Josias fut père de Jéchonias et de ses frères, au temps de la déportation à Babylone.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 12, 'Après la déportation à Babylone, Jéchonias fut père de Salathiel; Salathiel, de Zorobabel;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 13, 'Zorobabel, d\'Abiud; Abiud, d\'Éliakim; Éliakim, d\'Azor.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 14, 'Azor fut père de Sadoc; Sadoc, d\'Achim; Achini, d\'Éliud;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 15, 'Éliud, d\'Éléazar; Éléazar, de Matthan; Matthan, de Jacob.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 16, 'Jacob fut père de Joseph, l\'époux de Marie, de laquelle est né Jésus, qui est appelé Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 17, 'Il y a donc en tout, depuis Abraham jusqu\'à David, quatorze générations; depuis David jusqu\'à la déportation à Babylone, quatorze générations; et de la déportation à Babylone jusqu\'au Christ, quatorze générations.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 18, 'Voici comment arriva la naissance de Jésus-Christ: Marie, sa mère, ayant été fiancée à Joseph, se trouva avoir conçu par la vertu de l\'Esprit saint, avant qu\'ils eussent habité ensemble.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 19, 'Alors Joseph, son époux, qui était homme de bien et ne voulait pas l\'exposer à la honte, résolut de la répudier sans bruit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 20, 'Mais, comme il y pensait, voici qu\'un ange du Seigneur lui apparut en songe et lui dit: Joseph, fils de David, ne crains point de prendre Marie pour ta femme; car l\'enfant qu\'elle a conçu vient de l\'Esprit saint.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 21, 'Elle enfantera un fils, et tu lui donneras le nom de Jésus; car c\'est lui qui sauvera son peuple de ses péchés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 22, 'Tout cela arriva afin que s\'accomplît ce que le Seigneur avait dit par la bouche du prophète:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 23, '«La vierge enfantera et mettra au monde un fils, qu\'on nommera Emmanuel» — ce qui signifie: Dieu avec nous. —');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 24, 'Joseph, s\'étant réveillé de son sommeil, fit comme l\'ange du Seigneur lui avait commandé, et il prit sa femme avec lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 25, 'Mais il ne la connut point, jusqu\'à ce qu\'elle eût enfanté un fils, auquel il donna le nom de Jésus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 1, 'Jésus étant né à Bethléhem, en Judée, aux jours du roi Hérode, des mages d\'Orient arrivèrent à Jérusalem,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 2, 'et ils dirent: Où est le roi des Juifs qui vient de naître? Car nous avons vu son étoile en Orient, et nous sommes venus l\'adorer.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 3, 'A cette nouvelle, le roi Hérode fut troublé, et tout Jérusalem avec lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 4, 'Ayant rassemblé tous les principaux sacrificateurs et les scribes du peuple, il s\'informa auprès d\'eux du lieu où le Christ devait naître.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 5, 'Ils lui dirent: C\'est à Bethléhem, en Judée; car voici ce qui a été écrit par le prophète:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 6, '«Et toi, Bethléhem, terre de Juda, tu n\'es certainement pas la moindre entre les principales villes de Juda; car c\'est de toi que sortira le chef qui paîtra Israël, mon peuple».');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 7, 'Alors Hérode, ayant appelé les mages en secret, s\'enquit exactement auprès d\'eux du temps où l\'étoile était apparue;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 8, 'et, les envoyant à Bethléhem, il leur dit: Allez, prenez des informations exactes sur ce petit enfant; et, quand vous l\'aurez trouvé, faites-le-moi savoir, afin que j\'aille, moi aussi, l\'adorer.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 9, 'Après avoir entendu le roi, les mages partirent. Et voici que l\'étoile, qu\'ils avaient vue en Orient, allait devant eux, jusqu\'au moment où, arrivée au-dessus du lieu où se trouvait le petit enfant, elle s\'arrêta.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 10, 'A la vue de l\'étoile, ils eurent une fort grande joie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 11, 'Etant entrés dans la maison, ils virent le petit enfant avec Marie, sa mère; et, se prosternant devant lui, ils l\'adorèrent. Puis ils ouvrirent leurs trésors, et ils lui présentèrent des dons, de l\'or, de l\'encens et de la myrrhe.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 12, 'Ensuite, ayant été divinement avertis par un songe de ne pas retourner auprès d\'Hérode, ils revinrent dans leur pays par un autre chemin.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 13, 'Après qu\'ils furent partis, voici qu\'un ange du Seigneur apparut en songe à Joseph et lui dit: Lève-toi! Prends le petit enfant et sa mère, fuis en Egypte, et tu y resteras jusqu\'à ce que je te parle; car Hérode cherchera le petit enfant pour le faire mourir.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 14, 'Alors Joseph, s\'étant levé, prit pendant la nuit le petit enfant et sa mère; et il se retira en Egypte.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 15, 'Il y demeura jusqu\'à la mort d\'Hérode; ainsi fut accompli ce que le Seigneur avait dit par le prophète: «J\'ai appelé mon fils hors d\'Egypte».');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 16, 'Quand Hérode vit qu\'il avait été joué par les mages, il fut fort en colère; et il envoya tuer tous les enfants qui étaient dans Bethléhem et dans tout son territoire, depuis l\'âge de deux ans et au-dessous, d\'après la date exacte que les mages lui avaient fait connaître.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 17, 'Alors s\'accomplit ce qui avait été dit par Jérémie, le prophète:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 18, '«Un cri a été entendu dans Rama, des lamentations et de grands gémissements: c\'est Rachel qui pleure ses enfants, et elle ne veut pas être consolée, parce qu\'ils ne sont plus!»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 19, 'Mais après qu\'Hérode fut mort, voici qu\'un ange du Seigneur apparut en songe à Joseph, en Egypte; et il lui dit:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 20, 'Lève-toi, prends le petit enfant et sa mère, et retourne dans le pays d\'Israël; car ceux qui en voulaient à la vie du petit enfant sont morts.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 21, 'Joseph, s\'étant levé, prit le petit enfant et sa mère, et il rentra dans le pays d\'Israël.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 22, 'Mais quand il sut qu\'Archélaüs régnait sur la Judée à la place d\'Hérode, son père, il n\'osa pas y aller. Ayant été divinement averti en songe, il se retira dans le territoire de la Galilée,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 23, 'et il alla demeurer dans une ville appelée Nazareth. Ainsi fut accompli ce qui avait été dit par les prophètes: «Il sera appelé Nazaréen!»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 1, 'En ce temps-là parut Jean-Baptiste, prêchant dans le désert de la Judée;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 2, 'et il disait: Repentez-vous, car le royaume des cieux est proche!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 3, 'C\'est de lui qu\'Ésaïe le prophète a parlé, quand il a dit: «Une voix crie dans le désert: Préparez le chemin du Seigneur! aplanissez ses sentiers.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 4, 'Or, Jean avait un vêtement de poil de chameau et une ceinture de cuir autour des reins; il se nourrissait de sauterelles et de miel sauvage.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 5, 'Alors les habitants de Jérusalem, de toute la Judée et de toute la région environnant le Jourdain, accouraient auprès de lui;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 6, 'et, confessant leurs péchés, ils étaient baptisés par lui dans les eaux du Jourdain.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 7, 'Comme il voyait beaucoup de pharisiens et de sadducéens venir à son baptême, il leur dit: Race de vipères, qui vous a appris à fuir la colère à venir?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 8, 'Produisez donc des fruits dignes d\'une vraie repentance.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 9, 'Et n\'allez pas dire en vous-mêmes: Nous avons Abraham pour père! Car je vous déclare que, de ces pierres. Dieu peut faire naître des enfants à Abraham.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 10, 'Déjà la cognée est mise à la racine des arbres; tout arbre donc, qui ne produit pas de bons fruits, va être coupé et jeté au feu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 11, 'Quant à moi, je vous baptise d\'eau, pour la repentance; mais celui qui vient après moi est plus puissant que moi, et je ne suis pas digne de porter ses chaussures: c\'est lui qui vous baptisera d\'Esprit saint et de feu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 12, 'Il a son van dans sa main; il nettoiera parfaitement son aire, et il amassera son froment dans le grenier. Mais il brûlera la paille au feu qui ne s\'éteint point.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 13, 'Alors Jésus vint de la Galilée au Jourdain vers Jean, pour être baptisé par lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 14, 'Mais Jean s\'y opposait, en disant: C\'est moi qui ai besoin d\'être baptisé par toi, et tu viens à moi!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 15, 'Jésus lui répondit: Laisse faire pour le moment; car il est convenable que nous accomplissions ainsi toute justice.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 16, 'Alors Jean le laissa faire. Dès qu\'il eût été baptisé, Jésus sortit de l\'eau; et voici que les cieux s\'ouvrirent, et il vit l\'Esprit de Dieu descendre comme une colombe et venir sur lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 17, 'Aussitôt une voix se fit entendre des cieux, disant: Celui-ci est mon Fils bien-aimé, en qui j\'ai mis toute mon affection.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 1, 'Alors Jésus fut emmené par l\'Esprit dans le désert, pour être tenté par le Diable.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 2, 'Il jeûna quarante jours et quarante nuits; et après cela, il eut faim.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 3, 'Le tentateur, s\'approchant, lui dit: Si tu es le Fils de Dieu, ordonne que ces pierres deviennent des pains.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 4, 'Jésus répondit: Il est écrit: «L\'homme ne vivra pas seulement de pain, mais de toute parole qui sort de la bouche de Dieu»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 5, 'Alors le Diable le transporta dans la ville sainte; il le mit sur le faîte du temple,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 6, 'et il lui dit: Si tu es le Fils de Dieu, jette-toi en bas; car il est écrit: «Il ordonnera à ses anges de veiller sur toi, et ils te porteront dans leurs mains, de peur que ton pied ne heurte contre quelque pierre.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 7, 'Jésus lui dit: Il est aussi écrit: «Tu ne tenteras point le Seigneur, ton Dieu.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 8, 'Le Diable le transporta encore sur une montagne très haute; il lui montra tous les royaumes du monde et leur gloire,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 9, 'et il lui dit: Je te donnerai toutes ces choses, si, te prosternant devant moi, tu m\'adores.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 10, 'Alors Jésus lui dit: Retire-toi, Satan! Car il est écrit: «Tu adoreras le Seigneur, ton Dieu, et tu ne rendras de culte qu\'à lui seul.».');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 11, 'Alors le Diable le laissa; et voici que des anges s\'approchèrent, et ils se mirent à le servir.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 12, 'Or, Jésus, ayant appris que Jean avait été mis en prison, se retira dans la Galilée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 13, 'Il quitta Nazareth et vint demeurer à Capernaüm, ville proche de la mer, sur les confins de Zabulon et de Nephthali.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 14, 'Ainsi fut accompli ce qui avait été dit par Ésaïe, le prophète:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 15, '«La terre de Zabulon et de Nephthali, sur le chemin de la mer, — le pays au delà du Jourdain, la Galilée des Païens.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 16, '— ce peuple, assis dans les ténèbres, a vu resplendir une grande lumière; et sur ceux qui étaient assis dans la région et dans l\'ombre de la mort, une lumière s\'est levée!»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 17, 'Dès lors, Jésus commença à prêcher et à dire: Repentez-vous; car le royaume des cieux est proche.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 18, 'Comme il marchait le long de la mer de Galilée, il vit deux frères, Simon appelé Pierre, et André, son frère, qui jetaient le filet dans la mer; car ils étaient pêcheurs.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 19, 'Et il leur dit: Suivez-moi, et je vous ferai pêcheurs d\'hommes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 20, 'Aussitôt, laissant leurs filets, ils le suivirent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 21, 'De là, il s\'avança plus loin et vit deux autres frères, Jacques, fils de Zébédée, et Jean, son frère, qui raccommodaient leurs filets dans leurs barques, avec Zébédée, leur père; et il les appela.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 22, 'Aussitôt, laissant la barque et leur père, ils le suivirent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 23, 'Jésus allait par toute la Galilée, enseignant dans les synagogues, prêchant l\'Evangile du royaume, et guérissant toutes sortes de maladies et d\'infirmités parmi le peuple.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 24, 'Sa renommée se répandit par toute la Syrie. On vint lui présenter tous ceux qui étaient malades ou tourmentés par les douleurs et les souffrances les plus diverses, des démoniaques, des lunatiques, des paralytiques; et il les guérit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 25, 'Et de grandes foules le suivirent de la Galilée, de la Décapole, de Jérusalem, de la Judée, et du pays au-delà du Jourdain.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 1, 'Jésus, voyant la foule, alla sur la montagne; et, quand il se fut assis, ses disciples s\'approchèrent de lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 2, 'Alors, ouvrant la bouche, il se mit à les enseigner, en disant:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 3, 'Heureux les pauvres en esprit; car le royaume des cieux est à eux!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 4, 'Heureux ceux qui pleurent; car ils seront consolés!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 5, 'Heureux les débonnaires; car ils hériteront la terre!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 6, 'Heureux ceux qui ont faim et soif de la justice; car ils seront rassasiés!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 7, 'Heureux les miséricordieux; car ils obtiendront miséricorde!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 8, 'Heureux ceux qui ont le coeur pur; car ils verront Dieu!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 9, 'Heureux ceux qui procurent la paix; ils seront appelés fils de Dieu!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 10, 'Heureux ceux qui sont persécutés pour la justice; car le royaume des cieux est à eux!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 11, 'Vous serez heureux, lorsqu\'on vous outragera, qu\'on vous persécutera, et qu\'on dira faussement contre vous toute sorte de mal à cause de moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 12, 'Réjouissez-vous et tressaillez de joie, parce que votre récompense sera grande dans les cieux; car c\'est ainsi qu\'on a persécuté les prophètes qui sont venus avant vous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 13, 'Vous êtes le sel de la terre; mais, si le sel perd sa saveur, avec quoi la lui rendra-t-on? Il n\'est plus bon qu\'à être jeté dehors et foulé aux pieds par les hommes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 14, 'Vous êtes la lumière du monde: une ville située sur une montagne ne peut être cachée,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 15, 'et on n\'allume pas une lampe pour la mettre sous le boisseau; mais on la met sur un support, et elle éclaire tous ceux qui sont dans la maison.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 16, 'Que votre lumière luise ainsi devant les hommes, afin qu\'ils voient vos bonnes oeuvres, et qu\'ils glorifient votre Père qui est dans les cieux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 17, 'Ne pensez pas que je sois venu abolir la loi ou les prophètes: je suis venu, non pour abolir, mais pour accomplir.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 18, 'En effet, je vous le dis en vérité, avant que le ciel et la terre aient passé, il ne passera de la loi ni un iota ni un trait de lettre, jusqu\'à ce que tout soit accompli.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 19, 'Celui donc qui violera l\'un de ces plus petits commandements, et qui enseignera aux hommes à les violer, sera appelé le plus petit dans le royaume des cieux; mais celui qui les observera et qui les enseignera, celui-là sera appelé grand dans le royaume des cieux!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 20, 'Car je vous dis que si votre justice ne surpasse pas celle des scribes et des pharisiens, vous n\'entrerez point dans le royaume des cieux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 21, 'Vous avez entendu qu\'il a été dit aux anciens: «Tu ne tueras point»; et: «Celui qui aura tué sera jugé par le tribunal»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 22, 'Mais moi, je vous dis: Quiconque se met en colère contre son frère, sera jugé par le tribunal. Celui qui dira à son frère: Raca, sera jugé par le Sanhédrin; et celui qui lui dira: Fou, sera passible de la géhenne du feu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 23, '— Si donc tu apportes ton offrande à l\'autel, et que là tu te souviennes que ton frère a quelque chose contre toi,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 24, 'laisse là ton offrande devant l\'autel, et va premièrement te réconcilier avec ton frère; après cela, viens et présente ton offrande.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 25, 'Accorde-toi au plus tôt avec, ton adversaire, pendant que tu es en chemin avec lui, de peur qu\'il ne te livre au juge, que le juge ne te livre au sergent, et que tu ne sois mis en prison.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 26, 'En vérité, je te le dis, tu ne sortiras pas de là, que tu n\'aies payé jusqu\'à la dernière obole.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 27, 'Vous avez entendu qu\'il a été dit: «Tu ne commettras point d\'adultère.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 28, 'Mais moi, je vous dis: Quiconque jette sur une femme un regard de convoitise, a déjà commis l\'adultère avec elle dans son coeur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 29, 'Si donc ton oeil droit te fait tomber dans le péché, arrache-le et jette-le loin de toi; car il vaut mieux pour toi qu\'un de tes membres périsse, que si tout ton corps était jeté dans la géhenne.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 30, 'Si ta main droite te fait tomber dans le péché, coupe-la et jette-la loin de toi; car il vaut mieux pour toi qu\'un de tes membres périsse, que si tout ton corps allait dans la géhenne.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 31, 'Il a été dit: «Si quelqu\'un répudie sa femme, qu\'il lui donne une lettre de divorce.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 32, 'Mais moi, je vous dis: Quiconque répudie sa femme, si ce n\'est pour cause d\'inconduite, l\'expose à devenir adultère; et quiconque aura épousé une femme répudiée, commet un adultère.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 33, 'Vous avez encore entendu qu\'il a été dit aux anciens: «Tu ne te parjureras point; mais tu t\'acquitteras envers le Seigneur de tes serments.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 34, 'Mais moi, je vous dis de ne point jurer du tout: ni par le ciel, car c\'est le trône de Dieu;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 35, 'ni par la terre, car c\'est son marchepied; ni par Jérusalem, car c\'est la ville du grand Roi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 36, 'Ne jure pas non plus par ta tête, car tu ne peux rendre un seul de tes cheveux blanc ou noir.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 37, 'Mais que votre parole soit: oui, oui; non, non. Ce qu\'on dit de plus vient du Malin.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 38, 'Vous avez entendu qu\'il a été dit; «Oeil pour oeil, et dent pour dent.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 39, 'Mais moi, je vous dis de ne pas résister au méchant. Au contraire, si quelqu\'un te frappe à la joue droite, présente-lui aussi l\'autre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 40, 'Si quelqu\'un veut plaider contre toi pour t\'enlever ta tunique, laisse-lui encore le manteau;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 41, 'et si quelqu\'un veut te contraindre de faire un mille avec lui, fais-en deux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 42, 'Donne à celui qui te demande, et ne te détourne pas de celui qui veut emprunter de toi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 43, 'Vous avez entendu qu\'il a été dit: «Tu aimeras ton prochain», et tu haïras ton ennemi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 44, 'Mais moi, je vous dis: Aimez vos ennemis, et priez pour ceux qui vous persécutent,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 45, 'afin que vous soyez les fils de votre Père qui est dans les cieux; car il fait lever son soleil sur les méchants et sur les bons, et il fait pleuvoir sur les justes et sur les injustes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 46, 'Si vous n\'aimez que ceux qui vous aiment, quelle récompense en aurez-vous? Les péagers n\'en font-ils pas autant?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 47, 'Et si vous ne faites accueil qu\'à vos frères, que faites-vous d\'extraordinaire? Les Païens même n\'en font-ils pas autant?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 48, 'Soyez donc parfaits, comme votre Père céleste est parfait.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 1, 'Gardez-vous de pratiquer votre justice devant les hommes pour être remarqués par eux. Autrement, il n\'y a pas pour vous de récompense auprès de votre Père qui est dans les cieux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 2, 'Quand donc tu feras l\'aumône, ne fais pas sonner la trompette devant toi, comme font les hypocrites dans les synagogues et dans les rues, afin d\'être honorés des hommes. En vérité, je vous le dis, ils ont leur récompense.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 3, 'Mais toi, quand tu fais l\'aumône, que ta main gauche ne sache pas ce que fait ta main droite,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 4, 'afin que ton aumône se fasse en secret; et ton Père, qui voit dans le secret, te récompensera.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 5, 'Quand vous priez, ne soyez pas comme les hypocrites; car ils aiment à prier en se tenant debout dans les synagogues et aux coins des places, afin d\'être vus des hommes. En vérité, je vous le dis, ils ont leur récompense.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 6, 'Mais toi, quand tu pries, entre dans ta chambre; et, après avoir fermé ta porte, prie ton Père qui est là, dans le secret; et ton Père, qui voit dans le secret, te récompensera.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 7, 'Lorsque vous priez, n\'usez pas de vaines redites, comme font les Païens, qui pensent être exaucés en parlant beaucoup.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 8, 'Ne leur ressemblez donc pas; car votre Père sait de quoi vous avez besoin, avant que vous le lui demandiez.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 9, 'Vous donc priez ainsi: Notre Père qui es aux cieux. Que ton nom soit sanctifié;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 10, 'Que ton règne vienne; Que ta volonté soit faite sur la terre comme au ciel;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 11, 'Donne-nous aujourd\'hui notre pain quotidien;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 12, 'Pardonne-nous nos offenses, comme aussi nous pardonnons à ceux qui nous ont offensés;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 13, 'Ne nous laisse pas succomber à la tentation; mais délivre-nous du mal; [Car c\'est à toi qu\'appartiennent, dans tous les siècles, le règne, la puissance et la gloire. Amen!]');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 14, 'En effet, si vous pardonnez aux hommes leurs fautes, votre Père céleste vous pardonnera aussi les vôtres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 15, 'Mais si vous ne pardonnez pas aux hommes leurs fautes, votre Père ne vous pardonnera pas non plus vos fautes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 16, 'Quand vous jeûnez, n\'ayez pas un air triste, comme les hypocrites; car ils donnent à leur visage un air tout défait, pour montrer aux hommes qu\'ils jeûnent. En vérité, je vous le dis, ils ont leur récompense.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 17, 'Mais toi, quand tu jeûnes, oins ta tête et lave ton visage,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 18, 'afin que les hommes ne voient pas que tu jeûnes, mais seulement ton Père qui est là, dans le secret. Et ton Père, qui voit dans le secret, te récompensera.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 19, 'Ne vous amassez pas des trésors sur la terre, où les vers et la rouille détruisent, et où les voleurs percent et dérobent;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 20, 'mais amassez-vous des trésors dans le ciel, où ni les vers ni la rouille ne détruisent, et où les voleurs ne percent ni ne dérobent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 21, 'Car où est ton trésor, là aussi sera ton coeur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 22, 'L\'oeil est la lampe du corps. Si ton oeil est sain, tout ton corps sera dans la lumière;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 23, 'mais si ton oeil est mauvais, tout ton corps sera dans les ténèbres. Si donc la lumière qui est en toi n\'est que ténèbres, combien seront grandes ces ténèbres!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 24, 'Nul ne peut servir deux maîtres; car ou il haïra l\'un et aimera l\'autre, ou il s\'attachera à l\'un et méprisera l\'autre. Vous ne pouvez servir Dieu et Mammon.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 25, 'C\'est pourquoi, je vous dis: Ne soyez point en souci, pour votre vie, de ce que vous mangerez ou de ce que vous boirez; ni, pour votre corps, du vêtement dont vous le revêtirez. La vie n\'est-elle pas plus que la nourriture, et le corps plus que le vêtement?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 26, 'Regardez les oiseaux du ciel: ils ne sèment, ni ne moissonnent, ils n\'amassent rien dans les greniers; et votre Père céleste les nourrit! Ne valez-vous pas beaucoup plus qu\'eux?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 27, 'D\'ailleurs, qui d\'entre vous peut ajouter par son souci une coudée à sa taille?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 28, 'Et quant au vêtement, pourquoi vous en inquiétez-vous? Laissez-vous instruire par les lis des champs. Voyez comment ils croissent: ils ne travaillent ni ne filent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 29, 'Et cependant, je vous dis que Salomon même, dans toute sa gloire, n\'a pas été vêtu comme l\'un d\'eux!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 30, 'Si Dieu revêt ainsi l\'herbe des champs, qui est aujourd\'hui et qui demain sera jetée au four, combien plutôt vous vêtira-t-il, ô gens de peu de foi!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 31, 'Ne vous mettez donc pas en souci, en disant: Que mangerons-nous? Que boirons-nous? De quoi serons-nous vêtus?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 32, 'Car toutes ces choses, ce sont les Païens qui les recherchent. Or, votre Père céleste sait que vous avez besoin de tout cela.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 33, 'Cherchez premièrement son royaume et sa justice, et toutes ces choses vous seront données par-dessus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 34, 'Ne vous mettez donc pas en souci pour le lendemain; car le lendemain aura soin de ce qui le concerne. A chaque jour suffit sa peine.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 1, 'Ne jugez point, afin que vous ne soyez pas jugés;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 2, 'car on vous jugera comme vous jugez, et on se servira pour vous de la mesure avec laquelle vous mesurez.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 3, 'Pourquoi regardes-tu la paille qui est dans l\'oeil de ton frère, tandis que tu n\'aperçois pas la poutre qui est dans ton oeil?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 4, 'Ou comment dis-tu à ton frère: Laisse-moi ôter cette paille de ton oeil. — toi qui a une poutre dans le tien?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 5, 'Hypocrite! Ote premièrement la poutre de ton oeil, et alors tu verras à ôter la paille de l\'oeil de ton frère.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 6, 'Ne donnez pas les choses saintes aux chiens et ne jetez pas vos perles devant les pourceaux, de peur qu\'ils ne les foulent aux pieds, et que, se retournant, ils ne vous déchirent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 7, 'Demandez, et l\'on vous donnera; cherchez, et vous trouverez; frappez, et l\'on vous ouvrira.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 8, 'Car quiconque demande, reçoit; qui cherche, trouve; et l\'on ouvrira à celui qui frappe.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 9, 'Quel est l\'homme d\'entre vous qui donnera une pierre à son fils, s\'il lui demande du pain?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 10, 'Ou, s\'il demande du poisson, lui donnera-t-il un serpent?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 11, 'Si donc vous, qui êtes mauvais, savez donner de bonnes choses à vos enfants, combien plus votre Père, qui est dans les cieux, donnera-t-il de bonnes choses à ceux qui les lui demandent!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 12, 'Ainsi, tout ce que vous voulez que les hommes vous fassent, faites-le-leur aussi vous-mêmes; car c\'est là la loi et les prophètes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 13, 'Entrez par la porte étroite, parce que la porte large et le chemin spacieux mènent à la perdition, et il y en a beaucoup qui y entrent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 14, 'Mais la porte étroite et le chemin resserré mènent à la vie, et il y en a peu qui les trouvent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 15, 'Gardez-vous des faux prophètes, qui viennent à vous, couverts de peaux de brebis, mais qui, au dedans, sont des loups ravisseurs.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 16, 'Vous les reconnaîtrez à leurs fruits. Cueille-t-on des raisins sur des épines, ou des figues sur des chardons?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 17, 'Ainsi, tout arbre qui est bon, produit de bons fruits; mais le mauvais arbre produit de mauvais fruits.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 18, 'Un bon arbre ne peut porter de mauvais fruits, ni un mauvais arbre porter de bons fruits.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 19, 'Tout arbre qui ne produit pas de bons fruits est coupé et jeté au feu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 20, 'Vous les reconnaîtrez donc à leurs fruits.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 21, 'Ce ne sont pas tous ceux qui me disent: Seigneur, Seigneur! qui entreront dans le royaume des cieux, mais ceux-là seulement qui font la volonté de mon Père qui est dans les cieux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 22, 'Plusieurs me diront en ce jour-là: Seigneur, Seigneur, n\'avons-nous pas prophétisé en ton nom? N\'avons-nous pas chassé les démons en ton nom? N\'avons-nous pas fait plusieurs miracles en ton nom?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 23, 'Alors je leur dirai ouvertement: Je ne vous ai jamais connus; retirez-vous de moi, vous qui commettez l\'iniquité!»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 24, 'Ainsi, tout homme qui entend les paroles que je dis et qui les met en pratique, sera semblable à un homme prudent qui a bâti sa maison sur le roc.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 25, 'La pluie est tombée, les torrents sont venus, et les vents ont soufflé et se sont déchaînés contre cette maison-là: elle n\'est pas tombée; car elle était fondée sur le roc.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 26, 'Mais tout homme qui entend les paroles que je dis et qui ne les met pas en pratique, est semblable à un homme insensé qui a bâti sa maison sur le sable.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 27, 'La pluie est tombée, les torrents sont venus, les vents ont soufflé et se sont déchaînés contre cette maison-là: elle est tombée, et sa ruine a été grande!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 28, 'Or, il arriva, quand Jésus eut achevé ces discours, que les foules furent frappées de son enseignement;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 29, 'car il les enseignait comme ayant autorité, et non pas comme leurs scribes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 1, 'Jésus étant descendu de la montagne, une grande foule le suivit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 2, 'Et voici qu\'un lépreux, s\'approchant, se prosterna devant lui et lui dit: Seigneur, si tu le veux, tu peux me rendre net.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 3, 'Jésus, étendant la main, le toucha et lui dit: Je le veux, sois net! Et aussitôt, il fut nettoyé de sa lèpre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 4, 'Jésus lui dit: Garde-toi d\'en parler à personne; mais va, montre-toi au sacrificateur, et offre le don que Moïse a prescrit, afin que cela leur serve de témoignage.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 5, 'Comme Jésus entrait à Capernaüm, un centenier vint à lui et lui adressa cette prière:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 6, 'Seigneur, mon serviteur est au lit dans ma maison, atteint de paralysie et cruellement tourmenté.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 7, 'Jésus lui dit: J\'irai et je le guérirai.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 8, 'Le centenier répondit: Seigneur, je ne suis pas digne que tu entres sous mon toit; mais dis seulement une parole, et mon serviteur sera guéri.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 9, 'Car moi, qui suis sous la puissance d\'autrui, j\'ai sous moi des soldats, et je dis à l\'un: Va, et il va; et à l\'autre: Viens, et il vient; et à mon serviteur: Fais cela, et il le fait.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 10, 'Jésus, l\'ayant entendu, fut dans l\'admiration et dit à ceux qui le suivaient: En vérité, je vous le déclare, chez aucun homme en Israël je n\'ai trouvé une si grande foi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 11, 'Aussi, je vous dis que plusieurs viendront de l\'Orient et de l\'Occident, et ils seront à table dans le royaume des cieux avec Abraham, Isaac et Jacob.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 12, 'Mais les fils du royaume seront jetés dans les ténèbres du dehors; c\'est là qu\'il y aura des pleurs et des grincements de dents.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 13, 'Alors Jésus dit au centenier: Va, et qu\'il te soit fait selon ta foi! Et à cette heure même, son serviteur fut guéri.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 14, 'Puis Jésus entra dans la maison de Pierre; et il vit sa belle-mère qui était au lit, malade de la fièvre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 15, 'Il lui toucha la main, et la fièvre la quitta. Elle se leva et se mit à les servir.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 16, 'Quand le soir fut venu, on lui amena plusieurs démoniaques, et il chassa les esprits par sa parole. Il guérit aussi tous ceux qui étaient malades,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 17, 'de sorte que fut accompli ce qui avait été dit par Ésaïe, le prophète: «Il a pris lui-même nos infirmités et il a porté nos maladies.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 18, 'Jésus, voyant une grande foule autour de lui, donna l\'ordre de passer à l\'autre bord.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 19, 'Alors un scribe, s\'étant approché, lui dit: Maître, je te suivrai partout où tu iras.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 20, 'Jésus lui répondit: Les renards ont des tanières, et les oiseaux du ciel, des nids; mais le Fils de l\'homme n\'a pas un lieu où il puisse reposer sa tête.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 21, 'Un autre des disciples lui dit: Seigneur, permets que j\'aille auparavant ensevelir mon père.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 22, 'Mais Jésus lui dit: Suis-moi; et laisse les morts ensevelir leurs morts.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 23, 'Ensuite il entra dans la barque, et ses disciples le suivirent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 24, 'Et voici qu\'il s\'éleva sur la mer une si grande tourmente, que la barque était couverte par les flots; mais Jésus dormait.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 25, 'Ses disciples, s\'étant approchés, le réveillèrent, en disant: Seigneur, sauve-nous, nous périssons!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 26, 'Il leur dit: Pourquoi avez-vous peur, gens de peu de foi? Alors, s\'étant levé, il imposa le silence aux vents et à la mer; et il se fit un grand calme.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 27, 'Et ces hommes, saisis d\'admiration, disaient: Quel est donc celui-ci, que même les vents et la mer lui obéissent?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 28, 'Quand il fut arrivé à l\'autre bord, dans le pays des Gadaréniens, deux démoniaques vinrent à sa rencontre, sortant des tombeaux; ils étaient furieux, que personne n\'osait passer par ce chemin-là.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 29, 'Ils se mirent à crier: Qu\'y a-t-il entre nous et toi. Fils de Dieu? Es-tu venu ici pour nous tourmenter avant le temps?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 30, 'Or, il y avait au loin un grand troupeau de pourceaux qui paissaient.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 31, 'Et les démons adressaient à Jésus cette prière: Si tu nous chasses, envoie-nous dans ce troupeau de pourceaux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 32, 'Il leur dit: Allez! Les démons, étant sortis, entrèrent dans les pourceaux; et voici que tout le troupeau se précipita dans la mer, du haut de la falaise, et il périt dans les eaux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 33, 'Alors ceux qui le faisaient paître s\'enfuirent; et ils allèrent à la ville raconter tout ce qui s\'était passé et ce qui était arrivé aux démoniaques.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 34, 'Aussitôt, tous les habitants de la ville sortirent au-devant de Jésus; et, l\'ayant vu, ils le prièrent de se retirer de leur pays.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 1, 'Jésus, étant entré dans une barque, repassa la mer et vint dans sa ville.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 2, 'Et voici qu\'on lui apporta un paralytique couché sur un lit. Jésus, voyant la foi de ces gens, dit au paralytique: Prends courage, mon enfant, tes péchés te sont pardonnés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 3, 'Alors quelques scribes dirent en eux-mêmes: Cet homme blasphème!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 4, 'Mais Jésus, connaissant leurs pensées, dit: Pourquoi avez-vous de mauvaises pensées dans vos coeurs?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 5, 'Lequel est le plus aisé de dire: Tes péchés te sont pardonnés. — ou de dire: Lève-toi et marche.?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 6, 'Or, afin que vous sachiez que le Fils de l\'homme a sur la terre le pouvoir de pardonner les péchés.: Lève-toi, — dit-il au paralytique, — charge-toi de ton lit, et va dans ta maison.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 7, 'Celui-ci se leva, et il s\'en alla dans sa maison.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 8, 'A cette vue, la foule fut saisie de crainte; et elle rendit gloire à Dieu de ce qu\'il avait donné un tel pouvoir aux hommes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 9, 'Jésus, étant parti de là, vit un homme appelé Matthieu, assis au bureau du péage, et il lui dit: Suis-moi. Et lui, se levant, le suivit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 10, 'Or, il arriva, comme Jésus était à table dans la maison de cet homme, que beaucoup de péagers et de pécheurs y vinrent; et ils se mirent à table avec lui et ses disciples.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 11, 'Les pharisiens, voyant cela, dirent à ses disciples: Pourquoi votre maître mange-t-il avec les péagers et les pécheurs?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 12, 'Jésus, les ayant entendus, leur dit: Ce ne sont pas ceux qui se portent bien qui ont besoin de médecin, mais ceux qui se portent mal.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 13, 'Allez et apprenez ce que signifie cette parole: «Je veux la miséricorde, et non le sacrifice»; car je ne suis pas venu appeler les justes, mais les pécheurs.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 14, 'Alors les disciples de Jean vinrent trouver Jésus, et ils lui dirent: D\'où vient que nous et les pharisiens, nous jeûnons, et que tes disciples ne jeûnent pas?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 15, 'Jésus leur répondit: Les amis de l\'époux peuvent-ils s\'affliger aussi longtemps que l\'époux est avec eux? Mais les jours viendront où l\'époux leur sera ôté, et alors ils jeûneront!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 16, 'Personne ne met une pièce de drap neuf à un vieux vêtement; car la pièce emporte une partie du vêtement, et la déchirure en devient pire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 17, 'On ne met pas non plus du vin nouveau dans de vieilles outres; autrement, les outres se rompent, le vin se répand, et les outres sont perdues. Mais on met le vin nouveau dans une outre neuve; et l\'on conserve ainsi l\'un et l\'autre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 18, 'Comme il leur parlait ainsi, un chef de la synagogue entra, se prosterna devant lui et lui dit: Ma fille vient de mourir; mais viens, pose ta main sur elle, et elle vivra.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 19, 'Jésus, s\'étant levé, le suivit avec ses disciples.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 20, 'Voici qu\'une femme, malade d\'une perte de sang depuis douze ans, s\'approcha par derrière et toucha le bord de son vêtement;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 21, 'car elle disait en elle-même: Si je touche seulement son vêtement, je serai guérie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 22, 'Jésus se retourna et, la voyant, il lui dit: Prends courage, ma fille, ta foi t\'a guérie. Et à l\'heure même, cette femme fut guérie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 23, 'Lorsque Jésus fut arrivé à la maison du chef de la synagogue, voyant les joueurs de flûte et la foule qui faisait grand bruit,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 24, 'il leur dit: Retirez-vous; car cette petite fille n\'est pas morte, mais elle dort! Et ils se moquaient de lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 25, 'Après qu\'on eut mis la foule dehors, Jésus entra; il prit la petite fille par la main, et elle se leva.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 26, 'Et cette nouvelle se répandit dans tout le pays.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 27, 'Comme Jésus partait de là, deux aveugles le suivirent, en criant: Fils de David, aie pitié de nous!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 28, 'Quand il fut entré dans la maison, ces aveugles vinrent à lui; et Jésus leur dit: Croyez-vous que je puisse faire ce que vous désirez? Ils lui répondirent: Oui, Seigneur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 29, 'Alors il leur toucha les yeux, en disant: Qu\'il vous soit fait selon votre foi!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 30, 'Et leurs yeux furent ouverts. Jésus leur dit d\'un ton sévère: Prenez garde que personne ne le sache!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 31, 'Mais eux, étant sortis, répandirent sa renommée dans tout le pays.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 32, 'Comme ils sortaient, voici qu\'on lui présenta un homme muet, possédé d\'un démon.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 33, 'Le démon ayant été chassé, le muet parla. La foule était dans l\'admiration et s\'écriait: Jamais rien de semblable ne s\'est vu en Israël!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 34, 'Mais les pharisiens disaient: Il chasse les démons par le prince des démons.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 35, 'Jésus parcourait toutes les villes et tous les villages, enseignant dans les synagogues, prêchant l\'Évangile du royaume, et guérissant toutes sortes de maladies et d\'infirmités.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 36, 'En voyant les foules, il fut ému de compassion pour elles, parce qu\'elles étaient épuisées et dispersées comme des brebis qui n\'ont pas de berger.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 37, 'Alors il dit à ses disciples: La moisson est grande, mais il y a peu d\'ouvriers.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 38, 'Priez donc le maître de la moisson d\'envoyer des ouvriers dans sa moisson.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 1, 'Jésus, ayant appelé ses douze disciples, leur donna le pouvoir de chasser les esprits impurs et de guérir toutes sortes de maladies et d\'infirmités.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 2, 'Voici les noms des douze apôtres: le premier, Simon, appelé Pierre, et André, son frère; Jacques, fils de Zébédée, et Jean, son frère;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 3, 'Philippe et Barthélémy; Thomas et Matthieu, le péager; Jacques, fils d\'Alphée, et Thaddée;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 4, 'Simon, le Cananéen et Judas l\'Iscariote, celui-là même qui le trahit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 5, 'Ce sont là les Douze que Jésus envoya, en leur donnant ces instructions: N\'allez pas vers les Païens, et n\'entrez dans aucune ville des Samaritains;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 6, 'mais allez plutôt vers les brebis perdues de la maison d\'Israël.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 7, 'Et, sur votre route, prêchez et dites: Le royaume des cieux est proche.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 8, 'Guérissez les malades, ressuscitez les morts, nettoyez les lépreux, chassez les démons: vous avez reçu gratuitement, donnez gratuitement!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 9, 'Ne prenez ni or, ni argent, ni monnaie dans vos ceintures,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 10, 'ni sac pour le voyage, ni deux tuniques, ni chaussures, ni bâton; car l\'ouvrier mérite sa nourriture.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 11, 'Dans quelque ville ou village que vous entriez, demandez celui qui est digne de vous recevoir, et demeurez chez lui jusqu\'à votre départ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 12, 'En entrant dans la maison, saluez-la.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 13, 'Et si la maison en est digne, que votre paix descende sur elle; mais si elle n\'en est pas digne, que votre paix revienne à vous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 14, 'Si l\'on ne vous reçoit pas, et si l\'on n\'écoute pas vos paroles, en sortant de cette maison ou de cette ville, secouez la poussière de vos pieds.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 15, 'En vérité, je vous le dis, le pays de Sodome et de Gomorrhe sera traité moins rigoureusement que cette ville, au jour du jugement.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 16, 'Voici que je vous envoie comme des brebis au milieu des loups: soyez donc prudents comme les serpents, et purs comme les colombes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 17, 'Tenez-vous sur vos gardes vis-à vis des hommes; car ils vous livreront aux tribunaux et vous battront de verges dans leurs synagogues.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 18, 'Vous serez menés devant les gouverneurs et devant les rois, à cause de moi, pour rendre témoignage devant eux et devant les nations.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 19, 'Mais quand on vous livrera, ne soyez en peine ni de la manière dont vous parlerez, ni de ce que vous direz; car ce que vous aurez à dire vous sera inspiré à l\'heure même.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 20, 'Ce n\'est pas vous qui parlerez, mais c\'est l\'Esprit de votre Père, celui qui parle en vous!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 21, 'Le frère livrera son frère à la mort, et le père son enfant; les enfants se soulèveront contre leurs parents et les feront mourir.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 22, 'Vous serez haïs de tous à cause de mon nom; mais celui qui persévérera jusqu\'à la fin, celui-là sera sauvé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 23, 'Quand ils vous persécuteront dans une ville, fuyez dans une autre; car, je vous le dis en vérité, vous n\'aurez pas achevé de parcourir les villes d\'Israël, que le Fils de l\'homme sera venu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 24, 'Le disciple n\'est pas au-dessus de son maître, ni le serviteur au-dessus de son seigneur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 25, 'Il suffit au disciple d\'être comme son maître, et au serviteur d\'être comme son seigneur. S\'ils ont appelé le père de famille Béelzébul, combien plus ceux de sa maison!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 26, 'Ne les craignez donc point; car il n\'y a rien de caché qui ne doive être découvert, ni rien de secret qui ne doive être connu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 27, 'Ce que je vous dis dans les ténèbres, dites-le en plein jour; et ce que vous entendez à l\'oreille, prêchez-le sur les toits.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 28, 'Ne craignez pas ceux qui tuent le corps, mais qui ne peuvent tuer l\'âme. Craignez plutôt Celui qui peut faire périr l\'âme et le corps dans la géhenne.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 29, 'Deux passereaux ne se vendent-ils pas un sou? Et il n\'en tombe pas un seul à terre sans la volonté de votre Père!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 30, 'Les cheveux même de votre tête sont tous comptés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 31, 'Ne craignez donc rien; vous valez mieux que beaucoup de passereaux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 32, 'C\'est pourquoi, quiconque me confessera devant les hommes, je le confesserai aussi devant mon Père qui est dans les cieux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 33, 'Mais quiconque me reniera devant les hommes, je le renierai devant mon Père qui est dans les cieux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 34, 'Ne pensez pas que je sois venu apporter la paix sur la terre; je suis venu apporter non la paix, mais l\'épée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 35, 'Je suis venu mettre la division entre le fils et son père, entre la fille et sa mère, entre la belle-fille et sa belle-mère;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 36, 'et l\'homme aura pour ennemis ceux de sa propre maison.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 37, 'Celui qui aime son père ou sa mère plus que moi, n\'est pas digne de moi; celui qui aime son fils ou sa fille plus que moi, n\'est pas digne de moi;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 38, 'et celui qui ne prend pas sa croix et ne me suit pas, n\'est pas digne de moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 39, 'Celui qui aura conservé sa vie la perdra; et celui qui aura perdu sa vie, à cause de moi, la retrouvera.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 40, 'Qui vous reçoit, me reçoit; et qui me reçoit, reçoit Celui qui m\'a envoyé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 41, 'Celui qui reçoit un prophète en qualité de prophète, recevra une récompense de prophète; et celui qui reçoit un juste en qualité de juste, recevra une récompense de juste.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 42, 'Quiconque aura donné à boire seulement un verre d\'eau froide à l\'un de ces petits, parce qu\'il est mon disciple, en vérité, je vous le dis, celui-là ne perdra point sa récompense.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 1, 'Quand Jésus eut achevé de donner ces instructions à ses douze disciples, il partit de là pour aller enseigner et prêcher dans les villes du pays.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 2, 'Jean, ayant entendu parler dans sa prison des oeuvres du Christ, lui envoya dire par ses disciples:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 3, 'Es-tu celui qui doit venir, ou devons-nous en attendre un autre?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 4, 'Jésus leur répondit: Allez rapporter à Jean ce que vous entendez et ce que vous voyez:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 5, 'les aveugles recouvrent la vue, les boiteux marchent, les lépreux sont nettoyés, les sourds entendent, les morts ressuscitent, et l\'Évangile est annoncé aux pauvres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 6, 'Heureux celui pour qui je ne serai pas une occasion de chute!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 7, 'Comme ils s\'en allaient, Jésus se mit à parler de Jean à la foule: Qu\'êtes-vous allés voir au désert? Un roseau agité par le vent?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 8, 'Mais encore, qu\'êtes-vous allés voir? Un homme vêtu d\'habits somptueux? Ceux qui portent des vêtements somptueux sont dans les demeures des rois.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 9, 'Mais encore, qu\'êtes-vous allés voir? Un prophète? Oui, vous dis-je, et plus qu\'un prophète.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 10, 'C\'est celui dont il est écrit: «Voici que j\'envoie mon messager devant ta face, pour préparer ton chemin devant toi.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 11, 'En vérité, je vous le dis, parmi ceux qui sont nés de femme, il n\'en a pas été suscité de plus grand que Jean-Baptiste; toutefois, celui qui est le plus petit dans le royaume des cieux est plus grand que lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 12, 'Mais, depuis les jours de Jean-Baptiste jusqu\'à maintenant, le royaume des cieux est forcé, et ce sont les violents qui s\'en emparent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 13, 'Car tous les prophètes et la loi ont prophétisé jusqu\'à Jean.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 14, 'Et si vous voulez comprendre, il est cet Elie qui devait venir.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 15, 'Que celui qui a des oreilles pour entendre, entende!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 16, 'A qui donc comparerai-je cette génération? Elle ressemble à des enfants assis dans les places publiques, qui crient à leurs compagnons et qui leur disent:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 17, 'Nous vous avons joué de la flûte, et vous n\'avez pas dansé; nous avons chanté des complaintes, et vous ne vous êtes pas lamentés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 18, 'En effet, Jean est venu, ne mangeant ni ne buvant, et l\'on dit: Il a un démon!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 19, 'Le Fils de l\'homme est venu, mangeant et buvant, et l\'on dit: Voilà un mangeur et un buveur, un ami des péagers et des pécheurs! Mais la sagesse a été justifiée par ses enfants.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 20, 'Alors Jésus se mit à faire des reproches aux villes où il avait fait le plus grand nombre de ses miracles, parce qu\'elles ne s\'étaient point repenties:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 21, 'Malheur à toi, Corazin! Malheur à toi, Bethsaïda! Car si les miracles qui ont été faits au milieu de vous avaient été faits à Tyr et à Sidon, il y a longtemps qu\'elles se seraient repenties en prenant le sac et la cendre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 22, 'C\'est pourquoi, je vous le déclare: Tyr et Sidon seront traitées moins rigoureusement que vous, au jour du jugement.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 23, 'Et toi, Capernaüm, qui as été élevée jusqu\'au ciel, tu seras abaissée jusqu\'en enfer! Car si les miracles qui ont été faits au milieu de toi avaient été faits à Sodome, elle subsisterait encore aujourd\'hui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 24, 'C\'est pourquoi, je le déclare: le pays de Sodome sera traité moins rigoureusement que toi, au jour du jugement.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 25, 'En ce temps-là, Jésus prononça ces paroles: Je te loue, ô Père, Seigneur du ciel et de la terre, de ce que tu as caché ces choses aux sages et aux intelligents, et de ce que tu les as révélées aux petits enfants.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 26, 'Oui, Père, il en est ainsi, parce que tu l\'as trouvé bon.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 27, 'Toutes choses m\'ont été remises par mon Père; nul ne connaît le Fils, si ce n\'est le Père, et nul ne connaît le Père, si ce n\'est le Fils et celui à qui le Fils aura voulu le révéler.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 28, 'Venez à moi, vous tous qui êtes fatigués et chargés, et je vous soulagerai.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 29, 'Chargez-vous de mon joug, et apprenez de moi; car je suis doux et humble de coeur. Et vous trouverez le repos de vos âmes!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 30, 'Car mon joug est doux, et mon fardeau léger.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 1, 'En ce temps-là, Jésus passa par des champs de blé un jour de sabbat; et ses disciples, ayant faim, se mirent à arracher des épis et à les manger.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 2, 'Les pharisiens, voyant cela, lui dirent: Voilà tes disciples qui font ce qu\'il n\'est pas permis de faire le jour du sabbat.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 3, 'Il leur répondit: N\'avez-vous pas lu ce que fit David, lorsqu\'il eut faim, lui et ceux qui étaient avec lui;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 4, 'comment il entra dans la maison de Dieu et mangea les pains de proposition qu\'il n\'était pas permis de manger, ni à lui, ni à ceux qui étaient avec lui, mais aux seuls sacrificateurs?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 5, 'Ou bien n\'avez-vous pas lu dans la loi que les sacrificateurs, le jour du sabbat, violent le sabbat dans le temple, sans être coupables?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 6, 'Or, je vous le dis, il y a ici plus que le temple!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 7, 'Si vous saviez ce que signifie cette parole: «Je veux la miséricorde et non le sacrifice». — vous n\'auriez pas condamné des innocents;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 8, 'car le Fils de l\'homme est maître du sabbat.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 9, 'Étant parti de là, il entra dans la synagogue.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 10, 'Il s\'y trouvait un homme qui avait une main desséchée, et ils demandèrent à Jésus: Est-il permis de guérir le jour du sabbat? C\'était afin de pouvoir l\'accuser.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 11, 'Mais il leur répondit: Quel est celui d\'entre vous, qui, ayant une brebis, si elle tombe dans une fosse le jour du sabbat, ne la prenne et ne l\'en retire?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 12, 'Or, combien un homme ne vaut-il pas mieux qu\'une brebis! Il est donc permis de faire du bien le jour du sabbat.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 13, 'Alors il dit à cet homme: Étends ta main. Il l\'étendit; et elle redevint saine comme l\'autre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 14, 'Les pharisiens, étant sortis, tinrent conseil contre lui pour le faire périr.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 15, 'Mais Jésus, l\'ayant su, partit de là; plusieurs le suivirent, et il les guérit tous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 16, 'Puis il leur défendit expressément de le faire connaître.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 17, 'Ainsi fut accompli ce qui avait été prédit par Ésaïe, le prophète:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 18, '«Voici mon serviteur que j\'ai élu, mon bien-aimé en qui mon âme a mis toute son affection. Je ferai reposer mon Esprit sur lui, et il annoncera le jugement aux nations.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 19, 'Il ne contestera pas et ne criera point; on n\'entendra pas sa voix dans les places publiques.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 20, 'Il ne brisera pas le roseau froissé, et il n\'étouffera pas le lumignon qui va s\'éteindre, jusqu\'à ce qu\'il ait fait triompher la justice;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 21, 'et les nations espéreront en son nom.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 22, 'Alors on présenta à Jésus un démoniaque aveugle et muet; il le guérit, de sorte que le muet parlait et voyait.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 23, 'La foule en fut étonnée, et l\'on disait: N\'est-ce point là le Fils de David?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 24, 'Mais les pharisiens, entendant cela, dirent: Cet homme ne chasse les démons que par Béelzébul, le prince des démons!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 25, 'Jésus, connaissant leurs pensées, leur dit: Tout royaume divisé contre lui-même sera réduit en désert; et toute ville ou toute maison divisée contre elle-même ne pourra subsister.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 26, 'Si Satan chasse Satan, il est divisé contre lui-même; comment donc son royaume subsistera-t-il?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 27, 'Et si je chasse les démons par Béelzébul, — vos fils, par qui les chassent-ils? C\'est pourquoi, ils seront eux-mêmes vos juges!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 28, 'Mais si je chasse les démons par l\'Esprit de Dieu, le royaume de Dieu est donc venu jusqu\'à vous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 29, 'Ou bien, comment quelqu\'un peut-il entrer dans la maison de l\'homme fort et ravir ses biens, s\'il n\'a auparavant lié cet homme fort? Après cela, il pourra piller sa maison.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 30, 'Celui qui n\'est pas avec moi est contre moi, et celui qui n\'amasse pas avec moi disperse.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 31, 'C\'est pourquoi, je vous le dis, tout péché, tout blasphème sera pardonné aux hommes; mais le blasphème contre l\'Esprit ne sera point pardonné.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 32, 'Et si quelqu\'un parle contre le Fils de l\'homme, il lui sera pardonné; mais si quelqu\'un parle contre le Saint-Esprit, il ne lui sera pardonné, ni dans ce monde, ni dans le monde à venir.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 33, 'Ou dites que l\'arbre est bon et que son fruit est bon, ou dites que l\'arbre est mauvais et que son fruit est mauvais; car on connaît l\'arbre à son fruit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 34, 'Race de vipères, comment pourriez-vous, étant méchants, dire de bonnes choses? Car c\'est de l\'abondance du coeur que la bouche parle.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 35, 'L\'homme de bien tire de bonnes choses de son bon trésor; mais le méchant tire de mauvaises choses de son mauvais trésor.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 36, 'Je vous le déclare, les hommes rendront compte, au jour du jugement, de toute parole vaine qu\'ils auront dite.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 37, 'Car par tes paroles tu seras justifié, et par tes paroles tu seras condamné.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 38, 'Alors quelques-uns des scribes et des pharisiens lui dirent: Maître, nous voudrions te voir faire un miracle.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 39, 'Il leur répondit: Cette génération méchante et adultère demande un miracle; mais il ne lui en sera pas donné d\'autre que celui du prophète Jonas.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 40, 'Car, de même que Jonas fut dans le ventre du grand poisson trois jours et trois nuits, ainsi le Fils de l\'homme sera dans le sein de la terre trois jours et trois nuits.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 41, 'Les Ninivites se lèveront, au jour du jugement, avec cette génération, et ils la condamneront, parce qu\'ils se repentirent à la prédication de Jonas. Or, voici: Il y a ici plus que Jonas!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 42, 'La reine du Midi se lèvera, au jour du jugement, avec cette génération, et elle la condamnera, parce qu\'elle vint des extrémités de la terre pour entendre la sagesse de Salomon. Or, voici: Il y a ici plus que Salomon!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 43, 'Lorsque l\'esprit impur est sorti d\'un homme, il va par les lieux arides, cherchant, du repos, et il n\'en trouve point.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 44, 'Alors, il dit: Je retournerai dans ma maison, d\'où je suis sorti. Et quand il y est revenu, il la trouve vide, balayée et ornée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 45, 'Alors il s\'en va et prend avec lui sept autres esprits plus méchants que lui; ils y entrent et y demeurent, et la condition dernière de cet homme devient pire que la première. Il en sera ainsi de cette génération méchante.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 46, 'Comme Jésus parlait encore à la foule, sa mère et ses frères se tenaient dehors, cherchant à lui parler.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 47, '[Quelqu\'un lui dit: Voici que ta mère et tes frères sont là dehors, qui cherchent à te parler].');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 48, 'Il répondit à celui qui lui disait cela: Qui est ma mère, et qui sont mes frères?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 49, 'Puis, étendant la main sur ses disciples, il dit: Voici ma mère et mes frères!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 50, 'Car quiconque fait la volonté de mon Père qui est dans les cieux, celui-là est mon frère, et ma soeur, et ma mère.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 1, 'Ce même jour, Jésus, étant sorti de la maison, s\'assit au bord de la mer;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 2, 'et une grande foule s\'assembla autour de lui, de sorte qu\'il monta dans une barque. Il s\'y assit, tandis que toute la multitude se tenait sur le rivage;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 3, 'et il leur fit plusieurs discours en paraboles. Jésus leur parla ainsi:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 4, 'Le semeur sortit pour semer. Comme il semait, une partie de la semence tomba le long du chemin, et les oiseaux vinrent et la mangèrent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 5, 'Une autre partie tomba sur des endroits pierreux où elle n\'avait que peu de terre, et elle leva aussitôt, parce qu\'elle n\'entrait pas profondément dans la terre;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 6, 'mais le soleil s\'étant levé, elle fut brûlée, et, parce qu\'elle n\'avait point de racines, elle sécha.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 7, 'Une autre partie tomba parmi les épines, et les épines montèrent et l\'étouffèrent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 8, 'Une autre partie tomba dans la bonne terre, et donna du fruit: un grain en rapporta cent, un autre soixante, et un autre trente.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 9, 'Que celui qui a des oreilles entende!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 10, 'Alors les disciples s\'approchèrent et lui dirent: Pourquoi leur parles-tu en paraboles?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 11, 'Il leur répondit: Parce qu\'il vous a été donné de connaître les mystères du royaume des cieux; mais pour eux, cela ne leur a pas été donné.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 12, 'Car on donnera à celui qui a, et il sera dans l\'abondance; mais à celui qui n\'a pas, on ôtera même ce qu\'il a.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 13, 'C\'est pourquoi, je leur parle en paraboles, parce qu\'en voyant, ils ne voient pas, et qu\'en entendant ils n\'entendent et ne comprennent point.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 14, 'Ainsi s\'accomplit à leur égard la prophétie d\'Ésaïe, qui dit: «Vous entendrez de vos oreilles, et vous ne comprendrez pas; vous regarderez de vos yeux, et vous ne verrez point.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 15, 'Car le coeur de ce peuple s\'est appesanti; ils ont endurci leurs oreilles, ils ont fermé leurs yeux, de peur qu\'ils ne voient de leurs yeux, qu\'ils n\'entendent de leurs oreilles, qu\'ils ne comprennent de leur coeur, qu\'ils ne se convertissent et que je ne les guérisse.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 16, 'Mais, quant à vous, heureux sont vos yeux, parce qu\'ils voient, et vos oreilles, parce qu\'elles entendent!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 17, 'En vérité, je vous le déclare, beaucoup de prophètes et de justes ont désiré voir ce que vous voyez, et ils ne l\'ont pas vu, et entendre ce que vous entendez, et ils ne l\'ont pas entendu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 18, 'Vous donc, écoutez ce que signifie la parabole du semeur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 19, 'Lorsqu\'un homme entend la parole du royaume et ne la comprend pas, le Malin vient et enlève ce qui a été semé dans son coeur; c\'est celui qui a reçu la semence le long du chemin.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 20, 'Celui qui a reçu la semence dans les endroits pierreux, c\'est celui qui entend la parole et qui la reçoit aussitôt avec joie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 21, 'Mais il n\'y a pas en lui de racines; il n\'est que pour un temps. Et lorsque l\'affliction ou la persécution survient à cause de la parole, il y trouve aussitôt une occasion de chute.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 22, 'Celui qui a reçu la semence parmi les épines, c\'est celui qui entend la parole. Mais les soucis de ce monde et la séduction des richesses étouffent en lui cette parole, et elle devient infructueuse.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 23, 'Celui qui a reçu la semence dans la bonne terre, c\'est celui qui entend la parole, qui la comprend, et qui porte du fruit, en sorte qu\'un grain en produit cent, un autre soixante, et un autre trente.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 24, 'Jésus leur proposa une autre parabole, en disant: Le royaume des cieux est semblable à un homme qui avait semé une bonne semence dans son champ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 25, 'Mais pendant que les hommes dormaient, son ennemi vint, sema de l\'ivraie parmi le froment, et s\'en alla.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 26, 'Après que la semence eut poussé et qu\'elle eut produit du fruit, l\'ivraie parut aussi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 27, 'Alors les serviteurs du père de famille vinrent lui dire: Seigneur, n\'avais-tu pas semé une bonne semence dans ton champ? D\'où vient donc qu\'il y a de l\'ivraie?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 28, 'Et il leur dit: C\'est un ennemi qui a fait cela! Ils lui répondirent: Veux-tu donc que nous allions l\'arracher?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 29, 'Il leur dit: Non, de peur qu\'en arrachant l\'ivraie, vous ne déraciniez en même temps le froment.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 30, 'Laissez-les croître tous deux ensemble jusqu\'à la moisson; et au temps de la moisson, je dirai aux moissonneurs: Arrachez premièrement l\'ivraie, et liez-la en gerbes pour la brûler; mais amassez le froment dans mon grenier.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 31, 'Il leur proposa une autre parabole, en disant: Le royaume des cieux est semblable à un grain de moutarde, qu\'un homme prend et qu\'il sème dans son champ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 32, '— c\'est bien la plus petite de toutes les semences. — mais quand le grain a poussé, il est plus grand que les légumes; il devient un arbre, en sorte que les oiseaux du ciel viennent faire leurs nids dans ses branches.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 33, 'Il leur dit une autre parabole: Le royaume des cieux est semblable à du levain qu\'une femme prend et qu\'elle mêle à trois mesures de farine, pour faire lever toute la pâte.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 34, 'Jésus dit toutes ces choses à la foule en paraboles, et il ne leur parlait point sans paraboles.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 35, 'Ainsi fut accompli ce qui avait été dit par le prophète: «J\'ouvrirai ma bouche pour enseigner en paraboles; j\'annoncerai des choses cachées depuis la création.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 36, 'Alors Jésus, ayant renvoyé la foule, entra dans la maison; et ses disciples s\'approchèrent de lui et lui dirent: Explique-nous la parabole de l\'ivraie dans le champ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 37, 'Il leur répondit: Celui qui sème la bonne semence, c\'est le Fils de l\'homme;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 38, 'le champ, c\'est le monde; la bonne semence, ce sont les enfants du royaume; l\'ivraie, ce sont les enfants du Malin;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 39, 'l\'ennemi qui l\'a semée, c\'est le Diable; la moisson, c\'est la fin du monde; les moissonneurs, ce sont les anges.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 40, 'Et comme on arrache l\'ivraie et qu\'on la brûle au feu, il en sera de même à la fin du monde.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 41, 'Le Fils de l\'homme enverra ses anges, qui feront disparaître de son royaume tous les scandales et ceux qui commettent l\'iniquité,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 42, 'et ils les jetteront dans la fournaise ardente; c\'est là qu\'il y aura des pleurs et des grincements de dents.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 43, 'Alors les justes resplendiront comme le soleil dans le royaume de leur Père. Que celui qui a des oreilles entende!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 44, 'Le royaume des cieux est semblable à un trésor caché dans un champ, qu\'un homme a trouvé et qu\'il cache; puis, rempli de joie, il va vendre tout ce qu\'il possède, et il achète le champ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 45, 'Le royaume des cieux est encore semblable à un marchand qui cherche de belles perles,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 46, 'et qui, ayant trouvé une perle d\'un grand prix, s\'en est allé, a vendu tout ce qu\'il avait, et l\'a achetée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 47, 'Le royaume des cieux est encore semblable à un filet qu\'on jette dans la mer et qui ramasse toutes sortes de poissons.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 48, 'Quand il est rempli, les pêcheurs le tirent sur le rivage; puis, s\'étant assis, ils mettent à part, dans des paniers, ce qui est bon, et rejettent ce qui ne vaut rien.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 49, 'Il en sera de même à la fin du monde: et les anges viendront, et ils ôteront les méchants du milieu des justes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 50, 'Puis il les jetteront dans la fournaise ardente: c\'est là qu\'il y aura des pleurs et des grincements de dents.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 51, 'Avez-vous compris toutes ces choses? Ils lui répondirent: Oui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 52, 'Alors il leur dit: Ainsi tout scribe, bien instruit de tout ce qui concerne le royaume des cieux, est semblable à un père de famille qui tire de son trésor des choses nouvelles et des choses vieilles.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 53, 'Or, il arriva, quand Jésus eut achevé ces paraboles, qu\'il partit de là.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 54, 'Étant allé dans sa patrie, il enseignait dans la synagogue, de sorte que tous étaient saisis d\'étonnement, et disaient: D\'où viennent à cet homme cette sagesse et ces miracles?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 55, 'N\'est-ce pas le fils du charpentier? Sa mère ne s\'appelle-t-elle pas Marie, et ses frères, Jacques, Joseph, Simon et Jude?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 56, 'Ses soeurs ne sont-elles pas toutes parmi nous? D\'où lui viennent donc toutes ces choses?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 57, 'Et il était pour eux une occasion de chute. Mais Jésus leur dit: Un prophète n\'est méprisé que dans son pays et dans sa maison.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 58, 'Et il ne fit pas là beaucoup de miracles, à cause de leur incrédulité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 1, 'En ce temps-là, Hérode le tétrarque apprit ce que la renommée disait de Jésus. Et il dit à ses serviteurs:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 2, 'C\'est Jean-Baptiste! Il est ressuscité des morts; c\'est pour cela que des miracles s\'opèrent par lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 3, 'En effet, Hérode avait fait arrêter Jean, et il l\'avait fait lier et mettre en prison, à cause d\'Hérodias, femme de Philippe, son frère;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 4, 'car Jean lui disait: Il ne t\'est pas permis de l\'avoir pour femme!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 5, 'Hérode aurait bien voulu le faire mourir; mais il craignait le peuple, parce qu\'on regardait Jean comme un prophète.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 6, 'Or, comme on célébrait le jour de la naissance d\'Hérode, la fille d\'Hérodias dansa au milieu de l\'assemblée et plut à Hérode;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 7, 'de sorte qu\'il lui promit avec serment de lui donner tout ce qu\'elle lui demanderait.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 8, 'Elle donc, poussée par sa mère, lui dit: Donne-moi ici, sur un plat, la tête de Jean-Baptiste.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 9, 'Le roi en fut attristé; mais à cause de ses serments et des convives, il commanda qu\'on la lui donnât.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 10, 'Il envoya donc décapiter Jean dans la prison.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 11, 'On apporta la tête sur un plat, et on la donna à la jeune fille, qui la présenta à sa mère.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 12, 'Puis les disciples de Jean vinrent; ils emportèrent son corps et l\'ensevelirent; et ils allèrent l\'annoncer à Jésus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 13, 'Jésus, ayant appris ces choses, partit de là dans une barque, pour se retirer à l\'écart en un lieu désert. Quand la foule le sut, elle sortit des villes et le suivit à pied.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 14, 'Jésus, étant descendu de la barque, vit une grande multitude de gens: il fut ému de compassion pour eux, et il guérit leurs malades.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 15, 'Comme il se faisait tard, ses disciples vinrent le trouver et lui dirent: Ce lieu est désert, et l\'heure déjà avancée; renvoie la foule, afin qu\'elle aille dans les villages pour s\'acheter des vivres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 16, 'Mais Jésus leur dit: Il n\'est pas nécessaire qu\'ils y aillent; donnez-leur vous-mêmes à manger.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 17, 'Ils lui répondirent: Nous n\'avons là que cinq pains et deux poissons.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 18, 'Il leur dit: Apportez-les-moi ici.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 19, 'Alors, après avoir commandé que la multitude s\'assît sur l\'herbe, il prit les cinq pains et les deux poissons, et, levant les yeux au ciel, il rendit grâces; puis, ayant rompu les pains, il les donna aux disciples, et les disciples les donnèrent au peuple.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 20, 'Tous mangèrent et furent rassasiés, et on emporta douze paniers pleins des morceaux qui restèrent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 21, 'Ceux qui avaient mangé étaient environ cinq mille hommes, sans compter les femmes et les enfants.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 22, 'Aussitôt après, Jésus obligea ses disciples à entrer dans la barque et à passer avant lui sur l\'autre rive, pendant qu\'il renverrait le peuple.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 23, 'Après l\'avoir renvoyé, il alla sur la montagne pour prier à l\'écart; et, le soir étant venu, il était là seul.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 24, 'Cependant la barque était déjà au milieu de la mer, battue par les flots; car le vent était contraire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 25, 'Mais, à la quatrième veille de la nuit, Jésus alla vers eux, marchant sur la mer.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 26, 'Ses disciples, le voyant marcher sur la mer, furent troublés, et ils dirent: C\'est un fantôme! Et, dans leur frayeur, ils jetèrent des cris.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 27, 'Mais aussitôt, Jésus leur parla et leur dit: Rassurez-vous! C\'est moi, n\'ayez point de peur!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 28, 'Alors Pierre, prenant la parole, lui dit: Seigneur, si c\'est toi, ordonne que j\'aille vers toi sur les eaux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 29, 'Jésus lui dit: Viens! Pierre, étant descendu de la barque, marcha sur les eaux et alla vers Jésus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 30, 'Mais, voyant la violence du vent, il eut peur; et, comme il commençait à s\'enfoncer, il s\'écria: Seigneur, sauve-moi!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 31, 'Aussitôt Jésus, étendant la main, le saisit et lui dit: Homme de peu de foi, pourquoi as-tu douté?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 32, 'Et quand ils furent montés dans la barque, le vent s\'apaisa.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 33, 'Alors ceux qui étaient dans la barque vinrent et se prosternèrent devant lui, en disant: Tu es véritablement le Fils de Dieu!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 34, 'Ayant traversé la mer, ils abordèrent au pays de Génézareth.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 35, 'Quand les gens de ce lieu-là l\'eurent reconnu, ils envoyèrent dans toute la contrée d\'alentour, et on lui amena tous les malades.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 36, 'Ils le priaient de les laisser seulement toucher le bord de son vêtement; et tous ceux qui le touchèrent furent guéris.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 1, 'Alors des pharisiens et des scribes, venus de Jérusalem, s\'approchèrent de Jésus et lui dirent:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 2, 'Pourquoi tes disciples transgressent-ils la tradition des anciens? Car ils ne se lavent pas les mains, lorsqu\'ils prennent leur repas.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 3, 'Il leur répondit: Et vous, pourquoi transgressez-vous le commandement de Dieu par votre tradition?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 4, 'Car Dieu a donné ce commandement: «Honore ton père et ta mère»; et: «Que celui qui maudira son père ou sa mère soit puni de mort!!-»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 5, 'Mais vous, vous dites: Celui qui dira à son père ou à sa mère: J\'ai offert à Dieu ce dont je pourrais t\'assister, — celui-là ne sera pas tenu d\'honorer son père ou sa mère.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 6, 'Ainsi, vous avez anéanti la parole de Dieu par votre tradition.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 7, 'Hypocrites! Ésaïe a bien prophétisé à votre sujet, lorsqu\'il a dit:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 8, '«Ce peuple m\'honore des lèvres; mais son coeur est bien éloigné de moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 9, 'C\'est en vain qu\'ils me rendent un culte; ils enseignent des préceptes qui ne sont que des commandements d\'hommes.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 10, 'Puis, ayant appelé la foule, il leur dit: Écoutez et comprenez:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 11, 'Ce n\'est pas ce qui entre dans la bouche qui souille l\'homme; mais ce qui sort de la bouche, voilà ce qui souille l\'homme!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 12, 'Alors ses disciples, s\'approchant, lui dirent: Sais-tu que les pharisiens ont été scandalisés, quand ils ont entendu tes paroles?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 13, 'Il leur répondit: Toute plante que mon Père céleste n\'a point plantée sera déracinée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 14, 'Laissez-les: ce sont des aveugles, conducteurs d\'aveugles; si un aveugle conduit un aveugle, ils tomberont tous deux dans la fosse.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 15, 'Alors Pierre, prenant la parole, lui dit: Explique-nous cette parabole.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 16, 'Et Jésus dit: Vous aussi, vous êtes encore sans intelligence!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 17, 'Ne comprenez-vous pas que tout ce qui entre dans la bouche passe dans le ventre, et est rejeté en quelque lieu secret?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 18, 'Mais ce qui sort de la bouche vient du coeur; c\'est là ce qui souille l\'homme!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 19, 'Car c\'est du coeur que viennent les mauvaises pensées, les meurtres, les adultères, les impudicités, les vols, les faux témoignages, les calomnies.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 20, 'Voilà les choses qui souillent l\'homme! Mais manger sans s\'être lavé les mains, cela ne souille point l\'homme.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 21, 'Jésus, étant parti de là, se retira dans le territoire de Tyr et de Sidon.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 22, 'Et une femme cananéenne, qui venait de ce pays, s\'écria: Seigneur, fils de David, aie pitié de moi! Ma fille est cruellement tourmentée par un démon.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 23, 'Mais il ne lui répondit pas un mot. Alors, ses disciples, s\'étant approchés, lui disaient avec insistance: Renvoie-la; car elle nous poursuit de ses cris.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 24, 'Il répondit: Je n\'ai été envoyé qu\'aux brebis perdues de la maison d\'Israël.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 25, 'Mais elle vint et se prosterna en disant: Seigneur, aide-moi!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 26, 'Il lui répondit: Il ne convient pas de prendre le pain des enfants, pour le jeter aux petits chiens.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 27, 'Mais elle reprit: Assurément, Seigneur; pourtant les petits chiens mangent des miettes qui tombent de la table de leurs maîtres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 28, 'Alors Jésus lui dit: femme, ta foi est grande; qu\'il te soit fait comme tu le veux! Et à cette heure même, sa fille fut guérie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 29, 'Jésus partit de là et vint près de la mer de Galilée; puis, étant allé sur la montagne, il s\'y arrêta.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 30, 'Alors une grande foule s\'approcha de lui, ayant avec elle des boiteux, des aveugles, des muets, des estropiés, et beaucoup d\'autres malades qu\'on mit aux pieds de Jésus, et il les guérit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 31, 'Aussi la multitude était-elle dans l\'admiration, voyant que les muets parlaient, que les estropiés étaient guéris, que les boiteux marchaient, que les aveugles voyaient; et elle glorifiait le Dieu d\'Israël.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 32, 'Jésus, ayant appelé ses disciples, leur dit: J\'ai compassion de cette multitude; car il y a déjà trois jours que ces gens-là ne me quittent point, et ils n\'ont rien à manger; je ne veux pas les renvoyer à jeun, de peur qu\'ils ne défaillent en chemin.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 33, 'Ses disciples lui dirent: D\'où pourrions-nous avoir, dans ce désert, assez de pain pour rassasier une telle multitude?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 34, 'Jésus leur demanda: Combien avez-vous de pains? Ils répondirent: Sept, et quelques poissons.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 35, 'Alors il commanda à la foule de s\'asseoir à terre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 36, 'Puis il prit les sept pains et les poissons; et, après avoir rendu grâces, il les rompit et les donna à ses disciples, et les disciples les donnèrent à la foule.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 37, 'Tous mangèrent et furent rassasiés, et l\'on emporta sept corbeilles pleines des morceaux qui restaient.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 38, 'Or, ceux qui avaient mangé étaient au nombre de quatre mille hommes, sans compter les enfants et les femmes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 39, 'Alors Jésus, ayant renvoyé la multitude, entra dans la barque et vint au pays de Magadan.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 1, 'Les pharisiens et les sadducéens s\'approchèrent de Jésus; et, pour le mettre à l\'épreuve, ils lui demandèrent de leur faire voir un miracle venant du ciel.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 2, 'Mais il leur répondit: [Quand le soir est venu, vous dites: Il fera beau temps; car le ciel est rouge.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 3, 'Et le matin: Il y aura aujourd\'hui de l\'orage; car le ciel est sombre et rouge. Vous savez bien discerner l\'aspect du ciel, et vous ne pouvez pas discerner les signes des temps!]');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 4, 'Cette génération méchante et adultère demande un miracle; mais il ne lui en sera pas donné d\'autre que celui de Jonas. Et, les laissant, il s\'en alla.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 5, 'Les disciples, en passant à l\'autre bord, avaient oublié de prendre des pains.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 6, 'Jésus leur dit: Gardez-vous avec soin du levain des pharisiens et des sadducéens.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 7, 'Ils pensaient et se disaient entre eux: C\'est parce que nous n\'avons pas pris de pains.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 8, 'Jésus, connaissant cela, leur dit: Gens de peu de foi, pourquoi pensez-vous que c\'est parce que vous n\'avez pas de pains?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 9, 'Ne comprenez-vous pas encore, et ne vous souvenez-vous pas des cinq pains des cinq mille hommes, et combien vous avez remporté de paniers;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 10, 'ou des sept pains des quatre mille hommes, et combien vous avez remporté de corbeilles?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 11, 'Comment ne comprenez-vous pas que ce n\'est pas de pains que je parlais, quand je vous ai dit: Gardez-vous du levain des pharisiens et des sadducéens.?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 12, 'Alors ils comprirent qu\'il ne leur avait pas dit de se garder du levain du pain, mais de la doctrine des pharisiens et des sadducéens.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 13, 'Étant arrivé sur le territoire de Césarée de Philippe, Jésus interrogea ses disciples en disant: Qui est le fils de l\'homme, d\'après ce que les hommes en disent?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 14, 'Ils lui répondirent: Les uns disent que c\'est Jean-Baptiste; les autres, Élie; d\'autres, Jérémie ou l\'un des prophètes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 15, 'Il leur dit: Mais vous, qui dites-vous que je suis?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 16, 'Simon Pierre, répondant, lui dit: Tu es le Christ, le Fils du Dieu vivant!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 17, 'Alors Jésus lui dit: Tu es heureux, Simon, fils de Jona; car ce n\'est pas la chair et le sang qui t\'ont révélé cela, mais mon Père, qui est dans les cieux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 18, 'Et moi, je te le déclare: Tu es Pierre, et sur cette pierre je bâtirai mon Église, et les portes des enfers ne prévaudront point contre elle.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 19, 'Je te donnerai, les clefs du royaume des cieux; tout ce que tu lieras sur la terre sera lié dans les cieux, et tout ce que tu délieras sur la terre sera délié dans les cieux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 20, 'Puis il enjoignit à ses disciples de ne dire à personne que lui, Jésus, était le Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 21, 'Dès lors, Jésus commença à démontrer à ses disciples qu\'il fallait qu\'il allât à Jérusalem, qu\'il y souffrît beaucoup de la part des anciens, des principaux sacrificateurs et des scribes, qu\'il fût mis à mort, et qu\'il ressuscitât le troisième jour.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 22, 'Alors Pierre, l\'ayant pris à part, se mit à lui faire des reproches et à lui dire: A Dieu ne plaise. Seigneur, cela ne t\'arrivera point!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 23, 'Mais Jésus, se tournant, dit à Pierre: Arrière de moi, Satan, tu m\'es en scandale; car tu penses comme les hommes, et tes pensées ne viennent pas de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 24, 'Alors Jésus dit à ses disciples: Si quelqu\'un veut venir après moi, qu\'il renonce à lui-même, qu\'il se charge de sa croix, et qu\'il me suive.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 25, 'Car celui qui voudra sauver sa vie la perdra; mais celui qui aura perdu sa vie à cause de moi la retrouvera.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 26, 'Que servirait-il à un homme de gagner le monde entier, s\'il perdait son âme? Ou que donnerait l\'homme en échange de son âme?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 27, 'Car le Fils de l\'homme doit venir dans la gloire de son Père, avec ses anges, et alors il rendra à chacun selon ses oeuvres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 28, 'En vérité, je vous le déclare, quelques-uns de ceux qui sont ici présents ne mourront pas, qu\'ils n\'aient vu le Fils de l\'homme venir dans son règne.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 1, 'Six jours après, Jésus prit avec lui Pierre, Jacques et Jean, son frère, et il les mena sur une haute montagne, à l\'écart.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 2, 'Il fut transfiguré en leur présence: son visage devint resplendissant comme le soleil, et ses vêtements devinrent blancs comme la lumière.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 3, 'Et voici que Moïse et Élie leur apparurent, s\'entretenant avec lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 4, 'Alors Pierre, prenant la parole, dit à Jésus: Seigneur, il est bon pour nous d\'être ici; si tu veux, j\'y dresserai trois tentes, une pour toi, une pour Moïse, et une pour Élie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 5, 'Comme il parlait encore, une nuée lumineuse les couvrit; et on entendit une voix sortant de la nuée qui disait: Celui-ci est mon Fils bien-aimé, en qui j\'ai mis toute mon affection; écoutez-le.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 6, 'Les disciples, entendant cette voix, tombèrent le visage contre terre, et ils furent saisis d\'une grande crainte.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 7, 'Mais Jésus, s\'étant approché, les toucha et leur dit: Levez-vous, et n\'ayez point de peur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 8, 'Alors, levant les yeux, ils ne virent que Jésus seul.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 9, 'Comme ils descendaient de la montagne, Jésus leur fit cette défense: Ne dites à personne ce que vous avez vu, jusqu\'à ce que le Fils de l\'homme soit ressuscité des morts.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 10, 'Et ses disciples l\'interrogèrent, disant: Pourquoi donc les scribes disent-ils qu\'il faut qu\'Élie vienne premièrement?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 11, 'Il leur répondit: Il est vrai qu\'Élie doit venir et rétablir toutes choses.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 12, 'Mais je vous dis qu\'Élie est déjà venu, et ils ne l\'ont pas reconnu; mais ils lui ont fait tout ce qu\'ils ont voulu. C\'est ainsi qu\'à son tour le Fils de l\'homme doit souffrir par eux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 13, 'Alors les disciples comprirent que c\'était de Jean-Baptiste qu\'il leur parlait.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 14, 'Lorsqu\'ils eurent rejoint la foule, un homme s\'approcha, se jeta à genoux devant lui, et lui dit:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 15, 'Seigneur, aie pitié de mon fils! Il est lunatique, et il souffre beaucoup; car il tombe souvent dans le feu, et souvent dans l\'eau.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 16, 'Je l\'ai amené à tes disciples; mais ils n\'ont pu le guérir.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 17, 'Jésus répondit: Race incrédule et perverse, jusques à quand serai-je avec vous? Jusques à quand vous supporterai-je? Amenez-le-moi ici.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 18, 'Puis Jésus parla sévèrement au démon, qui sortit de l\'enfant; dès cette heure-là, l\'enfant fut guéri.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 19, 'Alors les disciples s\'approchèrent de Jésus, et le prenant à part, ils lui dirent: Pourquoi n\'avons-nous pu chasser ce démon?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 20, 'Il leur répondit: C\'est parce que vous manquez de foi; car, je vous le dis en vérité, si vous aviez de la foi comme un grain de moutarde, vous diriez à cette montagne: Transporte-toi d\'ici là, — et elle s\'y transporterait; et rien ne vous serait impossible.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 21, '[Mais cette sorte de démons ne sort que par la prière et par le jeûne,]');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 22, 'Comme ils parcouraient ensemble la Galilée, Jésus leur dit: Le Fils de l\'homme va être livré entre les mains des hommes,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 23, 'et ils le feront mourir; mais il ressuscitera le troisième jour. Alors les disciples furent fort affligés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 24, 'Quand ils furent arrivés à Capernaüm, ceux qui percevaient les didrachmes s\'approchèrent de Pierre et lui dirent: Votre maître ne paie-t-il pas les didrachmes?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 25, 'Il répondit: Il les paie. Quand il fut entré dans la maison, Jésus le prévint et lui dit: Que t\'en semble, Simon? Les rois de la terre, de qui tirent-ils des tributs ou des impôts? Est-ce de leurs fils ou des étrangers?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 26, 'Des étrangers, répondit Pierre. Jésus lui dit: Les fils en sont donc exempts!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 27, 'Toutefois, afin que nous ne les scandalisions pas, va-t-en à la mer, jette l\'hameçon, et tire le premier poisson qui se prendra. En lui ouvrant la bouche, tu trouveras un statère; prends-le, et donne-le-leur pour moi et pour toi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 1, 'A ce moment, les disciples s\'approchèrent de Jésus et lui dirent: Qui est le plus grand dans le royaume des cieux?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 2, 'Jésus, ayant appelé un petit enfant, le mit au milieu d\'eux,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 3, 'et il dit: En vérité, je vous le déclare, si vous ne changez et si vous ne devenez comme de petits enfants, vous n\'entrerez point dans le royaume des cieux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 4, 'Celui-là donc qui deviendra humble comme cet enfant, sera le plus grand dans le royaume des cieux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 5, 'Et celui qui reçoit un tel enfant en mon nom, me reçoit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 6, 'Mais si quelqu\'un fait tomber dans le péché l\'un de ces petits qui croient en moi, il vaudrait mieux pour lui qu\'on lui attachât au cou une meule de moulin, et qu\'on le jetât au fond de la mer.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 7, 'Malheur au monde à cause des scandales! Car il est nécessaire qu\'il arrive des scandales; mais malheur à l\'homme par qui le scandale arrive!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 8, 'Si donc ta main ou ton pied te fait tomber dans le péché, coupe-les et jette-les loin de toi; il vaut mieux que tu entres manchot ou boiteux dans la vie, que d\'avoir deux mains ou deux pieds et d\'être jeté dans le feu éternel.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 9, 'Si ton oeil te fait tomber dans le péché, arrache-le et jette-le loin de toi! Il vaut mieux que tu entres dans la vie n\'ayant qu\'un oeil, que d\'avoir deux yeux et d\'être jeté dans le feu de la géhenne.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 10, 'Gardez-vous de mépriser aucun de ces petits; car je vous dis que leurs anges, dans les cieux, voient sans cesse la face de mon Père, qui est dans les cieux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 11, '[Car le fils de l\'homme est venu sauver ce qui était perdu.].');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 12, 'Que vous en semble? Si un homme a cent brebis et que l\'une d\'elles s\'égare, ne laisse-t-il pas les quatre-vingt-dix-neuf dans les montagnes, pour aller chercher celle qui s\'est égarée?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 13, 'Et s\'il lui arrive de la retrouver, en vérité, je vous le dis, il en a plus de joie que des quatre-vingt-dix-neuf qui ne sont pas égarées.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 14, 'De même, ce n\'est pas la volonté de votre Père, qui est dans les cieux, qu\'un seul de ces petits périsse.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 15, 'Si ton frère a péché contre toi, va et reprends-le entre toi et lui seul; s\'il t\'écoute, tu auras gagné ton frère.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 16, 'S\'il ne t\'écoute pas, prends encore avec toi une ou deux personnes, afin que toute l\'affaire soit décidée sur la parole de deux ou trois témoins.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 17, 'S\'il refuse de les écouter, dis-le à l\'Eglise, et s\'il refuse d\'écouter l\'Église, qu\'il soit pour toi comme le païen et le péager.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 18, 'En vérité, je vous le déclare, tout ce que vous aurez lié sur la terre sera lié dans le ciel, et tout ce que vous aurez délié sur la terre sera délié dans le ciel.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 19, 'En vérité, je vous dis encore que si deux d\'entre vous sur la terre s\'accordent pour demander quoi que ce soit, ils l\'obtiendront de mon Père qui est dans les cieux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 20, 'Car là où deux ou trois sont réunis en mon nom, je suis au milieu d\'eux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 21, 'Alors Pierre, s\'étant approché, lui dit: Seigneur, combien de fois pardonnerai-je à mon frère, quand il aura péché contre moi? Sera-ce jusqu\'à sept fois?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 22, 'Jésus lui répondit: Je ne te dis pas jusqu\'à sept fois, mais jusqu\'à soixante-dix fois sept fois.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 23, 'C\'est pourquoi, il en est du royaume des cieux comme d\'un roi qui voulut faire rendre leurs comptes à ses serviteurs.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 24, 'Quand il eut commencé à compter, on lui en amena un qui lui devait dix mille talents.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 25, 'Comme ce serviteur n\'avait pas de quoi payer, son maître commanda qu\'il fût vendu, lui, sa femme et ses enfants, et tout ce qu\'il avait, afin que la dette fût payée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 26, 'Le serviteur, tombant à ses pieds, se prosternait devant lui et lui disait: Aie patience envers moi, et je te paierai tout!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 27, 'Alors le maître de ce serviteur, ému de compassion, le laissa aller et lui remit sa dette.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 28, 'Mais cet homme, étant sorti, rencontra l\'un de ses compagnons de service, qui lui devait cent deniers; et, l\'ayant saisi, il l\'étranglait, en disant: Paie ce que tu dois!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 29, 'Son compagnon, tombant à ses pieds, le suppliait et lui disait: Aie patience envers moi, et je te paierai!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 30, 'Mais lui ne voulut pas; il s\'en alla pour le faire mettre en prison, jusqu\'à ce qu\'il eût payé sa dette.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 31, 'Ses compagnons, ayant vu ce qui s\'était passé, en furent extrêmement attristés, et ils vinrent rapporter à leur maître tout ce qui était arrivé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 32, 'Alors son maître le fit venir, et lui dit: Méchant serviteur, je t\'ai remis toute ta dette, parce que tu m\'as supplié de le faire;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 33, 'ne devais-tu pas avoir pitié de ton compagnon de service, comme j\'ai eu moi-même pitié de toi?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 34, 'Et son maître, irrité, le livra aux bourreaux, jusqu\'à ce qu\'il eût payé tout ce qu\'il lui devait.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 35, 'Ainsi vous fera mon Père céleste, si chacun de vous ne pardonne pas à son frère de tout son coeur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 1, 'Or il arriva, quand Jésus eut achevé ces discours, qu\'il partit de la Galilée et vint sur le territoire de la Judée, au delà du Jourdain.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 2, 'De grandes foules l\'y suivirent, et il guérit leurs malades.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 3, 'Alors les pharisiens s\'approchèrent pour le mettre à l\'épreuve, et ils lui dirent: Est-il permis de répudier sa femme, pour quelque sujet que ce soit?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 4, 'Il leur répondit: N\'avez-vous pas lu que le Créateur, au commencement, fit un homme et une femme,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 5, 'et qu\'il dit: «C\'est pourquoi, l\'homme quittera son père et sa mère, et s\'attachera à sa femme; et les deux ne feront plus qu\'une seule chair»?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 6, 'Ainsi ils ne sont plus deux, mais une seule chair. Que l\'homme ne sépare donc pas ce que Dieu a uni!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 7, 'Ils lui dirent: Pourquoi donc Moïse a-t-il commandé de donner à la femme une lettre de divorce pour la répudier?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 8, 'Il leur répondit: C\'est à cause de la dureté de votre coeur que Moïse vous a permis de répudier vos femmes; mais, au commencement, il n\'en était pas ainsi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 9, 'Or, je vous le déclare, quiconque répudie sa femme, si ce n\'est pour inconduite, et en épouse une autre, commet un adultère.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 10, 'Ses disciples lui dirent: Si telle est la condition de l\'homme à l\'égard de la femme, il vaut mieux ne pas se marier!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 11, 'Il leur répondit: Tous ne sont pas capables d\'accepter cette parole, mais seulement ceux à qui cela est donné.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 12, 'Car il y a des eunuques qui le sont dès le sein de leur mère; il y en a qui ont été faits eunuques par les hommes, et il y en a qui se sont faits eunuques eux-mêmes pour le royaume des cieux. Que celui qui peut recevoir cette parole, la reçoive!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 13, 'A ce moment, on lui présenta des petits enfants, afin qu\'il leur imposât les mains et qu\'il priât pour eux; et les disciples reprenaient ceux qui les présentaient.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 14, 'Mais Jésus leur dit: Laissez venir à moi les petits enfants, et ne les en empêchez point; car le royaume des cieux est pour ceux qui leur ressemblent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 15, 'Et, leur ayant imposé les mains, il partit de là.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 16, 'Alors un homme s\'approcha et lui dit: Maître, que dois-je faire de bon pour avoir la vie éternelle?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 17, 'Jésus lui dit: Pourquoi m\'interroges-tu sur ce qui est bon? Un seul est bon. Si tu veux entrer dans la vie, observe les commandements.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 18, '— Lesquels? dit-il. — Jésus lui répondit: Ceux-ci: «Tu ne tueras point; tu ne commettras point d\'adultère; tu ne déroberas point; tu ne diras point de faux témoignage;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 19, 'honore ton père et ta mère»; et aussi: «Tu aimeras ton prochain comme toi-même.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 20, 'Le jeune homme lui dit: J\'ai observé toutes ces choses; que me manque-t-il encore?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 21, 'Jésus lui dit: Si tu veux être parfait, va, vends ce que tu as, donne-le aux pauvres, et tu auras un trésor dans le ciel; puis, viens et suis-moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 22, 'Mais quand le jeune homme eut entendu cette parole, il s\'en alla tout triste; car il avait de grands biens.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 23, 'Alors Jésus dit à ses disciples: En vérité, je vous le déclare, un riche entrera difficilement dans le royaume des cieux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 24, 'Je vous le répète: Il est plus aisé qu\'un chameau passe par le trou de l\'aiguille, qu\'il ne l\'est à un riche d\'entrer dans le royaume de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 25, 'En entendant ces paroles, ses disciples furent extrêmement étonnés, et ils disaient: Qui donc peut être sauvé?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 26, 'Jésus, les regardant, leur dit: Cela est impossible aux hommes; mais tout est possible à Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 27, 'Alors Pierre, prenant la parole, lui dit: Et nous, nous avons tout quitté, et nous t\'avons suivi; qu\'avons-nous donc à attendre?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 28, 'Jésus leur répondit: En vérité, je vous le déclare, au renouvellement de toutes choses, lorsque le Fils de l\'homme sera assis sur le trône de sa gloire, vous qui m\'avez suivi, vous serez de même assis sur douze trônes, jugeant les douze tribus d\'Israël.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 29, 'Et quiconque aura quitté frères ou soeurs, ou père, ou mère, ou enfants, ou champs, ou maisons, à cause de mon nom, recevra beaucoup plus, et il héritera de la vie éternelle.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 30, 'Mais plusieurs des premiers seront les derniers, et plusieurs des derniers seront les premiers.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 1, 'En effet, le royaume des cieux est semblable à un père de famille, qui sortit dès le point du jour, afin de louer des ouvriers pour sa vigne.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 2, 'Il convint avec les ouvriers de leur donner un denier par jour, et il les envoya à sa vigne.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 3, 'Il sortit encore vers la troisième heure, et il en vit d\'autres qui se tenaient sur la place sans rien faire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 4, 'Il leur dit: Allez, vous aussi, à la vigne, et je vous donnerai ce qui sera juste. Et ils y allèrent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 5, 'Il sortit de nouveau vers la sixième et vers la neuvième heure, et il fit de même.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 6, 'Étant sorti vers la onzième heure, il en trouva d\'autres qui se tenaient sur la place, et il leur dit: Pourquoi vous tenez-vous ici tout le jour sans rien faire?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 7, 'Ils lui répondirent: Parce que personne ne nous a loués. Il leur dit: Allez, vous aussi, à la vigne.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 8, 'Quand le soir fut venu, le maître de la vigne dit à son intendant: Appelle les ouvriers, et paie-leur le salaire, en commençant par les derniers et finissant par les premiers.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 9, 'Ceux de la onzième heure étant venus, reçurent chacun un denier.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 10, 'Les premiers, venant à leur tour, s\'attendaient à recevoir davantage; mais ils reçurent, eux aussi, chacun un denier.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 11, 'En le recevant, ils murmuraient contre le père de famille, et ils disaient:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 12, 'Ces derniers n\'ont travaillé qu\'une heure, et tu les as traités comme nous, qui avons supporté le labeur accablant du jour et la chaleur!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 13, 'Mais il répondit à l\'un d\'eux: Mon ami, je ne te fais point de tort; n\'avons-nous pas convenu ensemble que tu aurais un denier?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 14, 'Prends ce qui est à toi, et va-t-en! Je veux donner à ce dernier autant qu\'à toi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 15, 'Ne m\'est-il pas permis de faire ce que je veux de ce qui m\'appartient? Ou vois-tu de mauvais oeil que je sois bon?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 16, 'Ainsi les derniers seront les premiers, et les premiers seront les derniers.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 17, 'Jésus, montant à Jérusalem, prit à part ses douze disciples, et il leur dit en chemin:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 18, 'Voici que nous montons à Jérusalem; le Fils de l\'homme sera livré aux principaux sacrificateurs et aux scribes, et ils le condamneront à mort.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 19, 'Ils le livreront aux Païens, pour qu\'il soit exposé à la moquerie, battu de verges et crucifié; et le troisième jour, il ressuscitera.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 20, 'Alors la mère des fils de Zébédée s\'approcha de lui avec ses fils, et elle se prosterna pour lui faire une demande.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 21, 'Jésus lui dit: Que veux-tu? Ordonne, lui dit-elle, que mes deux fils, que voilà, soient assis l\'un à ta droite et l\'autre à ta gauche, dans ton royaume.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 22, 'Jésus répondit: Vous ne savez pas ce que vous demandez. Pouvez-vous boire la coupe que je dois boire? Ils lui dirent: Nous le pouvons.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 23, 'Il reprit: Il est vrai que vous boirez ma coupe; mais quant à être assis à ma droite ou à ma gauche, ce n\'est pas à moi de l\'accorder; ce sera pour ceux à qui mon Père l\'a préparé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 24, 'Les dix autres, qui avaient entendu cette demande, furent indignés contre les deux frères.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 25, 'Mais Jésus les appela et leur dit: Vous savez que les princes des nations les asservissent, et que les grands les tiennent sous leur puissance.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 26, 'Il n\'en sera pas ainsi parmi vous; au contraire, celui qui voudra être grand parmi vous sera votre serviteur,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 27, 'et celui qui voudra être le premier parmi vous sera votre esclave.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 28, 'C\'est ainsi que le Fils de l\'homme est venu, non pour être servi, mais pour servir, et donner sa vie pour la rançon de plusieurs.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 29, 'Comme ils sortaient de Jérico, une grande foule suivit Jésus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 30, 'Et voici que deux aveugles, assis au bord du chemin, ayant entendu dire que Jésus passait, se mirent à crier: Seigneur, fils de David, aie pitié de nous!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 31, 'La foule les reprit pour les faire taire; mais ils crièrent plus fort: Seigneur, Fils de David, aie pitié de nous!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 32, 'Jésus, s\'arrêtant, les appela et leur dit: Que voulez-vous que je vous fasse?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 33, 'Ils lui répondirent; Seigneur, que nos yeux soient ouverts!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 34, 'Alors Jésus, ému de compassion, toucha leurs yeux; et aussitôt ils recouvrèrent la vue, et ils le suivirent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 1, 'Comme ils approchaient de Jérusalem, et qu\'ils étaient déjà à Bethphagé, près de la montagne des Oliviers, Jésus envoya deux disciples,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 2, 'en leur disant: Allez au village qui est devant vous; vous trouverez aussitôt une ânesse attachée, et un ânon avec elle; détachez-les et amenez-les-moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 3, 'Si l\'on vous dit quelque chose, vous répondrez que le Seigneur en a besoin; et aussitôt on les enverra.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 4, 'Or, tout cela eut lieu, afin que cette parole du prophète fût accomplie:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 5, '«Dites à la fille de Sion: Voici que ton roi vient à toi, débonnaire, monté sur un âne, sur un ânon, le petit de celle qui porte le joug.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 6, 'Les disciples s\'en allèrent donc et firent ce que Jésus leur avait ordonné.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 7, 'Ils amenèrent l\'ânesse et l\'ânon, et, ayant mis leurs vêtements dessus, ils l\'y firent asseoir.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 8, 'Alors le peuple, en foule, étendit ses vêtements sur le chemin; d\'autres coupaient des branches aux arbres et en jonchaient la route.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 9, 'Et les foules qui marchaient devant lui comme celles qui suivaient, criaient: Hosanna au fils de David! Béni soit celui qui vient au nom du Seigneur! Hosanna au plus haut des cieux!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 10, 'Quand il fut entré dans Jérusalem, toute la ville fut en émoi, et on disait: Qui est celui-ci?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 11, 'Et la foule répondait: C\'est Jésus, le prophète de Nazareth, en Galilée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 12, 'Jésus entra dans le temple, et il en chassa tous ceux qui vendaient et qui achetaient; il renversa les tables des changeurs et les sièges de ceux qui vendaient les pigeons.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 13, 'Puis il leur dit: Il est écrit: «Ma maison sera appelée une maison de prière»; mais vous, vous en faites une caverne de voleurs!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 14, 'Alors des aveugles et des boiteux vinrent à lui dans le temple, et il les guérit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 15, 'Mais les principaux sacrificateurs et les scribes, voyant les merveilles qu\'il avait faites, et les enfants qui criaient dans le temple: Hosanna au Fils de David! en furent indignés,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 16, 'et ils lui dirent: Entends-tu ce que disent ces enfants? Jésus leur répondit: Oui. N\'avez-vous donc jamais lu ces paroles: «Tu as tiré ta louange de la bouche des petits enfants et de ceux qui sont à la mamelle»?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 17, 'Puis, les ayant laissés, il sortit de la ville et s\'en alla à Béthanie, où il passa la nuit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 18, 'Le matin, comme il retournait à la ville, il eut faim.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 19, 'Voyant un figuier sur le chemin, il s\'en approcha; mais il n\'y trouva que des feuilles, et il lui dit: Que jamais plus il ne naisse de toi aucun fruit! Aussitôt le figuier sécha.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 20, 'Les disciples, ayant vu cela, s\'étonnèrent et dirent: Comment ce figuier est-il devenu sec en un instant?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 21, 'Jésus leur répondit: En vérité, je vous le déclare, si vous aviez de la foi, et que vous ne doutiez point, non seulement vous feriez ce qui a été fait au figuier, mais même si vous disiez à cette montagne: Soulève-toi et jette-toi dans la mer — cela se ferait.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 22, 'Et tout ce que vous demanderez avec foi, en priant, vous le recevrez.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 23, 'Quand il fut entré dans le temple, les principaux sacrificateurs et les anciens du peuple s\'approchèrent de lui, pendant qu\'il enseignait, et ils lui dirent: Par quelle autorité fais-tu ces choses? Et qui t\'a donné cette autorité?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 24, 'Jésus leur répondit: Je vous poserai, moi aussi, une question, et si vous m\'y répondez, je vous dirai aussi en vertu de quelle autorité je fais ces choses.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 25, 'Le baptême de Jean, d\'où venait-il: du ciel ou des hommes? Or, ils raisonnaient ainsi entre eux: Si nous répondons: du ciel — il nous dira: Pourquoi donc n\'avez-vous pas cru à sa parole?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 26, 'Et si nous répondons: des hommes — nous avons à craindre le peuple; car tous regardent Jean comme un prophète.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 27, 'Ils répondirent donc à Jésus: Nous ne savons! Il leur dit à son tour: Et moi non plus, je ne vous dirai point en vertu de quelle autorité je fais ces choses.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 28, 'Que vous semble-t-il de ceci? Un homme avait deux fils. Il s\'adressa au premier et lui dit: Mon enfant, va aujourd\'hui travailler à la vigne.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 29, 'Il répondit: Oui, Seigneur! Et il n\'y alla point. Puis le père vint à l\'autre, et il lui dit la même chose.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 30, 'Celui-ci répondit: Je ne veux pas! Mais plus tard, s\'étant repenti, il y alla.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 31, 'Lequel des deux a fait la volonté du Père? Ils lui dirent: C\'est le dernier. Jésus leur dit: En vérité, je vous le déclare, les péagers et les femmes de mauvaise vie vous devancent dans le royaume de Dieu!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 32, 'Car Jean est venu à vous dans la voie de la justice, et vous ne l\'avez point cru; mais les péagers et les femmes de mauvaise vie l\'ont cru. Et vous, qui avez vu cela, vous ne vous êtes pas repentis ensuite pour le croire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 33, 'Ecoutez une autre parabole: Il y avait un père de famille qui planta une vigne. Il l\'environna d\'une haie, y creusa un pressoir et y bâtit une tour; puis il la loua à des vignerons et quitta le pays.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 34, 'Le temps de la récolte étant proche, il envoya ses serviteurs auprès des vignerons pour recueillir le produit de sa vigne.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 35, 'Les vignerons, ayant saisi les serviteurs, battirent l\'un, tuèrent l\'autre, et ils en lapidèrent un troisième.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 36, 'Il envoya encore d\'autres serviteurs, en plus grand nombre que les premiers, et ils les traitèrent de même.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 37, 'Enfin, il leur envoya son propre fils, on disant: Ils respecteront mon fils!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 38, 'Mais quand les vignerons virent le fils, ils se dirent entre eux: C\'est l\'héritier. Allons! Tuons-le, et nous aurons son héritage.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 39, 'Puis l\'ayant saisi, ils le jetèrent hors de la vigne, et ils le tuèrent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 40, 'Quand donc le maître de la vigne viendra, que fera-t-il à ces vignerons?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 41, 'Ils lui répondirent: Il fera périr misérablement ces misérables, et il louera la vigne à d\'autres vignerons, qui lui en donneront les fruits dans la saison.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 42, 'Jésus leur dit: N\'avez-vous jamais lu dans les Écritures: «La pierre rejetée par ceux qui bâtissaient est devenue la pierre de l\'angle; c\'est l\'ouvrage du Seigneur, et c\'est une merveille devant nos yeux»?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 43, 'C\'est pourquoi, je vous le déclare, le royaume de Dieu vous sera ôté, et il sera donné à une nation qui en produira les fruits.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 44, 'Celui qui tombera sur cette pierre sera brisé, et celui sur qui elle tombera, elle l\'écrasera.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 45, 'Quand les principaux sacrificateurs et les pharisiens entendirent ces paraboles, ils comprirent qu\'il parlait d\'eux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 46, 'Ils cherchaient à se saisir de lui; mais ils avaient peur du peuple, parce qu\'on regardait Jésus comme un prophète.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 1, 'Jésus, parlant encore en paraboles, leur dit:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 2, 'Le royaume des cieux est semblable à un roi qui célébra les noces de son fils.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 3, 'Il envoya ses serviteurs pour appeler ceux qui avaient été invités aux noces; mais ils ne voulurent pas venir.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 4, 'Il envoya encore d\'autres serviteurs avec cet ordre: Dites aux invités: J\'ai préparé mon festin; mes boeufs et mes bêtes grasses sont tués, et tout est prêt; venez aux noces.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 5, 'Mais eux, n\'en tenant aucun compte, s\'en allèrent, l\'un à son champ, l\'autre à son trafic;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 6, 'les autres saisirent les serviteurs, les outragèrent et les tuèrent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 7, 'Le roi se mit en colère, et, ayant envoyé ses troupes, il fit périr ces meurtriers et brûla leur ville.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 8, 'Puis il dit à ses serviteurs: Le festin des noces est prêt mais ceux qui étaient invités n\'en étaient pas dignes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 9, 'Allez donc dans tous les carrefours, et invitez aux noces tous ceux que vous trouverez.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 10, 'Ces serviteurs, étant allés par les chemins, rassemblèrent tous ceux qui s\'y trouvèrent, tant mauvais que bons, en sorte que la salle des noces fut remplie de convives.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 11, 'Le roi, entrant pour voir ceux qui étaient à table, aperçut un homme qui n\'était pas vêtu d\'un habit de noce.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 12, 'Il lui dit: Mon ami, comment es-tu entré ici, sans avoir un habit de noce? Et cet homme eut la bouche fermée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 13, 'Alors le roi dit aux serviteurs: Liez-le pieds et mains, et jetez-le dans les ténèbres du dehors; c\'est là qu\'il y aura des pleurs et des grincements de dents.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 14, 'Car il y a beaucoup d\'appelés, mais peu d\'élus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 15, 'Alors les pharisiens, s\'étant retirés, tinrent conseil, afin de trouver dans les propres paroles de Jésus un piège contre lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 16, 'Et ils lui envoyèrent leurs disciples, avec les hérodiens, pour lui dire: Maître, nous savons que tu es véridique, et que tu enseignes la voie de Dieu en toute vérité, sans te préoccuper de personne; car tu ne regardes pas à l\'apparence des hommes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 17, 'Dis-nous donc ce que tu penses de ceci: Est-il permis de payer l\'impôt à César, ou non?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 18, 'Jésus, connaissant leur malice, répondit: Pourquoi me tentez-vous, hypocrites?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 19, 'Montrez-moi la monnaie de l\'impôt! Ils lui présentèrent un denier.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 20, 'Et il leur dit: Cette effigie et cette inscription, de qui sont-elles?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 21, '— Ils lui répondirent: de César. Alors il leur dit: Rendez donc à César ce qui est à César, et à Dieu ce qui est à Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 22, 'En entendant cette réponse, ils furent dans l\'étonnement; et le laissant, ils s\'en allèrent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 23, 'Ce même jour, les sadducéens, qui disent qu\'il n\'y a point de résurrection, s\'approchèrent de Jésus, et ils lui firent cette question:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 24, 'Maître, Moïse a dit: «Si quelqu\'un meurt sans enfants, son frère épousera sa veuve, et il suscitera une postérité à son frère.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 25, 'Or, il y avait parmi nous sept frères. Le premier se maria et mourut; et comme il n\'avait point d\'enfants, il laissa sa femme à son frère.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 26, 'De même aussi le second, puis le troisième, jusqu\'au septième.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 27, 'Après eux tous, la femme mourut aussi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 28, 'Duquel des sept sera-t-elle donc la femme, lors de la résurrection, puisque tous l\'ont eue pour femme?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 29, 'Jésus leur répondit: Vous êtes dans l\'erreur, parce que vous ne comprenez pas les Écritures, ni quelle est la puissance de Dieu!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 30, 'Car, à la résurrection, on ne se marie pas, et on n\'est pas donné en mariage; mais les ressuscités sont comme les anges dans le ciel.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 31, 'Quant à la résurrection des morts, n\'avez-vous pas lu la parole que Dieu vous a dite:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 32, '«Je suis le Dieu d\'Abraham, le Dieu d\'Isaac et le Dieu de Jacob»? Il n\'est pas le Dieu des morts, mais le Dieu des vivants.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 33, 'Le peuple, entendant ces paroles, était frappé de son enseignement.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 34, 'Les pharisiens, ayant appris qu\'il avait fermé la bouche aux sadducéens, se rassemblèrent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 35, 'Et l\'un d\'eux, docteur de la loi, l\'interrogea pour l\'éprouver, et lui dit:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 36, 'Maître, quel est, dans la loi, le grand commandement?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 37, 'Jésus lui répondit: «Tu aimeras le Seigneur, ton Dieu, de tout ton coeur, de toute ton âme, et de toute ta pensée».');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 38, 'C\'est là le grand, le premier commandement.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 39, 'Et voici le second, qui lui est semblable: «Tu aimeras ton prochain comme toi-même».');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 40, 'De ces deux commandements dépendent toute la loi et les prophètes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 41, 'Les pharisiens étant assemblés, Jésus les interrogea,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 42, 'et il leur dit: Que pensez-vous du Christ? De qui est-il fils?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 43, 'Ils lui répondirent: De David. Il leur dit: Comment donc David, parlant par l\'Esprit, l\'appelle-t-il Seigneur, en disant:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 44, '«Le Seigneur a dit à mon Seigneur: Assieds-toi à ma droite, jusqu\'à ce que j\'aie mis tes ennemis sous tes pieds»?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 45, 'Si donc David l\'appelle Seigneur, comment est-il son fils?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 46, 'Personne ne put lui répondre un mot; et, depuis ce jour-là, nul n\'osa plus l\'interroger.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 1, 'Alors Jésus parla au peuple et à ses disciples, et il leur dit:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 2, 'Les scribes et les pharisiens sont assis dans la chaire de Moïse.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 3, 'Faites donc et observez tout ce qu\'ils vous disent; mais ne faites pas comme eux, parce qu\'ils disent et ne font pas.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 4, 'Ils lient des fardeaux pesants et les mettent sur les épaules des hommes; mais pour eux, ils ne veulent pas les remuer du doigt!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 5, 'Ils font toutes leurs actions pour être vus des hommes: ils élargissent leurs phylactères, et ils allongent les franges de leurs manteaux;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 6, 'ils aiment à avoir la première place dans les festins et les premiers sièges dans les synagogues,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 7, 'à être salués dans les places publiques et à être appelés par les hommes: Maître!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 8, 'Mais vous, ne vous faites point appeler maître. Car vous n\'avez qu\'un seul Maître; et vous êtes tous frères.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 9, 'N\'appelez personne sur la terre votre père; car vous n\'avez qu\'un seul Père, celui qui est dans les cieux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 10, 'Et ne vous faites pas appeler directeurs; car vous n\'avez qu\'un seul Directeur, le Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 11, 'Mais le plus grand d\'entre vous sera votre serviteur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 12, 'Quiconque s\'élèvera sera abaissé, et quiconque s\'abaissera sera élevé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 13, 'Malheur à vous, scribes et pharisiens hypocrites! Car vous fermez aux hommes le royaume des cieux; vous n\'y entrez pas, et ceux qui veulent y entrer, vous les en empêchez!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 14, '[Malheur à vous, scribes et pharisiens hypocrites! Car vous dévorez les maisons des veuves, en affectant de faire de longues prières! A cause de cela, vous subirez un jugement plus rigoureux.]');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 15, 'Malheur à vous, scribes et pharisiens hypocrites! Car vous courez la mer et la terre pour faire un prosélyte; et, quand vous l\'avez, vous en faites un enfant de la géhenne deux fois plus que vous!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 16, 'Malheur à vous, conducteurs aveugles, qui dites: Si quelqu\'un jure par le temple, ce n\'est rien, mais s\'il jure par l\'or du temple, il est lié par son serment.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 17, 'Insensés et aveugles, lequel est le plus grand, l\'or ou le temple qui rend cet or sacré?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 18, 'Et si quelqu\'un, dites-vous, jure par l\'autel, ce n\'est rien; mais s\'il jure par l\'offrande qui est sur l\'autel, il est lié par son serment.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 19, 'Aveugles, lequel est le plus grand, l\'offrande ou l\'autel qui rend cette offrande sacrée?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 20, 'Celui donc qui jure par l\'autel, jure par l\'autel et par tout ce qui est dessus;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 21, 'celui qui jure par le temple, jure par le temple et par celui qui en fait sa demeure;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 22, 'et celui qui jure par le ciel, jure par le trône de Dieu, et par celui qui y est assis.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 23, 'Malheur à vous, scribes et pharisiens hypocrites! Car vous payez la dîme de la menthe, de l\'aneth et du cumin, et vous négligez les choses les plus importantes de la loi: la justice, la miséricorde et la fidélité. Voilà les choses qu\'il fallait faire, sans omettre les autres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 24, 'Conducteurs aveugles, qui arrêtez le moucheron dans votre filtre et qui avalez le chameau!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 25, 'Malheur à vous, scribes et pharisiens hypocrites! Car vous nettoyez le dehors de la coupe et du plat, tandis que l\'intérieur est plein de rapacité et d\'intempérance.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 26, 'Pharisien aveugle, nettoie premièrement le dedans de la coupe et du plat, afin que le dehors aussi devienne pur!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 27, 'Malheur à vous, scribes et pharisiens hypocrites! Car vous ressemblez à des sépulcres blanchis, qui, au dehors, paraissent beaux, mais qui, au dedans, sont pleins d\'ossements de morts et de toutes sortes d\'impuretés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 28, 'Vous de même, au dehors, vous paraissez justes aux hommes, mais, au dedans, vous êtes remplis d\'hypocrisie et d\'iniquité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 29, 'Malheur à vous, scribes et pharisiens hypocrites! Car vous bâtissez les tombeaux des prophètes, et vous ornez les sépulcres des justes;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 30, 'puis vous dites: Si nous avions vécu du temps de nos pères, nous ne nous serions pas joints à eux pour répandre le sang des prophètes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 31, 'Ainsi, vous témoignez contre vous-mêmes que vous êtes bien les fils des meurtriers des prophètes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 32, 'Comblez donc la mesure de vos pères!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 33, 'Serpents, race de vipères, comment échapperez-vous au châtiment de la géhenne?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 34, 'C\'est pourquoi, voici que je vous envoie des prophètes, des sages et des scribes; vous tuerez et crucifierez les uns; vous battrez de verges les autres dans vos synagogues, et vous les persécuterez de ville en ville,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 35, 'afin que retombe sur vous tout le sang innocent qui a été répandu sur la terre, depuis le sang d\'Abel, le juste, jusqu\'au sang de Zacharie, fils de Barachie, que vous avez assassiné entre le temple et l\'autel.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 36, 'En vérité, je vous le dis, tous ces malheurs viendront sur cette génération.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 37, 'Jérusalem, Jérusalem, qui tues les prophètes et qui lapides ceux qui te sont envoyés, combien de fois j\'ai voulu rassembler tes enfants, comme une poule rassemble ses poussins sous ses ailes, et vous ne l\'avez pas voulu!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 38, 'Voici que votre demeure va vous être laissée déserte!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 39, 'Car, je vous le déclare, vous ne me verrez plus désormais, jusqu\'à ce que vous disiez: «Béni soit celui qui vient au nom du Seigneur!»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 1, 'Comme Jésus sortait du temple et s\'éloignait, ses disciples s\'approchèrent pour lui en faire considérer les bâtiments.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 2, 'Mais il leur répondit: Vous voyez tout cela? En vérité, je vous le déclare, il ne restera ici pierre sur pierre qui ne soit renversée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 3, 'Comme il était assis sur la montagne des Oliviers, les disciples vinrent lui dire en particulier: Dis-nous quand ces choses arriveront, et quel sera le signe de ton avènement et de la fin du monde.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 4, 'Jésus leur répondit: Prenez garde que personne ne vous séduise!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 5, 'En effet, plusieurs viendront en mon nom, en disant: Je suis le Christ. Et ils séduiront beaucoup de gens.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 6, 'Vous entendrez parler de guerres et de bruits de guerres: prenez garde, ne vous troublez pas! Car il faut que ces choses arrivent. Mais ce ne sera pas encore la fin.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 7, 'Une nation s\'élèvera contre une nation, et un royaume contre un royaume; il y aura des famines et des tremblements de terre en divers lieux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 8, 'Mais tout cela ne sera que le commencement des douleurs.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 9, 'Alors ils vous livreront aux supplices, et ils vous feront mourir; et vous serez haïs de toutes les nations à cause de mon nom.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 10, 'Alors aussi, plusieurs succomberont à l\'épreuve; ils se trahiront les uns les autres et se haïront les uns les autres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 11, 'Plusieurs faux prophètes s\'élèveront et séduiront beaucoup de gens.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 12, 'Et parce que l\'iniquité sera multipliée, la charité du plus grand nombre se refroidira.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 13, 'Mais celui qui persévérera jusqu\'à la fin, celui-là sera sauvé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 14, 'Et cet Évangile du royaume sera prêché par toute la terre, pour servir de témoignage à toutes les nations. Alors viendra la fin.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 15, 'Quand vous verrez établie dans le lieu saint l\'abomination de la désolation, dont a parlé le prophète Daniel — que le lecteur fasse attention! —');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 16, 'que ceux qui seront alors dans la Judée s\'enfuient dans les montagnes;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 17, 'que celui qui sera sur le toit ne descende pas pour emporter ce qui est dans la maison;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 18, 'et que celui qui sera aux champs ne retourne pas en arrière pour prendre son manteau.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 19, 'Malheur aux femmes qui seront enceintes et à celles qui allaiteront en ces jours-là!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 20, 'Priez pour que votre fuite n\'arrive pas en hiver, ni en un jour de sabbat;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 21, 'car il y aura alors une grande affliction, telle qu\'il n\'y en a point eu de semblable depuis le commencement du monde jusqu\'à présent, et qu\'il n\'y en aura jamais.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 22, 'Et si ces jours-là n\'étaient pas abrégés, aucune créature ne serait sauvée; mais ces jours-là seront abrégé» à cause des élus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 23, 'Alors, si quelqu\'un vous dit: Voyez, le Christ est ici! — ou bien: Il est là! — ne le croyez point.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 24, 'Car de faux christs et de faux prophètes s\'élèveront et feront de grands signes et des prodiges, jusqu\'à séduire, s\'il était possible, les élus eux-mêmes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 25, 'Vous voilà prévenus!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 26, 'Si donc on vous dit: Le voici dans le désert. — n\'y allez pas! Le voici dans l\'intérieur de la maison!!- ne le croyez pas!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 27, 'Car, comme l\'éclair part de l\'Orient et brille jusqu\'à l\'Occident, il en sera de même de l\'avènement du Fils de l\'homme.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 28, 'Où sera le cadavre, là s\'assembleront les aigles.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 29, 'Aussitôt après l\'affliction de ces jours-là, le soleil s\'obscurcira, la lune ne donnera plus sa lumière, les étoiles tomberont du ciel, et les puissances des cieux seront ébranlées.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 30, 'Alors paraîtra dans le ciel le signe du Fils de l\'homme: toutes les tribus de la terre se frapperont la poitrine, et elles verront le Fils de l\'homme venir sur les nuées du ciel avec une grande puissance et une grande gloire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 31, 'Il enverra ses anges, qui, au son éclatant de la trompette, rassembleront ses élus des quatre vents, depuis une extrémité des cieux jusqu\'à l\'autre extrémité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 32, 'Écoutez une comparaison empruntée au figuier! Dès que ses branches deviennent tendres et qu\'il pousse des feuilles, vous savez que l\'été est proche.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 33, 'Vous aussi de même, quand vous verrez toutes ces choses, sachez que le Fils de l\'homme est proche, qu\'il est à la porte.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 34, 'En vérité, je vous le déclare, cette génération ne passera pas, que toutes ces choses n\'arrivent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 35, 'Le ciel et la terre passeront, mais mes paroles ne passeront point!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 36, 'Pour ce qui est de ce jour et de cette heure, personne n\'en sait rien, pas même les anges du ciel, ni même le Fils, mais le Père seul.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 37, 'Ce qui arriva aux jours de Noé arrivera de même à l\'avènement du Fils de l\'homme:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 38, 'dans les jours qui précédèrent le déluge, on mangeait et on buvait, on se mariait et on donnait en mariage, jusqu\'au jour où Noé entra dans l\'arche,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 39, '— et les hommes ne s\'avisèrent de rien, jusqu\'au moment où vint le déluge qui les emporta tous. — Il en sera de même à l\'avènement du Fils de l\'homme.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 40, 'Alors, deux hommes seront dans un champ; l\'un sera pris et l\'autre laissé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 41, 'Deux femmes moudront au moulin; l\'une sera prise et l\'autre laissée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 42, 'Veillez donc; car vous ne savez pas à quelle heure votre Seigneur doit venir.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 43, 'Sachez-le bien, si le père de famille savait à quelle heure de la nuit le voleur viendra, il veillerait et ne laisserait pas percer sa maison.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 44, 'Vous donc aussi, tenez-vous prêts; car le Fils de l\'homme viendra à l\'heure que vous ne pensez pas.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 45, 'Quel est le serviteur fidèle et prudent que le maître a établi sur ses domestiques, pour leur donner la nourriture au temps convenable?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 46, 'Heureux sera le serviteur que le maître, à son arrivée, trouvera agissant ainsi!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 47, 'En vérité, je vous le déclare, il l\'établira sur tous ses biens.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 48, 'Si, au contraire, c\'est un mauvais serviteur qui dise en son coeur: Mon maître tarde à venir. —');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 49, 'et qu\'il se mette à battre ses compagnons de service, à manger et à boire avec les ivrognes, —');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 50, 'le maître de ce serviteur viendra le jour où il ne s\'y attend pas, et à l\'heure qu\'il ne sait pas.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 51, 'Il le déchirera de coups de fouet, et il lui donnera son lot avec les hypocrites. C\'est là qu\'il y aura des pleurs et des grincements de dents.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 1, '!!- Alors le royaume des cieux sera semblable à dix vierges qui, ayant pris leurs lampes, allèrent à la rencontre de l\'époux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 2, 'Cinq d\'entre elles étaient folles, et cinq étaient sages.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 3, 'Celles qui étaient folles, en prenant leurs lampes, n\'avaient pas pris d\'huile avec elles.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 4, 'Mais les sages avaient pris de l\'huile dans leurs vases avec leurs lampes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 5, 'Comme l\'époux tardait à venir, elles s\'assoupirent toutes et s\'endormirent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 6, 'Au milieu de la nuit, un cri se fit entendre: Voici l\'époux; sortez à sa rencontre!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 7, 'Alors ces vierges se levèrent toutes et préparèrent leurs lampes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 8, 'Et les folles dirent aux sages: Donnez-nous de votre huile; car nos lampes s\'éteignent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 9, 'Mais les sages répondirent: Non; car il n\'y en aurait pas assez pour nous et pour vous. Allez plutôt chez ceux qui en vendent, et achetez-en pour vous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 10, 'Mais pendant qu\'elles allaient en acheter, l\'époux vint; celles qui étaient prêtes entrèrent avec lui dans la salle des noces, et la porte fut fermée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 11, 'Plus tard, les autres vinrent aussi et dirent: Seigneur, Seigneur, ouvre-nous!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 12, 'Mais il répondit: En vérité, je vous le dis, je ne vous connais point.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 13, 'Veillez donc, car vous ne savez ni le jour ni l\'heure.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 14, 'En effet, il en sera comme d\'un homme qui, partant pour un voyage, appela ses serviteurs et leur confia ses biens.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 15, 'A l\'un il donna cinq talents, à l\'autre deux, et à l\'autre un: à chacun selon sa capacité; puis il partit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 16, 'Aussitôt, celui qui avait reçu les cinq talents alla les faire valoir; et il gagna cinq autres talents.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 17, 'De même, celui qui en avait reçu deux en gagna deux autres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 18, 'Mais celui qui n\'en avait reçu qu\'un, s\'en alla, fit un trou dans la terre, et il y cacha l\'argent de son maître.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 19, 'Longtemps après, le maître de ces serviteurs revint, et il leur fit rendre compte.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 20, 'Alors, celui qui avait reçu les cinq talents vint, présenta cinq autres talents, puis il dit: Seigneur, tu m\'avais remis cinq talents; en voici cinq autres que j\'ai gagnés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 21, 'Son maître lui dit: Cela va bien, bon et fidèle serviteur; tu as été fidèle en peu de choses, je t\'établirai sur beaucoup; viens prendre part à la joie de ton seigneur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 22, 'Celui qui avait reçu les deux talents vint aussi et dit: Seigneur, tu m\'avais remis deux talents; en voici deux autres que j\'ai gagnés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 23, 'Son maître lui dit: Cela va bien, bon et fidèle serviteur; tu as été fidèle en peu de choses, je t\'établirai sur beaucoup; viens prendre part à la joie de ton seigneur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 24, 'Celui qui n\'avait reçu qu\'un talent vint aussi et dit: Seigneur, je savais que tu es un homme dur, qui moissonnes où tu n\'as rien semé, et qui ramasses où tu n\'as rien répandu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 25, 'J\'ai eu peur et je suis allé cacher ton talent dans la terre; le voici, tu as ce qui est à toi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 26, 'Mais son maître lui répondit: Méchant serviteur, tu savais que je moissonne où je n\'ai rien semé, et que je ramasse où je n\'ai rien répandu!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 27, 'Il te fallait donc porter mon argent aux banquiers; et, à mon retour, j\'aurais retiré ce qui est à moi avec l\'intérêt.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 28, 'Otez-lui donc le talent et donnez-le à celui qui a les dix talents.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 29, 'Car on donnera à celui qui a, et il sera dans l\'abondance; mais à celui qui n\'a pas, on ôtera même ce qu\'il a.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 30, 'Quant au serviteur inutile, jetez-le dans les ténèbres du dehors: c\'est là qu\'il y aura des pleurs et des grincements de dents.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 31, 'Quand le Fils de l\'homme viendra dans sa gloire, avec tous les anges, alors il s\'assiéra sur son trône de gloire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 32, 'Toutes les nations seront rassemblées devant lui, et il séparera les uns d\'avec les autres, comme le berger sépare les brebis d\'avec les boucs.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 33, 'Et il mettra les brebis à sa droite et les boucs à sa gauche.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 34, 'Alors le roi dira à ceux qui seront à sa droite: Venez, vous qui êtes bénis de mon Père; recevez en héritage le royaume qui vous a été préparé dès la création du monde.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 35, 'Car j\'ai eu faim, et vous m\'avez donné à manger; j\'ai eu soif, et vous m\'avez donné à boire; j\'étais étranger, et vous m\'avez recueilli;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 36, 'j\'étais nu, et vous m\'avez vêtu; j\'étais malade, et vous m\'avez visité; j\'étais en prison, et vous êtes venu auprès de moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 37, 'Alors les justes lui répondront: Seigneur, quand t\'avons-nous vu avoir faim, et t\'avons-nous donné à manger; ou avoir soif, et t\'avons-nous donné à boire?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 38, 'Et quand t\'avons-nous vu étranger, et t\'avons-nous recueilli; ou nu, t\'avons-nous vêtu?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 39, 'Ou quand t\'avons-nous vu malade ou en prison, et sommes-nous venus auprès de toi?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 40, 'Et le roi leur répondra: En vérité, je vous le déclare, toutes les fois que vous l\'avez fait à l\'un de ces plus petits de mes frères, vous me l\'avez fait à moi-même.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 41, 'Ensuite il dira à ceux qui seront à sa gauche: Retirez-vous de moi, maudits, allez dans le feu éternel, préparé pour le Diable et pour ses anges.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 42, 'Car j\'ai eu faim, et vous ne m\'avez pas donné à manger; j\'ai eu soif, et vous ne m\'avez pas donné à boire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 43, 'J\'étais étranger, et vous ne m\'avez pas recueilli. J\'étais nu, et vous ne m\'avez pas vêtu; malade et en prison, et vous ne m\'avez pas visité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 44, 'Alors ceux-ci leur répondront à leur tour: Seigneur, quand t\'avons-nous vu avoir faim, ou soif, être étranger, ou nu, ou malade, ou en prison, et ne t\'avons-nous pas assisté?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 45, 'Il leur répondra: En vérité, je vous le déclare, toutes les fois que vous ne l\'avez pas fait à l\'un de ces plus petits, vous ne me l\'avez pas fait à moi non plus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 46, 'Et ceux-ci s\'en iront au châtiment éternel, mais les justes iront à la vie éternelle.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 1, 'Or, il arriva, quand Jésus eut achevé tous ces discours, qu\'il dit à ses disciples:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 2, 'Vous savez que la Pâque aura lieu dans deux jours, et que le Fils de l\'homme va être livré pour être crucifié.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 3, 'Alors les principaux sacrificateurs et les anciens du peuple se réunirent dans la cour du souverain sacrificateur, nommé Caïphe,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 4, 'et ils tinrent conseil pour s\'emparer de Jésus par la ruse et le faire mourir.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 5, 'Mais ils disaient: Que ce ne soit pas pendant la fête, de peur qu\'il n\'y ait du tumulte parmi le peuple.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 6, 'Comme Jésus était à Béthanie, dans la maison de Simon le lépreux,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 7, 'une femme s\'approcha de lui, portant un vase d\'albâtre plein d\'un parfum de grand prix, et elle le lui répandit sur la tête, pendant qu\'il était à table.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 8, 'Les disciples, voyant cela, furent indignés');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 9, 'et dirent: A quoi bon cette perte? On pouvait vendre ce parfum très cher et en donner le prix aux pauvres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 10, 'Mais Jésus, s\'en étant aperçu, leur dit: Pourquoi faites-vous de la peine à cette femme? Elle a fait une bonne action à mon égard!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 11, 'Car vous avez toujours les pauvres avec vous; mais moi, vous ne m\'avez pas toujours.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 12, 'Si elle a répandu ce parfum sur mon corps, elle l\'a fait en vue de ma sépulture.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 13, 'En vérité, je vous le dis, partout où cet Évangile sera prêché, dans le monde entier, ce qu\'elle a fait sera aussi raconté en mémoire d\'elle.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 14, 'Alors l\'un des Douze, appelé Judas Iscariote, alla trouver les principaux sacrificateurs,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 15, 'et il leur dit: Que voulez-vous me donner, et je vous le livrerai? Ils lui comptèrent trente pièces d\'argent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 16, 'Et dès ce moment, il cherchait une occasion favorable pour livrer Jésus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 17, 'Le premier jour de la fête des pains sans levain, les disciples s\'approchèrent de Jésus et lui dirent: Où veux-tu que nous te préparions le repas de la Pâque?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 18, 'Il répondit: Allez à la ville chez un tel, et dites-lui: Le Maître dit: Mon temps est proche; c\'est chez toi que je célébrerai la Pâque avec mes disciples.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 19, 'Les disciples firent ce que Jésus leur avait ordonné, et ils préparèrent la Pâque.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 20, 'Le soir étant venu, Jésus se mit à table avec les douze disciples.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 21, 'Et comme ils mangeaient, il dit: En vérité, je vous déclare que l\'un de vous me trahira.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 22, 'Ils furent fort affligés, et chacun d\'eux se mit à lui dire: Est-ce moi, Seigneur?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 23, 'Mais il répondit: Celui qui a mis la main au plat avec moi, c\'est celui qui me trahira.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 24, 'Le Fils de l\'homme s\'en va, conformément à ce qui a été écrit à son sujet; mais malheur à l\'homme par qui le Fils de l\'homme est trahi! Mieux vaudrait pour cet homme-là n\'être jamais né!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 25, 'Judas, qui le trahissait, prit la parole et dit: Maître, est-ce moi? Jésus lui répondit: Tu l\'as dit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 26, 'Pendant qu\'ils mangeaient, Jésus prit du pain; et, après avoir rendu grâces, il le rompit, le donna à ses disciples, et dit: Prenez, mangez; ceci est mon corps.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 27, 'Ayant aussi pris la coupe et rendu grâces, il la leur donna, en disant: Buvez-en tous!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 28, 'Car ceci est mon sang, le sang de l\'alliance, qui est répandu pour plusieurs, pour la rémission des péchés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 29, 'Je vous le dis, désormais je ne boirai plus de ce fruit de la vigne, jusqu\'au jour où je le boirai nouveau avec vous dans le royaume de mon Père.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 30, 'Après le chant des psaumes, ils sortirent pour se rendre à la montagne des Oliviers.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 31, 'Alors Jésus leur dit: Vous allez tous trouver en moi, cette nuit, une occasion de chute; car il est écrit: «Je frapperai le berger, et les brebis du troupeau seront dispersées.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 32, 'Mais après que je serai ressuscité, je vous précéderai en Galilée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 33, 'Pierre, prenant la parole, lui dit: Quand tu serais pour tous une occasion de chute, tu ne le seras jamais pour moi!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 34, 'Jésus lui répondit: En vérité, je te déclare que cette nuit même, avant que le coq chante, tu me renieras trois fois.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 35, 'Pierre reprit: Quand même il me faudrait mourir avec toi, je ne te renierai point! Et tous les disciples dirent la même chose.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 36, 'Jésus vint avec ses disciples dans un lieu appelé Gethsémané; et il leur dit: Asseyez- vous ici, pendant que j\'irai là pour prier.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 37, 'Puis, ayant pris avec lui Pierre et les deux fils de Zébédée, il commença à être saisi de tristesse et d\'angoisse.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 38, 'Alors il leur dit: Mon âme est triste jusqu\'à la mort; demeurez ici et veillez avec moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 39, 'Puis, étant allé un peu plus loin, il se jeta le visage contre terre, priant et disant: Mon Père, s\'il est possible, que cette coupe passe loin de moi! Toutefois, non pas ce que je veux, mais ce que tu veux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 40, 'Ensuite, il revint vers ses disciples et les trouva endormis; et il dit à Pierre: Ainsi, vous n\'avez pu veiller une heure avec moi!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 41, 'Veillez et priez, afin que vous ne tombiez pas en tentation; l\'esprit est plein de bonne volonté, mais la chair est faible.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 42, 'Il s\'en alla encore pour la seconde fois, et il pria en disant: Mon Père, s\'il n\'est pas possible que cette coupe passe sans que je la boive, que ta volonté soit faite!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 43, 'Étant revenu, il les trouva encore endormis; car leurs yeux étaient appesantis.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 44, 'Puis, les ayant laissés, il s\'en alla de nouveau et pria pour la troisième fois, répétant les mêmes paroles.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 45, 'Alors il vint vers ses disciples et leur dit: Vous dormez maintenant, et vous vous reposez! Voici que l\'heure est venue, et le Fils de l\'homme va être livré entre les mains des pécheurs.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 46, 'Levez-vous, allons! Voici que celui qui me trahit s\'approche.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 47, 'Comme il parlait encore, Judas, l\'un des Douze, survint, et avec lui une grande troupe de gens armés d\'épées et de bâtons, envoyés par les principaux sacrificateurs et les anciens du peuple.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 48, 'Celui qui le trahissait était convenu avec eux de ce signe: Celui auquel je donnerai un baiser, c\'est lui, saisissez-le!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 49, 'Et aussitôt, s\'approchant de Jésus, il dit: Salut, Maître! Et il lui donna un baiser.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 50, 'Mais Jésus lui dit: Mon ami, c\'est donc pour cela que tu es ici? Alors ils s\'approchèrent, mirent la main sur Jésus et le saisirent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 51, 'Et voici que l\'un de ceux qui étaient avec lui, étendit la main, tira son épée, en frappa le serviteur du souverain sacrificateur, et il lui emporta l\'oreille.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 52, 'Alors Jésus lui dit: émets ton épée en place; car tous ceux qui prendront l\'épée, périront par l\'épée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 53, 'Crois-tu que je ne pourrais pas invoquer mon Père, qui me donnerait aussitôt plus de douze légions d\'anges?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 54, 'Comment donc s\'accompliraient les Écritures, d\'après lesquelles il faut que tout ceci arrive?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 55, 'A ce moment, Jésus dit à la foule: Vous êtes sortis avec des épées et des bâtons, pour me prendre, comme si j\'étais un brigand. Tous les jours, j\'étais assis dans le temple et j\'y enseignais, et vous ne m\'avez point arrêté.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 56, 'Mais tout cela est arrivé, afin que fût accompli ce qui a été écrit par les prophètes. Alors tous les disciples l\'abandonnèrent et s\'enfuirent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 57, 'Ceux qui avaient arrêté Jésus l\'emmenèrent chez Caïphe, le souverain sacrificateur, où les scribes et les anciens étaient réunis.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 58, 'Pierre le suivit de loin jusqu\'à la cour du souverain sacrificateur; il y entra et s\'assit avec les gardes pour voir comment cela finirait.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 59, 'Cependant, les principaux sacrificateurs et le Sanhédrin tout entier cherchaient quelque faux témoignage contre Jésus pour le faire mourir.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 60, 'Mais ils n\'en trouvaient point, bien que plusieurs faux témoins se fussent présentés. Enfin, il en vint deux, qui parlèrent ainsi:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 61, 'Cet homme a dit: Je puis détruire le temple de Dieu et le rebâtir en trois jours.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 62, 'Alors le souverain sacrificateur se leva et lui dit: Ne réponds-tu rien à ce que ces hommes déposent contre toi? Mais Jésus gardait le silence.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 63, 'Le souverain sacrificateur, reprenant, lui dit: Je t\'adjure, par le Dieu vivant, de nous dire si tu es le Christ, le Fils de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 64, 'Jésus lui répondit: Tu l\'as dit! Et même, je vous le déclare, désormais vous verrez le Fils de l\'homme assis à la droite de la puissance de Dieu et venant sur les nuées du ciel.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 65, 'Alors le souverain sacrificateur déchira ses vêtements, en disant: Il a blasphémé; qu\'avons-nous encore besoin de témoins? Vous venez d\'entendre le blasphème.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 66, 'Que vous en semble? Ils répondirent: Il mérite la mort!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 67, 'Alors ils lui crachèrent au visage, et ils lui donnèrent des coups de poing. D\'autres lui donnaient des soufflets,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 68, 'en disant: Christ, prophétise! Dis-nous qui t\'a frappé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 69, 'Cependant, Pierre était assis dehors dans la cour. Une servante s\'approcha de lui et lui dit: Toi aussi, tu étais avec Jésus, le Galiléen.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 70, 'Mais il le nia devant tous, en disant: Je ne sais ce que tu dis.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 71, 'Et comme il s\'en allait vers le vestibule, une autre servante le vit et dit à ceux qui étaient là: Cet homme aussi était avec Jésus, le Nazaréen,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 72, 'Mais il le nia encore, en disant avec serment: Je ne connais point cet homme.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 73, 'Un peu après, ceux qui étaient là, s\'étant approchés, dirent à Pierre: Assurément, tu es aussi de ces gens-là; car ton langage te fait reconnaître.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 74, 'Alors il se mit à proférer des imprécations accompagnées de serments, en disant: Je ne connais point cet homme! Et aussitôt, le coq chanta.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 75, 'Pierre se souvint de la parole de Jésus qui lui avait dit: Avant que le coq chante, tu me renieras trois fois. Et, étant sorti, il pleura amèrement.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 1, '!!- Quand le matin fut venu, tous les principaux sacrificateurs et les anciens du peuple tinrent conseil contre Jésus, pour le faire mourir.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 2, 'Et après l\'avoir enchaîné, ils l\'emmenèrent et le livrèrent à Pilate, le gouverneur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 3, 'Alors Judas, qui l\'avait trahi, voyant que Jésus était condamné, fut pris de remords et rapporta les trente pièces d\'argent aux principaux sacrificateurs et aux anciens,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 4, 'en disant: J\'ai péché, en livrant le sang innocent. Mais ils répondirent: Que nous importe? Cela te regarde!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 5, 'Jetant alors les pièces d\'argent dans le temple, il se retira, et il alla se pendre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 6, 'Mais les principaux sacrificateurs prirent les pièces d\'argent, et ils dirent: Il n\'est pas permis de les mettre dans le trésor sacré, puisque c\'est le prix du sang.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 7, 'Après en avoir délibéré, ils achetèrent avec cet argent le Champ du Potier, pour la sépulture des étrangers.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 8, 'C\'est pourquoi ce champ-là est appelé, encore aujourd\'hui, «le Champ du sang».');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 9, 'Alors fut accompli ce qui avait été dit par Jérémie, le prophète: «Ils ont reçu les trente pièces d\'argent, le prix de celui qui a été évalué, oui, évalué par les enfants d\'Israël;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 10, 'et il les ont données pour le champ du potier, comme le Seigneur me l\'avait commandé.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 11, 'Jésus comparut devant le gouverneur, et le gouverneur l\'interrogea, en disant: C\'est toi qui es le roi des Juifs? Jésus répondit: Tu le dis.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 12, 'Et pendant que les principaux sacrificateurs et les anciens l\'accusaient, il ne répondait rien.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 13, 'Alors Pilate lui dit: N\'entends-tu pas tous les témoignages qu\'ils déposent contre toi?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 14, 'Mais il ne répondit rien sur aucun point, de sorte que le gouverneur était fort étonné.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 15, 'A chaque fête de Pâque, le gouverneur avait coutume de relâcher un prisonnier, celui que le peuple désignait.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 16, 'Or, il y avait, à ce moment-là, un prisonnier fameux, nommé Barabbas.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 17, 'Pilate dit donc au peuple rassemblé: Lequel voulez-vous que je vous relâche: Barabbas, ou Jésus, celui qu\'on appelle Christ?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 18, 'Car il savait bien que c\'était par jalousie qu\'ils avaient livré Jésus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 19, 'Pendant qu\'il siégeait à son tribunal, sa femme lui envoya dire: N\'aie rien à faire avec ce Juste; car j\'ai beaucoup souffert, aujourd\'hui, en songe, à cause de lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 20, '— Mais les principaux sacrificateurs et les anciens persuadèrent au peuple de demander Barabbas, et de faire périr Jésus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 21, 'Le gouverneur, prenant la parole, leur dit: Lequel des deux voulez-vous que je vous relâche? Ils répondirent: Barabbas!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 22, 'Pilate leur dit: Que ferai-je donc de Jésus, celui qu\'on appelle Christ? Tous répondirent: Qu\'il soit crucifié!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 23, 'Le gouverneur dit: Mais quel mal a-t-il fait? Ils criaient encore plus fort: Qu\'il soit crucifié!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 24, 'Pilate, voyant qu\'il ne gagnait rien, mais que le tumulte augmentait, prit de l\'eau et se lava les mains devant le peuple en disant: Je suis innocent du sang de cet homme; cela vous regarde.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 25, 'Et tout le peuple répondit: Que son sang retombe sur nous et sur nos enfants!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 26, 'Alors il leur relâcha Barabbas. Quant à Jésus, après l\'avoir fait battre de verges, il le leur livra pour qu\'il fût crucifié.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 27, 'Les soldats du gouverneur emmenèrent Jésus dans le prétoire, et ils rassemblèrent autour de lui toute la cohorte.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 28, 'Ils lui ôtèrent ses vêtements et le revêtirent d\'un manteau d\'écarlate.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 29, 'Puis, ils tressèrent une couronne d\'épines, ils la lui mirent sur la tête, avec un roseau dans la main droite; et, fléchissant le genou devant lui, ils se moquaient de lui, en disant: Salut, roi des Juifs!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 30, 'Ils crachaient sur lui, et, prenant le roseau, ils lui en donnaient des coups sur la tête.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 31, 'Après s\'être moqués de lui, ils lui ôtèrent le manteau et lui remirent ses vêtements; puis, ils l\'emmenèrent pour le crucifier.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 32, 'Comme ils sortaient, ils trouvèrent un homme de Cyrène, nommé Simon, et ils le contraignirent à porter la croix de Jésus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 33, 'Arrivés au lieu appelé Golgotha, — ce qui signifie «le lieu du Crâne,» —');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 34, 'ils lui donnèrent à boire du vin mêlé de fiel; mais, quand il en eut goûté, il n\'en voulut point boire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 35, 'Après l\'avoir crucifié, ils se partagèrent ses vêtements en les tirant au sort.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 36, 'Et, s\'étant assis, ils restaient là à le garder.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 37, 'Au-dessus de sa tête, ils avaient placé un écriteau portant le motif de sa condamnation: Voici Jésus, le Roi des Juifs.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 38, 'En même temps, on crucifia avec lui deux brigands, l\'un à sa droite et l\'autre à sa gauche.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 39, 'Ceux qui passaient par là l\'outrageaient, hochant la tête');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 40, 'et disant: Toi qui détruis le temple et qui le rebâtis en trois jours, sauve-toi toi-même, si tu es le Fils de Dieu, et descends de la croix!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 41, 'De même aussi, les principaux sacrificateurs, avec les scribes et les anciens, disaient en se moquant:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 42, 'Il en a sauvé d\'autres; il ne peut se sauver lui-même! S\'il est le roi d\'Israël, qu\'il descende maintenant de la croix, et nous croirons en lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 43, 'Il se confie en Dieu; que Dieu le délivre maintenant, s\'il l\'aime; car il a dit: Je suis le Fils de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 44, 'Et les brigands, crucifiés avec lui, lui adressaient les mêmes outrages.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 45, 'Depuis la sixième heure jusqu\'à la neuvième, il y eut des ténèbres sur tout le pays.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 46, 'Vers la neuvième heure, Jésus cria d\'une voix forte: Éli, Éli, lamma sabachtani. c\'est-à-dire: «Mon Dieu, mon Dieu, pourquoi m\'as-tu abandonné?»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 47, 'Quelques-uns de ceux qui étaient présents, l\'ayant entendu, disaient: Il appelle Élie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 48, 'Aussitôt l\'un d\'eux courut prendre une éponge, et, l\'ayant remplie de vinaigre, il la mit au bout d\'un roseau et lui donna à boire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 49, 'Mais les autres disaient: Laisse! Voyons si Élie viendra le délivrer.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 50, 'Et Jésus, ayant de nouveau jeté un grand cri, rendit l\'esprit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 51, 'Alors, voici que le voile du temple se déchira en deux, depuis le haut jusqu\'en bas. La terre trembla, les rochers se fendirent,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 52, 'les tombeaux s\'ouvrirent, et les corps de plusieurs saints qui étaient morts ressuscitèrent:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 53, 'étant sortis de leurs tombeaux, ils entrèrent dans la ville sainte après sa résurrection, et ils apparurent à plusieurs personnes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 54, 'Le centenier et ceux qui, avec lui, gardaient Jésus, ayant vu le tremblement de terre et tout ce qui était arrivé, furent fort effrayés, et ils dirent: Véritablement, celui-ci était le Fils de Dieu!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 55, 'Or, il y avait là plusieurs femmes qui regardaient de loin: c\'étaient celles qui avaient suivi Jésus depuis la Galilée, pour le servir.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 56, 'De ce nombre étaient Marie-Madeleine et Marie, mère de Jacques et de Joses, et la mère des fils de Zébédée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 57, 'Le soir étant venu, un homme riche, d\'Arimathée, nommé Joseph, qui lui-même était disciple de Jésus,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 58, 'alla trouver Pilate et lui demanda le corps de Jésus; alors Pilate ordonna qu\'on le lui remît.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 59, 'Joseph prit le corps, l\'enveloppa dans un linceul blanc,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 60, 'et il le déposa dans un sépulcre neuf qu\'il avait fait tailler dans le roc pour lui-même; puis, il roula une grande pierre à l\'entrée du sépulcre et il s\'en alla.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 61, 'Or, Marie-Madeleine et l\'autre Marie étaient là, assises en face du tombeau.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 62, 'Le lendemain, — qui était le jour après la préparation —, les principaux sacrificateurs et les pharisiens se rendirent ensemble chez Pilate,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 63, 'et ils lui dirent: Seigneur, nous nous sommes souvenus que cet imposteur, quand il vivait encore, disait: Après trois jours, je ressusciterai.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 64, 'Ordonne donc que le tombeau soit gardé sûrement jusqu\'au troisième jour, de peur que ses disciples ne viennent l\'enlever et qu\'ils ne disent au peuple: Il est ressuscité des morts. Cette dernière imposture serait pire que la première.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 65, 'Pilate leur dit: Vous avez une garde; allez, et gardez-le comme vous l\'entendrez.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 66, 'Ils s\'en allèrent donc, et ils s\'assurèrent du tombeau, en scellant la pierre et en y plaçant la garde.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 1, 'Après le sabbat, comme le premier jour de la semaine commençait à luire, Marie-Madeleine et l\'autre Marie vinrent pour voir le tombeau.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 2, 'Et voici qu\'il se fit un grand tremblement de terre; car un ange du Seigneur descendit du ciel et vint rouler la pierre, et il s\'assit dessus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 3, 'Son aspect était semblable à un éclair, et son vêtement blanc comme la neige.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 4, 'De la frayeur que les gardes en eurent, ils furent tout bouleversés, et ils devinrent comme morts.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 5, 'Mais l\'ange, prenant la parole, dit aux femmes: Pour vous, ne craignez point; car je sais que vous cherchez Jésus, qui a été crucifié.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 6, 'Il n\'est pas ici; il est ressuscité, comme il l\'avait dit. Venez, voyez le lieu où il était couché;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 7, 'et hâtez-vous d\'aller dire à ses disciples qu\'il est ressuscité des morts. Voici qu\'il vous précède en Galilée: c\'est là que vous le verrez, je vous en avertis!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 8, 'Aussitôt, elles s\'éloignèrent promptement du tombeau, avec une crainte mêlée d\'une grande joie, et elles coururent porter la nouvelle à ses disciples.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 9, 'Et voici que Jésus se présenta devant elles, et il leur dit: Je vous salue! Elles s\'approchèrent, saisirent ses pieds et l\'adorèrent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 10, 'Alors Jésus leur dit: Ne craignez point; allez dire à mes frères de se rendre en Galilée: c\'est là qu\'ils me verront.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 11, 'Comme elles étaient en chemin, quelques-uns des gardes vinrent à la ville et rapportèrent aux principaux sacrificateurs tout ce qui était arrivé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 12, 'Ceux-ci se réunirent avec les anciens, et, après en avoir délibéré, ils donnèrent une forte somme d\'argent aux soldats,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 13, 'avec cet ordre: Dites que ses disciples sont venus de nuit et qu\'ils l\'ont enlevé pendant que vous dormiez.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 14, 'Si cela vient à la connaissance du gouverneur, nous l\'apaiserons, et nous vous tirerons de peine.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 15, 'Les soldats, ayant pris l\'argent, agirent d\'après ces instructions; et ce bruit s\'est répandu parmi les Juifs jusqu\'à ce jour.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 16, 'Les onze disciples allèrent en Galilée, sur la montagne que Jésus leur avait désignée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 17, 'Quand ils le virent, ils l\'adorèrent. Or, ils avaient eu des doutes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 18, 'Jésus, s\'étant approché, leur parla ainsi: Toute puissance m\'a été donnée dans le ciel et sur la terre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 19, 'Allez donc, enseignez toutes les nations, en les baptisant au nom du Père, du Fils et du Saint-Esprit,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 20, 'et en leur apprenant à garder tout ce que je vous ai commandé. Et voici que je suis avec vous tous les jours, jusqu\'à la fin du monde!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 1, 'Commencement de l\'Évangile de Jésus-Christ, Fils de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 2, 'Conformément à ce qui est écrit dans le prophète Ésaïe: «Je vais envoyer mon messager devant ta face, et il te préparera le chemin.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 3, 'Une voix crie dans le désert: Préparez le chemin du Seigneur, aplanissez ses sentiers». —');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 4, 'Jean parut dans le désert, baptisant et prêchant le baptême de repentance, pour la rémission des péchés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 5, 'Toute la Judée et tous les habitants de Jérusalem allaient à lui, et, confessant leurs péchés, ils étaient baptisés par lui dans les eaux du Jourdain.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 6, 'Jean avait un vêtement de poil de chameau et une ceinture de cuir autour des reins; il se nourrissait de sauterelles et de miel sauvage.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 7, 'Et il prêchait, en disant: Il vient après moi, celui qui est plus puissant que moi; et je ne suis pas digne de délier, en me baissant, la courroie de ses chaussures.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 8, 'Moi, je vous ai baptisés d\'eau; mais lui, il vous baptisera d\'Esprit saint.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 9, 'Or, il arriva, en ces jours-là, que Jésus vint de Nazareth, ville de Galilée, et il fut baptisé par Jean dans le Jourdain.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 10, 'Au moment où il sortait de l\'eau, il vit les cieux s\'ouvrir et l\'Esprit descendre sur lui comme une colombe.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 11, 'Et il vint des cieux une voix qui disait: Tu es mon Fils bien-aimé, en qui j\'ai mis toute mon affection.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 12, 'Aussitôt l\'Esprit poussa Jésus au désert.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 13, 'Il passa quarante jours dans le désert, tenté par Satan; il était avec les bêtes sauvages, et les anges le servaient.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 14, 'Après que Jean eut été mis en prison, Jésus se rendit en Galilée, prêchant l\'Évangile de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 15, 'Il disait: Le temps est accompli, et le royaume de Dieu est proche. Repentez-vous et croyez à l\'Évangile.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 16, 'Comme il marchait le long de la mer de Galilée, il vit Simon et André, son frère, qui jetaient le filet dans la mer; car ils étaient pêcheurs.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 17, 'Jésus leur dit: Suivez-moi, et je vous ferai devenir pêcheurs d\'hommes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 18, 'Aussitôt, laissant leurs filets, ils le suivirent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 19, 'Étant allé un peu plus loin, il vit Jacques, fils de Zébcdce, et Jean son frère, qui étaient aussi dans une barque, raccommodant leurs filets.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 20, 'Il les appela aussitôt; et, laissant Zébédée leur père dans la barque avec les ouvriers, ils le suivirent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 21, 'Ensuite ils se rendirent à Capernaüm; et aussitôt, le jour du sabbat, Jésus étant entré dans la synagogue, se mit à y enseigner.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 22, 'On était frappé de son enseignement; car il enseignait comme ayant autorité, et non pas comme les scribes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 23, 'Or, il y avait, à ce moment même, dans la synagogue, un homme possédé d\'un esprit impur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 24, 'Il s\'écria: Qu\'y a-t-il entre nous et toi, Jésus de Nazareth? Es-tu venu pour nous perdre? Je sais qui tu es: le Saint de Dieu!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 25, 'Mais Jésus le reprit sévèrement et lui dit: Tais-toi, et sors de cet homme!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 26, 'Alors l\'esprit impur, le secouant avec violence et poussant un grand cri, sortit de lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 27, 'Ils furent tous dans l\'étonnement, de sorte qu\'ils se demandaient entre eux: Qu\'est-ce que ceci? C\'est un enseignement tout nouveau! Celui-là commande avec autorité, même aux esprits impurs, et ils lui obéissent!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 28, 'Et sa renommée se répandit aussitôt dans toute la contrée environnante, en Galilée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 29, 'Dès qu\'ils furent sortis de la synagogue, ils vinrent avec Jacques et Jean dans la maison de Simon et d\'André.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 30, 'Or, la belle-mère de Simon était au lit, malade de la fièvre; et aussitôt ils lui parlèrent d\'elle.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 31, 'Alors il s\'approcha, et, la prenant par la main, il la fit lever; la fièvre la quitta, et elle se mit à les servir.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 32, 'Quand le soir fut venu, après le coucher du soleil, on lui amena tous les malades et les démoniaques.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 33, 'Toute la ville était rassemblée devant la porte.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 34, 'Il guérit plusieurs malades atteints de divers maux, et il chassa plusieurs démons, ne permettant pas aux démons de dire qu\'ils le connaissaient.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 35, 'Le lendemain matin, comme il faisait encore fort obscur, s\'étant levé, il sortit et s\'en alla dans un lieu écarté; et il y priait.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 36, 'Simon et ceux qui étaient avec lui se mirent à sa recherche.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 37, 'L\'ayant trouvé, ils lui dirent: Tous te cherchent!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 38, 'Il leur répondit: Allons ailleurs, dans les bourgs des environs, afin que j\'y prêche aussi; car c\'est pour cela que je suis venu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 39, 'Et il allait par toute la Galilée, prêchant dans les synagogues et chassant les démons.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 40, 'Un lépreux vint à lui, et, s\'étant jeté à genoux, il lui adressait cette prière: Si tu le veux, tu peux me rendre net.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 41, 'Jésus, ému de compassion, étendit la main, le toucha et lui dit: Je le veux, sois net!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 42, 'A l\'instant, la lèpre disparut, et cet homme devint net.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 43, 'Jésus le renvoya aussitôt, en lui faisant, d\'une voix sévère, cette recommandation:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 44, 'Garde-toi d\'en parler à personne; mais va, montre-toi au sacrificateur, et offre pour ta purification ce que Moïse a prescrit, afin que cela leur serve de témoignage.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 45, 'Mais cet homme, étant parti, se mit à publier le fait et à le raconter partout, de sorte que Jésus ne pouvait plus entrer ouvertement dans une ville; mais il se tenait dehors dans des lieux écartés. Et l\'on venait à lui de toutes parts.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 1, 'Quelques jours après, Jésus revint à Capernaüm, et l\'on apprit qu\'il était dans la maison.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 2, 'Il s\'y assembla tant de monde, qu\'il n\'y avait plus de place même devant la porte; et il leur annonçait la parole.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 3, 'Alors, il vint des gens qui lui amenaient un paralytique, porté par quatre hommes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 4, 'Mais, ne pouvant arriver jusqu\'à lui à cause de la foule, ils découvrirent le toit au-dessus de l\'endroit où il était; et, par l\'ouverture, ils descendirent le lit sur lequel le paralytique était couché.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 5, 'Jésus, voyant leur foi, dit au paralytique: Mon enfant, tes péchés te sont pardonnés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 6, 'Or, il y avait là quelques scribes qui se tenaient assis, et ils faisaient ce raisonnement dans leur coeur:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 7, 'Pourquoi cet homme parle-t-il ainsi? Il blasphème! Qui peut pardonner les péchés, que Dieu seul?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 8, 'Aussitôt Jésus, ayant connu en son esprit qu\'ils raisonnaient ainsi en eux-mêmes, leur dit: Pourquoi faites-vous ces raisonnements dans vos coeurs?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 9, 'Lequel est le plus aisé, de dire au paralytique: Tes péchés te sont pardonnés. ou de dire: Lève-toi, prends ton lit, et marche?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 10, 'Or, — afin que vous sachiez que le Fils de l\'homme a sur la terre le pouvoir de pardonner les péchés, —');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 11, 'je te l\'ordonne, dit-il au paralytique, lève-toi, prends ton lit, et va dans ta maison.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 12, 'Cet homme se leva, et aussitôt, ayant pris son lit, il sortit en présence de tout le monde; de sorte qu\'ils étaient tous dans l\'étonnement, et ils glorifiaient Dieu en disant: Nous n\'avons jamais rien vu de pareil!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 13, 'Alors Jésus retourna du côté de la mer; tout le peuple venait à lui, et il les enseignait.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 14, 'En passant, il vit Lévi, fils d\'Alphée, assis au bureau du péage. Il lui dit: Suis-moi; et lui, se levant, le suivit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 15, 'Comme Jésus était à table dans la maison de Lévi, beaucoup de péagers et de pécheurs se mirent à table avec lui et ses disciples; car il y en avait beaucoup qui l\'avaient suivi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 16, 'Les scribes appartenant au parti des pharisiens, voyant qu\'il mangeait avec des péagers et des pécheurs, disaient à ses disciples: Il mange avec des péagers et des pécheurs!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 17, 'Jésus, ayant entendu cela, leur dit: Ce ne sont pas ceux qui se portent bien qui ont besoin de médecin, mais ceux qui se portent mal. Je ne suis pas venu appeler les justes, mais les pécheurs.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 18, 'Or, les disciples de Jean et les pharisiens jeûnaient. Ils vinrent dire à Jésus: D\'où vient que les disciples de Jean et ceux des pharisiens jeûnent, et que tes disciples ne jeûnent pas?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 19, 'Jésus leur répondit: Les amis de l\'époux peuvent-ils jeûner pendant que l\'époux est avec eux? Tant qu\'ils ont l\'époux avec eux, ils ne peuvent jeûner.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 20, 'Mais le temps viendra où l\'époux leur sera ôté; alors ils jeûneront ce jour-là.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 21, 'Personne ne coud une pièce de drap neuf à un vieux vêtement; autrement, la pièce neuve emporte une partie du vieux drap, et la déchirure en devient pire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 22, 'Et personne ne met du vin nouveau dans de vieilles outres; autrement, le vin fait rompre les outres; le vin est perdu, et les outres aussi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 23, 'Il arriva, comme Jésus passait par les blés un jour de sabbat, que ses disciples, chemin faisant, se mirent à arracher des épis.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 24, 'Alors les pharisiens lui dirent: Regarde! Pourquoi font-ils ce qui n\'est pas permis le jour du sabbat?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 25, 'Il leur répondit: N\'avez-vous jamais lu ce que fit David, lorsqu\'il fut dans le besoin et qu\'il eut faim, lui et ceux qui étaient avec lui;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 26, 'comment il entra dans la maison de Dieu, du temps d\'Abiathar, souverain sacrificateur, et mangea les pains de proposition — qu\'il est permis aux sacrificateurs seuls de manger — et comment il en donna même à ceux qui étaient avec lui?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 27, 'Puis Jésus ajouta: Le sabbat a été fait pour l\'homme, et non pas l\'homme pour le sabbat.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 28, 'Ainsi le Fils de l\'homme est maître même du sabbat.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 1, 'Une autre fois, Jésus entra dans une synagogue, où se trouvait un homme qui avait la main desséchée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 2, 'Les pharisiens l\'observaient pour voir s\'il le guérirait un jour de sabbat, afin de pouvoir l\'accuser.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 3, 'Il dit à l\'homme qui avait la main desséchée: Lève-toi et tiens-toi au milieu de nous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 4, 'Puis il leur dit: Est-il permis, le jour du sabbat, de faire du bien ou de faire du mal; de sauver une personne ou de la tuer? Mais ils gardaient le silence.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 5, 'Alors, promenant sur eux ses regards avec indignation, et affligé de l\'endurcissement de leur coeur, il dit à l\'homme: Étends ta main. Il l\'étendit, et sa main redevint saine.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 6, 'Les pharisiens, étant sortis, tinrent aussitôt conseil avec les hérodiens contre lui, pour le faire périr.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 7, 'Jésus se retira avec ses disciples du côté de la mer, et une grande multitude, venue de la Galilée, le suivit. De la Judée aussi,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 8, 'de Jérusalem, de l\'Idumée, du pays au-delà du Jourdain, ainsi que des environs de Tyr et de Sidon, une grande multitude, ayant entendu parler de tout ce qu\'il faisait, vint vers lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 9, 'Alors il dit à ses disciples de lui tenir une petite barque toute prête, à cause de la foule, pour ne pas être trop pressé par elle.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 10, 'Car il avait guéri plusieurs malades, de sorte que tous ceux qui avaient quelque mal se jetaient sur lui pour le toucher.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 11, 'Et quand les esprits impurs le voyaient, ils tombaient à ses pieds et s\'écriaient: Tu es le Fils de Dieu!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 12, 'Mais il leur défendait sévèrement de le faire connaître.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 13, 'Il alla ensuite sur la montagne, et il appela ceux qu\'il voulut choisir lui-même, et ils vinrent à lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 14, 'Il en désigna douze, qu\'il nomma apôtres, pour les avoir avec lui et pour les envoyer prêcher,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 15, 'avec le pouvoir de chasser les démons.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 16, 'Voici les douze qu\'il désigna: Simon, à qui il donna le nom de Pierre;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 17, 'Jacques, fils de Zébédée, et Jean, frère de Jacques, auxquels il donna le nom de Boanerges, c\'est-à-dire fils du tonnerre;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 18, 'André, Philippe, Barthélémy, Matthieu, Thomas, Jacques, fils d\'Alphée, Thaddée, Simon le Cananéen,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 19, 'et Judas Iscariote, celui-là même qui le trahit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 20, 'Jésus entra dans une maison avec ses disciples; et la foule s\'y rassembla encore, de sorte qu\'ils ne pouvaient pas même prendre leur repas.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 21, 'Quand ses proches l\'eurent appris, ils vinrent pour s\'emparer de lui; car ils disaient qu\'il avait perdu l\'esprit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 22, 'Les scribes, descendus de Jérusalem, disaient: Il est possédé de Béelzébul, et il chasse les démons par le prince des démons!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 23, 'Mais Jésus, les ayant appelés, leur dit en paraboles: Comment Satan pourrait-il chasser Satan?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 24, 'Si un royaume est divisé contre lui-même, ce royaume-là ne peut subsister;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 25, 'et si une maison est divisée contre elle-même, cette maison-là ne saurait subsister.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 26, 'Si donc Satan s\'élève contre lui-même, il est divisé et il ne peut subsister, mais il est près de sa fin.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 27, 'Nul ne peut entrer dans la maison de l\'homme fort et piller son bien, s\'il n\'a auparavant lié cet homme fort; après cela, il pourra piller sa maison.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 28, 'En vérité, je vous le dis, tous les péchés seront pardonnés aux enfants des hommes, ainsi que tous les blasphèmes qu\'ils auront proférés;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 29, 'mais tout homme qui aura blasphémé contre le Saint-Esprit, n\'en obtiendra jamais le pardon; il est coupable d\'un péché éternel.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 30, 'Jésus parla ainsi, parce qu\'ils disaient: Il est possédé d\'un esprit impur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 31, 'La mère et les frères de Jésus arrivèrent; et, se tenant dehors, ils l\'envoyèrent appeler.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 32, 'La foule était assise autour de lui. Et on lui dit: Voici que ta mère et tes frères sont là dehors, qui te cherchent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 33, 'Mais il répondit: Qui est ma mère, et qui sont mes frères?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 34, 'Puis, jetant les yeux sur ceux qui étaient assis autour de lui, il dit: Voilà ma mère et mes frères!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 35, 'Quiconque fait la volonté de Dieu, celui-là est mon frère, et ma soeur, et ma mère.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 1, 'Jésus se mit encore à enseigner au bord de la mer. Une grande foule s\'étant rassemblée autour de lui, il monta dans une barque où il s\'assit; et toute la foule était à terre sur le rivage.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 2, 'Il leur enseignait beaucoup de choses en paraboles, et il leur disait dans son enseignement:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 3, 'Écoutez! Le semeur sortit pour semer.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 4, 'Comme il semait, il arriva qu\'une partie de la semence tomba le long du chemin, et les oiseaux vinrent et la mangèrent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 5, 'Une autre partie tomba sur un endroit pierreux, où elle n\'avait que peu de terre, et elle leva aussitôt, parce qu\'elle n\'entrait pas profondément dans la terre;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 6, 'mais le soleil s\'étant levé, elle fut brûlée, et, parce qu\'elle n\'avait pas de racine, elle sécha.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 7, 'Une autre partie tomba parmi les épines; les épines montèrent et l\'étouffèrent, et elle ne donna point de fruit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 8, 'Une autre partie tomba dans la bonne terre, et elle donna du fruit qui grandit et se développa: un grain en rapporta trente, un autre soixante, et un autre cent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 9, 'Et il disait: Que celui qui a des oreilles pour entendre, entende!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 10, 'Quand Jésus se trouva seul, ceux qui étaient autour de lui et les Douze l\'interrogèrent sur les paraboles.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 11, 'Il leur répondit: A vous, le mystère du royaume de Dieu a été révélé; mais, à ceux du dehors, tout leur est présente sous forme de paraboles,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 12, 'afin qu\'en voyant, ils regardent et n\'aperçoivent pas, et qu\'en entendant, ils entendent et ne comprennent point — de peur qu\'ils ne se convertissent et qu\'il ne leur soit pardonné.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 13, 'Puis il leur dit: Vous ne comprenez pas cette parabole? Comment donc comprendrez-vous toutes les paraboles?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 14, 'Le semeur sème la parole.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 15, 'Ceux qui sont le long du chemin, ce sont ceux en qui la parole est semée; mais, à peine l\'ont-ils entendue, Satan vient aussitôt et enlève la parole qui a été semée en eux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 16, 'De même, ceux qui reçoivent la semence dans un endroit pierreux, ce sont ceux qui entendent la parole et la reçoivent aussitôt avec joie;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 17, 'mais comme il n\'y a pas de racine en eux-mêmes, ils ne sont que pour un temps, de sorte que, l\'affliction ou la persécution survenant à cause de la parole, ils y trouvent aussitôt une occasion de chute.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 18, 'D\'autres encore reçoivent la semence parmi les épines: ce sont ceux qui ont écouté la parole;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 19, 'mais les soucis de ce monde, la séduction des richesses et les autres convoitises, pénètrent en eux et étouffent la parole; et elle devient infructueuse.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 20, 'Enfin, ceux qui ont reçu la semence dans la bonne terre, ce sont ceux qui écoutent la parole, qui la reçoivent et portent des fruits: un grain trente, un autre soixante, un autre cent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 21, 'Il leur disait aussi: Apporte-t-on la lampe pour la mettre sous le boisseau ou sous le lit? N\'est-ce pas pour la mettre sur un support?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 22, 'Car il n\'y a rien de secret qui ne doive être manifesté, ni rien de caché qui ne doive être mis en évidence.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 23, 'Si quelqu\'un a des oreilles pour entendre, qu\'il entende!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 24, 'Il leur disait aussi: Prenez garde à ce que vous entendez. On se servira pour vous de la mesure avec laquelle vous mesurerez, et on y ajoutera encore.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 25, 'Car on donnera à celui qui a; mais à celui qui n\'a pas, on ôtera même ce qu\'il a!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 26, 'Il disait encore: Il en est du royaume de Dieu comme d\'un homme qui jette la semence en terre:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 27, 'qu\'il dorme ou qu\'il veille, la nuit et le jour, la semence germe et croît, sans qu\'il sache comment.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 28, 'Car la terre produit d\'elle-même son fruit: premièrement l\'herbe, ensuite l\'épi, puis le grain tout formé dans l\'épi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 29, 'Et quand le fruit est dans sa maturité, on y met aussitôt la faucille, parce que le temps de la moisson est venu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 30, 'Il disait encore: A quoi comparerons-nous le royaume de Dieu, ou par quelle parabole le représenterons-nous?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 31, 'Il en est de lui comme d\'un grain de moutarde: lorsqu\'on le sème, il est la plus petite de toutes les semences qui sont sur la terre;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 32, 'mais quand il a été semé, il monte, devient plus grand que tous les légumes et pousse de grandes branches, en sorte que les oiseaux du ciel peuvent s\'abriter sous son ombre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 33, 'C\'est par plusieurs paraboles de ce genre qu\'il leur annonçait la parole, dans la mesure où ils étaient capables de la comprendre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 34, 'Il ne leur parlait donc qu\'en paraboles; mais, en particulier, il expliquait tout à ses disciples.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 35, 'Ce jour-là, quand le soir fut venu, il leur dit: Passons à l\'autre bord.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 36, 'Après avoir renvoyé la foule, ils emmenèrent Jésus dans la barque où il était; et il y avait aussi d\'autres barques qui l\'accompagnaient.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 37, 'Or, il s\'éleva un grand tourbillon de vent, et les vagues se jetaient dans la barque, en sorte qu\'elle commençait à se remplir;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 38, 'mais lui était à la poupe, dormant sur un coussin. Ils le réveillèrent et lui dirent: Maître, cela ne te fait-il rien que nous périssions?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 39, 'Alors, s\'étant réveillé, il imposa silence au vent, et il dit à la mer: Tais-toi, sois tranquille! Le vent cessa, et il se fit un grand calme.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 40, 'Puis il leur dit: Pourquoi avez-vous peur? N\'avez-vous donc plus de foi?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 41, 'Ils furent saisis d\'une grande crainte, et ils se disaient l\'un à l\'autre: Qui est donc celui-ci, auquel le vent même et la mer obéissent?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 1, 'Ils arrivèrent de l\'autre côté de la mer, dans la contrée des Géraséniens.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 2, 'Et aussitôt que Jésus fut descendu de la barque, un homme, possédé d\'un esprit impur, sortit des tombeaux et vint au-devant de lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 3, 'Il faisait sa demeure dans les tombeaux, et personne ne pouvait plus le tenir lié, même avec une chaîne;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 4, 'car souvent, ayant les fers aux pieds et étant lié de chaînes, il avait rompu les chaînes et brisé les fers, et personne n\'avait la force de le dompter.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 5, 'Il demeurait continuellement, nuit et jour, dans les tombeaux et sur les montagnes, criant et se meurtrissant avec des pierres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 6, 'Ayant vu Jésus de loin, il accourut, se prosterna devant lui,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 7, 'et, poussant un grand cri, il lui dit: Qu\'y a-t-il entre moi et toi, Jésus, Fils du Dieu Très-Haut? Je t\'en conjure, au nom de Dieu, ne me tourmente pas!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 8, 'Car Jésus lui disait: Esprit impur, sors de cet homme!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 9, 'Puis Jésus lui demanda: Quel est ton nom? Il lui répondit: Mon nom, c\'est Légion; car nous sommes plusieurs.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 10, 'Et il le priait instamment de ne pas les chasser hors de cette contrée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 11, 'Or, il y avait là, sur la montagne, un grand troupeau de pourceaux qui paissaient.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 12, 'Les démons lui adressèrent cette prière: Envoie-nous vers ces pourceaux, afin que nous entrions en eux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 13, 'Et Jésus le leur permit. Alors les esprits impurs sortirent de cet homme; ils entrèrent dans les pourceaux, et le troupeau se précipita, du haut de la falaise, dans la mer. Il y en avait environ deux mille; et ils se noyèrent dans la mer.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 14, 'Ceux qui les faisaient paître s\'enfuirent, et répandirent la nouvelle dans la ville et dans la campagne.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 15, 'Alors les habitants sortirent pour voir ce qui était arrivé. Ils allèrent trouver Jésus, et ils virent le démoniaque qui avait eu la légion de démons, assis, vêtu et dans son bon sens; et ils furent remplis de crainte.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 16, 'Ceux qui avaient vu le fait leur racontèrent ce qui était arrivé au démoniaque et aux pourceaux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 17, 'Alors ils se mirent à le prier de se retirer de leur pays.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 18, 'Et comme il entrait dans la barque, le démoniaque lui demanda la permission de rester avec lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 19, 'Mais Jésus ne le lui permit pas, et il lui dit: Va dans ta maison, chez les tiens, et raconte-leur tout ce que le Seigneur t\'a fait, et comment il a eu pitié de toi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 20, 'Cet homme s\'en alla donc, et il se mit à publier dans la Décapole tout ce que Jésus lui avait fait; et tous étaient dans l\'admiration.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 21, 'Quand Jésus eut regagné, dans la barque, l\'autre rive, une grande foule se rassembla autour de lui. Il se tenait au bord de la mer.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 22, 'Alors vint l\'un des chefs de la synagogue, nommé Jaïrus, qui, ayant vu Jésus, se jeta à ses pieds.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 23, 'Il le priait instamment et lui disait: Ma petite fille est à toute extrémité; viens lui imposer les mains, pour qu\'elle soit guérie et qu\'elle vive.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 24, 'Jésus alla avec lui; et une grande foule le suivait et le pressait de tous les côtés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 25, 'Or, il se trouvait là une femme malade d\'une perte de sang depuis douze ans.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 26, 'Elle avait beaucoup souffert entre les mains de plusieurs médecins, et elle y avait dépensé tout son bien sans recevoir aucun soulagement; son état avait plutôt empiré.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 27, 'Ayant entendu parler de Jésus, elle vint dans la foule, par derrière, et elle toucha son vêtement.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 28, 'Car elle disait: Si je touche seulement ses vêtements, je serai guérie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 29, 'Au même instant, la perte de sang s\'arrêta; et elle sentit dans son corps qu\'elle était guérie de son mal.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 30, 'Aussitôt Jésus, ayant senti en lui-même qu\'une force était sortie de lui, se retourna au milieu de la foule, et il dit: Qui a touché mes vêtements?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 31, 'Ses disciples lui répondirent: Tu vois que la foule te presse, et tu dis: Qui est-ce qui m\'a touché?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 32, 'Mais il regardait tout autour de lui, pour voir celle qui avait fait cela.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 33, 'Alors la femme, effrayée et tremblante, sachant ce qui lui était arrivé, vint se jeter à ses pieds, et elle lui dit toute la vérité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 34, 'Jésus lui dit: Ma fille, ta foi t\'a sauvée; va en paix, et sois guérie de ton mal.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 35, 'Comme il parlait encore, on vint de la maison du chef de la synagogue pour lui dire: Ta fille est morte; pourquoi importuner encore le Maître?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 36, 'Mais Jésus, sans s\'arrêter à ces paroles, dit au chef de la synagogue: Ne crains point, crois seulement!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 37, 'Et il ne permit à personne de le suivre, si ce n\'est à Pierre, à Jacques et à Jean, frère de Jacques.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 38, 'Quand il fut arrivé à la maison du chef de la synagogue, il vit une foule bruyante, des gens qui pleuraient et qui jetaient de grands cris.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 39, 'Étant entré, il leur dit: Pourquoi faites-vous tout ce bruit, et pourquoi pleurez-vous? L\'enfant n\'est pas morte, mais elle dort.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 40, 'Et ils se moquaient de lui. Alors, il les fit tous sortir; il ne prit avec lui que le père et la mère de l\'enfant, et ceux qui l\'accompagnaient; puis il entra là où se trouvait l\'enfant.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 41, 'L\'ayant prise par la main, il lui dit: Talilha koumi! — c\'est-à-dire: Petite fille, je te le dis, lève-toi!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 42, 'Aussitôt, elle se leva et se mit à marcher; car elle avait douze ans. Et ils furent frappés d\'un grand étonnement.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 43, 'Il leur recommanda expressément que personne ne le sût, et il fit donner à manger à l\'enfant.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 1, 'Jésus, étant parti de là, vint dans son pays, et ses disciples le suivirent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 2, 'Quand le sabbat fut venu, il se mit à enseigner dans la synagogue; et la multitude qui l\'écoutait était dans l\'étonnement et disait: D\'où cela lui vient-il? Quelle est cette sagesse qui lui est donnée, et comment de tels miracles se font-ils par ses mains?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 3, 'N\'est-ce pas le charpentier, le fils de Marie, le frère de Jacques, de Joses, de Jude et de Simon? Ses soeurs ne sont-elles pas ici parmi nous? Et il était pour eux une occasion de chute.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 4, 'Mais Jésus leur dit: Un prophète n\'est méprisé que dans son pays, dans sa parenté et dans sa maison.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 5, 'Il ne put faire là aucun miracle, si ce n\'est qu\'il guérit un petit nombre de malades en leur imposant les mains;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 6, 'et il s\'étonna de leur incrédulité. C\'est ainsi qu\'il parcourait, en enseignant, les villages des environs.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 7, 'Alors il appela les Douze, et il commença à les envoyer deux à deux, en leur donnant pouvoir sur les esprits impurs.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 8, 'Il leur ordonna de ne rien prendre pour la route, sauf un bâton; de n\'avoir ni pain, ni sac, ni monnaie dans leur ceinture;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 9, 'de ne prendre pour chaussures que des sandales, et de ne pas emporter deux tuniques.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 10, 'Il leur disait: En quelque maison que vous entriez, demeurez-y jusqu\'à ce que vous partiez.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 11, 'Et si, dans quelque endroit, on ne veut ni vous recevoir ni vous écouter, sortez de là, et secouez la poussière attachée à vos pieds, en témoignage contre les habitants.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 12, 'Étant donc partis, ils prêchèrent la repentance.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 13, 'Ils chassaient beaucoup de démons, ils oignaient d\'huile beaucoup de malades, et ils les guérissaient.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 14, 'Or, le roi Hérode entendit parler de Jésus, — dont le nom était devenu célèbre. — Et il disait: Ce Jean qui baptisait est ressuscité des morts; et c\'est pour cela qu\'il s\'opère des miracles par son moyen.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 15, 'D\'autres disaient: C\'est Élie; et d\'autres disaient: C\'est un prophète, pareil à l\'un des anciens prophètes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 16, 'Mais Hérode, l\'ayant appris, disait: C\'est ce Jean que j\'ai fait décapiter: il est ressuscité!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 17, 'En effet, ce même Hérode avait envoyé prendre Jean; il l\'avait fait enchaîner et mettre en prison, à cause d\'Hérodias, femme de Philippe, son frère, parce qu\'il l\'avait épousée,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 18, 'et que Jean lui avait dit: Il ne t\'est pas permis d\'avoir la femme de ton frère.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 19, 'Aussi Hérodias était-elle remplie de haine contre Jean, et elle désirait le faire mourir. Mais elle ne le pouvait pas;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 20, 'car Hérode craignait Jean, sachant que c\'était un homme juste et saint. Il veillait sur lui; il était souvent troublé après l\'avoir entendu, et il l\'écoutait volontiers.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 21, 'Mais il se présenta un jour favorable: Hérode donna un festin, pour l\'anniversaire de sa naissance, aux grands de sa cour, à ses officiers et aux principaux de la Galilée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 22, 'La fille même d\'Hérodias, étant entrée, dansa, et elle plut à Hérode et à ses convives. Le roi dit à la jeune fille: Demande-moi ce que tu veux, et je te le donnerai.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 23, 'Il lui fit aussi ce serment: Tout ce que tu demanderas, je te le donnerai, quand ce serait la moitié de mon royaume!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 24, 'Étant sortie, elle dit à sa mère: Que demanderai-je? Celle-ci lui répondit: La tête de Jean-Baptiste.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 25, 'Aussitôt elle s\'empressa de rentrer chez le roi, et elle lui fit sa demande, en disant: Je veux qu\'à l\'instant même, tu me donnes, sur un plat, la tête de Jean-Baptiste.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 26, 'Le roi en fut fort attristé; mais, à cause de ses serments et des convives, il ne voulut pas lui opposer un refus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 27, 'Il envoya aussitôt l\'un de ses gardes, avec l\'ordre d\'apporter la tête de Jean. Cet homme alla décapiter Jean dans la prison;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 28, 'il apporta la tête sur un plat, la donna à la jeune fille, et la jeune fille la donna à sa mère.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 29, 'Les disciples de Jean l\'ayant appris, vinrent et emportèrent son corps; et ils le mirent dans un tombeau.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 30, 'Les apôtres se rassemblèrent auprès de Jésus, et ils lui racontèrent tout ce qu\'ils avaient fait et enseigné.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 31, 'Il leur dit: Venez à l\'écart, dans un lieu désert, et prenez un peu de repos. En effet, allait et venait tant de monde, qu\'ils n\'avaient pas même le temps de manger.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 32, 'Ils partirent donc dans la barque pour se retirer à l\'écart, dans un lieu désert.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 33, 'Mais plusieurs les virent s\'éloigner et les reconnurent; de toutes les villes le peuple accourut à pied là où ils se rendaient, et il y arriva avant eux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 34, 'Alors Jésus, étant sorti de la barque, vit une grande multitude, et il fut ému de compassion pour eux, parce qu\'ils étaient comme des brebis qui n\'ont point de berger; puis il se mit à leur enseigner beaucoup de choses.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 35, 'Comme l\'heure était déjà avancée, ses disciples s\'approchèrent de lui et lui dirent: Ce lieu est désert, et l\'heure est déjà avancée;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 36, 'renvoie-les, afin qu\'ils aillent dans les campagnes et les villages des environs, pour s\'acheter de quoi manger.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 37, 'Il leur répondit: Donnez-leur vous-mêmes à manger. Ils lui dirent! Irons-nous acheter pour deux cents deniers de pain, afin de leur donner à manger?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 38, 'Il leur répondit: Combien avez-vous de pains? Allez et voyez. Ils s\'en assurèrent et lui dirent: Cinq pains et deux poissons.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 39, 'Alors il leur commanda de les faire tous asseoir, par groupes, sur l\'herbe verte.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 40, 'Et ils s\'assirent par rangées, par centaines et par cinquantaines.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 41, 'Jésus prit les cinq pains et les deux poissons; et, levant les yeux au ciel, il rendit grâces, rompit les pains et les donna à ses disciples pour les offrir à la foule; il leur partagea aussi les deux poissons.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 42, 'Tous mangèrent et furent rassasiés;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 43, 'et on emporta douze paniers pleins de morceaux de pain, avec ce qui restait des poissons.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 44, 'Or, ceux qui avaient mangé étaient au nombre de cinq mille hommes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 45, 'Aussitôt après, Jésus obligea ses disciples à entrer dans la barque et à passer avant lui sur l\'autre rive, vers Beth-saïda, pendant qu\'il renverrait le peuple.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 46, 'Après l\'avoir renvoyé, il s\'en alla sur la montagne pour prier.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 47, 'Quand le soir fut venu, la barque était au milieu de la mer, et Jésus était seul à terre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 48, 'Et il vit qu\'ils avaient beaucoup de peine à ramer, parce que le vent leur était contraire. Vers la quatrième veille de la nuit, il vint à eux, marchant sur la mer; et il voulait les devancer.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 49, 'Quand ils le virent marcher sur la mer, ils crurent que c\'était un fantôme, et ils jetèrent des cris;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 50, 'car tous l\'avaient vu, et ils en étaient troublés. Mais aussitôt il leur parla et leur dit: Rassurez-vous c\'est moi, n\'ayez point de peur!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 51, 'Alors il monta auprès d\'eux dans la barque, et le vent s\'apaisa. Ils furent encore plus saisis d\'étonnement;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 52, 'Car ils n\'avaient pas compris le miracle des pains, parce que leur cœur était endurci.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 53, 'Quand ils eurent traversé la mer, ils vinrent au pays de Génézareth, et ils abordèrent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 54, 'Dès qu\'ils furent sortis de la barque, les gens reconnurent Jésus:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 55, 'ils parcoururent toute la contrée, et ils se mirent à apporter sur leurs lits ceux qui étaient malades, partout où ils entendaient dire que Jésus se trouvait.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 56, 'Et dans tous les endroits où il arrivait, villages, villes ou campagnes, on mettait les malades sur les places publiques, et on le priait de leur permettre de toucher au moins le bord de son vêtement; et tous ceux qui le touchaient étaient guéris.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 1, 'Alors les pharisiens et quelques scribes, venus de Jérusalem, se rassemblèrent près de Jésus;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 2, 'et ils virent que quelques-uns de ses disciples prenaient leur repas avec des mains qui n\'avaient pas été purifiées, c\'est-à-dire non lavées.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 3, 'Or, les pharisiens, et les Juifs en général, ne mangent pas sans se laver les mains soigneusement, observant en cela la tradition des anciens;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 4, 'et, lorsqu\'ils reviennent des places publiques, ils ne mangent pas non plus sans faire leurs ablutions. Il y a aussi beaucoup d\'autres coutumes qu\'ils observent par tradition, comme de laver les coupes et les vases de terre ou de cuivre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 5, 'Les pharisiens et les scribes demandèrent donc à Jésus: Pourquoi tes disciples ne suivent-ils pas la tradition des anciens, et prennent-ils leur repas avec des mains qu\'ils n\'ont pas purifiées?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 6, 'Il leur répondit: Ésaïe a bien prophétisé à votre sujet, hypocrites, ainsi qu\'il est écrit: «Ce peuple m\'honore des lèvres; mais son coeur est bien éloigné de moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 7, 'C\'est en vain qu\'ils me rendent un culte, enseignant des préceptes qui ne sont que des commandements d\'hommes.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 8, 'Vous abandonnez le commandement de Dieu, et vous observez la tradition des hommes!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 9, 'Il leur disait aussi: Vous annulez fort bien le commandement de Dieu, pour maintenir votre tradition.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 10, 'Car Moïse a dit: «Honore ton père et ta mère» et: «Que celui qui maudira son père ou sa mère soit puni de mort.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 11, 'Mais vous, vous dites: Si un homme dit à son père ou à sa mère: Tout ce dont je pourrais t\'assister est corban, — c\'est-à-dire: un don fait à Dieu —,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 12, 'dans ce cas, il ne lui est plus permis de rien faire pour son père ou pour sa mère.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 13, 'Voilà comment vous anéantissez la parole de Dieu par la tradition que vous avez établie! Et vous faites beaucoup d\'autres choses semblables.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 14, 'Alors, ayant appelé de nouveau la foule, il leur dit: Écoutez-moi tous et comprenez:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 15, 'Rien de ce qui est hors de l\'homme et qui entre en lui, ne peut le souiller; mais ce qui sort de lui, voilà ce qui souille l\'homme!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 16, '[Si quelqu\'un a des oreilles pour entendre, qu\'il entende!]');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 17, 'Quand il fut rentré dans la maison, loin de la foule, ses disciples l\'interrogèrent sur cette parabole.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 18, 'Et il leur dit: Vous aussi, vous êtes donc sans intelligence? Ne comprenez-vous pas que rien de ce qui entre, du dehors, dans l\'homme, ne peut le souiller?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 19, 'En effet, cela n\'entre pas dans son cœur, mais passe dans le ventre et est rejeté dans quelque lieu secret: ainsi sont purifiés tous les aliments.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 20, 'Il disait donc: Ce qui sort de l\'homme, voilà ce qui souille l\'homme!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 21, 'Car, c\'est du dedans, c\'est du cœur des hommes que sortent les mauvaises pensées, les impudicités,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 22, 'les vols, les meurtres, les adultères, la cupidité, les méchancetés, la fraude, la débauche, le regard envieux, la calomnie, l\'orgueil, le dérèglement de l\'esprit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 23, 'Toutes ces mauvaises passions sortent du dedans et, souillent l\'homme.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 24, 'Puis Jésus partit de là, et il s\'en alla vers les frontières de Tyr et de Sidon. Étant entré dans une maison, il ne voulait pas que personne le sût; mais il ne put rester caché.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 25, 'En effet, une femme, dont la fille était possédée d\'un esprit impur, ayant entendu parler de lui, entra aussitôt et, se jeta à ses pieds.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 26, 'Cette femme était grecque, syro-phénicienne de nation. Et elle le suppliait de chasser le démon hors de sa fille.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 27, 'Jésus lui dit: Laisse d\'abord les enfants se rassasier; car il ne convient pas de prendre le pain des enfants pour le jeter aux petits chiens.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 28, 'Mais elle répondit et lui dit: Assurément, Seigneur; pourtant les petits chiens mangent, sous la table, quelques miettes des enfants.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 29, 'Alors il lui dit: A cause de cette parole, va, le démon est sorti de ta fille!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 30, 'Et quand elle fut de retour dans sa maison, elle trouva l\'enfant couchée sur le lit, et le démon chassé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 31, 'Jésus, ayant quitté les frontières de Tyr, revint par Sidon vers la mer de Galilée, en traversant le territoire de la Décapole.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 32, 'On lui amena un sourd, qui parlait difficilement; et on le pria de poser la main sur lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 33, 'L\'ayant emmené à l\'écart, loin de la foule, Jésus lui mit les doigts dans les oreilles, et, avec sa salive, il lui toucha la langue.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 34, 'Puis, levant les yeux au ciel, il soupira et lui dit: Ephphatah! c\'est-à-dire: Ouvre toi!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 35, 'Alors les oreilles du sourd furent ouvertes; sa langue fut aussitôt déliée, et il parlait distinctement.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 36, 'Jésus leur défendit de le dire à personne; mais plus il le leur défendait, plus ils en parlaient.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 37, 'Et ils étaient dans le plus grand étonnement et disaient: Il a bien fait toutes choses: il fait entendre les sourds et, parler les muets!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 1, 'En ces jours-là, comme il y avait de nouveau avec Jésus une grande multitude, qui n\'avait rien à manger, il appela les disciples et leur dit:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 2, 'J\'ai compassion de cette multitude de gens car il y a déjà trois jours qu\'ils ne me quittent pas, et ils n\'ont rien à manger.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 3, 'Si je les renvoie à jeun dans leurs demeures, les forces leur manqueront en chemin; car quelques-uns sont venus de loin.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 4, 'Ses disciples répondirent: Où pourrait-on, dans ce désert, trouver des pains pour les rassasier?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 5, 'Il leur demanda: Combien avez-vous de pains? Ils dirent: Sept.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 6, 'Alors il commanda à la foule de s\'asseoir à terre; puis il prit les sept pains, et, après avoir rendu grâces, il les rompit et les donna à ses disciples pour les distribuer; et ils les distribuèrent à la foule.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 7, 'Ils avaient aussi quelques petits poissons; Jésus après avoir rendu grâces, les fit aussi distribuer.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 8, 'Tous mangèrent et furent rassasiés; et on emporta sept corbeilles pleines des morceaux qui restaient.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 9, 'Or, ils étaient environ quatre mille. Jésus les renvoya;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 10, 'et, aussitôt après, étant entré dans la barque avec ses disciples, il alla dans le pays de Dalmanutha.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 11, 'Alors survinrent des pharisiens, qui se mirent à disputer avec lui, et ils lui demandèrent, pour le mettre à l\'épreuve, un miracle venant du ciel.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 12, 'Jésus, soupirant en son esprit, dit: Pourquoi cette génération demande-t-elle un miracle? En vérité, je vous le déclare, il ne lui en sera donné aucun.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 13, 'Et, les ayant laissés, il rentra dans la barque et passa à l\'autre bord.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 14, 'Or, les disciples avaient oublié de prendre des pains; ils n\'en avaient qu\'un seul avec eux dans la barque.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 15, 'Jésus leur fit cette recommandation: Gardez-vous avec soin du levain des pharisiens et du levain d\'Hérode.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 16, 'Ils se disaient entre eux: C\'est parce que nous n\'avons pas de pains!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 17, 'Mais Jésus, s\'en étant aperçu, leur dit: Pourquoi vous dites- vous: c\'est parce que nous n\'avons pas de pains? N\'entendez-vous pas et ne comprenez-vous pas encore? Avez-vous toujours un coeur endurci?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 18, 'Vous avez des yeux, et vous ne voyez pas! Vous avez des oreilles, et, vous n\'entendez point! N\'avez-vous donc pas de mémoire?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 19, 'Lorsque j\'ai rompu les cinq pains pour les cinq mille hommes, combien avez-vous emporté de paniers pleins de morceaux? Ils lui répondirent Douze.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 20, 'Et lorsque j\'ai rompu les sept pains pour les quatre mille hommes, combien avez-vous emporté de corbeilles pleines de morceaux? Ils lui répondirent: Sept.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 21, 'Puis il leur dit N\'avez-vous pas encore compris?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 22, 'Ils allèrent ensuite à Bethsaïda. On amena à Jésus un aveugle, et on le pria de le toucher.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 23, 'Alors il prit l\'aveugle par la main, et, l\'ayant conduit hors du village, il lui mit de la salive sur les yeux, lui imposa les mains, et lui demanda s\'il voyait quelque chose.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 24, 'L\'aveugle, ayant regardé, dit: J\'aperçois des hommes qui marchent, pareils à des arbres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 25, 'Ensuite Jésus lui mit de nouveau les mains sur les yeux. L\'aveugle regarda; il fut guéri, et il voyait tout distinctement.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 26, 'Jésus le renvoya dans sa maison et lui dit: Ne rentre pas dans le village.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 27, 'Jésus, étant parti de là avec ses disciples, vint dans les villages voisins de Césarée de Philippe. Chemin faisant, il demanda à ses disciples: Qui dit-on, parmi les hommes, que je suis?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 28, 'Ils répondirent: Les uns disent: Jean-Baptiste; d\'autres, Elie; et d\'autres, l\'un des prophètes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 29, 'Il leur dit: Mais vous, qui dites-vous que je suis? Pierre lui répondit: Tu es le Christ!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 30, 'Et Jésus leur défendit sévèrement de dire cela de lui à personne.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 31, 'Alors il commença à leur enseigner qu\'il fallait que le fils de l\'homme souffrît beaucoup, qu\'il fût rejeté par les anciens, par les principaux sacrificateurs et les scribes, qu\'il fût mis à mort, et qu\'il ressuscitât trois jours après.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 32, 'Il leur en parlait ouvertement. Pierre, l\'ayant pris à part, se mit à lui faire des remontrances.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 33, 'Mais Jésus, se retournant et regardant ses disciples, censura Pierre et lui dit: Arrière de moi, Satan! Car tes pensées ne viennent pas de Dieu! Tu penses comme les hommes!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 34, 'Puis, ayant appelé le peuple avec ses disciples, il leur dit: Si quelqu\'un veut venir après moi, qu\'il renonce à lui- même, qu\'il se charge de sa croix et qu\'il me suive.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 35, 'Car celui qui voudra sauver sa vie la perdra; mais celui qui perdra sa vie à cause de moi et de l\'Évangile, la sauvera.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 36, 'Et que servirait-il à un homme de gagner le monde entier, s\'il perdait son âme?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 37, 'Ou bien, que donnerait l\'homme en échange de son âme?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 38, 'Car si quelqu\'un a honte de moi et de mes paroles, au milieu de cette génération adultère et pécheresse, le Fils de l\'homme aura aussi honte de lui, lorsqu\'il viendra dans la gloire de son Père avec les saints anges.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 1, 'Il leur disait aussi: En vérité, je vous le déclare, quelques-uns de ceux qui sont ici présents ne mourront pas, avant d\'avoir vu le règne de Dieu venir avec puissance.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 2, 'Six jours après, Jésus prit avec lui Pierre, Jacques et Jean; il les mena seuls à l\'écart sur une haute montagne; et il fut transfiguré en leur présence.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 3, 'Ses vêtements devinrent resplendissants et d\'une blancheur si éblouissante, qu\'il n\'y a pas de foulon sur la terre qui puisse blanchir ainsi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 4, 'Moïse et Élie leur apparurent, et ils s\'entretenaient avec Jésus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 5, 'Alors Pierre, prenant la parole, dit à Jésus: Maître, il est bon pour nous d\'être ici; dressons-y trois tentes, une pour toi, une pour Moïse, et une pour Élie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 6, 'En effet, il ne savait pas ce qu\'il disait, parce qu\'ils étaient effrayés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 7, 'Puis il vint une nuée qui les couvrit; et on entendit une voix, sortant de la nuée, qui disait: Celui-ci est mon Fils bien-aimé, écoutez-le!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 8, 'Soudain, les disciples ayant regardé autour d\'eux, ne virent plus personne que Jésus, qui était seul avec eux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 9, 'Comme ils descendaient de la montagne, Jésus leur défendit de dire à personne ce qu\'ils avaient vu, jusqu\'à ce que le Fils de l\'homme fût ressuscité des morts.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 10, 'Ils retinrent donc cette parole en eux-mêmes, se demandant ce que c\'était que ressusciter des morts.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 11, 'Et ils l\'interrogèrent, en disant: Pourquoi les scribes disent-ils qu\'il faut qu\'Élie vienne premièrement?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 12, 'Il leur répondit: Il est vrai qu\'Élie devait venir premièrement et rétablir toutes choses. Comment donc est-il écrit au sujet du Fils de l\'homme qu\'il doit souffrir beaucoup et être méprisé?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 13, 'Or, je vous le déclare, Élie est déjà venu, et ils lui ont fait tout ce qu\'ils ont voulu, suivant ce qui est écrit à son sujet.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 14, 'Étant venus vers les autres disciples, ils virent une très grande foule autour d\'eux, et des scribes qui discutaient avec eux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 15, 'Dès que toute cette foule vit Jésus, elle fut saisie d\'étonnement, et tous, étant accourus, le saluaient.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 16, 'Alors il leur demanda: Sur quoi discutiez-vous avec eux?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 17, 'Un homme de la foule répondit: Maître, je t\'ai amené mon fils; il est possédé d\'un esprit muet,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 18, 'qui l\'agite par des convulsions partout où il le saisit; il écume, grince des dents et devient tout raide. J\'ai prié tes disciples de chasser cet esprit, mais ils n\'ont pas pu le faire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 19, 'Alors Jésus leur répondit: race incrédule, jusques à quand serai-je avec vous? Jusques à quand vous supporterai-je? Amenez-le-moi!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 20, 'Et ils le lui amenèrent. Dès que l\'enfant vit Jésus, l\'esprit l\'agita avec violence; il tomba par terre, et il se roulait en écumant.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 21, 'Jésus demanda au père: Combien y a-t-il de temps que cela lui arrive? Le père dit: Depuis son enfance.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 22, 'L\'esprit l\'a souvent jeté dans le feu et dans l\'eau, pour le faire périr; mais si tu y peux quelque chose, aide-nous et aie compassion de nous!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 23, 'Jésus lui répondit: Si tu peux? — me dis-tu. Toutes choses sont possibles pour celui qui croit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 24, 'Aussitôt le père de l\'enfant s\'écria: Je crois! Aide-moi dans mon incrédulité!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 25, 'Quand Jésus vit que le peuple accourait en foule, il reprit sévèrement l\'esprit impur et lui dit: Esprit muet et sourd, je te le commande, sors de cet enfant et n\'y rentre plus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 26, 'Alors l\'esprit sortit, en jetant un grand cri et en l\'agitant avec violence; et l\'enfant devint comme mort, de sorte que plusieurs disaient: Il est mort!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 27, 'Mais Jésus, l\'ayant pris par la main, le releva; et l\'enfant se tint debout.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 28, 'Lorsque Jésus fut entré dans une maison, ses disciples lui demandèrent en particulier: Pourquoi n\'avons-nous pas pu chasser ce démon?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 29, 'Il leur répondit: Rien, si ce n\'est la prière, ne peut faire sortir cette espèce de démons.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 30, 'Étant partis de là, ils traversèrent la Galilée; et Jésus ne voulait pas que personne le sût.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 31, 'En effet, il instruisait ses disciples, et il leur disait: Le Fils de l\'homme va être livré entre les mains des hommes, et ils le feront mourir; et trois jours après avoir été mis à mort, il ressuscitera.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 32, 'Mais eux ne comprenaient point cette parole, et ils craignaient de l\'interroger.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 33, 'Ils vinrent à Capernaüm; et quand ils furent dans la maison, Jésus leur demanda: De quoi parliez-vous en chemin?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 34, 'Mais ils gardaient le silence; car ils avaient discuté en chemin pour savoir qui d\'entre eux était le plus grand.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 35, 'S\'étant alors assis, il appela les Douze et leur dit: Si quelqu\'un veut être le premier, qu\'il soit le dernier de tous et le serviteur de tous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 36, 'Puis il prit un petit enfant et le mit au milieu d\'eux; et, le tenant entre ses bras, il leur dit:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 37, 'Celui qui reçoit un de ces petits enfants en mon nom, me reçoit; et celui qui me reçoit, ce n\'est pas moi qu\'il reçoit, mais Celui qui m\'a envoyé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 38, 'Jean lui dit: Maître, nous avons vu quelqu\'un qui chassait les démons en ton nom, et nous l\'en avons empêché, parce qu\'il ne nous suit pas.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 39, 'Jésus répondit: Ne l\'en empêchez point; car il n\'y a personne qui, faisant un miracle en mon nom, puisse en même temps parler mal de moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 40, 'Celui qui n\'est pas contre nous est pour nous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 41, 'Et celui qui vous donnera un verre d\'eau en mon nom, parce que vous appartenez à Christ, — en vérité, je vous le déclare, il ne perdra pas sa récompense.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 42, 'Mais si quelqu\'un fait tomber dans le péché l\'un de ces petits qui croient, mieux vaudrait pour lui qu\'on lui mit au cou une grosse meule de moulin, et qu\'on le jetât dans la mer!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 43, 'Si ta main te fait tomber dans le péché, coupe-la; il vaut mieux pour toi que tu entres manchot dans la vie,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 44, 'que d\'avoir tes deux mains et d\'aller dans la géhenne, dans le feu qui ne s\'éteint point, [là où leur ver ne meurt point, et où le feu ne s\'éteint point.]');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 45, 'Et si ton pied te fait tomber dans le péché, coupe-le; il vaut mieux pour toi que tu entres boiteux dans la vie,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 46, 'que d\'avoir tes deux pieds et d\'être jeté dans la géhenne, [là où leur ver ne meurt point, et où le feu ne s\'éteint point.]');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 47, 'Et si ton oeil te fait tomber dans le péché, arrache-le! Il vaut mieux pour toi que tu entres dans le royaume de Dieu, n\'ayant qu\'un oeil, que d\'avoir deux yeux et d\'être jeté dans la géhenne,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 48, '«là où leur ver ne meurt point, et où le feu ne s\'éteint point.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 49, 'Car chacun sera salé de feu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 50, 'C\'est une bonne chose que le sel; mais si le sel perd sa saveur, avec quoi la lui rendrez-vous? Ayez du sel en vous-mêmes, et vivez en paix entre vous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 1, 'Jésus, étant parti de là, passa sur le territoire de la Judée, au-delà du Jourdain. La foule se rassembla encore auprès de lui, et, selon sa coutume, il se mit à l\'instruire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 2, 'Alors les pharisiens s\'approchèrent et lui demandèrent, pour le mettre à l\'épreuve: Est-il permis à un homme de répudier sa femme?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 3, 'Il leur répondit: Qu\'est-ce que Moïse vous a commandé?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 4, 'Ils lui dirent: Moïse a permis d\'écrire une lettre de divorce et de répudier sa femme.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 5, 'Jésus leur répondit: C\'est à cause de la dureté de votre coeur qu\'il vous a donné ce commandement.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 6, 'Mais au commencement de la création. Dieu fit un homme et une femme,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 7, '«C\'est pourquoi, l\'homme quittera son père et sa mère et s\'attachera à sa femme;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 8, 'et les deux ne feront qu\'une seule chair.» Ainsi ils ne sont plus deux, mais une seule chair.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 9, 'Que l\'homme ne sépare donc pas ce que Dieu a uni.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 10, 'Lorsqu\'ils furent dans la maison, les disciples l\'interrogèrent encore sur ce sujet;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 11, 'et il leur dit: Quiconque répudie sa femme pour en épouser une autre commet un adultère envers elle;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 12, 'et si une femme qui a quitté son mari en épouse un autre, elle commet un adultère.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 13, 'On lui présenta des petits enfants, afin qu\'il les touchât; mais les disciples reprenaient ceux qui les présentaient.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 14, 'Jésus, voyant cela, en fut indigné, et il leur dit: Laissez venir à moi les petits enfants, et ne les en empêchez point; car le royaume de Dieu est pour ceux qui leur ressemblent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 15, 'En vérité, je vous le déclare, quiconque ne recevra pas le royaume de Dieu comme un petit enfant, n\'y entrera point.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 16, 'Et, les ayant pria entre ses bras, il leur imposa les mains et les bénit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 17, 'Comme il sortait pour se mettre en route, un homme accourut; et, se jetant à genoux devant lui, il lui demanda: Mon bon Maître, que dois-je faire pour hériter la vie éternelle?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 18, 'Jésus lui répondit: Pourquoi m\'appelles-tu bon? Un seul est bon, c\'est Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 19, 'Tu connais les commandements: «Ne commets point d\'adultère; ne tue pas; ne dérobe point; ne dis pas de faux témoignage; ne fais tort à personne; honore ton père et ta mère.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 20, 'L\'homme répondit: Maître, j\'ai observé toutes ces choses dès ma jeunesse.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 21, 'Jésus, l\'ayant regardé, l\'aima, et il lui dit: Il te manque une chose. Va, vends tout ce que tu as, donne-le aux pauvres, et tu auras un trésor dans le ciel; puis, viens et suis-moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 22, 'Mais cet homme fut affligé de cette parole, et il s\'en alla tout triste; car il avait de grands biens.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 23, 'Alors Jésus, regardant autour de lui, dit à ses disciples: Qu\'il est difficile à ceux qui ont des richesses d\'entrer dans le royaume de Dieu!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 24, 'Ses disciples furent étonnés de ces paroles. Mais Jésus, reprenant, leur dit: Mes enfants, qu\'il est difficile à ceux qui se confient dans les richesses d\'entrer dans le royaume de Dieu!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 25, 'Il est plus facile à un chameau de passer par le trou de l\'aiguille, qu\'il ne l\'est à un riche d\'entrer dans le royaume de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 26, 'Ils furent encore plus étonnés, et ils se disaient l\'un à l\'autre: Et qui peut donc être sauvé?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 27, 'Jésus, les regardant, leur dit: Cela est impossible aux hommes, mais non pas à Dieu; car toutes choses sont possibles à Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 28, 'Pierre se mit à lui dire: Voici que nous avons tout quitté, et nous t\'avons suivi!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 29, 'Jésus répondit: En vérité, je vous le déclare, de tous ceux qui ont quitté maison, ou frères, ou soeurs, ou père, ou mère, ou enfants, ou champs, à cause de moi et de l\'Évangile,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 30, 'il n\'y en a pas un qui ne reçoive maintenant, dès le temps présent, cent fois davantage, des maisons, des frères, des soeurs, des mères, des enfants, et des champs, — avec des persécutions, — et, dans le siècle à venir, la vie éternelle.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 31, 'Mais plusieurs des premiers seront les derniers, et plusieurs des derniers seront les premiers.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 32, 'Ils étaient en chemin pour monter à Jérusalem, et Jésus marchait en avant; les disciples étaient saisis d\'effroi, et la crainte s\'était emparée de ceux qui le suivaient. Prenant encore avec lui les Douze, il se mit à leur dire ce qui devait lui arriver:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 33, 'Voici que nous montons à Jérusalem, et le Fils de l\'homme sera livré aux principaux sacrificateurs et aux scribes; ils le condamneront à mort et le livreront aux Païens.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 34, 'On se moquera de lui, on crachera sur lui, on le battra de verges, et on le fera mourir; et trois jours après, il ressuscitera.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 35, 'Alors Jacques et Jean, les fils de Zébédée, s\'approchèrent de Jésus et lui dirent: Maître, nous voudrions que tu fisses pour nous ce que nous te demanderons.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 36, 'Il leur répliqua: Que voulez-vous que je fasse pour vous?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 37, 'Ils lui répondirent: Accorde-nous d\'être assis dans ta gloire, l\'un à ta droite, l\'autre à ta gauche.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 38, 'Mais Jésus leur dit: Vous ne savez ce que vous demandez. Pouvez-vous boire la coupe que je bois, et être baptisés du baptême dont je suis baptisé?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 39, 'Ils lui répondirent: Nous le pouvons. Jésus leur dit: Vous boirez la coupe que je bois, et vous serez baptisés du baptême dont je suis baptisé;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 40, 'mais, quant à être assis à ma droite ou à ma gauche, il ne m\'appartient pas de l\'accorder: c\'est pour ceux à qui cela est réservé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 41, 'Les dix autres, qui avaient entendu cette demande, furent indignés contre Jacques et Jean.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 42, 'Mais Jésus, les ayant appelés, leur dit: Vous savez que ceux qui sont regardés comme les chefs des nations les asservissent, et que les grands les tiennent sous leur puissance.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 43, 'Il n\'en est pas ainsi parmi vous; au contraire, celui qui voudra être grand parmi vous, sera.votre serviteur;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 44, 'et celui d\'entre vous qui voudra être le premier, sera l\'esclave de tous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 45, 'Car le Fils de l\'homme est venu, non pour être servi, mais pour servir, et donner sa vie pour la rançon de plusieurs.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 46, 'Ensuite ils arrivèrent à Jérico. Comme Jésus en repartait avec ses disciples et une assez grande foule, un mendiant aveugle, Bartimée, le fils de Timée, était assis au bord du chemin.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 47, 'Ayant entendu dire que c\'était Jésus de Nazareth, il se mit à crier et à dire: Fils de David, Jésus, aie pitié de moi!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 48, 'Plusieurs le reprenaient, pour le faire taire; mais il criait encore plus fort: Fils de David, aie pitié de moi!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 49, 'Jésus, s\'étant arrêté, dit: Appelez-le. Ils appelèrent l\'aveugle, en lui disant: Prends courage, lève-toi, il t\'appelle.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 50, 'Et jetant son manteau, il s\'élança et vint vers Jésus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 51, 'Alors Jésus, prenant la parole, lui dit: Que veux-tu que je te fasse? L\'aveugle lui répondit: Maître, que je recouvre la vue!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 52, 'Jésus lui dit: Va, ta foi t\'a guéri. Aussitôt l\'aveugle recouvra la vue; et il suivait Jésus dans le chemin.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 1, 'Comme ils approchaient de Jérusalem, et qu\'ils étaient près de Bethphagé et de Béthanie, vers la montagne des Oliviers, Jésus envoya deux de ses disciples;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 2, 'et il leur dit: Allez au village qui est devant vous. Dès que vous y serez entrés, vous trouverez un ânon attaché, sur lequel personne n\'est encore monté; détachez-le, et amenez-le-moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 3, 'Si quelqu\'un vous dit: Pourquoi faites-vous cela? — vous répondrez: Le Seigneur en a besoin. Et aussitôt il l\'enverra ici.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 4, 'Ils s\'en allèrent, et ils trouvèrent l\'ânon attaché dehors devant une porte, au tournant du chemin; et ils le détachèrent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 5, 'Quelques-uns de ceux qui étaient là leur dirent: Pourquoi détachez-vous cet ânon?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 6, 'Ils leur répondirent comme Jésus le leur avait commandé; et on les laissa aller.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 7, 'Ils amenèrent à Jésus l\'ânon, sur lequel ils mirent leurs vêtements; et Jésus monta dessus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 8, 'Plusieurs étendirent leurs vêtements sur le chemin, d\'autres des branches d\'arbres coupées dans les champs.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 9, 'Et ceux qui marchaient devant, comme ceux qui suivaient, criaient: Hosanna! Béni soit celui qui vient au nom du Seigneur!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 10, 'Béni soit le règne qui vient, le règne de David, notre père! Hosanna au plus haut des cieux!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 11, 'Jésus entra dans Jérusalem, et il se rendit au temple; puis, ayant porté ses regards sur tout ce qui l\'entourait, comme il était déjà tard, il sortit pour aller à Béthanie avec les Douze.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 12, 'Le lendemain, quand ils eurent quitté Béthanie, il eut faim.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 13, 'Apercevant de loin un figuier qui avait des feuilles, il alla voir s\'il y trouverait du fruit; mais, s\'en étant approché, il n\'y trouva que des feuilles; car ce n\'était pas la saison des figues.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 14, 'Alors, prenant la parole, il dit au figuier: Que jamais personne ne mange de ton fruit! Et ses disciples l\'entendirent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 15, 'Puis ils vinrent à Jérusalem. Jésus, étant entré dans le temple, se mit à chasser ceux qui vendaient et qui achetaient dans le temple, et il renversa les tables des changeurs et les sièges de ceux qui vendaient les pigeons.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 16, 'Il ne permettait à personne de porter aucun objet à travers le temple.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 17, 'Et il les enseignait, en disant: N\'est-il pas écrit: «Ma maison sera appelée une maison de prière pour toutes les nations»? Mais vous, vous en avez fait une caverne de voleurs.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 18, 'Les principaux sacrificateurs et les scribes, l\'ayant entendu, cherchaient les moyens de le faire périr; car ils le craignaient, parce que toute la foule était frappée de son enseignement.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 19, 'Quand le soir fut venu, ils sortirent de la ville.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 20, 'Le lendemain matin, comme ils revenaient, ils virent le figuier séché jusqu\'aux racines.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 21, 'Alors Pierre, se souvenant de ce qui s\'était passé, lui dit: Maître, vois! Le figuier que tu as maudit a séché.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 22, 'Jésus, prenant la parole, leur dit: Ayez foi en Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 23, 'En vérité. Je vous le déclare, quiconque dira à cette montagne: Soulève-toi et jette-toi dans la mer. — s\'il ne doute pas dans son coeur, mais s\'il croit que ce qu\'il dit s\'accomplira, cela lui sera accordé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 24, 'C\'est pourquoi, je vous le déclare: Tout ce que vous demanderez en priant, croyez que vous l\'avez obtenu, et cela vous sera accordé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 25, 'Et quand vous vous levez pour prier, si vous avez quelque chose contre quelqu\'un, pardonnez, afin que votre Père qui est dans les cieux vous pardonne aussi vos fautes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 26, '[Mais si vous ne pardonnez pas, votre Père, qui est dans les cieux, ne vous pardonnera pas non plus vos fautes.]');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 27, 'Ils revinrent à Jérusalem. Comme il allait et venait dans le temple, les principaux sacrificateurs, les scribes et les anciens s\'approchèrent de lui,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 28, 'et ils lui dirent: En vertu de quelle autorité fais-tu ces choses? Qui t\'a donné l\'autorité de les faire?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 29, 'Jésus leur dit: Je vous poserai, moi aussi, une question; répondez-moi, et je vous dirai en vertu de quelle autorité je fais ces choses.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 30, 'Le baptême de Jean venait-il du ciel ou des hommes? Répondez-moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 31, 'Or, ils raisonnaient ainsi entre eux: Si nous disons: Du Ciel. — il dira: Pourquoi donc n\'avez-vous pas cru à sa parole?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 32, 'Si nous disons, au contraire: Des hommes. — nous avons à craindre le peuple. En effet, tous croyaient que Jean était véritablement un prophète.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 33, 'Ils répondirent donc à Jésus: Nous ne savons. Alors Jésus leur dit: Et moi non plus, je ne vous dirai point en vertu de quelle autorité je fais ces choses.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 1, 'Jésus se mit à les enseigner en paraboles: Un homme planta une vigne, il l\'environna d\'une haie, il y creusa un pressoir et y bâtit une tour; puis, il la loua à des vignerons et quitta le pays.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 2, 'Quand la saison fut venue, il envoya un serviteur auprès des vignerons, pour recevoir de leurs mains une part des fruits de la vigne.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 3, 'Mais, l\'ayant saisi, ils le battirent et le renvoyèrent les mains vides.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 4, 'Il leur envoya encore un autre serviteur; mais ils le frappèrent à la tête et l\'outragèrent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 5, 'Il en envoya un autre qu\'ils tuèrent; puis, plusieurs autres, parmi lesquels ceux-ci furent battus et ceux-là tués.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 6, 'Il avait encore un fils unique et bien-aimé; il le leur envoya le dernier, en disant: Ils respecteront mon fils!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 7, 'Mais ces vignerons se dirent entre eux: C\'est l\'héritier! Allons, tuons-le, et l\'héritage sera à nous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 8, 'Et l\'ayant saisi, ils le tuèrent et le jetèrent hors de la vigne.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 9, 'Que fera donc le maître de la vigne? Il viendra et fera périr ces vignerons, et il donnera la vigne à d\'autres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 10, 'N\'avez-vous point lu cette parole de l\'Écriture: «La pierre, rejetée par ceux qui bâtissaient, est devenue la pierre de l\'angle;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 11, 'c\'est l\'ouvrage du Seigneur, et c\'est une merveille devant nos yeux»?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 12, 'Alors ils cherchèrent à se saisir de lui; car ils comprirent bien que c\'était pour eux qu\'il avait dit cette parabole. Mais ils craignirent le peuple. Et le laissant, ils s\'en allèrent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 13, 'Ensuite, ils lui envoyèrent quelques-uns des pharisiens et des hérodiens, pour le surprendre dans ses paroles.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 14, 'Ceux-ci vinrent donc et lui dirent: Maître, nous savons que tu es véridique et que tu ne te préoccupes de personne, parce que tu ne regardes pas à l\'apparence des hommes; mais tu enseignes la voie de Dieu en toute vérité. Est-il permis de payer l\'impôt à César, ou non?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 15, 'Payerons-nous, ou ne payerons-nous pas? Mais lui, connaissant leur hypocrisie, leur répondit: Pourquoi voulez-vous me tenter? Apportez-moi un denier, que je le voie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 16, 'Et ils lui en apportèrent un. Alors il leur dit: Cette effigie et cette inscription, de qui sont-elles? Ils lui répondirent: De César.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 17, 'Jésus leur dit: Rendez à César ce qui est à César, et à Dieu ce qui est à Dieu. Et ils étaient dans l\'étonnement à son sujet.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 18, 'Les sadducéens, qui disent qu\'il n\'y a point de résurrection, s\'approchèrent de lui, et ils lui posèrent cette question:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 19, 'Maître, Moïse nous a donné cette loi: Si un homme a un frère qui vienne à mourir, laissant une femme sans enfants, il épousera la veuve et suscitera une postérité à son frère.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 20, 'Or, il y avait sept frères. Le premier épousa une femme, et mourut sans laisser d\'enfants.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 21, 'Le second épousa la veuve, et mourut sans laisser d\'enfants; le troisième, de même.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 22, 'Et aucun des sept n\'a laissé d\'enfants. Après eux tous, la femme mourut aussi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 23, 'Lors de la résurrection, duquel d\'entre eux sera-t-elle la femme, puisque tous les sept l\'ont eue pour femme?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 24, 'Jésus leur répondit: N\'êtes-vous pas dans l\'erreur, parce que vous ne comprenez pas les Écritures, ni la puissance de Dieu?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 25, 'En effet, à la résurrection des morts, on ne se marie pas, et l\'on n\'est pas donné en mariage; mais les ressuscités sont comme des anges dans les cieux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 26, 'Quant aux morts et à leur résurrection, n\'avez-vous pas lu, dans le livre de Moïse, ce que Dieu lui a dit près du buisson: «Je suis le Dieu d\'Abraham, le Dieu d\'Isaac, et le Dieu de Jacob»?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 27, 'Il n\'est pas le Dieu des morts, mais des vivants! Vous êtes dans une grande erreur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 28, 'Alors un des scribes, qui les avait entendus discuter ensemble, sachant qu\'il leur avait bien répondu, s\'approcha et lui demanda: Quel est le premier de tous les commandements?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 29, 'Jésus répondit: Voici le premier: «Écoute, Israël! Le Seigneur, notre Dieu, est le seul Seigneur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 30, 'Tu aimeras le Seigneur, ton Dieu, de tout ton coeur, de toute ton âme, de toute ta pensée, et de toute ta force.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 31, 'Et voici le second: «Tu aimeras ton prochain comme toi-même.» Il n\'y a point d\'autre commandement plus grand que ceux-là.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 32, 'Le scribe lui répondit: Maître, tu as bien dit, et avec vérité, qu\'il n\'y a qu\'un seul Dieu, et qu\'il n\'y en a point d\'autre que lui;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 33, 'que l\'aimer de tout son coeur, de toute son intelligence, et de toute sa force, et aimer son prochain comme soi-même, c\'est plus que tous les holocaustes et que tous les sacrifices!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 34, 'Jésus, voyant qu\'il avait répondu en homme intelligent, lui dit: Tu n\'es pas loin du royaume de Dieu! Et personne n\'osait plus l\'interroger.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 35, 'Alors Jésus, enseignant dans le temple, prit la parole en ces termes: Comment les scribes disent-ils que le Christ est fils de David?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 36, 'David lui-même a déclaré par le Saint-Esprit: «Le Seigneur a dit à mon Seigneur: Assieds-toi à ma droite, jusqu\'à ce que j\'aie fait de tes ennemis ton marchepied»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 37, 'Puisque David lui-même l\'appelle Seigneur, comment est-il son fils? Et une grande foule prenait plaisir à l\'écouter.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 38, 'Il leur disait aussi dans son enseignement: Gardez-vous des scribes qui aiment à se promener en robes longues, à être salués dans les places publiques,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 39, 'et qui veulent les premiers sièges dans les synagogues et les premières places dans les festins.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 40, 'Ces gens-là dévorent les maisons des veuves, en affectant de faire de longues prières: ils subiront une condamnation d\'autant plus rigoureuse!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 41, 'Jésus, étant assis vis-à-vis du tronc, regardait comment la foule y mettait de l\'argent. Plusieurs riches donnèrent beaucoup;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 42, 'une pauvre veuve vint, et elle y mit deux pites, qui font le quart d\'un sou.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 43, 'Alors, ayant appelé ses disciples, il leur dit: En vérité, je vous le déclare, cette pauvre veuve a donné plus que tous ceux qui ont mis dans le tronc.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 44, 'Car tous les autres ont donné de leur superflu; mais celle-ci a donné de son indigence, tout ce qu\'elle possédait, tout ce qu\'elle avait pour vivre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 1, 'Comme Jésus sortait du temple, un de ses disciples lui dit: Maître, regarde quelles pierres et quels bâtiments!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 2, 'Jésus lui répondit: Tu vois ces grands bâtiments? Pas une pierre n\'y restera sur une autre pierre: tout sera renversé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 3, 'Comme il était assis sur la montagne des Oliviers, vis-à-vis du temple, Pierre, Jacques, Jean et André le prirent à part, pour lui poser cette question:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 4, 'Dis-nous quand toutes ces choses arriveront, et à quel signe on connaîtra qu\'elles vont s\'accomplir?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 5, 'Jésus se mit à leur dire: Prenez garde que personne ne vous séduise.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 6, 'Plusieurs viendront en mon nom, disant: C\'est moi qui suis le Christ! Et ils séduiront beaucoup de gens.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 7, 'Quand vous entendrez parler de guerres et de bruits de guerres, ne vous troublez pas: il faut que ces choses arrivent; mais ce ne sera pas encore la fin.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 8, 'Car on verra s\'élever nation contre nation, royaume contre royaume. Il y aura des tremblements de terre en divers lieux; il y aura des famines. Ce ne sera là que le commencement des douleurs.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 9, 'Vous, soyez sur vos gardes! On vous traduira devant les tribunaux; vous serez frappés dans les synagogues, et vous comparaîtrez en présence des gouverneurs et des rois, à cause de moi, pour rendre témoignage devant eux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 10, 'Mais il faut tout d\'abord que l\'Évangile soit prêché à toutes les nations.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 11, 'Or, quand on vous emmènera pour vous livrer, ne vous mettez pas d\'avance en peine de ce que vous aurez à dire, mais dites ce qui vous sera inspiré à cette heure même; car ce ne sera pas vous qui parlerez, mais ce sera le Saint-Esprit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 12, 'Alors le frère livrera son frère à la mort, et le père son enfant; et les enfants se soulèveront contre leurs parents et les feront mourir.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 13, 'Et vous serez haïs de tous à cause de mon nom; mais celui-là qui persévérera jusqu\'à la fin, celui-là sera sauvé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 14, 'Quand vous verrez l\'abomination de la désolation établie où elle ne doit pas être — que celui qui lit cela, fasse attention! — que ceux qui seront alors dans la Judée s\'enfuient dans les montagnes;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 15, 'et que celui qui sera sur le toit ne descende pas, et qu\'il n\'entre point dans sa maison pour en emporter quoi que ce soit;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 16, 'et que celui qui sera aux champs ne retourne pas en arrière pour prendre son vêtement.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 17, 'Malheur aux femmes qui seront enceintes, et à celles qui allaiteront en ces jours-là!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 18, 'Priez pour que tout cela n\'arrive pas en hiver.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 19, 'En effet, ce seront des jours d\'une détresse telle, qu\'il n\'y en a jamais eu de pareille, — depuis le commencement, quand Dieu créa le monde, jusqu\'à maintenant, — et qu\'il n\'y en aura jamais.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 20, 'Et si le Seigneur n\'avait abrégé ces jours-là, aucune créature n\'aurait été sauvée; mais, à cause des élus qu\'il a choisis, il a abrégé ces jours.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 21, 'Alors, si quelqu\'un vous dit: Voyez, le Christ est ici! — ou: Il est là! — ne le croyez point.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 22, 'De faux christs et de faux prophètes s\'élèveront et ils feront des signes et des prodiges pour séduire, s\'il était possible, les élus eux-mêmes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 23, 'Prenez-y garde: je vous ai tout prédit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 24, 'En ces jours-là, après ce temps d\'affliction, le soleil s\'obscurcira, la lune ne donnera plus sa lumière,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 25, 'les étoiles tomberont du ciel, et les puissances qui sont dans les cieux seront ébranlées.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 26, 'Alors on verra le Fils de l\'homme venant sur les nuées, avec une grande puissance et une grande gloire;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 27, 'et il enverra les anges pour rassembler les élus des quatre vents, depuis l\'extrémité de la terre jusqu\'à l\'extrémité du ciel.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 28, 'Écoutez une comparaison empruntée au figuier. Dès que ses branches deviennent tendres, et qu\'il pousse des feuilles, vous savez que l\'été est proche.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 29, 'Vous aussi de même, quand vous verrez que ces choses arrivent, sachez que le Fils de l\'homme est proche, qu\'il est à la porte.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 30, 'En vérité, je vous le déclare, cette génération ne passera pas que toutes ces choses n\'arrivent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 31, 'Le ciel et la terre passeront, mais mes paroles ne passeront point.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 32, 'Pour ce qui est du jour et de l\'heure, personne n\'en sait rien, pas même les anges dans le ciel, ni même le Fils, mais seulement le Père.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 33, 'Soyez sur vos gardes, soyez vigilants; car vous ne savez pas quand le moment viendra.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 34, 'C\'est comme un homme qui, allant en voyage, quitte sa maison, en confie la direction à ses serviteurs, assigne à chacun sa tâche, et ordonne au portier de veiller.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 35, 'Veillez donc, vous aussi; car vous ne savez pas quand le maître de la maison viendra, si ce sera le soir, ou à minuit, ou au chant du coq, ou le matin.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 36, 'Craignez qu\'arrivant tout à coup, il ne vous trouve endormis.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 37, 'Ce que je vous dis, je le dis à tous: Veillez!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 1, 'La fête de la Pâque et des pains sans levain devait avoir lieu deux jours après; et les principaux sacrificateurs et les scribes cherchaient comment ils pourraient s\'emparer de Jésus par ruse et le faire mourir.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 2, 'Car ils disaient: Que ce ne soit pas pendant la fête, de peur qu\'il n\'y ait du tumulte parmi le peuple.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 3, 'Jésus se trouvait à Béthanie, dans la maison de Simon, le lépreux. Pendant qu\'il était à table, une femme entra, portant un vase d\'albâtre, plein d\'une huile de nard pur, d\'un grand prix. Ayant brisé le vase, elle répandit le parfum sur la tête de Jésus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 4, 'Quelques-uns s\'en indignaient entre eux et disaient: Pourquoi perdre ainsi ce parfum?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 5, 'Car on pouvait le vendre plus de trois cents deniers et les donner aux pauvres. Ainsi ils murmuraient contre elle.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 6, 'Mais Jésus dit: Laissez-la; pourquoi lui faites-vous de la peine? Elle a fait une bonne action à mon égard.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 7, 'Car vous avez toujours les pauvres avec vous, et, quand vous le voulez, vous pouvez leur faire du bien; mais moi, vous ne m\'avez pas toujours.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 8, 'Elle a fait ce qui était en son pouvoir; elle a d\'avance oint mon corps pour ma sépulture.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 9, 'En vérité, je vous le dis, partout où cet Évangile sera prêché, dans le monde entier, ce qu\'elle a fait sera aussi raconté en mémoire d\'elle.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 10, 'Alors Judas Iscariote, l\'un des Douze, alla vers les principaux sacrificateurs pour leur livrer Jésus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 11, 'Ils l\'écoutèrent avec joie et lui promirent de lui donner de l\'argent; et Judas cherchait, une occasion favorable pour le livrer.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 12, 'Le premier jour des pains sans levain, où l\'on immolait la Pâque, les disciples dirent à Jésus: Où veux-tu que nous allions te préparer le repas de la Pâque?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 13, 'Il envoya deux de ses disciples et leur dit: Allez à la ville. Vous rencontrerez un homme portant une cruche d\'eau; suivez-le,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 14, 'et là où il entrera, vous direz au maître de la maison: Le Maître dit: Où est la salle dans laquelle je mangerai la Pâque avec mes disciples?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 15, 'Il vous montrera lui-même une grande chambre haute, meublée et toute prête; préparez-nous là ce qu\'il faut.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 16, 'Les disciples partirent donc et allèrent à la ville; ils trouvèrent les choses comme Jésus le leur avait dit, et ils préparèrent la Pâque.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 17, 'Le soir, il vint avec les Douze.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 18, 'Et comme ils étaient à table et qu\'ils mangeaient, Jésus dit: En vérité, je vous le déclare, l\'un de vous, qui mange avec moi, me trahira.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 19, 'Alors ils devinrent tout tristes, et ils lui dirent, l\'un après l\'autre: Est-ce moi?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 20, 'Il leur répondit: C\'est l\'un des Douze, celui qui met la main au plat avec moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 21, 'Le Fils de l\'homme s\'en va, suivant ce qui a été écrit à son sujet; mais malheur à l\'homme par qui le Fils de l\'homme est trahi! Mieux vaudrait pour cet homme-là qu\'il ne fût jamais né.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 22, 'Pendant qu\'ils mangeaient, Jésus prit du pain; et, après avoir rendu grâces, il le rompit, le leur donna, et il dit: Prenez, ceci est mon corps.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 23, 'Ayant aussi pris la coupe et rendu grâces, il la leur donna, et ils en burent tous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 24, 'Puis il leur dit: Ceci est mon sang, le sang de l\'alliance, qui est répandu pour plusieurs.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 25, 'En vérité, je vous le déclare, je ne boirai plus de ce fruit de la vigne, jusqu\'au jour où je le boirai nouveau dans le royaume de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 26, 'Après avoir chanté les psaumes, ils sortirent pour aller à la montagne des Oliviers.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 27, 'Et Jésus leur dit: Vous allez tous avoir une occasion de chute; car il est écrit: «Je frapperai le berger, et les brebis seront dispersées.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 28, 'Mais, après que je serai ressuscité, je vous précéderai en Galilée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 29, 'Pierre lui dit: Quand tu serais pour tous une occasion de chute, tu ne le seras jamais pour moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 30, 'Jésus lui répondit: En vérité, je te déclare que toi, aujourd\'hui, cette nuit même, avant que le coq ait chanté deux fois, tu me renieras trois fois.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 31, 'Mais Pierre disait encore plus fortement: Quand même il me faudrait mourir avec toi, je ne te renierai point. Et tous les autres disaient la même chose.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 32, 'Ils allèrent ensuite dans un lieu appelé Gethsémané. Et Jésus dit à ses disciples: Asseyez-vous ici, jusqu\'à ce que j\'aie prié.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 33, 'Alors il prit avec lui Pierre, Jacques et Jean, et il commença à être saisi de frayeur et à être étreint par l\'angoisse.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 34, 'Il leur dit: Mon âme est triste jusqu\'à la mort; demeurez ici et veillez.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 35, 'Puis, étant allé un peu plus loin, il se prosternait contre terre et priait, demandant que, s\'il était possible, cette heure s\'éloignât de lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 36, 'Il disait: Abba, Père, toutes choses te sont possibles; détourne de moi cette coupe; toutefois, non ce que je veux, mais ce que tu veux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 37, 'Puis il revint et les trouva endormis; et il dit à Pierre: Simon, tu dors! Tu n\'as pu veiller une heure?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 38, 'Veillez et priez, afin que vous ne tombiez pas dans la tentation; l\'esprit est plein de bonne volonté, mais la chair est faible.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 39, 'Il s\'en alla de nouveau, et il pria, disant les mêmes paroles.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 40, 'Étant revenu, il les trouva encore endormis; car leurs yeux étaient appesantis. Et ils ne savaient que lui répondre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 41, 'Il revint pour la troisième fois, et il leur dit: Vous dormez maintenant, et vous vous reposez! C\'est assez; l\'heure est venue! Le Fils de l\'homme va être livré entre les mains des pécheurs.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 42, 'Levez-vous, allons! Voici que celui qui me trahit s\'approche.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 43, 'Aussitôt, comme Jésus parlait encore, Judas, l\'un des Douze, survint, et avec lui une grande troupe de gens armés d\'épées et de bâtons, envoyés par les principaux sacrificateurs, les scribes et les anciens.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 44, 'Or, celui qui le trahissait était convenu avec eux de ce signe: Celui à qui je donnerai un baiser, c\'est lui; saisissez-le, et emmenez-le sous bonne garde.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 45, 'Aussitôt donc que Judas fut arrivé, il s\'approcha de lui et lui dit: Maître! Et il lui donna un baiser.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 46, 'Alors ils mirent la main sur Jésus et le saisirent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 47, 'Un de ceux qui étaient là tira son épée, en frappa le serviteur du souverain sacrificateur, et il lui emporta l\'oreille.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 48, 'Jésus, prenant la parole, leur dit: Vous êtes sortis avec des épées et des bâtons pour me prendre, comme si j\'étais un brigand.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 49, 'J\'étais tous les jours au milieu de vous, enseignant dans le temple, et vous ne m\'avez pas arrêté; mais cela est arrivé, afin que les Écritures fussent accomplies.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 50, 'Alors tous l\'abandonnèrent et s\'enfuirent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 51, 'Il y avait un jeune homme qui le suivait, n\'ayant qu\'un drap sur le corps; et ils le saisirent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 52, 'Mais lui, laissant le drap, s\'échappa nu de leurs mains.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 53, 'Ils emmenèrent Jésus chez le souverain sacrificateur, où se réunirent tous les principaux sacrificateurs, les anciens et les scribes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 54, 'Pierre le suivit de loin jusque dans la cour intérieure du souverain sacrificateur; et, s\'étant assis auprès du feu avec les gardes, il se chauffait.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 55, 'Or, les principaux sacrificateurs et tout le Sanhédrin cherchaient quelque témoignage contre Jésus pour le faire mourir, et ils n\'en trouvaient point.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 56, 'Car plusieurs portaient de faux témoignages contre lui; mais leurs dépositions ne s\'accordaient pas.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 57, 'Alors quelques-uns se levèrent, qui portèrent contre lui ce faux témoignage:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 58, 'Nous lui avons entendu dire: Je détruirai ce temple, fait de main d\'homme, et en trois jours j\'en bâtirai un autre, qui ne sera pas fait de main d\'homme.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 59, 'Mais, même sur ce point, leurs témoignages ne s\'accordaient pas.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 60, 'Alors le souverain sacrificateur se levant au milieu de l\'assemblée, interrogea Jésus et lui dit: Ne réponds-tu rien à ce que ces hommes déposent contre toi?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 61, 'Mais Jésus garda le silence et ne répondit rien. Le souverain sacrificateur l\'interrogea encore, et lui dit: C\'est toi qui es le Christ, le Fils du Dieu béni?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 62, 'Jésus lui dit: Je le suis! Vous verrez le Fils de l\'homme assis à la droite de la puissance de Dieu, et venant au milieu des nuées du ciel.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 63, 'Alors le souverain sacrificateur déchira ses vêtements et dit: Qu\'avons-nous encore besoin de témoins?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 64, 'Vous avez entendu le blasphème? Que vous en semble? Tous le déclarèrent coupable et digne de mort.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 65, 'Quelques-uns se mirent à cracher sur lui, à lui couvrir le visage et à lui donner des coups de poing; et ils lui disaient: Prophétise! Et les gardes lui donnaient des coups de bâton.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 66, 'Comme Pierre était en bas dans la cour, l\'une des servantes du souverain sacrificateur y vint;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 67, 'et, voyant Pierre qui se chauffait, elle le regarda et lui dit: Toi aussi, tu étais avec Jésus de Nazareth!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 68, 'Mais il le nia et dit: Je ne sais pas, je ne comprends pas ce que tu veux dire. Puis il s\'en alla dans le vestibule, et le coq chanta.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 69, 'Cette servante, l\'ayant vu, se mit encore à dire à ceux qui étaient présents: Cet homme est bien de ces gens-là!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 70, 'Mais il le nia de nouveau. Un peu après, ceux qui étaient présents dirent à Pierre: Assurément, tu es de ces gens-là; car tu es Galiléen.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 71, 'Alors il se mit à proférer des malédictions accompagnées de serments, en disant: Je ne connais point cet homme dont vous parlez!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 72, 'Aussitôt, le coq chanta pour la seconde fois; et Pierre se ressouvint de la parole que Jésus lui avait dite: Avant que le coq ait chanté deux fois, tu me renieras trois fois. Et à cette pensée, il se mit à pleurer.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 1, 'Dès le matin, les principaux sacrificateurs tinrent conseil avec les anciens et les scribes et tout le Sanhédrin; et, après avoir fait lier Jésus, ils l\'emmenèrent et le livrèrent à Pilate.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 2, 'Pilate lui demanda: C\'est toi qui es le roi des Juifs? Jésus lui répondit: Tu le dis!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 3, 'Les principaux sacrificateurs portaient contre lui plusieurs accusations;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 4, 'et Pilate l\'interrogea encore et lui dit: Ne réponds-tu rien? Vois combien d\'accusations ils portent contre toi!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 5, 'Mais Jésus ne répondit plus rien, de sorte que Pilate en était étonné.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 6, 'Or, à chaque fête de Pâque, il leur relâchait un prisonnier, celui qu\'ils demandaient.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 7, 'Il y en avait un, nommé Barabbas, qui était en prison avec des séditieux, pour un meurtre qu\'ils avaient commis dans une émeute.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 8, 'La foule, étant montée, se mit à demander que Pilate leur fît comme il avait toujours fait.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 9, 'Il leur répondit: Voulez-vous que je vous relâche le roi des Juifs?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 10, 'Car il comprenait bien que c\'était par jalousie que les principaux sacrificateurs l\'avaient livré.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 11, 'Mais les principaux sacrificateurs poussèrent la foule à demander qu\'il leur relâchât plutôt Barabbas.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 12, 'Pilate reprit la parole et leur dit: Que ferai-je donc de celui que vous appelez le roi des Juifs?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 13, 'Ils crièrent de nouveau: Crucifie-le!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 14, 'Pilate leur dit: Mais quel mal a-t-il fait? Ils crièrent plus fort: Crucifie-le!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 15, 'Pilate, voulant satisfaire la foule, leur relâcha Barabbas; et, après avoir fait battre Jésus de verges, il le leur livra pour qu\'il fût crucifié.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 16, 'Les soldats emmenèrent Jésus à l\'intérieur de la cour, c\'est-à-dire dans le prétoire, et ils y rassemblèrent toute la cohorte.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 17, 'Ils le revêtirent d\'un manteau de pourpre, placèrent sur sa tête une couronne d\'épines qu\'ils avaient tressée,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 18, 'et ils se mirent à le saluer, en disant: Roi des Juifs, salut!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 19, 'Ils lui frappaient la tête avec un roseau, ils crachaient sur lui, et, fléchissant le genou, ils se prosternaient devant lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 20, 'Après s\'être ainsi moqués de lui, ils lui ôtèrent le manteau de pourpre, lui remirent ses vêtements, et l\'emmenèrent pour le crucifier.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 21, 'Un certain Simon, de Cyrène, père d\'Alexandre et de Rufus, passait par là en revenant des champs; ils le contraignirent à porter la croix.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 22, 'Et ils conduisirent Jésus au lieu appelé Golgotha, ce qui signifie: le lieu du Crâne.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 23, 'Ils lui présentèrent à boire du vin, mêlé de myrrhe; mais il n\'en prit point.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 24, 'Après l\'avoir crucifié, ils se partagèrent ses vêtements, en les tirant au sort, pour savoir ce que chacun en aurait.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 25, 'C\'était la troisième heure, quand ils le crucifièrent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 26, 'Le motif de sa condamnation était marqué par cette inscription: Le Roi des Juifs.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 27, 'On crucifia aussi avec lui deux brigands, l\'un à sa droite, l\'autre à sa gauche.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 28, '[Ainsi s\'accomplit cette parole des Écritures: «Il a été mis au rang des malfaiteurs.»]');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 29, 'Ceux qui passaient par là l\'outrageaient en hochant la tête et en disant: Hé! Toi qui détruis le temple et qui le rebâtis en trois jours,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 30, 'sauve-toi toi-même, et descends de la croix!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 31, 'De même aussi, les principaux sacrificateurs et les scribes disaient entre eux, en se moquant: Il en a sauvé d\'autres; il ne peut se sauver lui-même!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 32, 'Que le Christ, le roi d\'Israël, descende maintenant de la croix, afin que nous voyions et que nous croyions! Et ceux qui étaient crucifiés avec lui l\'injuriaient aussi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 33, 'Quand la sixième heure arriva, il y eut des ténèbres sur tout le pays, jusqu\'à la neuvième heure.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 34, 'A la neuvième heure, Jésus cria d\'une voix forte: Eloï, Eloï, lamma sabachtani. — c\'est-à-dire: Mon Dieu, mon Dieu, pourquoi m\'as-tu abandonné?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 35, 'Quelques-uns de ceux qui étaient présents, l\'ayant entendu, disaient: Voyez, il appelle Élie!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 36, 'L\'un d\'eux courut remplir une éponge de vinaigre, la mit au bout d\'un roseau, et il lui offrit à boire en disant: Laissez; voyons si Élie viendra le faire descendre!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 37, 'Mais Jésus, ayant jeté un grand cri, expira.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 38, 'Alors le voile du temple se déchira en deux, depuis le haut jusqu\'en bas.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 39, 'Le centenier, qui se tenait en face de Jésus, l\'ayant vu expirer ainsi, dit: Cet homme était véritablement le Fils de Dieu!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 40, 'Il y avait aussi des femmes qui regardaient de loin. De ce nombre étaient Marié-Madeleine, Marie, Mère de Jacques le mineur et de Joses, et Salomé,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 41, 'qui le suivaient et le servaient, lorsqu\'il était en Galilée, ainsi que plusieurs autres qui étaient montées avec lui à Jérusalem.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 42, 'Le soir était déjà venu, et c\'était un jour de préparation, c\'est-à-dire la veille du sabbat.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 43, 'Alors arriva Joseph d\'Arimathée, membre considéré du Sanhédrin, et qui attendait, lui aussi, le royaume de Dieu. Il eut le courage de se présenter devant Pilate pour lui demander le corps de Jésus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 44, 'Pilate s\'étonna que Jésus fût mort si tôt; et, ayant appelé le centenier, il lui demanda s\'il y avait longtemps qu\'il était mort.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 45, 'Informé par le centenier, il accorda le corps à Joseph.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 46, 'Celui-ci, ayant acheté un linceul, descendit Jésus de la croix, l\'enveloppa dans ce linceul et le mit dans un tombeau qui était taillé dans le roc; puis il roula une pierre à l\'entrée du tombeau.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 47, 'Or, Marie-Madeleine et Marie, mère de Joses, regardaient où on le mettait.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 1, 'Quand le sabbat fut passé, Marie-Madeleine, Marie, mère de Jacques, et Salomé, achetèrent des aromates pour aller embaumer le corps de Jésus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 2, 'Le premier jour de la semaine, de grand matin, elles se rendirent au tombeau, comme le soleil venait de se lever.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 3, 'Elles se disaient entre elles: Qui nous roulera la pierre qui ferme l\'entrée du tombeau?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 4, 'Ayant regardé, elles virent que la pierre avait été roulée; or, elle était très grande.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 5, 'Puis, étant entrées dans le tombeau, elles virent un jeune homme assis du côté droit, vêtu d\'une robe blanche; et elles en furent épouvantées.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 6, 'Mais il leur dit: Ne vous effrayez point! Vous cherchez Jésus de Nazareth qui a été crucifié: il est ressuscité. Il n\'est pas ici; voici le lieu où on l\'avait mis.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 7, 'Mais allez dire à ses disciples et à Pierre que Jésus vous précède en Galilée; c\'est là que vous le verrez, comme il vous l\'a dit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 8, 'Elles sortirent du tombeau et s\'enfuirent; car elles étaient saisies de crainte et d\'étonnement. Et elles ne dirent rien à personne, tant elles étaient effrayées.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 9, '[Or, Jésus, étant ressuscité le matin du premier jour de la semaine, apparut premièrement à Marie-Madeleine, de laquelle il avait chassé sept démons.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 10, 'Elle alla porter la nouvelle à ceux qui avaient vécu avec lui, et qui étaient dans le deuil et dans les larmes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 11, 'Mais eux, lorsqu\'ils apprirent d\'elle qu\'il était vivant et qu\'elle l\'avait vu, ne la crurent point.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 12, 'Après cela, Jésus se montra sous une autre forme à deux d\'entre eux qui étaient en chemin pour aller à la campagne.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 13, 'Ceux-ci vinrent l\'annoncer aux autres disciples; mais ils ne les crurent pas non plus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 14, 'Plus tard, il se montra aux Onze, pendant qu\'ils étaient à table, et il leur reprocha leur incrédulité et la dureté de leur coeur, parce qu\'ils n\'avaient pas cru ceux qui l\'avaient vu ressuscité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 15, 'Puis il leur dit: Allez par tout le monde et prêchez l\'Evangile à toute créature.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 16, 'Celui qui croira et sera baptisé, sera sauvé; mais celui qui ne croira point sera condamné.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 17, 'Voici les miracles qui accompagneront ceux qui auront cru: ils chasseront des démons en mon nom; ils parleront des langues nouvelles;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 18, 'ils prendront des serpents dans leurs mains; quand ils auront bu quelque breuvage mortel, il ne leur fera point de mal; ils imposeront les mains aux malades, et ceux-ci seront guéris.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 19, 'Le Seigneur Jésus, après leur avoir ainsi parlé, fut enlevé au ciel, et il s\'assit à la droite de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 20, 'Pour eux, étant partis, ils prêchèrent en tous lieux. Le Seigneur agissait avec eux, et il confirmait la parole par les miracles qui l\'accompagnaient.]');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 1, 'Plusieurs ayant entrepris d\'écrire l\'histoire des faits accomplis parmi nous,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 2, '— tels que nous les ont transmis ceux qui en ont été, dès le commencement, les témoins oculaires, et qui sont devenus ministres de la Parole,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 3, '— j\'ai cru bon, moi aussi, très excellent Théophile, de te les exposer par écrit et dans leur ordre, après m\'être exactement informé de tout, depuis l\'origine,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 4, 'afin que tu reconnaisses la solidité des enseignements que tu as reçus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 5, 'Au temps d\'Hérode, roi de Judée, il y avait un sacrificateur nommé Zacharie, de la classe d\'Abia; sa femme était de la race d\'Aaron et s\'appelait Élisabeth.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 6, 'Ils étaient tous deux justes devant Dieu, et ils suivaient tous les commandements et toutes les prescriptions du Seigneur d\'une manière irréprochable.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 7, 'Ils n\'avaient point d\'enfants, parce qu\'Elisabeth était stérile; et ils étaient tous deux avancés en âge.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 8, 'Or, il arriva, comme Zacharie remplissait devant Dieu les fonctions du sacerdoce, suivant le rang de sa classe,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 9, 'qu\'il fut appelé par le sort, d\'après la coutume établie parmi les sacrificateurs, à entrer dans le sanctuaire du Seigneur pour y offrir le parfum.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 10, 'Toute la multitude du peuple était dehors en prière, à l\'heure où le parfum était offert.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 11, 'Alors un ange du Seigneur lui apparut, debout à droite de l\'autel des parfums.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 12, 'Zacharie, en le voyant, fut troublé, et la frayeur le saisit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 13, 'Mais l\'ange lui dit: Ne crains point, Zacharie; car ta prière a été exaucée. Elisabeth, ta femme, t\'enfantera un fils, et tu lui donneras le nom de Jean.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 14, 'Il sera pour toi un sujet de joie et d\'allégresse, et plusieurs se réjouiront de sa naissance.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 15, 'En effet, il sera grand devant le Seigneur; il ne boira ni vin ni cervoise, et il sera rempli du Saint-Esprit dès le sein de sa mère.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 16, 'Il convertira plusieurs des fils d\'Israël au Seigneur, leur Dieu;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 17, 'et lui-même marchera devant le Seigneur, dans l\'esprit et avec la puissance d\'Élie, pour ramener les coeurs des pères vers les enfants, et les rebelles à la sagesse des justes, afin de préparer au Seigneur un peuple bien disposé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 18, 'Zacharie dit à l\'ange: A quoi reconnaîtrai-je cela? Car je suis vieux, et ma femme est avancée en âge.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 19, 'L\'ange lui répondit: Je suis Gabriel, qui me tiens devant Dieu; j\'ai été envoyé pour te parler et t\'annoncer cette bonne nouvelle.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 20, 'Voici que tu vas devenir muet, et tu ne pourras parler jusqu\'au jour où ces choses arriveront, parce que tu n\'as pas cru à mes paroles, qui s\'accompliront en leur temps.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 21, 'Cependant, le peuple attendait Zacharie, et s\'étonnait de ce qu\'il s\'attardait dans le sanctuaire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 22, 'Quand il sortit, Zacharie ne pouvait leur parler; et ils comprirent qu\'il avait eu quelque vision dans le sanctuaire; il leur faisait des signes, et il demeura muet.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 23, 'Lorsque les jours de son ministère furent achevés, il retourna dans sa maison.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 24, 'Quelque temps après, Elisabeth sa femme, devint enceinte; elle se tint cachée durant cinq mois, et elle disait:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 25, 'Voilà ce que le Seigneur m\'a fait, quand il a jeté les yeux sur moi, pour ôter l\'opprobre qui pesait sur moi parmi les hommes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 26, 'Au sixième mois. Dieu envoya l\'ange Gabriel dans une ville de Galilée, appelée Nazareth,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 27, 'auprès d\'une vierge fiancée à un homme nommé Joseph, de la maison de David; cette vierge s\'appelait Marie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 28, 'L\'ange, étant entré dans le lieu où elle était, lui dit: Je te salue, toi qui as été comblée de grâces; le Seigneur est avec toi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 29, 'Elle fut troublée de ces paroles, et elle se demandait ce que signifiait cette salutation.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 30, 'Alors l\'ange lui dit: Ne crains point, Marie; car tu as trouvé grâce devant Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 31, 'Voici que tu enfanteras et mettras au monde un fils, à qui tu donneras le nom de Jésus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 32, 'Il sera grand, et il sera appelé le Fils du Très-Haut; et le Seigneur, Dieu, lui donnera le trône de David, son père.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 33, 'Il régnera éternellement sur la maison de Jacob, et son règne n\'aura pas de fin.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 34, 'Alors Marie dit à l\'ange: Comment cela arrivera-t-il, puisque je ne connais point d\'homme?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 35, 'L\'ange lui répondit: L\'Esprit saint viendra sur toi, et la puissance du Très-Haut te couvrira de son ombre; c\'est pourquoi aussi, le saint enfant qui naîtra sera appelé le Fils de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 36, 'Et voici qu\'Elisabeth, ta parente, a aussi conçu un fils en sa vieillesse; c\'est ici le sixième mois de celle qui était appelée stérile.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 37, 'Car rien n\'est impossible à Dieu!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 38, 'Marie répondit: Me voici: je suis la servante du Seigneur. Qu\'il me soit fait selon ta parole! Puis l\'ange la quitta.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 39, 'En ces jours-là, Marie, s\'étant levée, s\'empressa d\'aller dans le pays des montagnes, dans, une ville de Juda.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 40, 'Elle entra dans la maison de Zacharie, et salua Elisabeth.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 41, 'Or il arriva, quand Elisabeth eut entendu la salutation de Marie, que le petit enfant tressaillit dans son sein; et Elisabeth fut remplie du Saint-Esprit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 42, 'Alors élevant la voix, elle s\'écria: Tu es bénie entre les femmes, et le fruit de tes entrailles est béni.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 43, 'Et d\'où me vient cet honneur, que la mère de mon Seigneur vienne me visiter?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 44, 'Car ta voix, quand tu m\'as saluée, n\'a pas plus tôt frappé mes oreilles, que le petit enfant a tressailli de joie dans mon sein.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 45, 'Bienheureuse est celle qui a cru; car ce qui lui a été dit de la part du Seigneur aura son accomplissement!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 46, 'Alors Marie dit: Mon âme magnifie le Seigneur,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 47, 'et mon esprit se réjouit en Dieu, qui est mon Sauveur,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 48, 'parce qu\'il a jeté les yeux sur la bassesse de sa servante. Et voici que désormais tous les âges m\'appelleront bienheureuse;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 49, 'car le Tout-Puissant a fait pour moi de grandes choses. Son nom est saint,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 50, 'et sa miséricorde s\'étend d\'âge en âge sur ceux qui le craignent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 51, 'Il a manifesté la vigueur de son bras. Il a dissipé les desseins que les orgueilleux formaient dans leur coeur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 52, 'Il a renversé de leurs trônes les puissants, et il a élevé les humbles.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 53, 'Il a comblé de biens les affamés, et il a renvoyé les riches les mains vides.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 54, 'Il est venu au secours d\'Israël, son serviteur, et il s\'est souvenu de sa miséricorde');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 55, '— ainsi qu\'il en avait parlé à nos pères — à l\'égard d\'Abraham et de sa postérité, pour toujours.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 56, 'Marie demeura avec Elisabeth environ trois mois; puis elle s\'en retourna dans sa maison.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 57, 'Cependant, le terme d\'Elisabeth étant venu, elle enfanta un fils.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 58, 'Ses voisins et ses parents, ayant appris que le Seigneur avait fait éclater en elle la grandeur de sa miséricorde, s\'en réjouissaient avec elle.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 59, 'Le huitième jour, ils vinrent pour circoncire l\'enfant; ils l\'appelaient Zacharie, du nom de son père.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 60, 'Mais sa mère dit: Non! Il sera nommé Jean.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 61, 'Ils lui dirent: Il n\'y a personne dans ta famille qui soit appelé de ce nom.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 62, 'Alors ils demandèrent au père, par signes, comment il voulait que l\'enfant fût nommé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 63, 'Zacharie ayant demandé des tablettes, écrivit: Jean est son nom. Et ils furent tous surpris.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 64, 'A l\'instant sa bouche s\'ouvrit, sa langue se délia, et il parlait, bénissant Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 65, 'Tous leurs voisins furent remplis de crainte, et l\'on s\'entretenait de toutes ces choses dans tout le pays des montagnes de la Judée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 66, 'Tous ceux qui les entendirent les conservèrent dans leur coeur et ils disaient: Que deviendra donc ce petit enfant? Car la main du Seigneur était avec lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 67, 'Alors Zacharie, son père, fut rempli de l\'Esprit saint. Il prophétisa et il dit:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 68, 'Béni soit le Seigneur, le Dieu d\'Israël, de ce qu\'il a visité et racheté son peuple,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 69, 'et nous a suscité un puissant Sauveur dans la maison de David, son serviteur,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 70, 'comme il l\'avait proclamé par la bouche de ses saints prophètes, dès les anciens temps.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 71, 'Il nous délivre de nos ennemis et de la main de tous ceux qui nous haïssent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 72, 'Il exerce sa miséricorde envers nos pères et se souvient de sa sainte alliance;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 73, 'car il a fait à Abraham, notre père, le serment de nous accorder cette grâce,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 74, 'qu\'après avoir été délivrés de la main de nos ennemis, nous pourrions le servir sans crainte,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 75, 'en sa présence, dans la sainteté et la justice, tous les jours de notre vie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 76, 'Et toi, petit enfant, tu seras appelé le prophète du Très-Haut; car tu marcheras devant la face du Seigneur, pour préparer ses voies,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 77, 'pour donner à son peuple la connaissance du salut par la rémission de ses péchés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 78, 'Les entrailles de la miséricorde de notre Dieu se sont émues, et le soleil levant nous a visités d\'en haut,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 79, 'pour éclairer ceux qui sont assis dans les ténèbres et l\'ombre de la mort, et pour conduire nos pas dans le chemin de la paix.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 80, 'Or, le petit enfant grandissait et se fortifiait en esprit; et il demeura dans les déserts jusqu\'au jour de sa manifestation à Israël.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 1, 'En ce temps-là, on publia un édit de la part de César Auguste, ordonnant un recensement de toute la terre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 2, 'Ce recensement fut le premier et eut lieu pendant que Quirinius était gouverneur de Syrie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 3, 'Et tous allaient se faire enregistrer, chacun dans sa ville.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 4, 'Joseph aussi monta de la Galilée en Judée, de la ville de Nazareth à la ville de David, nommée Bethléhem, — parce qu\'il était de la maison et de la famille de David, —');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 5, 'pour se faire enregistrer avec Marie, son épouse, qui était enceinte.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 6, 'Pendant qu\'ils étaient là, le jour où elle devait accoucher arriva.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 7, 'Elle mit au monde son fils premier-né, l\'emmaillota et le coucha dans une crèche, parce qu\'il n\'y avait point de place pour eux dans l\'hôtellerie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 8, 'Or, il y avait dans la même contrée des bergers, qui couchaient dans les champs et gardaient leurs troupeaux pendant les veilles de la nuit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 9, 'Un ange du Seigneur se présenta à eux; la gloire du Seigneur resplendit autour d\'eux, et ils furent saisis d\'une grande crainte.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 10, 'Alors l\'ange leur dit: Ne craignez point! Car voici que je vous annonce une bonne nouvelle, qui sera pour tout le peuple la cause d\'une grande joie:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 11, 'c\'est qu\'aujourd\'hui, dans la ville de David, un Sauveur, qui est le Christ, le Seigneur, vous est né.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 12, 'Et vous le reconnaîtrez à ce signe: vous trouverez un petit enfant emmailloté et couché dans une crèche.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 13, 'Et tout à coup, il y eut avec l\'ange une multitude de l\'armée céleste, louant Dieu et disant:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 14, 'Gloire à Dieu au plus haut des cieux, paix sur la terre, bienveillance envers les hommes!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 15, 'Après que les anges les eurent quittés pour retourner au ciel, les bergers se dirent les uns aux autres: Allons jusqu\'à Bethléhem; voyons ce qui est arrivé, ce que le Seigneur nous a fait connaître.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 16, 'Ils s\'empressèrent donc d\'y aller, et ils trouvèrent Marie, Joseph, et le petit enfant qui était couché dans la crèche.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 17, 'Après l\'avoir vu, ils publièrent ce qui leur avait été dit de cet enfant.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 18, 'Tous ceux qui les entendirent étaient dans l\'admiration de ce que les bergers leur disaient.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 19, 'Et Marie conservait toutes ces paroles et les repassait dans son coeur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 20, 'Les bergers s\'en retournèrent, glorifiant et louant Dieu de tout ce qu\'ils avaient entendu et vu, conformément à ce qui leur avait été dit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 21, 'Quand fut arrivé le huitième jour où l\'on devait circoncire l\'enfant, on lui donna le nom de Jésus, nom qui lui avait été donné par l\'ange avant qu\'il fût conçu dans le sein de sa mère.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 22, 'Lorsque furent achevés les jours de leur purification selon la loi de Moïse, ils portèrent l\'enfant à Jérusalem, pour le présenter au Seigneur,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 23, '— ainsi qu\'il est écrit dans la loi du Seigneur: «Tout mâle premier-né sera consacré au Seigneur» —');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 24, 'et pour offrir le sacrifice prescrit dans la loi du Seigneur: une paire de tourterelles ou deux pigeonneaux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 25, 'Or, il y avait à Jérusalem un homme qui s\'appelait Siméon. Cet homme était juste et pieux; il attendait la consolation d\'Israël, et l\'Esprit saint reposait sur lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 26, 'Il avait été averti divinement par le Saint-Esprit qu\'il ne verrait point la mort avant d\'avoir vu l\'Oint du Seigneur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 27, 'Il vint donc au temple, poussé par l\'Esprit; et comme les parents apportaient l\'enfant Jésus, pour accomplir à son égard les prescriptions ordinaires de la loi,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 28, 'il le prit dans ses bras, bénit Dieu et dit:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 29, 'Maintenant, Seigneur, tu laisses aller ton serviteur en paix, selon ta parole;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 30, 'car mes yeux ont vu ton salut,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 31, 'que tu as préparé pour être, à la face de tous les peuples,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 32, 'la lumière qui doit éclairer les nations et la gloire de ton peuple d\'Israël.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 33, 'Son père et sa mère admiraient ce qu\'on disait de lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 34, 'Et Siméon les bénit, et dit à Marie, sa mère: Voici que cet enfant est destiné à être une cause de chute et de relèvement pour plusieurs en Israël, et un signe qui provoquera la contradiction;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 35, 'à toi-même, une épée te transpercera l\'âme. C\'est ainsi que les pensées du coeur de plusieurs seront dévoilées.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 36, 'Il y avait aussi une prophétesse, Anne, fille de Phanuel, de la tribu d\'Asser, qui était fort avancée en âge. Après avoir vécu, depuis sa virginité, sept ans avec son mari,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 37, 'elle était restée veuve. Elle était alors âgée de quatre-vingt-quatre ans, et ne sortait point du temple, servant Dieu nuit et jour dans les jeûnes et les prières.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 38, 'Elle aussi, étant survenue en ce même instant, louait Dieu, et elle parlait de l\'enfant à tous ceux qui attendaient la délivrance de Jérusalem.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 39, 'Après qu\'ils eurent tout accompli selon la loi du Seigneur, ils retournèrent en Galilée, à Nazareth, leur ville.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 40, 'Le petit enfant grandissait et se fortifiait; il était rempli de sagesse, et la grâce de Dieu était sur lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 41, 'Les parents de Jésus allaient tous les ans à Jérusalem, à la fête de Pâque.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 42, 'Quand il eut atteint l\'âge de douze ans, ils montèrent à Jérusalem, selon la coutume de la fête.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 43, 'Les jours de la fête étant passés, comme ils s\'en retournaient, l\'enfant Jésus demeura à Jérusalem, et ses parents ne s\'en aperçurent point.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 44, 'Pensant qu\'il était avec leurs compagnons de route, ils marchèrent toute une journée, et ils le cherchaient parmi leurs parents et ceux de leur connaissance;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 45, 'mais, ne l\'ayant pas trouvé, ils retournèrent à Jérusalem pour le chercher.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 46, 'Au bout de trois jours, ils le trouvèrent dans le temple, assis au milieu des docteurs, les écoutant et leur posant des questions;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 47, 'et tous ceux qui l\'entendaient étaient ravis de son intelligence et de ses réponses.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 48, 'En le voyant, ils furent étonnés; et sa mère lui dit: Mon enfant, pourquoi as-tu agi de la sorte avec nous? Voici que ton père et moi nous te cherchions, étant fort en peine.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 49, 'Et il leur dit: Pourquoi me cherchiez-vous? Ne saviez-vous pas qu\'il me faut être occupé des affaires de mon Père?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 50, 'Mais eux ne comprirent pas ce qu\'il leur disait.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 51, 'Il s\'en alla ensuite avec eux et vint à Nazareth; et il leur était soumis. Sa mère conservait toutes ces paroles dans son coeur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 52, 'Jésus croissait en sagesse, en stature et en grâce, devant Dieu et devant les hommes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 1, 'La quinzième année du règne de Tibère César, — Ponce Pilate étant gouverneur de la Judée, Hérode tétrarque de la Galilée, Philippe, son frère, tétrarque de l\'Iturée et de la province de la Trachonite, et Lysanias tétrarque de l\'Abylène,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 2, 'Anne et Caïphe étant souverains sacrificateurs, — la parole de Dieu fut adressée à Jean, fils de Zacharie, dans le désert.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 3, 'Alors Jean parcourut toute la contrée voisine du Jourdain, prêchant le baptême de la repentance, pour la rémission des péchés,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 4, 'ainsi qu\'il est écrit dans le livre des paroles du prophète Ésaïe: «Une voix crie dans le désert: Préparez le chemin du Seigneur; aplanissez ses sentiers.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 5, 'Toute vallée sera comblée, toute montagne et toute colline seront abaissées; les chemins tortueux seront redressés, les chemins raboteux seront aplanis;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 6, 'et toute créature verra le salut de Dieu.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 7, 'Il disait donc à la foule qui venait pour être baptisée par lui: Race de vipères, qui vous a appris à fuir la colère à venir?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 8, 'Produisez donc des fruits dignes d\'une vraie repentance! Et n\'allez pas dire en vous-mêmes: Nous avons Abraham pour père. Car je vous dis que, de ces pierres. Dieu peut faire naître des enfants à Abraham.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 9, 'Déjà la cognée est mise à la racine des arbres. Tout arbre qui ne produit pas de bons fruits va être coupé et jeté au feu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 10, 'Alors la foule lui demanda: Que ferons-nous donc?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 11, 'Il leur répondit: Que celui qui a deux tuniques, en donne une à celui qui n\'en a point; et que celui qui a de quoi manger agisse de même.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 12, 'Il vint aussi des péagers pour être baptisés; et ils lui dirent: Maître, que ferons-nous?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 13, 'Il leur répondit: N\'exigez rien au delà de ce qui vous est ordonné.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 14, 'Des gens de guerre lui demandèrent aussi: Et nous, que ferons-nous? Il leur répondit: N\'usez ni de violence ni de fraude envers personne; mais contentez-vous de votre solde.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 15, 'Comme le peuple était dans l\'attente, et que tous se demandaient en leur coeur si Jean ne serait pas le Christ,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 16, 'Jean, prenant la parole, dit à tous: Pour moi, je vous baptise d\'eau; mais il vient, celui qui est plus puissant que moi! Je ne suis pas digne de délier la courroie de ses chaussures; c\'est lui qui vous baptisera d\'Esprit saint et de feu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 17, 'Il a son van dans sa main, il nettoiera parfaitement son aire et amassera le froment dans son grenier; mais il brûlera la paille au feu qui ne s\'éteint point.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 18, 'Il adressait encore plusieurs autres exhortations au peuple, en lui annonçant la bonne nouvelle.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 19, 'Mais Hérode le tétrarque, étant repris par Jean au sujet d\'Hérodias, femme de son frère, et au sujet de tous les crimes qu\'il avait commis,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 20, 'ajouta encore à tous les autres celui de faire mettre Jean en prison.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 21, 'Or, comme tout le peuple se faisait baptiser, Jésus se fit baptiser, lui aussi. Pendant qu\'il priait, le ciel s\'ouvrit,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 22, 'et le Saint-Esprit descendit sur lui, sous une forme corporelle, comme une colombe; et il vint du ciel une voix qui dit: Tu es mon Fils bien-aimé, en qui j\'ai mis toute mon affection!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 23, 'Jésus avait environ trente ans, lorsqu\'il commença son ministère. Il était, à ce que l\'on croyait, fils de Joseph, fils d\'Héli,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 24, 'fils de Matthat, fils de Lévi, fils de Melchi, fils de Janné, fils de Joseph,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 25, 'fils de Mattathias, fils d\'Amos, fils de Nahum, fils d\'Esli, fils de Naggé,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 26, 'fils de Maath, fils de Mattathias, fils de Siméin, fils de Josech, fils de Joda,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 27, 'fils de Joanan, fils de Rhésa, fils de Zorobabel, fils de Salathiel, fils de Néri,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 28, 'fils de Melchi, fils d\'Addi, fils de Cosam, fils d\'Elmadam, fils d\'Er,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 29, 'fils de Jésus, fils d\'Éliézer, fils de Jorim, fils de Matthat, fils de Lévi,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 30, 'fils de Siméon, fils de Juda, fils de Joseph, fils de Jonam, fils d\'Éliakim,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 31, 'fils de Méléa, fils de Menna, fils de Mattatha, fils de Nathan, fils de David,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 32, 'fils de Jessé, fils de Jobed, fils de Booz, fils de Sala, fils de Naasson,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 33, 'fils d\'Aminadab, fils d\'Admin, fils d\'Arni, fils d\'Esrom, fils de Pharez, fils de Juda,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 34, 'fils de Jacob, fils d\'Isaac, fils d\'Abraham, fils de Thara, fils de Nachor,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 35, 'fils de Séruch, fils de Ragaù, fils de Phalek, fils de Héber, fils de Sala,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 36, 'fils de Caïnam, fils d\'Arphaxad, fils de Sem, fils de Noé, fils de Lamech,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 37, 'fils de Mathusala, fils d\'Hénoch, fils de Jared, fils de Maléléel, fils de Caïnam,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 38, 'fils d\'Énos, fils de Seth, fils d\'Adam, fils de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 1, 'Jésus, rempli de l\'Esprit saint, revint des bords du Jourdain, et il fut conduit par l\'Esprit dans le désert,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 2, 'où il fut tenté par le Diable pendant quarante jours. Il ne mangea rien durant ces jours-là; et, après qu\'ils furent passés, il eut faim.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 3, 'Alors le Diable lui dit: Si tu es le fils de Dieu, dis à cette pierre qu\'elle devienne du pain.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 4, 'Jésus lui répondit: Il est écrit: «L\'homme ne vivra pas seulement de pain.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 5, 'Le Diable, l\'ayant emmené, lui fit voir en un instant tous les royaumes du monde;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 6, 'et il lui dit: Je te donnerai toute cette puissance et la gloire de ces royaumes; car elle m\'a été donnée, et je la donne à qui je veux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 7, 'Si donc tu te prosternes devant moi, toutes ces choses seront à toi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 8, 'Jésus lui répondit: Il est écrit: «Tu adoreras le Seigneur, ton Dieu, et tu ne rendras de culte qu\'à lui seul.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 9, 'Le Diable le conduisit à Jérusalem, et l\'ayant placé sur le faîte du temple, il lui dit: Si tu es le Fils de Dieu, jette-toi d\'ici en bas;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 10, 'car il est écrit: «Il donnera des ordres à ses anges, pour qu\'ils te gardent;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 11, 'et ils te porteront dans leurs mains, de peur que ton pied ne heurte contre quelque pierre.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 12, 'Jésus lui répondit: Il est dit: «Tu ne tenteras point le Seigneur, ton Dieu.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 13, 'Et le Diable, ayant achevé de le tenter de toute manière, se retira de lui jusqu\'à une autre occasion.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 14, 'Jésus s\'en retourna en Galilée, avec la puissance de l\'Esprit, et sa renommée se répandit dans tout le pays d\'alentour.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 15, 'Il enseignait dans les synagogues, et il était glorifié par tous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 16, 'Il vint à Nazareth, où il avait été élevé. Selon sa coutume, il entra le jour du sabbat dans la synagogue et il se leva pour lire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 17, 'On lui présenta le livre du prophète Ésaïe; et, ayant ouvert le livre, il trouva l\'endroit où il était écrit:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 18, '«L\'Esprit du Seigneur est sur moi; c\'est pourquoi il m\'a oint pour annoncer la bonne nouvelle aux pauvres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 19, 'Il m\'a envoyé pour publier la liberté aux captifs et le recouvrement de la vue aux aveugles, pour renvoyer libres ceux qui sont dans l\'oppression, et pour proclamer l\'année favorable du Seigneur.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 20, 'Puis il ferma le livre, le rendit au serviteur, et il s\'assit; et les yeux de tous dans la synagogue étaient fixés sur lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 21, 'Alors il se mit à leur dire: Aujourd\'hui est accomplie cette parole de l\'Écriture que vous venez d\'entendre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 22, 'Tous lui rendaient témoignage; ils admiraient les paroles pleines de grâce qui sortaient de sa bouche, et ils disaient: N\'est-ce pas le fils de Joseph?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 23, 'Il leur dit: Sans doute, vous me citerez ce proverbe: Médecin, guéris-toi toi-même; tout ce que nous avons entendu dire que tu as fait à Capernaüm, fais-le également ici, dans ta patrie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 24, 'Et il ajouta: En vérité, je vous le dis, aucun prophète n\'est bien reçu dans sa patrie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 25, 'Oui, en vérité, je vous le déclare, il y avait plusieurs veuves en Israël au temps d\'Élie, lorsque le ciel fut fermé pendant trois ans et six mois, et qu\'il y eut une grande famine dans tout le pays.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 26, 'Cependant, Élie ne fut envoyé chez aucune d\'elles; mais il fut envoyé à Sarepta, dans le pays de Sidon, chez une femme qui était veuve.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 27, 'Il y avait aussi plusieurs lépreux en Israël, au temps d\'Elisée, le prophète. Toutefois, aucun d\'eux ne fut guéri; mais Naaman le fut, lui qui était Syrien.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 28, 'Tous, dans la synagogue, furent remplis de colère, en entendant ces choses.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 29, 'Et, s\'étant levés, ils l\'entraînèrent hors de la ville et le menèrent jusqu\'au sommet de la montagne sur laquelle leur ville était bâtie, pour le jeter en bas.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 30, 'Mais lui, passant au milieu d\'eux, s\'en alla.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 31, 'Il descendit à Capernaüm, ville de Galilée, et il y enseignait le jour du sabbat.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 32, 'Tous étaient frappés de son enseignement; car il parlait avec autorité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 33, 'Or, il se trouvait dans la synagogue un homme possédé de l\'esprit d\'un démon impur, et il s\'écria à haute voix:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 34, 'Ah! qu\'y a-t-il entre nous et toi, Jésus de Nazareth? Es-tu venu pour nous perdre? Je sais qui tu es: le Saint de Dieu!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 35, 'Mais Jésus le reprit sévèrement et lui dit: Tais-toi, et sors de cet homme. Alors le démon, après l\'avoir jeté au milieu de l\'assemblée, sortit de lui, sans lui faire aucun mal.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 36, 'Ils furent tous dans l\'étonnement, et ils disaient entre eux: Quelle est donc cette parole? Il commande avec autorité et avec puissance aux esprits impurs, et ils s\'enfuient!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 37, 'Et sa renommée se répandit dans toute la région environnante.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 38, 'Jésus, sortant de la synagogue, entra dans la maison de Simon. La belle-mère de Simon avait une fièvre violente, et on le pria de la guérir.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 39, 'S\'étant penché sur elle, il commanda à la fièvre, et la fièvre la quitta. Aussitôt elle se leva et se mit à les servir.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 40, 'Quand le soleil fut couché, tous ceux qui avaient des malades atteints de divers maux les lui amenèrent; et il les guérit en imposant les mains à chacun d\'eux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 41, 'Les démons sortaient aussi de plusieurs, en criant: Tu es le Christ, le Fils de Dieu! Mais il les reprenait sévèrement, et il ne leur permettait pas de dire qu\'ils savaient qu\'il était le Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 42, 'Dès que le jour parut, il sortit et alla dans un lieu écarté; et une foule de gens se mirent à sa recherche. Ils parvinrent jusqu\'à lui, et ils le retenaient, ne voulant pas le laisser partir.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 43, 'Mais il leur dit: Il faut que j\'annonce aussi aux autres villes la bonne nouvelle du royaume de Dieu; car, c\'est pour cela que j\'ai été envoyé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 44, 'Et il prêchait dans les synagogues de la Galilée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 1, 'Comme Jésus était sur le bord du lac de Génézareth, la foule se pressait autour de lui pour entendre la parole de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 2, 'Il vit deux barques arrêtées près du rivage; les pêcheurs en étaient descendus pour laver leurs filets.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 3, 'Il monta dans l\'une de ces barques, qui appartenait à Simon, et il le pria de s\'éloigner un peu du bord; puis il s\'assit, et de là il enseignait la foule.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 4, 'Quand il eut cessé de parler, il dit à Simon: Avance en pleine eau, et jetez vos filets pour pêcher.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 5, 'Simon lui répondit: Maître, nous avons travaillé toute la nuit sans rien prendre; mais, sur ta parole, je jetterai le filet.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 6, 'L\'ayant jeté, ils prirent une si grande quantité de poissons que leur filet se rompait.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 7, 'Alors ils firent signe à leurs compagnons, qui étaient dans l\'autre barque, de venir les aider; ceux-ci vinrent, et ils remplirent les deux barques, tellement qu\'elles enfonçaient.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 8, 'Simon Pierre, ayant vu cela, se jeta aux genoux de Jésus, et il lui dit: Seigneur, retire-toi de moi; car je suis un homme pécheur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 9, 'En effet, la frayeur l\'avait saisi, ainsi que tous ceux qui étaient avec lui, à cause de la pêche qu\'ils avaient faite et des poissons qu\'ils avaient pris.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 10, 'Il en était de même de Jacques et de Jean, fils de Zébédée, qui étaient compagnons de Simon. Alors Jésus dit à Simon: Ne crains point; désormais, tu seras pêcheur d\'hommes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 11, 'Puis, après avoir ramené les barques à terre, ils quittèrent tout et le suivirent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 12, 'Comme Jésus était dans une ville, un homme tout couvert de lèpre, l\'ayant vu, se jeta le visage contre terre et lui adressa, tout suppliant, ces paroles: Seigneur, si tu le veux, tu peux me rendre net!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 13, 'Jésus étendit la main, le toucha et dit: Je le veux, sois net! Au même instant, la lèpre le quitta.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 14, 'Jésus lui défendit de le dire à personne. Mais va, — lui dit-il, — montre-toi au sacrificateur, et offre pour ta purification ce que Moïse a prescrit, afin que cela leur serve de témoignage.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 15, 'Sa renommée se répandait de plus en plus, et une foule de gens se rassemblaient pour l\'entendre et pour être guéris de leurs maladies.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 16, 'Mais lui se retirait dans les déserts, et il priait.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 17, 'Un jour que Jésus enseignait, des pharisiens et des docteurs de la loi, venus de tous les villages de la Galilée, de la Judée et de Jérusalem, s\'étaient assis près de lui; et la puissance du Seigneur lui faisait opérer des guérisons.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 18, 'Alors il survint des gens qui portaient sur un lit un paralytique, et ils cherchaient à le faire entrer et à le mettre devant Jésus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 19, 'Comme ils ne savaient par où le faire passer, à cause de la foule, ils montèrent sur le toit; et, ayant enlevé les tuiles, ils le descendirent avec son petit lit, au milieu de l\'assemblée, devant Jésus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 20, 'Voyant leur foi, Jésus dit: Mon ami, tes péchés te sont pardonnés!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 21, 'Alors les scribes et les pharisiens se mirent à raisonner et à dire: Quel est celui-ci, qui profère des blasphèmes? Qui peut pardonner les péchés, que Dieu seul?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 22, 'Mais Jésus, connaissant leurs pensées, prit la parole et leur dit: Quel raisonnement faites-vous dans vos coeurs?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 23, 'Lequel est le plus aisé, de dire: Tes péchés te sont pardonnés; ou de dire: Lève-toi et marche?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 24, 'Or, afin que vous sachiez que le Fils de l\'homme a sur la terre le pouvoir de pardonner les péchés: Je te l\'ordonne, — dit-il au paralytique, — lève-toi, emporte ton lit, et va dans ta maison.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 25, 'Et à l\'instant, le paralytique se leva en leur présence. Il emporta le lit sur lequel il avait été couché et s\'en alla dans sa maison, donnant gloire à Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 26, 'Tous furent transportés d\'enthousiasme; ils glorifiaient Dieu, et, remplis de crainte, ils disaient: Nous avons vu aujourd\'hui des choses extraordinaires!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 27, 'Après cela, Jésus sortit; et il vit un péager, nommé Lévi, assis au bureau du péage. Il lui dit: Suis-moi!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 28, 'Et Lévi, quittant tout, se leva et le suivit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 29, 'Lévi lui donna un grand festin dans sa maison, et un grand nombre de péagers et d\'autres personnes étaient à table avec eux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 30, 'Les pharisiens et leurs scribes murmuraient et disaient à ses disciples: Pourquoi mangez-vous et buvez-vous avec des péagers et des pécheurs?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 31, 'Jésus, prenant la parole, leur dit: Ce ne sont pas ceux qui sont en bonne santé qui ont besoin de médecin, mais ceux qui se portent mal.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 32, 'Je ne suis pas venu appeler à la repentance les justes, mais les pécheurs.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 33, 'Ils lui dirent: Les disciples de Jean jeûnent souvent et font des prières, de même que ceux des pharisiens, au lieu que les tiens mangent et boivent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 34, 'Il leur répondit: Pouvez-vous faire jeûner les amis de l\'époux, pendant que l\'époux est avec eux?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 35, 'Les jours viendront où l\'époux leur sera ôté; alors ils jeûneront dans ces jours-là!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 36, 'Il leur dit encore cette parabole: Personne n\'enlève une pièce à un vêtement neuf pour la mettre à un vieux vêtement. Autrement, on déchire le vêtement neuf sans que la pièce neuve s\'accorde avec le vêtement vieux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 37, 'De même, personne ne met du vin nouveau dans de vieilles outres; autrement, le vin nouveau rompra les outres; il se répandra, et les outres seront perdues.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 38, 'Mais le vin nouveau doit être mis dans des outres neuves.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 39, 'De même aussi, celui qui boit du vin vieux ne demande pas du vin nouveau; car il dit: C\'est le vieux qui est bon.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 1, 'Un jour de sabbat, Jésus passant par des blés, ses disciples arrachaient des épis, les froissaient entre leurs mains, et ils les mangeaient.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 2, 'Quelques-uns des pharisiens leur dirent: Pourquoi faites-vous ce qu\'il n\'est pas permis de faire le jour du sabbat?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 3, 'Jésus, prenant la parole, leur dit: N\'avez-vous donc pas lu ce que fit David, lorsqu\'il eut faim, lui et ceux qui étaient avec lui?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 4, 'Comment il entra dans la maison de Dieu, prit les pains de proposition, en mangea et en donna à ceux qui étaient avec lui, bien qu\'il ne soit permis qu\'aux seuls sacrificateurs d\'en manger?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 5, 'Et il leur dit: Le Fils de l\'homme est maître même du sabbat.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 6, 'Un autre jour de sabbat, Jésus entra dans la synagogue, et il se mit à enseigner. Il y avait là un homme dont la main droite était desséchée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 7, 'Or, les scribes et les pharisiens observaient Jésus pour voir s\'il ferait une guérison le jour du sabbat, afin de trouver l\'occasion de l\'accuser.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 8, 'Mais comme il connaissait leurs pensées, il dit à l\'homme qui avait la main desséchée: Lève-toi, et tiens-toi debout au milieu de nous! Et lui, s\'étant levé, se tint debout.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 9, 'Jésus leur dit: Est-il permis, le jour du sabbat, de faire du bien ou de faire du mal, de sauver une personne ou de la faire périr?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 10, 'Puis, ayant porté ses regards sur tous ceux qui étaient autour de lui, il dit à l\'homme: Étends ta main. Il le fit, et sa main redevint saine.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 11, 'Mais eux furent remplis de fureur; et ils s\'entretenaient ensemble de ce qu\'ils pourraient faire à Jésus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 12, 'En ce temps-là, Jésus alla sur la montagne pour prier; et il passa toute la nuit à prier Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 13, 'Quand le jour fut venu, il appela ses disciples, et il en choisit douze auxquels il donna le nom d\'apôtres:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 14, 'Simon, qu\'il nomma Pierre, et André, son frère; Jacques et Jean; Philippe et Barthélémy;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 15, 'Matthieu et Thomas; Jacques, fils d\'Alphée, et Simon, appelé Zélote;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 16, 'Jude, fils de Jacques, et Judas Iscariote, celui qui le trahit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 17, 'Ensuite, étant descendu avec eux, il s\'arrêta sur un plateau. Là, se trouvaient un grand nombre de ses disciples et une grande multitude de gens, qui étaient venus de toute la Judée et de Jérusalem, ainsi que du littoral de Tyr et de Sidon, pour l\'entendre et pour être guéris de leurs maladies.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 18, 'Ceux qui étaient tourmentés par des esprits impurs étaient aussi guéris.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 19, 'Toute la multitude cherchait à le toucher, parce qu\'il sortait de lui une force qui les guérissait tous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 20, 'Alors levant les yeux sur ses disciples, Jésus dit: Heureux, vous qui êtes pauvres, parce que le royaume de Dieu est à vous!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 21, 'Heureux, vous qui avez faim maintenant, parce que vous serez rassasiés! Heureux, vous qui pleurez maintenant, parce que vous serez dans la joie!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 22, 'Vous serez heureux, lorsque les hommes vous haïront, qu\'ils vous chasseront, qu\'ils vous diront des outrages et rejetteront votre, nom comme infâme, à cause du Fils de l\'homme!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 23, 'Réjouissez-vous en ce jour-là, et tressaillez de joie, parce que votre récompense sera grande dans le ciel; car c\'est ainsi que leurs pères traitaient les prophètes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 24, 'Mais malheur à vous, riches, parce que vous avez déjà reçu votre consolation!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 25, 'Malheur à vous qui êtes rassasiés maintenant, parce que vous aurez faim! Malheur à vous qui riez maintenant, parce que vous serez dans le deuil et dans les larmes!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 26, 'Malheur à vous, lorsque tous les hommes diront du bien de vous; car leurs pères faisaient de même à l\'égard des faux prophètes!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 27, 'Mais je vous dis, à vous qui m\'écoutez: Aimez vos ennemis, faites du bien à ceux qui vous haïssent,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 28, 'bénissez ceux qui vous maudissent, priez pour ceux qui vous outragent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 29, 'A celui qui te frappe sur une joue, présente aussi l\'autre; et si quelqu\'un t\'enlève ton manteau, ne l\'empêche pas de prendre aussi ta tunique.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 30, 'Donne à tout homme qui te demande, et si quelqu\'un t\'enlève ce qui est à toi, ne le réclame pas.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 31, 'Ce que vous voulez que les hommes vous fassent, faites-le-leur aussi de même.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 32, 'Si vous aimez ceux qui vous aiment, quel gré vous en saura-t-on? Les pécheurs aussi aiment ceux qui les aiment!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 33, 'Et si vous faites du bien à ceux qui vous font du bien, quel gré vous en saura-t-on? Les pécheurs font la même chose.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 34, 'Et si vous prêtez à ceux de qui vous espérez recevoir, quel gré vous en saura-t-on? Les pécheurs aussi prêtent aux pécheurs, afin de recevoir la pareille!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 35, 'Mais vous, aimez vos ennemis; faites du bien, et prêtez sans rien espérer en retour. Votre récompense sera grande, et vous serez les fils du Très-Haut, parce qu\'il est bon pour les ingrats et les méchants.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 36, 'Soyez miséricordieux, comme votre Père est miséricordieux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 37, 'Ne jugez point, et vous ne serez pas jugés; ne condamnez point, et vous ne serez pas condamnés; pardonnez, et on vous pardonnera.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 38, 'Donnez, et on vous donnera: on versera dans votre sein une bonne mesure, pressée, secouée, débordante; car on se servira pour vous de la mesure avec laquelle vous mesurez.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 39, 'Il leur dit aussi une parabole: Un aveugle peut-il conduire un aveugle? Ne tomberont-ils pas tous les deux dans la fosse?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 40, 'Le disciple n\'est pas au-dessus de son maître; mais tout disciple accompli sera comme son maître.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 41, 'Pourquoi regardes-tu la paille qui est dans l\'oeil de ton frère, et n\'aperçois-tu pas la poutre qui est dans ton oeil?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 42, 'Comment peux-tu dire à ton frère: Frère, laisse-moi ôter la paille qui est dans ton oeil, — toi qui ne vois pas la poutre qui est dans le tien? Hypocrite, ôte premièrement la poutre de ton oeil, et alors tu verras à ôter la paille qui est dans l\'oeil de ton frère.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 43, 'L\'arbre qui produit de mauvais fruits n\'est pas bon, et l\'arbre qui produit de bons fruits n\'est pas mauvais;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 44, 'car chaque arbre se reconnaît à son propre fruit. On ne cueille pas des figues sur des épines, et on ne récolte pas des raisins sur des ronces.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 45, 'L\'homme de bien tire le bien du bon trésor de son coeur, mais le méchant tire le mal de son mauvais trésor; car de l\'abondance du coeur la bouche parle.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 46, 'Pourquoi m\'appelez-vous: Seigneur, Seigneur, et ne faites-vous pas ce que je dis?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 47, 'Je vais vous montrer à qui ressemble tout homme qui vient à moi, qui entend mes paroles et qui les met en pratique.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 48, 'Il est semblable à un homme qui, bâtissant une maison, a creusé profondément la terre, et en a posé les fondements sur le roc: les eaux ont débordé, le torrent s\'est précipité avec violence contre cette maison, mais il n\'a pu l\'ébranler, parce qu\'elle avait été bien construite.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 49, 'Mais celui qui entend et ne met pas en pratique, est semblable à un homme qui a bâti sa maison sur la terre, sans fondements: le torrent a donné contre elle avec violence, et aussitôt elle est tombée; et la ruine de cette maison a été grande.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 1, 'Après que Jésus eut achevé de prononcer toutes ces paroles devant le peuple qui l\'écoutait, il entra dans Capernaüm.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 2, 'Or, un centenier avait un serviteur malade et près de mourir, qui lui était très cher.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 3, 'Ayant entendu parler de Jésus, il lui envoya quelques anciens des Juifs, pour le prier de venir guérir son serviteur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 4, 'Ceux-ci, étant arrivés auprès de Jésus, le priaient avec instance, en disant: Il est digne que tu lui accordes cela;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 5, 'car il aime notre nation, et c\'est lui qui nous a fait bâtir la synagogue.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 6, 'Alors Jésus s\'en alla avec eux. Comme il approchait déjà de la maison, le centenier envoya des amis, pour lui dire: Seigneur, ne te donne pas tant de peine; car je ne mérite pas que tu entres sous mon toit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 7, 'Aussi ne me suis-je pas même jugé digne d\'aller auprès de toi; mais dis une parole, et mon serviteur sera guéri.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 8, 'Car moi-même, qui suis un homme soumis à la puissance d\'autrui, j\'ai sous mes ordres des soldats. Je dis à l\'un: Va! Et il va; et à l\'autre! Viens! Et il vient; et à mon serviteur: Fais cela! Et il le fait.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 9, 'Jésus, ayant entendu ces paroles, admira le centenier; et, se tournant vers la foule qui le suivait, il dit: Je vous le déclare, même en Israël je n\'ai pas trouvé une aussi grande foi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 10, 'Et les envoyés, de retour à la maison, trouvèrent le serviteur en bonne santé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 11, 'Le jour suivant, Jésus allait à une ville appelée Nain, et plusieurs de ses disciples et une grande foule faisaient route avec lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 12, 'Comme il approchait de la porte de la ville, voici qu\'on emportait un mort, fils unique de sa mère qui était veuve; et il y avait avec elle un grand nombre de gens de la ville.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 13, 'Le Seigneur, l\'ayant vue, fut touché de compassion pour elle, et il lui dit: Ne pleure pas!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 14, 'Puis, s\'étant approché, il toucha le cercueil, et ceux qui le portaient s\'arrêtèrent. Alors il dit: Jeune homme, je te l\'ordonne, lève-toi!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 15, 'Le mort se mit sur son séant et commença à parler. Et Jésus le rendit à sa mère.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 16, 'La crainte les saisit tous, et ils glorifiaient Dieu en disant: Un grand prophète s\'est levé parmi nous, et Dieu a visité son peuple.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 17, 'Le bruit s\'en répandit dans toute la Judée et dans tout le pays environnant.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 18, 'Les disciples de Jean lui rapportèrent toutes ces choses.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 19, 'Alors il appela deux de ses disciples et les envoya dire au Seigneur: Es-tu celui qui doit venir, ou devons-nous en attendre un autre?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 20, 'Ces hommes, étant arrivés auprès de Jésus, lui dirent: Jean-Baptiste nous a envoyés vers toi pour te dire: Es-tu celui qui doit venir, ou devons-nous en attendre un autre?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 21, 'Or, à cette heure même, Jésus guérit plusieurs personnes de maladies, d\'infirmités et de malins esprits, et il rendit la vue à plusieurs aveugles.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 22, 'Puis il répondit: Allez rapporter à Jean ce que vous avez vu et entendu: les aveugles recouvrent la vue, les boiteux marchent, les lépreux sont nettoyés, les sourds entendent, les morts ressuscitent, l\'Évangile est annoncé aux pauvres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 23, 'Heureux celui pour qui je ne serai pas une occasion de chute!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 24, 'Quand les messagers de Jean furent partis, Jésus se mit à parler de Jean à la foule, et dit: Qu\'êtes-vous allés voir au désert? Un roseau agité par le vent?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 25, 'Encore une fois, qu\'êtes-vous allés voir? Un homme vêtu d\'habits somptueux? Mais ceux qui portent des vêtements magnifiques et qui vivent dans les délices sont dans les palais des rois!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 26, 'Mais enfin, qu\'êtes-vous allés voir? Un prophète? Oui, vous dis-je, et plus qu\'un prophète.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 27, 'C\'est celui dont il est écrit: «Je vais envoyer mon messager devant ta face, et il préparera ton chemin devant toi.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 28, 'Je vous le dis, entre ceux qui sont nés de femme, il n\'y en a point de plus grand que Jean-Baptiste; toutefois, celui qui est le plus petit dans le royaume de Dieu est plus grand que lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 29, 'Et tout le peuple qui l\'a entendu, ainsi que les péagers, ont justifié Dieu, en se faisant baptiser du baptême de Jean.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 30, 'Mais les pharisiens et les docteurs de la loi, en ne se faisant pas baptiser par lui, ont rejeté le dessein de Dieu à leur égard.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 31, 'A qui donc comparerai-je les hommes de cette génération, et à qui ressemblent-ils?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 32, 'Ils ressemblent à des enfants assis sur la place publique, et qui se disent les uns aux autres: Nous vous avons joué de la flûte, et vous n\'avez pas dansé; nous avons chanté des complaintes, et vous n\'avez pas pleuré.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 33, 'En effet, Jean-Baptiste est venu, ne mangeant pas de pain et ne buvant pas de vin; et vous dites: Il a un démon.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 34, 'Le Fils de l\'homme est venu, mangeant et buvant; et vous dites: Voilà un mangeur et un buveur, un ami des péagers et des pécheurs!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 35, 'Mais la sagesse a été justifiée par tous ses enfants.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 36, 'L\'un des pharisiens pria Jésus de prendre un repas chez lui. Étant donc entré dans la maison du pharisien, Jésus se mit à table.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 37, 'Or, voici qu\'une femme de la ville, qui était de mauvaise vie, ayant appris qu\'il était à table dans la maison du pharisien, apporta un vase d\'albâtre plein de parfum.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 38, 'Et, se tenant en arrière, aux pieds de Jésus, en pleurant, elle se mit à lui arroser les pieds de ses larmes et à les essuyer avec ses cheveux; elle lui baisait les pieds et les oignait avec le parfum.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 39, 'Le pharisien qui avait invité Jésus, voyant cela, dit en lui-même: Si cet homme était prophète, il saurait qui est cette femme qui le touche, et que c\'est une femme de mauvaise vie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 40, 'Alors Jésus, prenant la parole, lui dit: Simon, j\'ai quelque chose à te dire. Simon lui répondit: Maître, parle!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 41, 'Un créancier avait deux débiteurs: l\'un lui devait cinq cents deniers, l\'autre cinquante.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 42, 'Et comme ils n\'avaient pas de quoi payer, il leur remit à tous deux leur dette. Lequel des deux l\'aimera le plus?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 43, 'Simon répondit: J\'estime que c\'est celui à qui il a le plus remis. Jésus lui dit: Tu as bien jugé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 44, 'Puis se tournant vers la femme, il dit à Simon: Tu vois cette femme? Je suis entré dans ta maison. et tu ne m\'as pas donné d\'eau pour mes pieds; mais elle les a arrosés de ses larmes et les a essuyés avec ses cheveux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 45, 'Tu ne m\'as pas donné de baiser; mais elle, depuis qu\'elle est entrée, n\'a cessé de me baiser les pieds.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 46, 'Tu n\'as pas oint ma tête d\'huile; mais elle a oint mes pieds de parfum.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 47, 'C\'est pourquoi, je te le déclare, ses péchés, qui sont en grand nombre, lui sont pardonnés; car elle a beaucoup aimé. Mais celui à qui on pardonne peu, aime peu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 48, 'Puis il dit à la femme: Tes péchés te sont pardonnés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 49, 'Ceux qui étaient à table avec lui se mirent à dire en eux-mêmes: Quel est celui-ci, qui même pardonne les péchés?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 50, 'Mais il dit à la femme: Ta foi t\'a sauvée; va en paix.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 1, 'Ensuite, Jésus allait de ville en ville et de village en village, prêchant et annonçant la bonne nouvelle du royaume de Dieu;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 2, 'et les Douze étaient avec lui. Il y avait aussi avec eux quelques femmes, qui avaient été délivrées de malins esprits ou guéries de leurs maladies: Marie appelée Madeleine, de laquelle étaient sortis sept démons,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 3, 'Jeanne, femme de Chuzas, intendant d\'Hérode, Suzanne et plusieurs autres, qui les assistaient de leurs biens.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 4, 'Comme une grande foule s\'était rassemblée, et qu\'on venait à lui de toutes les villes, Jésus leur dit en parabole:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 5, 'Le semeur sortit pour semer. Et comme il jetait sa semence, il en tomba une partie le long du chemin; elle fut foulée aux pieds, et les oiseaux du ciel la mangèrent toute.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 6, 'Une autre partie tomba sur un sol pierreux; quand elle fut levée, elle sécha, parce qu\'elle n\'avait point d\'humidité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 7, 'Une autre partie tomba parmi les épines; les épines poussèrent avec la semence et l\'étouffèrent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 8, 'Une autre partie tomba dans la bonne terre; elle leva et produisit du fruit, cent pour un. En disant ces choses, il s\'écriait: Que celui qui a des oreilles pour entendre, entende!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 9, 'Ses disciples lui demandèrent ce que signifiait cette parabole.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 10, 'Il répondit: Il vous a été donné de connaître les mystères du royaume de Dieu; mais, aux autres, tout est présenté en forme de paraboles, de sorte qu\'en voyant, ils ne voient pas, et qu\'en entendant, ils ne comprennent point.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 11, 'Voici donc ce que signifie cette parabole: La semence, c\'est la parole de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 12, 'Ceux qui la reçoivent le long du chemin, ce sont ceux qui l\'ont entendue; mais ensuite vient le Diable qui enlève cette parole de leur coeur, de peur qu\'ils ne croient et ne soient sauvés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 13, 'Ceux qui la reçoivent sur le sol pierreux, ce sont ceux qui, entendant la parole, la reçoivent avec joie; mais ils n\'ont point de racine, ils ne croient que pour un temps; et, quand l\'épreuve survient, ils se retirent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 14, 'Ce qui est tombé parmi les épines, ce sont ceux qui ont entendu la parole, mais qui s\'en vont et la laissent étouffer par les soucis, les richesses et les plaisirs de cette vie, de sorte qu\'ils ne portent pas de fruit qui vienne à maturité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 15, 'Mais ce qui tombe dans la bonne terre, ce sont ceux qui, ayant entendu la parole avec un coeur honnête et bon, la retiennent et portent du fruit avec persévérance.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 16, 'Il n\'est personne qui, après avoir allumé une lampe, la couvre d\'un boisseau ou la mette sous un lit. Au contraire, on la place sur un support, afin que ceux qui entrent voient la lumière.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 17, 'En effet, il n\'y a rien de secret qui ne doive être manifesté, ni rien de caché qui ne doive être connu et mis en évidence.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 18, 'Prenez donc garde à la manière dont vous écoutez; car on donnera à celui qui a, mais à celui qui n\'a pas, on ôtera même ce qu\'il croit avoir.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 19, 'Sa mère et ses frères vinrent le trouver; mais ils ne pouvaient l\'aborder à cause de la foule.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 20, 'On vint donc lui dire: Ta mère et tes frères sont là dehors, qui désirent te voir.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 21, 'Mais il répondit: Ma mère et mes frères, ce sont ceux qui écoutent la parole de Dieu et qui la mettent en pratique!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 22, 'Un jour, il entra dans une barque avec ses disciples, et il leur dit: Passons de l\'autre côté du lac; et ils partirent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 23, 'Comme ils voguaient, Jésus s\'endormit. Un tourbillon de vent vint s\'abattre sur le lac; la barque se remplissait d\'eau et ils étaient en danger.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 24, 'Alors ils vinrent à lui, et le réveillèrent en lui disant: Maître, Maître, nous périssons! Mais lui, s\'étant réveillé, imposa silence au vent et aux flots, qui s\'apaisèrent, et il se fit un grand calme.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 25, 'Il leur dit alors: Où est votre foi? Et, saisis de crainte et d\'admiration, ils se disaient entre eux: Quel est donc celui-ci? Il commande même aux vents et aux flots, et ils lui obéissent!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 26, 'Ils abordèrent ensuite au pays des Géraséniens, qui est vis-à-vis de la Galilée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 27, 'Et quand Jésus fut descendu à terre, il vint au devant de lui un homme de la ville, qui était possédé de plusieurs démons. Depuis fort longtemps il ne portait pas de vêtement, et il ne demeurait pas dans une maison, mais dans les tombeaux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 28, 'Dès qu\'il vit Jésus, il poussa un grand cri, et, se jetant à ses pieds, il dit d\'une voix forte: Qu\'y a-t-il entre moi et toi, Jésus, Fils du Dieu très haut? Je t\'en supplie ne me tourmente pas!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 29, 'En effet, l\'esprit impur venait de recevoir de Jésus l\'ordre de sortir de cet homme, dont il s\'était rendu maître depuis longtemps; et, bien qu\'on gardât le malade, lié de chaînes et les fers aux pieds, il rompait ses liens et était emporté par le démon dans les déserts.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 30, 'Jésus lui demanda: Quel est ton nom? Il répondit: Légion! Car plusieurs démons étaient entrés en lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 31, 'Et ils suppliaient Jésus de ne pas leur commander d\'aller dans l\'abîme.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 32, 'Or, il y avait là un grand troupeau de pourceaux qui paissaient dans la montagne. Les démons supplièrent Jésus de leur permettre d\'entrer dans ces pourceaux; et il le leur permit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 33, 'Etant donc sortis de cet homme ils entrèrent dans les pourceaux; le troupeau se précipita dans le lac, du haut de la falaise, et il s\'y noya.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 34, 'Ceux qui le faisaient paître, voyant ce qui était arrivé, s\'enfuirent et répandirent la nouvelle dans la ville et dans la campagne.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 35, 'Alors les gens sortirent pour voir ce qui s\'était passé; et, quand ils furent arrivés auprès de Jésus, ils trouvèrent l\'homme, de qui les démons étaient sortis, assis aux pieds de Jésus, habillé et dans son bon sens; et ils furent saisis de crainte.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 36, 'Les témoins de l\'événement leur racontèrent comment le démoniaque avait été délivré.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 37, 'Tous les habitants de la contrée des Géraséniens prièrent Jésus de se retirer de chez eux; car ils étaient saisis d\'une grande frayeur. Il entra donc dans la barque pour s\'en retourner.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 38, 'Et l\'homme, de qui les démons étaient sortis, lui demandait la permission de rester avec lui; mais Jésus le renvoya, en disant:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 39, 'Retourne dans ta maison, et raconte tout ce que Dieu a fait pour toi. Il s\'en alla donc, publiant par toute la ville tout ce que Jésus lui avait fait.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 40, 'A son retour, Jésus fut reçu par la foule; car tous l\'attendaient.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 41, 'Et il vint un homme appelé Jaïrus, qui était chef de la synagogue. Il se jeta aux pieds de Jésus, en le priant de venir dans sa maison,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 42, 'parce qu\'il avait une fille unique, âgée de douze ans, qui se mourait. Pendant que Jésus s\'y rendait, la foule le pressait de tous côtés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 43, 'Alors une femme, qui avait une perte de sang depuis douze ans et qui avait dépensé tout son bien en médecins, sans avoir pu être guérie par aucun,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 44, 's\'approcha de lui par derrière et toucha le bord de son vêtement; et à l\'instant, sa perte de sang s\'arrêta.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 45, 'Alors Jésus dit: Qui m\'a touché? Comme tous s\'en défendaient, Pierre et ceux qui étaient avec lui, répondirent: Maître, la foule t\'environne et te presse!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 46, 'Jésus reprit: Quelqu\'un m\'a touché; car j\'ai senti qu\'une force est sortie de moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 47, 'La femme, voyant qu\'elle n\'avait pu rester cachée, vint toute tremblante se jeter à ses pieds; et elle expliqua, devant tout le peuple, pourquoi elle l\'avait touché, et comment elle avait été immédiatement guérie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 48, 'Jésus lui dit: Ma fille, ta foi t\'a sauvée; va en paix.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 49, 'Comme il parlait encore, quelqu\'un vint de la maison du chef de la synagogue et dit à ce dernier: Ta fille est morte; n\'importune plus le Maître.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 50, 'Mais Jésus, l\'ayant entendu, dit à Jaïrus: Ne crains point! Crois seulement, et elle sera sauvée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 51, 'Quand il fut arrivé à la maison, il ne laissa entrer avec lui que Pierre, Jacques et Jean, et le père et la mère de l\'enfant.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 52, 'Tous pleuraient et se lamentaient sur elle. Alors Jésus dit: Ne pleurez pas; elle n\'est pas morte, mais elle dort.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 53, 'Et ils se moquaient de lui, sachant qu\'elle était morte.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 54, 'Mais Jésus la prit par la main, et dit à haute voix: Mon enfant, lève-toi!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 55, 'Alors l\'esprit lui revint; elle se leva à l\'instant, et il commanda de lui donner à manger.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 56, 'Ses parents furent saisis d\'étonnement; mais il leur défendit de dire à personne ce qui était arrivé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 1, 'Jésus, ayant réuni les Douze, leur donna puissance et autorité sur tous les démons, avec le pouvoir de guérir les maladies.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 2, 'Puis, il les envoya annoncer le royaume de Dieu et guérir les malades.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 3, 'Et il leur dit: Ne prenez rien pour la route, ni bâton, ni sac, ni pain, ni argent, et n\'ayez pas deux vêtements.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 4, 'Dans quelque maison que vous entriez, demeurez-y jusqu\'à votre départ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 5, 'Quant à ceux qui ne vous recevront pas, sortez de leur ville et secouez la poussière de vos pieds en témoignage contre eux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 6, 'Étant donc partis, ils allaient de village en village, annonçant partout l\'Évangile et guérissant les malades.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 7, 'Cependant, Hérode le tétrarque apprit tout ce qui se passait; et il ne savait que penser, parce que les uns disaient: Jean est ressuscité des morts;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 8, 'd\'autres: Élie est apparu; d\'autres: Un des anciens prophètes est ressuscité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 9, 'Mais Hérode disait: J\'ai fait décapiter Jean; qui donc est celui-ci, au sujet duquel j\'entends dire de telles choses? Et il cherchait à le voir.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 10, 'Les apôtres, étant de retour, racontèrent à Jésus tout ce qu\'ils avaient fait. Alors il les prit avec lui et se retira à l\'écart, du côté d\'une ville appelée Bethsaïda.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 11, 'Mais quand les foules l\'eurent appris, elles le suivirent. Jésus, les ayant accueillies, leur parlait du royaume de Dieu, et il rendait la santé à ceux qui avaient besoin de guérison.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 12, 'Comme le jour commençait à baisser, les Douze s\'approchèrent et lui dirent: Renvoie la foule, afin qu\'elle aille dans les villages et les campagnes d\'alentour, pour y loger et y trouver à manger; car ici, nous sommes dans un lieu désert.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 13, 'Mais il leur dit: Donnez-leur vous-mêmes à manger. Ils répondirent: Nous n\'avons que cinq pains et deux poissons, à moins que nous n\'allions nous-mêmes acheter des vivres pour tout ce peuple.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 14, 'Or, il y avait là environ cinq mille hommes. Alors il dit à ses disciples: Faites-les asseoir par rangées de cinquante.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 15, 'C\'est ce qu\'ils firent; et tout le monde s\'assit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 16, 'Puis, Jésus prit les cinq pains et les deux poissons, et, levant les yeux vers le ciel, il les bénit, les rompit, et les donna aux disciples pour les distribuer à la foule.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 17, 'Tous mangèrent et furent rassasiés; et on emporta douze paniers, pleins des morceaux qui restaient.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 18, 'Un jour que Jésus se tenait à l\'écart et priait, comme ses disciples étaient venus le rejoindre, il leur demanda: Qui dit-on, parmi le peuple, que je suis?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 19, 'Ils répondirent: Les uns disent: Jean-Baptiste; d\'autres: Élie; et d\'autres: l\'un des anciens prophètes qui est ressuscité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 20, 'Et vous, — leur dit-il, — qui dites-vous que je suis? Pierre répondit: Tu es le Christ de Dieu!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 21, 'Jésus leur défendit sévèrement de le dire à personne,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 22, 'et il ajouta: Il faut que le Fils de l\'homme souffre beaucoup, qu\'il soit rejeté par les anciens, par les principaux sacrificateurs et par les scribes, qu\'il soit mis à mort, et qu\'il ressuscite le troisième jour.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 23, 'Puis il disait à tous: Si quelqu\'un veut venir après moi, qu\'il renonce à lui-même, qu\'il se charge chaque jour de sa croix, et qu\'il me suive.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 24, 'Car celui qui voudra sauver sa vie la perdra; mais celui qui aura perdu sa vie à cause de moi, la sauvera.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 25, 'Que servirait-il à un homme de gagner le monde entier, s\'il se perdait ou se ruinait lui-même?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 26, 'Car si quelqu\'un a honte de moi et de mes paroles, le Fils de l\'homme aura honte de lui, quand il viendra dans sa gloire et dans celle du Père et des saints anges.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 27, 'En vérité, je vous le dis, quelques-uns de ceux qui sont ici présents ne mourront pas, avant d\'avoir vu le royaume de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 28, 'Environ huit jours après avoir dit ces paroles, Jésus prit avec lui Pierre, Jean et Jacques, et il monta sur la montagne pour prier.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 29, 'Pendant qu\'il priait, son visage parut tout autre, et son vêtement devint d\'une blancheur éblouissante.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 30, 'Et voici que deux hommes s\'entretenaient avec lui: c\'étaient Moïse et Élie,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 31, 'qui apparaissaient environnés de gloire. Ils parlaient de son départ, qui devait s\'accomplir à Jérusalem.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 32, 'Pierre et ses compagnons étaient accablés de sommeil; mais, s\'étant réveillés, ils virent sa gloire et les deux hommes qui se tenaient près de lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 33, 'Comme ces hommes se séparaient de Jésus, Pierre lui dit: Maître, il est bon pour nous d\'être ici; dressons trois tentes, une pour toi, une pour Moïse, et une pour Élie! Car il ne savait pas ce qu\'il disait.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 34, 'Il parlait encore, lorsqu\'une nuée survint et les couvrit; et quand ils disparurent dans la nuée, les disciples furent saisis de crainte.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 35, 'Alors on entendit une voix venant de la nuée, qui disait: Celui-ci est mon Fils, mon Élu, écoutez-le!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 36, 'Et pendant que cette voix se faisait entendre, Jésus se trouva seul. Ils gardèrent le silence, et ils ne dirent rien à personne de ce qu\'ils avaient vu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 37, 'Le jour suivant, comme ils descendaient de la montagne, une grande foule vint au devant de Jésus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 38, 'Et un homme de la foule s\'écria: Maître, je te prie, jette les yeux sur mon fils; car c\'est mon seul enfant.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 39, 'Un esprit s\'empare de lui, et soudain il pousse des cris; l\'esprit l\'agite avec violence, le fait écumer, et ne s\'éloigne de lui qu\'après l\'avoir tout brisé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 40, 'J\'ai prié tes disciples de le chasser, mais ils ne l\'ont pu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 41, 'Jésus répondit: race incrédule et perverse, jusques à quand serai-je avec vous et vous supporterai-je? Amène ici ton fils.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 42, 'Comme l\'enfant approchait, le démon le jeta par terre et l\'agita violemment. Mais Jésus parla sévèrement à l\'esprit impur; il guérit l\'enfant et le rendit à son père.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 43, 'Tous furent frappés de la puissance magnifique de Dieu. Et comme ils étaient tous dans l\'admiration de tout ce que Jésus faisait, il dit à ses disciples:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 44, 'Pour vous, retenez bien ce que je vais vous dire: Le Fils de l\'homme va être livré entre les mains des hommes!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 45, 'Mais ils ne comprenaient point cette parole: elle était voilée pour eux, de sorte qu\'ils n\'en saisissaient pas le sens. Et ils craignaient de l\'interroger à ce sujet.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 46, 'Il survint entre eux une discussion pour savoir lequel était le plus grand parmi eux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 47, 'Mais Jésus, connaissant les pensées de leurs coeurs, prit un petit enfant, le mit auprès de lui,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 48, 'et il leur dit: Celui qui reçoit ce petit enfant en mon nom, me reçoit, et celui qui me reçoit, reçoit celui qui m\'a envoyé. Car celui qui est le plus petit entre vous tous, c\'est celui-là qui est grand!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 49, 'Jean prit la parole et dit: Maître, nous avons vu quelqu\'un qui chassait les démons en ton nom, et nous l\'en avons empêché parce qu\'il ne te suit pas avec nous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 50, 'Mais Jésus lui dit: Ne l\'en empêchez point; car celui qui n\'est pas contre vous, est pour vous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 51, 'Comme le temps où Jésus devait être enlevé du monde approchait, il prit résolument le chemin de Jérusalem.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 52, 'Et il envoya des messagers devant lui. Ceux-ci, étant partis, entrèrent dans un village des Samaritains pour lui préparer un logement;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 53, 'mais les Samaritains ne le reçurent pas, parce qu\'il se dirigeait vers Jérusalem.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 54, 'Jacques et Jean, ses disciples, voyant cela, dirent: Seigneur, veux-tu que nous disions que le feu descende du ciel et qu\'il les consume?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 55, 'Mais Jésus, se retournant, les réprimanda [et il leur dit: Vous ne savez de quel esprit vous êtes animés].');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 56, 'Puis ils allèrent dans un autre village.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 57, 'Pendant qu\'ils étaient en chemin, quelqu\'un lui dit: Je te suivrai partout où tu iras.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 58, 'Jésus lui répondit: Les renards ont des tanières, les oiseaux du ciel ont des nids; mais le Fils de l\'homme n\'a pas où reposer sa tête.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 59, 'Il dit à un autre: Suis-moi. Celui-ci lui répondit: Permets-moi d\'aller d\'abord ensevelir mon père.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 60, 'Mais Jésus lui dit: Laisse les morts ensevelir leurs morts; et toi, va annoncer le royaume de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 61, 'Un autre encore lui dit: Je te suivrai, Seigneur; mais permets-moi de prendre auparavant congé de ceux qui sont dans ma maison.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 62, 'Jésus lui dit: Celui qui, après avoir mis la main à la charrue, regarde en arrière, n\'est pas propre au royaume de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 1, 'Après cela, le Seigneur désigna encore soixante-dix autres disciples; et il les envoya deux à deux devant lui, dans toutes les villes et dans tous les lieux où il devait aller lui-même.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 2, 'Il leur disait: La moisson est grande; mais il y a peu d\'ouvriers. Priez donc le maître de la moisson d\'envoyer des ouvriers dans sa moisson.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 3, 'Allez! Je vous envoie comme des agneaux au milieu des loups.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 4, 'Ne portez ni bourse, ni sac, ni chaussures, et ne saluez personne en chemin.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 5, 'Dans quelque maison que vous entriez, dites d\'abord: La paix soit sur cette maison!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 6, 'Et s\'il se trouve là un enfant de la paix, votre paix reposera sur lui; sinon, elle reviendra à vous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 7, 'Demeurez dans cette maison-là, mangeant et buvant ce qu\'on vous donnera; car l\'ouvrier est digne de son salaire. Ne passez point de maison en maison.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 8, 'Dans quelque ville que vous entriez, si l\'on vous reçoit, mangez ce qu\'on vous présentera.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 9, 'Guérissez les malades qui s\'y trouveront, et dites-leur: Le royaume de Dieu s\'est approché de vous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 10, 'Mais, dans quelque ville que vous entriez, si l\'on ne vous reçoit pas, allez sur les places publiques et dites:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 11, 'Nous secouons contre vous la poussière même de votre ville, qui s\'est attachée à nos pieds; sachez pourtant que le royaume de Dieu s\'est approché de vous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 12, 'Je vous dis qu\'au dernier jour, Sodome sera traitée moins rigoureusement que cette ville.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 13, 'Malheur à toi, Corazin! Malheur à toi, Bethsaïda! Car si les miracles qui ont été faits au milieu de vous avaient été faits dans Tyret dans Sidon, il y a longtemps qu\'elles se seraient repenties, en prenant le sac et la cendre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 14, 'C\'est pourquoi, au jour du jugement, Tyr et Sidon seront traitées moins rigoureusement que vous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 15, 'Et toi, Capernaüm qui as été élevée jusqu\'au ciel, tu seras abaissée jusqu\'en enfer!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 16, '— Qui vous écoute, m\'écoute; qui vous rejette, me rejette; et qui me rejette, rejette Celui qui m\'a envoyé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 17, 'Les soixante-dix revinrent avec joie, en disant: Seigneur, les démons mêmes nous sont assujettis en ton nom.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 18, 'Alors Jésus leur dit: Je voyais Satan tomber du ciel comme un éclair.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 19, 'Voici que je vous ai donné le pouvoir de fouler aux pieds les serpents, les scorpions et toute la puissance de l\'ennemi; et rien ne pourra vous nuire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 20, 'Toutefois, ne vous réjouissez pas de ce que les esprits vous sont assujettis; mais réjouissez-vous de ce que vos noms sont écrits dans les cieux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 21, 'A cette heure même, Jésus tressaillit de joie par le Saint-Esprit, et il dit: Je te loue, ô Père, Seigneur du ciel et de la terre, de ce que tu as caché ces choses aux sages et aux intelligents, et de ce que tu les as révélées aux petits enfants! Oui, Père, il en est ainsi, parce que tu l\'as trouvé bon.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 22, 'Toutes choses m\'ont été remises par mon Père; et nul ne connaît qui est le Fils, si ce n\'est le Père, ni qui est le Père, si ce n\'est le Fils, et celui à qui le Fils aura voulu le révéler.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 23, 'Puis, se tournant vers ses disciples, il leur dit en particulier: Heureux les yeux qui voient ce que vous voyez!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 24, 'Car, je vous le déclare, beaucoup de prophètes et de rois ont souhaité de voir ce que vous voyez, et ils ne l\'ont pas vu, et d\'entendre ce que vous entendez, et ils ne l\'ont pas entendu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 25, 'Alors un docteur de la loi se leva pour mettre Jésus à l\'épreuve, et il lui dit: Maître, que ferai-je pour hériter la vie éternelle?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 26, 'Jésus lui dit: Qu\'est-ce qui est écrit dans la loi? Qu\'y lis-tu.?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 27, 'Il répondit: «Tu aimeras le Seigneur, ton Dieu, de tout ton coeur, de toute ton âme, de toute ta force et de toute ta pensée, et ton prochain comme toi-même.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 28, 'Jésus lui dit: Tu as bien répondu fais cela, et tu vivras.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 29, 'Mais cet homme, voulant se justifier, dit à Jésus: Et qui est mon prochain?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 30, 'Jésus reprit la parole et dit: Un homme descendait de Jérusalem à Jérico. Il tomba entre les mains de brigands qui le dépouillèrent, et qui, après l\'avoir couvert de blessures, s\'en allèrent, le laissant à demi-mort.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 31, 'Or, il se trouva qu\'un sacrificateur descendait par ce chemin-là; il vit cet homme, et il passa outre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 32, 'Un lévite aussi, étant venu en cet endroit, s\'approcha et, l\'ayant vu, il passa outre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 33, 'Mais un Samaritain, qui était en voyage, arriva près de lui, et, l\'ayant vu, il fut touché de compassion.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 34, 'Il s\'approcha et banda ses plaies, en y versant de l\'huile et du vin; puis il le mit sur sa propre monture, le conduisit à une hôtellerie et prit soin de lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 35, 'Le lendemain, il prit deux deniers, les donna à l\'hôtelier et lui dit: Aie soin de lui; et tout ce que tu dépenseras de plus, je te le rendrai à mon retour.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 36, 'Lequel de ces trois te paraît avoir été le prochain de celui qui était tombé entre les mains des brigands?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 37, 'Le docteur de la loi répondit: C\'est celui qui a exercé la miséricorde envers lui. Jésus dit: Va, et fais de même!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 38, 'Comme ils étaient en chemin, il entra dans un village, et une femme, nommée Marthe, le reçut dans sa maison.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 39, 'Elle avait une soeur, appelée Marie, qui, se tenant assise aux pieds du Seigneur, écoutait sa parole.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 40, 'Or, Marthe était absorbée par divers soins; elle vint et dit à Jésus: Seigneur, ne considères-tu pas que ma soeur me laisse servir toute seule? Dis-lui donc de m\'aider.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 41, 'Le Seigneur lui répondit: Marthe, Marthe, tu te mets en peine et tu t\'agites pour beaucoup de choses;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 42, 'mais une seule chose est nécessaire. Et Marie a choisi la bonne part qui ne lui sera point ôtée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 1, 'Un jour, Jésus était en prière dans un certain lieu. Quand il eut fini de prier, un de ses disciples lui dit: Seigneur, enseigne-nous à prier, comme Jean l\'a enseigné à ses disciples.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 2, 'Il leur dit: Quand vous priez, dites: Père, que ton nom soit sanctifié. Que ton règne vienne.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 3, 'Donne-nous chaque jour notre pain quotidien.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 4, 'Pardonne-nous nos péchés; car, nous aussi, nous pardonnons à tous ceux qui nous ont offensés. Ne nous laisse pas succomber à la tentation.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 5, 'Puis il leur dit: Si l\'un de vous a un ami et qu\'il aille le trouver au milieu de la nuit pour lui dire: Mon ami, prête-moi trois pains;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 6, 'car un de mes amis est arrivé de voyage, et je n\'ai rien à lui offrir.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 7, 'Si cet homme lui répond de l\'intérieur: Ne m\'importune pas; ma porte est déjà fermée, mes enfants et moi, nous sommes au lit; je ne puis me lever pour t\'en donner!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 8, 'Je vous le déclare, quand même cet homme ne se lèverait pas pour lui en donner parce qu\'il est son ami, il se lèvera à cause de son importunité et lui donnera tout ce dont il a besoin.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 9, 'Et moi, je vous dis: demandez, et l\'on vous donnera; cherchez, et vous trouverez; frappez, et l\'on vous ouvrira.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 10, 'Car quiconque demande, reçoit; qui cherche, trouve; et l\'on ouvrira à celui qui frappe.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 11, 'Quel est parmi vous le père qui donnera à son fils une pierre, s\'il lui demande du pain? Ou, s\'il demande du poisson, lui donnera-t-il un serpent au lieu d\'un poisson?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 12, 'Ou, s\'il demande un oeuf, lui donnera-t-il un scorpion?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 13, 'Si donc vous, qui êtes mauvais, savez donner de bonnes choses à vos enfants, combien plus votre Père céleste donnera-t-il le Saint-Esprit à ceux qui le lui demandent!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 14, 'Jésus chassa un démon, chez un homme qui était muet; et le démon étant sorti, le muet parla. La multitude fut remplie d\'admiration;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 15, 'mais quelques-uns dirent: C\'est par Béelzébul, le prince des démons, qu\'il chasse les démons.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 16, 'D\'autres, pour le mettre à l\'épreuve, lui demandaient un miracle venant du ciel.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 17, 'Jésus, connaissant leurs pensées, leur dit: Tout royaume divisé contre lui-même est réduit en désert, et ses maisons tombent l\'une sur l\'autre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 18, 'Si donc Satan est aussi divisé contre lui-même, comment son royaume subsistera-t-il, puisque vous dites que c\'est par Béelzébul que je chasse les démons?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 19, 'Et si moi je chasse les démons par Béelzébul, vos fils, par qui les chassent-ils? C\'est pourquoi ils seront eux-mêmes vos juges.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 20, 'Mais si c\'est par le doigt de Dieu que je chasse les démons, le royaume de Dieu est donc venu jusqu\'à vous!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 21, 'Quand un homme fort et bien armé garde l\'entrée de sa maison, ce qu\'il possède est en sûreté.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 22, 'Mais, qu\'il en vienne un plus fort que lui: celui-là, après l\'avoir vaincu, lui enlève toutes ses armes, dans lesquelles il mettait sa confiance, et il distribue ses dépouilles.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 23, 'Celui qui n\'est pas avec moi, est contre moi, et celui qui n\'amasse pas avec moi, disperse.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 24, 'Lorsque l\'esprit impur est sorti d\'un homme, il erre dans les lieux arides pour chercher du repos. N\'en trouvant point, il dit: Je retournerai dans ma maison, d\'où je suis sorti.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 25, 'Étant revenu, il la trouve balayée et ornée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 26, 'Alors il s\'en va et prend avec lui sept autres esprits plus méchants que lui. Ils entrent là et y demeurent; et la dernière condition de cet homme devient pire que la première.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 27, 'Pendant que Jésus disait ces paroles, une femme, élevant la voix au milieu de la foule, lui dit: Heureux les flancs qui t\'ont porté, et les mamelles qui t\'ont allaité!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 28, 'Jésus reprit: Heureux plutôt ceux qui écoutent la parole de Dieu et qui la gardent!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 29, 'Comme le peuple s\'amassait en foule, Jésus se mit à dire: Cette génération est une génération méchante: elle demande un signe; mais il ne lui en sera accordé aucun autre que celui de Jonas.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 30, 'Car, de même que Jonas fut un signe pour les Ninivites, le Fils de l\'homme aussi en sera un pour cette génération.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 31, 'La reine du Midi se lèvera, au jour du jugement, avec les hommes de cette génération, et elle les condamnera, parce qu\'elle vint des extrémités de la terre pour entendre la sagesse de Salomon; or, il y a ici plus que Salomon!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 32, 'Les Ninivites se lèveront au jour du jugement avec cette génération, et ils la condamneront, parce qu\'ils se repentirent à la prédication de Jonas; or, il y a ici plus que Jonas!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 33, 'Personne n\'allume une lampe pour la mettre dans un lieu caché, ou sous un boisseau; mais on la met sur un support, afin que ceux qui entrent, voient la lumière.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 34, 'L\'oeil est la lampe du corps; si ton oeil est sain, tout ton corps est dans la lumière; mais s\'il est mauvais, ton corps est dans les ténèbres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 35, 'Ainsi, prends garde que la lumière qui est en toi ne soit ténèbres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 36, 'il sera éclairé entièrement, comme lorsque la clarté d\'une lampe rayonne sur toi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 37, 'Pendant que Jésus parlait, un pharisien le pria de prendre un repas chez lui. Jésus entra et se mit à table.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 38, 'Le pharisien, voyant qu\'il ne s\'était pas lavé avant le repas, en fut surpris.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 39, 'Mais le Seigneur lui dit: Vous autres, pharisiens, vous nettoyez le dehors de la coupe et du plat; et, au dedans, vous êtes pleins de rapacité et de méchanceté.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 40, 'Insensés! Celui qui a fait le dehors, n\'a-t-il pas aussi fait le dedans?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 41, 'Donnez plutôt en aumônes ce que vous avez, et toutes choses seront pures pour vous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 42, 'Mais malheur à vous, pharisiens, parce que vous payez la dîme de la menthe, de la rue et de toutes sortes d\'herbes, tandis que vous négligez la justice et l\'amour de Dieu! Voilà les choses qu\'il fallait faire, sans toutefois négliger les autres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 43, 'Malheur à vous, pharisiens, parce que vous aimez la première place dans les synagogues, et les salutations dans les places publiques!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 44, 'Malheur à vous, parce que vous ressemblez aux tombeaux qu\'on ne remarque pas, et sur lesquels on marche sans le savoir!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 45, 'Alors un des docteurs de la loi prit la parole et lui dit: Maître, en parlant ainsi, tu nous outrages, nous aussi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 46, 'Jésus reprit: Malheur à vous aussi, docteurs de la loi, parce que vous chargez les hommes de fardeaux difficiles à porter, et vous-mêmes, vous n\'y touchez pas du doigt!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 47, 'Malheur à vous, parce que vous bâtissez les tombeaux des prophètes que vos pères ont fait mourir!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 48, 'Vous rappelez ainsi les oeuvres de vos pères, et vous les approuvez; car eux, ils les ont fait mourir, et vous, vous leur élevez des tombeaux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 49, 'C\'est pourquoi, la sagesse de Dieu a dit: Je leur enverrai des prophètes et des apôtres, et ils feront mourir les uns et persécuteront les autres,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 50, 'afin que le sang de tous les prophètes, répandu depuis la création du monde, soit redemandé à cette génération,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 51, 'depuis le sang d\'Abel jusqu\'au sang de Zacharie, qui fut tué entre l\'autel et le temple. Oui, vous dis-je, il en sera demandé compte à cette génération.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 52, 'Malheur à vous, docteurs de la loi, parce qu\'ayant pris la clef de la science, vous n\'êtes point entrés vous-mêmes, et ceux qui voulaient entrer, vous les en avez empêchés!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 53, 'Quand Jésus fut sorti de là, les scribes et les pharisiens se mirent à le presser violemment et à le harceler de leurs questions,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 54, 'lui tendant des pièges, pour s\'emparer de quelque parole sortie de sa bouche.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 1, 'Cependant, le peuple s\'étant rassemblé par milliers, au point que les gens s\'écrasaient les uns les autres, Jésus se mit tout d\'abord à dire à ses disciples Gardez-vous du levain des pharisiens, qui est l\'hypocrisie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 2, 'Il n\'y a rien de caché qui ne doive être découvert, ni rien de secret qui ne doive être connu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 3, 'C\'est pourquoi, tout ce que vous aurez dit dans les ténèbres, sera entendu en plein jour; et ce que vous aurez dit à l\'oreille, dans les chambres, sera prêché sur les toits.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 4, 'Je vous dis, à vous qui êtes mes amis: Ne craignez pas ceux qui tuent le corps, et qui, après cela, ne peuvent rien faire de plus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 5, 'Mais je vous montrerai qui vous devez craindre. Craignez celui qui, après avoir ôté la vie, a le pouvoir de jeter dans la géhenne! Oui, je vous le dis, c\'est celui-là que vous devez craindre!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 6, 'Ne vend-on pas cinq passereaux pour deux sous? Cependant, Dieu n\'en oublie pas un seul.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 7, 'Et les cheveux mêmes de votre tête sont tous comptés. Ne craignez point; vous valez plus que beaucoup de passereaux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 8, 'Je vous le déclare, quiconque me confessera devant les hommes, le Fils de l\'homme le confessera aussi devant les anges de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 9, 'Mais celui qui m\'aura renié devant les hommes, celui-là sera renié devant les anges de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 10, 'Quiconque parlera contre le Fils de l\'homme, obtiendra le pardon; mais à celui qui aura blasphémé contre le Saint-Esprit, il ne sera point pardonné.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 11, 'Quand on vous mènera dans les synagogues et devant les magistrats et les autorités, ne vous inquiétez pas de la manière dont vous parlerez pour votre défense, ni de ce que vous direz;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 12, 'car le Saint-Esprit vous enseignera à l\'heure même ce qu\'il faudra que vous disiez.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 13, 'Alors, du milieu de la foule, quelqu\'un dit à Jésus: Maître, dis à mon frère de partager avec moi notre héritage.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 14, 'Mais Jésus lui répondit: Homme, qui est-ce qui m\'a établi pour être votre juge, ou pour faire vos partages?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 15, 'Puis il leur dit: Gardez-vous avec soin de toute avarice; car, fût-il dans l\'abondance, la vie d\'un homme ne dépend pas de ce qu\'il possède.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 16, 'Jésus leur dit encore cette parabole: Les terres d\'un homme riche avaient beaucoup rapporté;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 17, 'et il raisonnait ainsi en lui-même: Que ferai-je? Car je n\'ai pas de place pour serrer ma récolte.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 18, 'Voici, dit-il, ce que je ferai j\'abattrai mes greniers, j\'en bâtirai de plus grands, j\'y amasserai toute ma récolte et tous mes biens.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 19, 'Puis je dirai à mon âme: Mon âme, tu as beaucoup de biens en réserve pour beaucoup d\'années; repose-toi, mange, bois et réjouis-toi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 20, 'Mais Dieu lui dit: Insensé, cette nuit même ton âme te sera redemandée; et ce que tu as préparé, pour qui cela sera-t-il?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 21, 'Il en est ainsi de celui qui amasse des trésors pour lui-même, et qui n\'est pas riche en Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 22, 'Alors Jésus dit à ses disciples: Ainsi, je vous le déclare: Ne soyez pas en souci, pour votre vie, de ce que vous mangerez, ni pour votre corps, du vêtement dont vous le revêtirez.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 23, 'La vie est plus que la nourriture, et le corps plus que le vêtement.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 24, 'Regardez les corbeaux: Ils ne sèment ni ne moissonnent, ils n\'ont ni cellier, ni grenier, et Dieu les nourrit; combien ne valez-vous pas plus que les oiseaux!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 25, 'Et qui de vous peut ajouter, par son souci, une coudée à sa taille?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 26, 'Si donc vous ne pouvez pas même les moindres choses, pourquoi vous inquiétez-vous des autres?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 27, 'Considérez comment croissent les lis: Ils ne travaillent ni ne filent; cependant, je vous dis que Salomon même, dans toute sa gloire, n\'a pas été vêtu comme l\'un d\'eux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 28, 'Si Dieu revêt ainsi, dans les champs, l\'herbe qui est aujourd\'hui, et qui demain sera jetée au four, combien plutôt vous vêtira-t-il, ô gens de peu de foi!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 29, 'Ne vous mettez donc pas en peine de ce que vous mangerez ou de ce que vous boirez, et n\'ayez pas l\'esprit inquiet.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 30, 'Car toutes ces choses, ce sont les nations de ce monde qui les recherchent; et votre Père sait que vous en avez besoin.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 31, 'Mais vous, recherchez plutôt son royaume; et toutes ces choses vous seront données par dessus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 32, 'Ne crains point, petit troupeau car il a plu à votre Père de vous donner le royaume.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 33, 'Vendez ce que vous possédez et donnez-le en aumônes. Faites-vous des bourses qui ne s\'usent pas, un trésor dans les cieux qui ne manque jamais, dont le voleur n\'approche pas, et que les vers ne détruisent point.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 34, 'Car où est votre trésor, là aussi sera votre coeur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 35, 'Que vos reins soient ceints, et vos lampes allumées.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 36, 'Soyez semblables à des hommes qui attendent le moment où leur maître reviendra des noces, afin de lui ouvrir dès qu\'il arrivera et qu\'il frappera.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 37, 'Heureux ces serviteurs que le maître, à son arrivée, trouvera veillant! En vérité, je vous le dis, il se ceindra, il les fera mettre à sa table et viendra les servir.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 38, 'Qu\'il arrive à la seconde ou à la troisième veille, s\'il les trouve dans cet état, heureux ces serviteurs!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 39, 'Sachez-le bien, si le père de famille connaissait l\'heure à laquelle le voleur viendra, il veillerait et, ne laisserait pas percer sa maison.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 40, 'Vous aussi, tenez-vous prêts; car le Fils de l\'homme viendra à l\'heure où vous n\'y penserez pas.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 41, 'Alors Pierre lui dit: Seigneur, est-ce pour nous que tu dis cette parabole, ou est-ce aussi pour tous?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 42, 'Le Seigneur répondit: Quel est l\'économe fidèle et prudent que le maître établira sur ses domestiques, pour leur donner, au temps convenable, leur mesure de blé?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 43, 'Heureux ce serviteur que le maître, à son arrivée, trouvera agissant ainsi!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 44, 'En vérité, je vous dis qu\'il l\'établira sur tous ses biens.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 45, 'Mais si ce serviteur dit en son cœur: Mon maître tarde à venir. s\'il se met à battre les serviteurs et les servantes, à manger, à boire et à s\'enivrer,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 46, 'le maître de ce serviteur viendra le jour où il ne s\'y attend point, et à l\'heure qu\'il ne sait pas. Il déchirera le serviteur à coups de fouet, et il lui donnera son lot avec les infidèles.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 47, 'Ce serviteur qui, ayant connu la volonté de son maître, n\'aura rien préparé et n\'aura pas fait cette volonté, sera battu de plusieurs coups.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 48, 'Mais celui qui ne l\'a pas connue, et qui a fait des choses dignes de châtiment, sera battu de peu de coups. A quiconque il aura été beaucoup donné, il sera beaucoup redemandé; et l\'on exigera davantage de celui à qui l\'on aura beaucoup confié.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 49, 'Je suis venu jeter un feu sur la terre et qu\'ai-je à désirer, s\'il est déjà allumé?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 50, 'Il est un baptême dont je dois être baptisé, et, combien je suis dans l\'angoisse jusqu\'à ce qu\'il soit accompli!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 51, 'Pensez-vous que je sois venu apporter la paix sur la terre? Non, vous dis-je, mais plutôt la division.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 52, 'Car désormais, s\'il y a cinq personnes dans une maison, elles seront divisées, trois contre deux, et deux contre trois;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 53, 'le père contre le fils, et le fils contre le père; la mère contre la fille, et la fille contre la mère la belle-mère contre la belle-fille, et la belle-fille contre la belle-mère.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 54, 'Il disait encore à la foule: Quand vous voyez un nuage se lever à l\'Occident, vous dites aussitôt: Il va pleuvoir; et cela arrive ainsi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 55, 'Et quand le vent du Midi souffle, vous dites: il fera chaud; et, cela arrive.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 56, 'Hypocrites! Vous savez bien discerner l\'aspect de la terre et du ciel comment donc ne savez-vous pas discerner ce temps-ci?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 57, 'Et pourquoi ne jugez-vous pas aussi, par vous-mêmes, de ce qui est juste?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 58, 'Quand tu vas devant le magistrat avec ton adversaire, tâche de t\'arranger avec lui en chemin, de peur qu\'il ne te traîne devant le juge, que le juge ne te livre à l\'exécuteur, et que l\'exécuteur ne te jette en prison.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 59, 'Je te dis que tu ne sortiras point de là, que tu n\'aies payé jusqu\'à la dernière pite.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 1, 'En ce même temps, quelques personnes, qui se trouvaient là, racontèrent à Jésus ce qui était arrivé aux Galiléens, dont Pilate avait mêlé le sang à celui de leurs sacrifices.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 2, 'Jésus, prenant la parole, leur dit: Pensez-vous que ces Galiléens fussent de plus grands pécheurs que tous les autres Galiléens, parce qu\'ils ont souffert ainsi?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 3, 'Non? vous dis-je; mais si vous ne vous repentez, vous périrez tous pareillement.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 4, 'Ou bien, ces dix-huit personnes, sur qui la tour de Siloé est tombée et qu\'elle a tuées, pensez-vous qu\'elles fussent plus coupables que tous les autres habitants de Jérusalem?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 5, 'Non, vous dis-je; mais si vous ne vous repentez, vous périrez tous également.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 6, 'Il disait aussi cette parabole: Un homme avait un figuier planté dans sa vigne; il vint y chercher du fruit et n\'en trouva point.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 7, 'Alors il dit au vigneron: Voilà trois ans que je viens chercher du fruit à ce figuier et que je n\'en trouve pas. Coupe-le; pourquoi occupe-t-il la terre inutilement?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 8, 'Le vigneron lui répondit: Seigneur, laisse-le encore cette année; je creuserai tout autour et j\'y mettrai du fumier.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 9, 'Peut-être qu\'à l\'avenir il portera du fruit; sinon tu le feras couper.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 10, 'Jésus enseignait dans une synagogue un jour de sabbat.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 11, 'Or, il y avait là une femme possédée d\'un esprit qui la rendait infirme depuis dix-huit ans; elle était courbée et ne pouvait pas du tout se redresser.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 12, 'Jésus, la voyant, l\'appela et lui dit: Femme, tu es délivrée de ton infirmité;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 13, 'et il lui imposa les mains. A l\'instant, elle se redressa, et elle se mit à rendre gloire à Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 14, 'Alors le chef de la synagogue, indigné de ce que Jésus avait fait cette guérison un jour de sabbat, prit la parole et, dit à la foule: Il y a six jours pendant lesquels on doit travailler venez donc ces jours-là pour être guéris, et non pas le jour du sabbat.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 15, 'Mais le Seigneur lui répondit: Hypocrites, chacun de vous, le jour du sabbat, ne détache-t-il pas de la crèche son boeuf ou son âne pour le mener boire?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 16, 'Et cette fille d\'Abraham, que Satan tenait liée depuis dix-huit ans, ne fallait-il pas la délivrer de ce lien le jour du sabbat?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 17, 'Comme il parlait ainsi, tons ses adversaires étaient confus, et tout le peuple se réjouissait de toutes les choses glorieuses qu\'il accomplissait.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 18, 'Et Jésus disait donc: A quoi ressemble le royaume de Dieu, et à quoi le comparerai-je?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 19, 'Il est semblable à un grain de moutarde, qu\'un homme a pris et a jeté dans son jardin; il a poussé, il est devenu un arbre et les oiseaux du ciel ont fait leurs nids dans ses branches.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 20, 'Il dit encore: A quoi comparerai-je le royaume de Dieu?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 21, 'Il est semblable à du levain qu\'une femme prend, et qu\'elle mêle à trois mesures de farine, pour faire lever toute la pâte.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 22, 'Jésus traversait les villes et les villages, en enseignant, tandis qu\'il se dirigeait vers Jérusalem.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 23, 'Quelqu\'un lui demanda: Seigneur, n\'y a-t-il qu\'un petit nombre de gens qui soient sauvés? Il leur répondit:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 24, 'Efforcez-vous d\'entrer par la porte étroite; car je vous le déclare, il y en a beaucoup qui chercheront à entrer, et ils ne le pourront pas.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 25, 'Et quand le maître de la maison se sera levé et aura fermé la porte, et que vous, qui serez restés dehors, vous vous mettrez à frapper et à dire: Seigneur, ouvre-nous! — il vous répondra: Je ne sais d\'où vous êtes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 26, 'Alors vous vous mettrez à dire: Nous avons mangé et bu en ta présence, et tu as enseigné sur nos places publiques.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 27, 'Et il répondra: Je vous le dis, je ne sais d\'où vous êtes; retirez-vous de moi, vous tous, ouvriers d\'iniquité!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 28, 'C\'est là qu\'il y aura des pleurs et, des grincements de dents, quand vous verrez Abraham, Isaac et Jacob, et tous les prophètes, dans le royaume de Dieu, et que vous serez jetés dehors.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 29, 'Il en viendra de l\'Orient et de l\'Occident, du Nord et du Midi, qui se mettront à table dans le royaume de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 30, 'Et voici qu\'il y en a des derniers qui seront les premiers; et il y en a des premiers qui seront les derniers.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 31, 'A ce moment-là, quelques pharisiens vinrent lui dire: Pars, éloigne-toi d\'ici Hérode veut te faire mourir.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 32, 'Il leur répondit: Allez dire à ce renard que je chasse les démons. J\'opère des guérisons aujourd\'hui et demain, et le troisième jour j\'achève ma vie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 33, 'Mais il faut que je marche aujourd\'hui, demain, et le jour suivant, parce qu\'il ne convient pas qu\'un prophète périsse hors de Jérusalem.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 34, 'Jérusalem, Jérusalem, toi qui tues les prophètes et qui lapides ceux qui te sont envoyés, combien de fois j\'ai voulu rassembler tes enfants, comme une poule rassemble sa couvée sous ses ailes, et vous ne l\'avez pas voulu!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 35, 'Voici que votre demeure vous sera laissée dans l\'abandon. Et je vous déclare que vous ne me verrez plus, jusqu\'à ce que vous disiez: «Béni soit celui qui vient au nom du Seigneur!»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 1, 'Un jour de sabbat, Jésus était entré dans la maison d\'un des principaux pharisiens pour prendre un repas, et ceux qui étaient là l\'observaient.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 2, 'Or, un homme hydropique se trouva devant lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 3, 'Jésus, prenant la parole, dit aux docteurs de la loi et aux pharisiens: Est-il permis de guérir le jour du sabbat, ou non?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 4, 'Et ils gardèrent le silence. Alors, prenant le malade, il le guérit et à le renvoya.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 5, 'Puis il leur dit: Lequel d\'entre vous, si son fils ou même son boeuf vient à tomber dans un puits, ne l\'en retire aussitôt le jour du sabbat?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 6, 'Et ils ne pouvaient rien répondre à cela.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 7, 'Ayant remarqué que les conviés choisissaient les premières places, il leur disait aussi cette parabole:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 8, 'Lorsqu\'on t\'invitera à des noces, ne te mets pas à la première place, de peur qu\'il ne se trouve parmi les conviés une personne plus considérable que toi,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 9, 'et que celui qui vous a invités, toi et lui, ne vienne te dire: Cède la place à celui-ci.! — et qu\'alors, tu n\'aies la honte d\'être mis à la dernière place.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 10, 'Mais quand tu seras invité, va te mettre à la dernière place, et lorsque celui qui t\'a invité viendra, il te dira: Mon ami, monte plus haut! Alors, cela sera pour toi un honneur aux yeux de tous ceux qui seront à table avec toi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 11, 'Car quiconque s\'élève sera abaissé, et quiconque s\'abaisse sera élevé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 12, 'Il disait aussi à celui qui l\'avait invité: Quand tu donnes un dîner ou un souper, n\'invite pas tes amis, ni tes frères, ni tes parents, ni des voisins riches, de peur qu\'ils ne t\'invitent à leur tour, et ne te rendent la pareille.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 13, 'Mais quand tu fais un festin, convie des pauvres, des estropiés, des boiteux et des aveugles.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 14, 'Tu seras heureux, parce qu\'ils ne peuvent pas te le rendre; et cela te sera rendu à la résurrection des justes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 15, 'Un des convives, ayant entendu ces paroles, lui dit: Heureux celui qui sera à table dans le royaume de Dieu!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 16, 'Mais Jésus lui répondit: Un homme fit un grand souper, et il y invita beaucoup de gens.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 17, 'A l\'heure du souper, il envoya son serviteur dire aux conviés: Venez; car tout est prêt.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 18, 'Mais tous, comme de concert, se mirent à s\'excuser. Le premier lui dit: J\'ai acheté une terre et je suis forcé d\'aller la voir; je te prie de m\'excuser.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 19, 'Un autre dit: J\'ai acheté cinq paires de boeufs, et je vais les essayer; je te prie de m\'excuser.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 20, 'Un autre dit: Je viens de me marier; ainsi, je ne puis y aller.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 21, 'Le serviteur, étant de retour, rapporta cela à son maître. Alors le père de famille, irrité, dit à son serviteur: Va vite sur les places et dans les rues de la ville, et amène ici les pauvres, les estropiés, les aveugles et les boiteux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 22, 'Le serviteur vint dire: Seigneur, on a fait ce que tu as commandé, et il y a encore de la place.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 23, 'Et le maître répondit au serviteur: Va dans les chemins et le long des haies, et contrains les gens d\'entrer, afin que ma maison soit remplie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 24, 'Car, je vous le déclare, aucun de ces hommes qui avaient été conviés ne goûtera de mon souper.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 25, 'Comme une grande foule accompagnait Jésus, il se tourna vers elle et lui dit:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 26, 'Si quelqu\'un vient à moi, et ne hait pas son père, sa mère, sa femme, ses enfants, ses frères, ses soeurs, et même sa propre vie, il ne peut être mon disciple.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 27, 'Et quiconque ne porte pas sa croix et ne me suit pas, ne peut être mon disciple.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 28, 'En effet, quel est celui d\'entre vous, qui, voulant bâtir une tour, ne commence d\'abord par s\'asseoir, et ne calcule la dépense, pour voir s\'il a de quoi aller jusqu\'au bout,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 29, '— de peur qu\'après avoir posé les fondements, il ne puisse achever la tour, et qu\'alors tous ceux qui le verront ne se mettent à se moquer de lui,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 30, 'en disant: Cet homme a commencé à bâtir, et il n\'a pu achever!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 31, 'Ou bien, quel est le roi qui, partant pour faire la guerre à un autre roi, ne commence par s\'asseoir, et n\'examine s\'il peut, avec dix mille hommes, aller à la rencontre de celui qui vient contre lui avec vingt mille?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 32, 'Autrement, pendant que celui-ci est encore loin, il lui envoie une ambassade pour demander la paix.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 33, 'Ainsi, quiconque d\'entre vous ne renonce pas à tout ce qu\'il possède, ne peut être mon disciple.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 34, 'C\'est une bonne chose que le sel; mais si le sel perd sa saveur, avec quoi l\'assaisonnera-t-on?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 35, 'Il n\'est bon ni pour la terre, ni pour le fumier; on le jette dehors. Que celui qui a des oreilles pour entendre, entende!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 1, 'Tous les péagers et les pécheurs s\'approchaient de Jésus pour l\'entendre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 2, 'Et les pharisiens et les scribes murmuraient, disant: Cet homme accueille des pécheurs et mange avec eux!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 3, 'Alors il leur dit cette parabole:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 4, 'Quel est l\'homme d\'entre vous, qui, ayant cent brebis, s\'il en perd une, ne laisse les quatre-vingt-dix-neuf au désert, pour aller chercher celle qui est perdue, jusqu\'à ce qu\'il l\'ait trouvée?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 5, 'Et quand il l\'a trouvée, il la met tout joyeux sur ses épaules;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 6, 'puis, arrivé à la maison, il appelle ses amis et ses voisins, et il leur dit: Réjouissez-vous avec moi, car j\'ai trouvé ma brebis qui était perdue.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 7, 'Je vous dis qu\'il y aura, de même, plus de joie dans le ciel pour un seul pécheur qui se repent, que pour quatre-vingt-dix-neuf justes qui n\'ont pas besoin de repentance.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 8, 'Ou bien, quelle est la femme qui, ayant dix drachmes, si elle en perd une, n\'allume une lampe, ne balaie la maison et ne cherche avec soin, jusqu\'à ce qu\'elle l\'ait trouvée?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 9, 'Et quand elle l\'a trouvée, elle appelle ses amies et ses voisines, et elle leur dit: Réjouissez-vous avec moi; car j\'ai trouvé la drachme que j\'avais perdue.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 10, 'De même, je vous le déclare, il y a de la joie, devant les anges de Dieu, pour un seul pécheur qui se repent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 11, 'Il dit encore: Un homme avait deux fils.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 12, 'Le plus jeune dit à son père: Mon père, donne-moi la part de bien qui doit me revenir. Et le père leur partagea son bien.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 13, 'Peu de jours après, le plus jeune fils, ayant tout ramassé, partit pour un pays éloigné, et il y dissipa son bien en vivant dans la débauche.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 14, 'Après qu\'il eut tout dépensé, une grande famine survint dans ce pays; et il commença à être dans l\'indigence.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 15, 'Alors il s\'en alla et se mit au service d\'un des habitants du pays, qui l\'envoya dans ses champs pour paître les pourceaux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 16, 'Et il aurait bien voulu se rassasier des caroubes que les pourceaux mangeaient; mais personne ne lui en donnait.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 17, 'Étant donc rentré en lui-même, il se dit: Combien de gens aux gages de mon père ont du pain en abondance, et moi, ici, je meurs de faim!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 18, 'Je me lèverai, j\'irai vers mon père, et je lui dirai: Mon père, j\'ai péché contre le ciel et contre toi:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 19, 'je ne suis plus digne d\'être appelé ton fils: traite-moi comme l\'un de tes mercenaires.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 20, 'Il se leva donc et alla vers son père. Comme il était encore loin, son père le vit et fut ému de compassion; et, courant à lui, il se jeta à son cou et l\'embrassa.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 21, 'Alors son fils lui dit: Mon père, j\'ai péché contre le ciel et contre toi; je ne suis plus digne d\'être appelé ton fils.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 22, 'Mais le père dit à ses serviteurs: Apportez vite la plus belle robe, et l\'en revêtez; mettez-lui un anneau au doigt et des souliers aux pieds.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 23, 'Amenez le veau gras, et tuez-le.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 24, 'Mangeons et réjouissons-nous, parce que mon fils, que voici, était mort, et il est revenu à la vie; il était perdu et il est retrouvé. Puis ils commencèrent à se réjouir.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 25, 'Or, le fils aîné était dans les champs. Comme il revenait et qu\'il approchait de la maison, il entendit la musique et les danses.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 26, 'Il appela donc un des domestiques et lui demanda ce que c\'était.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 27, 'Celui-ci lui dit: Ton frère est de retour et ton père a tué le veau gras, parce qu\'il l\'a retrouvé en bonne santé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 28, 'Il en fut irrité, et il ne voulait pas entrer. Son père sortit donc et le supplia d\'entrer.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 29, 'Mais il répondit à son père: Voilà tant d\'années que je te sers, sans avoir jamais désobéi à tes ordres, et jamais tu ne m\'as donné un chevreau pour me réjouir avec mes amis.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 30, 'Mais quand ton fils, que voilà, qui a mangé ton bien avec des femmes de mauvaise vie, est revenu, tu as tué pour lui le veau gras!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 31, 'Le père lui dit: Mon enfant, tu es toujours avec moi, et tout ce que j\'ai est à toi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 32, 'Mais il fallait bien faire un festin et se réjouir, parce que ton frère, que voilà, était mort, et il est revenu à la vie; il était perdu, et il est retrouvé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 1, 'Jésus disait aussi à ses disciples: Un homme riche avait un économe, qui fut accusé auprès de lui de dissiper ses biens.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 2, 'Il le fit venir et lui dit: Qu\'est-ce que j\'entends dire de toi? Rends compte de ton administration; car tu ne pourras plus désormais administrer mes biens.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 3, 'L\'économe se dit en lui-même: Que ferai-je, puisque mon maître m\'ôte mon emploi? Travailler la terre, je n\'en ai pas la force; et j\'ai honte de mendier.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 4, 'Je sais ce que je ferai, afin que, quand j\'aurai été renvoyé de mon emploi, il y ait des gens qui me reçoivent dans leurs maisons.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 5, 'Alors il fit venir séparément chacun des débiteurs de son maître, et il dit au premier: Combien dois-tu à mon maître?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 6, 'Le débiteur répondit: Cent mesures d\'huile. L\'économe lui dit: Prends ton billet; assieds-toi là, et écris vite: Cinquante.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 7, 'Il dit ensuite à un autre: Et toi, combien dois-tu? Celui-ci répondit: Cent mesures de froment. L\'économe lui dit: Prends ton billet, et écris: Quatre-vingts.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 8, 'Le maître loua l\'économe infidèle de ce qu\'il avait agi avec prudence; car les enfants de ce siècle, dans leurs rapports avec les hommes de leur génération, sont plus prudents que les enfants de lumière.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 9, 'Et moi, je vous le dis: Faites-vous des amis avec les richesses injustes, afin que, lorsqu\'elles viendront à vous manquer, ils vous reçoivent dans les tabernacles éternels.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 10, 'Celui qui est fidèle dans les plus petites choses est aussi fidèle dans les grandes; et celui qui est injuste dans les plus petites choses est aussi injuste dans les grandes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 11, 'Si donc vous n\'avez pas été fidèles dans les richesses injustes, qui vous confiera les véritables?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 12, 'Et si vous n\'avez pas été fidèles dans ce qui est à autrui, qui vous donnera ce qui est à vous?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 13, 'Nul serviteur ne peut servir deux maîtres; car, ou il haïra l\'un et aimera l\'autre, ou il s\'attachera à l\'un et méprisera l\'autre. Vous ne pouvez servir Dieu et Mammon.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 14, 'Les pharisiens, qui aimaient l\'argent, entendaient tout cela, et ils se moquaient de lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 15, 'Il leur dit: Vous vous faites passer pour justes devant les hommes, mais Dieu connaît vos coeurs; car ce qui est élevé aux yeux des hommes est une abomination devant Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 16, 'La loi et les prophètes ont duré jusqu\'à Jean; depuis lors, le royaume de Dieu est annoncé, et chacun y entre par la violence.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 17, 'Il est plus facile que le ciel et la terre passent, qu\'il ne l\'est qu\'un seul trait de lettre de la loi vienne à tomber.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 18, 'Quiconque répudie sa femme et en épouse une autre, commet un adultère, et celui qui épouse la femme répudiée par son mari, commet un adultère.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 19, 'Il y avait un homme riche, qui était vêtu de pourpre et de lin fin, et qui se traitait bien et magnifiquement tous les jours.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 20, 'Il y avait aussi un pauvre, nommé Lazare, couché à la porte du riche et couvert d\'ulcères.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 21, 'Il aurait bien voulu se rassasier de ce qui tombait de la table du riche; et même, les chiens venaient lécher ses ulcères.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 22, 'Or, il arriva que le pauvre mourut, et il fut porté par les anges dans le sein d\'Abraham; le riche mourut aussi, et il fut enseveli.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 23, 'Étant dans l\'enfer et en proie aux tourments, il leva les yeux et vit de loin Abraham, et Lazare dans son sein.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 24, 'Alors il s\'écria: Père Abraham, aie pitié de moi et envoie Lazare, afin qu\'il trempe dans l\'eau le bout de son doigt et me rafraîchisse la langue; car je souffre beaucoup dans cette flamme.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 25, 'Abraham lui répondit: Mon enfant, souviens-toi que tu as eu tes biens pendant ta vie, tandis que Lazare a eu des maux; maintenant, ici, il est consolé, et toi, tu es dans les tourments.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 26, 'D\'ailleurs, entre nous et vous s\'ouvre un grand abîme, de sorte que ceux qui voudraient aller d\'ici vers vous ne le peuvent, non plus que ceux qui voudraient passer de là vers nous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 27, 'Le riche dit: Je te prie donc, père, d\'envoyer Lazare dans la maison de mon père,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 28, '— car j\'ai cinq frères, — pour qu\'il leur atteste ces choses, de peur qu\'eux aussi ne viennent dans ce lieu de tourments.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 29, 'Abraham lui répondit: Ils ont Moïse et les prophètes; qu\'ils les écoutent!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 30, 'Le riche reprit: Non, père Abraham; mais si quelqu\'un des morts va vers eux, ils se repentiront.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 31, 'Mais Abraham lui dit: S\'ils n\'écoutent pas Moïse et les prophètes, ils ne seraient pas non plus persuadés, quand même quelqu\'un des morts ressusciterait.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 1, 'Jésus dit aussi à ses disciples: Il est impossible qu\'il n\'arrive pas des scandales; mais malheur à celui par qui ils arrivent!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 2, 'Il vaudrait mieux pour lui qu\'on lui mît au cou une meule de moulin et qu\'on le jetât dans la mer, que d\'être en scandale à un seul de ces petits.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 3, 'Prenez garde à vous-mêmes. Si ton frère a péché, reprends-le; et s\'il se repent, pardonne-lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 4, 'S\'il a péché contre toi sept fois dans un jour, et que sept fois il revienne à toi et te dise: Je me repens. — tu lui pardonneras.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 5, 'Les apôtres dirent au Seigneur: Augmente-nous la foi!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 6, 'Le Seigneur répondit: Si vous aviez de la foi, gros comme un grain de moutarde, vous diriez à ce mûrier: Déracine-toi, et va te planter dans la mer; et il vous obéirait.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 7, 'Qui devons, ayant un serviteur employé à labourer ou à faire paître les troupeaux, lui dira, à son retour des champs: Viens tout de suite te mettre à table?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 8, 'Ne lui dira-t-il pas au contraire: Prépare-moi à souper, ceins-toi pour me servir, jusqu\'à ce que j\'aie mangé et bu; et, après cela, tu mangeras et tu boiras.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 9, 'Saura-t-il gré à ce serviteur d\'avoir fait ce qui lui était commandé?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 10, 'Vous aussi de même, quand vous aurez fait tout ce qui vous est commandé, dites: Nous sommes des serviteurs inutiles. Ce que nous avons fait, nous devions le faire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 11, 'Comme il allait à Jérusalem, il passait sur les confins de la Samarie et de la Galilée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 12, 'Au moment où il entrait dans un village, dix lépreux vinrent à sa rencontre, et, se tenant à distance,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 13, 'ils élevèrent la voix et dirent; Jésus, Maître, aie pitié de nous!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 14, 'Les ayant vus, il leur dit: Allez, montrez-vous aux sacrificateurs. Et il arriva qu\'en y allant, ils furent rendus nets.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 15, 'L\'un d\'entre eux, voyant qu\'il était guéri, revint sur ses pas, glorifiant Dieu à haute voix.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 16, 'Et il se jeta aux pieds de Jésus, le visage contre terre, en lui rendant grâces. Or, c\'était un Samaritain.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 17, 'Alors Jésus prit la parole et dit: Les dix n\'ont-ils pas été guéris? Et les neuf autres, où sont-ils?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 18, 'Il ne s\'est trouvé que cet étranger qui soit revenu pour donner gloire à Dieu!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 19, 'Et il lui dit: Lève-toi, va, ta foi t\'a sauvé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 20, 'Les pharisiens lui ayant demandé quand viendrait le royaume de Dieu, Jésus leur répondit: Le royaume de Dieu ne vient pas de manière à frapper les regards,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 21, 'et l\'on ne dira pas: Il est ici! ou bien: Il est là! Car voici que le royaume de Dieu est au dedans de vous!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 22, 'Il dit aussi aux disciples: Le temps viendra où vous désirerez voir un seul des jours du Fils de l\'homme, et vous ne le verrez point.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 23, 'Des gens vous diront: Le voici! ou: Le voilà! N\'y allez pas; ne les suivez pas!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 24, 'Car, de même que l\'éclair, quand il brille, resplendit d\'une extrémité du ciel jusqu\'à l\'autre, il en sera ainsi du Fils de l\'homme en son jour.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 25, 'Mais il faut auparavant qu\'il souffre beaucoup, et qu\'il soit rejeté par cette génération.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 26, 'Ce qui arriva du temps de Noé, arrivera également aux jours du Fils de l\'homme:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 27, 'On mangeait, on buvait, on prenait et on donnait en mariage, jusqu\'au jour où Noé entra dans l\'arche, et le déluge vint, qui les fit tous périr.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 28, 'De même aussi, aux jours de Lot, on mangeait, on buvait, on achetait, on vendait, on plantait, on bâtissait;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 29, 'et le jour où Lot sortit de Sodome, il tomba du ciel une pluie de feu et de soufre qui les fit tous périr.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 30, 'Il en sera de même au jour où le Fils de l\'homme sera manifesté.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 31, 'En ce jour-là, que celui qui sera sur le toit et qui aura ses effets dans la maison, ne descende pas pour les emporter; de même, que celui qui sera aux champs ne revienne point sur ses pas.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 32, 'Souvenez-vous de la femme de Lot!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 33, 'Celui qui cherchera à sauver sa vie, la perdra: et celui qui la perdra, la retrouvera.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 34, 'Je vous le déclare, en cette nuit-là, deux hommes seront dans le même lit; l\'un sera pris et l\'autre laissé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 35, 'Deux femmes moudront ensemble; l\'une sera prise et l\'autre laissée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 36, '[Deux hommes seront aux champs; l\'un sera pris et l\'autre laissé].');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 37, 'Alors, prenant la parole, ils lui dirent: Seigneur, où sera-ce? Il leur répondit: Où sera le corps, là s\'assembleront les aigles.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 1, 'Jésus leur raconta une parabole, pour montrer qu\'il faut prier toujours, sans jamais se lasser.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 2, 'Il dit: Il y avait dans une ville un juge qui ne craignait point Dieu, et qui n\'avait d\'égards pour aucun homme.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 3, 'Il y avait aussi dans cette ville une veuve, qui venait à lui et lui disait: Fais-moi justice de ma partie adverse.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 4, 'Pendant longtemps, il ne le voulut pas. Mais ensuite, il se dit en lui-même: Quoique je ne craigne pas Dieu et que je n\'aie d\'égards pour aucun homme,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 5, 'néanmoins, comme cette veuve m\'importune, je lui ferai justice, afin qu\'elle ne vienne pas toujours me rompre la tête.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 6, 'Puis le Seigneur ajouta: Vous entendez ce que dit le juge inique?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 7, 'Et Dieu ne ferait pas justice à ses élus, qui crient à lui jour et nuit, et il tarderait à les secourir!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 8, 'Je vous dis qu\'il leur fera prompte justice. Mais quand le Fils de l\'homme viendra, trouvera-t-il la foi sur la terre?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 9, 'Il dit aussi cette parabole, en vue de certaines personnes qui se flattaient d\'être justes et qui méprisaient les autres:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 10, 'Deux hommes montèrent au temple pour prier; l\'un était pharisien, et l\'autre était péager.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 11, 'Le pharisien, se tenant debout, priait ainsi en lui-même: Dieu, je te rends grâces de ce que je ne suis pas comme le reste des hommes, qui sont rapaces, injustes, adultères, ni même comme ce péager.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 12, 'Je jeûne deux fois la semaine; je donne la dîme de tous mes revenus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 13, 'Le péager, se tenant éloigné, n\'osait pas même lever les yeux au ciel; mais il se frappait la poitrine, en disant: O Dieu, sois apaisé envers moi, qui suis un pécheur!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 14, 'Je vous le déclare, celui-ci s\'en retourna justifié dans sa maison plutôt que l\'autre; car quiconque s\'élève sera abaissé, et quiconque s\'abaisse sera élevé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 15, 'On lui présenta aussi des petits enfants, afin qu\'il les touchât. Les disciples, voyant cela, reprenaient ceux qui les présentaient.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 16, 'Mais Jésus les appela à lui, en disant: Laissez venir à moi les petits enfants, et ne les en empêchez point; car le royaume de Dieu est pour ceux qui leur ressemblent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 17, 'En vérité, je vous le déclare, quiconque ne recevra pas le royaume de Dieu comme un petit enfant, n\'y entrera pas.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 18, 'Alors l\'un des principaux du pays demanda à Jésus: Mon bon Maître, que dois-je faire pour hériter la vie éternelle?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 19, 'Jésus lui répondit: Pourquoi m\'appelles-tu bon? Il n\'y a qu\'un seul bon, c\'est Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 20, 'Tu connais les commandements: «Tu ne commettras point d\'adultère; tu ne tueras point; tu ne déroberas point; tu ne diras point de faux témoignage; honore ton père et ta mère.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 21, 'Cet homme répondit: J\'ai observé toutes ces choses dès ma jeunesse.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 22, 'Quand Jésus eut entendu cela, il lui dit: Il te manque encore une chose; vends tout ce que tu as et distribue-le aux pauvres, et tu auras un trésor dans les cieux. Viens alors, et suis-moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 23, 'Mais lui, ayant entendu ces paroles, devint tout triste; car il était fort riche.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 24, 'Jésus, le voyant tout triste, dit: Qu\'il est difficile à ceux qui ont des richesses d\'entrer dans le royaume de Dieu!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 25, 'Il est plus facile à un chameau de passer par le trou de l\'aiguille, qu\'il ne l\'est à un riche d\'entrer dans le royaume de Dieu!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 26, 'Ceux qui l\'entendaient, lui dirent: Et qui peut donc être sauvé?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 27, 'Il leur répondit: Ce qui est impossible aux hommes est possible à Dieu!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 28, 'Pierre dit alors: Pour nous, nous avons quitté ce que nous possédions, et nous t\'avons suivi!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 29, 'Jésus leur répondit: En vérité, je vous le déclare, tout homme qui aura quitté maison, ou femme, ou frères, ou parents, ou enfants, à cause du royaume de Dieu');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 30, 'recevra beaucoup plus dans le temps présent, et, dans le siècle à venir, la vie éternelle.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 31, 'Ensuite Jésus prit à part les Douze, et il leur dit: Voici que nous montons à Jérusalem, et toutes les choses qui ont été écrites par les prophètes au sujet du Fils de l\'homme, s\'accompliront.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 32, 'Car il sera livré aux Païens; on se moquera de lui, on l\'outragera, on crachera sur lui,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 33, 'et, après l\'avoir battu de verges, on le fera mourir. Et le troisième jour, il ressuscitera.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 34, 'Mais ils ne comprirent rien à cela: le sens de ces paroles leur était caché, et ils ne saisissaient point ce que Jésus leur disait.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 35, 'Comme Jésus approchait de Jérico, un aveugle était assis au bord du chemin et demandait l\'aumône.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 36, 'Entendant la foule qui passait, il s\'informa de ce que c\'était.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 37, 'On lui répondit: C\'est Jésus de Nazareth qui passe.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 38, 'Alors il cria: Jésus, fils de David, aie pitié de moi!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 39, 'Et ceux qui allaient devant le reprenaient pour le faire taire; mais il criait encore plus fort: Fils de David, aie pitié de moi!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 40, 'Jésus, s\'étant arrêté, ordonna qu\'on le lui amenât; et quand l\'aveugle se fut approché, il lui demanda:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 41, 'Que veux-tu que je te fasse? Il répondit: Seigneur, que je recouvre la vue.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 42, 'Jésus lui dit: Recouvre la vue; ta foi t\'a guéri!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 43, 'A l\'instant, il recouvra la vue, et il suivait Jésus, glorifiant Dieu. Tout le peuple, voyant cela, donna gloire à Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 1, 'Jésus, étant entré dans Jérico, passait par la ville.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 2, 'Il y avait là un homme appelé Zachée; c\'était le chef des péagers, et il était riche.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 3, 'Il cherchait à voir qui était Jésus, mais il ne le pouvait pas à cause de la foule, parce qu\'il était de petite taille.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 4, 'Il courut donc en avant et monta sur un sycomore pour voir Jésus, parce qu\'il devait passer par là.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 5, 'Jésus, arrivé à cet endroit, leva les yeux et lui dit: Zachée, hâte-toi de descendre; car il faut que je demeure aujourd\'hui dans ta maison.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 6, 'Zachée se hâta de descendre et reçut Jésus avec joie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 7, 'Voyant cela, tous murmuraient et disaient: Il est entré chez un pécheur pour y loger!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 8, 'Mais Zachée, se tenant debout devant le Seigneur, lui dit: Seigneur, voici que je donne la moitié de mes biens aux pauvres, et si j\'ai fait tort à quelqu\'un en quoi que ce soit, je lui rends quatre fois autant.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 9, 'Alors Jésus lui dit: Aujourd\'hui le salut est entré dans cette maison, parce que celui-ci est aussi un fils d\'Abraham.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 10, 'Car le Fils de l\'homme est venu chercher et sauver ce qui est perdu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 11, 'Comme on écoutait ces paroles, Jésus ajouta une parabole, parce qu\'il était près de Jérusalem, et qu\'on croyait que le royaume de Dieu allait apparaître soudain.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 12, 'Il dit donc: Un homme de haute naissance s\'en alla dans un pays éloigné, pour être investi de l\'autorité royale et revenir ensuite.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 13, 'Il appela dix de ses serviteurs, leur donna dix mines, et il leur dit: Faites-les valoir jusqu\'à ce que je revienne.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 14, 'Mais les gens de son pays le haïssaient; et ils envoyèrent une ambassade après lui, pour dire: Nous ne voulons pas que celui-ci règne sur nous!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 15, 'Lorsqu\'il fut de retour, après avoir été investi de l\'autorité royale, il fit venir ses serviteurs auxquels il avait donné l\'argent, pour savoir combien chacun lui avait fait rapporter.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 16, 'Le premier se présenta et dit: Seigneur, ta mine a produit dix autres mines.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 17, 'Et il lui dit: Cela va bien, bon serviteur; puisque tu as été fidèle en très peu de chose, tu auras le gouvernement de dix villes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 18, 'Le second vint et dit: Seigneur, ta mine a produit cinq mines.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 19, 'Il lui dit aussi: Et toi, commande à cinq villes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 20, 'Un autre vint et dit: Seigneur, voici ta mine que j\'ai gardée, enveloppée dans un linge;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 21, 'car je te craignais, parce que tu es un homme dur; tu prends ce que tu n\'as pas placé, et tu moissonnes ce que tu n\'as pas semé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 22, 'Son maître lui répondit: Méchant serviteur, je te jugerai sur tes propres paroles. Tu savais que je suis un homme dur, qui prend ce qu\'il n\'a pas placé, et qui moissonne ce qu\'il n\'a pas semé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 23, 'Pourquoi donc n\'as-tu pas mis mon argent dans une banque? A mon retour, je l\'aurais retiré avec l\'intérêt.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 24, 'Et il dit à ceux qui étaient présents: Otez-lui la mine, et donnez-la à celui qui a les dix mines.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 25, 'Ils lui répondirent: Seigneur, il a dix mines!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 26, '— Je vous le déclare, on donnera à celui qui a; mais à celui qui n\'a pas, cela même qu\'il a lui sera ôté.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 27, 'Quant à mes ennemis, ceux qui n\'ont pas voulu que je règne sur eux, amenez-les ici et égorgez-les en ma présence.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 28, 'Après avoir dit cela, Jésus allait devant eux, montant à Jérusalem.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 29, 'Lorsqu\'il fut arrivé près de Bethphagé et de Béthanie, vers la montagne appelée montagne des Oliviers, il envoya deux de ses disciples,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 30, 'et il leur dit: Allez au village qui est devant vous; en y entrant, vous trouverez un ânon attaché, que personne n\'a jamais monté; détachez-le et amenez-le-moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 31, 'Si quelqu\'un vous demande pourquoi vous le détachez, vous lui répondrez: Le Seigneur en a besoin.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 32, 'Ceux qui étaient envoyés partirent, et ils trouvèrent les choses comme Jésus le leur avait dit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 33, 'Pendant qu\'ils détachaient l\'ânon, ceux à qui il appartenait leur dirent: Pourquoi détachez-vous cet ânon?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 34, 'Ils répondirent: Le Seigneur en a besoin.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 35, 'Et ils l\'amenèrent à Jésus. Puis, ayant mis leurs vêtements sur l\'ânon, ils y firent monter Jésus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 36, 'Comme il s\'avançait, les gens étendaient leurs vêtements sur le chemin.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 37, 'Et lorsqu\'il approcha de la descente de la montagne des Oliviers, toute la multitude des disciples, transportée de joie, se mit à louer Dieu, à haute voix, de tous les miracles qu\'ils avaient vus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 38, 'Ils disaient: Béni soit le Roi qui vient au nom du Seigneur! Paix dans le ciel, et gloire dans les lieux très hauts!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 39, 'Alors quelques-uns des pharisiens, qui étaient dans la foule, lui dirent: Maître, reprends tes disciples!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 40, 'Il leur répondit: Je vous le déclare: s\'ils se taisent, les pierres crieront!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 41, 'Quand il fut près de la ville, en la voyant, Jésus pleura sur elle, et il dit:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 42, 'Si tu avais reconnu, toi aussi, au moins en ce jour, ce qui pouvait te donner la paix! Mais maintenant ces choses sont cachées à tes yeux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 43, 'Car des jours viendront sur toi où tes ennemis t\'environneront de tranchées, t\'investiront et te serreront de toutes parts.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 44, 'Ils te détruiront entièrement, toi et tes enfants au milieu de toi; et ils ne te laisseront pas une pierre sur une autre pierre, parce que tu n\'as point reconnu le temps où tu as été visitée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 45, 'Quand il fut entré dans le temple, il se mit à chasser ceux qui y vendaient en leur disant:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 46, 'Il est écrit: «Ma maison sera une maison de prière!» Et vous, vous en avez fait une caverne de voleurs.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 47, 'Il enseignait chaque jour dans le temple. Les principaux sacrificateurs, les scribes et les premiers du peuple cherchaient à le faire mourir;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 48, 'mais ils ne savaient comment s\'y prendre, car tout le peuple, en l\'écoutant, était suspendu à ses lèvres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 1, 'Un de ces jours-là, comme Jésus enseignait le peuple dans le temple et qu\'il annonçait l\'Évangile, les principaux sacrificateurs et les scribes survinrent avec les anciens,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 2, 'et lui parlèrent ainsi: Dis-nous par quelle autorité tu fais ces choses, ou qui est celui qui t\'a donné cette autorité?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 3, 'Il leur répondit: Je vous poserai, moi aussi, une question.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 4, 'Dites-moi: Le baptême de Jean venait-il du ciel ou des hommes?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 5, 'Or, ils raisonnaient ainsi entre eux: Si nous disons: Du ciel, — il nous dira: Pourquoi donc n\'avez-vous pas cru à sa parole?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 6, 'Et si nous disons: Des hommes, — tout le peuple nous lapidera; car il est persuadé que Jean était un prophète.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 7, 'Ils répondirent donc qu\'ils ne savaient d\'où il venait.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 8, 'Alors Jésus leur dit: Et moi non plus, je ne vous dirai point par quelle autorité je fais ces choses.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 9, 'Jésus se mit à dire au peuple cette parabole; Un homme planta une vigne; il la loua à des vignerons, puis il quitta le pays pour un temps assez long.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 10, 'La saison étant venue, il envoya auprès des vignerons un serviteur, chargé de recevoir du fruit de la vigne; mais les vignerons, l\'ayant battu, le renvoyèrent les mains vides.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 11, 'Il envoya encore un autre serviteur; mais, après l\'avoir battu aussi et outragé, ils le renvoyèrent les mains vides.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 12, 'Il en envoya encore un troisième; mais ils le blessèrent aussi et le chassèrent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 13, 'Alors le maître de la vigne dit: Que ferai-je? J\'enverrai mon fils bien-aimé; peut-être le respecteront-ils!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 14, 'Mais quand les vignerons le virent, ils raisonnèrent ainsi entre eux: C\'est l\'héritier; tuons-le, afin que l\'héritage soit à nous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 15, 'Et l\'ayant jeté hors de la ville, ils le tuèrent. Que leur fera donc le maître de la vigne?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 16, 'Il viendra et fera périr ces vignerons, et il donnera la vigne à d\'autres. A l\'ouïe de ces paroles, ils dirent: A Dieu ne plaise!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 17, 'Alors, les regardant, Jésus leur dit: Que signifie donc ce qui est écrit: «La pierre rejetée par ceux qui bâtissaient est devenue la pierre de l\'angle»?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 18, 'Quiconque tombera sur cette pierre sera brisé, et celui sur qui elle tombera, sera écrasé par elle.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 19, 'A l\'heure même, les principaux sacrificateurs et les scribes cherchèrent à mettre la main sur lui; car ils comprenaient qu\'il avait dit cette parabole contre eux. Mais ils craignirent le peuple.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 20, 'Alors ils se mirent à l\'observer de près, et ils lui envoyèrent des espions qui feignaient d\'être des gens de bien, pour le surprendre dans ses paroles, afin de le livrer aux autorités et au pouvoir du gouverneur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 21, 'Ces gens lui posèrent cette question: Maître, nous savons que tu parles et enseignes avec droiture, et que, sans faire acception de personne, tu enseignes la voie de Dieu en toute vérité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 22, 'Nous est-il permis de payer l\'impôt à César ou non?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 23, 'Mais Jésus, discernant leur ruse, leur répondit:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 24, 'Montrez-moi un denier. De qui porte-t-il l\'effigie et l\'inscription? Ils répondirent: De César.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 25, 'Alors il leur dit: Rendez donc à César ce qui est à César, et à Dieu ce qui est à Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 26, 'Ils ne purent le prendre en faute pour la parole qu\'il avait dite devant le peuple; et, étonnés de sa réponse, ils gardèrent le silence.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 27, 'Alors quelques-uns des sadducéens, qui prétendent qu\'il n\'y a point de résurrection, s\'approchèrent et lui firent cette question:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 28, 'Maître, Moïse nous a donné cette loi: «Si un homme a un frère marié venant à mourir sans enfants, il épousera la veuve et suscitera une postérité à son frère»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 29, 'Or, il y avait sept frères. Le premier ayant épousé une femme, mourut sans enfants.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 30, 'Le second l\'épousa aussi, puis le troisième,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 31, 'et de même tous les sept; mais ils moururent sans laisser d\'enfants.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 32, 'Enfin la femme mourut aussi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 33, 'Duquel d\'entre eux sera-t-elle donc la femme, lors de la résurrection, puisque les sept l\'ont eue pour femme?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 34, 'Jésus leur dit: Les enfants de ce siècle se marient et sont donnés en mariage.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 35, 'Mais ceux qui ont été jugés dignes d\'avoir part au siècle à venir et à la résurrection des morts, ne se marient pas et ne sont pas donnés en mariage.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 36, 'Car ils ne peuvent plus mourir, parce qu\'ils sont semblables aux anges, et qu\'ils sont fils de Dieu, étant fils de la résurrection.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 37, 'Que les morts ressuscitent. Moïse l\'a fait connaître dans le récit du buisson, quand il nomme le Seigneur le Dieu d\'Abraham, le Dieu d\'Isaac et le Dieu de Jacob.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 38, 'Or, Dieu n\'est pas le Dieu des morts, mais des vivants; car ils sont tous vivants en lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 39, 'Quelques-uns des scribes, prenant la parole, lui dirent: Maître, tu as bien parlé!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 40, 'Et ils n\'osaient plus lui poser aucune question.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 41, 'Jésus leur demanda: Comment peut-on dire que le Christ est le fils de David,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 42, 'puisque David lui-même dit dans le livre des Psaumes: «Le Seigneur a dit à mon Seigneur: Assieds-toi à ma droite,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 43, 'jusqu\'à ce que j\'aie fait de tes ennemis ton marche-pied»?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 44, 'Ainsi, David l\'appelle Seigneur; comment donc est-il son fils?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 45, 'Comme tout le peuple l\'écoutait, il dit à ses disciples:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 46, 'Gardez-vous des scribes, qui se plaisent à se promener en robes longues, et qui aiment les salutations dans les places publiques, les premiers sièges dans les synagogues et les premières places dans les festins,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 47, 'qui dévorent les maisons des veuves, en affectant de faire de longues prières: le châtiment qu\'ils subiront n\'en sera que plus sévère.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 1, 'Jésus, levant les yeux, vit les riches qui mettaient leurs offrandes dans le tronc.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 2, 'Il vit aussi une pauvre veuve qui y mettait deux pites.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 3, 'Et il dit: En vérité, je vous le déclare, cette pauvre veuve a mis plus que tous les autres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 4, 'Car tous ceux-là, pour leurs offrandes, ont donné de leur superflu; mais celle-ci a donné de son indigence, tout ce qu\'elle avait pour vivre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 5, 'Quelques-uns parlaient du temple, des belles pierres et des dons qui l\'ornaient. Jésus dit:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 6, 'Les jours viendront où, de ce que vous regardez, il ne restera pas ici une pierre sur une autre pierre qui ne soit renversée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 7, 'Alors ils lui demandèrent: Maître, quand donc ces choses arriveront-elles, et à quel signe connaîtra-t-on qu\'elles sont sur le point d\'arriver?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 8, 'Il répondit: Prenez garde de ne pas vous laisser séduire; car plusieurs viendront en mon nom, disant: C\'est moi qui suis le Christ. Le moment approche! Ne les suivez pas!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 9, 'Et quand vous entendrez parler de guerres et de séditions, ne vous effrayez pas, car il faut que ces choses arrivent d\'abord; mais ce ne sera pas de sitôt la fin.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 10, 'Il leur dit aussi: Une nation s\'élèvera contre une autre nation, et un royaume contre un autre royaume.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 11, 'Il y aura de grands tremblements de terre, des famines et des pestes en divers lieux, des phénomènes effrayants et de grands signes dans le ciel.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 12, 'Mais avant tout cela, on mettra la main sur vous, on vous persécutera, on vous livrera aux synagogues, on vous mettra en prison; et vous serez traînés devant les rois et devant les gouverneurs, à cause de mon nom.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 13, 'Cela vous arrivera pour que vous rendiez témoignage.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 14, 'Mettez-vous donc bien dans l\'esprit de ne pas vous préoccuper de votre défense.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 15, 'En effet, je vous donnerai une parole pleine de sagesse, à laquelle tous vos adversaires ne pourront résister ni contredire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 16, 'Vous serez livrés même par vos pères et vos mères, par vos frères, vos parents et vos amis; et ils feront mourir plusieurs d\'entre vous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 17, 'Vous serez haïs de tous, à cause de mon nom.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 18, 'Mais il ne se perdra pas un cheveu de votre tête.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 19, 'C\'est par votre patience que vous sauverez vos âmes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 20, 'Or, quand vous verrez Jérusalem investie par des armées, sachez, à ce moment-là, que sa ruine approche.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 21, 'Que ceux qui seront alors dans la Judée s\'enfuient dans les montagnes; que ceux qui seront dans l\'intérieur de la ville en sortent, et que ceux qui seront dans les champs, ne se retirent pas dans la ville.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 22, 'Car ce sont là les jours de la vengeance, afin que s\'accomplisse tout ce qui est écrit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 23, 'Malheur aux femmes qui seront enceintes, et à celles qui allaiteront en ces jours-là! Car il y aura une grande détresse dans le pays et une grande colère contre ce peuple.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 24, 'Ils tomberont sous le tranchant de l\'épée, ils seront emmenés captifs parmi toutes les nations; et Jérusalem sera foulée aux pieds par les Païens, jusqu\'à ce que les temps des nations païennes soient accomplis.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 25, 'Il y aura des signes dans le soleil, dans la lune et dans les étoiles; et, sur la terre, l\'angoisse s\'emparera des nations troublées par le fracas de la mer et des flots.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 26, 'Les hommes rendront l\'âme de frayeur, dans l\'attente des maux qui viendront sur le monde; car les puissances des cieux seront ébranlées.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 27, 'Alors on verra le Fils de l\'homme venant sur une nuée, avec une grande puissance et une grande gloire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 28, 'Lorsque ces choses commenceront à arriver, redressez-vous et levez vos têtes, parce que votre délivrance est proche.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 29, 'Puis il leur dit une parabole: Voyez le figuier et tous les autres arbres;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 30, 'quand ils commencent à pousser, vous savez de vous-mêmes, en les voyant, que l\'été est déjà proche.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 31, 'De même, lorsque vous verrez ces choses arriver, sachez que le royaume de Dieu est proche.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 32, 'En vérité, je vous le dis, cette génération ne passera pas, que toutes ces choses n\'arrivent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 33, 'Le ciel et la terre passeront; mais mes paroles ne passeront point.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 34, 'Prenez donc garde à vous-mêmes, de peur que vos coeurs ne soient appesantis par les excès de la bonne chère, par l\'ivresse et par les inquiétudes, de cette vie, et que ce jour-là ne vienne subitement sur vous,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 35, 'comme un filet; car il surprendra tous ceux qui habitent la surface de la terre entière.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 36, 'Veillez donc en tout temps et priez, afin que vous puissiez échapper à tous ces maux qui doivent arriver, et subsister devant le Fils de l\'homme.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 37, 'Or, Jésus enseignait dans le temple pendant le jour; mais le soir, il sortait et passait les nuits sur la montagne appelée montagne des Oliviers.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 38, 'Et, dès le point du jour, tout le peuple venait à lui dans le temple pour l\'écouter.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 1, 'La fête des pains sans levain, appelée la Pâque, approchait.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 2, 'Et les principaux sacrificateurs et les scribes cherchaient comment ils pourraient faire mourir Jésus; car ils craignaient le peuple.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 3, 'Or, Satan entra dans Judas, nommé Iscariote, qui était du nombre des Douze.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 4, 'Judas alla trouver les principaux sacrificateurs et les chefs des gardes, pour s\'entendre avec eux sur les moyens de le leur livrer.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 5, 'Ceux-ci, remplis de joie, lui promirent de lui donner de l\'argent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 6, 'Il se mit d\'accord avec eux, et il cherchait une occasion favorable pour livrer Jésus à l\'insu de la foule.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 7, 'Le jour des pains sans levain, où l\'on devait immoler la Pâque, étant arrivé,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 8, 'Jésus envoya Pierre et Jean, et il leur dit: Allez nous préparer la Pâque, afin que nous la mangions.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 9, 'Ils lui dirent: Où veux-tu que nous la préparions?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 10, 'Il leur répondit: Lorsque vous entrerez dans la ville, vous rencontrerez un homme portant une cruche d\'eau; suivez-le dans la maison où il entrera,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 11, 'et dites au maître de la maison: Le Maître te fait dire: Où se trouve la salle dans laquelle je dois manger la Pâque avec mes disciples?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 12, 'Et il vous montrera une grande chambre haute, toute meublée; préparez-y ce qu\'il faut.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 13, 'Ils s\'en allèrent et trouvèrent les choses comme Jésus le leur avait dit; et ils préparèrent la Pâque.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 14, 'Quand l\'heure fut venue, il se mit à table, et les apôtres avec lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 15, 'Puis il leur dit: J\'ai fort désiré de manger cette Pâque avec vous, avant que je souffre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 16, 'Car, je vous le déclare, je ne la mangerai plus, jusqu\'à ce qu\'elle soit accomplie dans le royaume de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 17, 'Et, ayant pris une coupe et rendu grâces, il dit: Prenez ceci, et partagez-le entre vous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 18, 'Car, je vous le déclare, désormais je ne boirai plus du fruit de la vigne, jusqu\'à ce que le royaume de Dieu soit venu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 19, 'Puis il prit du pain, et, après avoir rendu grâces, il le rompit et le leur donna, en disant: Ceci est mon corps, qui est donné pour vous; faites ceci en mémoire de moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 20, 'De même, après avoir soupé, il leur donna la coupe, en disant: Cette coupe est la nouvelle alliance en mon sang, qui est répandu pour vous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 21, 'Au reste, la main de celui qui me trahit est près de moi: il est assis à cette table!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 22, 'En ce qui concerne le Fils de l\'homme, il s\'en va, conformément à ce qui a été arrêté; mais malheur à cet homme, par qui il est trahi!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 23, 'Alors ils se mirent à se demander les uns aux autres, quel était donc celui d\'entre eux qui ferait cela.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 24, 'Il s\'éleva aussi parmi eux une contestation, pour savoir lequel d\'entre eux devait être regardé comme le plus grand.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 25, 'Mais Jésus leur dit: Les rois des nations leur commandent en maîtres, et ceux qui exercent l\'autorité sur elles sont appelés bienfaiteurs.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 26, 'Pour vous, ne faites pas ainsi; mais, que le plus grand parmi vous soit comme le plus petit, et celui qui gouverne, comme celui qui sert.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 27, 'Car lequel est le plus grand, celui qui est à table, ou celui qui sert? N\'est-ce pas celui qui est à table? Moi pourtant, je suis au milieu de vous comme celui qui sert.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 28, 'Quant à vous, vous avez persévéré avec moi dans mes épreuves,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 29, 'et je dispose du royaume en votre faveur, comme mon Père en a disposé pour moi,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 30, 'afin que vous mangiez et que vous buviez à ma table dans mon royaume, et que vous soyez assis sur des trônes, jugeant les douze tribus d\'Israël.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 31, 'Simon, Simon, voici que Satan a demandé à vous passer au crible comme le blé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 32, 'Mais j\'ai prié pour toi, afin que ta foi ne défaille point. Toi donc, quand tu seras converti, affermis tes frères.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 33, 'Pierre lui dit: Seigneur, je suis prêt à aller avec toi, et en prison et à la mort!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 34, 'Jésus répondit: Pierre, je te le déclare, le coq ne chantera pas aujourd\'hui, que tu n\'aies par trois fois nié de me connaître.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 35, 'Puis il ajouta: Lorsque je vous ai envoyés sans bourse, sans sac et sans chaussures, avez-vous manqué de quelque chose? Ils répondirent: De rien.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 36, 'Mais maintenant, leur dit-il, que celui qui a une bourse, la prenne, et de même, celui qui a un sac; et que celui qui n\'a point d\'épée, vende son manteau et en achète une.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 37, 'Car, je vous le déclare, il faut que s\'accomplisse en ma personne ce qui est écrit: «Il a été mis au rang des malfaiteurs.» En effet, ce qui me concerne touche à sa fin.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 38, 'Ils dirent: Seigneur, voici deux épées. Il leur répondit: Cela suffit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 39, 'Puis, Jésus sortit et alla, selon sa coutume, à la montagne des Oliviers; et les disciples le suivirent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 40, 'Quand il fut arrivé en ce lieu, il leur dit: Priez, afin que vous ne tombiez pas dans la tentation.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 41, 'Alors il s\'éloigna d\'eux d\'un jet de pierre environ, et, s\'étant mis à genoux, il priait,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 42, 'disant: Père, si tu voulais éloigner de moi cette coupe! Toutefois, que ta volonté soit faite et non la mienne!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 43, 'Et un ange lui apparut du ciel, qui le fortifiait.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 44, 'Étant en agonie, il priait plus instamment, et sa sueur devint comme de grosses gouttes de sang qui tombaient à terre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 45, 'Après avoir prié, il se leva et revint vers les disciples, qu\'il trouva endormis de tristesse.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 46, 'Et il leur dit: Pourquoi dormez-vous? Levez-vous, et priez, afin que vous ne tombiez pas dans la tentation.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 47, 'Comme il parlait encore, une troupe parut. Celui qu\'on nommait Judas, l\'un des Douze, marchait devant elle, et il s\'approcha de Jésus pour lui donner un baiser.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 48, 'Jésus lui dit: Judas, tu trahis le Fils de l\'homme par un baiser!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 49, 'Alors ceux qui étaient avec lui, voyant ce qui allait arriver, lui dirent: Seigneur, frapperons-nous de l\'épée?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 50, 'Et l\'un d\'eux frappa le serviteur du souverain sacrificateur, et il lui emporta l\'oreille droite.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 51, 'Mais Jésus, prenant la parole, dit: Arrêtez un moment! Et, ayant touché l\'oreille de cet homme, il le guérit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 52, 'Puis Jésus dit aux principaux sacrificateurs, aux chefs des gardes du temple et aux anciens, qui étaient venus vers lui: Vous êtes sortis avec des épées et des bâtons, comme après un brigand.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 53, 'J\'étais tous les jours dans le temple avec vous, et vous n\'avez pas mis la main sur moi. Mais c\'est ici votre heure et la puissance des ténèbres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 54, 'Alors, ils le saisirent et l\'emmenèrent; et ils le firent entrer dans la maison du souverain sacrificateur, Pierre suivait de loin.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 55, 'Ils allumèrent du feu au milieu de la cour et s\'assirent ensemble; et Pierre s\'assit parmi eux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 56, 'Une servante, le voyant assis près du feu et le regardant attentivement, dit: Cet homme était aussi avec lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 57, 'Mais il renia Jésus, en disant: Femme, je ne le connais point!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 58, 'Un peu après, un autre, l\'ayant vu, lui dit: Toi aussi, tu es de ces gens-là! Pierre répondit à cet homme: Je n\'en suis pas!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 59, 'Environ une heure plus tard, un autre assurait la même chose et disait: Certainement, cet homme était aussi avec lui; car il est Galiléen.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 60, 'Mais Pierre reprit: homme, je ne sais ce que tu veux dire! Au même instant, comme il parlait encore, le coq chanta;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 61, 'et le Seigneur, s\'étant retourné, regarda Pierre. Pierre se ressouvint de la parole que le Seigneur lui avait dite: Avant que le coq chante aujourd\'hui, tu me renieras trois fois.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 62, 'Et étant sorti, il pleura amèrement.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 63, 'Or, ceux qui gardaient Jésus se moquaient de lui et le frappaient;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 64, 'et, lui ayant couvert le visage, ils lui disaient: Prophétise, devine qui t\'a frappé!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 65, 'Et ils proféraient beaucoup d\'autres injures contre lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 66, 'Quand le jour fut venu, les anciens du peuple, les principaux sacrificateurs et les scribes se réunirent, et ils le firent venir dans leur Sanhédrin.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 67, 'Ils lui dirent: Si tu es le Christ, déclare-le-nous. Il leur répondit: Si je le disais, vous ne le croiriez pas;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 68, 'et si je vous interrogeais, vous ne me répondriez pas.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 69, 'Mais désormais le Fils de l\'homme sera assis à la droite du Dieu tout-puissant.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 70, 'Ils dirent tous: Tu es donc le Fils de Dieu? Il leur répondit: Vous dites vous-mêmes que je le suis.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 71, 'Alors ils s\'écrièrent: Qu\'avons-nous encore besoin de témoignage? Nous venons nous-mêmes de l\'entendre de sa propre bouche!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 1, 'Puis toute l\'assemblée, s\'étant levée, le mena devant Pilate.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 2, 'Alors ils se mirent à l\'accuser, en disant: Nous avons trouvé cet homme soulevant notre nation, défendant de payer le tribut à César, et se disant le Christ, le Roi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 3, 'Pilate lui demanda: C\'est toi qui es le roi des Juifs? Jésus lui répondit: Tu le dis!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 4, 'Alors Pilate dit aux principaux sacrificateurs et au peuple: Je ne trouve rien de criminel en cet homme.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 5, 'Mais ils insistaient plus fortement en disant: Il soulève le peuple, en enseignant dans toute la Judée; après avoir commencé par la Galilée, il est venu jusqu\'ici.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 6, 'Lorsque Pilate entendit cela, il demanda si cet homme était Galiléen.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 7, 'Apprenant que Jésus était de la juridiction d\'Hérode, il le renvoya à Hérode, qui se trouvait aussi à Jérusalem en ces jours-là.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 8, 'Quand Hérode vit Jésus, il eut une grande joie; car depuis longtemps il désirait le voir, à cause de ce qu\'il avait entendu dire de lui, et il espérait qu\'il lui verrait faire quelque miracle.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 9, 'Il lui adressa donc plusieurs questions; mais Jésus ne lui répondit rien.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 10, 'Et les principaux sacrificateurs et les scribes étaient là, qui l\'accusaient avec véhémence.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 11, 'Alors Hérode, ainsi que les gens de sa garde, le traita avec mépris et se moqua de lui; puis, après l\'avoir revêtu d\'un manteau éclatant, il le renvoya à Pilate.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 12, 'Ce jour-là même, Pilate et Hérode devinrent amis, d\'ennemis qu\'ils étaient auparavant.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 13, 'Pilate, ayant réuni les principaux sacrificateurs, les magistrats et le peuple, leur dit:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 14, 'Vous m\'avez amené cet homme, l\'accusant de soulever le peuple; et cependant, après l\'avoir interrogé en votre présence, je ne l\'ai trouvé coupable d\'aucun des crimes dont vous l\'accusez,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 15, 'ni Hérode non plus, puisqu\'il nous l\'a renvoyé: il n\'a donc rien fait qui mérite la mort.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 16, 'Ainsi, après l\'avoir fait châtier, je le relâcherai.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 17, '[Or, à chaque fête, Pilate était obligé de leur relâcher un prisonnier].');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 18, 'Alors ils se mirent à crier tous ensemble: Fais mourir celui-ci, et relâche-nous Barabbas!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 19, 'Or, cet homme avait été mis en prison pour une sédition qui avait eu lieu dans la ville, et pour un meurtre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 20, 'Pilate leur parla de nouveau, dans le dessein de délivrer Jésus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 21, 'Mais ils crièrent; Crucifie-le! crucifie-le!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 22, 'Il leur dit pour la troisième fois: Quel mal a-t-il donc fait? Je n\'ai rien trouvé en lui qui mérite la mort. Ainsi, après l\'avoir fait châtier, je le relâcherai.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 23, 'Mais ils insistaient, demandant à grands cris qu\'il fût crucifié, et leurs clameurs l\'emportèrent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 24, 'Pilate prononça la sentence qui répondait à leur désir.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 25, 'Il relâcha donc celui qui avait été mis en prison pour sédition et pour meurtre, et qu\'ils réclamaient; et il abandonna Jésus à leur volonté.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 26, 'Comme ils l\'emmenaient, ils prirent un homme de Cyrène, nommé Simon, qui revenait des champs; et ils le chargèrent de la croix, pour qu\'il la portât derrière Jésus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 27, 'Le peuple, en grande multitude, suivait Jésus, ainsi que des femmes qui se frappaient la poitrine et qui pleuraient sur lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 28, 'Mais Jésus, se tournant vers elles, leur dit: Filles de Jérusalem, ne pleurez pas sur moi, mais pleurez sur vous-mêmes et sur vos enfants!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 29, 'Car voici que les jours viennent où l\'on dira: Heureuses les stériles, heureuses les entrailles qui n\'ont pas enfanté, et les mamelles qui n\'ont point allaité!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 30, 'Alors les hommes se mettront à dire aux montagnes: Tombez sur nous!!!- et aux coteaux: Couvrez-nous!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 31, 'Car si l\'on fait ces choses au bois vert, qu\'arrivera-t-il au bois sec?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 32, 'On conduisait aussi deux autres hommes, des malfaiteurs, pour les faire mourir avec lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 33, 'Quand ils furent arrivés au lieu appelé le lieu du Crâne, ils le crucifièrent là, ainsi que les malfaiteurs, l\'un à sa droite, et l\'autre à sa gauche.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 34, 'Mais Jésus disait: Père, pardonne-leur; car ils ne savent ce qu\'ils font. Puis, ils se partagèrent ses vêtements, en les tirant au sort.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 35, 'Le peuple se tenait là et regardait. Et les chefs se moquaient, en disant: Il en a sauvé d\'autres; qu\'il se sauve lui-même, s\'il est le Christ, l\'élu de Dieu!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 36, 'Les soldats aussi le tournaient en dérision. Ils s\'approchaient et lui présentaient du vinaigre');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 37, 'en disant: Si tu es le roi des Juifs, sauve-toi toi-même!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 38, 'Au-dessus de sa tête, il y avait cette inscription: Celui-ci est le roi des Juifs.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 39, 'Or, l\'un des malfaiteurs qui avaient été crucifiés, l\'injuriait, en disant: N\'es-tu pas le Christ? Sauve-toi toi-même, et nous avec toi!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 40, 'Mais l\'autre, le reprenant, lui dit: Ne crains-tu pas Dieu, toi qui subis la même condamnation?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 41, 'Pour nous, ce n\'est que justice, car nous recevons ce que nos actions ont mérité; mais celui-ci n\'a fait aucun mal.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 42, 'Puis il disait; Jésus, souviens-toi de moi, quand tu viendras dans ton règne!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 43, 'Jésus lui répondit: En vérité, je te le déclare, aujourd\'hui tu seras avec moi dans le paradis.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 44, 'Il était déjà environ la sixième heure, et il y eut des ténèbres sur tout le pays jusqu\'à la neuvième heure.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 45, 'Le soleil s\'obscurcit, et le voile du temple se déchira par le milieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 46, 'Alors Jésus jeta un grand cri et dit: Père, je remets mon esprit entre tes mains! Et après avoir dit cela, il expira.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 47, 'Le centenier, voyant ce qui était arrivé, donna gloire à Dieu et dit: Certainement cet homme était juste.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 48, 'Et tout le peuple qui était accouru à ce spectacle, voyant ce qui s\'était passé, s\'en retournait en se frappant la poitrine.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 49, 'Mais ceux qui connaissaient Jésus, ainsi que les femmes qui l\'avaient suivi de la Galilée, se tenaient tous à distance et regardaient.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 50, 'Il y avait un homme, appelé Joseph, qui était membre du Sanhédrin, homme droit et juste,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 51, 'qui n\'avait pas consenti au dessein des autres, ni à ce qu\'ils avaient fait. Il était d\'Arimathée, ville de Judée, et il attendait le royaume de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 52, 'Il vint donc trouver Pilate et lui demanda le corps de Jésus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 53, 'Après l\'avoir descendu de la croix, il l\'enveloppa d\'un linceul et le déposa dans un tombeau, taillé dans le roc, où personne n\'avait encore été mis.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 54, 'C\'était le jour de la préparation, et le sabbat allait commencer.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 55, 'Les femmes qui étaient venues de la Galilée avec Jésus, ayant accompagné Joseph, virent le tombeau, et comment le corps de Jésus y avait été placé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 56, 'Puis s\'en étant retournées, elles préparèrent des aromates et des parfums. Le jour du sabbat, elles se reposèrent, conformément à la loi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 1, 'Le premier jour de la semaine, de très grand matin, elles vinrent au tombeau, apportant les aromates qu\'elles avaient préparés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 2, 'Elles trouvèrent que la pierre avait été roulée loin de l\'ouverture du tombeau;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 3, 'mais, étant entrées, elles ne trouvèrent point le corps du Seigneur Jésus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 4, 'Elles ne savaient qu\'en penser, lorsque deux hommes parurent devant elles, en vêtements brillants comme l\'éclair.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 5, 'Et comme elles étaient saisies de frayeur et baissaient le visage vers la terre, ils leur dirent: Pourquoi cherchez-vous parmi les morts celui qui est vivant?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 6, 'Il n\'est pas ici, mais il est ressuscité. Souvenez-vous de quelle manière il vous a parlé, lorsqu\'il était encore en Galilée,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 7, 'et qu\'il disait: Il faut que le Fils de l\'homme soit livré entre les mains des pécheurs, qu\'il soit crucifié et qu\'il ressuscite le troisième jour.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 8, 'Alors elles se souvinrent des paroles de Jésus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 9, 'Quand elles furent de retour du tombeau, elles annoncèrent toutes ces choses aux Onze et à tous les autres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 10, 'C\'étaient Marie-Madeleine, Jeanne, Marie, mère de Jacques; et les autres femmes, qui étaient avec elles, disaient les mêmes choses aux apôtres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 11, 'Mais ces paroles leur firent l\'effet d\'une rêverie, et ils ne les crurent point.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 12, 'Cependant, Pierre se leva et courut au tombeau; et, s\'étant baissé pour regarder, il ne vit que les linges qui étaient à terre; puis, il s\'en alla chez lui, tout surpris de ce qui était arrivé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 13, 'Ce même jour, deux des disciples allaient à un village, appelé Emmaüs, qui était à soixante stades de Jérusalem;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 14, 'et ils s\'entretenaient de tout ce qui s\'était passé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 15, 'Or il arriva, comme ils s\'entretenaient et discutaient ensemble, que Jésus lui-même s\'approcha et se mit à marcher avec eux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 16, 'Mais leurs yeux étaient privés du pouvoir de le reconnaître.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 17, 'Il leur dit: Quelles sont les paroles que vous échangez ainsi l\'un avec l\'autre, chemin faisant? Et ils s\'arrêtèrent tout tristes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 18, 'L\'un d\'eux, nommé Cléopas, lui répondit: Es-tu le seul étranger à Jérusalem, qui ne sache pas ce qui s\'y est passé ces jours-ci?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 19, '— Quoi donc? leur demanda-t-il. Ils lui répondirent: Ce qui est arrivé à Jésus de Nazareth, qui était un prophète puissant en oeuvres et en paroles, aux yeux de Dieu et de tout le peuple;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 20, 'comment les principaux sacrificateurs et nos magistrats l\'ont livré pour être condamné à mort, et l\'ont crucifié.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 21, 'Pour nous, nous espérions que ce serait lui qui délivrerait Israël; mais, avec tout cela, voici le troisième jour que ces choses sont arrivées.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 22, 'Il est vrai que quelques femmes, qui sont des nôtres, nous ont fort étonnés. Elles sont allées de grand matin au tombeau;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 23, 'puis, n\'ayant pas trouvé son corps, elles sont venues nous dire que des anges leur sont apparus et leur ont déclaré qu\'il était vivant.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 24, 'Quelques-uns des nôtres se sont aussi rendus au tombeau, et ils ont trouvé les choses comme les femmes l\'avaient dit; mais lui, ils ne l\'ont pas vu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 25, 'Alors Jésus leur dit: gens sans intelligence et d\'un coeur lent à croire tout ce qu\'ont annoncé les prophètes!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 26, 'Ne fallait-il pas que le Christ souffrît ces choses pour qu\'il entrât dans sa gloire?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 27, 'Puis, commençant par Moïse et continuant par tous les prophètes, il leur expliqua, dans toutes les Écritures, ce qui le concernait.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 28, 'Quand ils se trouvèrent près du village où ils se rendaient, Jésus semblait vouloir aller plus loin.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 29, 'Mais ils l\'obligèrent à s\'arrêter, en disant: Reste avec nous; car le soir approche, et le jour est déjà sur son déclin. Il entra donc pour rester avec eux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 30, 'Comme il était à table avec eux, il prit le pain, et, après avoir rendu grâces, il le rompit et le leur donna.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 31, 'Alors leurs yeux s\'ouvrirent, et ils le reconnurent; mais lui se déroba à leur vue.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 32, 'Et ils se dirent l\'un à l\'autre: Notre coeur ne brûlait-il pas au-dedans de nous, lorsqu\'il nous parlait en chemin et nous expliquait les Écritures?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 33, 'Se levant à l\'heure même, ils retournèrent à Jérusalem, et ils trouvèrent les Onze et d\'autres disciples assemblés avec eux,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 34, 'qui leur dirent: Le Seigneur est vraiment ressuscité, et il est apparu à Simon.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 35, 'Eux, à leur tour, racontèrent ce qui leur était arrivé en chemin, et comment ils l\'avaient reconnu lorsqu\'il avait rompu le pain.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 36, 'Comme ils parlaient ainsi, Jésus lui-même se présenta au milieu d\'eux et leur dit: La paix soit avec vous!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 37, 'Mais eux, saisis de stupeur et d\'effroi, croyaient voir un esprit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 38, 'Il leur dit: Pourquoi êtes-vous troublés, et pourquoi de telles pensées s\'élèvent-elles dans vos coeurs?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 39, 'Voyez mes mains et mes pieds: c\'est moi-même. Touchez-moi et regardez: un esprit n\'a ni chair ni os, ce que j\'ai, comme vous le voyez.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 40, 'En disant cela, il leur montra ses mains et ses pieds.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 41, 'Mais comme, dans leur joie, ils ne croyaient pas encore, et comme ils étaient remplis d\'étonnement, il leur dit: Avez-vous ici quelque chose à manger?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 42, 'Ils lui présentèrent un morceau de poisson grillé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 43, 'Il le prit et le mangea en leur présence.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 44, 'Puis il leur dit: Voilà ce que je vous déclarais, quand j\'étais encore avec vous, et quand je vous disais qu\'il fallait que fût accompli tout ce qui est écrit à mon sujet dans la loi de Moïse, dans les prophètes et dans les psaumes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 45, 'Alors il leur ouvrit l\'esprit pour leur faire comprendre les Écritures.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 46, 'Et il leur dit: C\'est ainsi qu\'il est écrit que le Christ devait souffrir, qu\'il ressusciterait des morts le troisième jour,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 47, 'et qu\'on prêcherait en son nom la repentance, pour la rémission des péchés, parmi toutes les nations, en commençant par Jérusalem.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 48, 'Vous êtes témoins de ces choses;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 49, 'et moi, je vais vous envoyer ce que mon Père vous a promis. Quant à vous, demeurez dans la Ville, jusqu\'à ce que vous soyez revêtus de la puissance d\'en haut.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 50, 'Il les emmena ensuite jusqu\'aux environs de Béthanie, et, levant ses mains, il les bénit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 51, 'Pendant qu\'il les bénissait, il se sépara d\'eux et fut élevé au ciel.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 52, 'Eux, l\'ayant adoré, s\'en retournèrent à Jérusalem, pleins d\'une grande joie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 53, 'Ils se tenaient continuellement dans le temple, bénissant Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 1, 'Au commencement était la Parole, et la Parole était avec Dieu, et la Parole était Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 2, 'Elle était au commencement avec Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 3, 'Toutes choses ont été faites par elle, et rien de ce qui a été fait n\'a été fait sans elle.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 4, 'En elle était la vie, et la vie était la lumière des hommes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 5, 'La lumière brille dans les ténèbres, et les ténèbres ne l\'ont point reçue.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 6, 'Il y eut un homme, envoyé de Dieu, dont le nom était Jean.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 7, 'Il vint pour être témoin, pour rendre témoignage à la lumière, afin que, par lui, tous fussent amenés à la foi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 8, 'Il n\'était pas lui-même la Lumière, mais il devait rendre témoignage à la Lumière.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 9, 'Celle-ci était la véritable Lumière, qui éclaire tout homme en venant dans le monde.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 10, 'La Parole était dans le monde, et le monde a été fait par elle; mais le monde ne l\'a pas connue.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 11, 'Elle est venue chez les siens, et les siens ne l\'ont point reçue.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 12, 'Mais à tous ceux qui l\'ont reçue, elle a donné le pouvoir de devenir enfants de Dieu, à tous ceux qui croient en son nom,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 13, 'qui ne sont pas nés du sang, ni de la volonté de la chair, ni de la volonté de l\'homme, mais qui sont nés de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 14, 'La Parole a été faite chair; elle a habité parmi nous, pleine de grâce et de vérité, et nous avons contemplé sa gloire, une gloire telle qu\'est celle du Fils unique venu d\'auprès du Père.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 15, 'Jean lui rendait témoignage lorsqu\'il s\'écriait: C\'est de lui que je disais: Celui qui vient après moi m\'a devancé, parce qu\'il était avant moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 16, 'En effet, c\'est de sa plénitude que nous avons tous reçu grâce sur grâce.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 17, 'Car la loi a été donnée par Moïse; la grâce et la vérité sont venues par Jésus-Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 18, 'Personne n\'a jamais vu Dieu; le Fils unique, qui est dans le sein du Père, est celui qui nous l\'a fait connaître.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 19, 'Voici quel fut le témoignage de Jean, lorsque les Juifs envoyèrent de Jérusalem des sacrificateurs et des lévites pour lui demander: Qui es-tu? Il fit cette déclaration, et il la confirma sans réserves:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 20, 'Moi, déclara-t-il, je ne suis pas le Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 21, 'Qui es-tu donc? lui demandèrent-ils, — es-tu Élie? Et il dit: Je ne le suis pas. Es-tu le prophète? Il répondit: Non.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 22, 'Ils reprirent: Dis-nous donc qui tu es, afin que nous puissions donner une réponse à ceux qui nous ont envoyés. Que dis-tu au sujet de toi-même?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 23, 'Il répondit: Je suis la voix de celui qui crie dans le désert: «Aplanissez le chemin du Seigneur», comme l\'a dit le prophète Ésaïe.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 24, 'Ceux qui avaient été envoyés vers lui étaient des pharisiens.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 25, 'Ils lui demandèrent encore: Pourquoi donc baptises-tu, si tu n\'es pas le Christ, ni Elie, ni le prophète?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 26, 'Jean leur répondit: Pour moi, je baptise d\'eau; mais il en est un au milieu de vous, que vous ne connaissez pas.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 27, 'C\'est celui qui vient après moi, et je ne suis pas digne de délier la courroie de sa chaussure.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 28, 'Ces choses se passèrent à Béthanie au delà du Jourdain, où Jean baptisait.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 29, 'Le lendemain, Jean vit Jésus qui venait à lui, et il dit: Voici l\'agneau de Dieu, qui ôte le péché du monde.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 30, 'C\'est celui dont je disais: Il vient après moi un homme qui m\'a devancé, parce qu\'il était avant moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 31, 'Pour moi, je ne le connaissais pas; mais je suis venu baptiser d\'eau, afin qu\'il fût manifesté à Israël.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 32, 'Jean rendit encore ce témoignage: J\'ai vu l\'Esprit descendre du ciel comme une colombe, et il s\'est arrêté sur lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 33, 'Pour moi, je ne le connaissais pas; mais celui qui m\'a envoyé baptiser d\'eau m\'a dit: Celui sur qui tu verras l\'Esprit descendre et s\'arrêter, c\'est celui qui baptise d\'Esprit saint.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 34, 'Je l\'ai vu, et j\'ai rendu ce témoignage: C\'est lui qui est le Fils de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 35, 'Le lendemain, Jean se trouvait là de nouveau avec deux de ses disciples;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 36, 'et, regardant Jésus qui passait, il dit: Voici l\'agneau de Dieu!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 37, 'Les deux disciples entendirent cette parole, et ils suivirent Jésus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 38, 'Jésus, s\'étant retourné et voyant qu\'ils le suivaient, leur dit: Que cherchez-vous? Ils lui répondirent: Rabbi, — c\'est-à-dire Maître, — où demeures-tu?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 39, 'Il leur dit: Venez et voyez. Ils allèrent donc et virent où il demeurait, et ils restèrent auprès de lui ce jour-là. C\'était environ la dixième heure.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 40, 'André, frère de Simon Pierre, était l\'un des deux qui avaient entendu ce que Jean disait, et qui avaient suivi Jésus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 41, 'Il trouva d\'abord son frère Simon, et il lui dit: Nous avons trouvé le Messie — c\'est-à-dire le Christ —.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 42, 'Et il l\'amena à Jésus. Jésus, l\'ayant regardé, lui dit: Tu es Simon, fils de Jona; tu seras appelé Céphas — c\'est-à-dire Pierre —.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 43, 'Le lendemain, Jésus voulut se rendre en Galilée. Il rencontra Philippe et lui dit: Suis-moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 44, 'Or, Philippe était de Bethsaïda, la ville d\'André et de Pierre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 45, 'Philippe rencontra Nathanaël, et il lui dit: Nous avons trouvé celui dont Moïse a parlé dans la loi et dont les prophètes aussi ont parlé; c\'est Jésus de Nazareth, le fils de Joseph.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 46, 'Nathanaël lui dit: Peut-il venir quelque chose de bon de Nazareth? Philippe lui répondit: Viens et vois!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 47, 'Jésus, voyant venir à lui Nathanaël, dit de lui: Voici un véritable Israélite, dans lequel il n\'y a point de fraude. Nathanaël lui dit:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 48, 'D\'où me connais-tu? Jésus lui répondit: Avant que Philippe t\'appelât, je t\'ai vu, quand tu étais sous le figuier.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 49, 'Nathanaël reprit: Maître, tu es le Fils de Dieu, tu es le roi d\'Israël!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 50, 'Jésus répondit: Parce que je t\'ai dit que je t\'avais vu sous le figuier, tu crois; tu verras de plus grandes choses que celles-ci!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 51, 'Et il ajouta: En vérité, en vérité, je vous le déclare, vous verrez le ciel ouvert, et les anges de Dieu montant et descendant sur le Fils de l\'homme.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 1, 'Trois jours après, on célébrait des noces à Cana en Galilée, et la mère de Jésus y était.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 2, 'Jésus fut aussi invité aux noces avec ses disciples.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 3, 'Le vin ayant manqué, la mère de Jésus lui dit: Ils n\'ont plus de vin.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 4, 'Jésus lui répondit: Femme, qu\'y a-t-il entre moi et toi? Mon heure n\'est pas encore venue.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 5, 'Sa mère dit à ceux qui servaient: Faites tout ce qu\'il vous dira.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 6, 'Or, il y avait là six vases de pierre, destinés aux purifications des Juifs, et qui contenaient chacun deux ou trois mesures.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 7, 'Jésus leur dit: Remplissez d\'eau ces vases. Et ils les remplirent jusqu\'au bord.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 8, 'Alors il leur dit: Puisez maintenant, et portez-en au maître d\'hôtel. Et ils lui en portèrent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 9, 'Quand le maître d\'hôtel eut goûté l\'eau qui avait été changée en vin — il ne savait pas d\'où venait ce vin, mais les serviteurs qui avaient puisé l\'eau le savaient bien, — il appela l\'époux,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 10, 'et il lui dit: Tout homme sert d\'abord le bon vin, et ensuite le moins bon, après qu\'on a bu abondamment. Toi, tu as gardé le bon vin jusqu\'à maintenant.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 11, 'C\'est ainsi que Jésus fit à Cana, en Galilée, le premier de ses miracles, et qu\'il manifesta sa gloire; et ses disciples crurent en lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 12, 'Après cela, il descendit à Capernaüm, avec sa mère, ses frères et ses disciples; et ils n\'y demeurèrent que peu de jours.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 13, 'La Pâque des Juifs était proche; et Jésus monta à Jérusalem.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 14, 'Il trouva dans le temple les marchands de boeufs, de brebis et de pigeons, et les changeurs qui s\'y étaient installés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 15, 'Ayant fait un fouet de cordes, il les chassa tous du temple, ainsi que les brebis et les boeufs; il répandit la monnaie des changeurs et renversa leurs tables.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 16, 'Et il dit à ceux qui vendaient les pigeons: Otez cela d\'ici; ne faites pas de la maison de mon Père une maison de trafic.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 17, 'Alors ses disciples se souvinrent de ce qui est écrit: «Le zèle de ta maison me dévore.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 18, 'Les Juifs, prenant la parole, lui dirent: Quel miracle nous fais-tu voir, pour agir de la sorte?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 19, 'Jésus répondit: Détruisez ce temple, et en trois jours je le relèverai!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 20, 'Les Juifs reprirent: On a mis quarante-six ans à bâtir ce temple, et toi, tu le relèverais en trois jours!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 21, 'Mais il parlait du temple de son corps.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 22, 'Aussi, quand il fut ressuscité des morts, ses disciples se souvinrent qu\'il avait dit cela; et ils crurent à l\'Écriture et à la parole que Jésus avait dite.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 23, 'Pendant qu\'il était à Jérusalem pour la fête de Pâque, plusieurs, voyant les miracles qu\'il faisait, crurent en son nom.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 24, 'Mais Jésus ne se fiait pas à eux, parce qu\'il les connaissait tous,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 25, 'et qu\'il n\'avait pas besoin que personne lui rendît témoignage au sujet d\'aucun homme, car il savait par lui-même ce qui était dans l\'homme.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 1, 'Il y avait parmi les pharisiens un homme, appelé Nicodème, qui était l\'un des principaux parmi les Juifs.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 2, 'Cet homme vint, de nuit, trouver Jésus et lui dit: Maître, nous savons que tu es un docteur venu de la part de Dieu; car personne ne peut faire ces miracles que tu fais, si Dieu n\'est pas avec lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 3, 'Jésus prit la parole et lui dit: En vérité, en vérité, je te le dis, si un homme ne naît de nouveau, il ne peut voir le royaume de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 4, 'Nicodème lui dit: Comment un homme peut-il naître, quand il est vieux? Peut-il rentrer dans le sein de sa mère et naître une seconde fois?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 5, 'Jésus répondit: En vérité, en vérité, je te le dis, si un homme ne naît d\'eau et d\'Esprit, il ne peut entrer dans le royaume de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 6, 'Ce qui est né de la chair est chair, et ce qui est né de l\'Esprit est esprit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 7, 'Ne t\'étonne pas de ce que je t\'ai dit: Il faut que vous naissiez de nouveau.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 8, 'Le vent souffle où il veut, et tu en entends le bruit; mais tu ne sais ni d\'où il vient, ni où il va. Il en est de même de tout homme qui est né de l\'Esprit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 9, 'Nicodème reprit: Comment cela peut-il se faire?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 10, 'Jésus lui répondit: Tu es le docteur d\'Israël, et tu ne sais pas ces choses?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 11, 'En vérité, en vérité, je te le déclare, nous disons ce que nous savons, et nous attestons ce que nous avons vu; et vous ne recevez point notre témoignage.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 12, 'Si vous ne croyez pas quand je vous parle des choses terrestres, comment croirez-vous quand je vous parlerai des choses célestes?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 13, 'Personne n\'est monté au ciel, sinon celui qui est descendu du ciel, le Fils de l\'homme, qui est dans le ciel.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 14, 'Et comme Moïse éleva le serpent dans le désert, de même il faut que le Fils de l\'homme soit élevé,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 15, 'afin que quiconque croit en lui ait la vie éternelle.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 16, 'Car Dieu a tellement aimé le monde, qu\'il a donné son Fils unique, afin que quiconque croit en lui ne périsse point, mais qu\'il ait la vie éternelle.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 17, 'En effet, Dieu n\'a point envoyé son Fils dans le monde pour juger le monde, mais afin que le monde soit sauvé par lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 18, 'Celui qui croit en lui n\'est point jugé; celui qui ne croit pas est déjà jugé, parce qu\'il n\'a pas cru au nom du Fils unique de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 19, 'Or, voici quel est ce jugement: la lumière est venue dans le monde, et les hommes ont mieux aimé les ténèbres que la lumière, parce que leurs oeuvres étaient mauvaises.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 20, 'Car quiconque fait le mal hait la lumière, et ne vient point à la lumière, de peur que ses oeuvres ne soient réprouvées.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 21, 'Mais celui qui met en pratique la vérité vient à la lumière, afin que ses oeuvres soient manifestées, parce que c\'est en Dieu qu\'elles sont faites.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 22, 'Après cela, Jésus se rendit avec ses disciples dans la campagne de la Judée; il y demeurait avec eux, et il y baptisait.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 23, 'Jean baptisait aussi à Énon, près de Salim, parce qu\'il y avait là beaucoup d\'eau; et on y venait pour être baptisé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 24, 'Car Jean n\'avait pas encore été mis en prison.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 25, 'Or, il y eut une discussion entre les disciples de Jean et un Juif, au sujet de la purification.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 26, 'Et ils vinrent trouver Jean et lui dirent: Maître, celui qui était avec toi au delà du Jourdain, auquel tu as rendu témoignage, le voilà qui baptise, et tous vont à lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 27, 'Jean leur répondit: Aucun homme ne peut rien s\'attribuer qui ne lui soit donné du ciel.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 28, 'Vous m\'êtes vous-mêmes témoins que j\'ai dit: Ce n\'est pas moi qui suis le Christ, mais j\'ai été envoyé devant lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 29, 'Celui qui a l\'épouse est l\'époux; mais l\'ami de l\'époux, qui se tient près de lui et qui l\'écoute, est ravi de joie en entendant la voix de l\'époux; et c\'est là ma joie, qui est parfaite.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 30, 'Il faut qu\'il croisse et que je diminue.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 31, 'Celui qui vient d\'en haut est au-dessus de tous. Celui qui vient de la terre est de la terre, et il parle comme étant de la terre; celui qui vient du ciel est au-dessus de tous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 32, 'Il atteste ce qu\'il a vu et entendu; et personne ne reçoit son témoignage!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 33, 'Celui qui a reçu son témoignage confirme ainsi que Dieu est vrai.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 34, 'Car celui que Dieu a envoyé prononce les paroles de Dieu, parce que Dieu lui donne l\'Esprit sans mesure.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 35, 'Le Père aime le Fils, et il a remis toutes choses entre ses mains.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 36, 'Celui qui croit au Fils a la vie éternelle; celui qui refuse de croire au Fils ne verra point la vie, mais la colère de Dieu demeure sur lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 1, 'Quand le Seigneur eut appris que les pharisiens avaient entendu dire qu\'il faisait et baptisait plus de disciples que Jean,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 2, '— toutefois ce n\'était pas Jésus lui-même qui baptisait, mais c\'étaient ses disciples, —');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 3, 'il quitta la Judée et retourna en Galilée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 4, 'Or, il fallait qu\'il passât par la Samarie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 5, 'Il arriva donc à une ville de Samarie, nommée Sichar, près du champ que Jacob avait donné à Joseph, son fils.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 6, 'Là se trouvait le puits de Jacob. Jésus, fatigué de la route, s\'assit auprès du puits; c\'était environ la sixième heure.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 7, 'Une femme samaritaine vint puiser de l\'eau. Jésus lui dit: Donne-moi à boire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 8, 'Car ses disciples étaient allés à la ville pour acheter des vivres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 9, 'La femme samaritaine lui répondit: Comment, toi qui es Juif, me demandes-tu à boire, à moi qui suis une femme samaritaine? — Les Juifs, en effet, n\'ont pas de relations avec les Samaritains. —');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 10, 'Jésus répondit et lui dit: Si tu connaissais le don de Dieu, et qui est celui qui te dit: Donne-moi à boire, — tu lui aurais demandé toi-même à boire, et il t\'aurait donné une eau vive.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 11, 'La femme lui dit: Seigneur, tu n\'as rien pour puiser, et le puits est profond; d\'où aurais-tu donc cette eau vive?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 12, 'Es-tu plus grand que Jacob, notre père, qui nous a donné ce puits et qui en a bu lui-même, aussi bien que ses fils et ses troupeaux?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 13, 'Jésus lui répondit: Quiconque boit de cette eau aura encore soif;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 14, 'mais celui qui boira de l\'eau que je lui donnerai n\'aura plus jamais soif. L\'eau que je lui donnerai deviendra en lui une source d\'eau qui jaillira jusque dans la vie éternelle.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 15, 'La femme lui dit; Seigneur, donne-moi de cette eau, afin que je n\'aie plus soif, et que je ne vienne plus ici pour puiser de l\'eau.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 16, 'Jésus lui dit: Va, appelle ton mari, et reviens.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 17, 'La femme répondit: Je n\'ai point de mari. Jésus reprit: Tu as raison de dire: Je n\'ai point de mari;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 18, 'car tu as eu cinq maris, et celui que tu as maintenant n\'est pas ton mari; en cela tu as dit vrai.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 19, 'La femme lui dit: Seigneur, je vois que tu es un prophète!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 20, 'Nos pères ont adoré sur cette montagne; et vous dites, vous, que le lieu où il faut adorer est à Jérusalem.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 21, 'Jésus lui répondit: Femme, crois-moi; l\'heure vient où vous n\'adorerez plus le Père ni sur cette montagne, ni à Jérusalem.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 22, 'Vous adorez ce que vous ne connaissez pas. Nous, nous adorons ce que nous connaissons; car le salut vient des Juifs.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 23, 'Mais l\'heure vient, et elle est déjà venue, où les vrais adorateurs adoreront le Père en esprit et en vérité: ce sont là les adorateurs que le Père demande.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 24, 'Dieu est Esprit, et il faut que ceux qui l\'adorent, l\'adorent en esprit et en vérité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 25, 'La femme lui répondit: Je sais que le Messie — c\'est-à-dire le Christ — doit venir; quand il sera venu, il nous annoncera toutes choses.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 26, 'Jésus lui dit: Je le suis, moi qui te parle.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 27, 'A ce moment, ses disciples arrivèrent, et ils furent surpris de ce qu\'il parlait avec une femme. Pourtant, aucun d\'eux ne lui dit: Que lui demandes-tu? ou: Pourquoi parles-tu avec elle?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 28, 'La femme laissa donc sa cruche et s\'en alla à la ville; et elle dit aux gens de l\'endroit:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 29, 'Venez voir un homme qui m\'a dit tout ce que j\'ai fait: ne serait-ce pas le Christ?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 30, 'Alors ils sortirent de la ville et allèrent vers Jésus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 31, 'Cependant les disciples insistaient auprès de lui, en disant: Maître, mange.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 32, 'Il leur répondit: J\'ai pour me nourrir un aliment que vous ne connaissez pas.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 33, 'Les disciples se disaient donc l\'un à l\'autre: Quelqu\'un lui aurait-il apporté à manger?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 34, 'Jésus leur dit: Ma nourriture est de faire la volonté de celui qui m\'a envoyé, et d\'accomplir son oeuvre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 35, 'Ne dites-vous pas qu\'il y a encore quatre mois jusqu\'à la moisson? Mais moi, je vous dis: Levez les yeux et regardez les campagnes, déjà blanches pour la moisson.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 36, 'Déjà le moissonneur reçoit son salaire et amasse du fruit pour la vie éternelle, afin que le semeur et le moissonneur en aient ensemble de la joie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 37, 'Car c\'est ici qu\'on peut dire en toute vérité: Autre est le semeur, autre le moissonneur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 38, 'Je vous ai envoyés moissonner où vous n\'aviez pas travaillé; d\'autres ont travaillé, et vous, vous êtes entrés dans leur travail.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 39, 'Plusieurs des Samaritains de cette ville crurent en lui, à cause de la parole de la femme qui lui avait rendu ce témoignage: Il m\'a dit tout ce que j\'ai fait.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 40, 'Les Samaritains, étant donc venus vers lui, le prièrent de demeurer chez eux; et il y demeura deux jours.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 41, 'Il y en eut beaucoup plus qui crurent en lui après avoir entendu sa parole.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 42, 'Et ils disaient à la femme: Ce n\'est plus à cause de ce que tu nous as dit, que nous croyons; car nous l\'avons entendu nous-mêmes, et nous savons que c\'est lui qui est véritablement le Sauveur du monde.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 43, 'Après ces deux jours, Jésus partit de là et s\'en alla en Galilée;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 44, '— car il avait déclaré lui-même qu\'un prophète n\'est point honoré dans sa patrie. —');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 45, 'Lorsqu\'il fut arrivé en Galilée, il fut bien reçu des Galiléens qui avaient vu tout ce qu\'il avait fait à Jérusalem pendant la fête; car ils étaient allés, eux aussi, à la fête.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 46, 'Il vint donc de nouveau à Cana en Galilée, où il avait changé l\'eau en vin. Or, il y avait à Capernaüm un officier royal, dont le fils était malade.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 47, 'Cet officier, ayant appris que Jésus était venu de Judée en Galilée, alla le trouver et le pria de descendre pour guérir son fils, qui était mourant.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 48, 'Jésus lui dit: Si vous ne voyez des miracles et des prodiges, vous ne croyez pas!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 49, 'L\'officier royal lui répondit: Seigneur, descends, avant que mon enfant ne meure!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 50, 'Jésus lui dit: Va, ton fils vit! Cet homme crut à la parole que Jésus lui avait dite, et il s\'en alla.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 51, 'Comme il était déjà en route, ses serviteurs vinrent à sa rencontre et lui dirent: Ton fils vit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 52, 'Il leur demanda à quelle heure il s\'était trouvé mieux. Ils lui répondirent: Hier, à la septième heure, la fièvre l\'a quitté.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 53, 'Le père reconnut que c\'était à cette heure-là que Jésus lui avait dit: Ton fils vit. Et il crut, lui et toute sa maison.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 54, 'Ce nouveau miracle fut le second que fit Jésus, à son retour de Judée en Gahlée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 1, 'Après cela, il y eut une fête des Juifs, et Jésus monta à Jérusalem.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 2, 'Or, il y a à Jérusalem, près de la porte des brebis, un réservoir, appelé en hébreu Béthesda, qui est entouré de cinq portiques.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 3, 'Là se trouvaient couchés un grand nombre de malades, des aveugles, des impotents, des paralytiques, [qui attendaient l\'agitation de l\'eau;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 4, 'car un ange descendait de temps en temps dans le réservoir et mettait l\'eau en mouvement; et le premier qui descendait dans le réservoir, après que l\'eau avait été agitée, était guéri, de quelque maladie qu\'il fût atteint].');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 5, 'Il y avait là un homme qui était malade depuis trente-huit ans.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 6, 'Jésus, le voyant couché et sachant qu\'il était malade depuis longtemps, lui dit: Veux-tu être guéri?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 7, 'Le malade lui répondit: Seigneur, je n\'ai personne pour me jeter dans le réservoir, quand l\'eau est agitée; et, pendant que j\'y vais, un autre y descend avant moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 8, 'Jésus lui dit: Lève-toi, prends ton lit et marche.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 9, 'Et aussitôt cet homme fut guéri; il prit son lit et se mit à marcher. Or, c\'était un jour de sabbat.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 10, 'Alors les Juifs dirent à celui qui avait été guéri: C\'est le jour du sabbat; il ne t\'est pas permis d\'emporter ton lit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 11, 'Il leur répondit: Celui-là même qui m\'a guéri, m\'a dit: Prends ton lit et marche!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 12, 'Ils lui demandèrent: Qui est cet homme qui t\'a dit: Prends ton lit et marche?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 13, 'Mais celui qui avait été guéri ne savait pas qui c\'était; car Jésus avait disparu dans la foule qui se trouvait à cet endroit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 14, 'Plus tard, Jésus le trouva dans le temple et lui dit: Te voilà guéri; ne pèche plus, de peur qu\'il ne t\'arrive quelque chose de pire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 15, 'Cet homme alla dire aux Juifs que c\'était Jésus qui l\'avait guéri.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 16, 'C\'est pourquoi les Juifs poursuivaient Jésus, parce qu\'il faisait ces miracles le jour du sabbat.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 17, 'Mais il leur dit: Mon Père travaille jusqu\'à présent, et je travaille, moi aussi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 18, 'A cause de cela, les Juifs cherchaient encore davantage à le faire mourir, non seulement parce qu\'il violait le sabbat, mais encore parce qu\'il disait que Dieu était son propre Père, se faisant égal à Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 19, 'Jésus prit donc la parole et leur dit: En vérité, en vérité, je vous le déclare, le Fils ne peut rien faire de lui-même: il ne fait que ce qu\'il voit faire au Père; car tout ce que le Père fait, le Fils aussi le fait pareillement.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 20, 'Le Père aime le Fils et lui montre tout ce qu\'il fait; il lui montrera des oeuvres plus grandes que celles-ci, afin que vous soyez dans l\'étonnement.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 21, 'En effet, de même que le Père ressuscite les morts et leur donne la vie, de même le Fils donne la vie à qui il veut.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 22, 'Le Père aussi ne juge personne; mais il a remis au Fils le jugement tout entier, afin que tous honorent le Fils, comme ils honorent le Père.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 23, 'Celui qui n\'honore pas le Fils, n\'honore pas le Père qui l\'a envoyé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 24, 'En vérité, en vérité, je vous le dis, celui qui écoute ma parole et croit en Celui qui m\'a envoyé, à la vie éternelle, et il ne vient pas en jugement, mais il est passé de la mort à la vie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 25, 'En vérité, en vérité, je vous le déclare, l\'heure vient, et elle est déjà venue, où les morts entendront la voix du Fils de Dieu, et ceux qui l\'auront entendue vivront.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 26, 'Car, comme le Père a la vie en lui-même, il a aussi donné au Fils d\'avoir la vie en lui-même.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 27, 'Il lui a donné le pouvoir d\'exercer le jugement, parce qu\'il est le Fils de l\'homme.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 28, 'Ne soyez point étonnés de cela; car l\'heure vient où tous ceux qui sont dans les sépulcres entendront sa voix et en sortiront;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 29, 'ceux qui auront fait le bien ressusciteront pour la vie, et ceux qui auront fait le mal ressusciteront pour le jugement.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 30, 'Je ne puis rien faire de moi-même; je juge d\'après ce que j\'entends, et mon jugement est juste, parce que je ne cherche pas ma volonté, mais la volonté de Celui qui m\'a envoyé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 31, 'Si je me rends témoignage à moi-même, mon témoignage n\'est pas digne de foi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 32, 'Il y en a un autre qui me rend témoignage, et je sais que le témoignage qu\'il me rend est digne de foi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 33, 'Vous avez envoyé à Jean des messagers, et il a rendu témoignage à la vérité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 34, 'Pour moi, ce n\'est pas le témoignage d\'un homme que j\'invoque; mais je parle ainsi, afin que vous soyez sauvés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 35, 'Il était le flambeau allumé et brillant, et vous avez voulu, pour un peu de temps, vous réjouir à sa lumière.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 36, 'Mais moi, j\'ai un témoignage plus grand que celui de Jean; car les oeuvres que le Père m\'a donné d\'accomplir, ces oeuvres-là que je fais rendent à mon sujet ce témoignage, que le Père m\'a envoyé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 37, 'Et le Père qui m\'a envoyé m\'a lui-même rendu témoignage. Vous n\'avez jamais entendu sa voix; vous n\'avez jamais vu sa face,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 38, 'et sa parole ne demeure pas en vous, puisque vous ne croyez pas celui qu\'il a envoyé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 39, 'Vous sondez les Écritures, parce que vous pensez avoir par elles la vie éternelle: ce sont elles qui rendent témoignage de moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 40, 'Et vous ne voulez pas venir à moi, pour avoir la vie!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 41, 'Je ne cherche point la gloire qui vient des hommes;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 42, 'mais je sais que vous n\'avez pas l\'amour de Dieu en vous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 43, 'Je suis venu au nom de mon Père, et vous ne me recevez pas. Qu\'un autre vienne en son propre nom, vous le recevrez.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 44, 'Comment pouvez-vous croire, vous qui recevez votre gloire les uns des autres, et ne recherchez pas la gloire qui vient de Dieu seul?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 45, 'Ne pensez pas que ce soit moi qui doive vous accuser devant le Père; celui qui vous accusera, c\'est Moïse, en qui vous avez mis votre espérance.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 46, 'Car si vous croyiez Moïse, vous me croiriez aussi; en effet, c\'est à mon sujet qu\'il a écrit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 47, 'Mais si vous ne croyez pas à ses écrits, comment croiriez-vous à mes paroles?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 1, 'Après cela, Jésus passa de l\'autre côté de la mer de Galilée — ou de Tibériade.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 2, 'Une grande foule le suivait, parce qu\'elle voyait les miracles qu\'il opérait sur ceux qui étaient malades.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 3, 'Mais Jésus monta sur la montagne, où il s\'assit avec ses disciples.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 4, 'Or, la Pâque, la fête des Juifs, était proche.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 5, 'Ayant levé les yeux et voyant une grande foule qui venait à lui, Jésus dit à Philippe: Où achèterons-nous des pains, afin que ces gens aient à manger?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 6, 'Il disait cela pour l\'éprouver; car il savait bien ce qu\'il allait faire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 7, 'Philippe lui répondit: Deux cents deniers de pain ne suffiraient pas pour en donner un peu à chacun.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 8, 'Un de ses disciples, André, frère de Simon Pierre, lui dit:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 9, 'Il y a ici un petit garçon, qui a cinq pains d\'orge et deux poissons; mais qu\'est-ce que cela pour tant de gens?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 10, 'Alors Jésus dit: Faites-les asseoir. Or, il y avait beaucoup d\'herbe en ce lieu-là. Ils s\'assirent donc, au nombre d\'environ cinq mille hommes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 11, 'Jésus prit les pains, et, après avoir rendu grâces, il les distribua à ceux qui étaient assis; il leur donna de même des poissons, autant qu\'ils en voulaient.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 12, 'Lorsqu\'ils furent rassasiés, il dit à ses disciples: Ramassez les morceaux qui restent, afin que rien ne se perde.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 13, 'Ils les ramassèrent donc, et ils remplirent douze paniers des morceaux qui étaient restés des cinq pains d\'orge, après qu\'on eut mangé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 14, 'Ces gens, ayant vu le miracle que Jésus avait fait, disaient: Celui-ci est vraiment le prophète qui doit venir dans le monde.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 15, 'Alors Jésus, sachant qu\'ils allaient venir l\'enlever pour le faire roi, se retira de nouveau seul sur la montagne.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 16, 'Quand le soir fut venu, ses disciples descendirent au bord de la mer;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 17, 'et, étant entrés dans une barque, ils se dirigeaient de l\'autre côté, vers Capernaüm. L\'obscurité les surprit, et Jésus ne les avait pas encore rejoints.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 18, 'Le vent soufflait avec violence, de sorte que la mer était très agitée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 19, 'Quand ils eurent ramé environ vingt-cinq ou trente stades, ils virent Jésus qui marchait sur la mer et qui s\'approchait de la barque; et ils eurent peur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 20, 'Mais il leur dit: C\'est moi, n\'ayez point de peur!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 21, 'Ils voulurent alors le prendre dans la barque; et aussitôt, la barque aborda au lieu où ils allaient.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 22, 'La foule, restée de l\'autre côté de la mer, avait remarqué qu\'il n\'y avait là qu\'une seule barque, et que Jésus n\'y était pas monté avec ses disciples, mais que les disciples étaient partis seuls.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 23, 'Le lendemain, — comme d\'autres barques étaient arrivées de Tibériade près du lieu où ils avaient mangé le pain, après que le Seigneur eut rendu grâces, —');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 24, 'la foule, voyant que Jésus n\'était pas là, ni ses disciples non plus, monta dans ces barques et vint à Capernaüm pour y chercher Jésus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 25, 'Et l\'ayant trouvé de l\'autre côté de la mer, ils lui dirent: Maître, quand es-tu arrivé ici?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 26, 'Jésus leur répondit: En vérité, en vérité, je vous le déclare, vous me cherchez, non parce que vous avez vu des miracles, mais parce que vous avez mangé des pains et que vous avez été rassasiés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 27, 'Travaillez, non pour la nourriture qui périt, mais pour celle qui subsiste jusque dans la vie éternelle, et que le Fils de l\'homme vous donnera; car c\'est lui que le Père, Dieu lui-même, a marqué de son sceau.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 28, 'Ils lui dirent: Que ferons-nous pour travailler aux oeuvres de Dieu?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 29, 'Jésus leur répondit: C\'est ici l\'oeuvre de Dieu, que vous croyiez en Celui qu\'il a envoyé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 30, 'Alors ils lui dirent: Quel miracle fais-tu donc, afin que nous le voyions et que nous croyions en toi? Quelle oeuvre accomplis-tu?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 31, 'Nos pères ont mangé la manne dans le désert, suivant ce qui est écrit: «Il leur a donné à manger le pain venu du ciel»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 32, 'Jésus leur répondit: En vérité, en vérité, je vous le dis. Moïse ne vous a point donné le pain du ciel; mais mon Père vous donne le vrai pain qui vient du ciel.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 33, 'Car le pain de Dieu est celui qui descend du ciel, et qui donne la vie au monde.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 34, 'Ils lui dirent: Seigneur, donne-nous toujours ce pain-là!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 35, 'Jésus reprit: Je suis le pain de vie; celui qui vient à moi n\'aura jamais faim, et celui qui croit en moi n\'aura jamais soif.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 36, 'Mais je vous l\'ai dit: Vous m\'avez vu, et vous ne croyez pas.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 37, 'Tout ce que le Père me donne viendra à moi, et je ne mettrai point dehors celui qui vient à moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 38, 'Car je suis descendu du ciel pour faire, non ma volonté, mais la volonté de Celui qui m\'a envoyé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 39, 'Or, la volonté de Celui qui m\'a envoyé, c\'est que je ne perde aucun de ceux qu\'il m\'a donnés, mais que je les ressuscite au dernier jour.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 40, 'Voici la volonté de mon Père: c\'est que quiconque contemple le Fils et croit en lui, ait la vie éternelle; et moi, je le ressusciterai au dernier jour.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 41, 'Cependant, les Juifs murmuraient contre lui, parce qu\'il avait dit: Je suis le pain descendu du ciel.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 42, 'Et ils disaient: N\'est-ce pas là Jésus, le fils de Joseph, dont nous connaissons le père et la mère? Comment donc dit-il: Je suis descendu du ciel?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 43, 'Jésus leur répondit: Ne murmurez pas entre vous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 44, 'Personne ne peut venir à moi, si le Père qui m\'a envoyé ne l\'attire; et je le ressusciterai au dernier jour.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 45, 'Il est écrit dans les prophètes: «Ils seront tous enseignés de Dieu.» Quiconque a écouté le Père et a été instruit par lui, vient à moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 46, 'Ce n\'est pas que personne ait vu le Père, si ce n\'est Celui qui vient de Dieu; celui-là a vu le Père.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 47, 'En vérité, en vérité, je vous le dis, celui qui croit a la vie éternelle.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 48, 'Je suis le pain de vie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 49, 'Vos pères ont mangé la manne dans le désert, et ils sont morts.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 50, 'C\'est ici le pain qui descend du ciel, afin que celui qui en mange ne meure point.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 51, 'Je suis le pain vivant qui est descendu du ciel; si quelqu\'un mange de ce pain, il vivra éternellement; et le pain que je donnerai pour la vie du monde, c\'est ma chair.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 52, 'Là-dessus, les Juifs disputaient entre eux, disant: Comment cet homme peut-il nous donner sa chair à manger?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 53, 'Jésus leur dit alors: En vérité, en vérité, je vous le déclare, si vous ne mangez la chair du Fils de l\'homme, et si vous ne buvez son sang, vous n\'avez point la vie en vous-mêmes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 54, 'Celui qui mange ma chair et qui boit mon sang, a la vie éternelle; et je le ressusciterai au dernier jour.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 55, 'Car ma chair est vraiment une nourriture, et mon sang est vraiment un breuvage.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 56, 'Celui qui mange ma chair et boit mon sang, demeure en moi, et moi en lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 57, 'De même que le Père, qui m\'a envoyé, est vivant, et que moi, je vis par le Père, de même aussi, celui qui me mange vivra par moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 58, 'C\'est ici le pain qui est descendu du ciel. Il n\'en est pas de lui comme de la manne que vos pères ont mangée., et ils sont morts; celui qui mange ce pain vivra éternellement.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 59, 'Jésus dit ces choses, en enseignant dans la synagogue, à Capernaüm.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 60, 'Plusieurs de ses disciples, l\'ayant entendu, dirent: Cette parole est dure; qui peut l\'écouter?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 61, 'Mais Jésus, connaissant en lui-même que ses disciples murmuraient à ce sujet, leur dit: Cela vous scandalise-t-il?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 62, 'Que sera-ce donc, si vous voyez le Fils de l\'homme monter où il était auparavant?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 63, 'C\'est l\'esprit qui vivifie, la chair ne sert de rien. Les paroles que je vous ai dites sont esprit et vie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 64, 'Mais il y en a parmi vous qui ne croient pas. En effet, Jésus savait, dès le commencement, quels étaient ceux qui ne croyaient pas, et quel était celui qui le trahirait.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 65, 'Et il disait: C\'est à cause de cela que je vous ai déclaré que personne ne peut venir à moi, si cela ne lui a pas été donné par le Père.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 66, 'Dès ce moment, plusieurs de ses disciples se retirèrent, et ils n\'allaient plus avec lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 67, 'Jésus dit aux Douze: Et vous, voulez-vous aussi vous en aller?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 68, 'Simon Pierre lui répondit: Seigneur, à qui irions-nous? Tu as les paroles de la vie éternelle;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 69, 'et nous avons cru, et nous avons connu que tu es le Saint de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 70, 'Jésus leur répondit: Ne vous ai-je pas choisis, vous les Douze? Et l\'un de vous est un démon!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 71, 'Or il parlait de Judas, fils de Simon Iscariote; car c\'était lui, l\'un des Douze, qui devait le trahir.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 1, 'Après cela, Jésus se mit à parcourir la Galilée: il ne voulait pas parcourir la Judée, parce que les Juifs cherchaient à le faire mourir.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 2, 'La fête des Juifs, appelée fête des Tabernacles, approchait.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 3, 'Et ses frères lui dirent: Pars d\'ici, et va en Judée, afin que tes disciples y voient aussi les oeuvres que tu fais.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 4, 'On ne fait rien en secret, quand on cherche à se faire connaître. Puisque tu fais ces choses, manifeste-toi au monde.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 5, 'En effet, ses frères eux-mêmes ne croyaient pas en lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 6, 'Jésus leur dit: Mon temps n\'est pas encore venu; pour vous, le temps est toujours favorable.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 7, 'Le monde ne peut vous haïr; mais il me hait, parce que je rends à ce sujet ce témoignage, que ses oeuvres sont mauvaises.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 8, 'Vous, montez à cette fête; pour moi je ne monte pas à cette fête, parce que mon temps n\'est pas encore accompli.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 9, 'Après leur avoir dit cela, il demeura en Galilée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 10, 'Lorsque ses frères furent montés à la fête, il y monta, lui aussi, mais comme en secret, et non pas publiquement.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 11, 'Les Juifs le cherchaient donc pendant la fête, et ils disaient: Où est-il?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 12, 'Et il y avait dans la foule une grande rumeur à son sujet. Les uns disaient: C\'est un homme de bien. Et les autres disaient: Non, certes; il séduit le peuple!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 13, 'Toutefois, personne ne parlait librement de lui, par crainte des Juifs.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 14, 'On était déjà au milieu de la fête, lorsque Jésus monta au temple et se mit à enseigner.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 15, 'Les Juifs, étonnés, disaient: Comment cet homme connaît-il les Écritures, lui qui n\'a pas étudié?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 16, 'Jésus leur répondit: Ma doctrine n\'est pas de moi, mais de Celui qui m\'a envoyé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 17, 'Si quelqu\'un veut faire la volonté de Dieu, il connaîtra si ma doctrine est de Dieu, ou si je parle de mon chef.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 18, 'Celui qui parle de son chef cherche sa propre gloire; mais celui qui cherche la gloire de celui qui l\'a envoyé, est digne de foi, et il n\'y a point d\'injustice en lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 19, 'Moïse ne vous a-t-il pas donné la Loi? Et aucun de vous n\'observe la Loi! Pourquoi cherchez-vous à me faire mourir?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 20, 'La foule répondit: Tu es possédé d\'un démon; qui donc cherche à te faire mourir?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 21, 'Jésus reprit en disant: J\'ai fait une oeuvre, et vous en êtes tous étonnés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 22, 'Moïse vous a donné la circoncision — qui vient, non de Moïse, lui-même, mais des patriarches, — et vous la pratiquez le jour du sabbat!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 23, 'Si un homme reçoit la circoncision le jour du sabbat, afin que la loi de Moïse ne soit pas violée, pourquoi vous irritez-vous contre moi, parce que j\'ai guéri un homme, dans son corps tout entier, le jour du sabbat?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 24, 'Ne jugez pas sur l\'apparence; mais jugez selon la justice.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 25, 'Quelques-uns des habitants de Jérusalem disaient: N\'est-ce pas là celui qu\'on cherche à faire mourir?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 26, 'Le voici qui parle librement, et on ne lui dit rien. Les chefs auraient-ils vraiment reconnu qu\'il est le Christ?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 27, 'Nous savons pourtant d\'où est celui-ci; or, quand le Christ viendra, personne ne saura d\'où il est.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 28, 'Alors Jésus, enseignant dans le temple, s\'écria: Vous me connaissez, et vous savez d\'où je suis. Je ne suis pas venu de moi-même, mais Celui qui m\'a envoyé est véritable, et vous ne le connaissez pas.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 29, 'Moi, je le connais; car je viens de lui, et c\'est lui qui m\'a envoyé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 30, 'Ils cherchaient donc à l\'arrêter; cependant personne ne mit la main sur lui, parce que son heure n\'était pas encore venue.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 31, 'Parmi le peuple, il y en eut beaucoup qui crurent en Jésus, et ils disaient: Quand le Christ viendra, fera-t-il plus de miracles que n\'en fait celui-ci?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 32, 'Les pharisiens entendirent les propos que la foule tenait à son sujet; et, de concert avec eux, les principaux sacrificateurs envoyèrent des agents pour s\'emparer de lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 33, 'Jésus dit alors: Je suis encore avec vous pour un peu de temps; puis, je m\'en vais à Celui qui m\'a envoyé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 34, 'Vous me chercherez et vous ne me trouverez pas, et là où je suis, vous ne pouvez venir.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 35, 'Les Juifs se dirent entre eux: Où doit-il donc aller, que nous ne le trouverons pas? Doit-il aller vers ceux qui sont dispersés parmi les Grecs et enseigner les Grecs?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 36, 'Que signifie ce qu\'il a dit: Vous me chercherez, et vous ne me trouverez pas, et là où je suis, vous ne pouvez venir?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 37, 'Le dernier, le grand jour de la fête, Jésus était là, debout, et il s\'écria: Si quelqu\'un a soif, qu\'il vienne à moi, et qu\'il boive.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 38, 'Celui qui croit en moi, des fleuves d\'eau vive, comme l\'a dit l\'Écriture, couleront de son sein.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 39, 'Il disait cela de l\'Esprit que devaient recevoir ceux qui croiraient en lui; car l\'Esprit n\'avait pas encore été donné, parce que Jésus n\'était pas encore glorifié.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 40, 'Plusieurs, parmi la foule, ayant entendu ces paroles, disaient: Celui-ci est véritablement le prophète.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 41, 'D\'autres disaient: C\'est le Christ. D\'autres encore: Le Christ viendra-t-il de la Galilée?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 42, 'L\'Écriture ne dit-elle pas que c\'est de la famille de David et du village de Bethléhem, d\'où était David, que le Christ doit sortir?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 43, 'Le peuple était donc divisé à son sujet.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 44, 'Et quelques-uns d\'entre eux voulaient l\'arrêter; mais personne ne mit la main sur lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 45, 'Les agents retournèrent donc vers les principaux sacrificateurs et les pharisiens; et ceux-ci leur dirent: Pourquoi ne l\'avez-vous pas amené?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 46, 'Les agents répondirent: Jamais homme n\'a parlé comme cet homme!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 47, 'Les pharisiens leur dirent: Avez-vous été séduits, vous aussi?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 48, 'Y a-t-il un seul des chefs ou des pharisiens qui ait cru en lui?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 49, 'Mais cette populace, qui ne connaît point la Loi, est exécrable!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 50, 'Nicodème — celui qui était venu précédemment trouver Jésus et qui était l\'un d\'entre eux — leur dit:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 51, 'Notre Loi juge-t-elle un homme sans qu\'on l\'ait entendu d\'abord, et sans qu\'on ait pris connaissance de ce qu\'il a fait?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 52, 'Ils lui répondirent: Es-tu Galiléen, toi aussi? Informe-toi, et tu verras qu\'il ne sort pas de prophète de la Galilée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 53, '[Chacun se retira dans sa maison.]');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 1, 'Jésus alla sur la montagne des Oliviers.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 2, 'Mais au point du jour, il retourna dans le temple; et comme tout le peuple venait à lui, il s\'assit, et il se mit à enseigner.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 3, 'Alors les scribes et les pharisiens lui amenèrent une femme qui avait été surprise en délit d\'adultère; et, l\'ayant placée au milieu de la foule,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 4, 'ils dirent à Jésus: Maître, cette femme a été prise en flagrant délit d\'adultère.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 5, 'Or, Moïse nous a ordonné dans la Loi de lapider ces sortes de personnes.; et toi, qu\'en dis-tu?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 6, 'Ils disaient cela pour le mettre à l\'épreuve, afin de pouvoir l\'accuser. Mais Jésus, s\'étant baissé, écrivait avec le doigt sur la terre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 7, 'Comme ils continuaient à l\'interroger, il se releva et leur dit: Que celui de vous qui est sans péché lui jette le premier la pierre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 8, 'Et, s\'étant baissé de nouveau, il écrivait sur la terre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 9, 'Quand ils entendirent cette parole, ils sortirent l\'un après l\'autre, en commençant par les plus âgés; et Jésus resta seul avec la femme, qui était là au milieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 10, 'Alors, Jésus s\'étant relevé et ne voyant personne que la femme, lui dit: Femme, où sont-ils, ceux qui t\'accusaient? Personne ne t\'a-t-il condamnée?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 11, 'Elle répondit: Personne, Seigneur. Et Jésus lui dit: Moi non plus, je ne te condamne pas; va, et ne pèche plus.]');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 12, 'Jésus prit de nouveau la parole, et il leur dit: Je suis la lumière du monde. Celui qui me suit ne marchera pas dans les ténèbres; mais il aura la lumière de la vie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 13, 'Alors les pharisiens lui dirent: Tu te rends témoignage à toi-même; ton témoignage n\'est pas digne de foi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 14, 'Jésus leur répondit: Quoique je me rende témoignage à moi-même, mon témoignage est digne de foi, car je sais d\'où je suis venu, et où je vais; mais vous, vous ne savez ni d\'où je viens, ni où je vais.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 15, 'Vous jugez selon la chair; moi, je ne juge personne.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 16, 'Et si j\'en viens à juger quelqu\'un, mon jugement est conforme à la vérité; car je ne suis pas seul, mais le Père qui m\'a envoyé est avec moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 17, 'Or, il est écrit dans votre Loi que le témoignage de deux personnes est digne de foi:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 18, 'je me rends, témoignage à moi-même, et le Père qui m\'a envoyé me rend aussi témoignage.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 19, 'Ils lui dirent: Où est ton Père? Jésus répondit: Vous ne connaissez ni moi, ni mon Père. Si vous me connaissiez, vous connaîtriez aussi mon Père.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 20, 'Jésus prononça ces paroles dans le lieu appelé le Trésor, en enseignant dans le temple; et personne ne mit la main sur lui, parce que son heure n\'était pas encore venue.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 21, 'Il leur dit encore: Je m\'en vais, et vous me chercherez, et vous mourrez dans votre péché. Vous ne pouvez venir où je vais.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 22, 'Les Juifs disaient donc: Va-t-il se donner la mort, puisqu\'il dit: Vous ne pouvez venir où je vais?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 23, 'Et il leur dit: Vous êtes d\'en bas; moi, je suis d\'en haut. Vous êtes de ce monde; moi, je ne suis pas de ce monde.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 24, 'Aussi vous ai-je dit que vous mourrez dans vos péchés; car, si vous ne croyez pas ce que je suis, vous mourrez dans vos péchés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 25, 'Alors ils lui demandèrent: Qui donc es-tu? Jésus leur répondit: Ce que je vous dis depuis le commencement.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 26, 'J\'ai sur vous beaucoup de choses à dire et de jugements à porter; mais Celui qui m\'a envoyé est vrai; et ce que j\'ai appris de lui, je le dis dans le monde.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 27, 'Ils ne comprirent point qu\'il leur parlait du Père.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 28, 'Jésus leur dit donc: Lorsque vous aurez élevé le Fils de l\'homme, alors vous connaîtrez ce que je suis et que je ne fais rien de moi-même, mais que je dis ce que mon Père m\'a enseigné.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 29, 'Celui qui m\'a envoyé est avec moi; il ne m\'a pas laissé seul, parce que je fais toujours ce qui lui est agréable.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 30, 'Comme Jésus parlait ainsi, plusieurs crurent en lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 31, 'Alors, il dit aux Juifs qui avaient cru en lui: Si vous demeurez dans ma parole, vous êtes véritablement mes disciples;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 32, 'vous connaîtrez la vérité, et la vérité vous affranchira.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 33, 'Les Juifs dirent: Nous sommes la postérité d\'Abraham, et nous n\'avons jamais été les esclaves de personne; comment donc dis-tu: Vous deviendrez libres?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 34, 'Jésus leur répondit: En vérité, en vérité, je vous le déclare, quiconque commet le péché est esclave du péché.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 35, 'Or, l\'esclave ne demeure pas pour toujours dans la maison; mais le fils y demeure pour toujours.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 36, 'Si donc le Fils vous affranchit, vous serez réellement libres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 37, 'Je sais que vous êtes la postérité d\'Abraham; mais vous cherchez à me faire mourir, parce que ma parole ne trouve point d\'accès en vous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 38, 'Je dis ce que j\'ai vu auprès de mon Père; et vous, vous faites ce que vous avez appris de votre père.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 39, 'Ils lui répondirent: Notre Père, à nous, c\'est Abraham. Jésus leur dit: Si vous étiez les enfants d\'Abraham, vous feriez les oeuvres d\'Abraham.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 40, 'Mais maintenant, vous cherchez à me faire mourir, moi qui vous ai dit la vérité que j\'ai entendue de Dieu. Abraham n\'a pas fait cela!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 41, 'Vous faites les oeuvres de votre père. Ils lui dirent: Nous ne sommes pas des enfants illégitimes; nous avons un seul Père, Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 42, 'Jésus leur répondit: Si Dieu était votre Père, vous m\'aimeriez, parce que je suis issu de Dieu et que je viens de lui; car je ne suis pas venu de moi-même, mais c\'est lui qui m\'a envoyé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 43, 'Pourquoi ne comprenez-vous pas mon langage? C\'est parce que vous ne pouvez écouter ma parole.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 44, 'Le père dont vous êtes issus, c\'est le Diable, et vous voulez accomplir les désirs de votre père. Il a été meurtrier dès le commencement; et il n\'a pas persévéré dans la vérité, parce qu\'il n\'y a point de vérité en lui. Quand il profère le mensonge, il parle de son propre fonds, parce qu\'il est menteur et le père du mensonge.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 45, 'Mais moi, parce que je dis la vérité, vous ne me croyez pas.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 46, 'Qui de vous me convaincra de péché? Et si je dis la vérité, pourquoi ne me croyez-vous pas?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 47, 'Celui qui est issu de Dieu, écoute les paroles de Dieu; c\'est pourquoi vous n\'écoutez pas, parce que vous n\'êtes pas de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 48, 'Les Juifs reprirent: N\'avons-nous pas raison de dire que tu es un Samaritain, et que tu es possédé d\'un démon?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 49, 'Jésus répondit: Je ne suis pas possédé d\'un démon, mais j\'honore mon Père, et vous, vous me déshonorez.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 50, 'Je ne cherche pas ma gloire; il y en a un qui la cherche, et qui juge.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 51, 'En vérité, en vérité, je vous le déclare, si quelqu\'un garde ma parole, il ne verra jamais la mort.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 52, 'Les Juifs lui dirent: Nous voyons bien maintenant que tu es possédé d\'un démon. Abraham est mort, les prophètes aussi, et tu dis: Si quelqu\'un garde ma parole, il ne mourra jamais!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 53, 'Es-tu plus grand que notre père Abraham, qui est mort? Les prophètes aussi sont morts; qui prétends-tu être?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 54, 'Jésus répondit: Si je me glorifie moi-même, ma gloire n\'est rien; c\'est mon Père qui me glorifie, lui dont vous dites qu\'il est votre Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 55, 'Cependant vous ne l\'avez pas connu; mais moi, je le connais. Et si je disais que je ne le connais pas, je serais menteur comme vous; mais je le connais et je garde sa parole.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 56, 'Abraham, votre père, a tressailli de joie à la pensée de voir mon jour: il l\'a vu, et il a été rempli de joie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 57, 'Les Juifs lui dirent: Tu n\'as pas encore cinquante ans, et tu as vu Abraham!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 58, 'Jésus leur répondit: En vérité, en vérité, je vous le déclare: Avant qu\'Abraham fût, je SUIS!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 59, 'Alors ils prirent des pierres pour les lui jeter; mais Jésus, se dérobant à eux, sortit du temple.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 1, 'Comme Jésus passait, il vit un homme aveugle de naissance.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 2, 'Et ses disciples lui demandèrent: Maître, qui a péché, cet homme ou ses parents, pour qu\'il soit né aveugle?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 3, 'Jésus répondit: Ce n\'est pas que lui ou ses parents aient péché, mais c\'est afin que les oeuvres de Dieu soient manifestées en lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 4, 'Tandis qu\'il fait jour, il me faut accomplir les oeuvres de Celui qui m\'a envoyé; la nuit vient, dans laquelle personne ne peut travailler.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 5, 'Pendant que je suis dans le monde, je suis la lumière du monde.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 6, 'Ayant dit cela, il cracha à terre et fit de la boue avec sa salive; et il oignit de cette boue les yeux de l\'aveugle.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 7, 'Puis il lui dit: Va; lave-toi au réservoir de Siloé — mot qui signifie Envoyé. — Il y alla donc et se lava, et il revint voyant clair.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 8, 'Ses voisins, et ceux qui l\'avaient vu auparavant demander l\'aumône, disaient: N\'est-ce pas celui qui se tenait assis et qui mendiait?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 9, 'Les uns disaient: C\'est lui. D\'autres disaient: Non, mais c\'est quelqu\'un qui lui ressemble. Lui disait: C\'est bien moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 10, 'Ils lui demandèrent alors: Comment tes yeux ont-ils été ouverts?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 11, 'Il répondit; Cet homme, qu\'on appelle Jésus, a fait de la boue; il en a oint mes yeux, et il m\'a dit: Va au réservoir de Siloé, et lave-toi. J\'y suis donc allé, je m\'y suis lavé, et je vois.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 12, 'Ils lui dirent: Où est cet homme? Il répondit: Je ne sais pas.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 13, 'Ils amenèrent aux pharisiens celui qui avait été aveugle.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 14, 'Or, c\'était un jour de sabbat que Jésus avait fait de la boue et avait ouvert les yeux de cet homme.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 15, 'Les pharisiens lui demandèrent à leur tour comment il avait recouvré la vue. Il leur répondit: Il m\'a mis de la boue sur les yeux; je me suis lavé, et je vois.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 16, 'Alors quelques-uns des pharisiens dirent: Cet homme ne vient point de la part de Dieu, puisqu\'il n\'observe pas le sabbat. Mais d\'autres disaient: Comment un pécheur pourrait-il faire de tels miracles? Et ils étaient divisés entre eux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 17, 'Alors ils demandèrent de nouveau à l\'aveugle: Et toi, que dis-tu de cet homme, qui t\'a ouvert les yeux? Il répondit: C\'est un prophète!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 18, 'Mais les Juifs ne crurent pas que cet homme eût été aveugle et qu\'il eût recouvré la vue, jusqu\'à ce qu\'ils eussent fait venir son père et sa mère.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 19, 'Ils les interrogèrent et leur dirent: Est-ce bien là votre fils, que vous dites être né aveugle? Comment donc voit-il maintenant?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 20, 'Ses parents répondirent: Nous savons que c\'est là notre fils, et qu\'il est né aveugle;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 21, 'mais comment il se fait qu\'il voit maintenant, nous ne le savons pas. Nous ne savons pas non plus qui lui a ouvert les yeux. Interrogez-le; il a de l\'âge, il s\'expliquera lui-même.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 22, 'Ses parents dirent cela, parce qu\'ils craignaient les Juifs; car les Juifs avaient déjà décidé que si quelqu\'un reconnaissait Jésus pour le Christ, il serait chassé de la synagogue.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 23, 'C\'est pour cela que ses parents dirent: Il a de l\'âge, interrogez-le.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 24, 'Les pharisiens appelèrent donc pour la seconde fois l\'homme qui avait été aveugle, et ils lui dirent: Donne gloire à Dieu! Nous savons que cet homme est un pécheur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 25, 'Il répondit: Je ne sais si c\'est un pécheur; je sais une chose, c\'est que j\'étais aveugle, et que maintenant je vois.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 26, 'Ils lui dirent encore: Que t\'a-t-il fait? Comment t\'a-t-il ouvert les yeux?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 27, 'Il leur répondit: Je vous l\'ai déjà dit, et vous ne m\'avez pas écouté. Pourquoi voulez-vous l\'entendre encore une fois? Voulez-vous, vous aussi, devenir ses disciples?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 28, 'Alors ils se mirent à l\'injurier, et ils lui dirent: C\'est toi qui es son disciple; nous, nous sommes les disciples de Moïse.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 29, 'Nous savons que Dieu a parlé à Moïse; mais celui-ci, nous ne savons d\'où il est.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 30, 'Cet homme répondit: C\'est là ce qui est étonnant, que vous ne sachiez pas d\'où il est, alors qu\'il m\'a ouvert les yeux!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 31, 'Nous savons que Dieu n\'exauce pas les pécheurs; mais si quelqu\'un craint Dieu et fait sa volonté, il l\'exauce.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 32, 'Jamais on n\'a entendu dire que quelqu\'un ait ouvert les yeux d\'un aveugle-né.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 33, 'Si cet homme ne venait pas de la part de Dieu, il ne pourrait rien faire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 34, 'Ils lui répondirent: Tu es né entièrement dans le péché, et tu veux nous enseigner! Puis ils le jetèrent dehors.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 35, 'Jésus apprit qu\'on l\'avait chassé; et, l\'ayant rencontré, il lui dit: Crois-tu au Fils de Dieu?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 36, 'Il répondit: Qui est-il, Seigneur, pour que je croie en lui?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 37, 'Jésus lui dit: Tu l\'as vu, et c\'est lui-même qui te parle!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 38, 'Il reprit: Je crois. Seigneur! Et il se prosterna devant lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 39, 'Alors Jésus dit: Je suis venu dans le monde pour exercer ce jugement: que ceux qui ne voient point, voient, et que ceux qui voient, deviennent aveugles.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 40, 'Ceux des pharisiens qui étaient auprès de lui entendirent cela, et ils lui dirent: Et nous, sommes-nous aussi des aveugles?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 41, 'Jésus leur répondit: Si vous étiez aveugles, vous seriez sans péché, mais comme vous dites: Nous voyons. — c\'est pour cela que votre péché subsiste.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 1, 'En vérité, en vérité, je vous le déclare, celui qui n\'entre pas par la porte dans la bergerie, mais qui y monte par un autre endroit, celui-là est un voleur et un brigand.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 2, 'Mais celui qui entre par la porte est le berger des brebis.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 3, 'Le portier lui ouvre, et les brebis entendent sa voix; il appelle ses brebis par leur nom, et il les mène dehors.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 4, 'Quand il les a toutes fait sortir, il marche devant elles, et les brebis le suivent, parce qu\'elles connaissent sa voix.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 5, 'Mais elles ne suivront pas un étranger; au contraire, elles le fuiront, parce qu\'elles ne connaissent point la voix des étrangers.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 6, 'Jésus leur dit cette similitude, mais ils ne comprirent pas ce qu\'il voulait dire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 7, 'Jésus leur dit encore: En vérité, en vérité, je vous le déclare, je suis la porte des brebis.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 8, 'Tous ceux qui sont venus avant moi sont des voleurs et des brigands; mais les brebis ne les ont pas écoutés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 9, 'Je suis la porte: si quelqu\'un entre par moi, il sera sauvé; il entrera et sortira, et il trouvera de la pâture.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 10, 'Le voleur ne vient que pour dérober, pour égorger et pour détruire; moi, je suis venu, afin que les brebis aient la vie, et qu\'elles l\'aient en abondance.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 11, 'Je suis le bon berger; le bon berger donne sa vie pour ses brebis.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 12, 'Le mercenaire, qui n\'est pas le berger, et à qui les brebis n\'appartiennent pas, s\'il voit venir le loup, abandonne les brebis et s\'enfuit; et le loup les ravit et les disperse.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 13, 'C\'est qu\'il est mercenaire, et qu\'il ne se soucie pas des brebis.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 14, 'Je suis le bon berger! Je connais mes brebis, et mes brebis me connaissent,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 15, 'comme le Père me connaît et comme je connais le Père; et je donne ma vie pour mes brebis.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 16, 'J\'ai encore d\'autres brebis qui ne sont pas de cette bergerie; il faut aussi que je les amène. Elles entendront ma voix, et il y aura un seul troupeau, un seul berger!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 17, 'Voici pourquoi le Père m\'aime: c\'est parce que je donne ma vie, afin de la reprendre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 18, 'Personne ne me l\'ôte, mais je la donne de moi-même; j\'ai le pouvoir de la donner, et j\'ai le pouvoir de la reprendre: j\'ai reçu cet ordre de mon Père.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 19, 'Les Juifs furent de nouveau divisés, à cause de ces paroles.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 20, 'Plusieurs d\'entre eux disaient: Il est possédé d\'un démon, il est hors de sens; pourquoi l\'écoutez-vous?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 21, 'D\'autres disaient: Ce ne sont pas là les paroles d\'un possédé. Un démon peut-il ouvrir les yeux des aveugles?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 22, 'On célébrait à Jérusalem la fête de la Dédicace. C\'était l\'hiver;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 23, 'et Jésus se promenait dans le temple, sous le portique de Salomon.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 24, 'Les Juifs se rassemblèrent autour de lui, et lui dirent: Jusques à quand nous tiendras-tu l\'esprit en suspens? Si tu es le Christ, dis-le-nous franchement.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 25, 'Jésus leur répondit: Je vous l\'ai dit, et vous ne croyez pas; les oeuvres que je fais au nom de mon Père me rendent témoignage.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 26, 'Mais vous ne croyez pas, parce que vous n\'êtes pas de mes brebis.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 27, 'Mes brebis entendent ma voix; je les connais, et elles me suivent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 28, 'Je leur donne la vie éternelle; elles ne périront jamais, et nul ne les ravira de ma main.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 29, 'Mon Père, qui me les a données, est plus grand que tous; et personne ne peut les ravir de la main du Père.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 30, 'Moi et le Père, nous sommes un.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 31, 'Les Juifs prirent de nouveau des pierres pour le lapider.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 32, 'Jésus leur dit: J\'ai fait sous vos yeux beaucoup de bonnes oeuvres de la part du Père; pour laquelle me lapidez-vous?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 33, 'Les Juifs lui répondirent: Ce n\'est pas pour une bonne oeuvre que nous te lapidons, mais pour un blasphème, parce que, étant homme, tu te fais Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 34, 'Jésus leur répondit: N\'est-il pas écrit dans votre Loi: «J\'ai dit: Vous êtes des dieux»?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 35, 'Si elle a appelé «dieux» ceux à qui la parole de Dieu était adressée, et si l\'Écriture ne peut être anéantie,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 36, 'comment dites-vous que je blasphème, — moi que le Père a consacré et qu\'il a envoyé dans le monde; — parce que j\'ai dit: Je suis le Fils de Dieu.?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 37, 'Si je ne fais pas les oeuvres de mon Père, ne me croyez point.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 38, 'Mais si je les fais, quand même vous ne me croiriez pas, croyez à mes oeuvres, afin que vous appreniez et que vous sachiez que le Père est en moi, et que je suis dans le Père.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 39, 'Ils cherchaient encore à s\'emparer de lui; mais il s\'échappa de leurs mains.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 40, 'Puis il s\'en alla de nouveau au delà du Jourdain, à l\'endroit où Jean avait baptisé tout d\'abord, et il y demeura.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 41, 'Beaucoup de gens vinrent à lui, et ils disaient: Jean n\'a fait aucun miracle, mais tout ce que Jean a dit de cet homme était vrai.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 42, 'Et il y en eut là plusieurs qui crurent en lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 1, 'Il y avait un homme malade, nommé Lazare, qui était de Béthanie, le village de Marie et de Marthe, sa soeur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 2, 'Marie était celle qui oignit le Seigneur d\'une huile parfumée, et qui lui essuya les pieds avec ses cheveux; et c\'était son frère Lazare qui était malade.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 3, 'Les soeurs envoyèrent donc dire à Jésus: Seigneur, voici que celui que tu aimes est malade.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 4, 'Jésus, ayant entendu ces paroles, dit: Cette maladie n\'est pas à la mort, mais elle est pour la gloire de Dieu, afin que le Fils de Dieu soit glorifié par elle.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 5, 'Or, Jésus aimait Marthe, et sa soeur, et Lazare.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 6, 'Lorsqu\'il eut appris que celui-ci était malade, il resta encore deux jours dans le lieu où il se trouvait.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 7, 'Après cela, il dit à ses disciples: Retournons en Judée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 8, 'Les disciples lui dirent: Maître, hier encore les Juifs cherchaient à te lapider, et tu retournes au milieu d\'eux!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 9, 'Jésus répondit: N\'y a-t-il pas douze heures dans le jour? Si quelqu\'un marche pendant le jour, il ne bronche point, parce qu\'il voit la lumière de ce monde.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 10, 'Mais si quelqu\'un marche pendant la nuit, il bronche, parce qu\'il n\'a pas la lumière.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 11, 'Il parla ainsi, puis il ajouta: Lazare, notre ami, s\'est endormi; mais je vais le réveiller.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 12, 'Ses disciples lui dirent: Seigneur, s\'il dort, il sera guéri.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 13, 'Or, Jésus avait dit cela de la mort de Lazare; mais ils crurent qu\'il parlait du sommeil ordinaire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 14, 'Jésus leur dit alors ouvertement: Lazare est mort.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 15, 'Et je me réjouis pour vous de ce que je n\'étais pas là, afin que vous croyiez; mais allons auprès de lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 16, 'Sur quoi Thomas, appelé Didyme, dit aux autres disciples: Allons-y, nous aussi, pour mourir avec lui!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 17, 'Jésus, à son arrivée, trouva qu\'il y avait déjà quatre jours que Lazare était dans le tombeau.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 18, 'Or, Béthanie n\'était éloignée de Jérusalem que d\'environ quinze stades.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 19, 'Plusieurs des Juifs étaient venus auprès de Marthe et de Marie pour les consoler de la mort de leur frère.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 20, 'Quand Marthe apprit que Jésus arrivait, elle alla au-devant de lui; mais Marie était restée assise à la maison.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 21, 'Marthe dit à Jésus: Seigneur, si tu avais été ici, mon frère ne serait pas mort;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 22, 'et maintenant même, je sais que tout ce que tu demanderas à Dieu, Dieu te l\'accordera.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 23, 'Jésus lui dit: Ton frère ressuscitera.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 24, 'Marthe lui répondit: Je sais qu\'il ressuscitera, à la résurrection, au dernier jour.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 25, 'Jésus lui dit: Je suis la résurrection et la vie; celui qui croit en moi vivra quand même il serait mort.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 26, 'Et quiconque vit et croit en moi ne mourra jamais. Crois-tu cela?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 27, 'Elle lui répondit: Oui, Seigneur, je crois que tu es le Christ, le Fils de Dieu, celui qui devait venir dans le monde.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 28, 'Quand elle eut dit ces paroles, elle s\'en alla, appela en secret Marie, sa soeur, et lui dit: Le Maître est là, et il t\'appelle.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 29, 'Dès que Marie eut entendu cette parole, elle se leva promptement et alla vers lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 30, 'Or Jésus n\'était pas encore entré dans le village, mais il était à l\'endroit ou Marthe était venue à sa rencontre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 31, 'Quand les Juifs, qui étaient avec Marie dans la maison et qui la consolaient, la virent se lever et sortir si promptement, ils la suivirent, croyant qu\'elle allait au tombeau pour y pleurer.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 32, 'Mais Marie, étant arrivée à l\'endroit où se trouvait Jésus, se jeta à ses pieds, dès qu\'elle l\'aperçut, et elle lui dit: Seigneur, si tu avais été ici, mon frère ne serait pas mort!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 33, 'Lorsque Jésus vit qu\'elle pleurait, et que les Juifs qui étaient venus avec elle pleuraient aussi, il frémit en son esprit et il fut tout troublé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 34, 'Puis il demanda: Où l\'avez-vous mis? Ils lui répondirent: Seigneur, viens et vois.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 35, 'Alors Jésus pleura.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 36, 'Les Juifs disaient donc: Voyez comme il l\'aimait!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 37, 'Et quelques-uns d\'entre eux dirent: Lui qui a ouvert les yeux de l\'aveugle, ne pouvait-il pas faire aussi que cet homme ne mourût pas?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 38, 'Alors Jésus, frémissant de nouveau en lui-même, vint au tombeau: c\'était une grotte à l\'entrée de laquelle une pierre avait été placée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 39, 'Jésus dit: Otez la pierre. Marthe, la soeur du mort répondit: Seigneur, il sent déjà; car il est là depuis quatre jours.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 40, 'Jésus reprit: Ne t\'ai-je pas dit que, si tu crois, tu verras la gloire de Dieu?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 41, 'Ils ôtèrent donc la pierre. Alors Jésus leva les yeux au ciel et dit: Père, je te rends grâces de ce que tu m\'as exaucé!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 42, 'Je savais bien que tu m\'exauces toujours; mais je parle ainsi à cause de cette foule qui m\'entoure, afin qu\'elle croie que c\'est toi qui m\'as envoyé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 43, 'Quand il eut dit cela, il cria d\'une voix forte: Lazare, sors!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 44, 'Le mort sortit, ayant les mains et les pieds liés de bandelettes, et le visage enveloppé d\'un suaire. Jésus leur dit: Déliez-le, et laissez-le aller.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 45, 'Plusieurs des Juifs qui étaient venus auprès de Marie, et qui avaient vu ce que Jésus avait fait, crurent en lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 46, 'Mais quelques-uns d\'entre eux allèrent trouver les pharisiens, et ils leur rapportèrent ce qu\'avait fait Jésus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 47, 'Alors les principaux sacrificateurs et les pharisiens réunirent le Sanhédrin et dirent: Que ferons-nous? Cet homme, en effet, opère beaucoup de miracles.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 48, 'Si nous le laissons faire, tout le monde croira en lui; et les Romains viendront détruire et ce lieu et notre nation.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 49, 'Mais l\'un d\'entre eux, Caïphe, qui était souverain sacrificateur cette année-là, leur dit: Vous n\'y entendez rien!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 50, 'Vous ne considérez pas qu\'il vaut mieux pour vous qu\'un seul homme meure pour le peuple, et que toute la nation ne périsse pas.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 51, 'Or, il ne dit pas cela de lui-même, mais, étant souverain sacrificateur cette année-là, il prophétisa que Jésus devait mourir pour la nation;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 52, 'et non seulement pour la nation, mais aussi pour rassembler en un seul corps les enfants de Dieu dispersés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 53, 'Depuis ce jour-là, ils formèrent le projet de le faire mourir.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 54, 'C\'est pourquoi Jésus ne se montrait plus ouvertement parmi les Juifs; mais il s\'en alla dans la contrée voisine du désert, à une ville appelée Éphraïm; et il y séjourna avec ses disciples.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 55, 'La Pâque des Juifs était proche, et beaucoup de gens du pays montèrent à Jérusalem, avant la Pâque, pour se purifier.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 56, 'Ils cherchaient donc Jésus; et, se tenant dans le temple, ils se disaient les uns aux autres: Que vous en semble? Ne viendra-t-il pas à la fête?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 57, 'Or, les principaux sacrificateurs et les pharisiens avaient donné des ordres pour que, si quelqu\'un savait où se trouvait Jésus, il le déclarât, afin qu\'on pût s\'emparer de lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 1, 'Six jours avant la Pâque, Jésus vint à Béthanie, où était Lazare qu\'il avait ressuscité des morts.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 2, 'On lui fit là un souper, et Marthe servait; Lazare était l\'un de ceux qui étaient à table avec lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 3, 'Alors Marie, ayant pris une livre d\'un parfum de nard pur, qui était de grand prix, oignit les pieds de Jésus, et les essuya avec ses cheveux; et la maison fut remplie de l\'odeur de ce parfum.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 4, 'Mais Judas l\'Iscariote, l\'un de ses disciples, celui qui devait le trahir, dit:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 5, 'Pourquoi n\'a-t-on pas vendu ce parfum trois cents deniers, pour les donner aux pauvres? —');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 6, 'Il disait cela, non qu\'il se souciât des pauvres, mais parce qu\'il était voleur et que, tenant la bourse, il prenait ce qu\'on y mettait. —');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 7, 'Jésus répondit: Laisse-la; elle a gardé ce parfum pour le jour de ma sépulture.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 8, 'Car vous avez toujours les pauvres avec vous; mais moi, vous ne m\'avez pas toujours.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 9, 'Un grand nombre de Juifs apprirent que Jésus était là, et ils vinrent, non seulement à cause de lui, mais aussi pour voir Lazare, qu\'il avait ressuscité des morts.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 10, 'Alors les principaux sacrificateurs résolurent de faire mourir aussi Lazare, parce que plusieurs des Juifs, à cause de lui, se séparaient d\'eux et croyaient en Jésus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 11, 'Le lendemain, une grande foule, venue pour la fête, ayant su que Jésus se rendait à Jérusalem,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 12, 'prit des branches de palmiers, et sortit au-devant de lui, en criant: Hosanna! Béni soit celui qui vient au nom du Seigneur, le Roi d\'Israël!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 13, 'Jésus, ayant trouvé un ânon, s\'assit dessus, conformément à ce qui est écrit:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 14, '«Ne crains point, fille de Sion; voici ton roi qui vient, monté sur le poulain d\'une ânesse.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 15, 'Ses disciples ne comprirent pas cela, tout d\'abord; mais quand Jésus eut été glorifié, alors ils se souvinrent que ces choses avaient été écrites à son sujet, et qu\'elles s\'étaient réalisées en lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 16, 'C\'est pourquoi, la foule qui était avec lui, lorsqu\'il avait rappelé Lazare du tombeau et l\'avait ressuscité des morts, lui rendait témoignage.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 17, 'C\'est aussi pour cela que la multitude était allée au-devant de lui, parce qu\'elle avait appris qu\'il avait accompli ce miracle.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 18, 'Là-dessus les pharisiens se disaient les uns aux autres: Vous voyez que vous ne gagnez rien; voilà que tout le monde court après lui!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 19, 'Or, il y avait là quelques Grecs, parmi ceux qui étaient montés pour adorer pendant la fête.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 20, 'Ils vinrent trouver Philippe, de Bethsaïda en Galilée, et lui firent cette demande: Seigneur, nous voudrions voir Jésus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 21, 'Philippe alla le dire à André; André et Philippe vinrent le dire à Jésus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 22, 'Alors Jésus leur répondit: L\'heure est venue où le Fils de l\'homme doit être glorifié.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 23, 'En vérité, en vérité, je vous le déclare, si le grain de froment ne meurt après être tombé dans la terre, il demeure seul; mais s\'il meurt, il porte beaucoup de fruit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 24, 'Celui qui aime sa vie la perdra; et celui qui hait sa vie en ce monde, la conservera pour la vie éternelle.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 25, 'Si quelqu\'un me sert, qu\'il me suive, et là où je suis, là aussi sera mon serviteur; si quelqu\'un me sert, mon Père l\'honorera.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 26, 'Maintenant mon âme est troublée; et que dirai-je? Père, délivre-moi de cette heure? Mais c\'est pour cela même que je suis venu jusqu\'à cette heure!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 27, 'Père, glorifie ton nom! Alors il vint une voix du ciel qui dit: Je l\'ai glorifié, et je le glorifierai encore!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 28, 'La foule qui était là, et qui avait entendu la voix, disait que c\'était le tonnerre; d\'autres disaient: Un ange lui a parlé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 29, 'Jésus prit la parole et dit: Ce n\'est pas pour moi que cette voix s\'est fait entendre, mais pour vous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 30, 'Maintenant a lieu le jugement de ce monde; maintenant le prince de ce monde va être jeté dehors.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 31, 'Et moi, quand j\'aurai été élevé de la terre, j\'attirerai tous les hommes à moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 32, 'Il disait cela pour indiquer de quelle mort il devait mourir.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 33, 'La foule lui dit: Nous avons appris par la Loi que le Christ doit demeurer éternellement; comment peux-tu dire qu\'il faut que le Fils de l\'homme soit élevé? Qui est ce Fils de l\'homme?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 34, 'Alors Jésus leur répondit: La lumière est encore parmi vous pour un peu de temps. Marchez pendant que vous avez la lumière, de peur que les ténèbres ne vous surprennent; celui qui marche dans les ténèbres ne sait où il va.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 35, 'Pendant que vous avez de la lumière, croyez en la lumière, afin que vous deveniez des enfants de la lumière.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 36, 'Jésus parla ainsi; puis il s\'en alla, et il se tint caché loin d\'eux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 37, 'Or, bien qu\'il eût opéré tant de miracles en leur présence, ils ne croyaient pas en lui,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 38, 'afin que cette parole d\'Ésaïe le prophète fût accomplie: «Seigneur, qui a cru à notre prédication, et à qui la puissance du Seigneur a-t-elle été révélée»?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 39, 'D\'ailleurs, ils ne pouvaient croire, parce qu\'Ésaïe a dit encore:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 40, '«Il a aveuglé leurs yeux, et il a endurci leur coeur, afin qu\'ils ne voient pas de leurs yeux, et qu\'ils ne comprennent pas de leur coeur; qu\'ils ne se convertissent pas, et que je ne les guérisse point.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 41, 'Ésaïe dit ces choses, lorsqu\'il vit sa gloire et qu\'il parla de lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 42, 'Cependant il y en eut plusieurs, même parmi les chefs, qui crurent en Jésus; mais, à cause des pharisiens, ils ne l\'avouaient pas, de peur d\'être chassés de la synagogue.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 43, 'Car ils aimaient la gloire qui vient des hommes, plus que la gloire qui vient de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 44, 'Cependant Jésus éleva la voix et dit: Celui qui croit en moi, ne croit pas en moi, mais en Celui qui m\'a envoyé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 45, 'Et celui qui me voit, voit Celui qui m\'a envoyé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 46, 'Je suis venu dans le monde, moi qui suis la lumière, afin que quiconque croit en moi ne demeure pas dans les ténèbres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 47, 'Et si quelqu\'un entend mes paroles et ne les garde pas, ce n\'est pas moi qui le juge; car je ne suis pas venu pour juger le monde, mais pour le sauver.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 48, 'Celui qui me rejette et ne reçoit pas mes paroles, a déjà Celui qui le juge; la parole que j\'ai annoncée, c\'est elle qui le jugera au dernier jour.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 49, 'En effet, je n\'ai point parlé de mon chef; mais le Père, qui m\'a envoyé, m\'a prescrit ce que je dois dire et comment je dois parler.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 50, 'Et je sais que son commandement, c\'est la vie éternelle. Ainsi, les choses que je dis, je les dis comme le Père me les a dites.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 1, 'Avant la fête de Pâque, sachant que l\'heure était venue pour lui de passer de ce monde au Père, Jésus qui avait aimé les siens dans le monde, les aima jusqu\'à la fin.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 2, 'Pendant le souper — le Diable ayant déjà mis au coeur de Judas Iscariote, fils de Simon, le dessein de le trahir, —');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 3, 'Jésus, qui savait que le Père lui avait remis toutes choses entre les mains, qu\'il était venu de Dieu et qu\'il s\'en allait à Dieu,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 4, 'se leva de table, ôta son vêtement, et, ayant pris un linge, il s\'en ceignit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 5, 'Ensuite il remplit d\'eau le bassin, et il se mit à laver les pieds de ses disciples et à les essuyer avec le linge dont il était ceint.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 6, 'Il vint donc à Simon Pierre, qui lui dit: Toi, Seigneur, tu me laverais les pieds!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 7, 'Jésus lui répondit: Tu ne sais pas maintenant ce que je fais, mais tu le sauras plus tard.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 8, 'Pierre lui dit: Tu ne me laveras jamais les pieds! Jésus lui répondit: Si je ne te lave, tu n\'auras point de part avec moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 9, 'Simon Pierre lui dit: Seigneur! non seulement les pieds, mais aussi les mains et la tête.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 10, 'Jésus lui répondit: Celui qui s\'est déjà baigné n\'a plus qu\'à se laver les pieds; il est entièrement purifié. Or, vous êtes purs, mais non pas tous!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 11, 'Car il savait quel était celui qui le trahirait; c\'est pour cela qu\'il dit: Vous n\'êtes pas tous purs.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 12, 'Après qu\'il leur eut lavé les pieds, il reprit son vêtement; et, s\'étant remis à table, il leur dit: Comprenez-vous ce que je vous ai fait?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 13, 'Vous m\'appelez Maître et Seigneur et vous dites bien, car je le suis.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 14, 'Si donc je vous ai lavé les pieds, moi, le Seigneur et le Maître, vous devez aussi vous laver les pieds les uns aux autres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 15, 'Car je vous ai donné un exemple, afin que vous fassiez comme je vous ai fait.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 16, 'En vérité, en vérité, je vous le dis, le serviteur n\'est pas plus grand que son maître, ni l\'envoyé plus grand que celui qui l\'envoie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 17, 'Si vous savez ces choses, vous êtes bienheureux, pourvu que vous les pratiquiez.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 18, 'Je ne parle pas de vous tous; je connais ceux que j\'ai choisis; mais il faut que cette parole de l\'Écriture soit accomplie: «Celui qui mange mon pain, a levé le talon contre moi.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 19, 'Je vous le dis dès à présent, avant que la chose arrive, afin que, quand elle sera arrivée, vous croyiez ce que je suis.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 20, 'En vérité, en vérité, je vous le dis, quiconque reçoit celui que j\'ai envoyé, me reçoit; et quiconque me reçoit, reçoit celui qui m\'a envoyé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 21, 'Quand Jésus eut ainsi parlé, il fut troublé en son esprit, et il dit ouvertement: En vérité, en vérité, je vous le déclare, l\'un de vous me trahira!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 22, 'Les disciples se regardaient les uns les autres, ne sachant de qui il parlait.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 23, 'Or, il y avait un des disciples qui était, couché sur le sein de Jésus; c\'était celui que Jésus aimait.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 24, 'Simon Pierre lui fit signe, en lui disant: Dis-nous quel est celui dont il parle.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 25, 'Lui donc, s\'étant penché sur le sein de Jésus, lui demanda: Seigneur, qui est-ce?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 26, 'Jésus répondit: C\'est celui à qui je donnerai le morceau que je vais tremper. Puis ayant trempé un morceau, il le prit et le donna à Judas Iscariote, fils de Simon.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 27, 'Aussitôt que Judas eut pris le morceau, Satan entra en lui. Jésus lui dit alors: Ce que tu fais, fais-le au plus tôt.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 28, 'Mais aucun de ceux qui étaient à table ne comprit pourquoi il lui parlait ainsi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 29, 'Quelques-uns pensaient que, comme Judas avait la bourse, Jésus lui disait: Achète ce dont nous avons besoin pour la fête; ou: Donne quelque chose aux pauvres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 30, 'Judas, ayant pris le morceau, sortit aussitôt. Et il faisait nuit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 31, 'Quand Judas fut sorti, Jésus dit: Maintenant le Fils de l\'homme est glorifié, et Dieu est glorifié en lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 32, 'Dieu aussi le glorifiera en lui-même, et il le glorifiera bientôt.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 33, 'Mes petits enfants, je suis encore avec vous pour un peu de temps; vous me chercherez, et comme je l\'ai dit aux Juifs, je vous le dis aussi maintenant: Vous ne pouvez venir où je vais.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 34, 'Je vous donne un commandement nouveau, c\'est que vous vous aimiez les uns les autres; comme je vous ai aimés, vous aussi, aimez-vous les uns les autres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 35, 'C\'est à ceci que tous connaîtront que vous êtes mes disciples, si vous avez de l\'amour les uns pour les autres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 36, 'Simon Pierre lui dit: Seigneur, où vas-tu? Jésus lui répondit: Tu ne saurais maintenant me suivre où je vais; mais tu me suivras plus tard.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 37, 'Pierre lui dit: Seigneur, pourquoi ne puis-je pas te suivre à présent? Je donnerai ma vie pour toi!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 38, 'Jésus lui répondit: Tu donneras ta vie pour moi? En vérité, en vérité, je te le dis, le coq ne chantera pas, que tu ne m\'aies renié trois fois!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 1, 'Que votre coeur ne se trouble point; croyez en Dieu, croyez aussi en moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 2, 'Il y a beaucoup de demeures dans la maison de mon Père; si cela n\'était pas, je vous l\'aurais dit. Je vais vous préparer une place.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 3, 'Et quand je m\'en serai allé et que je vous aurai préparé une place, je reviendrai et je vous prendrai avec moi, afin que là où je suis, vous y soyez aussi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 4, 'Et vous savez où je vais, et vous en savez le chemin.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 5, 'Thomas lui dit: Seigneur, nous ne savons où tu vas; comment en saurions-nous le chemin?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 6, 'Jésus répondit: Je suis le chemin, la vérité et la vie; personne ne vient au Père que par moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 7, 'Si vous me connaissiez, vous connaîtriez aussi mon Père; et dès à présent, vous le connaissez et vous l\'avez vu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 8, 'Philippe lui dit: Seigneur, montre-nous le Père, et cela nous suffit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 9, 'Jésus répondit: Il y a si longtemps que je suis avec vous, et tu ne m\'as pas connu, Philippe! Celui qui m\'a vu, a vu le Père. Comment dis-tu; Montre-nous le Père?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 10, 'Ne crois-tu pas que je suis dans le Père, et que le Père est en moi? Les paroles que je vous dis, je ne les dis pas de moi-même; le Père, qui demeure en moi, c\'est lui qui accomplit ses propres oeuvres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 11, 'Croyez-moi, quand je dis que je suis dans le Père et que le Père est dans moi; sinon, croyez à cause de mes oeuvres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 12, 'En vérité, en vérité, je vous le dis, celui qui croit en moi fera aussi les oeuvres que je fais; il en fera même de plus grandes, parce que je vais auprès du Père.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 13, 'Et quoi que vous demandiez en mon nom, je le ferai, afin que le Père soit glorifié dans le fils.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 14, 'Si vous demandez quelque chose en mon nom, je le ferai.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 15, 'Si vous m\'aimez, vous garderez mes commandements.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 16, 'Et je prierai le Père, qui vous donnera un autre Consolateur, afin qu\'il soit éternellement avec vous,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 17, 'l\'Esprit de vérité, que le monde ne peut recevoir, parce qu\'il ne le voit pas et ne le connaît pas; mais vous, vous le connaissez, parce qu\'il demeure avec vous, et il sera en vous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 18, 'Je ne vous laisserai pas orphelins, je viendrai à vous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 19, 'Encore un peu de temps, et le monde ne me verra plus, mais vous me verrez; parce que je vis, vous vivrez aussi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 20, 'En ce jour-là, vous reconnaîtrez que je suis en mon Père, que vous êtes en moi, et que je suis en vous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 21, 'Celui qui a mes commandements et qui les garde, c\'est celui-là qui m\'aime. Et celui qui m\'aime sera aimé de mon Père; et je l\'aimerai, et je me ferai connaître à lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 22, 'Jude, non pas l\'Iscariote, lui dit: Seigneur, d\'où vient que tu te feras connaître à nous, et non pas au monde?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 23, 'Jésus lui répondit: Si quelqu\'un m\'aime, il gardera ma parole, et mon Père l\'aimera, et nous viendrons à lui, et nous ferons notre demeure chez lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 24, 'Celui qui ne m\'aime pas ne garde pas mes paroles; et la parole que vous entendez n\'est pas de moi, mais elle est du Père qui m\'a envoyé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 25, 'Je vous ai dit ces choses, pendant que je demeurais avec vous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 26, 'Mais le Consolateur, le Saint-Esprit, que le Père enverra en mon nom, celui-là vous enseignera toutes choses, et vous remettra en mémoire tout ce que je vous ai dit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 27, 'Je vous laisse la paix; je vous donne ma paix; je ne vous la donne pas comme le monde la donne. Que votre coeur ne se trouble pas et qu\'il ne craigne point.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 28, 'Vous avez entendu que je vous ai dit: Je m\'en vais, et je reviens à vous. Si vous m\'aimiez, vous vous réjouiriez de ce que je vais auprès du Père, parce que le Père est plus grand que moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 29, 'Et maintenant, je vous ai dit ces choses avant qu\'elles arrivent, afin que, quand elles seront arrivées, vous croyiez.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 30, 'Je ne vous parlerai plus guère; car le prince de ce monde vient, et il n\'a rien en moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 31, 'Mais il faut que le monde connaisse que j\'aime le Père, et que je fais ce que le Père m\'a commandé. Levez-vous, partons d\'ici.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 1, 'Je suis le vrai cep, et mon Père est le vigneron.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 2, 'Il retranche tout sarment qui ne porte pas de fruit en moi; et il émonde tout sarment qui porte du fruit, afin qu\'il porte encore plus de fruit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 3, 'Vous êtes déjà purs, à cause de la parole que je vous ai annoncée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 4, 'Demeurez en moi, et moi, je demeurerai en vous. Comme le sarment ne saurait de lui-même porter du fruit, s\'il ne demeure attaché au cep de même, vous n\'en pouvez porter, si vous ne demeurez en moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 5, 'Je suis le cep, vous êtes les sarments. Celui qui demeure en moi, et en qui je demeure, porte beaucoup de fruits; car, hors de moi, vous ne pouvez rien faire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 6, 'Si quelqu\'un ne demeure pas en moi, il est jeté dehors, comme le sarment. Il sèche, et on le ramasse; on le jette au feu, et il brûle.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 7, 'Si vous demeurez en moi et que mes paroles demeurent en vous, demandez tout ce que vous voudrez, et cela vous sera accordé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 8, 'Voici comment mon Pète sera glorifié: c\'est que vous portiez beaucoup de fruits, et alors vous serez mes disciples.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 9, 'Comme le Père m\'a aimé, je vous ai aussi aimés; demeurez dans mon amour.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 10, 'Si vous gardez mes commandements, vous demeurerez dans mon amour, comme moi-même j\'ai gardé les commandements de mon Père, et je demeure dans son amour.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 11, 'Je vous ai dit ces choses, afin que ma joie demeure en vous, et que votre joie soit parfaite.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 12, 'C\'est ici mon commandement: que vous vous aimiez les uns les autres, comme je vous ai aimés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 13, 'Il n\'y a pas de plus grand amour que de donner sa vie pour ses amis.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 14, 'Vous êtes mes amis, si vous faites ce que je vous commande.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 15, 'Je ne vous appelle plus serviteurs, parce que le serviteur ne sait pas ce que fait son maître; mais je vous ai appelés mes amis, parce que je vous ai fait connaître tout ce que j\'ai appris de mon Père.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 16, 'Ce n\'est pas vous qui m\'avez choisi, c\'est moi qui vous ai choisis et qui vous ai établis, afin que vous alliez et que vous portiez du fruit, et que votre fruit demeure; afin, aussi, que tout ce que vous demanderez au Père en mon nom, il vous l\'accorde.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 17, 'Je vous donne ces commandements, pour que vous vous aimiez les uns les autres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 18, 'Si le monde vous hait, sachez qu\'il m\'a haï avant vous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 19, 'Si vous étiez du monde, le monde aimerait ce qui serait à lui; mais parce que vous n\'êtes pas du monde et que je vous ai choisis du milieu du monde, c\'est à cause de cela que le monde vous hait.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 20, 'Souvenez-vous de la parole que je vous ai dite: Le serviteur n\'est pas plus grand que son maître. S\'ils m\'ont persécuté, ils vous persécuteront aussi; s\'ils ont gardé ma parole, ils garderont aussi la vôtre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 21, 'Mais ils vous feront tout cela à cause de mon nom, parce qu\'ils ne connaissent pas Celui qui m\'a envoyé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 22, 'Si je n\'étais pas venu, et que je ne leur eusse point parlé, ils n\'auraient point de péché; mais maintenant leur péché est sans excuse.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 23, 'Celui qui me hait, hait aussi mon Père.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 24, 'Si je n\'avais pas fait parmi eux des oeuvres qu\'aucun autre n\'a faites, ils seraient sans péché; mais maintenant ils les ont vues, et ils ont haï et moi et mon Père.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 25, 'Et cela, afin que fût accomplie cette parole, écrite dans leur loi: «Ils m\'ont haï sans cause.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 26, 'Quand sera venu le Consolateur que je vous enverrai de la part du Père, l\'Esprit de vérité qui procède du Père, c\'est lui qui rendra témoignage de moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 27, 'Et vous aussi, vous me rendrez témoignage, parce que vous êtes depuis le commencement avec moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 1, 'Je vous ai dit ces choses, pour que vous soyez préservés de toute chute.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 2, 'On vous chassera des synagogues; et même, l\'heure vient où quiconque vous fera mourir croira rendre un culte à Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 3, 'Et ils feront cela, parce qu\'ils n\'ont connu ni le Père, ni moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 4, 'Mais je vous ai dit ces choses, afin que, quand l\'heure sera venue, vous vous souveniez que je vous les ai dites. Je ne vous les ai pas dites dès le commencement, parce que j\'étais avec vous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 5, 'Maintenant, je m\'en vais auprès de Celui qui m\'a envoyé, et aucun de vous ne me demande: Où vas-tu?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 6, 'Mais parce que je vous ai dit ces choses, la tristesse a rempli votre coeur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 7, 'Cependant je vous dis la vérité: il vous est avantageux que je m\'en aille! Car si je ne m\'en vais pas, le Consolateur ne viendra point à vous; mais si je m\'en vais, je vous l\'enverrai.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 8, 'Et quand il sera venu, il convaincra le monde de péché, de justice et de jugement;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 9, 'de péché, parce qu\'ils ne croient pas en moi;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 10, 'de justice, parce que je m\'en vais auprès du Père, et que vous ne me verrez plus;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 11, 'de jugement, parce que le prince de ce monde est jugé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 12, 'J\'ai encore plusieurs choses à vous dire: mais elles sont maintenant au-dessus de votre portée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 13, 'Quand lui, l\'Esprit de vérité, sera venu, il vous conduira dans toute la vérité; car il ne parlera pas de son chef, mais il dira tout ce qu\'il aura entendu, et il vous annoncera les choses à venir.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 14, 'C\'est lui qui me glorifiera, parce qu\'il prendra de ce qui est à moi, et qu\'il vous l\'annoncera.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 15, 'Tout ce que possède le Père est à moi; c\'est pourquoi, j\'ai dit qu\'il prendra de ce qui est à moi, et qu\'il vous l\'annoncera.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 16, 'Encore un peu de temps et vous ne me verrez plus; puis encore un peu de temps, et vous me verrez, parce que je vais auprès du Père.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 17, 'Alors, quelques-uns de ses disciples se dirent les uns aux autres: Qu\'est-ce qu\'il nous dit: Encore un peu de temps, et vous ne me verrez plus; puis encore un peu de temps, et vous me verrez; et aussi: Parce que je vais auprès du Père?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 18, 'Ils disaient donc: Que signifie ce qu\'il dit: Un peu de temps? Nous ne savons de quoi il parle.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 19, 'Jésus, connaissant qu\'ils voulaient l\'interroger, leur dit: Vous vous demandez les uns aux autres ce que signifie cette parole: Encore un peu de temps, et vous ne me verrez plus; puis encore un peu de temps, et vous me verrez.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 20, 'En vérité, en vérité, je vous le déclare, vous pleurerez, vous vous lamenterez, et le monde se réjouira; vous serez dans la tristesse, mais votre tristesse sera changée en joie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 21, 'Quand une femme enfante, elle est dans la douleur, parce que son heure est venue; mais quand l\'enfant est né, elle ne se souvient plus de son angoisse, dans la joie qu\'elle a de ce qu\'un homme est né dans le monde.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 22, 'De même, vous êtes maintenant dans la douleur; mais je vous reverrai et votre coeur se réjouira, et personne ne vous ravira votre joie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 23, 'En ce jour-là, vous ne m\'interrogerez plus sur rien. En vérité, en vérité, je vous le déclare, ce que vous demanderez au Père, il vous le donnera en mon nom.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 24, 'Jusqu\'à présent, vous n\'avez rien demandé en mon nom. Demandez, et vous recevrez, afin que votre joie soit parfaite.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 25, 'Je vous ai dit ces choses en similitudes. L\'heure vient où je ne vous parlerai plus en similitudes, mais où je vous parlerai du Père ouvertement.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 26, 'En ce jour-là, vous demanderez en mon nom, et je ne vous dis pas que je prierai le Père pour vous;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 27, 'car le Père lui-même vous aime, parce que vous m\'avez aimé, et que vous avez cru que je suis venu de la part du Père.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 28, 'Je suis issu du Père, et je suis venu dans le monde; maintenant je quitte le monde, et je vais auprès du Père.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 29, 'Ses disciples lui dirent: C\'est maintenant que tu parles ouvertement, et que tu ne dis pas de similitudes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 30, 'Maintenant, nous savons que tu sais toutes choses, et que tu n\'as pas besoin que personne t\'interroge; voilà pourquoi nous croyons que tu es issu de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 31, 'Jésus leur répondit: Vous croyez maintenant?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 32, 'Voici que l\'heure vient, et elle est déjà venue, où vous serez dispersés, chacun de son côté, et où vous me laisserez seul; mais je ne serai pas seul, parce que le Père est avec moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 33, 'Je vous ai dit ces choses, afin que vous ayez la paix en moi. Vous aurez des afflictions dans le monde; mais prenez courage, j\'ai vaincu le monde!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 1, 'Jésus parla ainsi; puis, levant les yeux au ciel, il dit: Père, l\'heure est venue; glorifie ton Fils, afin que ton Fils te glorifie,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 2, 'et que, par le pouvoir que tu lui as donné sur toute créature, il donne la vie éternelle à tous ceux que tu lui as donnés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 3, 'Or c\'est ici la vie éternelle, qu\'ils te connaissent, toi, le seul vrai Dieu, et celui que tu as envoyé, Jésus-Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 4, 'Je t\'ai glorifié sur la terre; j\'ai achevé l\'oeuvre que tu m\'avais donnée à faire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 5, 'Et maintenant, toi, Père, glorifie-moi auprès de toi-même de la gloire que j\'avais auprès de toi, avant que le monde fût.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 6, 'J\'ai manifesté ton nom aux hommes que tu m\'as donnés du milieu du monde; ils étaient à toi! et tu me les as donnés, et ils ont gardé ta parole.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 7, 'Maintenant ils ont reconnu que tout ce que tu m\'as donné vient de toi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 8, 'Car je leur ai donné les paroles que tu m\'as données, et ils les ont reçues; ils ont vraiment reconnu que je suis venu de toi, et ils ont cru que c\'est toi qui m\'as envoyé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 9, 'Je prie pour eux; je ne prie pas pour le monde, mais pour ceux que tu m\'as donnés, parce qu\'ils sont à toi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 10, 'Et tout ce qui est à moi est à toi, et ce qui est à toi est à moi, et je suis glorifié en eux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 11, 'Je ne suis plus dans le monde, mais eux sont dans le monde, et moi je vais auprès de toi. Père saint, garde-les! Qu\'ils soient fidèles à ton nom, que tu m\'as chargé de faire connaître, afin qu\'ils soient un comme nous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 12, 'Pendant que j\'étais avec eux, je les gardais, et ils étaient fidèles à ton nom que tu m\'as chargé de faire connaître. Je les ai préservés, et aucun d\'eux ne s\'est perdu, sinon le fils de perdition, afin que l\'Écriture fût accomplie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 13, 'Mais maintenant je vais auprès de toi, et je dis ces choses, étant encore dans le monde, afin qu\'ils aient en eux la plénitude de ma joie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 14, 'Je leur ai donné ta Parole, et le monde les a haïs, parce qu\'ils ne sont pas du monde, comme je ne suis pas du monde.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 15, 'Je ne te prie pas de les ôter du monde, mais de les préserver du mal.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 16, 'Ils ne sont pas du monde, comme je ne suis pas du monde.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 17, 'Sanctifie-les par la vérité; ta Parole est la vérité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 18, 'Comme tu m\'as envoyé dans le monde, je les ai aussi envoyés dans le monde.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 19, 'Et je me sanctifie moi-même pour eux, afin qu\'eux aussi soient sanctifiés par la vérité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 20, 'Ce n\'est pas seulement pour eux que je prie, mais aussi pour ceux qui croiront en moi par leur parole,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 21, 'afin que tous soient un, comme toi. Père, tu es en moi, et moi en toi; afin qu\'eux aussi soient en nous, pour que le monde croie que c\'est toi qui m\'as envoyé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 22, 'Je leur ai donné la gloire que tu m\'as donnée, afin qu\'ils soient un, comme nous sommes un:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 23, 'moi en eux, et toi en moi, afin qu\'ils soient parfaits dans l\'unité, et que le monde connaisse que c\'est toi qui m\'as envoyé, et que tu les as aimés comme tu m\'as aimé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 24, 'Père, je veux que là où je suis, ceux que tu m\'as donnés y soient aussi avec moi, afin qu\'ils contemplent ma gloire, la gloire que tu m\'as donnée, parce que tu m\'as aimé avant la création du monde.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 25, 'Père juste, le monde ne t\'a pas connu; mais moi, je t\'ai connu, et ceux-ci ont reconnu que c\'est toi qui m\'as envoyé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 26, 'Je leur ai fait connaître ton nom, et je le leur ferai connaître, afin que l\'amour dont tu m\'as aimé soit en eux, et que je sois moi-même en eux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 1, 'Après avoir dit ces choses, Jésus s\'en alla avec ses disciples au delà du torrent du Cédron; il y avait là un jardin dans lequel il entra, ainsi que ses disciples.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 2, 'Or, Judas, celui qui le trahissait, connaissait aussi cet endroit, parce que Jésus et ses disciples s\'y étaient souvent réunis.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 3, 'Judas, ayant donc pris la cohorte et les agents envoyés par les principaux sacrificateurs et les pharisiens, vint dans ce lieu avec des lanternes, des torches et des armes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 4, 'Jésus, qui savait tout ce qui allait lui arriver, s\'avança et leur dit: Qui cherchez-vous?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 5, 'Ils lui répondirent: Jésus de Nazareth. Jésus leur dit: C\'est moi! Judas, qui le trahissait, se trouvait aussi avec eux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 6, 'Dès que Jésus leur eut dit: C\'est moi! — ils reculèrent et tombèrent à terre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 7, 'Il leur demanda encore une fois: Qui cherchez-vous? Ils répondirent: Jésus de Nazareth.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 8, 'Jésus reprit: Je vous ai dit que c\'est moi; si donc c\'est moi que vous cherchez, laissez aller ceux-ci.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 9, 'Ainsi fut accomplie la parole qu\'il avait dite: Je n\'ai perdu aucun de ceux que tu m\'as donnés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 10, 'Alors Simon Pierre, qui avait une épée, la tira, frappa le serviteur du souverain sacrificateur, et lui coupa l\'oreille droite. Ce serviteur s\'appelait Malchus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 11, 'Mais Jésus dit à Pierre: Remets ton épée dans le fourreau: ne boirai-je pas la coupe que le Père m\'a donnée à boire?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 12, 'La cohorte, le tribun et les agents des Juifs, se saisirent alors de Jésus et le chargèrent de liens.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 13, 'Ils l\'emmenèrent d\'abord chez Anne; car il était le beau-père de Caïphe, qui était souverain sacrificateur cette année-là.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 14, 'Or, Caïphe était celui qui avait donné ce conseil aux Juifs: Il vaut mieux qu\'un seul homme meure pour le peuple.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 15, 'Simon Pierre, avec un autre disciple, suivait Jésus. Cet autre disciple était connu du souverain sacrificateur; il entra donc avec Jésus dans la cour du souverain sacrificateur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 16, 'Mais Pierre se tenait dehors, près de la porte. L\'autre disciple, qui était connu du souverain sacrificateur, sortit, parla à la portière, et fit entrer Pierre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 17, 'Alors cette servante, qui gardait la porte, dit à Pierre: N\'es-tu pas, toi aussi, des disciples de cet homme? Il répondit: Je n\'en suis pas.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 18, 'Les serviteurs et les agents se tenaient là auprès d\'un feu qu\'ils avaient allumé, parce qu\'il faisait froid, et ils se chauffaient. Pierre se tenait avec eux, et il se chauffait aussi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 19, 'Le souverain sacrificateur interrogea donc Jésus sur ses disciples et sur sa doctrine.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 20, 'Jésus lui répondit: J\'ai parlé ouvertement au monde; j\'ai toujours enseigné dans la synagogue et dans le temple, où se rassemblent tous les Juifs, et je n\'ai rien dit en secret.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 21, 'Pourquoi m\'interroges-tu? Demande à ceux qui m\'ont entendu ce que je leur ai dit; ceux-là savent ce que j\'ai dit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 22, 'Comme il parlait ainsi, un des agents qui étaient présents donna un soufflet à Jésus, en disant: Est-ce ainsi que tu réponds au souverain sacrificateur?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 23, 'Jésus lui répondit: Si j\'ai mal parlé, fais voir ce que j\'ai dit de mal; mais si j\'ai bien parlé, pourquoi me frappes-tu?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 24, 'Alors Anne l\'envoya, chargé de liens, à Caïphe, le souverain sacrificateur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 25, 'Cependant, Simon Pierre se tenait là et se chauffait; et on lui dit: N\'es-tu pas, toi aussi, de ses disciples? Il le nia et répondit: Je n\'en suis pas.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 26, 'L\'un des serviteurs du souverain sacrificateur, parent de celui à qui Pierre avait coupé l\'oreille, lui dit: Ne t\'ai-je pas vu dans le jardin avec lui?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 27, 'Pierre nia une fois encore; et aussitôt le coq chanta.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 28, 'Ils emmenèrent ensuite Jésus de chez Caïphe au prétoire; c\'était le matin. Mais ils n\'entrèrent pas eux-mêmes dans le prétoire, afin de ne point se souiller et de pouvoir manger la Pâque.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 29, 'Pilate sortit donc, alla vers eux et leur dit: Quelle accusation portez-vous contre cet homme?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 30, 'Ils lui répondirent: Si ce n\'était pas un malfaiteur, nous ne te l\'aurions pas livré.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 31, 'Alors Pilate leur dit: Prenez-le vous-mêmes et jugez-le selon votre loi. Les juifs lui dirent: Il ne nous est pas permis de faire mourir personne.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 32, 'C\'était afin que fût accompli ce que Jésus avait dit, pour indiquer de quelle mort il devait mourir.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 33, 'Alors Pilate rentra dans le prétoire, et, ayant fait venir Jésus, il lui dit: C\'est toi qui es le roi des Juifs?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 34, 'Jésus répondit: Dis-tu cela de ton propre mouvement, ou d\'autres te l\'ont-ils dit de moi?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 35, 'Pilate répondit; Suis-je Juif? Ta nation et les principaux sacrificateurs t\'ont livré à moi; qu\'as-tu fait?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 36, 'Jésus répondit: Mon règne n\'est pas de ce monde. Si mon règne était de ce monde, mes gens combattraient, pour que je ne fusse pas livré aux Juifs; mais maintenant mon règne n\'est pas d\'ici-bas.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 37, 'Alors Pilate lui dit: Tu es donc roi? Jésus répondit: Tu le dis, je suis roi. Voici pourquoi je suis né et pourquoi je suis venu dans le monde: c\'est pour rendre témoignage à la vérité. Quiconque est pour la vérité écoute ma voix.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 38, 'Pilate lui dit: Qu\'est-ce que la vérité? Quand Pilate eut dit cela, il sortit de nouveau pour aller vers les Juifs, et il leur dit: Je ne trouve aucun crime en lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 39, 'Mais vous avez une coutume, c\'est que je vous relâche quelqu\'un à la fête de Pâque; voulez-vous donc que je vous relâche le roi des Juifs?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 40, 'Alors ils s\'écrièrent de nouveau: Non! Pas lui, mais Barabbas! Or, Barabbas était un brigand.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 1, 'Alors Pilate prit Jésus et le fit battre de verges.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 2, 'Les soldats, ayant tressé une couronne d\'épines, la lui mirent sur la tête, et ils le revêtirent d\'un manteau de pourpre. Puis, s\'approchant,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 3, 'ils lui dirent: Salut, roi des Juifs! Et ils lui donnaient des soufflets.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 4, 'Pilate sortit encore une fois et leur dit: Le voici, je vous l\'amène dehors, afin que vous sachiez que je ne trouve aucun crime en lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 5, 'Jésus sortit donc, portant la couronne d\'épines et le manteau de pourpre; et Pilate leur dit: Voici l\'homme!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 6, 'Mais quand les principaux sacrificateurs et leurs agents le virent, ils s\'écrièrent: Crucifie-le! Crucifie-le! Pilate leur dit: Prenez-le vous-mêmes et crucifiez-le; car pour moi, je ne trouve aucun crime en lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 7, 'Les Juifs reprirent: Nous avons une loi, et d\'après cette loi, il doit mourir, parce qu\'il s\'est fait le Fils de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 8, 'Quand Pilate eut entendu cette parole, il eut encore plus de crainte.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 9, 'Il rentra de nouveau dans le prétoire et dit à Jésus: D\'où es-tu? Mais Jésus ne lui fit aucune réponse.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 10, 'Pilate lui dit: Tu ne me dis rien? Ne sais-tu pas que j\'ai le pouvoir de te délivrer et le pouvoir de te crucifier?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 11, 'Jésus répondit: Tu n\'aurais aucun pouvoir sur moi, s\'il ne t\'avait pas été donné d\'en haut; c\'est pourquoi, celui qui m\'a livré à toi est coupable d\'un plus grand péché.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 12, 'Depuis ce moment, Pilate cherchait à le délivrer; mais les Juifs criaient: Si tu délivres cet homme, tu n\'es pas ami de César. Quiconque se fait roi se déclare contre César!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 13, 'Pilate ayant entendu ces paroles, mena Jésus dehors et s\'assit sur le tribunal, au lieu appelé le Pavé, en hébreu Gabbatha.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 14, 'Or, c\'était le jour de la préparation de la Pâque, environ la sixième heure. Et Pilate dit aux Juifs: Voilà votre roi!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 15, 'Ceux-ci se mirent à crier: Ote-le, ôte-le! Crucifie-le! Pilate leur dit: Crucifierai-je votre roi? Les principaux sacrificateurs répondirent: Nous n\'avons pas d\'autre roi que César.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 16, 'Alors il le leur livra pour être crucifié. Ils prirent donc Jésus et l\'emmenèrent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 17, 'Jésus, portant sa croix, arriva hors de la ville au lieu appelé le Crâne, qui se nomme en hébreu Golgotha.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 18, 'C\'est là qu\'ils le crucifièrent, et deux autres avec lui, un de chaque côté, et Jésus au milieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 19, 'Pilate fit aussi faire un écriteau qu\'il plaça au-dessus de la croix. On y avait écrit: Jésus de Nazareth, le roi des Juifs.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 20, 'Beaucoup de Juifs lurent cet écriteau, parce que le lieu où Jésus fut crucifié était près de la ville, et que l\'inscription était en hébreu, en latin et en grec.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 21, 'Alors les principaux sacrificateurs des Juifs dirent à Pilate: N\'écris pas: Le roi des Juifs; mais écris que lui-même a dit: Je suis le roi des Juifs.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 22, 'Pilate répondit: Ce que j\'ai écrit, je l\'ai écrit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 23, 'Après que les soldats eurent crucifié Jésus, ils prirent ses vêtements, et ils en firent quatre parts, une pour chaque soldat. Ils prirent aussi sa robe, mais cette robe était sans couture, tout entière d\'un seul tissu, depuis le haut jusqu\'en bas.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 24, 'Ils se dirent donc les uns aux autres: Ne la déchirons pas; mais tirons au sort à qui l\'aura. C\'était afin que cette parole de l\'Écriture fût accomplie: «Ils ont partagé mes vêtements entre eux, et ils ont tiré ma robe au sort.» Voilà ce que firent les soldats.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 25, 'Auprès de la croix de Jésus se tenaient sa mère et la soeur de sa mère, Marie, femme de Cléopas, et Marie-Madeleine.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 26, 'Jésus, voyant sa mère et, près d\'elle, le disciple qu\'il aimait, dit à sa mère: Femme, voilà ton fils!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 27, 'Puis il dit au disciple: Voilà ta mère! A partir de ce moment, le disciple la prit chez lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 28, 'Après cela, sachant que déjà tout était accompli, Jésus dit, afin que fût pleinement accomplie l\'Écriture: J\'ai soif.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 29, 'Il y avait là un vase plein de vinaigre. Les soldats emplirent donc de vinaigre une éponge, et, l\'ayant fixée à une tige d\'hysope, ils l\'approchèrent de sa bouche.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 30, 'Quand Jésus eut pris le vinaigre, il dit: Tout est accompli! Et, baissant la tête, il rendit l\'esprit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 31, 'Les Juifs, craignant que les corps ne restassent sur la croix pendant le sabbat — car c\'était la préparation du sabbat, et ce sabbat était très solennel, — demandèrent à Pilate qu\'on leur rompît les jambes et qu\'on les enlevât.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 32, 'Les soldats vinrent donc; ils rompirent les jambes au premier, et ensuite à l\'autre qui était crucifié avec lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 33, 'Quand ils vinrent à Jésus, voyant qu\'il était déjà mort, ils ne lui rompirent pas les jambes;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 34, 'mais l\'un des soldats lui perça le côté avec une lance, et aussitôt il en sortit du sang et de l\'eau.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 35, 'Celui qui a vu ce fait l\'atteste — et son témoignage est véritable, et il sait qu\'il est vrai, — afin que vous aussi, vous croyiez.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 36, 'Cela arriva, afin que cette parole de l\'Écriture fût accomplie: «Aucun de ses os ne sera rompu.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 37, 'Et ailleurs, l\'Écriture dit encore: «Ils regarderont à celui qu\'ils ont percé.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 38, 'Après cela, Joseph d\'Arimathée, qui était disciple de Jésus, mais en secret, parce qu\'il craignait les juifs, demanda à Pilate la permission d\'enlever le corps de Jésus; et Pilate le lui permit. Il vint donc et enleva le corps.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 39, 'Nicodème, celui qui était venu la première fois trouver Jésus pendant la nuit, vint aussi, apportant environ cent livres d\'une composition de myrrhe et d\'aloès.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 40, 'Ils prirent donc le corps de Jésus et l\'enveloppèrent de linges avec des aromates, comme c\'est la coutume d\'ensevelir chez les Juifs.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 41, 'Or, à l\'endroit où il avait été crucifié, il y avait un jardin, et dans ce jardin un tombeau neuf, où personne n\'avait encore été mis.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 42, 'C\'est là qu\'ils déposèrent Jésus, parce que c\'était la préparation des Juifs, et que ce tombeau était tout proche.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 1, 'Le premier jour de la semaine, Marie-Madeleine se rendit au tombeau de grand matin, comme il faisait encore obscur; et elle vit la pierre enlevée de l\'entrée du tombeau.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 2, 'Elle courut donc trouver Simon Pierre et l\'autre disciple que Jésus aimait, et elle leur dit: On a enlevé du tombeau le Seigneur, et nous ne savons pas où on l\'a mis.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 3, 'Alors Pierre sortit avec l\'autre disciple, et ils allèrent au tombeau.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 4, 'Ils couraient tous deux ensemble; mais l\'autre disciple courut plus vite que Pierre, et il arriva le premier au tombeau.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 5, 'S\'étant baissé, il vit les linges qui étaient à terre; toutefois, il n\'entra point.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 6, 'Simon Pierre, qui le suivait, vint à son tour et entra dans le tombeau; il vit les linges qui étaient à terre,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 7, 'ainsi que le suaire dont on avait couvert la tête de Jésus, et qui n\'était pas avec les linges, mais roulé à part, à une autre place.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 8, 'Alors l\'autre disciple, qui était arrivé le premier au tombeau, y entra aussi; il vit, et il crut.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 9, 'En effet, ils n\'avaient pas encore compris l\'Écriture, d\'après laquelle il fallait que Jésus ressuscitât des morts.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 10, 'Puis les disciples retournèrent chez eux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 11, 'Cependant Marie se tenait dehors, auprès du tombeau, et elle pleurait. Comme elle pleurait, elle se baissa pour regarder dans le tombeau,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 12, 'et elle vit deux anges vêtus de blanc, assis l\'un à la tête et l\'autre aux pieds, à la place où le corps de Jésus avait été couché.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 13, 'Ils lui dirent: Femme, pourquoi pleures-tu? Elle leur répondit: parce qu\'on a enlevé mon Seigneur, et que je ne sais où on l\'a mis.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 14, 'Ayant dit cela, elle se retourna et vit Jésus qui était là; mais elle ne savait pas que c\'était Jésus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 15, 'Jésus lui dit: Femme, pourquoi pleures-tu? Qui cherches-tu? Elle, croyant que c\'était le jardinier, lui dit: Seigneur, si c\'est toi qui l\'as emporté, dis-moi où tu l\'a mis, et j\'irai le prendre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 16, 'Jésus lui dit: Marie! Et elle, s\'étant retournée, lui dit en hébreu: Rabbouni — c\'est-à-dire: Maître! —');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 17, 'Jésus lui dit: Ne me touche pas; car je ne suis pas encore monté vers le Père! Mais va vers mes frères, et dis-leur que je monte vers mon Père et votre Père, vers mon Dieu et votre Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 18, 'Marie-Madeleine alla annoncer aux disciples qu\'elle avait vu le Seigneur, et qu\'il lui avait dit ces choses.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 19, 'Le soir de ce même jour, le premier de la semaine, les portes du lieu où se trouvaient les disciples étant fermées, parce qu\'ils craignaient les Juifs, Jésus vint et se tint au milieu d\'eux; et il leur dit: La paix soit avec vous!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 20, 'Ayant dit cela, il leur montra ses mains et son côté. Les disciples furent remplis de joie, en voyant le Seigneur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 21, 'Il leur dit encore: La paix soit avec vous! Comme le Père m\'a envoyé, moi aussi je vous envoie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 22, 'Et quand il eut dit cela, il souffla sur eux et leur dit: Recevez le Saint-Esprit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 23, 'Ceux à qui vous remettrez leurs péchés, ils leur seront remis; ceux à qui vous les retiendrez, ils leur seront retenus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 24, 'Or, Thomas, l\'un des Douze, appelé Didyme, ne se trouvait pas avec eux, lorsque Jésus était venu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 25, 'Les autres disciples lui dirent: Nous avons vu le Seigneur! Mais il leur répondit: Si je ne vois la marque des clous dans ses mains, et si je ne mets mon doigt dans la marque des clous, si je ne mets ma main dans son côté, je ne croirai pas.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 26, 'Huit jours après, les disciples étaient de nouveau réunis dans la maison, et Thomas se trouvait avec eux. Jésus vint, les portes étant fermées; il se tint au milieu d\'eux et leur dit: La paix soit avec vous!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 27, 'Puis il dit à Thomas: Mets ici ton doigt, et regarde mes mains; avance aussi ta main et mets-la dans mon côté; et ne sois pas incrédule, mais crois!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 28, 'Thomas répondit et lui dit: Mon Seigneur et mon Dieu!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 29, 'Jésus lui dit: Parce que tu m\'as vu, tu as cru. Heureux ceux qui n\'ont pas vu et qui ont cru!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 30, 'Jésus a fait en présence de ses disciples beaucoup d\'autres miracles, qui ne sont pas rapportés dans ce livre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 31, 'Mais ces choses ont été écrites, afin que vous croyiez que Jésus est le Christ, le Fils de Dieu, et qu\'en croyant, vous ayez la vie par son nom.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 1, 'Après cela, Jésus se fit voir de nouveau à ses disciples, près de la mer de Tibériade. Et voici comment il se fit voir:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 2, 'Simon Pierre, Thomas, appelé Didyme, Nathanaël, de Cana en Galilée, les fils de Zébédée et deux autres de ses disciples étaient ensemble.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 3, 'Simon Pierre leur dit: Je vais pêcher. Ils lui répondirent: Nous y allons avec toi. Ils partirent et montèrent dans la barque; mais ils ne prirent rien cette nuit-là.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 4, 'Comme le jour venait, Jésus se trouva là sur le rivage; mais les disciples ne savaient pas que c\'était Jésus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 5, 'Jésus leur dit: Enfants, n\'avez-vous rien à manger? Ils lui répondirent: Non.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 6, 'Il leur dit: Jetez le filet du côté droit de la barque, et vous trouverez. Ils le jetèrent donc, et ils ne pouvaient plus le tirer, tant il y avait de poissons.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 7, 'Alors le disciple que Jésus aimait dit à Pierre: C\'est le Seigneur! Quand Simon Pierre eut entendu. que c\'était le Seigneur, il s\'enveloppa de sa robe de dessus — car il était nu — et il se jeta dans l\'eau.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 8, 'Les autres disciples revinrent avec la barque, traînant le filet plein de poissons; car ils n\'étaient éloignés de la terre que d\'environ deux cents coudées.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 9, 'Lorsqu\'ils furent descendus à terre, ils virent de la braise qui était là, du poisson placé dessus, et du pain.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 10, 'Jésus leur dit: Apportez ces poissons que vous venez de prendre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 11, 'Simon Pierre monta dans la barque, et il tira à terre le filet plein de cent cinquante-trois gros poissons; et, quoiqu\'il y en eût tant, le filet ne se rompit pas.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 12, 'Jésus leur dit: Venez et mangez. Mais aucun des disciples n\'osait lui demander: Qui es-tu? — car ils savaient bien que c\'était le Seigneur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 13, 'Jésus s\'approcha, prit le pain et le leur donna, ainsi que le poisson.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 14, 'C\'était déjà la troisième fois que Jésus se faisait voir à ses disciples, après sa résurrection des morts.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 15, 'Quand ils eurent mangé, Jésus dit à Simon Pierre: Simon, fils de Jona, m\'aimes-tu plus que ne font ceux-ci? Pierre lui répondit: Oui, Seigneur, tu sais que je t\'aime. Jésus lui dit: Pais mes agneaux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 16, 'Il lui dit une seconde fois: Simon, fils de Jona, m\'aimes-tu? Pierre lui répondit: Oui, Seigneur, tu sais que je t\'aime. Jésus lui dit: Pais mes brebis.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 17, 'Il lui dit pour la troisième fois: Simon, fils de Jona, m\'aimes-tu? Pierre fut attristé de ce qu\'il lui avait demandé pour la troisième fois: M\'aimes-tu? Il lui répondit: Seigneur, tu connais toutes choses; tu sais que je t\'aime! Jésus lui dit: Pais mes brebis.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 18, 'En vérité, en vérité, je te le déclare, lorsque tu étais plus jeune, tu te ceignais toi-même, et tu allais où tu voulais; mais lorsque tu seras vieux, tu étendras les mains, et un autre te ceindra et te mènera où tu ne voudrais pas.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 19, 'Il dit cela pour marquer par quelle mort Pierre devait glorifier Dieu. Et, après avoir ainsi parlé, il lui dit: Suis-moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 20, 'Pierre, s\'étant retourné, vit venir derrière lui le disciple que Jésus aimait, celui qui, pendant le souper, s\'était penché sur le sein de Jésus et lui avait dit: Seigneur, qui est celui qui te trahit?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 21, 'En le voyant, Pierre dit à Jésus: Seigneur, et celui-ci, que lui arrivera-t-il?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 22, 'Jésus lui répondit: Si je veux qu\'il demeure jusqu\'à ce que je vienne, que t\'importe? Toi, suis-moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 23, 'Le bruit se répandit parmi les frères que ce disciple ne mourrait point. Cependant Jésus n\'avait pas dit: Il ne mourra pas; mais: Si je veux qu\'il demeure jusqu\'à ce que je vienne, que t\'importe?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 24, 'C\'est ce même disciple qui rend témoignage de ces choses, et qui les a écrites; et nous savons que son témoignage est véridique.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 25, 'Il y a encore beaucoup d\'autres choses que Jésus a faites; et si on les écrivait en détail, je ne pense pas que le monde entier pût contenir les livres qu\'on écrirait.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 1, 'Dans mon premier livre, ô Théophile, j\'ai parlé de tout ce que Jésus a fait et enseigné depuis le commencement,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 2, 'jusqu\'au jour où il fut élevé dans le ciel, après avoir donné ses ordres, par le Saint-Esprit, aux apôtres qu\'il avait choisis.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 3, 'Il leur était apparu vivant, après avoir souffert; et il leur avait donné plusieurs preuves de sa résurrection, se faisant voir à eux pendant quarante jours et leur parlant de ce qui concerne le royaume de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 4, 'Comme il se trouvait avec eux, il leur recommanda de ne point partir de Jérusalem, mais d\'y attendre que fût accomplie la promesse du Père, celle dont je vous ai parlé, — leur disait-il;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 5, '— car Jean a baptisé d\'eau, mais vous, vous serez baptisés du Saint-Esprit dans peu de jours.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 6, 'Ceux donc qui étaient là réunis lui demandèrent: Seigneur, est-ce dans ce temps-là que tu rétabliras le royaume d\'Israël?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 7, 'Il leur répondit: Ce n\'est pas à vous de connaître les temps ou les moments que le Père a fixés de sa propre autorité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 8, 'Mais vous recevrez la vertu du Saint-Esprit, qui descendra sur vous; et vous serez mes témoins, tant à Jérusalem que dans toute la Judée et la Samarie, et jusqu\'aux extrémités de la terre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 9, 'Après avoir prononcé ces paroles, il fut enlevé, pendant qu\'ils le regardaient, et une nuée le déroba à leurs yeux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 10, 'Et comme ils avaient les regards attachés au ciel, pendant qu\'il s\'en allait, voici que deux hommes, en vêtements blancs, se présentèrent devant eux,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 11, 'et leur dirent: Hommes de Galilée, pourquoi vous arrêtez-vous à regarder au ciel? Ce Jésus, qui a été enlevé du milieu de vous dans le ciel, en reviendra de la même manière que vous l\'y avez vu monter.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 12, 'Alors ils retournèrent à Jérusalem, de la montagne, appelée montagne des Oliviers, qui est près de Jérusalem, à la distance d\'un chemin de sabbat.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 13, 'Quand ils furent arrivés, ils montèrent dans la chambre haute, où se tenaient d\'ordinaire Pierre, Jean, Jacques et André, Philippe et Thomas, Barthélémy et Matthieu, Jacques, fils d\'Alphée, Simon le zélote, et Jude, fils de Jacques.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 14, 'Tous ceux-là persévéraient d\'un commun accord dans la prière, avec les femmes, avec Marie, mère de Jésus, et avec ses frères.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 15, 'En ces jours-là, Pierre se leva au milieu des frères, — qui étaient assemblés au nombre d\'environ cent-vingt, — et il dit:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 16, 'Mes frères, il fallait que fût accompli ce que le Saint-Esprit a prédit dans l\'Écriture, par la bouche de David, au sujet de Judas, qui a été le guide de ceux qui ont arrêté Jésus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 17, 'Car il était l\'un des nôtres, et il avait reçu sa part de notre ministère.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 18, 'Cet homme, après avoir acheté un champ avec le salaire de son crime, est tombé en avant, son corps s\'est ouvert par le milieu, et toutes ses entrailles se sont répandues.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 19, '— Cela est si bien connu de tous les habitants de Jérusalem, que ce champ est appelé, dans leur langue, Haceldama, c\'est-à-dire: le champ du sang. —');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 20, 'Aussi est-il écrit dans le livre des Psaumes: «Que sa demeure devienne déserte, et qu\'il n\'y ait personne qui l\'habite»; et encore: «Qu\'un autre prenne sa charge.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 21, 'Il faut donc que, parmi les hommes qui nous ont accompagnés pendant tout le temps que le Seigneur Jésus a vécu avec nous,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 22, 'depuis le baptême de Jean jusqu\'au jour où il a été enlevé du milieu de nous, il y en ait un qui soit témoin avec nous de sa résurrection.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 23, 'Ils en présentèrent deux: Joseph, dit Barsabas, surnommé Justus, et Matthias.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 24, 'Puis ils firent cette prière: Seigneur, toi qui connais les coeurs de tous, montre-nous lequel de ces deux hommes tu as choisi,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 25, 'pour occuper, dans ce ministère de l\'apostolat, la place que Judas a abandonnée pour s\'en aller en son lieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 26, 'Ensuite ils tirèrent au sort; et le sort tomba sur Matthias, qui fut associé aux onze apôtres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 1, 'Quand fut arrivé le jour de la Pentecôte, ils étaient tous ensemble dans le même lieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 2, 'Tout à coup, il vint du ciel un bruit pareil à celui d\'un vent qui souffle avec impétuosité, et il remplit toute la maison où ils étaient assis.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 3, 'Alors ils virent paraître des langues séparées les unes des autres, qui étaient comme des langues de feu, et qui se posèrent sur chacun d\'eux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 4, 'Ils furent tous remplis du Saint-Esprit, et ils commencèrent à parler en des langues étrangères, selon que l\'Esprit leur donnait de s\'exprimer.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 5, 'Or, il y avait, en séjour à Jérusalem, des Juifs, hommes pieux venus de toutes les nations qui sont sous le ciel.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 6, 'Quand ce bruit se fit entendre, la foule accourut, et tous furent étonnés de ce que chacun d\'eux les entendait parler sa propre langue.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 7, 'Ils en étaient tous hors d\'eux-mêmes et remplis d\'admiration, et ils disaient: Tous ces gens-là qui parlent, ne sont-ils pas des Galiléens?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 8, 'Comment donc chacun de nous les entend-il parler la propre langue du pays où il est né?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 9, 'Parthes, Mèdes, Élamites, ceux qui habitent la Mésopotamie, la Judée, la Cappadoce, le Pont, l\'Asie,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 10, 'la Phrygie, la Pamphylie, l\'Egypte, le territoire de la Libye qui est près de Cyrène, et ceux qui sont venus de Rome, tant Juifs que proselytes,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 11, 'Cretois et Arabes, nous les entendons parler dans nos langues des choses magnifiques de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 12, 'Ils étaient tous hors d\'eux-mêmes, et ne savaient que penser, se disant l\'un à l\'autre: Qu\'est-ce que cela veut dire?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 13, 'Mais d\'autres disaient en se moquant: C\'est qu\'ils sont pleins de vin doux!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 14, 'Alors Pierre, se présentant avec les Onze, éleva la voix et leur dit: Hommes de la Judée, et vous tous qui êtes en séjour à Jérusalem, sachez bien ceci, et prêtez l\'oreille à mes paroles.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 15, 'Ces gens ne sont pas ivres, comme vous le supposez; car il n\'est encore que la troisième heure du jour.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 16, 'Mais ce qui arrive a été prédit par le prophète Joël:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 17, '«Il arrivera, pendant les derniers jours, — c\'est Dieu lui-même qui parle — que je répandrai de mon Esprit sur toute créature; vos fils et vos filles prophétiseront, vos jeunes gens auront des visions, et vos vieillards auront des songes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 18, 'Oui, en ces jours-là, je répandrai de mon Esprit sur mes serviteurs et sur mes servantes, et ils prophétiseront.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 19, 'Je ferai paraître des prodiges en haut dans le ciel, et des miracles en bas sur la terre: du sang, du feu, et des tourbillons de fumée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 20, 'Le soleil sera changé en ténèbres, et la lune en sang, avant que vienne le grand et glorieux jour du Seigneur;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 21, 'et il arrivera que quiconque invoquera le nom du Seigneur, sera sauvé.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 22, 'Enfants d\'Israël, écoutez ces paroles: Jésus de Nazareth, cet homme à qui Dieu a rendu témoignage parmi vous par les actes de puissance, les prodiges et les miracles qu\'il a opérés par son moyen au milieu de vous, comme vous le savez vous-mêmes,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 23, '— cet homme, livré selon le dessein arrêté et la prescience de Dieu, vous l\'avez fait mourir par la main des impies, en le clouant à la croix.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 24, 'Mais Dieu l\'a ressuscité, en le délivrant des douleurs de la mort, parce qu\'il n\'était pas possible qu\'elle le retînt en sa puissance.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 25, 'En effet, David dit de lui: «Je voyais toujours le Seigneur devant moi; car il est à ma droite, afin que je ne sois point ébranlé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 26, 'C\'est pour cela que mon coeur s\'est réjoui, et que ma langue a fait entendre un chant d\'allégresse. Ma chair elle-même, remplie d\'espérance, trouvera le repos;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 27, 'car tu n\'abandonneras pas mon âme dans le Séjour des morts, et tu ne. permettras pas que ton Saint voie la corruption.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 28, 'Tu m\'as fait connaître les sentiers de la vie; tu me rempliras de joie par ta présence.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 29, 'Mes frères, permettez-moi de vous dire en toute liberté, au sujet du patriarche David, qu\'il est mort, qu\'il a été enseveli, et que son tombeau est encore aujourd\'hui au milieu de nous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 30, 'Mais, étant prophète et sachant que Dieu lui avait promis avec serment de faire asseoir un de ses descendants sur son trône,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 31, 'c\'est la résurrection du Christ qu\'il a prévue et dont il a parlé en disant: «Il n\'a pas été laissé dans le Séjour des morts, et sa chair n\'a pas vu la corruption.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 32, 'Ce Jésus, en effet, Dieu l\'a ressuscité, et nous en sommes tous témoins.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 33, 'Après donc qu\'il a été élevé à la droite de Dieu, et qu\'il a reçu du Père le Saint-Esprit qui avait été promis, il l\'a répandu, comme vous le voyez et l\'entendez.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 34, 'Car David n\'est pas monté au ciel; mais il dit lui-même: «Le Seigneur a dit à mon Seigneur: Assieds-toi à ma droite,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 35, 'jusqu\'à ce que j\'aie mis tes ennemis sous tes pieds, pour te servir de marche-pied».');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 36, 'Que toute la maison d\'Israël tienne donc pour certain que Dieu a fait Seigneur et Christ ce Jésus que vous avez crucifié.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 37, 'En entendant ces paroles, ils furent touchés jusqu\'au fond du coeur, et ils dirent à Pierre et aux autres apôtres: Frères, que ferons-nous?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 38, 'Pierre leur répondit: Convertissez-vous, et que chacun de vous soit baptisé au nom de Jésus-Christ pour obtenir la rémission de ses péchés; et vous recevrez le don du Saint-Esprit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 39, 'Car la promesse est pour vous, pour vos enfants, et pour tous ceux qui sont au loin, en aussi grand nombre que le Seigneur, notre Dieu, en appellera.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 40, 'Puis, par beaucoup d\'autres paroles, il leur adressait les exhortations les plus pressantes, en disant: Sauvez-vous du milieu de cette race perverse!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 41, 'Ceux qui accueillirent la prédication de Pierre furent donc baptisés; et il y eut, ce jour-là, environ trois mille personnes ajoutées à l\'Eglise.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 42, 'Or, ils persévéraient dans la doctrine des apôtres et dans la communion fraternelle; ils rompaient le pain et priaient ensemble.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 43, 'La crainte était dans tous les coeurs, et beaucoup de prodiges et de miracles étaient opérés par les apôtres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 44, 'Tous ceux qui croyaient étaient ensemble et avaient toutes choses en commun;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 45, 'ils vendaient leurs propriétés et leurs biens, et ils en partageaient le prix entre tous, selon les besoins de chacun.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 46, 'Chaque jour, tous ensemble, ils allaient assidûment au temple; dans leurs maisons, ils rompaient le pain et prenaient leurs repas avec joie et simplicité de coeur,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 47, 'louant Dieu et se rendant agréables à tout le peuple. Et le Seigneur ajoutait tous les jours à l\'Église ceux qui étaient sauvés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 1, 'Pierre et Jean montaient au temple pour la prière de la neuvième heure.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 2, 'Or, il y avait un homme impotent de naissance qu\'on portait et qu\'on plaçait tous les jours à la porte du temple, appelée la Belle Porte, pour demander l\'aumône à ceux qui entraient dans l\'édifice.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 3, 'Voyant Pierre et Jean qui allaient entrer dans le temple, il leur demanda l\'aumône.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 4, 'Pierre ayant, ainsi que Jean, arrêté sur lui ses regards, lui dit: Regarde-nous!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 5, 'L\'impotent tenait les yeux attentivement fixés sur eux, s\'attendant à recevoir quelque chose.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 6, 'Mais Pierre lui dit: Je n\'ai ni argent, ni or; mais ce que j\'ai, je te le donne: Au nom de Jésus-Christ de Nazareth, marche!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 7, 'Puis, l\'ayant saisi par la main droite, il le fit lever. A l\'instant, les plantes et les chevilles de ses pieds devinrent fermes;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 8, 'd\'un saut, il fut debout, se mit à marcher, et il entra avec eux dans le temple, marchant, sautant et louant Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 9, 'Tout le peuple le vit, qui marchait et louait Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 10, 'On reconnaissait que c\'était celui-là même qui était assis à la Belle Porte du temple, pour demander l\'aumône; et on était rempli d\'étonnement et de stupeur de ce qui lui était arrivé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 11, 'Comme cet homme tenait par la main Pierre et Jean, tout le peuple étonné accourut vers eux, au portique appelé Portique de Salomon.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 12, 'Alors Pierre, voyant cela, dit au peuple: Enfants d\'Israël, pourquoi vous étonnez-vous de ce qui vient d\'arriver? Pourquoi avez-vous les yeux arrêtés sur nous, comme si c\'était par notre propre puissance ou par notre piété que nous avons fait marcher cet homme?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 13, 'Le Dieu d\'Abraham, d\'Isaac et de Jacob, le Dieu de nos pères a glorifié son serviteur Jésus, que vous avez livré, et que vous avez renié devant Pilate, qui était d\'avis de le relâcher.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 14, 'Vous avez renié le Saint et le Juste, et vous avez demandé qu\'on vous accordât la grâce d\'un meurtrier.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 15, 'Vous avez fait mourir le Prince de la vie, que Dieu a ressuscité des morts; et nous en sommes témoins.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 16, 'C\'est par la foi en son nom, que ce nom a rendu les forces à cet homme que vous voyez et que vous connaissez; la foi, qui agit par Jésus, a donné à cet homme en présence de vous tous, une complète guérison.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 17, 'Et maintenant, mes frères, je sais que vous avez agi ainsi par ignorance, aussi bien que vos chefs.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 18, 'Mais Dieu a, de cette manière, accompli ce qu\'il avait prédit par la bouche de tous les prophètes, que son Christ devait souffrir.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 19, 'Repentez-vous donc et convertissez-vous, pour que vos péchés soient effacés, afin que des temps de rafraîchissement viennent de la part du Seigneur,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 20, 'et qu\'il envoie celui qu\'il vous a destiné, le Christ Jésus,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 21, 'que le ciel doit recevoir jusqu\'au temps du rétablissement de toutes choses, dont Dieu a parlé autrefois par la bouche de ses saints prophètes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 22, 'Moïse a dit, en effet: «Le Seigneur, notre Dieu, vous suscitera, du milieu de vos frères, un prophète comme moi; vous l\'écouterez dans tout ce qu\'il vous dira.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 23, 'Quiconque n\'écoutera pas ce prophète, sera retranché du milieu du peuple.».');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 24, 'De même tous les prophètes qui ont parlé, depuis Samuel et ses successeurs, ont aussi annoncé ces jours-là.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 25, 'Vous êtes les fils des prophètes et de l\'alliance que Dieu a conclue avec nos pères, en disant à Abraham: «Toutes les familles de la terre seront bénies en ta postérité»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 26, 'C\'est à vous premièrement que Dieu, après avoir suscité son serviteur, l\'a envoyé pour vous bénir, en détournant chacun de vous de ses iniquités.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 1, 'Pendant que Pierre et Jean parlaient au peuple, les sacrificateurs, le commandant du temple et les sadducéens survinrent,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 2, 'très inquiets de ce qu\'ils enseignaient le peuple et annonçaient, en la personne de Jésus, la résurrection des morts.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 3, 'Ils mirent la main sur eux et les jetèrent en prison jusqu\'au lendemain, parce qu\'il était déjà tard.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 4, 'Cependant, plusieurs de ceux qui avaient entendu la parole crurent, et le nombre des fidèles s\'éleva à cinq mille environ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 5, 'Le lendemain, les chefs du peuple, les anciens et les scribes, s\'assemblèrent à Jérusalem,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 6, 'avec Anne, le souverain sacrificateur, Caïphe, Jean, Alexandre, et tous ceux qui étaient de la famille des souverains sacrificateurs.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 7, 'Ils firent comparaître devant eux Pierre et Jean, et leur demandèrent: Par quel pouvoir, ou au nom de qui avez-vous fait cela?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 8, 'Alors Pierre, rempli de l\'Esprit saint, leur dit: Chefs du peuple et anciens,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 9, 'puisque nous sommes aujourd\'hui interrogés pour avoir fait du bien à un homme infirme, et qu\'on nous demande comment il a été guéri,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 10, 'sachez-le, vous tous, et que tout le peuple d\'Israël le sache aussi, c\'est au nom de Jésus-Christ de Nazareth, que vous avez crucifié et que Dieu a ressuscité des morts, c\'est par lui que cet homme se présente guéri devant vous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 11, 'Ce Jésus est la pierre rejetée par vous qui bâtissez; elle est devenue la pierre de l\'angle.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 12, 'Il n\'y a de salut en aucun autre; car il n\'y a, sous le ciel, aucun autre nom qui ait été donné aux hommes, par lequel nous devions être sauvés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 13, 'Quand ils virent la hardiesse de Pierre et de Jean, sachant bien que c\'étaient des hommes du peuple, sans aucune instruction, ils furent dans l\'étonnement; et ils reconnaissaient que Pierre et Jean avaient été avec Jésus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 14, 'Mais comme ils voyaient, debout auprès d\'eux, l\'homme qui avait été guéri, ils n\'avaient rien à répliquer.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 15, 'Alors, après leur avoir ordonné de sortir du Sanhédrin, ils tinrent conseil entre eux en disant:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 16, 'Que ferons-nous à ces gens-là? Il est évident, en effet, pour tous les habitants de Jérusalem, qu\'un miracle notoire a été accompli par eux; nous ne pouvons pas le nier.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 17, 'Cependant, afin que la chose ne se répande pas davantage dans le peuple, défendons-leur, avec menaces, de parler désormais à qui que ce soit en ce nom-là.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 18, 'Ils les firent donc rappeler et leur défendirent absolument de parler et d\'enseigner au nom de Jésus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 19, 'Mais Pierre et Jean leur répondirent: Jugez vous-mêmes s\'il est juste, devant Dieu, de vous obéir plutôt qu\'à Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 20, 'Car, pour nous, nous ne pouvons pas ne point parler des choses que nous avons vues et que nous avons entendues.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 21, 'Ils les relâchèrent, après leur avoir adressé de nouvelles menaces, ne trouvant pas le moyen de les punir, à cause du peuple, parce que tous glorifiaient Dieu de ce qui était arrivé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 22, 'En effet, l\'homme, en qui cette miraculeuse guérison avait été accomplie, était âgé de plus de quarante ans.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 23, 'Quand on les eut relâchés, ils vinrent auprès de leurs frères, et ils leur racontèrent tout ce que les principaux sacrificateurs et les anciens leur avaient dit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 24, 'Après les avoir entendus, ils élevèrent tous ensemble leur voix vers Dieu, et ils dirent: Souverain Maître, toi qui as fait le ciel, la terre, la mer et toutes les choses qui s\'y trouvent,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 25, '— tu as dit par le Saint-Esprit, par la bouche de notre père, ton serviteur David: «Pourquoi les nations se sont-elles agitées, et pourquoi les peuples ont-ils formé de vains projets?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 26, 'Les rois de la terre se sont soulevés, et les princes se sont ligués ensemble contre le Seigneur et contre son Oint»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 27, 'En effet, Hérode et Ponce-Pilate, avec les nations et le peuple d\'Israël, se sont véritablement ligués dans cette ville contre ton saint serviteur, Jésus, que tu as oint,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 28, '— pour accomplir tout ce que ta main et ta volonté avaient décidé d\'avance.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 29, 'Et maintenant, Seigneur, sois attentif à leurs menaces, et donne à tes serviteurs d\'annoncer ta parole avec une pleine hardiesse,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 30, 'en étendant ta main, afin qu\'il se fasse des guérisons, des miracles et des prodiges par le nom de ton saint serviteur Jésus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 31, 'Lorsqu\'ils eurent prié, le lieu où ils étaient rassemblés trembla. Ils furent tous remplis du Saint-Esprit, et ils annonçaient la parole de Dieu avec hardiesse.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 32, 'Or, la multitude de ceux qui avaient cru n\'était qu\'un coeur et qu\'une âme. Personne ne disait que ce qu\'il possédait fût à lui en particulier; mais toutes choses étaient communes entre eux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 33, 'Les apôtres, avec une grande puissance, rendaient leur témoignage au Seigneur Jésus et à sa résurrection, et une grande grâce reposait sur eux tous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 34, 'Car personne parmi eux n\'était dans l\'indigence, parce que tous ceux qui possédaient des champs ou des maisons, les vendaient, et ils apportaient le prix de ce qu\'ils avaient vendu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 35, 'Ils le mettaient aux pieds des apôtres; puis, on le distribuait à chacun selon ses besoins.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 36, 'Ainsi Joseph, surnommé par les apôtres Barnabas — c\'est à dire: Fils de consolation — qui était Lévite et originaire de Chypre, possédait un champ:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 37, 'il le vendit, en apporta le prix, et il le mit aux pieds des apôtres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 1, 'Un homme, nommé Ananias, d\'accord avec Saphira, sa femme, vendit une propriété,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 2, 'et retint une partie du prix de la vente, avec l\'assentiment de sa femme; il apporta le reste et le mit aux pieds des apôtres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 3, 'Alors Pierre lui dit: Ananias, pourquoi Satan est-il si complètement entré dans ton coeur, que tu aies menti au Saint-Esprit et détourné une partie du prix de ce champ?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 4, 'Si tu ne l\'avais pas vendu, ne te serait-il pas resté? Et après l\'avoir vendu, n\'étais-tu pas libre d\'en garder le prix? Comment as-tu pu former dans ton coeur un pareil dessein? Ce n\'est pas aux hommes que tu as menti, c\'est à Dieu!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 5, 'Ananias, en entendant ces paroles, tomba et expira; et une grande crainte saisit tous ceux qui se trouvaient là.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 6, 'Mais les jeunes gens, s\'étant levés, enveloppèrent le corps et l\'emportèrent pour l\'ensevelir.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 7, 'Environ trois heures après, la femme d\'Ananias, ne sachant rien de ce qui était arrivé, entra.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 8, 'Pierre, prenant la parole, lui dit: Dis-moi, avez-vous vendu le champ à tel prix? Elle répondit: Oui, c\'est à ce prix-là.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 9, 'Alors Pierre lui dit: Pourquoi vous êtes-vous accordés ensemble pour tenter l\'Esprit du Seigneur? Voici que les pieds de ceux qui ont enseveli ton mari sont à la porte et ils t\'emporteront.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 10, 'Au même instant, elle tomba à ses pieds et elle expira. Les jeunes gens qui rentraient la trouvèrent morte; ils l\'emportèrent et l\'ensevelirent à côté de son mari.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 11, 'Alors une grande crainte saisit toute l\'Église, ainsi que tous ceux qui apprirent ces événements.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 12, 'Cependant il se faisait, par les mains des apôtres, beaucoup de miracles et de prodiges parmi le peuple; et les disciples étaient réunis tous ensemble sous le portique de Salomon.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 13, 'Toutefois, aucune autre personne n\'osait se joindre à eux; mais le peuple faisait hautement leur éloge.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 14, 'Des multitudes d\'hommes et de femmes croyaient au Seigneur, et le nombre des croyants augmentait de plus en plus,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 15, 'au point qu\'on apportait les malades dans les rues; puis on les mettait sur de petits lits ou sur des grabats, afin qu\'au moment où Pierre viendrait à passer, son ombre du moins en couvrît quelques-uns.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 16, 'Le peuple des villes voisines venait aussi en foule à Jérusalem, amenant des malades et des gens tourmentés par des esprits impurs; et tous étaient guéris.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 17, 'Alors, le souverain sacrificateur et tous ses partisans — c\'était la secte des sadducéens — se levèrent, remplis de colère;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 18, 'ils firent arrêter les apôtres et les jetèrent dans la prison publique.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 19, 'Mais un ange du Seigneur leur ouvrit, pendant la nuit, les portes de la prison, les fit sortir et leur dit:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 20, 'Allez, présentez-vous dans le temple, et annoncez au peuple toutes ces paroles de vie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 21, 'A ces mots, les apôtres entrèrent, dès le point du jour, dans le temple, et ils se mirent à enseigner. Cependant le souverain sacrificateur et ceux qui étaient avec lui étant arrivés, assemblèrent le Sanhédrin et tous les anciens des enfants d\'Israël, et ils envoyèrent chercher les apôtres à la prison.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 22, 'Les agents s\'y rendirent, mais ils ne les trouvèrent pas dans la prison. Ils s\'en retournèrent, firent leur rapport');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 23, 'et dirent: Nous avons trouvé la prison bien fermée, et les gardes dehors, devant les portes; mais, nous avons ouvert, et nous n\'avons trouvé personne à l\'intérieur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 24, 'En entendant ces paroles, le commandant du temple et les principaux sacrificateurs étaient très inquiets au sujet des apôtres et de l\'issue de cette affaire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 25, 'Mais quelqu\'un survint, qui leur dit: Voilà que ces hommes, que vous aviez mis en prison, sont dans le temple, et ils enseignent le peuple!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 26, 'Alors le commandant du temple s\'y rendit avec les agents, et il les amena, toutefois sans violence, car ils craignaient d\'être lapidés par le peuple.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 27, 'Les ayant donc amenés, ils les présentèrent au Sanhédrin. Le souverain sacrificateur les interrogea et leur dit:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 28, 'Nous vous avons formellement défendu d\'enseigner en ce nom-là, et vous avez rempli Jérusalem de votre doctrine. Vous voulez donc faire retomber sur nous le sang de cet homme!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 29, 'Pierre et les apôtres répondirent: Il faut obéir à Dieu plutôt qu\'aux hommes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 30, 'Le Dieu de nos pères a ressuscité Jésus, que vous avez fait mourir en le pendant au bois.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 31, 'Dieu l\'a élevé à sa droite comme Prince et Sauveur, afin de donner à Israël la repentance et le pardon des péchés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 32, 'Et nous, nous sommes témoins de ces choses, ainsi que le Saint-Esprit, que Dieu a donné à ceux qui lui obéissent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 33, 'En l\'entendant, ils frémissaient de rage et ils délibéraient de les faire mourir.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 34, 'Mais un pharisien, nommé Gamaliel, docteur de la loi, honoré de tout le peuple, se levant dans le Sanhédrin, donna l\'ordre de faire sortir un instant les apôtres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 35, 'Puis il dit: Enfants d\'Israël, prenez garde à ce que vous allez faire à ces hommes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 36, 'Il y a quelque temps, Theudas se leva, qui se donnait pour un personnage. Environ quatre cents hommes se joignirent à lui: il fut tué, et tous ceux qui l\'avaient suivi furent défaits et réduits à rien.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 37, 'Après lui se leva Judas le Galiléen, à l\'époque du recensement, et il entraîna une foule de gens à sa suite; il périt aussi, et tous ceux qui l\'avaient suivi furent dispersés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 38, 'Maintenant, je vous le dis: Ne poursuivez plus ces gens-là; laissez-les aller! En effet, si cette entreprise ou cette oeuvre vient des hommes, elle se détruira d\'elle-même;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 39, 'mais si elle vient de Dieu, vous ne pourrez faire disparaître ces gens-là. Vous risquez ainsi de vous trouver avoir fait la guerre à Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 40, 'Ils furent de son avis. Ils firent donc rentrer les apôtres, et, après les avoir fait battre de verges, ils leur défendirent de parler au nom de Jésus; puis ils les relâchèrent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 41, 'Alors les apôtres, ayant quitté le Sanhédrin, se retirèrent, tout joyeux d\'avoir été trouvés dignes de souffrir des opprobres pour le nom de Jésus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 42, 'Et ils ne cessaient tous les jours, dans le temple et de maison en maison, d\'enseigner et d\'annoncer la bonne nouvelle de Jésus, le Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 1, 'En ce temps-là, comme les disciples se multipliaient, il y eut des plaintes de la part des Hellénistes contre les Hébreux, parce que leurs veuves étaient négligées dans la distribution qui se faisait chaque jour.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 2, 'Les Douze, ayant alors convoqué une réunion de tous les disciples, leur dirent: Il n\'est pas convenable que nous délaissions la parole de Dieu pour faire le service des tables.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 3, 'Choisissez donc parmi vous, frères, sept hommes de bon renom, pleins du Saint-Esprit et de sagesse, que nous chargerons de ce service.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 4, 'Et pour nous, nous continuerons de nous appliquer à la prière et au ministère de la parole.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 5, 'Cette proposition plut à toute l\'assemblée. Ils élurent Etienne, homme plein de foi et du Saint-Esprit, Philippe, Procore, Nicanor, Timon, Parménas et Nicolas, prosélyte d\'Antioche;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 6, 'et ils les présentèrent aux apôtres, qui, après avoir prié, leur imposèrent les mains.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 7, 'La parole de Dieu se répandait de plus en plus, et le nombre des disciples augmentait beaucoup à Jérusalem. Il y avait même une foule de sacrificateurs qui obéissaient à la foi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 8, 'Etienne, plein de grâce et de force, faisait de grands prodiges et de grands miracles parmi le peuple.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 9, 'Mais quelques membres de la synagogue appelée synagogue des Affranchis, ainsi que des Cyrénéens, des Alexandrins et des Juifs de Cilicie et d\'Asie, se levèrent et se mirent à discuter avec Etienne;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 10, 'mais ils ne pouvaient résister à sa sagesse et à l\'Esprit sous l\'inspiration duquel il parlait.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 11, 'Alors ils subornèrent des hommes qui dirent: Nous lui avons entendu proférer des paroles blasphématoires contre Moïse et contre Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 12, 'Ils soulevèrent le peuple, les anciens et les scribes, et, survenant soudain, ils se rendirent maîtres de lui et l\'emmenèrent devant le Sanhédrin.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 13, 'Ils produisirent de faux témoins, qui dirent: Cet homme ne cesse de parler contre le saint Lieu et contre la Loi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 14, 'Car nous lui avons entendu dire que ce Jésus de Nazareth détruira ce Lieu et changera les coutumes que nous avons reçues de Moïse.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 15, 'Et comme tous ceux qui siégeaient au Sanhédrin avaient les yeux arrêtés sur lui, son visage leur parut semblable à celui d\'un ange.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 1, 'Alors le souverain sacrificateur lui demanda: En est-il bien ainsi?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 2, 'Etienne répondit: Mes frères et mes pères, écoutez-moi! Le Dieu de gloire apparut à notre père Abraham, lorsqu\'il était en Mésopotamie, avant qu\'il vînt demeurer à Carran, et il lui dit:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 3, '«Quitte ton pays et ta famille, et va dans le pays que je te montrerai.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 4, 'Alors, étant sorti du pays des Caldéens, il vint demeurer à Carran. De là, après la mort de son père, Dieu le fit passer dans le pays que vous habitez maintenant;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 5, 'il ne lui donna aucune propriété dans ce pays, pas même un pouce de terre; mais il promit de lui en donner la possession, comme à sa postérité après lui, bien qu\'Abraham n\'eût point d\'enfants.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 6, 'Dieu parla ainsi: «Ses descendants séjourneront dans une terre étrangère; on les réduira en servitude, et on les maltraitera pendant quatre cents ans.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 7, 'Mais Dieu dit encore: «Je jugerai la nation qui les aura asservis, et après cela, ils partiront et me rendront leur culte dans ce pays-ci.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 8, 'Puis Dieu lui donna l\'alliance de la circoncision. C\'est ainsi qu\'Abraham ayant eu un fils, Isaac, le circoncit le huitième jour; ensuite Isaac circoncit Jacob, et Jacob les douze patriarches.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 9, 'Les patriarches, jaloux de Joseph, le vendirent pour être mené en Egypte; mais Dieu fut avec lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 10, 'Il le délivra de toutes ses afflictions, et le remplit de grâce et de sagesse devant Pharaon, roi d\'Egypte, qui l\'établit gouverneur de l\'Egypte et de toute sa maison.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 11, 'Cependant il survint une famine dans tout le pays d\'Egypte et en Canaan; la détresse était grande et nos pères ne pouvaient trouver des vivres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 12, 'Jacob, ayant appris qu\'il y avait du blé en Egypte, y envoya nos pères une première fois.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 13, 'La seconde fois, Joseph fut reconnu par ses frères, et Pharaon apprit quelle était l\'origine de Joseph.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 14, 'Alors Joseph envoya chercher Jacob, son père, et toute sa famille, en tout soixante-quinze personnes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 15, 'Jacob descendit donc en Egypte et il y mourut, ainsi que nos pères.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 16, 'Ils furent transportés à Sichem, et ensevelis dans le tombeau qu\'Abraham avait acheté, à prix d\'argent, des fils d\'Hémor, de Sichem.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 17, 'Mais, lorsque vint le temps où devait s\'accomplir la promesse que Dieu avait faite avec serment à Abraham, le peuple s\'accrut et se multiplia en Egypte,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 18, 'jusqu\'au moment où s\'éleva en Egypte un autre roi, qui n\'avait point connu Joseph.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 19, 'Ce roi, employant la ruse contre notre race, maltraita nos pères, et les contraignit à exposer leurs nouveau-nés, pour les empêcher de vivre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 20, 'En ce temps-là naquit Moïse; il était beau aux yeux de Dieu, et il fut élevé pendant trois mois dans la maison de son père.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 21, 'Quand il fut exposé, la fille de Pharaon le recueillit et le fit élever comme son fils.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 22, 'Moïse fut instruit dans toute la sagesse des Égyptiens; il était puissant en paroles et en oeuvres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 23, 'Mais, quand il eut quarante ans accomplis, il lui vint au coeur la pensée de visiter ses frères, les enfants d\'Israël.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 24, 'Voyant qu\'on maltraitait l\'un d\'eux, il prit la défense de l\'opprimé et le vengea en frappant l\'Égyptien.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 25, 'Il croyait que ses frères comprendraient que Dieu leur accordait par sa main la délivrance; mais ils ne le comprirent pas.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 26, 'Le lendemain, il se présenta à eux pendant qu\'ils se battaient, et il les exhorta à vivre en paix, en leur disant: Mes amis, vous êtes frères; pourquoi vous maltraitez-vous l\'un l\'autre?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 27, 'Celui qui maltraitait son prochain, le repoussa, en disant: Qui t\'a établi chef et juge sur nous?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 28, 'Veux-tu me tuer, comme tu as tué hier l\'Égyptien?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 29, 'A cette parole, Moïse s\'enfuit et alla vivre en étranger dans le pays de Madian, où il eut deux fils.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 30, 'Quarante ans après, un ange lui apparut dans le désert du mont Sinaï, dans la flamme d\'un buisson en feu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 31, 'En le voyant, Moïse fut étonné de cette apparition; et comme il s\'approchait pour la considérer de plus près, la voix du Seigneur se fit entendre:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 32, '«Je suis le Dieu de tes pères, le Dieu d\'Abraham, d\'Isaac et de Jacob» Moïse, tout tremblant, n\'osait pas regarder.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 33, 'Alors le Seigneur lui dit: Ote la chaussure de tes pieds; car le lieu où tu te trouves est une terre sainte.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 34, 'J\'ai regardé et j\'ai vu l\'affliction de mon peuple en Egypte; j\'ai entendu ses gémissements, et je suis descendu pour le délivrer. Viens maintenant, afin que je t\'envoie en Egypte.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 35, 'Ce Moïse qu\'ils avaient rejeté, en disant: Qui t\'a établi notre chef et notre juge? — c\'est lui que Dieu envoya comme chef et comme libérateur, avec l\'aide de l\'ange qui lui était apparu dans le buisson.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 36, 'C\'est lui qui les fit sortir en accomplissant des prodiges et des miracles dans le pays d\'Egypte, sur la mer Rouge et dans le désert, pendant quarante ans.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 37, 'C\'est ce Moïse qui a dit aux enfants d\'Israël: «Dieu vous suscitera, parmi vos frères, un prophète comme moi.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 38, 'C\'est lui qui, dans l\'assemblée du désert, était avec l\'ange qui lui parlait sur le mont Sinaï et avec nos pères, et qui reçut des paroles de vie pour nous les donner.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 39, 'C\'est à lui que nos pères n\'ont pas voulu obéir; c\'est lui qu\'ils repoussèrent pour tourner leur coeur vers l\'Egypte,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 40, 'en disant à Aaron: «Fais-nous des dieux qui marchent devant nous; car ce Moïse, qui nous a conduits hors du pays d\'Egypte, nous ne savons ce qui lui est arrivé»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 41, 'En ces jours-là, ils se firent un veau, ils offrirent un sacrifice à l\'idole et se réjouirent de l\'ouvrage de leurs mains.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 42, 'Alors Dieu se détourna d\'eux et les livra au culte de l\'armée du ciel, comme il est écrit dans le livre des prophètes: «M\'avez-vous donc offert des victimes et des sacrifices durant quarante ans au désert, maison d\'Israël,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 43, 'quand vous transportiez le tabernacle de Moloch et l\'étoile du dieu Romphan, ces idoles que vous avez faites pour les adorer? C\'est pourquoi, je vous déporterai au delà de Babylone.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 44, 'La Tente du témoignage était au milieu de nos pères dans le désert, comme l\'avait ordonné Celui qui dit à Moïse de la faire sur le modèle qu\'il avait vu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 45, 'Nos pères, l\'ayant reçue, l\'introduisirent avec Josué dans le pays conquis sur les nations que Dieu chassa devant eux; et elle y resta jusqu\'aux jours de David,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 46, 'qui trouva grâce devant Dieu et demanda la faveur de donner une demeure au Dieu de Jacob.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 47, 'Alors Salomon lui bâtit une maison.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 48, 'Mais le Très-Haut n\'habite pas des édifices faits de main d\'homme, suivant ces paroles du prophète:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 49, '«Le ciel est mon trône, et la terre est mon marchepied. Quelle maison me bâtirez-vous, dit le Seigneur, ou quel sera le lieu où je reposerai?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 50, 'N\'est-ce pas ma main qui a fait toutes ces choses?»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 51, 'Hommes au cou raide, incirconcis de coeur et d\'oreilles, vous vous opposez toujours au Saint-Esprit; vous êtes tels que vos pères!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 52, 'Lequel des prophètes vos pères n\'ont-ils pas persécuté? Ils ont même tué ceux qui ont prédit la venue du Juste; et vous, maintenant, c\'est lui que vous avez trahi; vous avez été ses meurtriers,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 53, 'vous qui avez reçu la Loi par le ministère des anges et qui ne l\'avez point gardée!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 54, 'Comme ils entendaient ces paroles, ils frémissaient de rage dans leur coeur, et ils grinçaient des dents contre Etienne.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 55, 'Mais lui, rempli du Saint-Esprit, les yeux attachés au ciel, vit la gloire de Dieu et Jésus debout à la droite de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 56, 'Et il dit: Je vois les cieux ouverts, et le Fils de l\'homme debout à la droite de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 57, 'Alors ils poussèrent de grands cris, se bouchèrent les oreilles, et ils se jetèrent tous ensemble sur lui;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 58, 'et, après l\'avoir traîné hors de la ville, ils le lapidèrent. Les témoins mirent leurs vêtements aux pieds d\'un jeune homme nommé Saul.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 59, 'Pendant qu\'ils le lapidaient, Etienne priait et disait: Seigneur Jésus, reçois mon Esprit!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 60, 'Puis, s\'étant mis à genoux, il s\'écria d\'une voix forte: Seigneur, ne leur impute point ce péché! Et quand il eut dit ces paroles, il s\'endormit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 1, 'Saul avait approuvé le meurtre d\'Étienne. Le même jour, une grande persécution éclata contre l\'Église de Jérusalem; tous les fidèles, excepté les apôtres, furent dispersés dans les contrées de la Judée et de la Samarie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 2, 'Cependant, des hommes pieux procédèrent à l\'inhumation d\'Etienne, et ils pleurèrent sa mort, en faisant entendre de grandes lamentations.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 3, 'Mais Saul ravageait l\'Église: il pénétrait dans les maisons, et, entraînant de force hommes et femmes, il les faisait mettre en prison. Conversion des Samaritains Simon le magicien');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 4, 'Ceux donc qui avaient été dispersés allaient de lieu en lieu, annonçant l\'Évangile.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 5, 'Ainsi Philippe, étant descendu dans la ville de Samarie, y annonça le Christ. La foule était unanime à écouter avec attention ce que disait Philippe, lorsqu\'elle l\'entendit et qu\'elle vit les miracles qu\'il accomplissait.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 6, 'En effet, des esprits impurs sortaient d\'un grand nombre de possédés, en jetant de grands cris, et beaucoup de paralytiques et d\'impotents étaient guéris.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 7, 'Ce fut une grande joie dans cette ville.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 8, 'Il y avait alors, dans la même ville, un homme nommé Simon, qui exerçait la magie et remplissait d\'étonnement le peuple de Samarie, se faisant passer pour un grand personnage.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 9, 'Tous, depuis le plus petit jusqu\'au plus grand s\'attachaient à lui, et ils disaient: C\'est lui qui est la puissance de Dieu, la Grande Puissance, comme on l\'appelle.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 10, 'Ils s\'étaient donc attachés à lui, parce que, depuis longtemps, il les avait mis hors d\'eux-mêmes par ses enchantements.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 11, 'Mais, quand ils eurent cru Philippe, qui leur annonçait l\'Évangile du royaume de Dieu et le nom de Jésus-Christ, ils furent baptisés, hommes et femmes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 12, 'Simon lui-même crut aussi, et, après avoir été baptisé, il ne quittait plus Philippe. La vue des prodiges et des grands miracles qui s\'accomplissaient le mettait hors de lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 13, 'Les apôtres, qui étaient à Jérusalem, ayant appris que la Samarie avait accueilli la parole de Dieu, y envoyèrent Pierre et Jean.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 14, 'Ceux-ci, étant arrivés, prièrent pour les nouveaux disciples, afin que le Saint-Esprit leur fût donné.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 15, 'Car il n\'était encore descendu sur aucun d\'eux; ils avaient été seulement baptisés au nom du Seigneur Jésus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 16, 'Alors Pierre et Jean leur imposèrent les mains, et ils reçurent le Saint-Esprit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 17, 'Quand Simon vit que l\'Esprit était donné par l\'imposition des mains des apôtres, il leur offrit de l\'argent,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 18, 'en disant: Donnez-moi aussi ce pouvoir, afin que ceux à qui j\'imposerai les mains reçoivent le Saint-Esprit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 19, 'Mais Pierre lui dit: Que ton argent périsse avec toi, puisque tu as cru que le don de Dieu s\'acquiert avec de l\'argent!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 20, 'Tu n\'as ni part, ni lot en tout ceci; car ton coeur n\'est pas droit devant Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 21, 'Repens-toi donc de ta méchanceté, et prie le Seigneur, afin que, s\'il est possible, cette pensée de ton coeur te soit pardonnée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 22, 'Car je vois que tu as le coeur rempli de fiel et que tu es dans les liens de l\'iniquité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 23, 'Simon répondit: Priez vous-mêmes le Seigneur pour moi, afin qu\'il ne m\'arrive rien de ce que vous avez dit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 24, 'Pierre et Jean, après avoir ainsi rendu leur témoignage et annoncé la parole du Seigneur, retournèrent à Jérusalem, en évangélisant plusieurs villages des Samaritains.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 25, 'Cependant, un ange du Seigneur parla à Philippe et lui dit: Lève-toi, et, vers l\'heure de midi, va sur le chemin qui conduit de Jérusalem à Gaza.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 26, 'Ce chemin est désert. Philippe se leva et partit. Or, un eunuque éthiopien, officier de la cour de Candace, reine d\'Ethiopie, administrateur de tous ses trésors, qui était venu à Jérusalem pour adorer,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 27, 's\'en retournait; et, assis sur son char, il lisait le prophète Ésaïe.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 28, 'L\'Esprit dit à Philippe: Approche-toi et rejoins ce char.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 29, 'Philippe accourut, et, entendant l\'Éthiopien qui lisait le prophète Ésaïe, il lui dit: Comprends-tu ce que tu lis?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 30, 'L\'eunuque lui répondit: Comment le pourrais-je, si quelqu\'un ne me guide? Et il pria Philippe de monter et de s\'asseoir auprès de lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 31, 'Or, le passage de l\'Écriture qu\'il lisait était celui-ci: «Il a été mené comme une brebis à la boucherie; et, comme un agneau muet devant celui qui le tond, il n\'a pas ouvert la bouche.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 32, 'Dans son abaissement même, sa condamnation a été levée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 33, 'Mais qui dépeindra sa génération? Car sa vie a été retranchée de la terre.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 34, 'L\'eunuque, prenant la parole, dit à Philippe: Je te prie, de qui le prophète dit-il cela? Est-ce de lui-même, ou de quelque autre?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 35, 'Alors Philippe, ouvrant la bouche et commençant par ce passage de l\'Écriture, lui annonça Jésus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 36, 'Chemin faisant, ils rencontrèrent de l\'eau; et l\'eunuque dit; Voici de l\'eau; qu\'est-ce qui empêche que je sois baptisé?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 37, '[Philippe dit: Si tu crois de tout ton coeur, cela est possible. L\'eunuque répondit: Je crois que Jésus-Christ est le Fils de Dieu].');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 38, 'Il donna l\'ordre d\'arrêter le char; puis, tous deux descendirent dans l\'eau, et Philippe baptisa l\'eunuque.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 39, 'Quand ils furent sortis de l\'eau, l\'Esprit du Seigneur enleva Philippe; l\'eunuque ne le vit plus, et il continua son chemin, plein de joie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 40, 'Quant à Philippe, il se trouva dans Azot; de là, il se rendit à Césarée, annonçant l\'Évangile dans toutes les villes où il passait.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 1, 'Cependant, Saul, ne respirant toujours que menaces et carnage contre les disciples du Seigneur, s\'adressa au souverain sacrificateur;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 2, 'et il lui demanda des lettres pour les synagogues de Damas, afin que, s\'il trouvait quelques personnes de la secte, hommes ou femmes, il les amenât enchaînées à Jérusalem.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 3, 'Mais, comme il était en chemin et qu\'il approchait de Damas, tout à coup, une lumière venant du ciel resplendit autour de lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 4, 'Il tomba à terre, et il entendit une voix qui lui disait: Saul, Saul, pourquoi me persécutes-tu?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 5, 'Il répondit: Qui es-tu, Seigneur? Le Seigneur dit: Je suis Jésus que tu persécutes!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 6, 'Mais relève-toi, entre dans la ville, et on te dira ce qu\'il faut que tu fasses.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 7, 'Ses compagnons de voyage s\'étaient arrêtés stupéfaits, entendant bien la voix, mais ne voyant personne.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 8, 'Saul se releva de terre; et, quoiqu\'il eût les yeux ouverts, il ne voyait rien.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 9, 'Ils le conduisirent par la main, et le menèrent à Damas, où il resta trois jours sans voir, et sans manger ni boire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 10, 'Or, il y avait à Damas un disciple, nommé Ananias. Le Seigneur lui dit dans une vision: Ananias! Il répondit: Me voici, Seigneur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 11, 'Le Seigneur lui dit: Lève-toi, va dans la rue appelée la rue Droite, et cherche dans la maison de Judas un nommé Saul, de Tarse. Voici qu\'il est en prière;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 12, 'et il a vu un homme, nommé Ananias, entrer chez lui et lui imposer les mains, pour lui faire recouvrer la vue.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 13, 'Ananias répondit: Seigneur, j\'ai entendu dire à plusieurs personnes tout le mal que cet homme a fait à tes saints, dans Jérusalem.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 14, 'Et il est ici avec pleins pouvoirs, de la part des principaux sacrificateurs, pour enchaîner tous ceux qui invoquent ton nom.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 15, 'Mais le Seigneur lui dit: Va; car cet homme est un instrument que je me suis choisi, pour porter mon nom devant les nations, les rois et les enfants d\'Israël;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 16, 'et je lui montrerai combien il faut qu\'il souffre pour mon nom.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 17, 'Ananias s\'en alla donc; puis étant entré dans la maison, il imposa les mains à Saul et lui dit: Saul, mon frère, le Seigneur, ce Jésus qui t\'est apparu sur le chemin par lequel tu venais, m\'a envoyé, afin que tu recouvres la vue et que tu sois rempli du Saint-Esprit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 18, 'Aussitôt il tomba des yeux de Saul comme des écailles, et il recouvra la vue; puis, il se leva et fut baptisé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 19, 'Et quand il eut pris de la nourriture, les forces lui revinrent. Saul passa quelques jours avec les disciples qui étaient à Damas.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 20, 'Aussitôt il se mit à prêcher dans les synagogues que Jésus est le Fils de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 21, 'Tous ceux qui l\'entendirent étaient dans l\'étonnement, et ils disaient: N\'est-ce pas lui qui persécutait à Jérusalem ceux qui invoquent ce nom, et n\'était-il pas venu ici afin de les conduire enchaînés aux principaux sacrificateurs?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 22, 'Quant à Saul, il se fortifiait de plus en plus, et il confondait les Juifs qui habitaient à Damas, en démontrant que Jésus est le Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 23, 'Quelque temps après, les Juifs se concertèrent pour le faire périr.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 24, 'Mais Saul fut averti de leur complot. On gardait même les portes jour et nuit, afin de le tuer.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 25, 'Mais les disciples le prirent, pendant la nuit, et ils le descendirent le long de la muraille, dans une corbeille.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 26, 'Quand Saul fut arrivé à Jérusalem, il essayait de se joindre aux disciples; mais tous le redoutaient, ne croyant pas qu\'il fût aussi un disciple.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 27, 'Alors Barnabas le prit avec lui, le mena aux apôtres et leur raconta comment le Seigneur lui était apparu sur le chemin et lui avait parlé, et comment il avait prêché hardiment à Damas, au nom de Jésus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 28, 'Dès lors, il allait et venait avec eux dans Jérusalem, et il parlait avec hardiesse au nom du Seigneur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 29, 'Il s\'entretenait aussi et discutait avec les Hellénistes; mais ceux-ci cherchaient à lui ôter la vie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 30, 'Les frères, l\'ayant appris, le menèrent à Césarée, et le firent partir pour Tarse.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 31, 'Ainsi, l\'Église jouissait de la paix dans toute la Judée, la Galilée et la Samarie, s\'édifiant et marchant dans la crainte du Seigneur; et elle croissait en nombre par l\'assistance du Saint-Esprit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 32, 'Or, il arriva que Pierre, qui visitait tout le pays, se rendit aussi auprès des saints qui demeuraient à Lydda.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 33, 'Il y trouva un homme, appelé Énée, couché sur son lit depuis huit ans, et qui était paralytique.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 34, 'Pierre lui dit: Énée, Jésus-Christ te guérit; lève-toi, et fais toi-même ton lit. Aussitôt Énée se leva.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 35, 'Tous les habitants de Lydda et du Saron le virent, et ils se convertirent au Seigneur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 36, 'Il y avait à Joppé, parmi les disciples, une femme nommée Tabitha, c\'est-à-dire Dorcas; elle était riche en bonnes oeuvres, et elle faisait beaucoup d\'aumônes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 37, 'Elle tomba malade en ce temps-là et mourut. On lava son corps, et on le déposa dans une chambre haute.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 38, 'Les disciples ayant appris que Pierre se trouvait à Lydda, qui est près de Joppé, lui envoyèrent deux hommes pour le prier de venir auprès d\'eux sans tarder.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 39, 'Pierre se leva et partit avec eux. Lorsqu\'il fut arrivé, on le conduisit à la chambre haute, et toutes les veuves vinrent à lui en, pleurant, et elles lui montrèrent combien Dorcas faisait de vêtements et de manteaux, lorsqu\'elle était avec elles.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 40, 'Pierre, après avoir fait sortir tout le monde, se mit à genoux et pria; puis, se tournant vers le corps, il dit: Tabitha, lève-toi! Elle ouvrit les yeux, et, voyant Pierre, elle se mit sur son séant.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 41, 'Il lui tendit la main, et il la fit lever; puis, ayant appelé les saints et les veuves, il la leur présenta vivante.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 42, 'Ce fait fut connu de toute la ville de Joppé; et beaucoup de personnes crurent au Seigneur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 43, 'Quant à Pierre, il resta plusieurs jours à Joppé, chez un corroyeur, nommé Simon.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 1, 'Il y avait à Césarée un homme, nommé Corneille, centenier de la cohorte appelée Italique.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 2, 'Il était pieux et craignait Dieu, lui et toute sa maison; il faisait beaucoup d\'aumônes au peuple et priait Dieu continuellement.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 3, 'Il vit clairement dans une vision, vers la neuvième heure du jour, un ange de Dieu, qui entrait chez lui, et qui lui dit: Corneille!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 4, 'Les yeux fixés sur l\'ange et tout effrayé, il répondit: Qu\'y a-t-il, Seigneur? L\'ange lui dit: Tes prières et tes aumônes sont montées jusqu\'à Dieu, et il s\'en est souvenu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 5, 'Maintenant donc, envoie des hommes à Joppé, et fais venir un certain Simon, surnommé Pierre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 6, 'Il est logé chez Simon, le corroyeur, dont la maison est près de la mer.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 7, 'Quand l\'ange qui lui parlait se fut retiré. Corneille appela deux de ses serviteurs et un soldat pieux, de ceux qui étaient attachés à sa personne;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 8, 'et leur ayant tout raconté, il les envoya à Joppé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 9, 'Le lendemain, comme ils étaient en route et qu\'ils approchaient de la ville, Pierre monta sur le haut de la maison, vers la sixième heure, pour prier.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 10, 'Il eut faim et voulut prendre de la nourriture; et pendant qu\'on la lui préparait, il fut ravi en extase.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 11, 'Il vit le ciel ouvert, et un objet ressemblant à une grande nappe retenue aux quatre coins, qui descendait et s\'abaissait jusqu\'à terre;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 12, 'il s\'y trouvait des quadrupèdes de toute espèce, des reptiles de la terre et des oiseaux du ciel.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 13, 'Une voix lui dit: Pierre, lève-toi, tue et mange.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 14, 'Mais Pierre répondit: Non, Seigneur; car je n\'ai jamais rien mangé de souillé ni d\'impur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 15, 'La voix, parlant une seconde fois, lui dit: Ce que Dieu a purifié, ne le regarde pas comme souillé!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 16, 'Cela se répéta par trois fois; et aussitôt après, l\'objet fut retiré dans le ciel.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 17, 'Pierre ne savait que penser de la vision qu\'il avait eue, lorsque les hommes envoyés par Corneille, s\'étant informés de la maison de Simon, se présentèrent à la porte.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 18, 'Ayant appelé, ils demandèrent si c\'était là que logeait Simon, surnomme Pierre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 19, 'Comme Pierre réfléchissait à cette vision, l\'Esprit lui dit; Voici trois hommes qui te cherchent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 20, 'Lève-toi donc, descends, et pars avec eux sans hésiter; car c\'est moi qui les ai envoyés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 21, 'Alors Pierre, étant descendu vers ces hommes, leur dit: Me voici; je suis celui que vous cherchez; pour quel motif êtes-vous venus?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 22, 'Ils répondirent: Corneille, centenier, homme juste et craignant Dieu, auquel la nation juive rend un bon témoignage, a reçu d\'un saint ange l\'ordre de te faire venir dans sa maison et d\'écouter tes paroles.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 23, 'Alors Pierre les fit entrer et leur donna l\'hospitalité. Le lendemain, il se leva et partit avec eux et quelques-uns des frères de Joppé l\'accompagnèrent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 24, 'Le jour suivant, ils arrivèrent à Césarée. Corneille les attendait avec ses parents et ses amis intimes, qu\'il avait réunis chez lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 25, 'Comme Pierre entrait, Corneille alla au-devant de lui, et, se jetant à ses pieds, il l\'adora.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 26, 'Mais Pierre le releva, en disant: Lève-toi, je ne suis moi-même qu\'un homme!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 27, 'Et tout en s\'entretenant avec lui, il entra et trouva plusieurs personnes réunies.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 28, 'Vous savez, leur dit-il, qu\'il est interdit à un Juif d\'entrer en relation avec un étranger, ou d\'aller chez lui; mais Dieu m\'a fait voir que je ne devais appeler aucun homme souillé ou impur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 29, 'Aussi n\'ai-je fait aucune difficulté pour venir, lorsque vous m\'avez envoyé chercher. Je demande donc pour quel motif vous m\'avez fait venir.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 30, 'Corneille lui répondit: Il y a maintenant quatre jours, à la neuvième heure, j\'étais chez-moi en prière, quand tout à coup un homme, portant un vêtement resplendissant, se présenta devant moi,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 31, 'et il me dit: Corneille, ta prière a été exaucée, et Dieu s\'est souvenu de tes aumônes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 32, 'Envoie donc à Joppé, et fais venir Simon, surnommé Pierre: il est logé chez Simon, le corroyeur, près de la mer.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 33, 'J\'ai sur-le-champ envoyé vers toi, et tu as bien fait de venir. Maintenant donc, nous voici tous en présence de Dieu, pour entendre tout ce que le Seigneur t\'a commandé de nous dire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 34, 'Alors Pierre ouvrit la bouche et dit: En vérité, je reconnais que Dieu ne fait pas acception de personnes,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 35, 'mais qu\'en toute nation, celui qui le craint et qui pratique la justice lui est agréable.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 36, 'C\'est la parole qu\'il a adressée aux enfants d\'Israël, en leur faisant annoncer la bonne nouvelle de la paix par Jésus-Christ, qui est le Seigneur de tous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 37, 'Vous savez les faits qui se sont passés dans toute la Judée, et qui avaient commencé à se produire en Galilée, à la suite du baptême prêché par Jean:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 38, 'comment Dieu a oint d\'Esprit saint et de puissance Jésus de Nazareth, qui allait de lieu en lieu, faisant du bien et guérissant tous ceux qui étaient sous l\'empire du Diable; car Dieu était avec lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 39, 'Nous avons été témoins de tout ce qu\'il a fait dans le pays des Juifs et à Jérusalem. Ils l\'ont fait mourir, en le pendant au bois.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 40, 'Mais Dieu l\'a ressuscité le troisième jour, et il a permis qu\'il se montrât,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 41, 'non à tout le peuple, mais aux témoins choisis d\'avance par Dieu, à nous qui avons mangé et bu avec lui après sa résurrection d\'entre les morts.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 42, 'Et il nous a commandé de prêcher au peuple, et d\'attester que c\'est lui qui a été établi par Dieu pour juger les vivants et les morts.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 43, 'Tous les prophètes rendent de lui ce témoignage, que quiconque croit en lui reçoit par son nom la rémission des péchés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 44, 'Comme Pierre parlait encore, le Saint-Esprit descendit sur tous ceux qui écoutaient la Parole.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 45, 'Et les fidèles circoncis, qui étaient venus avec Pierre, étaient fort étonnés de voir que le don du Saint-Esprit était aussi accordé aux Païens.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 46, 'Car ils les entendaient parler en langues étrangères et glorifier Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 47, 'Alors Pierre reprit la parole et dit: Peut-on refuser l\'eau du baptême à ceux qui ont reçu le Saint-Esprit aussi bien que nous?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 48, 'Et il ordonna de les baptiser au nom de Jésus-Christ. Ils le prièrent alors de demeurer quelques jours avec eux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 1, 'Les apôtres et les frères, qui étaient en Judée, apprirent que les païens avaient aussi reçu la parole de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 2, 'Et lorsque Pierre fut monté à Jérusalem, les fidèles circoncis lui adressèrent des reproches.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 3, 'Ils lui disaient: Tu es entré chez des incirconcis, et tu as mangé avec eux!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 4, 'Mais Pierre se mit à leur raconter, d\'une manière suivie, ce qui s\'était passé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 5, 'J\'étais — leur dit-il — en prière dans la ville de Joppé, lorsque je fus ravi en extase. J\'eus une vision: un objet, semblable à une grande nappe retenue aux quatre coins, descendait du ciel; et il vint jusqu\'à moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 6, 'Je l\'examinai attentivement, et j\'y vis les quadrupèdes de la terre, les bêtes sauvages, les reptiles, et les oiseaux du ciel.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 7, 'Puis j\'entendis une voix qui me disait: Pierre, lève-toi, tue et mange.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 8, 'Je répondis: Non, Seigneur; car jamais rien de souillé ni d\'impur n\'est entré dans ma bouche.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 9, 'La voix me parla du ciel une seconde fois, et me dit: Ne regarde pas comme souillé ce que Dieu a purifié.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 10, 'Cette vision se répéta par trois fois, puis tout fut retiré dans le ciel.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 11, 'Et voilà qu\'au même instant, trois hommes qui m\'avaient été envoyés de Césarée, se présentèrent à la porte de la maison où j\'étais.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 12, 'Alors l\'Esprit me dit d\'aller avec eux, sans hésiter. Les six frères que voici vinrent également avec moi, et nous entrâmes dans la maison de Corneille.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 13, 'Celui-ci nous raconta comment il avait vu, dans sa maison, un ange qui s\'était présenté à lui et lui avait dit: envoie à Joppé, et fais venir Simon, surnommé Pierre;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 14, 'il t\'annoncera des choses qui seront le salut pour toi et toute ta maison.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 15, 'Quand j\'eus commencé à parler, le Saint-Esprit descendit sur eux, comme il était descendu sur nous au commencement.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 16, 'Alors je me souvins de la parole prononcée par le Seigneur: Jean a baptisé d\'eau; mais vous serez baptisés du Saint-Esprit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 17, 'Si donc Dieu leur a fait le même don qu\'à nous, qui avons cru au Seigneur Jésus-Christ, qui étais-je, moi, pour m\'opposer à Dieu?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 18, 'Après avoir entendu ces paroles, ils s\'apaisèrent et glorifièrent Dieu, en disant: Dieu a donc accordé aussi aux Païens la repentance, afin qu\'ils aient la vie!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 19, 'Ceux qui avaient été dispersés par la persécution, survenue à l\'occasion d\'Etienne, allèrent jusqu\'en Phénicie, dans l\'île de Chypre et à Antioche, n\'annonçant la parole qu\'aux Juifs seulement.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 20, 'Mais quelques-uns d\'entre eux, qui étaient de Chypre et de Cyrène, étant venus à Antioche, parlèrent aussi aux Grecs, leur annonçant l\'Évangile du Seigneur Jésus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 21, 'La main du Seigneur était avec eux, et grand fut le nombre de ceux qui crurent et se convertirent au Seigneur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 22, 'Le bruit en vint aux oreilles de l\'Église de Jérusalem; et on envoya Barnabas jusqu\'à Antioche.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 23, 'Quand il fut arrivé et qu\'il eut vu la grâce accordée par Dieu, il se réjouit, et il les exhorta tous à rester attachés d\'un coeur ferme au Seigneur;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 24, 'car c\'était un homme de bien, plein du Saint-Esprit et de foi. Alors un grand nombre de personnes se joignirent au Seigneur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 25, 'Barnabas alla ensuite à Tarse, pour chercher Saul, et, l\'ayant trouvé, il l\'amena à Antioche.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 26, 'Pendant toute une année, ils assistèrent aux assemblées de l\'Église, et ils instruisirent un grand nombre de personnes. Ce fut à Antioche que, pour la première fois, on donna aux disciples le nom de chrétiens.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 27, 'En ces jours-là, des prophètes descendirent de Jérusalem à Antioche.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 28, 'L\'un d\'eux, nommé Agabus, se leva, et il prédit par l\'Esprit qu\'il y aurait une famine sur toute la terre. Elle survint, en effet, sous le règne de Claude.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 29, 'Les disciples résolurent d\'envoyer, chacun selon son pouvoir, un secours aux frères qui habitaient en Judée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 30, 'C\'est ce qu\'ils firent: ils l\'envoyèrent aux anciens par les mains de Barnabas et de Saul.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 1, 'Vers ce temps-là, le roi Hérode se mit à maltraiter quelques-uns des membres de l\'Église.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 2, 'Il fit mourir par l\'épée Jacques, frère de Jean;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 3, 'et, voyant que cela était agréable aux Juifs, il fit aussi arrêter Pierre. C\'était pendant les jours des pains sans levain.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 4, 'Après l\'avoir fait saisir et mettre en prison, il le donna à garder à quatre escouades, de quatre soldats chacune. Son intention était de le faire comparaître devant le peuple, après la Pâque.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 5, 'Pierre était donc gardé dans la prison, et l\'Église ne cessait d\'adresser à Dieu des prières pour lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 6, 'Or, la nuit qui précéda le jour où Hérode devait le faire comparaître, Pierre, chargé de deux chaînes, dormait entre deux soldats; et des sentinelles, devant la porte, gardaient la prison.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 7, 'Tout à coup survint un ange du Seigneur, et une lumière resplendit dans le cachot. L\'ange réveilla Pierre en le frappant au côté, et lui dit: Lève-toi vite! Et les chaînes tombèrent de ses mains.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 8, 'L\'ange lui dit ensuite: Mets ta ceinture et tes sandales. Pierre obéit. L\'ange ajouta: Mets ton manteau et suis-moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 9, 'Pierre sortit et le suivit; il ne comprenait pas que ce que l\'ange faisait fût réel, mais il croyait à une vision.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 10, 'Quand ils eurent passé la première garde, puis la seconde, ils arrivèrent à la porte de fer qui donne sur la ville. Cette porte s\'ouvrit devant eux d\'elle-même, et, étant sortis, ils s\'avancèrent dans une rue. Aussitôt l\'ange le quitta.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 11, 'Alors Pierre revint à lui et dit: Maintenant, je reconnais vraiment que le Seigneur a envoyé son ange, et qu\'il m\'a délivré de la main d\'Hérode et de tous les maux dont le peuple juif me menaçait.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 12, 'Après avoir réfléchi, il se rendit à la maison de Marie, mère de Jean, surnommé Marc, où plusieurs personnes étaient assemblées et priaient.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 13, 'Quand il eut frappé à la porte du vestibule, une servante, nommée Rhode, vint écouter;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 14, 'puis, ayant reconnu la voix de Pierre, dans sa joie, au lieu d\'ouvrir la porte, elle courut annoncer que Pierre était devant la porte d\'entrée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 15, 'Ils lui dirent: Tu es folle! Mais elle soutenait qu\'il en était ainsi. Ils dirent alors: C\'est son ange.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 16, 'Cependant Pierre continuait à frapper. Quand ils eurent ouvert, ils le virent et furent saisis d\'étonnement.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 17, 'Mais lui, leur ayant, de la main, fait signe de se taire, leur raconta comment le Seigneur l\'avait tiré de la prison; puis il leur dit: Faites-le savoir à Jacques et aux frères. Après cela il sortit, et s\'en alla dans un autre endroit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 18, 'Quand il fit jour, il y eut une grande agitation parmi les soldats: ils ne savaient ce que Pierre était devenu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 19, 'Hérode, l\'ayant fait chercher et n\'ayant pu le trouver, instruisit le procès des gardes, et ordonna de les mener au supplice. Ensuite, il descendit de Judée à Césarée, où il demeura.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 20, 'Or, Hérode avait des sentiments hostiles contre les Tyriens et les Sidoniens. Ils se rendirent auprès de lui d\'un commun accord, et, ayant gagné Blastus, son chambellan, ils demandèrent la paix, parce que leur pays tirait sa subsistance de celui du roi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 21, 'Au jour fixé, Hérode se revêtit de ses habits royaux, s\'assit sur son trône, et les harangua publiquement.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 22, 'Alors le peuple s\'écria: C\'est la voix d\'un Dieu, et non pas d\'un homme!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 23, 'A l\'instant même, Hérode fut frappé par un ange du Seigneur, parce qu\'il n\'avait pas rendu gloire à Dieu; et il mourut rongé des vers.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 24, 'Cependant, la parole de Dieu faisait de grands progrès, et se répandait de plus en plus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 25, 'Barnabas et Saul, après s\'être acquittés de leur mission, revinrent de Jérusalem à Antioche, emmenant avec eux Jean, surnommé Marc.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 1, 'Il y avait dans l\'Église d\'Antioche des prophètes et des docteurs: Barnabas, Siméon, appelé Niger, Lucius le Cyrénéen, Manahem, qui avait été élevé avec Hérode le tétrarque, et Saul.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 2, 'Pendant qu\'ils célébraient le culte du Seigneur et qu\'ils jeûnaient, le Saint-Esprit leur dit: Mettez à part Barnabas et Saul, pour l\'oeuvre à laquelle je les ai appelés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 3, 'Alors, après avoir jeûné et prié. ils leur imposèrent les mains et les laissèrent partir.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 4, 'Eux donc, étant envoyés par le Saint-Esprit, descendirent à Séleucie, et, de là, ils firent voile vers l\'île de Chypre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 5, 'Arrivés à Salamine, ils annoncèrent la parole de Dieu dans les synagogues des Juifs; ils avaient Jean avec eux pour les aider.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 6, 'Ayant traversé toute l\'île jusqu\'à Paphos, ils trouvèrent un certain Juif, magicien et faux prophète, nommé Bar-Jésus,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 7, 'qui vivait auprès du proconsul Sergius Paulus, homme d\'une intelligence éprouvée. Celui-ci, ayant fait appeler Barnabas et Saul, demanda à entendre la parole de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 8, 'Mais Élymas, le magicien — c\'est ce que signifie son nom — leur résistait, tâchant de détourner le proconsul de la foi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 9, 'Alors Saul, appelé aussi Paul, plein du Saint-Esprit, le regarda en face et lui dit:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 10, 'Homme tout rempli d\'artifice et de méchanceté, enfant du Diable, ennemi de toute justice, ne cesseras-tu pas de rendre tortueuses les voies droites du Seigneur?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 11, 'Déjà la main du Seigneur est sur toi; tu seras aveugle, tu ne verras pas le soleil pendant un certain temps. A l\'instant même, l\'obscurité et les ténèbres tombèrent sur Élymas; et, tournant de tous côtés, il cherchait quelqu\'un pour le conduire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 12, 'Alors le proconsul, voyant ce qui était arrivé, devint croyant; car la doctrine du Seigneur l\'avait rempli d\'admiration.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 13, 'S\'étant embarqués à Paphos, Paul et ses compagnons arrivèrent à Perge, en Pamphylie. Mais Jean se sépara d\'eux, et retourna à Jérusalem.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 14, 'Pour eux, ayant quitté Perge, ils poursuivirent leur route et parvinrent à Antioche de Pisidie; et, étant entrés dans la synagogue le jour du sabbat, ils y prirent place.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 15, 'Après la lecture de la loi et des prophètes, les chefs de la synagogue leur envoyèrent dire: Frères, si vous avez quelques paroles d\'exhortation à adresser au peuple, parlez!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 16, 'Alors Paul se leva, et, ayant fait signe de la main, il dit: Enfants d\'Israël et vous qui craignez Dieu, écoutez:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 17, 'Le Dieu de ce peuple d\'Israël choisit nos pères; il éleva bien haut ce peuple, pendant son séjour à l\'étranger, dans le pays d\'Egypte, et il l\'en fit sortir par la puissance de son bras.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 18, 'Il supporta leur conduite dans le désert, pendant environ quarante ans.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 19, 'Puis, ayant détruit sept nations dans le pays de Canaan, il mit les Israélites en possession de leur territoire,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 20, 'pendant environ quatre cent cinquante ans; c\'est alors qu\'il leur donna des juges jusqu\'au prophète Samuel.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 21, 'Ensuite les Israélites demandèrent un roi. Dieu leur donna pour quarante ans Saül, fils de Kis, de la tribu de Benjamin;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 22, 'puis, l\'ayant rejeté. Dieu leur suscita pour roi David, auquel il rendit ce témoignage: «J\'ai trouvé David, fils de Jessé, un homme selon mon coeur, qui exécutera toutes mes volontés.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 23, 'C\'est de sa postérité que Dieu, selon sa promesse, a suscité pour Israël un Sauveur, qui est Jésus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 24, 'Avant sa venue, Jean avait prêché le baptême de la repentance à tout le peuple d\'Israël.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 25, 'Et pendant que Jean poursuivait sa course, il disait: Je ne suis pas ce que vous pensez; mais il vient après moi, celui dont je ne suis pas digne de délier la chaussure.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 26, 'Mes frères, enfants de la race d\'Abraham, et vous qui craignez Dieu, c\'est à nous que ce message de salut est adressé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 27, 'Car les habitants de Jérusalem et leurs chefs, ayant méconnu ce Jésus, ont accompli, en le condamnant, les paroles des prophètes qu\'on lit chaque sabbat.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 28, 'Bien qu\'ils n\'eussent rien trouvé en lui qui fût digne de mort, ils demandèrent à Pilate de le faire mourir.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 29, 'Après qu\'ils eurent accompli tout ce qui avait été écrit à son sujet, ils le descendirent de la croix et le mirent dans un tombeau.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 30, 'Mais Dieu l\'a ressuscité des morts.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 31, 'Il a été vu, pendant plusieurs jours, par ceux qui étaient montés avec lui de la Galilée à Jérusalem, et qui sont maintenant ses témoins auprès du peuple.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 32, 'Quant à nous, nous vous annonçons une bonne nouvelle: La promesse faite à nos pères.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 33, 'Dieu l\'a accomplie pour nous, leurs enfants, en ressuscitant Jésus, ainsi qu\'il est écrit dans le psaume second: «Tu es mon fils; je t\'ai engendré aujourd\'hui.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 34, 'Qu\'il l\'ait ressuscité des morts, de sorte qu\'il ne saurait désormais tomber en corruption, c\'est ce qu\'il a déclaré en disant: «Je vous tiendrai fidèlement les promesses sacrées, faites à David.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 35, 'Aussi dit-il encore dans un autre endroit: «Tu ne permettras pas que ton Saint voie la corruption.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 36, 'En effet, David, après avoir servi en son temps aux desseins de Dieu, est mort; il a été recueilli avec ses pères, et il a vu la corruption.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 37, 'Mais celui que Dieu a ressuscité, n\'a pas vu la corruption.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 38, 'Sachez-le donc, frères, c\'est par lui que la rémission des péchés vous est annoncée;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 39, 'et c\'est par lui que tout croyant est justifié de tout ce dont vous ne pouviez être justifiés par la loi de Moïse.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 40, 'Prenez donc garde qu\'il ne vous arrive ce qui est dit dans les prophètes:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 41, '«Voyez, hommes dédaigneux, soyez étonnés, et disparaissez; car je vais faire une oeuvre en vos jours, une oeuvre que vous ne croiriez point, si on vous la racontait.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 42, 'Lorsqu\'ils sortirent, on les pria de parler, le sabbat suivant, sur les mêmes sujets.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 43, 'Et après que l\'assemblée se fut séparée, plusieurs Juifs et prosélytes pieux suivirent Paul et Barnabas, qui s\'entretinrent avec eux et les exhortèrent à demeurer attachés à la grâce de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 44, 'Le sabbat suivant, presque toute la ville se rassembla pour entendre la parole du Seigneur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 45, 'Mais les Juifs, voyant cette foule, furent remplis de jalousie; ils s\'opposèrent à ce que Paul disait, en l\'injuriant.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 46, 'Alors Paul et Barnabas leur dirent hardiment: C\'était à vous, les premiers, qu\'il fallait annoncer la parole de Dieu; mais puisque vous la rejetez et que vous vous jugez vous-mêmes indignes de la vie éternelle, nous nous tournons vers les Païens.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 47, 'Car le Seigneur nous l\'a ainsi commandé: «Je t\'ai établi pour être la lumière des nations, afin que tu portes le salut jusqu\'aux extrémités de la terre.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 48, 'Les Païens, en les entendant parler, étaient remplis de joie et donnaient gloire à la parole du Seigneur, et tous ceux qui étaient destinés à la vie éternelle, crurent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 49, 'La parole du Seigneur se répandait dans tout le pays.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 50, 'Mais les Juifs excitèrent les femmes dévotes de haut rang et les principaux habitants de la ville; ils provoquèrent une persécution contre Paul et Barnabas, et ils les chassèrent de leur territoire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 51, 'Ceux-ci, ayant secoué contre eux la poussière de leurs pieds, allèrent à Iconium.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 52, 'Quant aux disciples, ils étaient remplis de joie et du Saint-Esprit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 1, 'A Iconium, Paul et Barnabas entrèrent ensemble dans la synagogue des Juifs, et ils parlèrent de telle sorte qu\'il y eut une grande multitude de Juifs et de Grecs qui devinrent croyants.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 2, 'Mais les Juifs restés incrédules excitèrent et aigrirent l\'esprit des Païens contre les frères.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 3, 'Cependant, Paul et Barnabas séjournèrent là assez longtemps, pleins de courage et de confiance dans le Seigneur, qui rendait témoignage à la parole de sa grâce, en faisant par leurs mains des miracles et des prodiges.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 4, 'Mais le peuple de la ville se divisa; les uns étaient pour les Juifs, les autres pour les apôtres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 5, 'Et comme les Païens et les Juifs, avec leurs chefs, se soulevaient pour les maltraiter et les lapider,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 6, 'les apôtres, en ayant eu connaissance, se réfugièrent dans les villes de la Lycaonie, à Lystre, à Derbe, et dans les environs,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 7, 'et ils y annoncèrent l\'Évangile.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 8, 'Il y avait à Lystre un homme paralysé des jambes, impotent de naissance, et qui n\'avait jamais marché.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 9, 'Il était assis, et il écoutait parler Paul. Celui-ci, ayant arrêté les yeux sur lui et voyant qu\'il avait la foi pour être guéri,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 10, 'dit d\'une voix forte: Lève-toi, et tiens-toi droit sur tes pieds. Il se leva d\'un saut, et il se mit à marcher.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 11, 'Le peuple, ayant vu ce que Paul avait fait, s\'écria en langue lycaonienne: Les dieux, ayant pris une forme humaine, sont descendus vers nous!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 12, 'Et ils appelaient Barnabas Jupiter, et Paul Mercure, parce que c\'était lui qui portait la parole.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 13, 'Le prêtre de Jupiter, dont le temple est à l\'entrée de la ville, vint devant les portes avec des taureaux et des couronnes, et il voulait, d\'accord avec la foule, offrir un sacrifice.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 14, 'Mais les apôtres, Barnabas et Paul, l\'ayant appris, déchirèrent leurs vêtements et se jetèrent au milieu de la foule en s\'écriant:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 15, 'Amis, pourquoi faites-vous cela? Nous ne sommes que des hommes, de la même nature que vous; et nous vous annonçons l\'Évangile, afin que vous vous détourniez de ces vaines idoles, et que vous vous convertissiez au Dieu vivant, qui a fait le ciel, la terre, la mer, et tout ce qui s\'y trouve.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 16, 'Il a laissé dans les siècles passés toutes les nations suivre leurs propres voies.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 17, 'Néanmoins, il n\'a cessé, par ses bienfaits, de donner des témoignages de ce qu\'il est, en vous envoyant du ciel des pluies et les saisons fertiles, en vous accordant la nourriture avec abondance, et en remplissant vos coeurs de joie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 18, 'Malgré ces paroles, ils ne parvinrent que difficilement à empêcher le peuple de leur offrir un sacrifice.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 19, 'Cependant, il survint, d\'Antioche et d\' Iconium, des Juifs qui gagnèrent le peuple; et, ayant lapidé Paul, ils le traînèrent hors de la ville, pensant qu\'il était mort.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 20, 'Mais, les disciples s\'étant réunis autour de lui, il se releva et entra dans la ville. Le lendemain, il s\'en alla avec Barnabas à Derbe.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 21, 'Après avoir annoncé l\'Évangile dans cette ville, et y avoir fait un assez grand nombre de disciples, ils retournèrent à Antioche de Pisidie. Lystre, Iconie et Antioche,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 22, 'fortifiant l\'âme des disciples, les exhortant à persévérer dans la foi, et les avertissant que c\'est par beaucoup d\'afflictions qu\'il nous faut entrer dans le royaume de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 23, 'Ils nommèrent des anciens dans chaque Église; et, après avoir prié et jeûné, ils les recommandèrent au Seigneur, en qui ils avaient cru.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 24, 'Ayant traversé la Pisidie, ils vinrent en Pamphylie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 25, 'Puis, après avoir annoncé la parole à Perge, ils descendirent à Attalie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 26, 'De là, ils firent voile vers Antioche d\'où ils étaient partis, recommandés à la grâce de Dieu pour l\'oeuvre qu\'ils venaient d\'accomplir.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 27, 'Quand ils furent arrivés, et qu\'ils eurent assemblé l\'Eglise, ils racontèrent toutes les choses que Dieu avait faites par eux, et comment il avait ouvert aux Païens la porte de la foi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 28, 'Et ils demeurèrent là longtemps avec les disciples.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 1, 'Or, quelques hommes venus de la Judée, enseignaient aux frères cette doctrine: Si vous n\'êtes pas circoncis selon le rite mosaïque, vous ne pouvez être sauvés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 2, 'Comme une discussion, et même une dispute assez vive, s\'était élevée à ce sujet entre Paul et Barnabas, et ces gens-là, on décida que Paul et Barnabas, avec quelques-uns d\'entre eux, monteraient à Jérusalem, auprès des apôtres et des anciens, pour traiter de cette affaire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 3, 'Eux donc, après avoir été accompagnés par l\'Église, traversèrent la Phénicie et la Samarie, racontant la conversion des Païens, et ils causèrent ainsi une grande joie à tous les frères.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 4, 'A leur arrivée à Jérusalem, ils furent accueillis par l\'Église, les apôtres et les anciens, et ils rapportèrent tout ce que Dieu avait fait par leur moyen.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 5, 'Mais quelques membres de la secte des pharisiens, qui avaient cru, se levèrent et dirent qu\'il fallait circoncire les Païens, et leur enjoindre d\'observer la loi de Moïse.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 6, 'Alors les apôtres et les anciens s\'assemblèrent pour examiner cette affaire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 7, 'Après une longue discussion, Pierre se leva et leur dit: Mes frères, vous savez que, dès les premiers jours, Dieu m\'a choisi parmi vous, pour faire entendre aux Païens par ma bouche la parole de l\'Évangile, et pour les amener à la foi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 8, 'Dieu, qui connaît les coeurs, leur a rendu témoignage, en leur donnant le Saint-Esprit aussi bien qu\'à nous;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 9, 'il n\'a point fait de différence entre nous et eux, ayant purifié leurs coeurs par la foi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 10, 'Maintenant donc, pourquoi tentez-vous Dieu, en chargeant les disciples d\'un joug que ni nos pères ni nous-mêmes n\'avons pu porter?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 11, 'Nous croyons, au contraire, que c\'est par la grâce du Seigneur Jésus que nous sommes sauvés, de la même manière qu\'eux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 12, 'Toute l\'assemblée se tut, et on écoutait Barnabas et Paul, qui racontaient quels miracles et quels prodiges Dieu avait opérés par leur moyen, parmi les Païens.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 13, 'Quand ils eurent cessé de parler, Jacques prit la parole et dit: Mes frères, écoutez-moi!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 14, 'Simon a raconté comment, pour la première fois, Dieu a jeté les yeux sur les nations païennes, pour en tirer un peuple consacré à son nom.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 15, 'Cela s\'accorde avec les paroles des prophètes; car il est écrit:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 16, '«Après tout cela, je reviendrai, et je relèverai la tente de David, qui est tombée. Je réparerai ses ruines, et je la redresserai,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 17, 'afin que le reste des hommes et toutes les nations sur lesquelles mon nom est invoqué, cherchent le Seigneur. Ainsi parle le Seigneur qui accomplit ces choses;»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 18, 'et elles lui sont connues de tout temps.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 19, 'C\'est pourquoi je suis d\'avis qu\'on ne doit pas inquiéter ceux des Païens qui se convertissent à Dieu;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 20, 'mais il faut leur écrire de s\'abstenir des souillures des idoles, de l\'impudicité, des animaux étouffés et du sang.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 21, 'Car Moïse, depuis bien des générations, a dans chaque ville ses prédicateurs, puisqu\'on le lit tous les jours de sabbat dans les synagogues.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 22, 'Alors les apôtres et les anciens, d\'accord avec toute l\'Église, décidèrent d\'envoyer à Antioche, avec Paul et Barnabas, des personnes choisies parmi eux. Ils choisirent Jude, appelé Barsabas, et Silas, deux hommes éminents parmi les frères;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 23, 'et ils les chargèrent de la lettre suivante: Les apôtres, les anciens et les frères, aux frères. Païens d\'origine, qui sont à Antioche, en Syrie et en Cilicie, salut!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 24, 'Ayant appris que quelques-uns d\'entre nous, sans aucun mandat de notre part, vous ont troublés par leurs paroles et ont bouleversé vos âmes,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 25, 'nous avons été d\'avis, d\'un commun accord, de choisir des délégués et de vous les envoyer avec nos bien-aimés Barnabas et Paul,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 26, 'ces hommes qui ont exposé leur vie pour le nom de notre Seigneur Jésus-Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 27, 'Nous vous avons donc envoyé Jude et Silas, qui vous diront, de vive voix, les mêmes choses:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 28, 'C\'est qu\'il a semblé bon au Saint-Esprit et à nous de ne pas vous imposer d\'autres charges que celles qui sont indispensables,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 29, 'savoir, de vous abstenir des viandes offertes en sacrifice aux idoles, du sang, des animaux étouffés et de l\'impudicité; toutes choses dont vous vous trouverez bien de vous garder. Adieu!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 30, 'Eux donc, après avoir pris congé de l\'Église, descendirent à Antioche; et ayant assemblé tous les frères, ils leur remirent la lettre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 31, 'On en fit là lecture, et tous se réjouirent de l\'encouragement qu\'elle leur apportait.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 32, 'Jude et Silas, qui étaient eux-mêmes prophètes, exhortèrent et fortifièrent aussi les frères par plusieurs discours.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 33, 'Au bout de quelque temps, les frères les renvoyèrent en paix auprès de ceux qui les avaient délégués.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 34, '[Mais Silas jugea à propos de rester à Antioche.]');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 35, 'Cependant Paul et Barnabas restèrent à Antioche, prêchant l\'Évangile et enseignant avec plusieurs autres la parole du Seigneur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 36, 'Quelque temps après, Paul dit à Barnabas: Retournons visiter les frères dans toutes les villes où nous avons annoncé la parole du Seigneur, et voyons en quel état ils se trouvent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 37, 'Barnabas voulait emmener aussi Jean, surnommé Marc.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 38, 'Mais Paul n\'était pas d\'avis d\'emmener celui qui les avait quittés en Pamphylie, et qui ne les avait pas accompagnés pour être à l\'oeuvre avec eux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 39, 'Il y eut entre eux une vive discussion, de sorte qu\'ils se séparèrent, et que Barnabas, prenant Marc avec lui, s\'embarqua pour l\'île de Chypre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 40, 'Quant à Paul, ayant choisi Silas, il partit, après avoir été recommandé par les frères à la grâce du Seigneur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 41, 'Il parcourut la Syrie et la Cilicie, affermissant les Églises.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 1, 'Paul arriva à Derbe et à Lystre. Il y avait là un disciple, nommé Timothée, fils d\'une Juive fidèle et d\'un père grec.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 2, 'Les frères de Lystre et d\'Iconium lui rendaient un bon témoignage.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 3, 'Paul voulut l\'emmener avec lui; et, l\'ayant pris, il le circoncit, à cause des Juifs qui vivaient dans ces pays-là; car tous savaient que son père était Grec.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 4, 'Dans les villes où ils passaient, ils recommandaient d\'observer les décisions prises par les apôtres et par les anciens de Jérusalem.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 5, 'Ainsi les Églises étaient affermies dans la foi, et elles augmentaient en nombre de jour en jour.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 6, 'Puis, ils traversèrent la Phrygie et le pays des Galates, le Saint-Esprit les ayant empêchés d\'annoncer la parole en Asie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 7, 'Arrivés près de la Mysie, ils se disposaient à aller en Bithynie; mais l\'Esprit de Jésus ne le leur permit pas.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 8, 'Alors ils traversèrent rapidement la Mysie, et ils descendirent à Troas. Paul se rend en Macédoine');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 9, 'Pendant la nuit, Paul eut une vision; un Macédonien se tenait devant lui et le suppliait, en disant: Passe en Macédoine et viens nous secourir!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 10, 'Aussitôt après cette vision de Paul, nous cherchâmes à partir pour la Macédoine, convaincus que Dieu nous appelait à y annoncer l\'Évangile.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 11, 'Étant donc partis de Troas, nous naviguâmes droit sur Samothrace, et le lendemain, sur Néapolis;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 12, 'de là, nous vînmes à Philippes, la première ville de la province de la Macédoine, et une colonie romaine. Nous y séjournâmes quelques jours.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 13, 'Le jour du sabbat, nous nous rendîmes hors des portes, au bord de la rivière, où nous pensions qu\'on se rassemblait pour la prière; et, nous étant assis, nous parlions aux femmes qui s\'y trouvaient réunies.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 14, 'L\'une d\'elles, nommée Lydie, de la ville de Thyatire, marchande de pourpre, qui craignait Dieu, nous écouta; et le Seigneur lui ouvrit le coeur pour qu\'elle fût attentive à ce que Paul disait.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 15, 'Quand elle eut été baptisée avec sa famille, elle nous adressa cette demande: Si vous m\'avez jugée fidèle au Seigneur, entrez dans ma maison, et demeurez-y; et elle nous y obligea.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 16, 'Un jour que nous allions à la prière, une servante, qui avait un esprit de Python, et qui, en devinant, procurait un grand profit à ses maîtres, nous rencontra.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 17, 'Elle se mit à nous suivre, Paul et nous, en criant: Ces hommes-là sont des serviteurs du Dieu Très-Haut; ils vous annoncent la voie du salut.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 18, 'Elle fit ainsi pendant plusieurs jours; mais Paul, en étant importuné, se retourna et dit à l\'esprit: Je te commande, au nom de Jésus-Christ, de sortir de cette femme. Et l\'esprit sortit à l\'heure même.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 19, 'Cependant les maîtres de cette servante, voyant disparaître l\'espoir de leur gain, se saisirent de Paul et de Silas, les traînèrent sur la place publique devant les magistrats,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 20, 'et, les ayant amenés aux préteurs, ils dirent: Ces hommes troublent notre ville!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 21, 'Ce sont des Juifs; et ils enseignent des coutumes qu\'il ne nous est permis ni d\'accepter ni de suivre, à nous qui sommes Romains.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 22, 'La foule se souleva aussi contre eux, et les préteurs, les ayant fait dépouiller de leurs vêtements, ordonnèrent qu\'ils fussent battus de verges.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 23, 'Après qu\'on leur eut donné plusieurs coups, ils les firent jeter en prison, en recommandant au geôlier de les tenir sous bonne garde.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 24, 'Ayant reçu cet ordre, il les mit au fond de la prison, et leur serra les pieds dans des entraves.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 25, 'Vers le milieu de la nuit, Paul et Silas, étant en prières, chantaient les louanges de Dieu, et les prisonniers les écoutaient.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 26, 'Tout à coup, il se fit un grand tremblement de terre, de sorte que les fondements de la prison furent ébranlés. En même temps toutes les portes s\'ouvrirent, et les liens de tous les prisonniers tombèrent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 27, 'Le geôlier, réveillé en sursaut et voyant les portes de la prison ouvertes, tira son épée; et il allait se tuer, croyant que les prisonniers s\'étaient enfuis.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 28, 'Mais Paul lui cria à haute voix: Ne te fais point de mal; nous sommes tous ici!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 29, 'Alors le geôlier, ayant demandé de la lumière, accourut; et, tout tremblant, il se jeta aux pieds de Paul et de Silas.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 30, 'Puis, les ayant menés dehors, il leur dit: Seigneurs, que faut-il que je fasse pour être sauvé?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 31, 'Ils lui dirent: Crois au Seigneur Jésus, et tu seras sauvé, toi et ta famille.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 32, 'Alors ils lui annoncèrent la parole de Dieu, ainsi qu\'à tous ceux qui étaient dans sa maison.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 33, 'Le geôlier, les prenant avec lui à cette même heure de la nuit, lava leurs plaies; et aussitôt il fut baptisé, lui et tous les siens.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 34, 'Puis, les ayant fait monter dans son logement, il fit dresser la table, et il se réjouit avec toute sa famille de ce qu\'il avait cru en Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 35, 'Quand le jour fut venu, les préteurs envoyèrent les licteurs dire au geôlier: Laisse aller ces hommes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 36, 'Le geôlier rapporta ces paroles à Paul: Les préteurs me font dire de vous laisser partir. Sortez donc, et allez en paix.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 37, 'Mais Paul dit aux licteurs: Après nous avoir battus de verges en public et sans jugement, nous qui sommes citoyens romains, ils nous ont mis en prison; et maintenant, ils nous font sortir en cachette! Cela ne sera pas! Qu\'ils viennent eux-mêmes nous mettre en liberté!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 38, 'Les licteurs rapportèrent ces paroles aux préteurs, qui furent effrayés en apprenant qu\'ils étaient Romains.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 39, 'Ils vinrent leur parler; ils les mirent en liberté et les prièrent de quitter la ville.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 40, 'Quand ils furent sortis de la prison, les apôtres entrèrent chez Lydie, et, après avoir vu les frères et les avoir exhortés, ils partirent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 1, 'Paul et Silas passèrent par Amphipolis et par Apollonie; puis ils vinrent à Thessalonique, où les Juifs avaient une synagogue.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 2, 'Selon sa coutume, Paul s\'y rendit, et il discuta avec eux pendant trois sabbats,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 3, 'expliquant et démontrant, par les Ecritures, qu\'il fallait que le Christ souffrît, et qu\'il ressuscitât des morts. Ce Christ, disait-il, c\'est Jésus que je vous annonce.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 4, 'Quelques-uns d\'entre eux furent persuadés; et ils se joignirent à Paul et à Silas, ainsi qu\'une grande multitude de Grecs craignant Dieu, et à plusieurs femmes, des premières de la ville.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 5, 'Mais les Juifs, pleins de jalousie, prirent avec eux quelques mauvais sujets des rues, et, ameutant la foule, ils jetèrent le trouble dans la ville. Ils assaillirent la maison de Jason, et ils y cherchèrent Paul et Silas pour les amener devant le peuple.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 6, 'Ne les ayant pas trouvés, ils traînèrent Jason et quelques-uns des frères devant les magistrats de la ville, en criant: Ces gens, qui ont bouleversé le monde, les voilà maintenant ici!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 7, 'Jason les a reçus chez lui. Or, ils sont tous rebelles aux édits de César, puisqu\'ils disent qu\'il y a un autre roi, Jésus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 8, 'Ces paroles émurent la foule et les magistrats.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 9, 'Ceux-ci, cependant, après avoir exigé une caution de Jason et des autres, les relâchèrent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 10, 'Aussitôt, les frères firent partir de nuit Paul et Silas pour Bérée. Lorsqu\'ils furent arrivés, ils entrèrent dans la synagogue des Juifs.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 11, 'Ceux-ci eurent des sentiments plus nobles que ceux de Thessalonique, et ils accueillirent la Parole avec beaucoup d\'empressement, examinant tous les jours les Écritures, pour vérifier ce qu\'on leur disait.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 12, 'Plusieurs d\'entre eux crurent, ainsi que des femmes grecques de haut rang, et des hommes en assez grand nombre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 13, 'Mais quand les Juifs de Thessalonique surent que Paul annonçait aussi la parole de Dieu à Bérée, ils y vinrent pour répandre l\'agitation et le trouble parmi le peuple.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 14, 'Aussitôt, les frères firent partir Paul, dans la direction de la mer, tandis que Silas et Timothée restaient à Bérée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 15, 'Ceux qui accompagnaient Paul le conduisirent jusqu\'à Athènes; puis ils s\'en retournèrent, apportant à Silas et à Timothée l\'ordre de le rejoindre au plus tôt.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 16, 'Pendant que Paul les attendait à Athènes, il avait le coeur outré à la vue de cette ville toute pleine d\'idoles.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 17, 'Il discutait donc dans la synagogue avec les Juifs et les prosélytes, et, chaque jour, sur la place publique, avec ceux qui s\'y rencontraient.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 18, 'Quelques philosophes épicuriens et stoïciens conféraient aussi avec lui. Les uns disaient: Que veut dire ce discoureur? Et d\'autres: Il semble annoncer des divinités étrangères. — car Paul leur annonçait Jésus et la résurrection. —');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 19, 'Ils le prirent avec eux et le menèrent à l\'Aréopage, en lui disant: Pourrions-nous savoir quelle est cette nouvelle doctrine que tu enseignes?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 20, 'Car tu nous fais entendre des choses étranges. Nous voudrions bien savoir ce que cela veut dire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 21, 'Or, tous les Athéniens, aussi bien que les étrangers qui séjournaient à Athènes ne s\'occupaient qu\'à dire ou à écouter les nouvelles.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 22, 'Alors Paul, se tenant au milieu de l\'Aréopage, dit: Athéniens, je vois qu\'à tous égards vous êtes, pour ainsi dire, dévots à l\'excès.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 23, 'Car, en parcourant votre ville, et en considérant les objets de votre culte, j\'ai trouvé un autel portant cette inscription: Au dieu inconnu. Eh bien, ce que vous honorez sans le connaître, c\'est ce que je vous annonce!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 24, 'Le Dieu qui a fait le monde, et tout ce qui s\'y trouve, étant le Seigneur du ciel et de la terre, n\'habite pas dans des temples bâtis par la main des hommes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 25, 'Il n\'est pas non plus servi par des mains humaines, comme s\'il avait besoin de quoi que ce soit, lui qui donne à tous la vie, la respiration, tous les biens.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 26, 'Il a fait naître d\'un seul homme toutes les nations, et il les a fait habiter sur toute l\'étendue de la terre, ayant fixé le temps précis de leur existence et les limites de leur demeure,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 27, 'afin qu\'elles cherchent Dieu et s\'efforcent de le trouver comme en tâtonnant, quoiqu\'il ne soit pas loin de chacun de nous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 28, 'Car c\'est en lui que nous avons la vie, le mouvement et l\'être, comme l\'ont dit quelques-uns de vos poètes: «Nous sommes aussi de sa race!»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 29, 'Étant donc de la race de Dieu, nous ne devons pas croire que la divinité soit semblable à l\'or, à l\'argent ou à la pierre, sculptés par l\'art et le génie de l\'homme.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 30, 'C\'est pourquoi, ne tenant pas compte de ces temps d\'ignorance, Dieu invite maintenant tous les hommes, en tous lieux, à se repentir,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 31, 'parce qu\'il a fixé un jour, où il doit juger le monde avec justice, par l\'Homme qu\'il a établi pour cela; et il en a donné à tous une preuve certaine en le ressuscitant des morts.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 32, 'Quand ils entendirent parler de résurrection des morts, les uns se moquèrent, les autres dirent: Nous t\'entendrons là-dessus une autre fois.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 33, 'C\'est ainsi que Paul se retira du milieu d\'eux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 34, 'Il y eut cependant quelques personnes qui se joignirent à lui et qui crurent: de ce nombre étaient Denis, membre de l\'Aréopage, une femme nommée Damaris, et d\'autres encore avec eux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 1, 'Après cela, Paul, étant parti d\'Athènes, vint à Corinthe.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 2, 'Il y trouva un Juif, nommé Aquilas, originaire du Pont, récemment arrivé d\'Italie avec Priscille, sa femme, parce que Claude avait ordonné à tous les Juifs de s\'éloigner de Rome; et il se joignit à eux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 3, 'Comme Paul exerçait le même métier, il demeura chez eux, et ils travaillaient ensemble; or, leur métier était de faire des tentes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 4, 'Paul parlait dans la synagogue tous les jours de sabbat, et il persuadait les Juifs et les Grecs.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 5, 'Quand Silas et Timothée arrivèrent de Macédoine, Paul s\'adonnait de toute son âme à la prédication, attestant aux Juifs que Jésus était le Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 6, 'Mais, comme ils s\'opposaient à lui et l\'injuriaient, il secoua ses vêtements et leur dit: Que votre sang retombe sur votre tête! Pour moi, j\'en suis net; dès maintenant, j\'irai vers les Païens.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 7, 'Etant sorti de là, il entra chez un certain Titius Justus, homme craignant Dieu et dont la maison touchait à la synagogue.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 8, 'Cependant Crispus, le chef de la synagogue, crut au Seigneur avec toute sa maison; et plusieurs des Corinthiens, ayant entendu Paul, crurent aussi et furent baptisés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 9, 'Le Seigneur dit à Paul pendant la nuit, dans une vision: Ne crains rien; mais parle et ne te tais point!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 10, 'Je suis avec toi, et personne ne mettra la main sur toi, pour te faire du mal; car j\'ai un grand peuple dans cette ville.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 11, 'Paul demeura là un an et six mois, enseignant parmi eux la parole de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 12, 'Lorsque Gallion était proconsul d\'Achaïe, les Juifs, d\'un commun accord, s\'élevèrent contre Paul et l\'amenèrent au tribunal, en disant:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 13, 'Cet homme excite les gens à adorer Dieu d\'une manière contraire à la loi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 14, 'Comme Paul ouvrait la bouche pour répondre, Gallion dit aux Juifs: S\'il s\'agissait, ô Juifs, de quelque injustice ou de quelque crime, je vous écouterais patiemment, comme de raison.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 15, 'Mais puisqu\'il s\'agit de discussions sur une doctrine, sur des noms et sur votre loi particulière, examinez cela vous-mêmes; je ne veux pas être juge de ces choses.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 16, 'Puis il les renvoya du tribunal.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 17, 'Alors tous, ayant saisi Sosthène, le chef de la synagogue, le battaient devant le tribunal; mais Gallion ne s\'en souciait pas.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 18, 'Paul resta encore quelque temps à Corinthe. Il prit ensuite congé des frères et s\'embarqua pour la Syrie avec Priscille et Aquilas, après s\'être fait raser la tête à Cenchrées; car il avait fait un voeu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 19, 'Puis ils arrivèrent à Ephèse, où il laissa ses compagnons. Pour lui, il entra dans la synagogue et s\'entretint avec les Juifs.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 20, 'Alors ils lui demandèrent de rester plus longtemps, mais il n\'y consentit pas.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 21, 'Il prit congé d\'eux, en disant: Je reviendrai une autre fois chez vous, s\'il plaît à Dieu; et il partit d\'Éphèse.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 22, 'Étant débarqué à Césarée, il monta à Jérusalem; et, après avoir salué l\'Église, il descendit à Antioche.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 23, 'Lorsqu\'il y eut passé quelque temps, il en repartit, et il parcourut successivement la Galatie et la Phrygie, affermissant tous les disciples.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 24, 'Cependant un Juif, nommé Apollos, natif d\'Alexandrie, homme éloquent et très versé dans les Écritures, arriva à Éphèse.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 25, 'Il avait été instruit dans la voie du Seigneur; il parlait avec une grande ferveur, et il enseignait avec exactitude ce qui concerne Jésus, bien qu\'il n\'eût connaissance que du baptême de Jean.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 26, 'Il commença donc à parler avec hardiesse dans la synagogue. Priscille et Aquilas, l\'ayant entendu, le prirent avec eux et lui exposèrent plus exactement encore la voie de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 27, 'Comme Apollos voulait passer en Achaïe, les frères l\'y encouragèrent et écrivirent aux disciples de lui faire bon accueil. Quand il fut arrivé, il se rendit très utile, par la grâce de Dieu, à ceux qui avaient cru.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 28, 'Car il réfutait publiquement les Juifs avec une grande force, démontrant par les Écritures que Jésus est le Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 1, 'Pendant qu\'Apollos était à Corinthe, Paul, après avoir parcouru les régions les plus élevées du pays, descendit à Éphèse, et il y trouva quelques disciples.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 2, 'Il leur dit: Avez-vous reçu le Saint-Esprit lorsque vous avez cru? Ils lui répondirent: Nous n\'avons pas même entendu dire qu\'il y ait un Saint-Esprit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 3, 'Il reprit: Quel baptême avez-vous donc reçu? Ils répondirent: Le baptême de Jean.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 4, 'Alors Paul leur dit: Jean a baptisé du baptême de repentance, en disant au peuple de croire en celui qui devait venir après lui, c\'est-à-dire en Jésus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 5, 'Ayant entendu ces paroles, ils furent baptisés au nom du Seigneur Jésus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 6, 'Après que Paul leur eut imposé les mains, le Saint-Esprit descendit sur eux, et ils se mirent à parler en d\'autres langues et à prophétiser.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 7, 'Ils étaient environ douze hommes en tout.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 8, 'Paul se rendit dans la synagogue, et il parla avec hardiesse pendant trois mois. Il persuadait ses auditeurs, en leur exposant ce qui concerne le royaume de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 9, 'Mais, comme quelques-uns s\'endurcissaient et refusaient de croire, décriant la voie du Seigneur devant la foule, il se sépara d\'eux et réunit à part les disciples; et il enseignait tous les jours dans l\'école de Tyrannus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 10, 'Cela continua pendant deux ans, de sorte que tous ceux qui demeuraient en Asie, Juifs et Grecs, entendirent la parole du Seigneur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 11, 'Et Dieu opérait des miracles extraordinaires par les mains de Paul,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 12, 'au point qu\'on mettait sur les malades les linges et les vêtements qui avaient touché son corps; et ils étaient guéris de leurs maladies, et délivrés des mauvais esprits.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 13, 'Alors quelques exorcistes juifs, qui allaient de lieu en lieu, essayèrent d\'invoquer le nom du Seigneur Jésus sur ceux qui étaient possédés des mauvais esprits; et ils disaient: Je vous adjure, par ce Jésus que Paul prêche!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 14, 'Ceux qui procédaient ainsi étaient les sept fils de Scévas, l\'un des principaux sacrificateurs juifs.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 15, 'Mais le mauvais esprit leur répondit: Je connais Jésus, et je sais qui est Paul; mais vous, qui êtes-vous?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 16, 'Alors, se jetant sur eux, l\'homme qui était possédé du mauvais esprit se rendit maître de deux d\'entre eux, et il les maltraita si fort, qu\'ils s\'enfuirent de la maison, nus et blessés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 17, 'Le fait fut connu de tous les Juifs et de tous les Grecs qui demeuraient à Éphèse. Ils furent tous saisis de crainte, et le nom du Seigneur Jésus était magnifié.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 18, 'Beaucoup de ceux qui avaient cru venaient avouer et déclarer ce qu\'ils avaient fait.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 19, 'Plusieurs de ceux qui s\'étaient livrés à la magie apportèrent leurs livres, et les brûlèrent devant tout le monde; quand on en eut estimé la valeur, elle se trouva être de cinquante mille pièces d\'argent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 20, 'Ainsi, par la puissance du Seigneur, la parole se répandait, et elle devenait de plus en plus efficace.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 21, 'Après ces événements, Paul se proposa d\'aller à Jérusalem, en passant par la Macédoine et par l\'Achaïe. Lorsque j\'aurai été là, disait-il, il faudra aussi que je voie Rome.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 22, 'Il envoya en Macédoine deux de ses aides, Timothée et Éraste, mais lui-même resta encore quelque temps en Asie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 23, 'Il se produisit, en ce temps-là, un grand trouble à l\'occasion de l\'Évangile.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 24, 'Un orfèvre, nommé Démétrius, qui fabriquait des temples de Diane en argent, et qui donnait beaucoup de travail aux ouvriers,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 25, 'les rassembla, ainsi que les artisans du même métier, et il leur dit: Mes amis, vous savez que notre prospérité vient de cette industrie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 26, 'Or, vous voyez et entendez dire que, non seulement à Éphèse, mais presque dans toute l\'Asie, ce Paul a persuadé et entraîné un grand nombre de personnes, en disant que les dieux faits de main d\'homme ne sont pas des dieux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 27, 'Nous avons à craindre, non seulement que notre métier ne soit décrié, mais encore que le temple de la grande Diane ne tombe dans le mépris, et que notre déesse ne soit dépouillée de cette majesté que vénèrent l\'Asie et le monde entier.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 28, 'A ces paroles, tous furent transportés de colère, et se mirent à crier: Grande est la Diane des Éphésiens!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 29, 'Toute la ville fut remplie de trouble; et ils se précipitèrent tous ensemble dans le théâtre, entraînant avec eux Gaïus et Aristarque, Macédoniens, compagnons de voyage de Paul.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 30, 'Paul lui-même voulait se présenter devant le peuple; mais les disciples ne le lui permirent pas.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 31, 'Il y eut même des Asiarques, de ses amis, qui le firent prier de ne pas se rendre au théâtre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 32, 'Ainsi, les uns criaient d\'une manière, et les autres d\'une autre; car l\'assemblée était tumultueuse, et la plupart ne savaient même pas pourquoi ils étaient réunis.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 33, 'Alors on tira de la foule Alexandre, que les Juifs poussaient en avant; et Alexandre, faisant signe de la main, voulait parler au peuple pour leur défense.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 34, 'Mais, dès que la foule eut reconnu qu\'il était juif, elle se mit à crier d\'une seule voix, pendant près de deux heures: Grande est la Diane des Éphésiens!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 35, 'Cependant, le secrétaire de la ville, ayant apaisé la foule, dit: Éphésiens, quel est l\'homme qui ignore que la ville d\'Éphèse est la gardienne du temple de la grande Diane et de son image tombée du ciel?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 36, 'Cela étant incontestable, vous devez rester calmes et ne rien faire avec précipitation.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 37, 'En effet, ces gens, que vous avez amenés ici, ne sont coupables ni de sacrilège, ni de blasphème contre votre déesse.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 38, 'Si donc Démétrius et les ouvriers qui sont avec lui ont à se plaindre de quelqu\'un, il y a des jours d\'audience, et il y a des proconsuls; qu\'ils s\'assignent les uns les autres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 39, 'Si vous avez une autre affaire à proposer, on pourra en décider dans une assemblée légale.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 40, 'Car nous sommes en danger d\'être accusés de sédition pour ce qui s\'est passé aujourd\'hui, ne pouvant alléguer aucune raison pour justifier ce rassemblement.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 41, 'Sur ces paroles, il congédia l\'assemblée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 1, 'Lorsque le tumulte eut cessé, Paul réunit les disciples; et, après leur avoir fait entendre ses exhortations, il prit congé d\'eux et partit pour la Macédoine.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 2, 'Il parcourut cette contrée, et il adressa des exhortations nombreuses aux fidèles; puis, il vint en Grèce,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 3, 'et il y demeura trois mois. Les Juifs ayant dressé contre lui des embûches, au moment où il allait s\'embarquer pour la Syrie, il se décida à retourner par la Macédoine.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 4, 'Sopater, fils de Pyrrhus, de Bérée, l\'accompagnait, ainsi qu\'Aristarque et Secundus, de Thessalonique, Gaïus, de Derbe, et Timothée, Tychique et Trophime, originaires d\'Asie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 5, 'Ceux-ci prirent les devants et nous attendirent à Troas.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 6, 'Quant à nous, après les jours des pains sans levain, nous nous embarquâmes à Philippes, et en cinq jours nous les rejoignîmes à Troas, où nous demeurâmes sept jours.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 7, 'Le premier jour de la semaine, comme nous étions réunis pour rompre le pain, Paul, devant partir le lendemain, s\'entretint avec les disciples et prolongea son discours jusqu\'à minuit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 8, 'Il y avait beaucoup de lampes, dans la chambre haute où nous étions réunis.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 9, 'Un jeune homme, nommé Eutyche, assis sur la fenêtre, s\'endormit profondément pendant le long discours de Paul; et, accablé par le sommeil, il tomba du troisième étage et fut relevé mort.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 10, 'Mais Paul, étant descendu, se pencha sur lui, et, l\'ayant pris dans ses bras, il dit: Ne vous troublez point; car son âme est encore en lui!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 11, 'Après être remonté, il rompit le pain et mangea; et après avoir parlé longtemps, jusqu\'au point du jour, il partit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 12, 'Quant au jeune homme, on le ramena vivant, ce qui fut pour tous une grande consolation.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 13, 'Pour nous, ayant pris les devants, nous fîmes voile vers Assos, où nous devions rejoindre Paul; il l\'avait ainsi décidé, parce qu\'il voulait faire le chemin à pied.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 14, 'Quand il nous eut rejoints à Assos, nous le prîmes avec nous, et nous vînmes à Mitylène.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 15, 'Puis, étant partis de là, toujours par mer, nous arrivions le lendemain vis-à-vis de Chio. Le jour suivant, nous touchions à Samos, et, le jour d\'après, nous étions à Milet.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 16, 'Paul, en effet, avait résolu de passer devant Éphèse sans s\'y arrêter, pour ne pas perdre de temps en Asie. Il se hâtait, pour être à Jérusalem, si possible, le jour de la Pentecôte.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 17, 'Cependant, de Milet, Paul envoya des messagers à Éphèse pour convoquer les anciens de l\'Eglise.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 18, 'Lorsqu\'ils furent réunis auprès de lui, il leur dit: Vous savez de quelle manière je me suis toujours conduit avec vous, depuis le premier jour de mon arrivée en Asie,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 19, 'servant le Seigneur en toute humilité, dans les larmes, et au milieu des épreuves auxquelles m\'exposaient les embûches des Juifs.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 20, 'Vous savez que je n\'ai pas négligé de vous annoncer tout ce qui vous était utile, sans vous en rien cacher, que je vous ai instruits en public et de maison en maison,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 21, 'prêchant aux Juifs comme aux Grecs la repentance envers Dieu et la foi en notre Seigneur Jésus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 22, 'Maintenant, voici que, lié par l\'Esprit, je vais à Jérusalem, sans savoir ce qui doit m\'y arriver;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 23, 'seulement, le Saint-Esprit m\'avertit de ville en ville que des chaînes et des afflictions m\'attendent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 24, 'Mais je n\'attache pour moi-même aucun prix à ma vie, pourvu que j\'achève ma course et le ministère que j\'ai reçu du Seigneur Jésus, en rendant, témoignage à l\'Évangile de la grâce de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 25, 'Oui, je le sais, vous ne verrez plus mon visage, ô vous tous, parmi lesquels j\'ai passé en prêchant le Royaume!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 26, 'C\'est pourquoi, je proteste aujourd\'hui devant vous que je suis net du sang de vous tous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 27, 'Car je n\'ai rien négligé pour vous faire connaître tout le dessein de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 28, 'Prenez garde à vous-mêmes, et à tout le troupeau au milieu duquel le Saint-Esprit vous a établis évêques, pour paître l\'Église de Dieu qu\'il s\'est acquise par son propre sang.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 29, 'Pour moi, je sais qu\'après mon départ, il s\'introduira parmi vous des loups cruels, qui n\'épargneront point le troupeau;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 30, 'et même du milieu de vous, il se lèvera des hommes au langage pervers, qui s\'efforceront d\'entraîner les disciples à leur suite.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 31, 'Veillez donc, vous souvenant que, durant trois ans, je n\'ai cessé, nuit et jour, d\'avertir chacun avec larmes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 32, 'Et maintenant, je vous recommande à Dieu et à la parole de sa grâce, à lui qui peut vous édifier et vous donner votre part d\'héritage, avec tous ceux qui sont sanctifiés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 33, 'Je n\'ai désiré ni l\'argent, ni l\'or, ni le vêtement de personne.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 34, 'Vous le savez vous-mêmes, les mains que voilà ont pourvu à mes besoins et à ceux de mes compagnons.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 35, 'Je vous ai toujours montré que c\'est en travaillant ainsi, qu\'il faut venir en aide aux faibles, et se souvenir des paroles du Seigneur Jésus, qui a dit lui-même: «Il y a plus de bonheur à donner qu\'à recevoir!»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 36, 'Quand il eut dit cela, il se mit à genoux, et pria avec eux tous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 37, 'Ils fondirent tous en larmes; et, se jetant au cou de Paul,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 38, 'ils l\'embrassaient tendrement, étant surtout affligés de ce qu\'il avait dit qu\'ils ne verraient plus son visage. Puis, ils l\'accompagnèrent jusqu\'au navire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 1, 'Après nous être séparés d\'eux avec peine, nous nous embarquâmes, et nous vînmes droit à Cos, le jour suivant à Rhodes, et de là, à Patara.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 2, 'Il s\'y trouvait un navire qui mettait à la voile pour la Phénicie; nous montâmes à son bord et nous partîmes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 3, 'Quand nous fûmes en vue de l\'île de Chypre, nous la laissâmes à gauche, poursuivant notre route vers la Syrie, et nous abordâmes à Tyr, parce que le navire devait y laisser son chargement.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 4, 'Étant allés trouver les disciples, nous restâmes sept jours avec eux. Poussés par l\'Esprit, ils disaient à Paul de ne pas monter à Jérusalem.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 5, 'Mais, lorsque le temps de notre séjour fut écoulé, nous nous remîmes en route. Ils nous accompagnèrent tous, avec leurs femmes et leurs enfants, jusqu\'en dehors de la ville; et, nous étant agenouillés sur le rivage, nous priâmes ensemble.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 6, 'Puis, après avoir fait nos adieux les uns aux autres, nous montâmes nous-mêmes à bord, tandis qu\'ils retournaient chez eux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 7, 'Quant à nous, achevant notre voyage par mer, nous nous rendîmes de Tyr à Ptolémaïs; et, après avoir salué les frères, nous passâmes un jour avec eux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 8, 'Le lendemain, étant partis de là, nous vînmes à Césarée; et, entrant dans la maison de Philippe l\'évangéliste, un des sept diacres, nous demeurâmes chez lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 9, 'Il avait quatre filles, non mariées, qui prophétisaient.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 10, 'Nous étions là depuis plusieurs jours, quand arriva de Judée un prophète, nommé Agabus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 11, 'Étant venu nous voir, il prit la ceinture de Paul, se lia les pieds et les mains, et il dit: Voici ce que déclare le Saint-Esprit: L\'homme à qui appartient cette ceinture sera ainsi lié à Jérusalem par les Juifs, et ils le livreront aux mains des Païens.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 12, 'Lorsque nous eûmes entendu ces paroles, les fidèles de ce lieu et nous, nous priâmes Paul de ne pas monter à Jérusalem.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 13, 'Mais il répondit: Que faites-vous, en pleurant ainsi et en me brisant le coeur? Car, pour moi, je suis prêt, non seulement à être lié, mais encore à mourir à Jérusalem pour le nom du Seigneur Jésus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 14, 'Comme il ne se laissait pas persuader, nous n\'insistâmes pas davantage, et nous dîmes: Que la volonté du Seigneur se fasse!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 15, 'Après ces jours-là, ayant fait nos préparatifs, nous montâmes à Jérusalem.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 16, 'Quelques disciples de Césarée y vinrent aussi avec nous, et ils nous conduisirent chez un certain Mnason, de Chypre, qui, depuis longtemps, était un disciple, et qui devait nous donner l\'hospitalité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 17, 'A notre arrivée à Jérusalem, les frères nous reçurent avec joie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 18, 'Le lendemain, Paul se rendit avec nous chez Jacques; et tous les anciens s\'y réunirent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 19, 'Après les avoir salués, Paul raconta en détail ce que Dieu avait fait parmi les Païens par son ministère.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 20, 'Quand ils l\'eurent entendu, ils glorifièrent Dieu. Puis ils lui dirent: Frère, tu vois combien de milliers de Juifs ont cru; et tous sont zélés pour la loi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 21, 'Or, ils ont été informés que tu enseignes à tous les Juifs qui vivent parmi les Païens, de renoncer à Moïse, en leur disant qu\'ils ne doivent pas circoncire leurs enfants, ni suivre leurs coutumes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 22, 'Qu\'y a-t-il donc à faire? Il est certain que la multitude va se rassembler; car on apprendra que tu es arrivé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 23, 'Fais donc ce que nous allons te dire: Nous avons ici quatre hommes qui ont fait un voeu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 24, 'Prends-les avec toi; purifie-toi avec eux, et charge-toi de ce qu\'ils auront à payer pour se faire raser la tête. Tous sauront qu\'il n\'y a rien de vrai dans tout ce qu\'on a raconté de toi, mais que, toi aussi, tu vis en observateur de la loi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 25, 'Quant aux Païens qui ont cru, nous leur avons écrit ce que nous avions décidé: qu\'ils devaient seulement s\'abstenir des viandes offertes en sacrifice aux idoles, du sang, des animaux étouffés et de l\'impudicité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 26, 'Alors Paul, ayant pris ces hommes avec lui, et s\'étant, dès le lendemain, purifié avec eux, entra dans le temple, pour déclarer le jour où la purification serait achevée et l\'offrande présentée pour chacun d\'eux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 27, 'Les sept jours touchaient à leur fin, quand les Juifs d\'Asie, ayant vu Paul dans le temple, ameutèrent toute la multitude et mirent la main sur lui,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 28, 'en criant: Hommes d\'Israël, à l\'aide! Voici l\'homme qui prêche partout, à tout le monde, contre la nation, contre la loi et contre ce lieu; il a même introduit des Grecs dans le temple, et il a profané ce saint lieu!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 29, 'En effet, ils avaient vu auparavant Trophime d\'Éphèse avec lui dans la ville, et ils croyaient que Paul l\'avait introduit dans le temple.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 30, 'Toute la ville fut en émoi, et le peuple accourut en foule. Ayant saisi Paul, ils le traînèrent hors du temple, dont les portes furent aussitôt fermées.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 31, 'Comme ils cherchaient à le tuer, le bruit parvint au tribun de la cohorte que tout Jérusalem s\'agitait.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 32, 'Immédiatement, il prit avec lui des soldats et des centeniers; et il se hâta de descendre vers eux. A la vue du tribun et des soldats, ils cessèrent de frapper Paul.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 33, 'Alors le tribun s\'approcha, mit la main sur lui et ordonna de le lier de deux chaînes; puis, il demanda qui il était, et ce qu\'il avait fait.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 34, 'Dans la foule, les uns criaient d\'une manière, les autres d\'une autre; et comme il ne pouvait rien apprendre de certain, à cause du tumulte, il ordonna de le mener dans la forteresse.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 35, 'Quand Paul fut sur les degrés, les soldats durent le porter, à cause de la violence de la foule.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 36, 'Car le peuple suivait en masse, en criant: A mort!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 37, 'Au moment d\'entrer dans la forteresse, Paul dit au tribun: M\'est-il permis de te dire quelque chose? Le tribun répondit: Tu sais parler grec?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 38, 'Tu n\'es donc pas l\'Égyptien qui, ces jours passés, a provoqué une sédition et entraîné au désert quatre mille brigands?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 39, 'Paul lui dit: Je suis Juif, de Tarse, citoyen d\'une ville de Cilicie qui n\'est pas sans renom; permets-moi, je te prie, de parler au peuple.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 40, 'Le tribun le lui permit; et Paul, se tenant sur les degrés, fit signe de la main au peuple. Un profond silence s\'établit; puis, parlant en langue hébraïque, il leur dit:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 1, 'Mes frères et mes pères, écoutez ce que j\'ai à vous dire maintenant pour ma défense.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 2, 'Quand ils l\'entendirent parler en langue hébraïque, ils redoublèrent d\'attention. Alors il dit:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 3, 'Je suis Juif, né à Tarse, en Cilicie; mais j\'ai été élevé ici dans cette ville, aux pieds de Gamaliel, instruit dans la connaissance exacte de la loi de nos pères. J\'étais plein de zèle pour Dieu, comme vous l\'êtes tous aujourd\'hui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 4, 'Cette secte, je l\'ai persécutée à mort, chargeant de chaînes et jetant en prison hommes et femmes:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 5, 'le souverain sacrificateur m\'en est témoin, ainsi que toute l\'assemblée des anciens. C\'est d\'eux, en effet, que je reçus des lettres pour les frères de Damas, où je me rendis, afin de jeter aussi dans les chaînes ceux qui se trouvaient là et de les amener à Jérusalem pour les y faire punir.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 6, 'Or il arriva, comme j\'étais en chemin et que j\'approchais de Damas, vers midi, que tout à coup une grande lumière, venant du ciel, resplendit autour de moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 7, 'Je tombai à terre, et j\'entendis une voix qui me disait: Saul, Saul, pourquoi me persécutes-tu?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 8, 'Je répondis: Qui es-tu. Seigneur? La voix me dit; Je suis Jésus de Nazareth, que tu persécutes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 9, 'Ceux qui étaient avec moi virent bien la lumière, mais ils n\'entendirent pas la voix de celui qui me parlait.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 10, 'Alors je m\'écriai: Que ferai-je, Seigneur? Le Seigneur me répondit: Lève-toi, va à Damas, et là on te dira tout ce qu\'il t\'est ordonné de faire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 11, 'Et comme je n\'y voyais pas, à cause de l\'éclat de cette lumière, ceux qui étaient avec moi me prirent par la main, et j\'allai à Damas.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 12, 'Un certain Ananias, homme pieux selon la loi, auquel tous les Juifs demeurant à Damas rendaient un bon témoignage, vint me trouver;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 13, 'et, se tenant devant moi, il me dit: Saul, mon frère, recouvre la vue. Au même instant, je recouvrai la vue et je vis Ananias.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 14, 'Puis il me dit: Le Dieu de nos pères t\'a destiné à connaître sa volonté, à voir le Juste et à entendre la parole de sa bouche.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 15, 'Car tu seras pour lui, devant tous les hommes, le témoin des choses que tu as vues et entendues.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 16, 'Et maintenant, que tardes-tu? Lève-toi, sois baptisé et purifié de tes péchés, en invoquant son nom.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 17, 'De retour à Jérusalem, comme je priais dans le temple, je fus ravi en extase;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 18, 'et je vis Jésus qui me disait: Hâte-toi, sors promptement de Jérusalem; car on n\'y recevra point le témoignage que tu me rendras.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 19, 'Je répondis: Seigneur, ils savent eux-mêmes que je mettais en prison et que je faisais battre de verges dans les synagogues ceux qui croient en toi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 20, 'Lorsque fut répandu le sang d\'Etienne, ton témoin, j\'étais là, j\'approuvais, et je gardais les vêtements de ceux qui le faisaient mourir.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 21, 'Alors il me dit: Va; car je t\'enverrai au loin, vers les Païens.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 22, 'On avait écouté Paul jusque-là; mais à ce mot, ils se mirent à crier: Ote de la terre un tel homme! Il n\'est pas digne de vivre!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 23, 'Ils poussaient des cris; ils jetaient leurs vêtements, et faisaient voler la poussière en l\'air.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 24, 'Le tribun ordonna alors de mener Paul dans la forteresse et de lui donner la question par le fouet, afin de savoir pour quel sujet ils criaient ainsi contre lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 25, 'Comme on l\'attachait pour lui donner les coups, Paul dit au centenier qui était présent: Vous est-il permis de battre de verges un citoyen romain, qui n\'a pas même été condamné?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 26, 'A ces paroles, le centenier alla avertir le tribun: Que vas-tu faire? lui dit-il; car cet homme est citoyen romain.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 27, 'Le tribun, étant venu, dit à Paul: Dis-moi, es-tu citoyen romain? Oui, répondit Paul.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 28, 'Le tribun reprit: J\'ai acheté à grand prix ce droit de citoyen. Et moi, dit Paul, je l\'ai par ma naissance.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 29, 'Aussitôt, ceux qui devaient lui donner la question s\'éloignèrent; et le tribun eut peur, quand il sut que celui qu\'il avait fait charger de liens était citoyen romain.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 30, 'Le lendemain, voulant savoir exactement de quoi Paul était accusé par les Juifs, le tribun lui fit ôter ses liens; et, ayant ordonné aux principaux sacrificateurs et à tout le Sanhédrin de se réunir, il amena Paul et le fit comparaître devant eux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 1, 'Paul ayant les yeux fixés sur le Sanhédrin, dit: Mes frères, je me suis conduit jusqu\'à ce jour en toute bonne conscience devant Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 2, 'Alors le souverain sacrificateur, Ananias, commanda à ceux qui étaient près de Paul, de le frapper sur la bouche.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 3, 'Mais Paul lui dit: Dieu te frappera, muraille blanchie! Tu sièges pour me juger selon la loi, et, au mépris de la loi, tu ordonnes qu\'on me frappe!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 4, 'Ceux qui étaient là, lui dirent: Tu injuries le souverain sacrificateur de Dieu!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 5, 'Paul, répondit: Frères, je ne savais pas que ce fût le souverain sacrificateur; car il est écrit: «Tu n\'outrageras pas le chef de ton peuple.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 6, 'Paul, sachant qu\'une partie d\'entre eux étaient sadducéens et les autres pharisiens, s\'écria devant le Sanhédrin: Mes frères, je suis pharisien, fils de pharisiens. C\'est à cause de mon espérance en la résurrection des morts, que je suis mis en jugement.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 7, 'Quand il eut parlé ainsi, une discussion s\'éleva entre les pharisiens et les sadducéens, et l\'assemblée fut divisée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 8, 'En effet, les sadducéens disent qu\'il n\'y a pas de résurrection, et qu\'il n\'existe ni ange, ni esprit, tandis que les pharisiens professent ces croyances.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 9, 'Il y eut alors une grande clameur. Quelques scribes, du parti des pharisiens, se levèrent et combattirent l\'accusation, en disant: Nous ne trouvons aucun mal en cet homme. Qui sait si un esprit ou un ange ne lui a point parlé?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 10, 'Comme le tumulte augmentait, le tribun, craignant que Paul ne fût mis en pièces par eux, commanda à la troupe de descendre, pour l\'enlever du milieu d\'eux et le ramener dans la forteresse.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 11, 'La nuit suivante, le Seigneur apparut à Paul et lui dit: Aie bon courage! Comme tu m\'as rendu témoignage à Jérusalem, il faut aussi que tu me rendes témoignage à Rome.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 12, 'Quand le jour fut venu, les Juifs formèrent un complot, et s\'engagèrent, sous peine d\'anathème, à ne manger ni boire, tant qu\'ils n\'auraient pas tué Paul.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 13, 'Ils étaient plus de quarante qui avaient fait cette conjuration.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 14, 'Ils allèrent trouver les principaux sacrificateurs et les anciens, et ils leur dirent: Nous nous sommes engagés, sous peine d\'anathème, à ne rien manger, avant d\'avoir tué Paul.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 15, 'Vous donc maintenant, adressez-vous, avec le Sanhédrin, au tribun, pour qu\'il le fasse comparaître devant vous, comme si vous vouliez examiner plus à fond son affaire. Quant à nous, nous sommes prêts à le faire périr, avant qu\'il soit arrivé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 16, 'Mais le fils de la soeur de Paul, ayant été informé de ce guet-apens, se rendit à la forteresse; il y entra et avertit Paul.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 17, 'Alors Paul appela l\'un des centeniers et lui dit: Mène ce jeune homme auprès du tribun: il a quelque chose à lui communiquer.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 18, 'Le centenier l\'emmena donc, le conduisit chez le tribun et lui dit: Le prisonnier Paul m\'a appelé et m\'a prié de t\'amener ce jeune homme, qui a quelque chose à te dire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 19, 'Le tribun prit le jeune homme par la main et, le tirant à l\'écart, lui demanda: Qu\'as-tu à me communiquer?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 20, 'Il répondit: Les Juifs ont résolu de te prier de faire comparaître Paul, demain, devant le Sanhédrin, comme s\'il s\'agissait d\'instruire plus exactement son affaire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 21, 'Mais ne les crois point; car plus de quarante d\'entre eux lui dressent des embûches, et se sont engagés, sous peine d\'anathème, à ne manger ni boire avant de l\'avoir tué; et maintenant, ils sont prêts, n\'attendant que ta réponse.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 22, 'Le tribun renvoya ce jeune homme, avec défense de dire à personne ce qu\'il venait de lui révéler.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 23, 'Puis, le tribun appela deux des centeniers, et il leur dit: Tenez prêts, dès la troisième heure de la nuit, deux cents soldats, soixante-dix cavaliers et deux cents archers, pour aller jusqu\'à Césarée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 24, 'Préparez aussi des montures, afin de conduire Paul sain et sauf au gouverneur Félix.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 25, 'Ensuite il écrivit à celui-ci une lettre, ainsi conçue:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 26, 'Claude Lysias au très excellent gouverneur Félix, salut!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 27, 'Les Juifs, s\'étant saisis de cet homme, allaient le tuer, quand je suis survenu avec la troupe et le leur ai enlevé, ayant appris qu\'il était citoyen romain.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 28, 'Comme je voulais savoir de quoi ils l\'accusaient, je le fis conduire devant leur Sanhédrin.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 29, 'J\'ai trouvé qu\'on l\'attaquait à propos de questions relatives à leur loi, mais sans qu\'on lui imputât aucune faute méritant la mort ou la prison.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 30, 'Cependant, ayant appris qu\'on dressait des embûches contre cet homme, je te l\'ai aussitôt envoyé, et j\'ai fait savoir à ses accusateurs qu\'ils eussent à parler contre lui devant toi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 31, 'Les soldats prirent donc Paul, selon l\'ordre qu\'ils avaient reçu, et ils le menèrent de nuit jusqu\'à Antipatris.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 32, 'Le lendemain, ils laissèrent les cavaliers partir avec lui, et ils retournèrent à la forteresse.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 33, 'Arrivés à Césarée, les cavaliers remirent la lettre au gouverneur et lui présentèrent Paul.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 34, 'Après avoir lu cette lettre, le gouverneur demanda à Paul de quelle province il était. En apprenant qu\'il était de la Cilicie, il lui dit:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 35, 'Je t\'entendrai quand tes accusateurs seront venus. Puis, il ordonna de le garder dans le prétoire d\'Hérode.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 1, 'Cinq jours après, arriva le souverain sacrificateur Ananias, avec quelques anciens et un orateur, un certain Tertullus; et ils exposèrent devant le gouverneur leur plainte contre Paul.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 2, 'Celui-ci ayant été appelé, Tertullus commença à l\'accuser en ces termes:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 3, 'La paix profonde dont nous jouissons, grâce à toi, très excellent Félix, et les réformes que ta prévoyance t\'a inspirées pour le bien de ce peuple, sont accueillies par nous en tout temps et en tout lieu avec une entière gratitude.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 4, 'Mais, pour ne pas te retenir plus longtemps, je te prie d\'écouter, avec ta bonté ordinaire, ce que nous dirons en peu de mots.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 5, 'Nous avons trouvé cet homme, qui est une peste, et qui provoque des séditions parmi tous les Juifs dans le monde entier: il est le chef de la secte des Nazaréens!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 6, 'Il a même essayé de profaner le temple; nous nous sommes donc emparés de lui. [Nous voulions le juger selon notre loi;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 7, 'mais le tribun Lysias, étant survenu, l\'a violemment arraché de nos mains,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 8, 'en donnant l\'ordre à ses accusateurs de se présenter devant toi]. Tu pourras, en l\'interrogeant toi-même, prendre connaissance de tous les faits dont nous l\'accusons. —');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 9, 'Les Juifs à leur tour confirmèrent ces paroles, assurant qu\'il en était ainsi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 10, 'Après que le gouverneur lui eut fait signe de parler, Paul répondit: Sachant que, depuis plusieurs années, tu es juge de cette nation, c\'est avec confiance que je défends ma cause.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 11, 'Tu peux t\'assurer qu\'il n\'y a pas plus de douze jours que je suis monté à Jérusalem pour adorer.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 12, 'Ni dans le temple, ni dans les synagogues, ni dans la ville, on ne m\'a trouvé discutant avec qui que ce soit ou ameutant le peuple.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 13, 'Aussi ne peuvent-ils prouver ce dont ils m\'accusent maintenant.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 14, 'Je reconnais devant toi que, conformément à une certaine doctrine qu\'ils appellent une hérésie, je sers le Dieu de mes pères, croyant à tout ce qui est écrit dans la loi et dans les prophètes;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 15, 'et j\'ai cette espérance en Dieu, comme ils l\'ont eux-mêmes, qu\'il y aura une résurrection des justes et des injustes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 16, 'C\'est pourquoi aussi, je m\'efforce d\'avoir toujours la conscience sans reproche, devant Dieu et devant les hommes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 17, 'Or, après plusieurs années d\'absence, je suis venu apporter des aumônes à ma nation et présenter des offrandes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 18, 'C\'est dans ces circonstances que certains Juifs d\'Asie m\'ont trouvé dans le temple, pendant que je me purifiais sans provoquer aucun attroupement ni aucun tumulte.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 19, 'Ils auraient dû se présenter eux-mêmes devant toi pour m\'accuser, s\'ils avaient quelque chose à dire contre moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 20, 'Ou bien, que ceux qui sont ici disent de quel méfait ils m\'ont trouvé coupable, lorsque j\'ai comparu devant le Sanhédrin,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 21, 'à moins qu\'ils ne me reprochent ces seules paroles que j\'ai dites à haute voix au milieu d\'eux: C\'est pour la résurrection des morts que je suis aujourd\'hui mis en jugement devant vous!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 22, 'Félix, qui connaissait assez exactement la doctrine dont il s\'agissait, ajourna la cause, en disant: Quand le tribun Lysias sera descendu, j\'examinerai votre affaire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 23, 'Puis, il commanda au centenier de garder Paul, mais de lui laisser une certaine liberté et de n\'empêcher aucun des siens de lui rendre des services.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 24, 'Quelques jours après, Félix, étant venu avec Drusille, sa femme, qui était Juive, fit appeler Paul, et l\'entendit parler de la foi en Jésus-Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 25, 'Mais comme Paul parlait de la justice, de la tempérance et du jugement à venir, Félix, effrayé, lui dit: Pour le moment, retire-toi; quand j\'en aurai le loisir, je te rappellerai.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 26, 'Il espérait aussi que Paul lui donnerait de l\'argent. C\'est pourquoi, il le faisait venir fréquemment et s\'entretenait avec lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 27, 'Deux années s\'étant écoulées, Félix eut pour successeur Portius Festus. Comme il voulait faire plaisir aux Juifs, Félix avait laissé Paul en prison.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 1, 'Trois jours après son arrivée dans sa province, Festus monta de Césarée à Jérusalem.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 2, 'Là, les principaux sacrificateurs et les premiers parmi les Juifs portèrent plainte devant lui contre Paul;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 3, 'et ils lui demandèrent avec instance, comme une faveur, dans une intention hostile, de faire revenir Paul à Jérusalem: ils préparaient un guet-apens pour le tuer en chemin.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 4, 'Mais Festus répondit que Paul était gardé à Césarée, et que lui-même y retournerait bientôt.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 5, 'Que les principaux d\'entre vous, dit-il, descendent avec moi, et, si cet homme a commis quelque crime, qu\'ils l\'accusent!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 6, 'Après avoir passé parmi eux huit à dix jours seulement, Festus redescendit à Césarée. Le lendemain, il prit place à son tribunal et commanda qu\'on amenât Paul.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 7, 'Celui-ci étant arrivé, les Juifs descendus de Jérusalem l\'entourèrent, portant contre lui plusieurs graves accusations, qu\'ils ne pouvaient prouver.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 8, 'Paul disait pour sa défense: Je n\'ai rien fait de mal, ni contre la loi des Juifs, ni contre le temple, ni contre César.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 9, 'Mais Festus, voulant être agréable aux Juifs, répondit à Paul: Veux-tu monter à Jérusalem, et y être jugé sur ces questions en ma présence?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 10, 'Alors Paul dit: Je comparais devant le tribunal de César: c\'est là que je dois être jugé. Je n\'ai fait aucun tort aux Juifs, comme tu le sais bien toi-même.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 11, 'Si je suis coupable, si j\'ai commis quelque crime digne de mort, je ne refuse pas de mourir. Si, au contraire, il n\'y a rien de fondé dans les accusations qu\'ils portent contre moi, personne ne peut me livrer à eux. J\'en appelle à César!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 12, 'Alors Festus, après en avoir conféré avec son conseil, répondit: Tu en as appelé à César, tu iras à César!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 13, 'Quelques jours après, le roi Agrippa et Bérénice arrivèrent à Césarée, pour saluer Festus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 14, 'Comme ils passaient plusieurs jours, Festus exposa au roi l\'affaire de Paul, en disant: Il y a ici un homme que Félix a laissé prisonnier.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 15, 'Lorsque j\'étais à Jérusalem, les principaux sacrificateurs et les anciens des Juifs vinrent l\'accuser et me demander sa condamnation.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 16, 'Je leur répondis que ce n\'est pas la coutume des Romains de livrer un homme, sans que l\'accusé ait été confronté avec ses accusateurs et qu\'il ait eu le moyen de se justifier du crime dont il est accusé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 17, 'Alors ils vinrent ici, et sans aucun délai, dès le lendemain, je pris place à mon tribunal, et je commandai qu\'on amenât cet homme.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 18, 'Les accusateurs, s\'étant présentés, n\'alléguèrent contre lui aucun des crimes que je supposais.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 19, 'Il ne s\'agissait entre eux que de questions relatives à leur religion particulière, et à un certain Jésus, qui est mort, mais que Paul assurait être vivant.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 20, 'Ne sachant quel parti prendre dans ce débat, je demandai à Paul s\'il voulait aller à Jérusalem et y être jugé sur tout cela.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 21, 'Mais, comme il a fait appel, pour que sa cause fût réservée au jugement de l\'empereur, j\'ai ordonné de le garder en prison jusqu\'à ce que je l\'envoie à César.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 22, 'Alors Agrippa dit à Festus: Je voudrais, moi aussi, entendre cet homme. Demain, répondit Festus, tu l\'entendras.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 23, 'Le lendemain donc, Agrippa et Bérénice vinrent en grande pompe; et ils entrèrent dans la salle d\'audience, avec les tribuns et les principaux de la ville. Sur l\'ordre de Festus, Paul fut amené.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 24, 'Puis Festus dit: Roi Agrippa, et vous tous qui êtes ici présents, vous voyez cet homme, au sujet duquel les Juifs sont tous venus en foule me solliciter, tant à Jérusalem qu\'ici, criant qu\'il ne fallait plus le laisser vivre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 25, 'Pour moi, j\'ai trouvé qu\'il n\'avait rien fait qui méritât la mort; et, lui-même en ayant appelé à César, j\'ai résolu de le lui envoyer.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 26, 'Mais comme je n\'ai rien de précis à écrire à l\'empereur sur son compte, je l\'ai fait venir devant vous, et principalement devant toi, roi Agrippa, afin qu\'après cet interrogatoire, j\'aie quelque chose à écrire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 27, 'En effet, il me semble déraisonnable d\'envoyer un prisonnier sans signaler ce dont on l\'accuse.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 1, 'Alors Agrippa dit à Paul: Il t\'est permis de parler pour ta défense. Paul, ayant étendu la main, se défendit ainsi:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 2, 'Roi Agrippa, je m\'estime heureux d\'avoir aujourd\'hui à me disculper devant toi de tout ce dont les Juifs m\'accusent,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 3, 'surtout parce que tu connais toutes les coutumes des Juifs et les questions sur lesquelles ils discutent. Je te prie donc de m\'écouter patiemment.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 4, 'Ma vie, telle qu\'elle s\'est écoulée dès les premiers temps de ma jeunesse, au sein de ma nation et à Jérusalem, est connue de tous les Juifs.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 5, 'Ils savent depuis longtemps, s\'ils veulent en rendre témoignage, que j \'ai vécu en pharisien, selon cette secte qui est la plus austère de notre religion.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 6, 'Et maintenant, je suis mis en jugement pour avoir espéré en la promesse faite par Dieu à nos pères,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 7, 'promesse dont nos douze tribus, qui servent Dieu nuit et jour avec ferveur, attendent l\'accomplissement. C\'est pour cette espérance, ô roi, que je suis accusé par des Juifs.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 8, 'Eh quoi! Jugez-vous incroyable que Dieu ressuscite les morts?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 9, 'Moi-même, il est vrai, j\'avais cru qu\'il fallait combattre par tous les moyens le nom de Jésus de Nazareth.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 10, 'C\'est ce que j\'ai fait à Jérusalem: j\'ai jeté en prison plusieurs des saints, après en avoir reçu le pouvoir des principaux sacrificateurs; et lorsqu\'on les faisait mourir, je donnais mon suffrage.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 11, 'Souvent même, allant d\'une synagogue à l\'autre, je sévissais contre eux pour les contraindre à blasphémer. J\'étais tellement transporté de fureur contre eux, que je les persécutais jusque dans les villes étrangères.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 12, 'C\'est ainsi que je me rendais à Damas, avec pleins pouvoirs et une autorisation des principaux sacrificateurs,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 13, 'lorsque, sur la route, je vis, ô roi, en plein midi, une lumière venant du ciel, plus éclatante que celle du soleil, et qui resplendit autour de moi et de ceux qui m\'accompagnaient.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 14, 'Nous tombâmes tous à terre, et j\'entendis une voix qui me disait, en langue hébraïque: Saul, Saul, pourquoi me persécutes-tu? Il te serait dur de te regimber contre, l\'aiguillon.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 15, 'Je dis: Qui es-tu, Seigneur? Le Seigneur me répondit: Je suis Jésus, que tu persécutes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 16, 'Mais relève-toi, et tiens-toi debout; car je te suis apparu pour t\'établir ministre et témoin des choses que tu as vues, et de celles pour lesquelles je t\'apparaîtrai encore.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 17, 'Je te protégerai contre ce peuple et contre les Païens vers lesquels je t\'envoie,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 18, 'pour leur ouvrir les yeux, afin qu\'ils passent des ténèbres à la lumière et de la puissance de Satan à Dieu, et qu\'ils obtiennent, par la foi en moi, la rémission des péchés et leur part d\'héritage avec ceux qui ont été sanctifiés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 19, 'Dès lors, roi Agrippa, je ne résistai point à la vision céleste;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 20, 'mais j\'exhortai d\'abord les habitants de Damas, ensuite ceux de Jérusalem et de toute la Judée, puis les Païens, à se repentir et à se convertir à Dieu, en faisant des oeuvres dignes de la repentance.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 21, 'Voilà pourquoi les Juifs, m\'ayant saisi dans le temple, se sont efforcés de me tuer.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 22, 'Grâce à la protection de Dieu, j\'ai subsisté jusqu\'à aujourd\'hui, rendant témoignage devant les petits et devant les grands, ne disant rien d\'autre que ce que les prophètes et Moïse ont prédit devoir arriver,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 23, 'savoir, que le Christ devait souffrir, et qu\'étant le premier ressuscité des morts, il devait annoncer la lumière au peuple et aux Païens.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 24, 'Comme Paul parlait ainsi pour sa défense, Festus dit d\'une voix forte: Tu as perdu le sens, Paul! Ton grand savoir te met hors de sens.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 25, 'Paul reprit: Je n\'ai pas perdu le sens, excellent Festus; ce sont des paroles de vérité et de raison que je prononce.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 26, 'Le roi est bien informé de ces faits; voilà pourquoi je lui parle avec confiance, car je suis persuadé qu\'il n\'en ignore aucun. Tout cela ne s\'est pas fait en cachette.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 27, 'Roi Agrippa, crois-tu aux prophètes? Je sais que tu y crois!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 28, 'Agrippa répondit à Paul: Tu vas bientôt me persuader de devenir chrétien!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 29, 'Paul reprit: Plût à Dieu que, tôt ou tard, non seulement toi, mais tous ceux qui m\'écoutent aujourd\'hui, vous devinssiez tels que je suis, à l\'exception de ces liens!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 30, 'Alors le roi se leva, ainsi que le gouverneur, Bérénice, et ceux qui étaient assis avec eux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 31, 'Puis s\'étant retirés, ils se disaient entre eux: Il n\'y a, dans la conduite de cet homme, rien qui mérite la mort ou la prison.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 32, 'Agrippa dit à Festus: Cet homme aurait pu être relâché, s\'il n\'en eût appelé à César.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 1, 'Quand il fut décidé que nous irions par mer en Italie, on remit Paul et quelques autres prisonniers à un centenier nommé Julius, de la cohorte Augusta.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 2, 'Étant montés sur un navire d\'Adramytte, qui devait longer les côtes de l\'Asie, nous partîmes. Aristarque, Macédonien de Thessalonique, était avec nous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 3, 'Le jour suivant, nous arrivâmes à Sidon; et Julius, qui traitait Paul avec humanité, lui permit d\'aller voir ses amis et de recevoir leurs soins.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 4, 'Puis, étant partis de là, nous suivîmes les côtes de l\'île de Chypre, parce que les vents étaient contraires.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 5, 'Après avoir traversé la mer de Cilicie et de Pamphylie, nous arrivâmes à Myra, en Lycie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 6, 'Là, le centenier trouva un navire d\'Alexandrie, qui allait en Italie, et sur lequel il nous fit monter.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 7, 'Après plusieurs jours d\'une navigation lente et pénible, nous arrivâmes vis-à-vis de Cnide. Le vent ne nous permettant pas d\'aborder, nous suivîmes les côtes de l\'île de Crète, vers Salmone.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 8, 'Après l\'avoir longée, non sans difficulté, nous vînmes à un endroit appelé Beaux-Ports, près de la ville de Lasée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 9, 'Comme il s\'était écoulé beaucoup de temps, et que la navigation devenait dangereuse — l\'époque du Jeûne étant déjà passée — Paul fit entendre ces paroles d\'avertissement:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 10, 'Je vois que la navigation ne se fera pas sans péril et sans de graves dommages, non seulement pour la cargaison et le bâtiment, mais aussi pour nos personnes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 11, 'Mais le centenier se fiait plutôt au pilote et au capitaine du navire, qu\'à ce que Paul disait.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 12, 'Comme le port n\'était pas bon pour hiverner, la plupart furent d\'avis d\'en repartir et de tâcher de gagner Phénix, port de la Crète, qui regarde le Sud-Ouest et le Nord-Ouest, pour y passer l\'hiver.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 13, 'Une brise du Sud s\'étant mise à souffler, ils crurent qu\'ils exécuteraient à leur gré leur dessein, et, ayant levé l\'ancre, ils côtoyèrent de près l\'île de Crète.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 14, 'Bientôt après, un vent furieux, appelé Euraquilon, vint s\'abattre sur l\'île.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 15, 'Le navire se trouva entraîné, sans pouvoir résister à l\'ouragan, et nous nous laissâmes aller à la dérive.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 16, 'Ayant été poussés au-dessous d\'une petite île, appelée Clauda, nous parvînmes avec peine à nous rendre maîtres de la chaloupe.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 17, 'Après l\'avoir hissée, on prit des mesures de sûreté. On lia le navire par-dessous avec des cordes; puis, dans la crainte d\'échouer sur les bancs de la Syrte, on amena les voiles, et on se laissa ainsi emporter par le vent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 18, 'Le lendemain, la tempête étant toujours aussi forte, on jeta la cargaison à la mer.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 19, 'Le troisième jour, nous jetâmes de nos propres mains les agrès du navire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 20, 'Pendant plusieurs jours, ni le soleil, ni les étoiles ne se montrèrent, et la tempête restait toujours si violente que nous perdîmes toute espérance de nous sauver.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 21, 'Comme il y avait longtemps qu\'on n\'avait mangé, Paul se leva au milieu d\'eux et leur dit: Mes amis, il aurait fallu me croire, et ne pas partir de Crète; nous aurions évité ce péril et cette perte.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 22, 'Mais maintenant, je vous exhorte à prendre courage; aucun de nous ne périra, et il n\'y aura de perte que celle du navire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 23, 'Cette nuit, en effet, un ange du Dieu à qui je suis et que je sers, m\'est apparu');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 24, 'et m\'a dit: Paul, ne crains point; il faut que tu comparaisses devant César; et voici que Dieu t\'a donné tous ceux qui naviguent avec toi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 25, 'C\'est pourquoi, mes amis, ayez bon courage, car j\'ai cette confiance en Dieu, qu\'il en sera comme il m\'a été dit;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 26, 'mais il faut que nous soyons jetés sur quelque île.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 27, 'C\'était déjà la quatorzième nuit que nous étions ballottés sur l\'Adriatique, quand vers minuit, les matelots estimèrent qu\'ils approchaient de quelque terre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 28, 'Ayant jeté la sonde, ils trouvèrent vingt brasses; un peu plus loin, ils la jetèrent encore, et trouvèrent quinze brasses.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 29, 'Alors, craignant de donner contre des écueils, ils jetèrent quatre ancres du haut de la poupe, et ils appelaient de leurs voeux la venue du jour.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 30, 'Mais, comme les matelots cherchaient à s\'échapper du navire et mettaient la chaloupe à la mer, sous prétexte de jeter des ancres du côté de la proue,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 31, 'Paul dit au centenier: Si ces hommes ne restent pas à bord, vous ne pouvez être sauvés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 32, 'Alors les soldats coupèrent les cordes de la chaloupe et la laissèrent tomber.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 33, 'Puis, en attendant que le jour vînt, Paul les exhorta tous à prendre de la nourriture. Voici, leur dit-il, le quatorzième jour que vous êtes dans l\'attente, et que vous restez à jeun, sans rien manger.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 34, 'Je vous exhorte donc à prendre de la nourriture; car cela est nécessaire à votre salut. Aucun d\'entre vous ne perdra un cheveu de sa tête!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 35, 'Ayant ainsi parlé, il prit du pain; il rendit grâces à Dieu, en présence de tous; puis il le rompit et se mit à manger.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 36, 'Tous alors, reprenant courage, mangèrent aussi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 37, 'Or, nous étions en tout deux cent soixante seize personnes à bord.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 38, 'Quand ils se furent rassasiés, ils allégèrent le navire en jetant les provisions à la mer.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 39, 'Le jour venu, ils ne reconnaissaient pas la terre; mais, ayant aperçu un golfe avec une plage, ils résolurent d\'y mettre, si possible, le navire à l\'abri.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 40, 'Ils coupèrent donc les câbles des ancres qu\'ils abandonnèrent à la mer, et ils lâchèrent les amarres des gouvernails; puis, ayant mis au vent la voile d\'artimon, ils tâchèrent de gagner le rivage.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 41, 'Mais, étant tombés sur un endroit battu par la mer, des deux côtés, ils y firent échouer le navire; et, tandis que la proue enfoncée restait immobile, la poupe était brisée par la violence des vagues.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 42, 'Alors les soldats furent d\'avis de tuer les prisonniers, de peur que l\'un d\'eux ne vînt à s\'échapper à la nage.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 43, 'Mais le centenier, voulant sauver Paul, les empêcha d\'exécuter leur dessein. Il ordonna à ceux qui savaient nager de se jeter à l\'eau les premiers et de gagner la terre,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 44, 'et à ceux qui restaient, de se mettre, les uns sur des planches, les autres sur quelques débris du navire. C\'est ainsi que tous parvinrent à terre, sains et saufs.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 1, 'Après avoir été ainsi sauvés, nous apprîmes que l\'île s\'appelait Malte.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 2, 'Les indigènes nous témoignèrent une humanité peu commune; ils nous recueillirent tous auprès d\'un grand feu qu\'ils avaient allumé, parce que la pluie tombait et qu\'il faisait froid.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 3, 'Paul ayant ramassé une brassée de bois sec et l\'ayant jetée dans le feu, une vipère en sortit à cause de la chaleur, et s\'attacha à sa main.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 4, 'Quand les indigènes virent l\'animal qui pendait à sa main, ils se dirent les uns aux autres: Certainement, cet homme est un meurtrier; car, après qu\'il a été sauvé de la mer, la justice divine ne permet pas qu\'il vive!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 5, 'Mais Paul, ayant secoué la vipère dans le feu, ne ressentit aucun mal.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 6, 'Les indigènes s\'attendaient à le voir enfler ou tomber mort tout d\'un coup; mais, après avoir longtemps attendu, voyant qu\'il ne lui arrivait aucun mal, ils changèrent de sentiment et dirent que c\'était un dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 7, 'Il y avait, dans cet endroit-là, des terres appartenant au premier personnage de l\'île, nommé Publius; celui-ci nous reçut de la façon la plus hospitalière pendant trois jours.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 8, 'Or, le père de ce Publius était au lit, malade de la fièvre et de la dysenterie. Paul alla le voir; et, ayant prié, il lui imposa les mains et le guérit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 9, 'Là-dessus, tous les autres habitants de l\'île qui se trouvaient malades, vinrent à lui, et ils furent guéris.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 10, 'Aussi nous rendirent-ils de grands honneurs; et, à notre départ, ils nous fournirent ce qui nous était nécessaire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 11, 'Trois mois après, nous partîmes sur un navire d\'Alexandrie, qui avait passé l\'hiver dans l\'île, et qui avait pour enseigne les Dioscures.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 12, 'Arrivés à Syracuse, nous y demeurâmes trois jours.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 13, 'De là, en suivant la côte, nous atteignîmes Rhégium. Le lendemain, le vent du Midi s\'étant levé, nous vînmes en deux jours à Pouzzoles.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 14, 'Nous y trouvâmes des frères qui nous prièrent de demeurer avec eux sept jours; et ensuite nous allâmes à Rome.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 15, 'Les frères de cette ville, ayant entendu parler de nous, vinrent à notre rencontre jusqu\'au Forum d\'Appius et aux Trois-Tavernes. Paul, en les voyant, rendit grâces à Dieu et prit courage.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 16, 'Quand nous fûmes arrivés à Rome, Paul eut la permission de demeurer à part, avec un soldat qui le gardait.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 17, 'Trois jours après, il convoqua les principaux des Juifs. Quand ils furent réunis, il leur dit: Mes frères, quoique je n\'eusse rien fait ni contre le peuple, ni contre les coutumes de nos pères, j\'ai été arrêté à Jérusalem et livré entre les mains des Romains.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 18, 'Ceux-ci, après avoir examiné ma cause, voulaient me relâcher, parce que je n\'avais rien fait qui méritât la mort.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 19, 'Mais les Juifs s\'y étant opposés, j\'ai été contraint d\'en appeler à César, sans que j\'aie dessein néanmoins d\'accuser ma nation.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 20, 'C\'est pour ce motif que j\'ai demandé à vous voir et à vous parler; car c\'est à cause de l\'espérance d\'Israël que je suis chargé de cette chaîne.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 21, 'Ils lui répondirent: Nous n\'avons pas reçu de lettres de Judée à ton sujet; et aucun des frères n\'est venu faire un rapport ou dire du mal sur ton compte.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 22, 'Cependant, nous voudrions bien apprendre de toi ce que tu penses; car, pour ce qui est de cette secte, nous savons qu\'elle rencontre partout de l\'opposition.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 23, 'Ayant pris jour avec lui, ils vinrent en plus grand nombre le trouver dans son logis. Depuis le matin jusqu\'au soir, il rendait son témoignage; il les entretenait du royaume de Dieu, et il s\'efforçait de les persuader, par la loi de Moïse et par les prophètes, de ce qui concerne Jésus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 24, 'Les uns furent persuadés de ce qu\'il disait; les autres ne crurent point.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 25, 'Comme ils n\'étaient pas d\'accord entre eux et qu\'ils se retiraient, Paul n\'ajouta que ces mots: Elle était bien vraie la parole que l\'Esprit saint fit entendre à nos pères, par le moyen d\'Ésaïe, le prophète, quand il leur dit:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 26, '«Va vers ce peuple, et dis-lui: Vous entendrez de vos oreilles, et vous ne comprendrez point; vous regarderez de vos yeux, et vous ne verrez point.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 27, 'Car le coeur de ce peuple s\'est appesanti. Ils ont endurci leurs oreilles, et ils ont fermé leurs yeux de peur qu\'ils ne voient de leurs yeux qu\'ils n\'entendent de leurs oreilles qu\'ils ne comprennent de leur coeur qu\'ils ne se convertissent, et que je ne les guérisse»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 28, 'Sachez donc que ce salut de Dieu a été envoyé aux Païens ceux-là l\'écouteront.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 29, '[Lorsqu\'il eut dit cela, les Juifs s\'en allèrent, discutant vivement entre eux.]');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 30, 'Paul demeura deux ans entiers dans un logement qu\'il avait loué. Il recevait tous ceux qui venaient le voir,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 31, 'prêchant le royaume de Dieu, et enseignant ce qui concerne le Seigneur Jésus-Christ, avec une entière liberté et sans aucun empêchement.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 1, 'Paul, serviteur de Jésus-Christ, appelé à être apôtre, mis à part pour annoncer l\'Évangile de Dieu,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 2, '— Évangile que Dieu avait promis d\'avance par ses prophètes dans les saintes Écritures,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 3, 'et qui concerne son Fils né de la race de David, selon la chair,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 4, 'et déclaré avec puissance Fils de Dieu, selon l\'esprit de sainteté, par sa résurrection d\'entre les morts, Jésus-Christ notre Seigneur,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 5, 'par lequel nous avons reçu la grâce et l\'apostolat, afin d\'amener à l\'obéissance de la foi, pour la gloire de son nom, toutes les nations,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 6, 'dont vous faisiez partie, vous aussi, vous qui avez été appelés par Jésus-Christ. —');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 7, 'à tous les bien-aimés de Dieu qui sont à Rome, appelés à être saints. Que la grâce et la paix vous soient données de la part de Dieu, notre Père, et du Seigneur Jésus-Christ!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 8, 'Avant tout, je rends grâces à mon Dieu, par Jésus-Christ, au sujet de vous tous, de ce que votre foi est renommée dans le monde entier.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 9, 'Car Dieu, que je sers en mon esprit, par la prédication de l\'Évangile de son fils, m\'est témoin que je fais sans cesse mention de vous');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 10, 'dans toutes mes prières, demandant de pouvoir enfin, par la volonté de Dieu, trouver une occasion favorable d\'aller chez vous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 11, 'En effet, j\'ai un ardent désir de vous voir, pour vous communiquer quelque don spirituel, afin que vous soyez affermis,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 12, 'ou plutôt, afin que, me trouvant parmi vous, nous nous encouragions mutuellement par la foi qui nous est commune, à vous et à moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 13, 'Je ne veux pas, frères, vous laisser ignorer que j\'ai souvent formé le projet d\'aller vous voir, pour recueillir quelque fruit parmi vous comme parmi les autres nations; mais j\'en ai été empêché jusqu\'à présent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 14, 'Je me dois aux Grecs et aux Barbares, aux savants et aux ignorants.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 15, 'Ainsi, autant qu\'il dépend de moi, j\'ai à coeur de vous annoncer l\'Évangile, à vous aussi qui êtes à Rome.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 16, 'En effet, je n\'ai pas honte de l\'Évangile, — parce qu\'il est la puissance de Dieu pour le salut de tout croyant, du Juif premièrement, et aussi du Grec. —');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 17, 'Car, dans cet Évangile est révélée la justice de Dieu, qui s\'obtient par la foi et qui conduit à la foi, ainsi qu\'il est écrit: «Le juste vivra par la foi.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 18, 'La colère de Dieu, en effet, se révèle du ciel contre toute impiété et toute injustice des hommes, qui retiennent la vérité captive de l\'injustice.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 19, 'Car, ce que l\'on peut connaître de Dieu est devenu manifeste pour eux. Dieu le leur ayant manifesté,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 20, 'puisque ses perfections invisibles, sa puissance éternelle et sa divinité, se voient comme à l\'oeil depuis la création du monde, quand on les considère dans ses ouvrages. Aussi sont-ils inexcusables,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 21, 'parce que, tout en connaissant Dieu, ils ne lui ont pas donné la gloire qui appartient à Dieu, et ils ne lui ont pas rendu grâces; mais ils se sont égarés dans leurs vains raisonnements, et leur coeur sans intelligence a été rempli de ténèbres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 22, 'Se disant sages, ils sont devenus fous;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 23, 'ils ont remplacé la gloire du Dieu incorruptible par des images qui représentent l\'homme corruptible, des oiseaux, des quadrupèdes, des reptiles.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 24, 'C\'est pourquoi, Dieu les a livrés à l\'impureté, suivant les convoitises de leurs coeurs, en sorte qu\'ils déshonorent eux-mêmes leurs propres corps,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 25, 'eux qui ont changé la vérité de Dieu en mensonge, et qui ont adoré et servi la créature au lieu du Créateur, lequel est béni éternellement. Amen!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 26, 'C\'est pour cela que Dieu les a livrés à des passions honteuses; car, parmi eux, les femmes ont changé l\'usage naturel en un autre qui est contre nature.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 27, 'De même aussi, les hommes, laissant l\'usage naturel de la femme, se sont enflammés dans leurs désirs les uns pour les autres, commettant, homme avec homme, des infamies, et recevant en eux-mêmes le salaire dû à leur égarement.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 28, 'Comme ils ne se sont pas souciés de conserver la connaissance de Dieu, Dieu les a livrés à un esprit pervers, de sorte qu\'ils ont commis des actions indignes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 29, 'Ils sont remplis de toute espèce d\'injustice, de perversité, de cupidité, de méchanceté; pleins d\'envie, de meurtre, de dispute, de tromperie, de malignité;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 30, 'délateurs, médisants, impies, insolents, arrogants, vaniteux, ingénieux à faire le mal, désobéissants envers leurs parents;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 31, 'sans intelligence, sans loyauté, sans affection naturelle, sans pitié.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 32, 'Et, bien qu\'ils connaissent le décret de Dieu déclarant dignes de mort ceux qui commettent de telles actions, non seulement ils s\'en rendent coupables, mais encore ils approuvent ceux qui les commettent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 1, 'Toi donc, ô homme, qui que tu sois, qui juge les autres, tu es inexcusable; car, en les jugeant, tu te condamnes toi-même, puisque toi qui les juges, tu fais les mêmes choses.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 2, 'Or, nous savons que le jugement de Dieu contre ceux qui se rendent coupables de telles actions est conforme à la vérité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 3, 'Penses-tu donc, toi qui juges ceux qui commettent de tels actes et qui les commets, que tu échapperas toi-même au jugement de Dieu?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 4, 'Ou méprises-tu les richesses de sa bonté, de sa patience, de sa longanimité, et ne reconnais-tu pas que la bonté de Dieu te convie à la repentance?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 5, 'Par ton endurcissement et par l\'impénitence de ton coeur, tu t\'amasses un trésor de colère pour le jour de la colère et de la manifestation du juste jugement de Dieu,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 6, 'qui rendra à chacun selon ses oeuvres:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 7, 'la vie éternelle à ceux qui, en persévérant à faire le bien, cherchent la gloire, l\'honneur et l\'immortalité;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 8, 'mais à ceux qui, dans un esprit de contradiction, désobéissent à la vérité et obéissent à l\'injustice, — à eux la colère et l\'indignation!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 9, 'Oui, détresse et angoisse pour toute âme d\'homme qui fait le mal, pour le Juif d\'abord, et aussi pour le Grec;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 10, 'mais gloire, honneur et paix à tout homme qui fait le bien, au Juif d\'abord, et aussi au Grec!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 11, 'Car, devant Dieu, il n\'y a point d\'acception de personnes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 12, 'Tous ceux qui auront péché sans la loi, périront aussi sans la loi; et tous ceux qui auront péché ayant la loi, seront jugés par la loi;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 13, 'car ce ne sont pas ceux qui entendent lire la loi qui sont justes devant Dieu, mais ceux-là seuls qui pratiquent la loi seront justifiés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 14, 'En effet, quand les Païens, qui n\'ont pas la loi, font naturellement les choses que la loi commande, ces hommes, qui n\'ont pas la loi, se tiennent lieu de loi à eux-mêmes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 15, 'Ils font voir que l\'oeuvre commandée par la loi est écrite dans leurs coeurs: leur propre conscience en témoigne, et leurs pensées tantôt les accusent, tantôt même les défendent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 16, 'C\'est ce qui apparaîtra le jour où, selon mon Évangile, Dieu jugera par Jésus-Christ les actions secrètes des hommes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 17, 'Mais toi, qui portes le nom de Juif, qui te reposes sur la loi, qui te glorifies de ton Dieu,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 18, 'toi qui connais sa volonté et qui sais discerner la différence des choses, instruit que tu es par la loi;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 19, 'toi qui te flattes d\'être le conducteur des aveugles, la lumière de ceux qui sont dans les ténèbres,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 20, 'le docteur des ignorants, le maître des simples, ayant dans la loi la règle de la connaissance et de la vérité,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 21, 'toi donc qui enseignes les autres, tu ne t\'enseignes pas toi-même!!- Toi, qui prêches qu\'on ne doit pas dérober, tu dérobes!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 22, 'Toi, qui dis qu\'il ne faut pas commettre d\'adultère, tu commets l\'adultère! Toi, qui as en abomination les idoles, tu t\'empares de leurs dépouilles!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 23, 'Toi, qui te glorifies de la loi, tu déshonores Dieu par la transgression de la loi!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 24, 'En effet, «le nom de Dieu est blasphémé à cause de vous parmi les nations», — comme dit l\'Ecriture.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 25, 'Sans doute, la circoncision est utile, si tu pratiques la loi; mais si tu transgresses la loi, tu n\'es plus, avec ta circoncision, qu\'un incirconcis.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 26, 'Si donc l\'incirconcis observe les commandements de la loi, son incirconcision ne sera-t-elle pas tenue pour circoncision?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 27, 'Et celui qui, tout en restant incirconcis, accomplit cependant la loi, te jugera, toi qui, avec la lettre de la loi et la circoncision, es transgresseur de la loi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 28, 'Car celui-là n\'est pas Juif, qui ne l\'est qu\'au dehors, et la circoncision n\'est pas celle qui se fait extérieurement dans la chair;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 29, 'mais celui-là est Juif qui l\'est au dedans, et la vraie circoncision est celle du coeur, faite selon l\'esprit, et non selon la lettre. Un tel Juif tire sa louange, non pas des hommes, mais de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 1, 'Quelle est donc la prérogative du Juif, ou quelle est l\'utilité de la circoncision?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 2, 'Elle est grande à tous égards. Et tout d\'abord en ceci: c\'est aux Juifs que les oracles de Dieu ont été confiés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 3, 'Eh quoi! Si quelques-uns d\'entre eux ont été infidèles, leur infidélité anéantira-t-elle la fidélité de Dieu?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 4, 'Non certes! Dieu doit être reconnu vrai, et tout homme menteur, comme il est écrit: «C\'est ainsi que tu seras trouvé juste dans tes paroles, et que tu gagneras ta cause quand on te jugera.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 5, 'Mais alors, si notre injustice fait éclater la justice de Dieu, que dirons-nous? Dieu est-il injuste — je parle ici comme les hommes — quand il déploie sa colère? —');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 6, 'Non certes! Autrement comment Dieu jugerait-il le monde?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 7, 'Cependant, si la vérité de Dieu reçoit une plus grande gloire par mon mensonge, pourquoi suis-je encore jugé comme pécheur? —');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 8, 'Alors, pourquoi ne ferions-nous pas le mal pour qu\'il en arrive du bien, ainsi que des calomniateurs nous en accusent et comme ils prétendent que nous l\'enseignons? La condamnation de ces hommes-là est juste!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 9, 'Quoi donc! Avons-nous quelque chose à faire valoir en notre faveur? Nullement, car nous avons déjà prouvé que tous, Juifs et Grecs, sont sous l\'empire du péché,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 10, 'ainsi qu\'il est écrit: «Il n\'y a point de juste, pas même un seul.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 11, 'Il n\'y en a pas un seul qui soit intelligent; il n\'y en a pas un qui cherche Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 12, 'Ils se sont tous égarés, ils se sont pervertis tous ensemble; il n\'y en a point qui fasse le bien, non pas même un seul.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 13, 'Leur gosier est un sépulcre ouvert; ils se sont servis de leurs langues pour tromper; il y a un venin d\'aspic sous leurs lèvres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 14, 'Leur bouche est pleine de malédiction et d\'amertume.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 15, 'Ils ont les pieds légers pour répandre le sang.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 16, 'La destruction et la ruine sont sur leurs sentiers,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 17, 'et ils n\'ont point connu le chemin de la paix.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 18, 'La crainte de Dieu n\'est pas devant leurs yeux.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 19, 'Or, nous savons que tout ce que la loi dit, elle l\'adresse à ceux qui sont sous la loi, afin que toute bouche soit fermée, et que le monde entier soit reconnu coupable devant Dieu;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 20, 'car aucun homme ne sera justifié devant lui par les oeuvres de la loi, puisque c\'est la loi qui donne la connaissance du péché.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 21, 'Mais maintenant, c\'est indépendamment de la loi que la justice de Dieu a été manifestée, la loi et les prophètes lui rendant témoignage:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 22, 'la justice de Dieu, par la foi en Jésus-Christ, pour tous ceux qui croient. Il n\'y a point de distinction;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 23, 'car tous ont péché et sont privés de la gloire de Dieu,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 24, 'et ils sont justifiés gratuitement par sa grâce, au moyen de la rédemption accomplie en Jésus-Christ,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 25, 'que Dieu a établi comme victime expiatoire, par la foi en son sang. Il a ainsi manifesté sa justice, parce qu\'il avait laissé impunis les péchés commis auparavant, au temps de sa patience;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 26, 'il a, dis-je, manifesté sa justice dans le temps présent, faisant voir qu\'il est juste et qu\'il justifie celui qui croit en Jésus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 27, 'Où est donc le sujet de se glorifier? Il est exclu. Par quelle loi? Celle des oeuvres? Non, par la loi de la foi;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 28, 'car nous estimons que l\'homme est justifié par la foi, sans les oeuvres de la loi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 29, 'Ou bien, Dieu est-il seulement le Dieu des Juifs? N\'est-il pas aussi le Dieu des Païens? Oui, il l\'est aussi des Païens,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 30, '— puisqu\'il y a un seul Dieu, qui justifiera par la loi les circoncis et, au moyen de la foi également, les incirconcis.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 31, 'Anéantissons-nous donc la loi par la foi? Non certes! Au contraire, nous confirmons la loi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 1, 'Quel avantage dirons-nous donc qu\'Abraham, notre père, a obtenu selon la chair?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 2, 'Sans doute, si Abraham a été justifié par les oeuvres, il a sujet de se glorifier; mais devant Dieu, il n\'en est pas ainsi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 3, 'En effet, que dit l\'Écriture? «Abraham, dit-elle, crut à Dieu, et cela lui fut imputé à justice.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 4, 'Or, celui qui fait une oeuvre, reçoit son salaire non pas comme une grâce, mais comme une chose due;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 5, 'tandis que, pour celui qui ne fait point d\'oeuvre, mais qui croit en celui qui justifie l\'impie, sa foi lui est imputée à justice.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 6, 'C\'est ainsi que David exprime le bonheur de l\'homme à qui Dieu impute la justice sans les oeuvres:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 7, '«Heureux ceux dont les iniquités sont pardonnées, et dont les péchés sont couverts!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 8, 'Heureux l\'homme à qui le Seigneur n\'impute point son péché!.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 9, 'Cette déclaration de bonheur ne concerne-t-elle donc que les circoncis? Elle est également pour les incirconcis. Nous disons, en effet, que la foi d\'Abraham lui fut imputée à justice.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 10, 'Or, comment lui fut-elle imputée? Alors qu\'il était circoncis, ou lorsqu\'il ne l\'était pas encore? Ce n\'a pas été après, mais avant sa circoncision.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 11, 'Puis il reçut le signe de la circoncision, comme un sceau de la justice qu\'il avait obtenue par la foi, quand il était encore incirconcis, afin qu\'il fût le père de tous ceux qui ont la foi bien qu\'étant incirconcis, pour que la justice leur soit imputée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 12, 'Il est aussi le père des circoncis, de ceux qui n\'ont pas seulement reçu la circoncision, mais qui marchent sur les traces de la foi qu\'avait Abraham, notre père, avant sa circoncision.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 13, 'En effet, la promesse d\'avoir le monde pour héritage fut faite à Abraham ou à sa postérité, non pas en vertu de la loi, mais en vertu de la justice de la foi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 14, 'Car, si c\'est de la loi que vient l\'héritage, la foi est rendue vaine, et la promesse est annulée,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 15, 'parce que la loi produit la colère. Mais où il n\'y a point de loi, il n\'y a pas non plus de transgression.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 16, 'C\'est donc par la foi qu\'on devient héritier, afin que ce soit par grâce, et que la promesse soit assurée à toute la postérité d\'Abraham, non seulement à celle qui est sous la loi, mais aussi à celle qui possède la foi d\'Abraham, notre Père à tous, selon ce qui est écrit:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 17, '«Je t\'ai établi père de beaucoup de nations» — notre père, dis-je, devant Dieu, en qui il a cru, qui donne la vie aux morts, et qui appelle les choses qui ne sont point comme si elles étaient.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 18, 'Espérant contre toute espérance, il crut, et il devint ainsi le père de beaucoup de nations, selon ce qui lui avait été dit; «Telle sera ta postérité.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 19, 'Il vit, sans faiblir dans sa foi, que son corps était usé, puisqu\'il avait près de cent ans, et que Sara n\'était plus en âge d\'avoir des enfants.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 20, 'Il n\'eut ni hésitation ni défiance à l\'égard de la promesse de Dieu, mais il fut fortifié dans sa foi, et il donna gloire à Dieu,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 21, 'étant pleinement persuadé que ce que Dieu a promis, il a aussi la puissance de l\'accomplir.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 22, 'C\'est pourquoi, sa foi lui fut imputée à justice.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 23, 'Or, ce n\'est pas pour lui seul qu\'il est écrit que sa foi lui fut imputée à justice,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 24, 'mais c\'est aussi pour nous, à qui notre foi doit être pareillement imputée; pour nous, qui croyons en Celui qui a ressuscité d\'entre les morts Jésus, notre Seigneur,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 25, 'qui a été livré pour nos offenses et qui est ressuscité pour notre justification.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 1, 'Étant donc justifiés par la foi, nous avons la paix avec Dieu, par notre Seigneur Jésus-Christ,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 2, 'qui nous a fait aussi avoir accès, par la foi, à cette grâce dans laquelle nous demeurons fermes; et nous nous glorifions dans l\'espérance de la gloire de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 3, 'Bien plus encore, nous nous glorifions même dans les afflictions, sachant que l\'affliction produit la patience,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 4, 'la patience la fidélité éprouvée, et la fidélité éprouvée, l\'espérance.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 5, 'Or, l\'espérance ne rend pas confus, parce que l\'amour de Dieu a été répandu dans nos coeurs par le Saint-Esprit, qui nous a été donné.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 6, 'En effet, lorsque nous étions encore sans force, Christ, au temps marqué, est mort pour des impies.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 7, 'Or, à peine voudrait-on mourir pour un juste; peut-être cependant, pour un homme de bien, quelqu\'un se résoudrait-il à mourir.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 8, 'Mais Dieu a fait éclater son amour envers nous en ce que, quand nous étions encore des pécheurs, Christ est mort pour nous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 9, 'Combien plus, étant maintenant justifiés par son sang, serons-nous sauvés par lui de la colère!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 10, 'Car si, lorsque nous étions les ennemis de Dieu, nous avons été réconciliés avec lui par la mort de son Fils, combien plus, étant réconciliés, serons-nous sauvés par sa vie!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 11, 'Bien plus, nous nous glorifions en Dieu par notre Seigneur Jésus-Christ, par lequel nous avons maintenant obtenu la réconciliation.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 12, 'C\'est pourquoi, comme, par un seul homme, le péché est entré dans le monde, et par le péché la mort, — et qu\'ainsi la mort a passé sur tous les hommes, parce que tous ont péché.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 13, 'En effet, avant la loi, le péché était dans le monde; mais le péché n\'est pas imputé, quand il n\'y a point de loi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 14, 'Cependant la mort a régné, depuis Adam jusqu\'à Moïse, même sur ceux qui n\'avaient pas péché par une transgression semblable à celle d\'Adam, lequel est l\'image de Celui qui devait venir.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 15, 'Mais il n\'en est pas du don de la grâce comme de la faute. Car si, par la faute d\'un seul, tous les autres sont morts, combien plus la grâce de Dieu et le don qu\'il nous a fait, dans sa grâce, par un seul homme, Jésus-Christ, — ont-ils abondé pour tous les autres!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 16, 'Et il n\'en est pas de ce don comme des suites du péché commis par un seul homme: par suite d\'une seule faute, le jugement a entraîné la condamnation; mais le don de la grâce, après un grand nombre de fautes, conduit à la justification.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 17, 'En effet, si, par la faute d\'un seul, la mort a régné par ce seul homme, combien plus ceux qui reçoivent dans toute leur abondance la grâce et le don de la justice, régneront-ils dans la vie par un seul, Jésus-Christ!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 18, 'Ainsi donc, de même que, par une seule faute, la condamnation s\'étend à tous les hommes, de même, par un seul acte de justice, la justification qui donne la vie s\'étend aussi à tous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 19, 'Car de même que, par la désobéissance d\'un seul homme, tous les autres ont été rendus pécheurs, ainsi, par l\'obéissance d\'un seul, tous les autres seront rendus justes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 20, 'Or, la loi est intervenue, afin que la faute abondât; mais, où le péché a abondé, la grâce a surabondé,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 21, 'afin que, comme le péché a régné en donnant la mort, ainsi la grâce régnât par la justice, pour donner la vie éternelle par Jésus-Christ, notre Seigneur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 1, 'Que dirons-nous donc? Que nous devons demeurer dans le péché, afin que la grâce abonde?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 2, 'Non certes! Nous qui sommes morts au péché, comment vivrions-nous encore dans le péché?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 3, 'Ou bien, ignorez-vous que nous tous, qui avons été baptisés en Jésus-Christ, nous avons été baptisés en sa mort?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 4, 'Nous avons donc été ensevelis avec lui par le baptême en sa mort, afin que, comme Christ est ressuscité des morts par la gloire du Père, de même, nous aussi, nous vivions d\'une vie nouvelle.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 5, 'Car si nous sommes devenus une même plante avec lui par une mort qui ressemble à la sienne, nous le serons aussi par une résurrection semblable,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 6, 'sachant bien que notre vieil homme a été crucifié avec lui, afin que ce corps de péché soit détruit et que nous ne soyons plus asservis au péché.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 7, 'Car celui qui est mort est libéré du péché.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 8, 'Or, si nous sommes morts avec Christ, nous croyons que nous vivrons aussi avec lui,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 9, 'puisque nous savons que Christ, ressuscité des morts, ne meurt plus: la mort n\'a plus d\'empire sur lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 10, 'Car, s\'il est mort, il est mort pour le péché une fois pour toutes; mais maintenant qu\'il est vivant, il est vivant pour Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 11, 'Vous donc aussi, considérez-vous comme morts pour le péché et comme vivants pour Dieu, en Jésus-Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 12, 'Que le péché ne règne donc point dans votre corps mortel, et n\'obéissez pas à ses convoitises.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 13, 'Ne livrez pas vos membres au péché, comme des instruments d\'iniquité; mais donnez-vous vous-mêmes à Dieu, comme étant devenus vivants, de morts que vous étiez, et offrez vos membres à Dieu comme des instruments de justice.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 14, 'Car le péché ne dominera point sur vous, parce que vous n\'êtes plus sous la loi, mais sous la grâce.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 15, 'Quoi donc! Pécherions-nous, parce que nous ne sommes pas sous la loi, mais sous la grâce?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 16, 'Non certes! Ne savez-vous pas que si vous vous livrez à quelqu\'un comme esclaves pour lui obéir, vous êtes les esclaves de celui à qui vous obéissez, soit du péché pour la mort, soit de l\'obéissance pour la justice?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 17, 'Or, grâces soient rendues à Dieu de ce que, après avoir été esclaves du péché, vous avez obéi de coeur à la doctrine qui vous a été donnée pour règle');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 18, 'Étant donc affranchis du péché, vous êtes devenus les esclaves de la justice.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 19, '— Je parle à la manière des hommes, à cause de la faiblesse de votre chair! — Ainsi, de même que vous avez mis vos membres au service de l\'impureté et de l\'iniquité, pour commettre l\'iniquité, de même, maintenant, mettez vos membres au service de la justice, pour votre sanctification.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 20, 'En effet, lorsque vous étiez esclaves du péché, vous étiez libres à l\'égard de la justice.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 21, 'Quels fruits portiez-vous donc alors? Des fruits dont maintenant vous avez honte! Car la fin de ces choses-là, c\'est la mort.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 22, 'Mais maintenant, affranchis du péché et devenus les esclaves de Dieu, vous avez pour fruit la sanctification et pour fin la vie éternelle.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 23, 'Car le salaire du péché, c\'est la mort; mais le don de Dieu, c\'est la vie éternelle en Jésus-Christ, notre Seigneur!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 1, 'Ignorez-vous donc, frères, — car je parle à des gens qui connaissent la loi — que la loi n\'a d\'autorité sur une personne, qu\'aussi longtemps que celle-ci est en vie?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 2, 'Ainsi, la femme mariée est liée par la loi à son mari, tant qu\'il est vivant; mais si le mari vient à mourir, elle est dégagée de la loi qui la liait à lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 3, 'Si donc, du vivant de son mari, elle devient la femme d\'un autre, elle sera appelée adultère; mais si le mari meurt, elle est affranchie de la loi, de sorte qu\'elle n\'est point adultère en devenant la femme d\'un autre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 4, 'De même, mes frères, vous aussi, vous êtes morts à la loi, par le sacrifice du corps de Christ, pour appartenir à un autre, à celui qui est ressuscité des morts afin que nous portions des fruits pour Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 5, 'En effet, lorsque nous vivions selon la chair, les passions mauvaises, excitées par la loi, agissaient dans nos membres et produisaient des fruits pour la mort.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 6, 'Mais maintenant, étant morts à cette loi qui nous tenait captifs, nous en sommes affranchis, pour servir Dieu sous le régime nouveau de l\'Esprit, et non sous le régime vieilli de la lettre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 7, 'Que dirions-nous donc? La loi est-elle une puissance de péché? Non certes! Mais je n\'ai connu le péché que par la loi; car je n\'aurais pas connu la convoitise, si la loi n\'eût dit: «Tu ne convoiteras point!»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 8, 'C\'est le péché qui, ayant saisi l\'occasion, a produit en moi, par le commandement, toutes sortes de convoitises; car, sans la loi, le péché est mort.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 9, 'Autrefois, j\'étais sans loi, et je vivais, mais quand le commandement est venu, le péché a repris vie, et moi, je suis mort, —');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 10, 'de sorte qu\'il s\'est trouvé que le commandement, qui devait me donner la vie, m\'a conduit à la mort.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 11, 'Car le péché, ayant saisi l\'occasion, m\'a séduit par le commandement même, et par lui m\'a fait mourir.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 12, 'Ainsi, la loi est sainte, et le commandement est saint, juste et bon.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 13, 'Ce qui est bon est-il donc devenu pour moi une cause de mort? Non certes! Mais c\'est le péché qui m\'a fait mourir, afin qu\'il se manifestât comme péché, en me donnant la mort par ce qui est bon; en sorte que, par le moyen du commandement, le péché a atteint son dernier degré de gravité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 14, 'Nous savons, en effet, que la loi est spirituelle; mais moi, je suis charnel, vendu et asservi au péché.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 15, 'Car je ne comprends pas ce que je fais: je ne fais pas ce que je veux, mais je fais ce que je hais.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 16, 'Or, si je fais ce que je ne veux pas, je reconnais par là que la loi est bonne.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 17, 'Et alors, ce n\'est plus moi qui agis ainsi, mais c\'est le péché qui habite en moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 18, 'En effet, je sais que ce qui est bon n\'habite point en moi, c\'est-à-dire dans ma chair, parce que j\'ai la volonté de faire le bien, mais je n\'ai pas le pouvoir de l\'accomplir;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 19, 'car je ne fais pas le bien que je veux, mais je fais le mal que je ne veux pas.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 20, 'Si je fais ce que je ne veux pas, ce n\'est plus moi qui agis ainsi, mais c\'est le péché qui habite en moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 21, 'Je trouve donc en moi cette loi: Quand je veux faire le bien, le mal est attaché à moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 22, 'Car, dans mon être intime, je prends plaisir à la loi de Dieu;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 23, 'mais je vois dans mes membres une autre loi qui combat contre la loi de mon entendement, et qui me rend captif de la loi du péché, qui se trouve dans mes membres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 24, 'Misérable que je suis! Qui me délivrera de ce corps de mort?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 25, 'Grâces soient rendues à Dieu par Jésus-Christ, notre Seigneur! Ainsi donc, je suis moi-même assujetti, par l\'entendement, à la loi de Dieu, mais, par la chair, à la loi du péché.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 1, 'Il n\'y a donc maintenant aucune condamnation pour ceux qui sont en Jésus-Christ,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 2, 'parce que la loi de l\'esprit de vie m\'a affranchi, en Jésus-Christ, de la loi du péché et de la mort.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 3, 'Car ce qui était impossible à la loi, attendu que la chair la rendait impuissante. Dieu l\'a fait! En envoyant, à cause du péché, son propre Fils dans une chair semblable à notre chair de péché, il a condamné le péché dans la chair,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 4, 'afin que la justice prescrite par la loi fût accomplie en nous, qui marchons non selon la chair, mais selon l\'esprit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 5, 'En effet, ceux qui vivent selon la chair s\'attachent aux choses de la chair; mais ceux qui vivent selon l\'esprit, s\'attachent aux choses de l\'esprit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 6, 'Or, les sentiments que fait naître la chair produisent la mort; mais les sentiments que fait naître l\'esprit produisent la vie et la paix.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 7, 'L\'attachement à la chair, en effet, est inimitié contre Dieu; car la chair ne se soumet pas à la loi de Dieu, et même elle ne le peut pas.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 8, 'Or, ceux qui vivent selon la chair ne peuvent plaire à Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 9, 'Pour vous, vous ne vivez pas selon la chair, mais selon l\'esprit, s\'il est vrai que l\'Esprit de Dieu habite en vous; mais si quelqu\'un n\'a pas l\'esprit de Christ, il n\'est point à lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 10, 'Si donc Christ est en vous, le corps est mort à cause du péché, mais l\'esprit est vivant à cause de la justice.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 11, 'Et si l\'Esprit de Celui qui a ressuscité Jésus d\'entre les morts habite en vous, Celui qui a ressuscité Jésus-Christ d\'entre les morts rendra aussi la vie à vos corps mortels, par son Esprit qui habite en vous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 12, 'Ainsi donc, frères, nous ne sommes point redevables à la chair, pour vivre selon la chair.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 13, 'En effet, si vous vivez selon la chair, vous devez mourir; mais si, par l\'esprit, vous faites mourir les oeuvres du corps, vous vivrez.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 14, 'Car tous ceux qui sont conduits par l\'Esprit de Dieu, sont fils de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 15, 'Aussi bien, vous n\'avez pas reçu un esprit de servitude pour être encore dans la crainte; mais vous avez reçu l\'esprit d\'adoption, par lequel nous crions: Abba, c\'est-à-dire: Père!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 16, 'L\'Esprit lui-même rend témoignage à notre esprit que nous sommes enfants de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 17, 'Et si nous sommes enfants, nous sommes aussi héritiers: héritiers de Dieu et cohéritiers de Christ, si toutefois nous souffrons avec lui, afin que nous soyons aussi glorifiés avec lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 18, 'Or, j\'estime qu\'il n\'y a aucune proportion entre les souffrances du temps présent et la gloire à venir qui doit être manifestée en nous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 19, 'En effet, la création attend, avec un ardent désir, que les enfants de Dieu soient manifestés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 20, 'Car la création a été assujettie à la vanité, non pas volontairement, mais à cause de celui qui l\'y a assujettie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 21, 'Et elle espère qu\'elle aussi sera délivrée de la servitude de la corruption, pour avoir part à la liberté glorieuse des enfants de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 22, 'Car nous savons que, jusqu\'à ce jour, toute la création ensemble soupire, et qu\'elle est comme en travail;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 23, 'et non seulement elle, mais nous, qui avons reçu les prémices de l\'Esprit, nous soupirons, nous aussi, en nous-mêmes, attendant l\'adoption, la rédemption de notre corps.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 24, 'En effet, c\'est en espérance que nous sommes sauvés; or, quand on voit ce qu\'on espérait, ce n\'est plus de l\'espérance: ce que l\'on voit, pourquoi l\'espérer encore?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 25, 'Mais si nous espérons ce que nous ne voyons pas, nous l\'attendons avec patience.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 26, 'De même aussi, l\'Esprit vient en aide à notre faiblesse. Car nous ne savons pas ce que nous devons demander, pour prier comme il faut; mais l\'Esprit lui-même intercède pour nous par des soupirs inexprimables.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 27, 'Et Celui qui sonde les coeurs sait quelle est la pensée de l\'Esprit, parce que c\'est selon Dieu qu\'il intercède en faveur des saints.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 28, 'Or, nous savons que toutes choses concourent au bien de ceux qui aiment Dieu, de ceux qui sont appelés, selon le dessein qu\'il en avait formé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 29, 'Car ceux qu\'il a connus d\'avance, il les a aussi prédestinés à être conformes à l\'image de son Fils, afin que celui-ci soit le premier-né de plusieurs frères.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 30, 'Et ceux qu\'il a prédestinés, il les a aussi appelés; ceux qu\'il a appelés, il les a aussi justifiés; et ceux qu\'il a justifiés, il les a aussi glorifiés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 31, 'Que dirons-nous donc après cela? Si Dieu est pour nous, qui sera contre nous?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 32, 'Lui qui n\'a point épargné son propre Fils, mais qui l\'a livré pour nous tous, comment ne nous donnera-t-il pas aussi toutes choses avec lui?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 33, 'Qui accusera les élus de Dieu? Dieu est celui qui les justifie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 34, 'Qui condamnera? Jésus-Christ est celui qui est mort; bien plus, il est ressuscité, il est à la droite de Dieu, et il intercède pour nous!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 35, 'Qui nous séparera de l\'amour du Christ? Sera-ce l\'affliction, ou l\'angoisse, ou la persécution, ou la faim, ou la nudité, ou le péril, ou l\'épée?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 36, 'Il est écrit, en effet: «Nous sommes tout le jour livrés à la mort à cause de toi; on nous regarde comme des brebis destinées à la boucherie.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 37, 'Mais voici que, dans toutes ces épreuves, nous sommes plus que vainqueurs par Celui qui nous a aimés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 38, 'Car je suis assuré que ni la mort, ni la vie, ni les anges, ni les dominations, ni les choses présentes, ni les choses à venir,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 39, 'ni les puissances, ni hauteur, ni profondeur, ni aucune autre créature ne pourra nous séparer de l\'amour que Dieu nous a témoigné en Jésus-Christ, notre Seigneur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 1, 'Je dis la vérité en Christ, je ne mens point, et ma conscience m\'en rend témoignage par le Saint-Esprit:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 2, 'j\'ai une grande tristesse et un continuel tourment dans le coeur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 3, 'Car je souhaiterais d\'être moi-même anathème, séparé de Christ, pour mes frères, mes parents selon la chair,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 4, 'qui sont Israélites, à qui appartiennent l\'adoption, la gloire, les alliances, la loi, le culte, les promesses;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 5, 'qui descendent des patriarches, et desquels est issu selon la chair le Christ, qui est au-dessus de tous. Dieu béni éternellement. Amen!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 6, 'Ce n\'est pas que la parole de Dieu soit restée sans effet. Car tous ceux qui descendent d\'Israël ne sont pas pour cela le vrai Israël.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 7, 'Pour être la postérité d\'Abraham, ils ne sont pas tous ses enfants; mais il est dit: «C\'est en Isaac que tu auras une postérité appelée de ton nom»,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 8, '— c\'est-à-dire que ce ne sont pas les enfants de la chair qui sont enfants de Dieu, mais ce sont les enfants de la promesse qui sont considérés comme la postérité d\'Abraham.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 9, 'En effet, c\'est une promesse que cette parole: «Je reviendrai en cette même saison, et Sara aura un fils»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 10, 'Et d\'autre part il en fut de même pour Rébecca, lorsqu\'elle eut conçu deux jumeaux d\'Isaac, notre père.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 11, 'En effet, lorsque les enfants n\'étaient pas encore nés et qu\'il n\'avaient fait ni bien, ni mal — afin que fût maintenu le dessein de Dieu, qui procède de son libre choix, et qui dépend non des oeuvres, mais de Celui qui appelle —');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 12, 'il fut dit à leur mère: «L\'aîné sera assujetti au plus jeune»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 13, '— conformément à ce qui est écrit:, «J\'ai aimé Jacob et j\'ai haï Ésaü.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 14, 'Que dirons-nous donc? Y a-t-il en Dieu de l\'injustice?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 15, 'Non certes! Car il dit à Moïse: «Je ferai miséricorde à qui je ferai miséricorde, et j\'aurai pitié de qui j\'aurai pitié.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 16, 'Cela ne vient donc ni de celui qui veut, ni de celui qui court, mais de Dieu qui fait miséricorde.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 17, 'Aussi l\'Écriture dit-elle à Pharaon: «Voici pourquoi je t\'ai suscité: c\'est pour montrer en toi ma puissance, et afin que mon nom soit annoncé par toute la terre.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 18, 'Ainsi donc, il fait miséricorde à qui il veut, et il endurcit qui il veut.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 19, 'Tu me diras: Pourquoi donc Dieu se plaint-il encore? Car qui peut résister à sa volonté?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 20, 'Mais plutôt, qui es-tu, toi, homme, pour contester avec Dieu? Le vase d\'argile dira-t-il à celui qui l\'a formé: Pourquoi m\'as-tu fait ainsi?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 21, 'Le potier n\'est-il pas maître de l\'argile, pour faire avec la même masse tel vase pour un usage honorable, et tel autre pour un usage vulgaire?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 22, 'Et qu\'y a-t-il à dire, si Dieu, voulant montrer sa colère et faire connaître sa puissance, a supporté, avec une grande longanimité, des vases de colère destinés à la perdition,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 23, 'afin de faire connaître aussi les richesses de sa gloire par les vases de miséricorde, qu\'il a d\'avance préparés pour la gloire?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 24, 'Je parle de nous, qu\'il a appelés non seulement du milieu des Juifs, mais aussi du milieu des Païens.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 25, 'C\'est ainsi qu\'il dit dans Osée: «J\'appellerai mon peuple celui qui n\'était pas mon peuple, et bien-aimée celle qui n\'était pas la bien-aimée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 26, 'Et il arrivera que dans le lieu où il leur avait été dit: Vous n\'êtes point mon peuple; là même ils seront appelés fils du Dieu vivant.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 27, 'Ésaïe, de son côté, s\'écrie en parlant d\'Israël: «Quand le nombre des enfants d\'Israël serait comme le sable de la mer, un reste seulement sera sauvé;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 28, 'car le Seigneur accomplira pleinement et promptement sa parole sur la terre.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 29, 'Et comme Ésaïe l\'a prédit: «Si le Seigneur des armées ne nous eût laissé un germe de notre race, nous serions devenus comme Sodome; nous aurions été semblables à Gomorrhe.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 30, 'Que dirons-nous donc? Que les Païens, qui ne cherchaient pas la justice, ont obtenu la justice, mais la justice qui vient de la foi;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 31, 'tandis que les Israélites qui cherchaient la loi de la justice, ne sont point parvenus à cette loi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 32, 'Pourquoi? Parce qu\'ils l\'ont cherchée non par la foi, mais par les oeuvres; ils se sont heurtés contre la pierre d\'achoppement,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 33, 'ainsi qu\'il est écrit: «Voici que je place en Sion une pierre d\'achoppement, un rocher qui fait tomber; et celui qui croit en lui, ne sera pas couvert de confusion.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 1, 'Frères, le désir de mon coeur et la prière que j\'adresse à Dieu pour les Israélites, c\'est qu\'ils soient sauvés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 2, 'Car je leur rends ce témoignage, qu\'ils ont du zèle pour Dieu; mais ce zèle est sans connaissance.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 3, 'Ne connaissant point la justice de Dieu et cherchant à établir leur propre justice, ils ne se sont pas soumis à la justice de Dieu;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 4, 'car Christ est la fin de la loi, pour justifier tous ceux qui croient.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 5, 'En effet, Moïse décrit de cette manière la justice qui vient de la loi: «L\'homme qui l\'aura pratiquée, vivra par elle.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 6, 'Mais la justice qui vient de la foi, parle ainsi: Ne dis pas en ton coeur: Qui montera au ciel? C\'est en faire descendre Christ;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 7, 'ou: Qui descendra dans l\'abîme? C\'est faire remonter Christ d\'entre les morts.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 8, 'Mais que dit-elle? La parole est près de toi, dans ta bouche et dans ton coeur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 9, 'C\'est la parole de la foi que nous prêchons. Si donc tu confesses de ta bouche le Seigneur Jésus, et si tu crois dans ton coeur que Dieu l\'a ressuscité des morts, tu seras sauvé;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 10, 'car c\'est en croyant du coeur qu\'on obtient la justice, et c\'est en confessant de la bouche qu\'on obtient le salut.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 11, 'En effet, l\'Écriture dit: «Quiconque croit en lui, ne sera pas couvert de confusion.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 12, 'Il n\'y a point de distinction entre le Juif et le Grec, parce qu\'ils ont tous le même Seigneur, riche pour tous ceux qui l\'invoquent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 13, 'Car «quiconque invoquera le nom du Seigneur, sera sauvé.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 14, 'Mais comment invoqueront-ils Celui auquel ils n\'ont pas cru? Et comment croiront-ils en Celui dont ils n\'ont pas entendu parler? Et comment en entendront-ils parler, s\'il n\'y a personne qui le leur prêche?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 15, 'Et comment ira-t-on le leur prêcher, s\'il n\'y en a pas qui soient envoyés, conformément à ce qui est écrit: «Qu\'ils sont beaux, les pieds de ceux qui annoncent de bonnes nouvelles!»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 16, 'Mais tous n\'ont pas prêté l\'oreille à la bonne nouvelle; car Esaïe dit: «Seigneur, qui a cru à notre prédication?»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 17, 'Ainsi, la foi vient de ce qu\'on entend; et l\'on entend, lorsque la parole de Christ est prêchée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 18, 'Mais je demande: Est-ce qu\'ils ne l\'ont pas entendue? Au contraire, «la voix des messagers a retenti par toute la terre, et leurs paroles sont parvenues jusqu\'aux extrémités du monde.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 19, 'Je demande encore: Israël n\'en a-t-il rien su? Déjà Moïse dit: «J\'exciterai votre jalousie contre un peuple qui n\'en est pas un. Je provoquerai votre colère contre une nation privée d\'intelligence.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 20, 'Ésaïe pousse même la hardiesse jusqu\'à dire: «J\'ai été trouvé par ceux qui ne me cherchaient pas; je me suis manifesté à ceux qui ne me demandaient pas.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 21, 'Mais, à l\'égard d\'Israël, il dit: «Tout le jour, j\'ai tendu les mains vers un peuple rebelle et contredisant.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 1, 'Je dis donc: Dieu a-t-il rejeté son peuple? Non, certes; car je suis moi-même Israélite, de la postérité d\'Abraham, de la tribu de Benjamin.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 2, 'Dieu n\'a point rejeté son peuple, qu\'il a connu d\'avance. Ne savez-vous pas ce que l\'Écriture raconte d\'Élie, et comment celui-ci présente à Dieu sa plainte contre Israël:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 3, '«Seigneur, ils ont tué tes prophètes et ont démoli tes autels. Je suis demeuré, moi seul; et ils cherchent à m\'ôter la vie!»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 4, 'Mais quelle fut la réponse divine? «Je me suis réservé sept mille hommes, qui n\'ont point fléchi le genou devant Baal.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 5, 'De même, encore à présent, un reste subsiste selon l\'élection de la grâce.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 6, 'Mais si c\'est par la grâce, ce n\'est plus par les oeuvres; autrement, la grâce ne serait plus une grâce.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 7, 'Qu\'est-ce à dire? C\'est qu\'Israël n\'a point obtenu ce qu\'il cherche; mais les élus l\'ont obtenu, et les autres ont été endurcis,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 8, 'ainsi qu\'il est écrit: «Dieu leur a donné un esprit d\'étourdissement: des yeux pour ne point voir et des oreilles pour ne pas entendre, jusqu\'à ce jour.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 9, 'Et David dit: «Que leur table devienne pour eux un piège, un filet, une occasion de chute, leur juste punition;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 10, 'que leurs yeux soient obscurcis pour ne point voir et que leur dos soit continuellement courbé!»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 11, 'Je demande encore: Est-ce pour tomber que les enfants d\'Israël ont ainsi bronché? Non, certes! Mais c\'est par suite de leur faute, que le salut est parvenu aux Païens, afin d\'exciter leur propre émulation.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 12, 'Or, si leur faute a fait la richesse du monde, et leur amoindrissement la richesse des Païens, que ne fera pas leur complet relèvement!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 13, 'Je vous le dis à vous. Païens: en tant qu\'apôtre des Païens, je rends mon ministère glorieux,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 14, 'en m\'efforçant de provoquer l\'émulation de ceux de ma race et d\'en sauver quelques-uns.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 15, 'Car, si leur rejet a eu pour effet la réconciliation du monde, que sera leur retour en grâce, sinon une résurrection d\'entre les morts?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 16, 'Or, si les prémices sont saintes, la masse l\'est aussi; et si la racine est sainte, les branches le sont aussi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 17, 'Si quelques-unes des branches ont été retranchées, et si toi, qui étais un olivier sauvage, tu as été greffé à leur place pour avoir part à la sève et à la racine de l\'olivier,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 18, 'ne te glorifie pas aux dépens des branches. Et si tu te glorifies, sache que ce n\'est pas toi qui portes la racine, c\'est la racine qui te porte!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 19, 'Tu diras: les branches ont été retranchées, afin que je fusse greffé à leur place.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 20, 'Fort bien; elles ont été retranchées à cause de leur incrédulité, et toi, tu subsistes par la foi. Garde-toi de t\'enorgueillir; tremble plutôt!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 21, 'Car si Dieu n\'a point épargné les branches naturelles, il peut ne pas t\'épargner non plus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 22, 'Considère donc la bonté et la sévérité de Dieu: sa sévérité envers ceux qui sont tombés, et sa bonté envers toi, si toutefois tu te maintiens dans sa bonté; autrement, tu seras aussi retranché.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 23, 'Et quant à eux, s\'ils ne persistent pas dans l\'incrédulité, ils seront aussi greffés; car Dieu est assez puissant pour les greffer de nouveau.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 24, 'Si toi-même, après avoir été coupé sur l\'olivier qui, de sa nature, était sauvage, tu as été greffé, contre l\'ordre de la nature, sur l\'olivier franc, combien plus ceux-ci, qui sont les branches naturelles, seront-ils greffés sur leur propre olivier!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 25, 'En effet, je ne veux pas, frères, que vous ignoriez ce mystère, de peur que vous ne présumiez trop de votre sagesse: c\'est qu\'une partie d\'Israël est tombée dans l\'endurcissement, jusqu\'à ce que toute la multitude des Païens soit entrée;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 26, 'et ainsi, tout Israël sera sauvé, comme il est écrit: «Le libérateur viendra de Sion, et il éloignera de Jacob les impiétés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 27, 'C\'est l\'alliance que je ferai avec eux, lorsque j\'effacerai leurs péchés.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 28, 'Si, en ce qui concerne l\'Évangile, ils sont ennemis à cause de vous, — en ce qui concerne l\'élection, ils sont aimés à cause de leurs pères;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 29, 'car les dons et l\'appel de Dieu sont irrévocables.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 30, 'Et, de même que vous avez été autrefois rebelles à Dieu, et que maintenant vous avez obtenu miséricorde par suite de leur rébellion, —');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 31, 'de même, ils ont maintenant désobéi, afin que, à cause de la miséricorde qui vous a été faite, eux aussi obtiennent maintenant miséricorde.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 32, 'Car Dieu a enfermé tous les hommes dans la rébellion, pour faire miséricorde à tous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 33, 'O profondeur de la richesse, et de la sagesse, et de la connaissance de Dieu! Que ses jugements sont impénétrables et ses voies incompréhensibles!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 34, 'Car, «qui a connu la pensée du Seigneur, ou qui a été son conseiller?»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 35, 'Ou bien «qui lui a donné le premier, pour recevoir quelque chose en retour?»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 36, 'C\'est de lui, et par lui, et pour lui, que sont toutes choses. A lui soit la gloire, dans tous les siècles! Amen.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 1, 'Je vous exhorte donc, frères, par les compassions de Dieu, à offrir vos corps en sacrifice vivant, saint, agréable à Dieu, ce qui est votre culte raisonnable.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 2, 'Ne vous conformez pas au présent siècle, mais soyez transformés par le renouvellement de votre esprit, afin que vous discerniez quelle est la volonté de Dieu, qui est bonne, agréable et parfaite.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 3, 'En vertu de la grâce qui m\'a été donnée, je recommande donc à chacun de vous de n\'avoir pas de lui-même une plus haute opinion qu\'il ne doit, mais d\'avoir des sentiments modestes, selon la mesure de la foi que Dieu a départie à chacun.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 4, 'En effet, comme nous avons plusieurs membres dans un seul corps, et que tous les membres n\'ont pas la même fonction, —');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 5, 'ainsi nous, qui sommes plusieurs, nous formons un seul corps en Christ; et nous sommes tous membres les uns des autres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 6, 'Et, puisque nous avons des dons différents, suivant la grâce qui nous a été accordée, que celui qui a le don de prophétie, l\'exerce selon l\'analogie de la foi;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 7, 'que celui qui est appelé au ministère, s\'attache à son ministère; que celui qui enseigne, s\'applique à l\'enseignement;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 8, 'que celui qui est chargé d\'exhorter, exhorte; que celui qui distribue les aumônes, le fasse avec libéralité; que celui qui préside, le fasse avec soin; que celui qui exerce la miséricorde, le fasse avec joie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 9, 'Que la charité soit sincère. Ayez le mal en horreur, et attachez-vous fortement au bien.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 10, 'Aimez-vous réciproquement d\'une affection tendre et fraternelle; prévenez-vous par des égards réciproques.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 11, 'Ne vous relâchez point dans votre zèle; soyez fervents d\'esprit; servez le Seigneur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 12, 'Soyez joyeux dans l\'espérance, patients dans l\'affliction, persévérants dans la prière.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 13, 'Subvenez aux besoins des saints; soyez empressés à exercer l\'hospitalité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 14, 'Bénissez ceux qui vous persécutent; bénissez, et ne maudissez point.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 15, 'Soyez dans la joie avec ceux qui sont dans la joie, et pleurez avec ceux qui pleurent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 16, 'Vivez entre vous en bonne intelligence; n\'aspirez pas aux choses élevées, mais laissez-vous attirer par ce qui est humble. Ne soyez point sages à vos propres yeux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 17, 'Ne rendez à personne le mal pour le mal; appliquez-vous, devant tous les hommes, à rechercher ce qui est bien.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 18, 'S\'il est possible, autant que cela dépend de vous, ayez la paix avec tous les hommes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 19, 'Ne vous vengez point vous-mêmes, mes bien aimés, mais laissez agir la colère divine; car il est écrit: «C\'est à moi qu\'appartient la vengeance; c\'est moi qui rétribuerai», dit le Seigneur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 20, 'Si donc ton ennemi a faim, donne-lui à manger; s\'il a soif, donne-lui à boire; car, en agissant ainsi, tu amasseras des charbons ardents sur sa tête.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 21, 'Ne te laisse pas vaincre par le mal, mais triomphe du mal par le bien.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 1, 'Que toute personne soit soumise aux autorités placées au-dessus de nous; car il n\'y a pas d\'autorité qui ne vienne de Dieu, et celles qui existent ont été instituées par Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 2, 'Ainsi, celui qui résiste à l\'autorité, s\'oppose à l\'ordre que Dieu a établi; et ceux qui s\'y opposent, attireront sur eux le jugement.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 3, 'En effet, ceux qui gouvernent ne sont pas à craindre pour les bonnes actions, mais pour les mauvaises. Veux-tu ne pas avoir à craindre l\'autorité? Fais le bien, et tu auras son approbation;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 4, 'car le magistrat est ministre de Dieu pour ton bien. Mais si tu fais le mal, crains; car ce n\'est pas en vain qu\'il porte l\'épée: il est ministre de Dieu pour exercer la justice et pour punir celui qui fait le mal.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 5, 'C\'est pourquoi, il est nécessaire de se soumettre, non seulement par crainte de la punition, mais encore par motif de conscience.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 6, 'C\'est pour la même raison que vous payez des impôts; car les magistrats sont les serviteurs de Dieu, quand ils s\'acquittent fidèlement de leur fonction.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 7, 'Rendez à tous ce qui leur est dû: l\'impôt, à qui est dû l\'impôt; le tribut, à qui est dû le tribut; la crainte, à qui est due la crainte; l\'honneur, à qui est dû l\'honneur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 8, 'N\'ayez de dettes envers personne, si ce n\'est l\'amour que vous vous devez les uns aux autres; car celui qui aime son prochain a accompli la loi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 9, 'En effet, ces commandements: «Tu ne commettras point d\'adultère; tu ne tueras point; tu ne déroberas point; tu ne convoiteras point» — et tels autres qu\'on pourrait encore citer, — tous se résument dans cette parole: «Tu aimeras ton prochain comme toi-même.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 10, 'L\'amour ne fait point de mal au prochain; l\'amour est donc l\'accomplissent de la loi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 11, 'Au surplus, vous savez dans quel temps nous vivons: l\'heure est venue de vous réveiller de votre sommeil, puisque le salut est maintenant plus près de nous que lorsque nous avons cru.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 12, 'La nuit est avancée, le jour approche; dépouillons-nous donc des oeuvres des ténèbres et revêtons-nous des armes de la lumière.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 13, 'Marchons honnêtement, comme en plein jour. Ne vous livrez pas aux excès et à l\'ivrognerie, à la débauche et au dérèglement, aux querelles et à la jalousie;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 14, 'mais revêtez-vous du Seigneur Jésus-Christ, et ne prenez pas soin de la chair de manière à en exciter les convoitises.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 1, 'Accueillez avec bonté celui qui est faible dans la foi, sans discuter les opinions.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 2, 'L\'un croit pouvoir manger de tout; l\'autre, qui est faible, ne prend que des légumes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 3, 'Que celui qui mange de tout, ne méprise pas celui qui ne mange pas de tout. Et que celui qui ne mange pas, ne juge pas celui qui mange; car Dieu lui a aussi fait accueil.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 4, 'Qui es-tu, toi qui juges le serviteur d\'autrui? Qu\'il demeure ferme, ou qu\'il tombe, cela regarde son maître; — mais il sera affermi, car le Seigneur a le pouvoir de l\'affermir!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 5, 'L\'un estime tel jour plus que tel autre; l\'autre estime que tous les jours sont égaux: que chacun agisse avec une entière conviction d\'esprit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 6, 'Celui qui observe tel jour, l\'observe pour le Seigneur; et celui qui mange, le fait pour le Seigneur; car il rend grâces à Dieu. Et celui qui ne mange pas, le fait aussi pour le Seigneur, et il rend grâces à Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 7, 'En effet, aucun de nous ne vit pour lui-même, et aucun de nous ne meurt pour lui-même;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 8, 'car si nous vivons, nous vivons pour le Seigneur, et si nous mourons, nous mourons pour le Seigneur. Soit donc que nous vivions, soit que nous mourions, nous sommes au Seigneur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 9, 'Car c\'est pour être le Seigneur des morts et des vivants, que Christ est mort et qu\'il a repris vie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 10, 'Mais toi, pourquoi juges-tu ton frère? Et toi, de ton côté, pourquoi méprises-tu ton frère? Nous comparaîtrons tous devant le tribunal de Dieu;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 11, 'car il est écrit: «Aussi vrai que je suis vivant, dit le Seigneur, tout genou fléchira devant moi, et toute langue donnera gloire à Dieu»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 12, 'Ainsi, chacun de nous rendra compte à Dieu pour soi-même.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 13, 'Ne nous jugeons donc plus les uns les autres. Mais prenez plutôt la résolution de ne pas mettre devant votre frère une pierre d\'achoppement, et de ne pas être pour lui une cause de chute.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 14, 'Je sais, et j\'ai cette persuasion dans le Seigneur Jésus, que rien n\'est impur en soi-même; seulement, si quelqu\'un croit qu\'une chose est impure, elle l\'est pour lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 15, 'Or si, pour un aliment, tu affliges ton frère, tu ne te conduis plus selon la charité. N\'entraîne pas à la perdition, par ton aliment, celui pour lequel Christ est mort.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 16, 'Que l\'avantage dont vous jouissez ne devienne donc pas un sujet de blâme.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 17, 'Car le royaume de Dieu ne consiste pas dans le manger et le boire, mais dans la justice, la paix et la joie par le Saint-Esprit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 18, 'Celui qui sert le Christ de cette manière est agréable à Dieu et approuvé des hommes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 19, 'Recherchons donc ce qui contribue à la paix et à l\'édification mutuelle.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 20, 'Ne va pas, pour un aliment, détruire l\'oeuvre de Dieu. Toutes choses, il est vrai, sont pures; mais il est mal d\'en manger, si l\'on devient ainsi pour d\'autres une occasion de chute.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 21, 'Ce qui est bien, c\'est de ne pas manger de viande, de ne pas boire de vin, et de t\'abstenir de tout ce qui est une occasion de chute pour ton frère.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 22, 'Tu as une conviction: garde-la pour toi-même devant Dieu. Heureux celui qui ne se condamne pas lui-même dans le plan de conduite qu\'il adopte!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 23, 'Mais celui qui a des doutes au sujet d\'un aliment, est condamné, s\'il en mange, parce qu\'il ne le fait pas avec foi; or, tout ce qu\'on ne fait pas avec foi, est un péché.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 1, 'Nous devons donc, nous qui sommes forts, supporter les infirmités des faibles, et ne pas nous complaire en nous-mêmes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 2, 'Que chacun de nous complaise à son prochain, pour le bien, en vue de l\'édification.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 3, 'Le Christ, en effet, n\'a pas eu de complaisance pour lui-même; mais il est écrit: «Les outrages de ceux qui t\'outragent sont tombés sur moi.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 4, 'Or, toutes les choses qui ont été écrites auparavant, l\'ont été pour notre instruction, afin que, par la patience et par la consolation que donnent les Écritures, nous possédions l\'espérance.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 5, 'Que le Dieu de la patience et de la consolation vous donne de vivre, les uns avec les autres, en bonne intelligence, selon Jésus-Christ,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 6, 'afin que, d\'un même coeur et d\'une même bouche, vous rendiez gloire à Dieu, le Père de notre Seigneur Jésus-Christ!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 7, 'Ainsi donc, accueillez-vous les uns les autres, comme Christ aussi vous a accueillis, pour la gloire de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 8, 'Je dis, en effet, que Jésus-Christ a exercé son ministère auprès des circoncis, pour manifester la fidélité de Dieu et pour confirmer les promesses faites à nos pères,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 9, 'tandis que les Païens ont à glorifier Dieu pour sa miséricorde, ainsi qu\'il est écrit: «C\'est pourquoi, je te louerai parmi les nations, et je chanterai à la gloire de ton nom.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 10, 'Il est dit encore: «Nations, réjouissez-vous avec son peuple!»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 11, 'Et encore: «Louez le Seigneur, vous toutes les nations, et que tous les peuples le célèbrent!»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 12, 'Ésaïe dit aussi: «De la racine de Jessé s\'élèvera le rejeton qui gouvernera les nations, et les nations espéreront en lui.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 13, 'Que le Dieu de l\'espérance vous remplisse donc de toute joie et de toute paix dans la foi, afin que vous abondiez en espérance, par la puissance du Saint-Esprit!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 14, 'En ce qui vous concerne, mes frères, je suis persuadé, moi aussi, que vous êtes pleins de bonté, remplis d\'une parfaite connaissance, capables de vous avertir les uns les autres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 15, 'Si je vous ai écrit, ici et là, avec une certaine hardiesse, c\'est pour raviver vos souvenirs, en vertu de la grâce que Dieu m\'a faite,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 16, 'd\'être ministre de Jésus-Christ parmi les Païens, exerçant le sacerdoce de l\'Évangile de Dieu, afin que les Païens lui soient une offrande agréable, sanctifiée par l\'Esprit saint.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 17, 'J\'ai donc sujet de me glorifier en Jésus-Christ, pour ce qui regarde le service de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 18, 'Car je ne me permettrais pas de parler de choses que Christ n\'aurait pas faites par moi pour amener les Païens à son obéissance, par la parole et par les oeuvres,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 19, 'par la puissance des miracles et des prodiges, par la puissance de l\'Esprit de Dieu. C\'est au point que, depuis Jérusalem et les contrées voisines jusqu\'en Illyrie, j\'ai porté partout l\'Évangile du Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 20, 'Mais je me suis fait un honneur d\'annoncer l\'Évangile là où le nom de Christ n\'avait pas encore été prononcé, afin de ne point bâtir sur le fondement posé par un autre,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 21, 'ainsi qu\'il est écrit: «Ceux à qui il n\'avait pas été annoncé le verront, et ceux qui n\'avaient pas entendu parler de lui le connaîtront.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 22, 'C\'est aussi ce qui m\'a souvent empéché d\'aller vous voir.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 23, 'Mais, à présent, je n\'ai plus rien qui me retienne dans ces contrées; et comme, depuis plusieurs années, j\'ai un grand désir d\'aller chez vous, si je puis me rendre en Espagne,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 24, 'j\'espère que je vous verrai en passant, et qu\'ensuite vous m\'y ferez conduire, après que j\'aurai satisfait, au moins en partie, mon désir d\'être avec vous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 25, 'Maintenant, je vais à Jérusalem pour le service des saints.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 26, 'En effet, la Macédoine et l\'Achaïe ont bien voulu faire une collecte en faveur des saints de Jérusalem, qui sont dans la pauvreté.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 27, 'Elles l\'ont bien voulu, et puis, elles le leur devaient; car si les Païens ont eu part aux biens spirituels des Juifs, ils doivent à leur tour les assister de leurs biens temporels.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 28, 'Lors donc que j\'aurai achevé cette oeuvre et que j\'aurai remis fidèlement ce fruit de leur libéralité, je passerai chez vous pour aller en Espagne.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 29, 'Et je sais qu\'en me rendant auprès de vous, je viendrai avec toute la richesse des bénédictions de Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 30, 'Je vous exhorte donc, mes frères, par notre Seigneur Jésus-Christ et par l\'amour que produit l\'Esprit, à combattre avec moi dans les prières que vous adresserez à Dieu en ma faveur,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 31, 'afin que je sois délivré des incrédules qui sont en Judée, et que le secours que je porte à Jérusalem soit bien accueilli par les saints.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 32, 'Alors, je pourrai arriver chez vous avec joie, et, s\'il plaît à Dieu, goûter avec vous quelque repos.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 33, 'Que le Dieu de paix soit avec vous tous! Amen.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 1, 'Je vous recommande Phébé, notre soeur, qui est diaconesse de l\'Église de Cenchrées.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 2, 'Ayez soin de l\'accueillir, en notre Seigneur, d\'une manière digne des saints, et de l\'assister dans toutes les occasions où elle pourrait avoir besoin de vous; car elle-même en a assisté plusieurs, et moi en particulier.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 3, 'Saluez Priscille et Aquilas, mes compagnons d\'oeuvre en Jésus-Christ,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 4, 'qui ont exposé leur tête pour sauver ma vie; et ce n\'est pas moi seul qui leur rends grâces, mais ce sont encore toutes les Églises des pays païens.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 5, 'Saluez aussi l\'Église qui se réunit dans leur maison. Saluez Épaïnète, qui m\'est très cher, et qui a été pour Christ les prémices de l\'Asie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 6, 'Saluez Marie, qui a beaucoup travaillé pour vous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 7, 'Saluez Andronique et Junias, mes parents et mes compagnons de captivité, qui sont très estimés parmi les apôtres, et qui même ont été en Christ avant moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 8, 'Saluez Amplias, mon bien-aimé dans le Seigneur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 9, 'Saluez Urbain, notre compagnon d\'oeuvre en Christ, et Stachys, qui m\'est fort cher.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 10, 'Saluez Appelles, qui a fait ses preuves en Christ. Saluez ceux de la maison d\'Aristobule.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 11, 'Saluez Hérodion, mon parent. Saluez ceux de la maison de Narcisse, qui sont au Seigneur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 12, 'Saluez Tryphène et Tryphose, qui travaillent pour le Seigneur. Saluez Perside, qui m\'est très chère, et qui a beaucoup travaillé pour le Seigneur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 13, 'Saluez Rufus, l\'élu du Seigneur, et sa mère, qui est aussi la mienne.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 14, 'Saluez Asyncrite, Phlégon, Hermès, Patrobas, Hermas, et les frères qui sont avec eux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 15, 'Saluez Philologue et Julie, Nérée, et sa soeur, et Olympe, et tous les saints qui sont avec eux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 16, 'Saluez-vous les uns les autres par un saint baiser. Toutes les Églises du Christ vous saluent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 17, 'Je vous exhorte, frères, à prendre garde à ceux qui causent des divisions et des scandales, en s\'opposant à l\'enseignement que vous avez reçu. Éloignez-vous d\'eux;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 18, 'car ces gens-là servent non le Christ, notre Seigneur, mais leur ventre; et, par des paroles douces et flatteuses, ils séduisent les coeurs des simples.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 19, 'Votre obéissance est connue de tous; je me réjouis donc à votre sujet, et je souhaite que vous soyez sages pour le bien, et purs à l\'égard du mal.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 20, 'Le Dieu de paix écrasera bientôt Satan sous vos pieds. Que la grâce de notre Seigneur Jésus soit avec vous!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 21, 'Timothée, mon compagnon d\'oeuvre, vous salue, ainsi que Lucius, Jason et Sosipater, mes parents.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 22, 'Je vous salue dans le Seigneur, moi Tertius, qui ai écrit cette épître.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 23, 'Gaïus, mon hôte et celui de toute l\'Église, vous salue. Éraste, le trésorier de la ville, et Quartus, mon frère, vous saluent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 24, '[La grâce de notre Seigneur Jésus-Christ soit avec vous tous. Amen]');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 25, 'A Celui qui peut vous affermir selon mon Évangile et la prédication du nom de Jésus-Christ, conformément à la révélation du mystère, tenu caché durant les siècles passés,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 26, 'mais qui maintenant, sur l\'ordre du Dieu éternel, a été manifesté et porté, par les écrits prophétiques, à la connaissance de toutes les nations, pour les amener à l\'obéissance de la foi, —');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 27, 'à Dieu seul sage, soit la gloire dans tous les siècles, par Jésus-Christ! Amen.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 1, 'Paul, appelé par la volonté de Dieu à être apôtre de Jésus-Christ, et Sosthène, notre frère,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 2, 'à l\'Église de Dieu qui est à Corinthe, à ceux qui sont sanctifiés en Jésus-Christ, appelés à être saints, et à tous ceux qui invoquent, en quelque lieu que ce soit, le nom de notre Seigneur Jésus-Christ, leur Seigneur et le nôtre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 3, 'Que la grâce et la paix vous soient données de la part de Dieu, notre Père, et du Seigneur Jésus-Christ!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 4, 'Je ne cesse de bénir mon Dieu à votre sujet, à cause de la, grâce qui vous a été accordée par lui, en Jésus-Christ;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 5, 'car vous avez été enrichis de tous les dons, ceux de la parole et ceux de la connaissance,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 6, 'le témoignage du Christ ayant été fermement établi parmi vous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 7, 'Aussi ne vous manque-t-il aucun don, à vous qui attendez le moment où apparaîtra notre Seigneur Jésus-Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 8, 'C\'est lui qui vous rendra fermes jusqu\'à la fin, pour que vous soyez irréprochables au jour de notre Seigneur Jésus-Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 9, 'Le Dieu par qui vous avez été appelés à la communion de son Fils Jésus-Christ, notre Seigneur, est un Dieu fidèle.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 10, 'Je vous exhorte, frères, au nom de notre Seigneur Jésus-Christ, à tenir tous le même langage et à n\'avoir point de divisions parmi vous, mais à être bien unis dans une même pensée et dans un même sentiment.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 11, 'En effet, mes frères, j\'ai été informé, par les gens de la maison de Chloé, qu\'il y a des disputes parmi vous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 12, 'Voici ce que je veux dire: c\'est que, parmi vous, chacun parle ainsi: Moi, je suis disciple de Paul; — et moi, d\'Apollos; — et moi, de Céphas; — et moi, de Christ. —');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 13, 'Christ est-il divisé? Paul a-t-il été crucifié pour vous, ou avez-vous été baptisés au nom de Paul?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 14, 'Je rends grâces de ce que je n\'ai baptisé aucun de vous, — sinon Crispus et Gaius —,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 15, 'afin que personne ne puisse dire que vous avez été baptisés en mon nom.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 16, 'J\'ai baptisé aussi la famille de Stéphanas; à part ceux-là, je ne sache pas que j\'aie baptisé quelqu\'un d\'autre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 17, 'En effet, ce n\'est pas pour baptiser que Christ m\'a envoyé, mais c\'est pour annoncer l\'Évangile, et cela sans recourir à la sagesse des discours, afin que la croix du Christ ne soit pas rendue vaine.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 18, 'Car la prédication de la croix est une folie pour ceux qui périssent; mais, pour nous qui sommes sauvés, elle est la puissance de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 19, 'Aussi est-il écrit: «Je détruirai la sagesse des sages, et j\'anéantirai l\'intelligence des intelligents.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 20, 'Où est le sage? Où est le scribe? Où est le disputeur de ce siècle? Dieu n\'a-t-il pas convaincu de folie la sagesse du monde?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 21, 'Car, puisque le monde, avec sa sagesse, n\'a pas connu Dieu dans la sagesse de Dieu, il a plu à Dieu de sauver ceux qui croient, par la folie de notre prédication.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 22, 'En effet, tandis que les Juifs demandent des miracles et que les Grecs cherchent la sagesse,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 23, 'nous, nous prêchons Christ crucifié, scandale pour les Juifs, folie pour les Païens;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 24, 'mais, pour ceux qui sont appelés, Juifs comme Grecs, Christ est la puissance de Dieu, la sagesse de Dieu!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 25, 'Car la folie de Dieu est plus sage que les hommes, et la faiblesse de Dieu plus forte que les hommes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 26, 'Considérez, frères, que, parmi vous qui avez été appelés, il n\'y a ni beaucoup de sages selon la chair, ni beaucoup de puissants, ni beaucoup de nobles.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 27, 'Mais Dieu a choisi les choses folles du monde pour confondre les sages; Dieu a choisi les choses faibles du monde pour confondre les fortes;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 28, 'Dieu a choisi les choses viles du monde et les plus méprisées, celles qui ne sont point, pour réduire à néant celles qui sont,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 29, 'afin que personne ne se glorifie devant Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 30, 'Or, c\'est grâce à lui que vous appartenez à Jésus-Christ qui a été fait pour nous, de la part de Dieu, sagesse, et justice, et sanctification, et rédemption,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 31, '— afin, comme le dit l\'Écriture, «que celui qui se glorifie, se glorifie dans le Seigneur.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 1, 'Pour moi, frères, quand je suis venu chez vous, je n\'y suis pas venu pour vous annoncer le témoignage de Dieu avec le prestige du langage et de la sagesse.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 2, 'Car je n\'ai pas jugé que je dusse savoir parmi vous autre chose que Jésus-Christ, et Jésus-Christ crucifié.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 3, 'Quand j\'ai vécu parmi vous, j\'ai été faible, craintif, tout tremblant.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 4, 'Et ma parole et ma prédication n\'ont pas consisté dans les discours persuasifs de la sagesse, mais dans une démonstration d\'esprit et de puissance,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 5, '— afin que votre foi fût fondée, non sur la sagesse des hommes, mais sur la puissance de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 6, 'C\'est cependant une sagesse que nous prêchons aux hommes faits, mais une sagesse qui n\'est pas de ce monde, ni des princes de ce monde qui vont être anéantis.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 7, 'Nous prêchons la sagesse de Dieu, mystérieuse et cachée, que Dieu avait prédestinée avant les siècles, pour notre gloire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 8, 'Aucun des princes de ce monde ne l\'a connue; car, s\'ils l\'avaient connue, ils n\'auraient pas crucifié le Seigneur de gloire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 9, 'Mais, comme le dit l\'Écriture: «Ce sont des choses que l\'oeil n\'a point vues, que l\'oreille n\'a pas entendues et qui ne sont pas montées au coeur de l\'homme, mais que Dieu a préparées pour ceux qui l\'aiment.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 10, 'Dieu nous les a révélées par l\'Esprit; car l\'Esprit sonde toutes choses, même les profondeurs de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 11, 'En effet, qui sait ce qui est dans l\'homme, sinon l\'esprit de l\'homme qui est en lui? De même aussi, personne ne connaît ce qui est en Dieu, si ce n\'est l\'Esprit de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 12, 'Quant à nous, nous n\'avons pas reçu l\'esprit du monde, mais l\'Esprit qui vient de Dieu, afin que nous connaissions les grâces que nous avons reçues de Dieu;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 13, 'et nous en parlons, non avec les discours qu\'enseigne la sagesse humaine, mais avec ceux qu\'enseigne l\'Esprit, exposant les choses spirituelles dans un langage spirituel.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 14, 'Or, l\'homme naturel n\'accueille point les choses qui, sont de l\'esprit de Dieu; car elles sont pour lui une folie, et il ne peut les comprendre, parce que c\'est spirituellement qu\'on en juge.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 15, 'Mais l\'homme spirituel juge de toutes choses, et il n\'est lui-même jugé par personne.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 16, 'Car, qui a connu la pensée du Seigneur, pour lui donner des leçons? Nous, nous avons la pensée de Christ!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 1, 'Pour moi, frères, je n\'ai pu vous parler comme à des hommes spirituels; mais je vous ai parlé comme à des hommes charnels, comme à des petits enfants en Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 2, 'Je vous ai donné du lait, et non de la nourriture solide; car vous ne pouviez pas la supporter. Et même à présent, vous ne le pouvez pas encore, parce que vous êtes encore charnels.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 3, 'En effet, puisqu\'il y a parmi vous de la jalousie et des dissensions, n\'êtes-vous pas charnels, et ne vous conduisez-vous pas à la manière des hommes?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 4, 'Quand l\'un dit: Moi, je suis disciple de Paul; et l\'autre: Moi, d\'Apollos, — n\'êtes-vous pas des hommes comme les autres?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 5, 'Qu\'est-ce donc qu\'Apollos, et qu\'est-ce que Paul? Ce sont des serviteurs, par le moyen desquels vous avez cru, selon ce qui a été accordé à chacun par le Seigneur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 6, 'J\'ai planté, Apollos a arrosé, mais Dieu a donné l\'accroissement.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 7, 'Ainsi, ce n\'est pas celui qui plante, qui est quelque chose, — pas plus que celui qui arrose —, mais Dieu, qui donne l\'accroissement.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 8, 'Celui qui plante et celui qui arrose sont égaux; et chacun recevra sa propre récompense selon son propre travail.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 9, 'En effet, nous sommes ouvriers avec Dieu; vous êtes le champ que Dieu cultive, la maison que Dieu édifie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 10, 'Selon la grâce de Dieu qui m\'a été donnée, j\'ai posé le fondement, comme fait un sage architecte, et un autre bâtit dessus; mais que chacun prenne garde à la manière dont il bâtit lui-même.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 11, 'Pour ce qui est du fondement, personne ne peut en poser un autre que celui qui a été posé, Jésus-Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 12, 'Si l\'on bâtit sur ce fondement avec de l\'or, de l\'argent, des pierres précieuses, du bois, du foin, du chaume, l\'oeuvre de chacun sera manifestée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 13, 'Le jour vient qui la fera connaître; c\'est dans le feu qu\'elle se révélera, et ce que vaut l\'oeuvre de chacun, le feu le montrera.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 14, 'Si l\'ouvrage bâti par quelqu\'un sur le fondement subsiste, l\'ouvrier recevra sa récompense.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 15, 'Si son ouvrage est consumé, il la perdra. Pour lui, il sera sauvé, mais comme au travers du feu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 16, 'Ne savez-vous pas que vous êtes le temple de Dieu, et que l\'Esprit de Dieu habite en vous?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 17, 'L\'homme qui détruit le temple de Dieu sera détruit lui-même par Dieu; car le temple de Dieu est saint, et vous êtes saints, vous aussi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 18, 'Que personne ne s\'abuse soi-même: si quelqu\'un parmi vous pense être sage à la façon de ce siècle, qu\'il devienne fou, pour devenir sage;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 19, 'car la sagesse de ce monde est une folie devant Dieu. Aussi est-il écrit: «C\'est lui qui prend les sages dans leur propre ruse.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 20, 'Et ailleurs: «Le Seigneur connaît les pensées des sages; il sait qu\'elles sont vaines.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 21, 'Que personne donc ne mette sa gloire dans les hommes, car toutes choses sont à vous:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 22, 'soit Paul, soit Apollos, soit Céphas, soit le monde, soit la vie, soit la mort, soit les choses présentes, soit les choses à venir.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 23, 'Toutes choses sont à vous, et vous êtes à Christ, et Christ est à Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 1, 'Ainsi, que chacun nous regarde comme des serviteurs de Christ et des administrateurs des mystères de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 2, 'Au reste, ce qu\'on demande à des administrateurs, c\'est d\'être trouvés fidèles.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 3, 'Pour moi, il m\'importe fort peu d\'être jugé par vous, ou par aucun tribunal humain. Je ne me juge pas non plus moi-même;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 4, 'car je ne me sens coupable de rien, mais je ne suis pas justifié pour cela: celui qui me juge, c\'est le Seigneur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 5, 'Ne portez donc pas de jugement prématuré; attendez que le Seigneur vienne. C\'est lui qui mettra en lumière les choses cachées dans les ténèbres, et qui manifestera les desseins des coeurs; et alors, chacun de vous recevra de Dieu la louange qui lui revient.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 6, 'Si j\'ai fait l\'application de ces vérités à moi-même et à Apollos, c\'est à cause de vous, frères, afin que vous appreniez, en nos personnes, à ne pas aller au delà de ce qui est écrit, et que vous ne vous enfliez pas d\'orgueil, en prenant parti pour l\'un contre l\'autre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 7, 'Car, de qui vient la différence entre toi et un autre? Qu\'as-tu, que tu ne l\'aies reçu? Et si tu l\'as reçu, pourquoi te glorifies-tu, comme si tu ne l\'avais pas reçu?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 8, 'Vous êtes déjà rassasiés, vous êtes déjà enrichis; sans nous vous avez commencé à régner; et que ne régnez-vous en effet, afin que, nous aussi, nous régnions avec vous!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 9, 'Car Dieu nous a exposés, semble-t-il, nous, les apôtres, comme les derniers des hommes, comme des condamnés à mort, nous donnant en spectacle au monde, aux anges et aux hommes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 10, 'Nous sommes fous à cause de Christ, mais vous, vous êtes sages en Christ; nous sommes faibles, et vous êtes forts; vous êtes honorés, et nous sommes méprisés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 11, 'Jusqu\'à cette heure nous souffrons et la faim et la soif; nous sommes nus; on nous frappe au visage; nous sommes errants çà et là.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 12, 'Nous nous fatiguons à travailler de nos propres mains. Injuriés, nous bénissons; persécutés, nous supportons;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 13, 'calomniés, nous exhortons! Nous sommes comme les balayures du monde, le rebut de tous les hommes, jusqu\'à ce jour.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 14, 'Je n\'écris point ces choses pour vous faire honte; mais je vous avertis, comme mes enfants bien-aimés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 15, 'Car, eussiez-vous dix mille maîtres en Christ, cependant vous n\'avez pas plusieurs pères: c\'est moi qui vous ai engendrés en Jésus-Christ, par l\'Évangile.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 16, 'Je vous en conjure donc: soyez mes imitateurs.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 17, 'C\'est pour cela que je vous ai envoyé Timothée, qui est mon enfant bien-aimé, fidèle dans le Seigneur; il vous rappellera quelle est en Jésus-Christ ma ligne de conduite, et de quelle manière j\'enseigne partout dans toutes les Églises.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 18, 'Quelques-uns se sont enflés d\'orgueil, comme si je ne devais plus aller chez vous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 19, 'Mais j\'irai bientôt chez vous, si le Seigneur le veut, et je saurai, non quelle est la parole, mais quelle est la puissance de ces orgueilleux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 20, 'Car le royaume de Dieu consiste, non en paroles, mais en puissance.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 21, 'Qu\'aimez-vous mieux, que j\'aille à vous avec la verge, ou avec l\'amour et dans un esprit de douceur?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 1, 'On entend dire partout qu\'il y a de l\'immoralité parmi vous, une immoralité telle qu\'on n\'en rencontre pas de semblable chez les Païens: c\'est au point que l\'un de vous vit avec la femme de son père...');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 2, 'Et vous êtes enflés d\'orgueil! Et vous n\'avez pas plutôt pris le deuil, afin que celui qui a commis une telle action fût retranché du milieu de vous!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 3, 'Pour moi, absent de corps, mais présent d\'esprit,— vous et mon esprit étant réunis ensemble, et en vertu du pouvoir que possède Jésus, notre Seigneur, — j\'ai déjà, comme si j\'étais présent, prononcé mon jugement contre celui qui a commis cette action:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 4, 'Au nom de Jésus, notre Seigneur,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 5, 'qu\'un tel homme soit livré à Satan pour la destruction de la chair, afin que l\'esprit soit sauvé au jour du Seigneur Jésus!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 6, 'Vous n\'avez certes point sujet de vous glorifier. Ne savez-vous pas qu\'un peu de levain fait lever toute la pâte?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 7, 'Purifiez-vous du vieux levain, afin que vous deveniez une pâte nouvelle et sans levain, comme vous l\'êtes aussi; car Christ, notre Pâque, a été immolé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 8, 'Ainsi donc, célébrons la fête, non avec le vieux levain, ni avec un levain de malice et de méchanceté, mais avec les pains sans levain de la sincérité et de la vérité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 9, 'Je vous ai écrit, dans ma lettre, de ne point avoir de relations avec les impudiques;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 10, 'non pas, en général, avec les impudiques de ce monde, ou avec les hommes cupides et rapaces, ou avec les idolâtres; car alors il vous faudrait sortir du monde...');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 11, 'Mais je vous ai écrit de ne point avoir de relations avec quelqu\'un qui, prenant le nom de frère, serait impudique, ou cupide, ou idolâtre, ou diffamateur, ou ivrogne, ou rapace, et même de ne pas manger avec un tel homme.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 12, 'Car, est-ce à moi de juger ceux du dehors? N\'est-ce pas ceux du dedans que vous avez à juger?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 13, 'Quant à ceux du dehors, Dieu les jugera... Otez le méchant du milieu de vous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 1, 'Quand l\'un de vous a un différend avec un autre, comment ose-t-il le faire juger par les infidèles, plutôt que par les saints?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 2, 'Ne savez-vous pas que les saints jugeront le monde? Et si c\'est par vous que le monde doit être jugé, seriez-vous indignes de juger les affaires les moins importantes?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 3, 'Ne savez-vous pas que nous jugerons les anges? Combien plus les affaires de cette vie!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 4, 'Et, lorsque vous avez des différends sur des questions de cet ordre, vous prenez pour juges des gens dont l\'Église ne fait aucun cas!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 5, 'Je le dis pour vous faire honte. Ainsi, il n\'y a pas, parmi vous, un homme sage, pas un seul, qui puisse être juge entre ses frères?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 6, 'Et l\'on voit tel frère qui est en procès avec son frère, et cela devant les infidèles!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 7, 'Certes, c\'est déjà de votre part une faute, que d\'avoir des procès entre vous. Pourquoi n\'endurez-vous pas plutôt une injustice? Pourquoi ne vous laissez-vous pas plutôt dépouiller?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 8, 'Mais c\'est vous qui pratiquez l\'injustice, c\'est vous qui dépouillez! Et c\'est envers des frères que vous agissez de la sorte!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 9, 'Ne savez-vous pas que les injustes n\'hériteront pas le royaume de Dieu?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 10, 'Ne vous abusez point: ni les impudiques, ni les idolâtres, ni les adultères, ni les efféminés, ni les infâmes, ni les voleurs, ni les avares, ni les ivrognes, ni les diffamateurs, ni les rapaces, n\'hériteront le royaume de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 11, 'Et c\'est là ce que vous étiez, quelques-uns d\'entre vous du moins. Mais vous avez été lavés, mais vous avez été sanctifiés, mais vous avez été justifiés, au nom du Seigneur Jésus-Christ et par l\'Esprit de notre Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 12, 'Tout m\'est permis, mais tout n\'est pas utile; tout m\'est permis, mais je ne me laisserai asservir par rien.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 13, 'Les aliments sont pour le ventre et le ventre pour les aliments; et Dieu détruira ceux-ci aussi bien que celui-là. Mais le corps n\'est point pour l\'impudicité: il est pour le Seigneur, et le Seigneur pour le corps;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 14, 'et Dieu, qui a ressuscité le Seigneur, nous ressuscitera aussi par sa puissance.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 15, 'Ne savez-vous pas que vos corps sont les membres de Christ? Prendrai-je donc les membres du Christ pour en faire les membres d\'une prostituée? A Dieu ne plaise!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 16, 'Ne savez-vous pas que celui qui s\'unit à une prostituée devient un même corps avec elle? Car il est dit: «Les deux seront une seule chair.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 17, 'Mais celui qui s\'unit au Seigneur, devient avec lui un même esprit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 18, 'Fuyez l\'impudicité! Quelque péché que l\'homme commette, ce péché est hors du corps; mais celui qui se livre à l\'impudicité pèche contre son propre corps.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 19, 'Ne savez-vous pas que votre corps est le temple du Saint-Esprit, qui est en vous et que vous avez reçu de Dieu, et que vous n\'êtes point à vous-mêmes?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 20, 'Car vous avez été rachetés à un grand prix. Glorifiez donc Dieu dans votre corps.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 1, 'Pour en venir aux questions posées dans votre lettre, j\'estime qu\'il est bon pour un homme de ne point prendre de femme.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 2, 'Cependant, afin d\'éviter toute impudicité, que chaque homme ait sa femme, et que chaque femme ait son mari.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 3, 'Que le mari rende à sa femme ce qu\'il lui doit; et, pareillement, la femme à son mari.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 4, 'La femme ne dispose pas de son corps, mais c\'est le mari; et, pareillement, le mari ne dispose pas de son corps, mais c\'est la femme.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 5, 'Ne vous refusez pas l\'un à l\'autre, à moins que ce ne soit d\'un commun accord, pour un temps, afin de vaquer à la prière; puis, retournez ensemble, de peur que Satan ne vous tente par suite de votre incontinence.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 6, 'C\'est là une concession que je fais, ce n\'est pas un ordre que je donne.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 7, 'Je voudrais que tous les hommes fussent comme moi; mais chacun a reçu de Dieu son don particulier, l\'un celui-ci, l\'autre celui-là.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 8, 'Je dis donc, à ceux qui ne sont pas mariés et aux veuves, qu\'il leur est bon de demeurer comme je suis.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 9, 'Mais s\'ils ne peuvent garder la continence, qu\'ils se marient; car il vaut mieux se marier que de brûler.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 10, 'A ceux qui sont mariés j\'ordonne, — non pas moi, mais le Seigneur, — que la femme ne se sépare pas de son mari.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 11, 'Si elle est séparée, qu\'elle demeure sans se marier, ou qu\'elle se réconcilie avec son mari. Que le mari, de son côté, ne répudie point sa femme.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 12, 'Quant aux autres, ce n\'est pas le Seigneur, mais c\'est moi qui leur dis: Si un frère est marié avec une femme qui ne soit pas du nombre des fidèles, et qu\'elle consente à demeurer avec lui, qu\'il ne la répudie pas.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 13, 'Si une femme a un mari qui ne soit pas du nombre des fidèles, et s\'il consent à demeurer avec elle, qu\'elle ne se sépare pas de lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 14, 'Car le mari non croyant est sanctifié par sa femme, et la femme non croyante est sanctifiée par le mari croyant; autrement, vos enfants seraient impurs, tandis qu\'ils sont saints.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 15, 'Si celui qui n\'est pas croyant veut se séparer, qu\'il se sépare: dans ce cas, le frère ou la soeur ne sont pas liés. Dieu vous a appelés à vivre dans la paix.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 16, 'Et sais-tu, femme, si tu sauveras ton mari? Ou sais-tu, mari, si tu sauveras ta femme?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 17, 'Au reste, que chacun agisse conformément à la condition que le Seigneur lui a donnée en partage, et dans laquelle Dieu l\'a appelé. C\'est là ce que je prescris dans toutes les Églises.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 18, 'Quelqu\'un a-t-il été appelé, étant circoncis? Qu\'il demeure circoncis. Quelqu\'un a-t-il été appelé, étant incirconcis? Qu\'il ne se fasse pas circoncire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 19, 'La circoncision n\'est rien, et l\'incirconcision n\'est rien; ce qui importe, c\'est l\'observation des commandements de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 20, 'Que chacun demeure dans l\'état où il se trouvait quand il fut appelé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 21, 'As-tu été appelé étant esclave? Ne t\'en mets pas en peine; mais aussi, si tu peux devenir libre, profites-en plutôt.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 22, 'Car l\'esclave, qui a été appelé par le Seigneur, est l\'affranchi du Seigneur; de même aussi, celui qui a été appelé étant libre, est l\'esclave de Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 23, 'Vous avez été rachetés à un grand prix; ne devenez point esclaves des hommes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 24, 'Frères, que chacun demeure, devant Dieu, dans la condition où il se trouvait lorsqu\'il a été appelé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 25, 'Pour ce qui est des vierges, je n\'ai point de commandements du Seigneur; mais je donne un conseil, et, par la miséricorde du Seigneur, je suis digne de confiance.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 26, 'J\'estime donc qu\'il est bon, à cause des calamités qui approchent, qu\'il est bon, dis-je, pour un homme, de demeurer comme il est.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 27, 'Es-tu lié à une femme? Ne cherche point à t\'en séparer. N\'es-tu pas lié à une femme? Ne cherche pas de femme.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 28, 'Si pourtant tu te maries, tu ne pèches pas; et si une vierge se marie, elle ne pèche pas; mais ceux qui se marient auront des afflictions dans la chair, et je voudrais vous les épargner.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 29, 'Voici donc, frères, ce que je vous déclare: le temps est court! Que désormais ceux qui ont une femme soient comme s\'ils n\'en avaient point;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 30, 'ceux qui pleurent, comme s\'ils ne pleuraient pas; ceux qui sont dans la joie, comme s\'ils n\'étaient pas dans la joie; ceux qui achètent, comme s\'ils ne possédaient pas;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 31, 'et ceux qui usent de ce monde, comme s\'ils n\'en usaient point; car la figure de ce monde passe.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 32, 'Or, je désire que vous soyez libres de toute préoccupation. Celui qui n\'est pas marié s\'occupe des choses du Seigneur, cherchant à plaire au Seigneur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 33, 'Mais celui qui est marié s\'occupe des choses du monde, cherchant à plaire à sa femme; aussi a-t-il le coeur partagé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 34, 'Il en est de même de la femme mariée et de la vierge: celle qui n\'est pas mariée s\'occupe des choses du Seigneur, pour être sainte de corps et d\'esprit; mais celle qui est mariée s\'occupe des choses du monde, cherchant à plaire à son mari.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 35, 'Je vous dis cela pour votre bien, non pour vous attirer dans mes filets, mais pour vous porter à ce qui convient le mieux, et pour vous attacher sans partage au service du Seigneur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 36, 'Si quelqu\'un croit qu\'il n\'est pas convenable pour sa fille de dépasser la fleur de l\'âge, et qu\'elle doit se marier, il peut faire ce qu\'il voudra, il ne pèche point. Qu\'elle se marie en pareil cas.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 37, 'Mais celui qui, sans subir aucune contrainte, étant maître de faire ce qu\'il veut, a fermement décidé, dans le fond de son coeur, de garder sa fille vierge, celui-là fera bien de s\'en tenir à sa résolution.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 38, 'Ainsi, celui qui marie sa fille, fait bien; mais celui qui ne la marie pas, fait mieux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 39, 'Une femme est liée à son mari aussi longtemps qu\'il vit; si son mari meurt, elle est libre d\'épouser qui elle veut, pourvu que ce soit selon le Seigneur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 40, 'Toutefois, elle sera plus heureuse, à mon avis, si elle demeure comme elle est. Or, j\'estime avoir, moi aussi, l\'Esprit de Dieu!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 1, 'En ce qui concerne les viandes offertes en sacrifice aux idoles, nous sommes éclairés à ce sujet, car nous avons tous de la connaissance. Seulement, la connaissance enfle, tandis que la charité édifie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 2, 'Et si quelqu\'un s\'imagine connaître quelque chose, il n\'a pas encore connu comme il faut connaître.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 3, 'Mais si un homme aime Dieu, il est connu de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 4, 'Ainsi donc, en ce qui concerne le fait de manger des viandes sacrifiées aux idoles, nous savons qu\'il n\'existe pas réellement d\'idoles dans le monde, qu\'il y a un seul Dieu, et qu\'il n\'y en a point d\'autre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 5, 'On prétend, il est vrai, qu\'il y a d\'autres dieux, soit dans le ciel, soit sur la terre — et, en effet, on adore plusieurs dieux et plusieurs seigneurs. —');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 6, 'Mais pour nous, nous avons un seul Dieu, le Père, de qui procèdent toutes choses, et nous sommes pour lui; et un seul Seigneur, Jésus-Christ, par qui sont toutes choses, et nous sommes par lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 7, 'Mais tous n\'ont pas la connaissance. Quelques-uns, avec l\'idée qu\'ils se font toujours de l\'idole, mangent de ces viandes en les considérant comme sacrifiées à une idole; et leur conscience, qui est faible, en est souillée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 8, 'Or, ce n\'est pas un aliment qui nous rendra agréables à Dieu; si nous en mangeons, nous ne gagnons rien, et si nous n\'en mangeons pas, nous ne perdons rien.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 9, 'Mais prenez garde que la liberté que vous avez ne devienne, pour les faibles, une occasion de chute.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 10, 'Car, si quelqu\'un te voit, toi qui as de la connaissance, assis à table dans un temple d\'idoles, cet homme, dont la conscience est faible, ne sera-t-il pas entraîné à manger de ce qui est sacrifié aux idoles?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 11, 'Et ainsi, avec ta connaissance, tu es une cause de perdition pour le faible, ce frère pour lequel Christ est mort!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 12, 'Quand vous péchez ainsi contre les frères, et que vous blessez leur conscience qui est faible, vous péchez contre Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 13, 'C\'est pourquoi, si un aliment scandalise mon frère, je ne mangerai jamais de viande, afin de ne pas être en scandale à mon frère.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 1, 'Ne suis-je pas libre? Ne suis-je pas apôtre? N\'ai-je pas vu Jésus, notre Seigneur? N\'êtes-vous pas mon oeuvre dans le Seigneur?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 2, 'Si pour d\'autres je ne suis pas apôtre, je le suis au moins pour vous; car vous êtes le sceau de mon apostolat dans le Seigneur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 3, 'C\'est là ma défense contre ceux qui m\'accusent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 4, 'N\'avons-nous pas le droit de manger et de boire?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 5, 'N\'avons-nous pas le droit de conduire partout avec nous une soeur comme épouse, ainsi que le font les autres apôtres, et les frères du Seigneur, et Céphas?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 6, 'Ou bien, est-ce que moi seul et Barnabas, nous n\'avons pas le droit de ne point travailler?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 7, 'Qui donc va à la guerre à ses propres frais? Qui plante une vigne, sans en manger le fruit? Ou encore, qui fait paître un troupeau, sans se nourrir du lait de ce troupeau?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 8, 'Est-ce seulement d\'après l\'usage des hommes que je parle ainsi? La loi ne dit-elle pas la même chose?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 9, 'Car il est écrit dans la loi de Moïse: «Tu n\'emmuselleras point le boeuf qui foule le grain.» Est-ce des boeufs que Dieu s\'occupe?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 10, 'N\'est-ce pas, en réalité, pour nous qu\'il dit cela? Oui, c\'est pour nous qu\'il est écrit que celui qui laboure, doit labourer avec espérance, et que celui qui foule le grain, doit le fouler dans l\'espérance d\'en avoir sa part.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 11, 'Nous avons semé pour vous les biens spirituels; serions-nous très exigeants, si nous voulions recueillir vos biens matériels?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 12, 'Si d\'autres ont ce droit sur vous, ne l\'avons-nous pas à plus forte raison? Cependant, nous n\'avons pas usé de ce droit; mais nous supportons tout, afin de n\'apporter aucun obstacle à l\'Évangile du Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 13, 'Ne savez-vous pas que ceux qui font le service sacré, mangent dans ce qui est offert dans le temple, et que ceux qui servent à l\'autel, ont part à l\'autel?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 14, 'De même, le Seigneur a ordonné que ceux qui annoncent l\'Évangile vivent de l\'Évangile.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 15, 'Pour moi, je n\'ai usé d\'aucun de ces droits, et je n\'écris point cela pour les réclamer; car j\'aimerais mieux mourir que de me laisser enlever ce sujet de gloire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 16, 'Si j\'annonce l\'Évangile, je n\'ai pas sujet de m\'en glorifier, parce que la nécessité m\'en est imposée; et malheur à moi si je n\'annonce pas l\'Évangile!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 17, 'Si je le fais de bon coeur, j\'en ai la récompense; si je le fais contre mon gré, la charge ne m\'en est pas moins confiée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 18, 'Quelle est donc ma récompense? C\'est, en annonçant l\'Évangile, de l\'offrir gratuitement, sans user des droits que j\'ai comme prédicateur de l\'Évangile.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 19, 'Libre, en effet, à l\'égard de tous, je me suis assujetti à tous, afin d\'en gagner un plus grand nombre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 20, 'Avec les Juifs je me suis comporté comme un Juif, afin de gagner les Juifs; avec ceux qui sont sous la loi, comme si j\'étais sous la loi, — bien que je ne sois plus moi-même sous la loi, — afin de gagner ceux qui sont sous la loi;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 21, 'avec ceux qui étaient sans loi, comme si j\'eusse été sans loi, — bien que je ne sois pas sans loi à l\'égard de Dieu, puisque je suis sous la loi de Christ, — afin de gagner ceux qui étaient sans loi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 22, 'J\'ai été faible avec les faibles, afin de gagner les faibles; je me suis fait tout à tous, afin d\'en sauver à tout prix quelques-uns.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 23, 'Et tout ce que je fais, je le fais à cause de l\'Évangile, afin d\'y avoir part, moi aussi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 24, 'Ne savez-vous pas que, dans les courses du stade, tous courent, mais qu\'un seul remporte le prix? Courez donc de manière à le, remporter.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 25, 'Tous ceux qui combattent, s\'imposent toutes sortes d\'abstinences; et ils le font pour une couronne corruptible. Mais nous, nous le faisons pour une couronne incorruptible.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 26, 'Ainsi donc, je cours, et ce n\'est pas à l\'aventure; je frappe, et ce n\'est pas en l\'air;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 27, 'mais je traite durement mon corps, et je le tiens assujetti, de peur qu\'après avoir prêché aux autres, je ne sois moi-même rejeté.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 1, 'En effet, mes frères, je ne veux pas que vous ignoriez que nos pères ont tous été sous la nuée, qu\'ils ont tous passé à travers la mer,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 2, 'qu\'ils ont tous été baptisés en Moïse dans la nuée et dans la mer,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 3, 'qu\'ils ont tous mangé du même aliment spirituel,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 4, 'et qu\'ils ont tous bu du même breuvage spirituel; car ils buvaient à un rocher spirituel qui les suivait, et ce rocher était le Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 5, 'Mais la plupart d\'entre eux ne furent point agréables à Dieu, puisqu\'ils tombèrent morts dans le désert.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 6, 'Tout cela est arrivé pour nous servir d\'exemple, afin que nous ne nous abandonnions pas aux mauvaises convoitises, comme ils s\'y abandonnèrent eux-mêmes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 7, 'Ne soyez pas non plus idolâtres, comme le furent quelques-uns d\'entre eux, ainsi qu\'il est écrit: «Le peuple s\'assit pour manger et pour boire; puis il se leva pour se divertir.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 8, 'Ne nous livrons pas à l\'impudicité, comme quelques-uns d\'entre eux s\'y livrèrent; et vingt-trois mille tombèrent morts en un seul jour.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 9, 'Ne tentons pas le Seigneur, comme quelques-uns d\'entre eux le tentèrent; et ils périrent par les serpents.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 10, 'Et ne murmurez point, comme quelques-uns d\'entre eux murmurèrent; et ils périrent par l\'exterminateur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 11, 'Ces événements ont une signification typique, et ils ont été rapportés pour nous avertir, nous qui touchons à la fin des temps.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 12, 'Ainsi donc, que celui qui croit être debout, prenne garde qu\'il ne tombe.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 13, 'Aucune des tentations qui vous sont survenues n\'a été au-dessus des forces humaines. Dieu est fidèle, et il ne permettra pas que vous soyez jamais tentés au-delà de vos forces; mais il vous aidera à triompher de la tentation, en vous donnant la force de la supporter.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 14, 'C\'est pourquoi, mes bien-aimés, fuyez l\'idolâtrie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 15, 'Je vous parle comme à des personnes intelligentes; jugez vous-mêmes de ce que je dis.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 16, 'La coupe de bénédiction que nous bénissons, n\'est-elle pas la communion au sang du Christ? Le pain que nous rompons, n\'est-il pas la communion au corps du Christ?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 17, 'Puisqu\'il y a un seul pain, nous ne faisons qu\'un seul corps, tout en étant plusieurs; car nous avons tous part au même pain.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 18, 'Voyez l\'Israël selon la chair: ceux qui mangent les victimes, n\'ont-ils pas communion avec l\'autel?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 19, 'Est-ce à dire que ce qui est sacrifié à une idole ait quelque valeur, ou que l\'idole soit quelque chose? Assurément non;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 20, 'mais ce que les Païens sacrifient, ils le sacrifient aux démons, et non pas à Dieu. Or, je ne veux pas que vous ayez communion avec les démons.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 21, 'Vous ne pouvez boire à la coupe du Seigneur et à la coupe des démons; vous ne pouvez participer à la table du Seigneur et à la table des démons.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 22, 'Ou bien, voulons-nous provoquer la jalousie du Seigneur? Sommes-nous plus forts que lui?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 23, 'Tout est permis, mais tout n\'est pas utile; tout est permis, mais tout n\'édifie pas!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 24, 'Que personne ne cherche son propre intérêt, mais que chacun cherche celui d\'autrui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 25, 'Mangez de tout ce qui se vend à la boucherie, sans poser aucune question à ce sujet, par motif de conscience;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 26, 'car la terre est au Seigneur, avec tout ce qu\'elle contient.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 27, 'Si un infidèle vous invite et que vous vouliez aller chez lui, mangez de tout ce qu\'on vous présente, sans poser aucune question par motif de conscience.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 28, 'Mais si quelqu\'un vous dit: «Ceci a été offert en sacrifice» — alors, n\'en mangez pas, à cause de celui qui vous a avertis, et aussi par conscience:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 29, 'je ne parle pas de votre conscience, mais de celle de cet homme-là. Pourquoi, en effet, ma liberté tomberait-elle sous le jugement de la conscience d\'autrui?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 30, 'Si je mange avec actions de grâces, pourquoi serais-je blâmé au sujet d\'un repas pour lequel je rends grâces?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 31, 'Soit donc que vous mangiez, soit que vous buviez, ou que vous fassiez quelque autre chose, faites tout pour la gloire de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 32, 'Ne donnez de scandale ni aux Juifs, ni aux Grecs, ni à l\'Église de Dieu;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 33, 'faites comme moi, qui m\'efforce de complaire à tous en toutes choses, cherchant, non mon propre avantage, mais celui du plus grand nombre, afin qu\'ils soient sauvés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 1, 'Soyez mes imitateurs, comme je le suis moi-même de Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 2, 'Je vous loue donc de ce que vous vous souvenez de moi en toute occasion, et de ce que vous retenez fidèlement les instructions que je vous ai transmises.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 3, 'Cependant, je veux que vous le sachiez: le Christ est le chef de tout homme, et l\'homme est le chef de la femme, et Dieu est le chef du Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 4, 'Tout homme qui prie ou qui prophétise, la tête couverte, déshonore son chef.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 5, 'Mais toute femme qui prie ou qui prophétise sans avoir la tête voilée, déshonore son chef; c\'est exactement comme si elle était rasée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 6, 'Si une femme n\'est pas voilée, qu\'elle se coupe aussi les cheveux. Mais s\'il est malséant pour une femme d\'avoir les cheveux coupés ou la tête rasée, qu\'elle mette un voile.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 7, 'L\'homme, en effet, étant l\'image et la gloire de Dieu, ne doit pas se couvrir la tête; mais la femme est la gloire de l\'homme.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 8, 'Car l\'homme n\'a pas été tiré de la femme, mais la femme de l\'homme;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 9, 'et l\'homme n\'a pas été créé à cause de la femme, mais la femme à cause de l\'homme.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 10, 'C\'est pourquoi, la femme doit avoir sur la tête, à cause des anges, une marque de l\'autorité dont elle dépend.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 11, 'Toutefois, dans le Seigneur, la femme ne va pas sans l\'homme, ni l\'homme sans la femme;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 12, 'car, si la femme a été tirée de l\'homme, l\'homme aussi naît de la femme, et tout vient de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 13, 'Jugez-en vous-mêmes: est-il bienséant qu\'une femme prie Dieu sans être voilée?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 14, 'La nature elle-même ne vous enseigne-t-elle pas qu\'il est honteux, pour l\'homme, de laisser croître sa chevelure?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 15, '— Au contraire, si la femme porte ses cheveux longs, c\'est un honneur pour elle, parce que sa chevelure lui a été donnée pour lui servir de voile.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 16, 'Au reste, si quelqu\'un se plaît à contester, nous n\'avons pas cette habitude, ni les Églises de Dieu non plus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 17, 'En vous donnant cet avertissement, je ne saurais vous louer de ce que vos assemblées, au lieu de vous rendre meilleurs, vous rendent pires.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 18, 'Et d\'abord, on m\'affirme que, lorsque vous avez, dans l\'Eglise, une assemblée, il se produit parmi vous des divisions; et j\'en crois bien quelque chose.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 19, 'En effet, il faut même qu\'il y ait parmi vous des partis différents, afin qu\'on puisse reconnaître ceux d\'entre vous qui sont vraiment fidèles.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 20, 'Quand donc vous vous réunissez dans un même lieu, ce n\'est plus la Cène du Seigneur que vous prenez;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 21, 'car, lorsqu\'on se met à manger, chacun se hâte de prendre son repas particulier, en sorte que l\'un a faim, tandis que l\'autre se livre à des excès.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 22, 'N\'avez-vous pas des maisons pour manger et pour boire? Ou méprisez-vous l\'Église de Dieu, et voulez-vous faire honte à ceux qui n\'ont rien? Que vous dirai-je? Dois-je vous louer? Non, en cela, je ne vous loue point.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 23, 'En effet, j\'ai appris du Seigneur ce que je vous ai aussi enseigné: c\'est que le Seigneur Jésus, dans la nuit où il fut livré, prit du pain,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 24, 'et, après avoir rendu grâces, il le rompit et dit: Ceci est mon corps, qui est donné pour vous; faites ceci en mémoire de moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 25, 'De même aussi, après avoir soupé, il prit la coupe et dit: Cette coupe est la nouvelle alliance en mon sang; faites ceci, toutes les fois que vous en boirez, en mémoire de moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 26, 'Ainsi, toutes les fois que vous mangez de ce pain, et que vous buvez de cette coupe, vous annoncez la mort du Seigneur, jusqu\'à ce qu\'il vienne.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 27, 'C\'est pourquoi, quiconque mangera le pain ou boira la coupe du Seigneur indignement, sera coupable envers le corps et le sang du Seigneur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 28, 'Que chacun donc s\'éprouve soi-même, et qu\'ainsi il mange de ce pain et boive de cette coupe;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 29, 'car celui qui en mange et qui en boit sans discerner le corps du Seigneur, mange et boit son propre jugement.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 30, 'C\'est pour cela qu\'il y a parmi vous beaucoup d\'infirmes et de malades, et que plusieurs sont morts.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 31, 'Si nous savions nous juger nous-mêmes, nous ne serions pas jugés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 32, 'Mais quand nous sommes jugés par le Seigneur, nous sommes châtiés par lui, afin que nous ne soyons pas condamnés avec le monde.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 33, 'Ainsi donc, mes frères, lorsque vous vous réunissez pour manger ensemble, attendez-vous les uns les autres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 34, 'Et si quelqu\'un a faim, qu\'il mange chez lui, afin que vous ne vous assembliez pas pour attirer un jugement sur vous. Quant aux autres points, je les réglerai lorsque je serai arrivé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 1, 'En ce qui concerne les dons spirituels, je ne veux pas, frères, que vous soyez dans l\'ignorance.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 2, 'Vous savez que, lorsque vous étiez des Païens, vous étiez entraînés vers les idoles muettes, au gré de ceux qui vous conduisaient.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 3, 'C\'est pourquoi, je vous le déclare, aucun homme, parlant par l\'Esprit de Dieu, ne dit: Que Jésus soit anathème! Et personne ne peut dire: Jésus est le Seigneur! — si ce n\'est par le Saint-Esprit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 4, 'Or, il y a diversité de dons, mais il n\'y a qu\'un même Esprit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 5, 'Il y a diversité de ministères, mais il n\'y a qu\'un même Seigneur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 6, 'Il y a diversité d\'opérations, mais il n\'y a qu\'un même Dieu, qui opère tout en tous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 7, 'Et l\'Esprit, qui se manifeste en chacun, lui est donné pour l\'utilité commune.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 8, 'En effet, à l\'un est donnée, par le moyen de l\'Esprit, la parole de sagesse; à l\'autre, la parole de connaissance, selon le même Esprit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 9, 'A l\'un est donnée la foi, par le même Esprit; à un autre, les dons de guérison, par ce même Esprit;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 10, 'à un autre, le pouvoir d\'opérer des miracles; à un autre, la prophétie; à un autre, le discernement des esprits; à l\'un, le don de parler diverses langues, à un autre, l\'interprétation de ces langues.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 11, 'Tout cela est l\'oeuvre d\'un seul et même Esprit, qui distribue ses dons à chacun en particulier, comme il le veut.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 12, 'En effet, comme le corps est un, tout en ayant plusieurs membres, et comme tous les membres du corps, bien qu\'ils soient plusieurs, ne forment qu\'un seul corps, ainsi en est-il du Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 13, 'Car nous avons tous été baptisés d\'un même Esprit, pour former un même corps, soit Juifs, soit Grecs, soit esclaves, soit hommes libres; et nous avons tous été abreuvés d\'un même Esprit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 14, 'Aussi bien, le corps n\'est-il pas composé d\'un seul membre, mais de plusieurs.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 15, 'Quand même le pied dirait: Parce que je ne suis pas la main, je ne suis pas du corps, — il n\'en ferait pas moins partie du corps.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 16, 'Et quand même l\'oreille dirait: Parce que je ne suis pas l\'oeil, je ne suis pas du corps, — elle n\'en ferait pas moins partie du corps.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 17, 'Si tout le corps était oeil, où serait l\'ouïe, où serait l\'odorat?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 18, 'Mais voici que Dieu a disposé les membres de notre corps, en donnant à chacun d\'eux la place qu\'il a trouvé bon de lui assigner.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 19, 'S\'ils n\'étaient tous qu\'un seul membre, où serait le corps?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 20, 'Il y a donc plusieurs membres, mais un seul corps.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 21, 'L\'oeil ne peut pas dire à la main: Je n\'ai pas besoin de toi; ni la tête dire aux pieds: Je n\'ai pas besoin de vous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 22, 'Bien au contraire, les membres du corps qui paraissent les plus faibles, sont des membres nécessaires.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 23, 'Ceux que nous estimons les moins honorables dans le corps, sont ceux que nous entourons de plus d\'honneur; les moins décents sont ceux que nous traitons avec le plus de décence,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 24, 'tandis que ceux qui sont décents n\'en ont pas besoin. Mais Dieu a disposé le corps de manière à donner plus d\'honneur à ce qui en manquait,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 25, 'afin qu\'il n\'y ait point de division dans le corps, mais que les membres aient un égal souci les uns des autres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 26, 'Aussi, lorsqu\'un des membres souffre, tous les membres souffrent avec lui; et lorsqu\'un des membres est honoré, tous les membres s\'en réjouissent avec lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 27, 'Or, vous êtes le corps de Christ, et vous êtes ses membres, chacun pour sa part.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 28, 'Dieu a établi dans l\'Église, premièrement des apôtres, secondement des prophètes, en troisième lieu des docteurs, ensuite ceux qui font des miracles, puis ceux qui ont le don de guérir, de secourir, d\'administrer, de parler diverses langues.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 29, 'Tous sont-ils apôtres? Tous sont-ils prophètes? Tous sont-ils docteurs? Tous font-ils des miracles?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 30, 'Tous ont-ils les dons de guérison? Tous parlent-ils en langues inconnues? Tous interprètent-ils?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 31, 'Aspirez aux dons les plus grands. Et maintenant, je vais vous montrer la voie la plus excellente.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 1, 'Quand je parlerais les langues des hommes et celles des anges, si je n\'ai pas la charité, je ne suis qu\'un airain qui résonne, ou une cymbale qui retentit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 2, 'Quand j\'aurais le don de prophétie, et que je connaîtrais tous les mystères et toute la science; quand j\'aurais toute la foi jusqu\'à transporter des montagnes, si je n\'ai pas la charité, je ne suis rien.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 3, 'Quand je distribuerais tous mes biens pour la nourriture des pauvres, quand je livrerais mon corps pour être brûlé, si je n\'ai pas la charité, cela ne me sert de rien.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 4, 'La charité est patiente; la charité est pleine de bonté. La charité n\'est point envieuse; elle n\'est pas présomptueuse, elle ne s\'enfle pas d\'orgueil.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 5, 'Elle ne fait rien de malhonnête; elle ne cherche pas son intérêt; elle ne s\'aigrit pas; elle ne soupçonne point le mal.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 6, 'Elle ne se réjouit pas de l\'injustice, mais elle met sa joie dans la vérité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 7, 'Elle excuse tout, elle croit tout, elle espère tout, elle supporte tout.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 8, 'La charité ne périt jamais. Les prophéties prendront fin, le don des langues cessera, la connaissance sera abolie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 9, 'Car nous ne connaissons qu\'imparfaitement, et nous ne prophétisons qu\'imparfaitement;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 10, 'mais quand la perfection sera venue, alors ce qui est imparfait sera aboli.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 11, 'Lorsque j\'étais enfant, je parlais comme un enfant, je pensais comme un enfant, je raisonnais comme un enfant; lorsque je suis devenu homme, je me suis défait de ce qui tenait de l\'enfant.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 12, 'Aujourd\'hui nous voyons comme dans un miroir, confusément: alors nous verrons face à face! Aujourd\'hui je connais imparfaitement: alors je connaîtrai comme j\'ai été connu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 13, 'Maintenant donc, ces trois choses demeurent: la foi, l\'espérance et la charité; mais la plus grande des trois est la charité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 1, 'Recherchez avec ardeur la charité. Aspirez aussi aux dons spirituels, et surtout au don de prophétie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 2, 'Car celui qui parle en langue inconnue ne parle pas aux hommes, mais à Dieu, puisque personne ne le comprend, — c\'est sous l\'inspiration de l\'Esprit qu\'il prononce des paroles mystérieuses —,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 3, 'tandis que celui qui prophétise, parle aux hommes pour les édifier, les exhorter et les consoler.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 4, 'Celui qui parle en langue inconnue, s\'édifie lui-même; mais celui qui prophétise, édifie l\'Église.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 5, 'Je désire que vous parliez tous en langues inconnues, mais je désire encore plus que vous prophétisiez. Celui qui prophétise est supérieur à celui qui parle en langues inconnues, à moins que ce dernier n\'interprète, pour que l\'Église en reçoive de l\'édification.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 6, 'En effet, mes frères, si je venais parmi vous, parlant en langues inconnues, et que ma parole ne vous donnât ni révélation, ni connaissance, ni prophétie, ni instruction, — en quoi vous serais-je utile?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 7, 'Ainsi en est-il, même des objets inanimés qui rendent un son, tels que la flûte ou la harpe: s\'ils ne donnent pas des sons distincts, comment reconnaîtra-t-on l\'air qui est joué sur la flûte ou sur la harpe?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 8, 'Et si la trompette rend un son confus, qui se préparera au combat?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 9, 'Vous de même, si, avec votre langue, vous ne faites pas entendre un discours intelligible, comment saura-t-on ce que vous dites? Vous parlerez en l\'air.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 10, 'Il y a dans le monde tant de sortes de mots, dont chacun a sa signification!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 11, 'Si donc je ne sais pas ce que ces mots signifient, je serai un barbare pour celui qui parle, et celui qui parle sera un barbare pour moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 12, 'Ainsi, puisque vous désirez avec ardeur les dons spirituels, cherchez à en avoir abondamment pour l\'édification de l\'Église.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 13, 'C\'est pourquoi, que celui qui parle en langue inconnue, prie, afin de pouvoir l\'interpréter.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 14, 'Car, si je prie en langue inconnue, mon esprit est en prière, mais mon intelligence reste inactive.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 15, 'Que ferai-je donc? Je prierai sous l\'inspiration de l\'Esprit, mais je prierai aussi avec mon intelligence. Je chanterai sous l\'inspiration de l\'Esprit, mais je chanterai aussi avec mon intelligence.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 16, 'Autrement, si tu ne rends grâces qu\'en esprit, comment celui qui est dans les rangs des simples auditeurs répondra-t-il «Amen» à tes actions de grâces, puisqu\'il ne sait pas ce que tu dis?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 17, 'Sans doute, tes actions de grâces sont excellentes; mais l\'autre n\'en est pas édifié.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 18, 'Je bénis Dieu de ce que je possède, plus que vous tous, le don de parler en langue inconnue;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 19, 'mais je préfère prononcer dans l\'Église cinq paroles avec toute mon intelligence, afin d\'instruire aussi les autres, plutôt que prononcer dix mille paroles en langue inconnue.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 20, 'Frères, ne soyez pas des enfants, pour l\'intelligence; mais pour la malice, oui, soyez de petits enfants. Quant à l\'intelligence, soyez des hommes faits.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 21, 'Il est écrit dans la loi: «C\'est par des hommes parlant une langue étrangère, c\'est par la bouche d\'étrangers, que je m\'adresserai à ce peuple; et même alors, ils ne m\'écouteront pas, dit le Seigneur.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 22, 'Ainsi, les langues sont un signe, non pour les croyants, mais pour les incrédules; tandis que la prophétie est un signe, non pour les incrédules, mais pour les croyants.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 23, 'Si donc, l\'Église entière étant réunie dans un même lieu, tous parlent en langues inconnues, et qu\'il entre de simples auditeurs ou des incrédules, ne diront-ils pas que vous êtes fous?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 24, 'Mais si tous prophétisent, et qu\'il entre un incrédule ou un simple auditeur, il est convaincu par tous, jugé par tous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 25, 'Les secrets de son coeur sont dévoilés; alors il se prosternera la face contre terre, il adorera Dieu, et il proclamera que Dieu est réellement parmi vous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 26, 'Qu\'est-ce à dire, frères? Lorsque vous vous assemblez, quelqu\'un de vous a-t-il un cantique, ou une instruction, ou une révélation; a-t-il à parler en langue inconnue, ou à donner une interprétation? Que tout se fasse pour l\'édification.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 27, 'S\'il y en a qui parlent en langue inconnue, qu\'ils ne soient que deux ou trois, tout au plus; qu\'ils parlent chacun à son tour, et qu\'un seul interprète.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 28, 'S\'il n\'y a pas d\'interprète, qu\'ils se taisent dans l\'Église, et qu\'ils parlent à eux-mêmes et à Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 29, 'Qu\'il n\'y ait aussi que deux ou trois prophètes qui parlent, et que les autres soient juges de leurs prophéties.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 30, 'Cependant, si un autre de ceux qui sont assis a une révélation, que le premier se taise.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 31, 'Car vous pouvez tous prophétiser l\'un après l\'autre, afin que tous soient instruits et que tous soient exhortés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 32, 'Or, les esprits des prophètes sont soumis aux prophètes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 33, 'Dieu, en effet, n\'est pas un Dieu de confusion, mais un Dieu de paix.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 34, 'Comme dans toutes les Églises des saints, que les femmes se taisent dans vos assemblées: il ne leur est pas permis d\'y parler, mais elles doivent être soumises, comme aussi la Loi le dit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 35, 'Si elles désirent s\'instruire sur quelque chose, que chacune d\'elles interroge son mari à la maison; car il n\'est pas convenable pour une femme de parler dans l\'Église.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 36, 'Est-ce de chez vous que la parole de Dieu est venue, ou n\'est-elle parvenue qu\'à vous seuls?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 37, 'Si quelqu\'un pense être prophète ou inspiré, qu\'il reconnaisse que ce que je vous écris est un commandement du Seigneur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 38, 'Mais si quelqu\'un veut l\'ignorer, qu\'il l\'ignore!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 39, 'Ainsi donc, mes frères, aspirez au don de prophétie, et n\'empêchez point de parler en langues inconnues.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 40, 'Mais que tout se fasse avec bienséance et avec ordre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 1, 'Je vous rappelle, frères, l\'Évangile que je vous ai annoncé et que vous avez reçu, dans lequel aussi vous demeurez fermes,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 2, 'et par lequel vous êtes sauvés, si vous le retenez tel que je vous l\'ai annoncé. — autrement, vous auriez cru en vain!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 3, 'En effet, je vous ai transmis, avant toutes choses, cet enseignement que j\'ai reçu moi-même: c\'est que Christ est mort pour nos péchés, selon les Écritures;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 4, 'il a été enseveli; il est ressuscité le troisième jour, selon les Écritures;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 5, 'il a été vu de Céphas, ensuite des Douze.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 6, 'Après cela, il a été vu, en une seule fois, de plus de cinq cents frères, dont la plupart sont encore vivants aujourd\'hui, et dont quelques-uns sont morts.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 7, 'Puis il a été vu de Jacques, et ensuite de tous les apôtres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 8, 'Enfin, après eux tous, il s\'est aussi fait voir à moi, comme à je ne sais quel avorton.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 9, 'Car je suis le moindre des apôtres, moi qui ne suis pas digne d\'être appelé apôtre, puisque j\'ai persécuté l\'Église de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 10, 'Mais c\'est par la grâce de Dieu que je suis ce que je suis, et la grâce qu\'il m\'a faite n\'a pas été vaine. Au contraire, j\'ai travaillé beaucoup plus qu\'eux tous, non pas moi pourtant, mais la grâce de Dieu qui est avec moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 11, 'Ainsi donc, que ce soit moi, que ce soit eux, voilà ce que nous prêchons et ce que vous avez cru.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 12, 'Or, si l\'on prêche que Christ est ressuscité des morts, comment quelques-uns d\'entre vous peuvent-ils dire qu\'il n\'y a point de résurrection des morts?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 13, 'S\'il n\'y a point de résurrection des morts. Christ non plus n\'est pas ressuscité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 14, 'Et si Christ n\'est pas ressuscité, notre prédication est donc vaine, et votre foi aussi est vaine.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 15, 'Il se trouve même que nous sommes de faux témoins de Dieu, puisque nous avons témoigné, en contradiction avec Dieu, qu\'il a ressuscité le Christ, — tandis qu\'il ne l\'a pas ressuscité, s\'il est vrai que les morts ne ressuscitent pas.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 16, 'En effet, si les morts ne ressuscitent pas. Christ n\'est pas non plus ressuscité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 17, 'Et si Christ n\'est pas ressuscité, votre foi est vaine; vous êtes encore dans vos péchés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 18, 'Alors aussi, ceux qui se sont endormis en Christ sont à jamais perdus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 19, 'Si nous n\'avons d\'espérance en Christ que pour cette vie seulement, nous sommes les plus misérables de tous les hommes!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 20, 'Mais maintenant, Christ est ressuscité des morts, et il est les prémices de ceux qui sont morts.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 21, 'En effet, puisque la mort est venue par un homme, c\'est par un homme aussi qu\'est venue la résurrection des morts.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 22, 'Comme tous meurent en Adam, de même tous revivront en Christ,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 23, 'mais chacun à son propre rang: Christ est les prémices; puis ceux qui sont à Christ ressusciteront à son avènement.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 24, 'Ensuite viendra la fin, quand il remettra le royaume à Dieu, le Père, après avoir détruit tout empire, toute domination et toute puissance;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 25, 'car il faut qu\'il règne, jusqu\'à ce qu\'il ait mis tous ses ennemis sous ses pieds.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 26, '— L\'ennemi qui sera détruit le dernier, c\'est la mort. —');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 27, 'Dieu, en effet, a mis toutes choses sous ses pieds; mais quand il est dit que toutes choses lui sont soumises, il est évident qu\'il faut excepter Celui qui lui a soumis toutes choses.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 28, 'Puis, quand toutes choses lui auront été soumises, alors le Fils lui-même sera soumis à Celui qui lui a soumis toutes choses, afin que Dieu soit tout en tous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 29, 'Autrement, que feraient ceux qui se font baptiser pour les morts? Si absolument les morts ne ressuscitent pas, pourquoi se font-ils baptiser pour eux?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 30, 'Et pourquoi nous-mêmes sommes-nous à toute heure en péril?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 31, 'Je suis chaque jour exposé à la mort, aussi vrai, frères, que vous êtes pour moi un sujet de gloire en Jésus-Christ, notre Seigneur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 32, 'Si c\'est dans des vues humaines que j\'ai combattu contre les bêtes à Éphèse, quel avantage m\'en revient-il? Si les morts ne ressuscitent pas, mangeons et buvons, car demain nous mourrons!..');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 33, 'Ne vous y trompez pas: les mauvaises compagnies corrompent les bonnes moeurs.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 34, 'Revenez à la raison, comme il convient, et ne péchez point; car il y en a qui n\'ont aucune connaissance de Dieu, je le dis à votre honte.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 35, 'Mais quelqu\'un dira: Comment les morts ressuscitent-ils, et avec quel corps reviennent-ils?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 36, 'Insensé, ce que tu sèmes ne reprend pas vie, si d\'abord il ne meurt.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 37, 'Et quant à ce que tu sèmes, ce n\'est pas le corps qui naîtra, que tu sèmes, mais un simple grain, de blé peut-être, ou de quelque autre semence.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 38, 'Et Dieu lui donne le corps qu\'il a trouvé bon de lui donner, à chaque semence le corps qui lui est propre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 39, 'Toute chair n\'est pas la même chair; mais autre est la chair des hommes, autre la chair des bêtes, autre celle des oiseaux, autre celle des poissons.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 40, 'Il y a aussi des corps célestes et des corps terrestres; mais l\'éclat des corps célestes est différent de celui des corps terrestres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 41, 'Autre est l\'éclat du soleil, autre l\'éclat de la lune, autre l\'éclat des étoiles; et même une étoile diffère en éclat d\'une autre étoile.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 42, 'Il en est ainsi de la résurrection des morts. Le corps est semé corruptible, il ressuscite incorruptible;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 43, 'il est semé méprisable, il ressuscite glorieux; il est semé infirme, il ressuscite plein de force;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 44, 'il est semé corps animal, il ressuscite corps spirituel. S\'il y a un corps animal, il y a aussi un corps spirituel;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 45, 'c\'est ainsi qu\'il est écrit: «Le premier homme, Adam, a été fait âme vivante» Le dernier Adam est esprit vivifiant.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 46, 'Mais ce n\'est pas ce qui est spirituel qui vient le premier, c\'est ce qui est animal; ce qui est spirituel vient ensuite.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 47, 'Le premier homme, étant de la terre, est terrestre; le second homme est du ciel.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 48, 'Tel est le terrestre, tels sont aussi les terrestres; tel est le céleste, tels sont aussi les célestes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 49, 'Et comme nous avons porté l\'image de celui qui est terrestre, nous porterons aussi l\'image de celui qui est. céleste.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 50, 'Ce que j\'affirme, frères, c\'est que la chair et le sang ne peuvent hériter le royaume de Dieu, et que la corruption n\'hérite point l\'incorruptibilité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 51, 'Voici un mystère que je vous révèle: nous ne mourrons pas tous, mais tous nous serons changés,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 52, 'en un instant, en un clin d\'oeil, au son de la dernière trompette; car la trompette sonnera, et les morts ressusciteront incorruptibles, et nous serons changés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 53, 'Il faut, en effet, que ce corps corruptible revête l\'incorruptibilité, et que ce corps mortel revête l\'immortalité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 54, 'Et quand ce corps corruptible aura revêtu l\'incorruptibilité, et que ce corps mortel aura revêtu l\'immortalité, alors s\'accomplira cette parole de l\'Ecriture: «La mort a été engloutie dans la victoire.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 55, 'mort, où est ta victoire? mort, où est ton aiguillon?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 56, 'Or, l\'aiguillon de la mort, c\'est le péché; et la puissance du péché, c\'est la loi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 57, 'Mais grâces soient rendues à Dieu, qui nous donne la victoire par notre Seigneur Jésus-Christ!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 58, 'Ainsi donc, mes frères bien-aimés, soyez fermes, inébranlables, et abondez toujours plus dans l\'oeuvre du Seigneur, sachant que votre travail n\'est pas vain auprès du Seigneur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 1, 'En ce qui concerne la collecte qui se fait pour les saints, suivez, vous aussi, les directions que j\'ai données aux Églises de la Galatie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 2, 'Que chacun de vous, le premier jour de la semaine, mette en réserve chez lui ce qu\'il aura pu épargner, afin qu\'on n\'attende pas mon arrivée pour faire les collectes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 3, 'Quand je serai arrivé, j\'enverrai avec des lettres ceux que vous aurez choisis, pour porter vos libéralités à Jérusalem.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 4, 'Et si la chose mérite que j\'y aille moi-même, ils viendront avec moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 5, 'Or, j\'irai chez vous, après avoir passé par la Macédoine; car je passerai par la Macédoine.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 6, 'Peut-être m\'arrêterai-je chez vous, ou même y passerai-je l\'hiver, afin que vous me fassiez conduire là où je désirerai aller.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 7, 'Je ne veux pas cette fois vous voir seulement en passant; j\'espère bien demeurer quelque temps avec vous, si le Seigneur le permet.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 8, 'Mais je resterai à Éphèse jusqu\'à la Pentecôte;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 9, 'car une porte y est ouverte toute grande à mon activité, et les adversaires sont nombreux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 10, 'Si Timothée vient vous voir, veillez à ce qu\'il n\'ait rien à craindre parmi vous; car il travaille à l\'oeuvre du Seigneur, comme moi-même.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 11, 'Que personne donc ne lui manque d\'égards, et faites-le reconduire en paix, afin qu\'il vienne me rejoindre; car je l\'attends avec les frères.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 12, 'Quant à notre frère Appollos, je l\'ai souvent engagé à se rendre auprès de vous avec les frères, mais il n\'a absolument pas voulu y aller maintenant. Il ira vous voir, quand il en trouvera le temps.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 13, 'Veillez, soyez fermes dans la foi, soyez virils, soyez forts.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 14, 'Que tout ce que vous faites se fasse avec charité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 15, 'Encore une recommandation, frères: vous savez que la famille de Stéphanas est les prémices de l\'Achaïe, et qu\'elle s\'est dévouée au service des saints.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 16, 'Ayez, vous aussi, de la déférence pour de telles personnes, et pour tous ceux qui s\'associent à notre oeuvre et à nos travaux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 17, 'Je suis heureux de la venue de Stéphanas, de Fortunat et d\'Achaïcus; ils ont suppléé à votre absence,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 18, 'car ils ont tranquillisé mon esprit et le vôtre. Sachez apprécier de telles personnes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 19, 'Les Églises d\'Asie vous saluent. Aquilas et Priscille vous envoient bien des salutations dans le Seigneur, ainsi que l\'Église qui se réunit dans leur maison.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 20, 'Tous les frères vous saluent. Saluez-vous les uns les autres par un baiser.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 21, 'Je vous salue, moi Paul, de ma propre main.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 22, 'Si quelqu\'un n\'aime point le Seigneur, qu\'il soit anathème! Maranatha.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 23, 'Que la grâce du Seigneur Jésus-Christ soit avec vous!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 24, 'Je vous aime tous, en Jésus-Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 1, 'Paul, apôtre de Jésus-Christ par la volonté de Dieu, et Timothée, notre frère, à l\'Église de Dieu qui est à Corinthe et à tous les saints qui sont dans toute l\'Achaïe.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 2, 'Que la grâce et la paix vous soient données de la part de Dieu, notre Père, et du Seigneur Jésus-Christ!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 3, 'Béni soit Dieu, le Père de notre Seigneur Jésus-Christ, le Père des miséricordes et le Dieu de toute consolation,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 4, 'qui nous console dans toutes nos afflictions, afin que, par la consolation dont Dieu nous console nous-mêmes, nous puissions aussi consoler les autres, dans quelque affliction qu\'ils se trouvent!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 5, 'En effet, de même que les souffrances du Christ abondent en nous, de même aussi notre consolation abonde par le Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 6, 'Ainsi, soit que nous soyons affligés, c\'est pour votre consolation et votre salut; soit que nous soyons consolés, c\'est pour votre consolation, dont la réalité se manifeste par votre patience à supporter les souffrances que nous endurons nous-mêmes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 7, 'Et notre espérance à votre sujet est ferme; car nous savons que, comme vous avez part aux souffrances, vous aurez aussi part à la consolation.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 8, 'En effet, mes frères, nous ne voulons pas vous laisser ignorer l\'affliction qui nous est survenue en Asie, et dont nous avons été excessivement accablés, au delà même de nos forces, au point que nous désespérions de conserver la vie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 9, 'Bien plus, nous avions prononcé en nous-mêmes notre arrêt de mort, ne voulant pas mettre notre confiance en nous, mais en Dieu qui ressuscite les morts.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 10, 'C\'est lui qui nous a délivrés d\'un si grand danger de mort, et qui nous en délivrera; oui, nous avons en lui cette espérance, qu\'il nous délivrera encore.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 11, 'Et vous-mêmes, vous nous viendrez en aide par vos prières, afin que la grâce, obtenue pour nous par plusieurs personnes, soit aussi, pour plusieurs personnes, une occasion de rendre grâces à notre sujet.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 12, 'Quant à nous, ce qui fait notre gloire, c\'est le témoignage que nous rend notre conscience de nous être conduits dans le monde, et surtout à votre égard, avec la sainteté et la sincérité qui viennent de Dieu, non pas dans un esprit de sagesse charnelle, mais avec le secours de la grâce divine.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 13, 'En effet, nous ne vous écrivons pas autre chose que ce que vous lisez dans nos lettres et que vous reconnaissez vous-mêmes; et j\'espère que vous le reconnaîtrez jusqu\'à la fin,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 14, 'de même que vous l\'avez déjà reconnu, en partie du moins: c\'est que nous sommes votre gloire, comme vous serez aussi la nôtre au jour de notre Seigneur Jésus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 15, 'Dans cette confiance, et afin de vous procurer une double grâce, j\'avais résolu d\'aller premièrement vous voir.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 16, 'J\'aurais passé chez vous en allant en Macédoine, puis je serais revenu de la Macédoine chez vous, d\'où vous m\'auriez fait conduire en Judée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 17, 'Ce dessein, l\'ai-je donc formé à la légère? Ou les résolutions que je prends sont-elles prises selon la chair, de sorte qu\'il y ait en moi le oui et le non?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 18, 'Aussi vrai que Dieu est fidèle, la parole que nous vous adressons n\'est pas tantôt oui, tantôt non.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 19, 'Le Fils de Dieu, Jésus-Christ, que nous avons prêché parmi vous, — moi, Silvain et Timothée, — n\'a pas été tout à la fois «oui et non»; mais il n\'y a eu que «oui en lui».');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 20, 'Car, de même que toutes les promesses de Dieu sont «oui en lui», c\'est aussi par lui que nous disons: Amen! — à la gloire de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 21, 'Or, celui qui nous affermit avec vous en Christ et qui nous a oints, c\'est Dieu;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 22, 'c\'est lui aussi qui nous a marqués de son sceau, et nous a donné, dans nos coeurs, les arrhes de l\'Esprit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 23, 'Je prends Dieu à témoin sur mon âme, que c\'est par ménagement pour vous que je ne suis pas encore allé à Corinthe;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 24, 'non pas que nous cherchions à dominer sur votre foi, mais nous voulons contribuer à votre joie, puisque vous demeurez fermes dans la foi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 1, 'J\'ai donc résolu en moi-même de ne pas retourner chez vous pour vous attrister;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 2, 'car, si je vous attristais, comment pourrais-je attendre de la joie de ceux que j\'aurais moi-même attristés?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 3, 'Si je vous ai écrit comme je l\'ai fait, c\'est afin qu\'à mon arrivée, je ne sois pas attristé par ceux qui devraient me donner de la joie: j\'ai cette confiance en vous tous, que vous faites tous votre joie de la mienne.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 4, 'C\'est dans une grande affliction, en effet, le coeur serré, et avec beaucoup de larmes, que je vous ai écrit, et cela non pour vous attrister, mais pour vous faire connaître l\'affection toute particulière que j\'ai pour vous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 5, 'Si quelqu\'un a été une cause de tristesse, ce n\'est pas moi seul qu\'il a attristé, mais aussi vous tous, du moins en quelque mesure, pour ne rien exagérer.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 6, 'C\'est assez pour cet homme-là d\'avoir été censuré par le plus grand nombre d\'entre vous;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 7, 'aussi vaut-il mieux maintenant que vous lui pardonniez et le consoliez, pour qu\'il ne succombe pas à une trop grande tristesse.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 8, 'Je vous prie donc de faire prévaloir en sa faveur des sentiments de charité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 9, 'Car mon but, en vous écrivant, a été de vous mettre à l\'épreuve et de voir si vous êtes obéissants en toutes choses.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 10, 'Mais à qui vous pardonnez, je pardonne aussi. En effet, si j\'ai pardonné, je l\'ai fait à cause de vous, en présence de Christ,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 11, 'afin de ne pas laisser à Satan prendre l\'avantage sur nous; car nous n\'ignorons pas ses desseins! L\'Évangile, odeur de vie et de mort');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 12, 'Au reste, quand je fus arrivé à Troas pour prêcher l\'Évangile du Christ, quoique le Seigneur m\'y eût ouvert une porte,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 13, 'je n\'eus point l\'esprit en repos, parce que je n\'y trouvai pas Tite, mon frère. C\'est pourquoi, après avoir pris congé des fidèles, je partis pour la Macédoine.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 14, 'Mais, grâces soient rendues à Dieu qui triomphe toujours de nous en Christ, et qui répand en tous lieux, par notre ministère, le parfum de sa connaissance!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 15, 'Car nous sommes, devant Dieu, la bonne odeur de Christ parmi ceux qui sont sauvés et parmi ceux qui périssent:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 16, 'pour ceux-ci, une odeur de mort, qui donne la mort; pour ceux-là, une odeur de vie, qui donne la vie. — Et qui est suffisant pour ces choses? —');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 17, 'En effet, nous ne falsifions point la parole de Dieu, comme le font tant d\'autres; mais c\'est avec pureté, c\'est telle qu\'elle vient de Dieu, que nous la prêchons devant Dieu, en Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 1, 'Commençons-nous de nouveau à nous recommander nous-mêmes, ou aurions-nous besoin, comme quelques-uns, de lettres de recommandation auprès de vous, ou de votre part?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 2, 'C\'est vous qui êtes notre lettre de recommandation, écrite dans nos coeurs, connue et lue par tous les hommes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 3, 'En effet, il est manifeste que vous êtes une lettre de Christ, écrite par notre ministère, non avec de l\'encre, mais avec l\'Esprit du Dieu vivant, non sur des tables de pierre, mais sur des tables de chair, sur vos coeurs.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 4, 'Telle est l\'assurance que nous avons en Dieu par Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 5, 'Non pas que, par nous-mêmes, nous soyons capables de penser quelque chose qui nous viendrait de notre propre fonds; mais toute notre capacité vient de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 6, 'C\'est lui qui nous a rendus capables d\'être ministres de la nouvelle alliance, non celle de la lettre, mais celle de l\'Esprit; car la lettre tue, mais l\'Esprit vivifie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 7, 'Or, si le ministère de la mort, gravé en lettres sur des pierres, a été si glorieux que les enfants d\'Israël ne pouvaient arrêter leurs regards sur le visage de Moïse, à cause de l\'éclat, pourtant passager, de ce visage,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 8, '— combien le ministère de l\'Esprit ne sera-t-il pas plus glorieux encore!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 9, 'En effet, si le ministère de la condamnation a été glorieux, le ministère de la justice le surpasse de beaucoup en gloire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 10, 'Et même, ce qui fut glorieux dans le premier ministère disparaît devant la gloire bien supérieure du second;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 11, 'car, si ce qui devait passer a eu son moment de gloire, combien plus ce qui demeure aura-t-il une gloire impérissable!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 12, 'Ayant donc une telle espérance, nous possédons une grande liberté,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 13, 'et nous ne faisons pas comme Moïse, qui mettait un voile sur son visage, afin que les enfants d\'Israël n\'arrêtassent pas leurs regards sur la fin d\'un éclat qui allait passer.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 14, 'Mais leur intelligence a été obscurcie; car, jusqu\'à ce jour, quand ils lisent l\'Ancien Testament, ce même voile demeure, sans être levé, parce que c\'est en Christ seul qu\'il peut disparaître.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 15, 'Ainsi, aujourd\'hui encore, chaque fois qu\'on leur lit Moïse, ce voile est étendu sur leur coeur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 16, 'Quand ils se convertiront au Seigneur, ce voile sera ôté.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 17, 'Or, le Seigneur est l\'Esprit; et là où est l\'Esprit du Seigneur, là est la liberté.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 18, 'Et nous tous, qui, le visage découvert, contemplons comme dans un miroir la gloire du Seigneur, nous sommes transformés à son image, de gloire en gloire, par l\'action de l\'Esprit du Seigneur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 1, 'C\'est pourquoi, exerçant ce ministère par la miséricorde qui nous a été faite, nous ne perdons pas courage;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 2, 'mais nous rejetons tout ce qui est honteux et que l\'on cache. Nous ne nous conduisons pas avec artifice, et nous n\'altérons point la parole de Dieu; mais nous nous rendons recommandables à toute conscience d\'homme, devant Dieu, par la manifestation de la vérité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 3, 'Et si notre Évangile est encore voilé, il n\'est voilé que pour ceux qui périssent,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 4, 'pour les incrédules, dont le Dieu de ce siècle a aveuglé l\'esprit, afin qu\'ils ne voient pas resplendir le glorieux Evangile du Christ, qui est l\'image de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 5, 'En effet, nous ne nous prêchons pas nous-mêmes, mais nous prêchons Jésus-Christ, le Seigneur. En ce qui nous concerne personnellement, nous nous disons vos serviteurs pour l\'amour de Jésus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 6, 'Car Dieu, qui a dit: «Que la lumière brille du sein des ténèbres!» — a fait aussi briller sa lumière dans nos coeurs, pour que la connaissance de la gloire de Dieu resplendisse en la personne de Jésus-Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 7, 'Mais nous portons ce trésor dans des vases de terre, afin qu\'une puissance si grande soit attribuée à Dieu, et non pas à nous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 8, 'Nous sommes pressés de toutes les manières, mais non réduits à l\'extrémité; dénués de toute ressource, mais non désespérés;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 9, 'persécutés, mais non abandonnés; abattus, mais non perdus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 10, 'Nous portons toujours dans notre corps la mort de Jésus, afin que la vie de Jésus soit aussi manifestée dans notre corps.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 11, 'Car, nous qui vivons, nous sommes sans cesse livrés à la mort à cause de Jésus, afin que la vie de Jésus soit aussi manifestée dans notre chair mortelle;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 12, 'de telle sorte que la mort agit en nous et la vie en vous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 13, 'Et comme nous sommes animés du même esprit de foi qui a inspiré cette parole de l\'Écriture: «J\'ai cru, c\'est pourquoi j\'ai parlé» —, nous aussi, nous croyons, c\'est pourquoi nous parlons,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 14, 'sachant que celui qui a ressuscité le Seigneur Jésus, nous ressuscitera aussi avec Jésus, et nous fera paraître avec vous en sa présence.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 15, 'Car tout cela arrive à cause de vous, afin que la grâce, se répandant avec abondance, fasse abonder chez un plus grand nombre les actions de grâces, à la gloire de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 16, 'C\'est pourquoi nous ne perdons pas courage; mais si notre homme extérieur se détruit, l\'homme intérieur se renouvelle de jour en jour.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 17, 'Car notre légère affliction du moment présent produit pour nous le poids éternel d\'une gloire sans mesure et sans limite,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 18, 'parce que nous ne regardons pas aux choses visibles, mais aux invisibles; car les choses visibles ne sont que pour un temps, mais les invisibles sont éternelles.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 1, 'Nous savons, en effet, que si notre demeure terrestre, — qui n\'est qu\'une tente! — est détruite, nous avons dans le ciel un édifice qui est l\'oeuvre de Dieu, une demeure éternelle qui n\'est pas faite de main d\'homme.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 2, 'Aussi gémissons-nous dans cette tente, ayant l\'ardent désir d\'être revêtus de notre habitation céleste,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 3, 'si toutefois nous sommes trouvés vêtus, et non pas nus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 4, 'Car nous qui sommes dans cette tente, nous gémissons comme sous un fardeau, parce que nous souhaitons, non d\'être dépouillés, mais d\'être revêtus, afin que ce qu\'il y a de mortel en nous soit absorbé par la vie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 5, 'Et celui qui nous a formés pour cela même, c\'est Dieu, qui nous a donné pour arrhes son Esprit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 6, 'Nous sommes donc toujours pleins de confiance, et nous savons que, pendant que nous demeurons dans ce corps, nous habitons loin du Seigneur');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 7, '— car c\'est par la foi que nous marchons, et non par la vue. —');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 8, 'Nous sommes, dis-je, pleins de confiance, et nous aimons mieux quitter ce corps, pour habiter avec le Seigneur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 9, 'C\'est pourquoi aussi nous faisons tous nos efforts pour lui être agréables, soit que nous demeurions dans ce corps, soit que nous en sortions.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 10, 'Car il nous faut tous comparaître, devant le tribunal du Christ, afin que chacun reçoive selon le bien ou le mal qu\'il aura fait, pendant qu\'il était dans son corps.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 11, 'Connaissant donc la crainte qu\'on doit avoir du Seigneur, nous cherchons à en convaincre les hommes; et Dieu nous connaît, et j\'espère que dans vos consciences vous nous connaissez aussi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 12, 'Nous ne venons pas nous faire encore valoir auprès de vous, mais nous voulons vous donner l\'occasion de vous glorifier à notre sujet, pour que vous puissiez répondre à ceux qui tirent gloire de ce qui n\'est qu\'apparence, et non de ce qui est dans le coeur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 13, 'En effet, soit que nous soyons hors de sens, c\'est pour Dieu; soit que nous soyons de sens rassis, c\'est pour vous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 14, 'Car l\'amour du Christ nous possède, et nous estimons que, si un seul est mort pour tous, tous donc sont morts,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 15, 'et qu\'il est mort pour tous, afin que ceux qui vivent ne vivent plus pour eux-mêmes, mais pour celui qui est mort et ressuscité pour eux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 16, 'Aussi, désormais, nous ne connaissons plus personne selon la chair; et, si nous avons connu, selon la chair, le Christ lui-même, nous ne le connaissons plus de cette manière.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 17, 'Si donc quelqu\'un est en Christ, il est une nouvelle créature: les choses vieilles sont passées; voici que toutes choses sont devenues nouvelles.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 18, 'Et tout cela vient de Dieu, qui nous a réconciliés avec lui par Christ et qui nous a confié le ministère de la réconciliation.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 19, 'Car Dieu était en Christ, réconciliant le monde avec lui-même, en n\'imputant point aux hommes leurs offenses; et il a mis en nous la parole de la réconciliation.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 20, 'Nous faisons donc fonction d\'ambassadeurs pour Christ, comme si Dieu exhortait par nous. Nous vous en supplions, au nom du Christ: Soyez réconciliés avec Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 21, 'Celui qui n\'a point connu le péché. Dieu l\'a traité pour nous, comme le péché même, afin que nous devinssions en lui justice de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 1, 'Ainsi, puisque nous travaillons avec le Seigneur, nous vous prions de faire en sorte que vous n\'ayez pas reçu la grâce de Dieu en vain.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 2, 'Car il dit: «Je t\'ai exaucé au temps favorable; je t\'ai secouru au jour du salut». Voici maintenant le temps favorable; voici maintenant le jour du salut!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 3, 'Nous ne donnons de scandale en rien, afin que notre ministère ne soit exposé à aucun blâme.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 4, 'Mais nous nous rendons recommandables en toutes choses, comme des ministres de Dieu, par une grande patience dans les afflictions, dans les détresses, dans les angoisses,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 5, 'sous les coups, dans les prisons, dans les séditions, dans les travaux, dans les veilles, dans les jeûnes;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 6, 'par la pureté, par la connaissance, par la longanimité, par la douceur, par l\'Esprit saint, par une charité sincère,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 7, 'par la parole de vérité, par la puissance de Dieu, avec les armes de la justice, que l\'on tient de la main droite et de la main gauche;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 8, 'à travers l\'honneur et l\'ignominie, à travers la mauvaise et la bonne réputation; étant regardés comme des séducteurs, et pourtant véridiques;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 9, 'comme des inconnus, et pourtant bien connus; comme des mourants, et voici que nous vivons; comme châtiés, et nous ne sommes pas mis à mort;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 10, 'comme affligés, et nous sommes toujours joyeux; comme pauvres, et nous faisons beaucoup de riches; comme n\'ayant rien, et nous possédons toutes choses!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 11, 'Corinthiens, notre bouche s\'est ouverte pour vous. Notre coeur s\'est élargi:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 12, 'vous n\'y êtes point à l\'étroit; mais c\'est votre coeur qui s\'est rétréci pour nous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 13, 'Rendez-nous la pareille — je vous parle comme à mes enfants — élargissez aussi votre coeur!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 14, 'Ne vous mettez pas sous un joug étranger, en vous unissant aux infidèles. Car quelle association peut-il y avoir entre la justice et l\'iniquité? Que peut-il y avoir de commun entre la lumière et les ténèbres?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 15, 'Quel accord existe-t-il entre Christ et Bélial, ou quelle part le fidèle a-t-il avec l\'infidèle?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 16, 'Et comment réunir le temple de Dieu et les idoles? Car nous sommes le temple du Dieu vivant, comme Dieu l\'a dit: «J\'habiterai et je marcherai au milieu d\'eux; je serai leur Dieu, et ils seront mon peuple.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 17, 'C\'est pourquoi, sortez du milieu d\'eux, dit le Seigneur; séparez-vous d\'eux, et ne touchez point à ce qui est impur. Je vous accueillerai:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 18, 'je serai votre père, et vous serez mes fils et mes filles, dit le Seigneur tout-puissant.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 1, 'Ayant donc de telles promesses, mes bien-aimés, purifions-nous de toute souillure de la chair et de l\'esprit, et achevons notre sanctification dans la crainte de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 2, 'Donnez-nous une place dans vos coeurs: nous n\'avons fait tort à personne, nous n\'avons dépouillé personne, nous n\'avons exploité personne.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 3, 'Je ne dis pas cela pour vous condamner; car j\'ai déjà dit que nos coeurs sont à vous, à la vie et à la mort.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 4, 'J\'ai en vous une entière confiance; j\'ai tout sujet de me glorifier à votre égard; je suis rempli de consolation; je suis comblé de joie au miheu de toutes nos afflictions.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 5, 'En effet, à notre arrivée en Macédoine, nous n\'avons eu aucun repos. Nous étions affligés de toutes manières: combats au dehors, craintes au dedans.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 6, 'Mais le Dieu qui console ceux qui sont abattus, nous a consolés par l\'arrivée de Tite;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 7, 'et non seulement par son arrivée, mais aussi par la consolation qu\'il a lui-même reçue de vous: il nous a dit votre ardeur, vos larmes, votre zèle pour moi, ce qui a rendu ma joie plus grande encore.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 8, 'Si je vous ai attristés par ma lettre, je ne le regrette pas; et si je l\'ai regretté — car je vois que cette lettre vous a attristés, du moins sur le moment,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 9, '— maintenant je me réjouis, non pas de ce que vous avez été attristés, mais de ce que votre tristesse vous a portés à la repentance. En effet, vous avez été attristés selon Dieu, de sorte que vous n\'avez éprouvé de notre part aucun dommage.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 10, 'Car la tristesse selon Dieu produit une repentance qui conduit au salut, — et dont on ne se repent jamais, — tandis que la tristesse du monde produit la mort.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 11, 'Voyez, en effet, quel empressement cette tristesse selon Dieu a fait naître en vous! Que dis-je? Quelles excuses! Quelle indignation! Quelle crainte! Quelle ardeur! Quel zèle! Quelle sévérité! Vous avez montré à tous égards que vous étiez purs dans cette affaire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 12, 'Au reste, si je vous ai écrit, ce n\'a été ni à cause de l\'offenseur ni à cause de l\'offensé, mais afin que votre dévoûment pour nous se manifestât parmi vous devant Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 13, 'Voilà ce qui nous a consolés. Et, avec cette consolation, nous avons éprouvé une joie beaucoup plus grande encore, en voyant la joie de Tite; car vous avez mis tout son esprit en repos.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 14, 'Si je me suis un peu glorifié à votre sujet auprès de lui, je n\'en ai pas eu de confusion; mais, comme nous vous avons toujours dit la vérité, l\'éloge que nous avons fait de vous à Tite s\'est trouvé être la vérité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 15, 'Son affection pour vous redouble, lorsqu\'il se rappelle la déférence que vous lui avez tous montrée, et avec quelle crainte, avec quel respect vous l\'avez accueilli.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 16, 'Je me réjouis de ce qu\'en toutes choses je puis avoir confiance en vous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 1, 'Nous voulons, frères, vous faire connaître la grâce que Dieu a faite aux fidèles des Églises de Macédoine:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 2, 'éprouvés par beaucoup d\'afflictions, ils ont, dans l\'abondance de leur joie et dans leur pauvreté profonde, répandu largement les richesses de leur libéralité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 3, 'En effet, je leur rends ce témoignage, qu\'ils ont donné de leur propre mouvement, selon leur pouvoir, et même au-delà de leur pouvoir,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 4, 'nous demandant très instamment de leur accorder la grâce de prendre part à l\'assistance destinée aux saints.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 5, 'Et ils ont dépassé nos espérances; car ils se sont donnés eux-mêmes premièrement au Seigneur, et ensuite à nous, par la volonté de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 6, 'Aussi avons-nous prié Tite d\'aller chez vous pour achever cette oeuvre de charité, comme il l\'avait commencée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 7, 'Ainsi donc, comme vous excellez, à tous égards, dans la foi, dans l\'éloquence, dans la connaissance, en zèle de tout genre, en amour pour nous, appliquez-vous à exceller aussi dans cette oeuvre de charité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 8, 'Je ne dis pas cela pour vous donner un ordre; mais, par l\'exemple du zèle des autres, je voudrais mettre à l\'épreuve la sincérité de votre charité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 9, 'Car vous connaissez la grâce de notre Seigneur Jésus-Christ, qui, étant riche, s\'est fait pauvre pour vous, afin que par sa pauvreté vous fussiez rendus riches.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 10, 'C\'est donc un avis que je donne; et il s\'adresse à vous d\'autant mieux que, dès l\'année dernière, vous avez été les premiers, non seulement à entreprendre cette oeuvre, mais à la vouloir.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 11, 'Achevez donc maintenant votre oeuvre, afin qu\'à l\'ardeur de votre bonne volonté réponde aussi l\'exécution, suivant vos moyens.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 12, 'Car, si l\'on donne de bon coeur, suivant ce qu\'on a, — et non suivant ce qu\'on n\'a pas, — on est agréable à Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 13, 'Je ne vous demande pas, pour soulager les autres, de vous mettre vous-mêmes dans la gêne, mais je voudrais qu\'il y eût de l\'égalité entre vous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 14, 'Dans les circonstances présentes, votre abondance suppléera à leur indigence, afin que leur abondance supplée aussi à votre indigence, et qu\'ainsi il y ait égalité,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 15, 'comme il est écrit: «Celui qui avait beaucoup recueilli n\'avait pas trop, et celui qui avait peu recueilli ne manquait de rien.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 16, 'Grâces soient rendues à Dieu de ce qu\'il a mis au coeur de Tite le même zèle pour vous;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 17, 'car il a accueilli ma prière, et même, dans l\'ardeur de son zèle, il est parti de son propre mouvement pour aller vous voir.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 18, 'Nous avons envoyé avec lui le frère dont l\'éloge est répandu dans toutes les Églises, à cause de ce qu\'il a fait pour l\'Evangile.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 19, 'Bien plus, il a été choisi par les suffrages des Eglises, pour être notre compagnon de voyage dans cette oeuvre de charité que nous accomplissons à la gloire du Seigneur lui-même, et pour montrer notre bonne volonté.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 20, 'Nous voulons éviter par là tout reproche au sujet de l\'administration de cette abondante collecte;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 21, 'car nous recherchons ce qui est bien, non seulement devant le Seigneur, mais aussi devant les hommes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 22, 'Nous avons encore envoyé avec eux l\'un de nos frères dont nous avons plusieurs fois, en diverses occasions, éprouvé le zèle, et qui en aura beaucoup plus encore cette fois-ci, à cause de la grande confiance qu\'il a en vous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 23, 'Ainsi, en ce qui concerne Tite, il est mon compagnon et mon collaborateur auprès de vous; en ce qui concerne nos frères, ils sont les envoyés des Églises, la gloire du Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 24, 'Donnez-leur donc, à la face des Églises, des preuves de votre chanté, et montrez-leur que nous avons eu raison de leur faire un si grand éloge de vous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 1, 'Quant à l\'assistance destinée aux saints, il est superflu de vous écrire à ce sujet.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 2, 'En effet, je connais votre bonne volonté et je m\'en glorifie auprès des Macédoniens, leur disant que l\'Achaïe est prête depuis l\'année dernière et votre sollicitude a stimulé celle de beaucoup d\'autres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 3, 'Cependant, je vous ai envoyé nos frères, afin que l\'éloge que je me suis plu à faire de vous ne soit pas démenti sur ce point, et que vous soyez prêts, comme je l\'ai dit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 4, 'Je craindrais, si les Macédoniens venaient avec moi et ne vous trouvaient pas prêts, que cette confiance même ne tournât à notre confusion, pour ne pas dire à la vôtre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 5, 'J\'ai donc jugé nécessaire de prier nos frères de nous devancer auprès de vous, et de veiller à ce que la libéralité que vous avez promise soit toute prête, afin qu\'elle soit une vraie libéralité, et non un acte de lésinerie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 6, 'Sachez-le bien, celui qui sème peu moissonnera peu, et celui qui sème abondamment moissonnera abondamment.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 7, 'Que chacun donne comme il l\'a décidé dans son coeur, non pas à regret ou par contrainte; car Dieu aime celui qui donne gaiement.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 8, 'Et Dieu est puissant pour vous combler de toutes sortes de grâces, afin qu\'ayant toujours, en toute chose, tout ce qui vous est nécessaire, vous ayez encore largement de quoi faire toutes sortes de bonnes oeuvres,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 9, 'comme il est écrit: «Il a répandu, il a donné aux pauvres; sa justice demeure éternellement.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 10, 'Celui qui fournit au semeur la semence et le pain dont il se nourrit, vous fournira aussi la semence et la multipliera, et il augmentera les fruits de votre justice.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 11, 'Ainsi, vous serez enrichis à tous égards, et vous pourrez accomplir toutes sortes de libéralités, qui, par notre ministère, feront rendre à Dieu des actions de grâces.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 12, 'En effet, la distribution de telles offrandes ne pourvoit pas seulement aux besoins des saints, mais elle est encore une source abondante d\'actions de grâces rendues à Dieu par plusieurs.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 13, 'Faisant ainsi l\'épreuve de votre libéralité, ils glorifient Dieu à cause de votre obéissance dans la profession de l\'Évangile du Christ, et à cause des largesses de votre charité envers eux et envers tous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 14, 'Et ils prient pour vous, vous aimant tendrement à cause de la grâce surabondante que Dieu vous a faite.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 15, 'Grâces soient rendues à Dieu pour son don ineffable!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 1, 'Au reste, moi Paul, je vous prie, par la douceur et la bonté de Christ, — moi qui ai l\'air si humble quand je suis au milieu de vous, mais qui, à distance, montre tant de hardiesse à votre égard!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 2, '— je vous supplie de ne pas m\'obliger, quand je serai présent, à m\'armer de cette hardiesse, que je me propose de montrer contre certaines gens, qui se figurent que nous nous conduisons selon la chair.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 3, 'Car, si nous vivons dans la chair, nous ne combattons pas selon la chair.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 4, 'En effet, les armes avec lesquelles nous combattons ne sont point charnelles, mais elles sont puissantes, par la vertu de Dieu, pour renverser les forteresses:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 5, 'par elles, nous renversons les raisonnements et toute hauteur qui s\'élève contre la connaissance de Dieu, et nous amenons toutes les pensées captives à l\'obéissance du Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 6, 'Par elles aussi, nous sommes en mesure de punir toute désobéissance, lorsque, de votre côté, l\'obéissance sera complète.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 7, 'Vous regardez à l\'apparence? Si quelqu\'un se persuade d\'appartenir à Christ, qu\'il se dise bien que, s\'il appartient à Christ, nous lui appartenons aussi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 8, 'Et quand je me glorifierais un peu trop du pouvoir que le Seigneur nous a donné pour votre édification, et non pour votre ruine, je n\'aurais pas à en rougir;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 9, 'mais je ne veux pas avoir l\'air de vous intimider par mes lettres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 10, 'Ses lettres, dit-on, sont impérieuses et sévères; mais, quand il est présent, sa personne est faible, et sa parole inspire la pitié.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 11, 'Que celui qui parle ainsi, se dise bien que ce que nous sommes en paroles, dans nos lettres, quand nous sommes absents, — nous le sommes aussi dans nos actes, quand nous sommes présents.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 12, 'Certes, nous n\'osons pas nous égaler ou nous comparer à tels de ces hommes qui font leur propre éloge. Mais, en se mesurant à leur propre mesure et en se comparant à eux-mêmes, ils montrent peu d\'intelligence.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 13, 'Pour nous, nous ne voulons pas nous glorifier outre mesure, mais seulement dans la mesure de la part que Dieu nous a assignée, en nous faisant parvenir jusqu\'à vous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 14, 'Car nous n\'étendons pas notre domaine plus qu\'il ne faut, comme si nous n\'étions point parvenus jusqu\'à vous, puisque, en effet, nous sommes arrivés les premiers jusqu\'à vous avec l\'Evangile du Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 15, 'Nous ne nous glorifions pas outre mesure, ni au sujet des travaux d\'autrui; mais nous espérons qu\'avec l\'accroissement de votre foi, notre oeuvre aussi grandira parmi vous, dans les limites mêmes qui nous sont assignées, et qu\'elle se développera,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 16, 'à tel point que nous pourrons porter l\'Évangile dans les pays qui sont au delà du vôtre, sans jamais nous glorifier des travaux déjà faits par d\'autres dans le domaine qui leur a été assigné.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 17, 'Mais que celui qui se glorifie, se glorifie dans le Seigneur!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 18, 'Car ce n\'est pas celui qui se recommande lui-même qui mérite l\'approbation, c\'est celui que le Seigneur recommande.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 1, 'Oh! si vous pouviez supporter de ma part un peu de folie! Eh bien, oui, supportez-moi!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 2, 'En effet, je suis jaloux, à votre sujet, de la jalousie de Dieu, parce que je vous ai fiancés à un seul époux, en vous présentant au Christ comme une vierge pure.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 3, 'Mais je crains que, comme Eve fut séduite par la ruse du serpent, vos pensées ne se corrompent et ne se détournent de la simplicité que le Christ demande.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 4, 'Car, si l\'on vient vous prêcher un autre Jésus que celui que nous vous avons prêché, ou s\'il s\'agit de recevoir un autre Esprit que celui que vous avez reçu, ou un autre Évangile que celui que vous avez embrassé, vous le supportez fort bien!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 5, 'Or, j\'estime que je n\'ai été inférieur en rien à ces apôtres, si éminents soient-ils.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 6, 'Et si même je suis un homme ordinaire pour la parole, je ne le suis pas pour la connaissance: nous l\'avons fait voir parmi vous, à tous égards et en toutes choses.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 7, 'Ai-je donc commis une faute en m\'abaissant moi-même, afin que vous fussiez élevés, par le fait que je vous ai annoncé gratuitement l\'Évangile de Dieu?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 8, 'J\'ai dépouillé d\'autres Églises, en recevant d\'elles un salaire, pour pouvoir vous servir.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 9, 'Et quand j\'étais auprès de vous et que je me suis trouvé dans le besoin, je n\'ai été à charge à personne; car les frères venus de Macédoine ont pourvu à ce qui me manquait. Je me suis gardé de vous être à charge en quoi que ce soit, et je m\'en garderai encore.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 10, 'Aussi vrai que la vérité de Christ est en moi, ce sujet de gloire ne me sera point enlevé dans les contrées de l\'Achaïe.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 11, 'Pourquoi? Parce que je ne vous aime pas? Dieu le sait!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 12, 'Mais ce que je fais, je le ferai encore, pour ôter tout prétexte à ceux qui cherchent des prétextes, — afin que, dans les choses mêmes dont ils se vantent, ils se trouvent n\'avoir aucune supériorité sur nous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 13, 'Car de tels hommes sont de faux apôtres, des ouvriers trompeurs, qui se déguisent en apôtres de Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 14, 'Et il n\'y a là rien d\'étonnant, puisque Satan lui-même se déguise en ange de lumière.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 15, 'Il n\'est donc pas surprenant que ses ministres se déguisent aussi en ministres de justice; mais leur fin sera conforme à leurs oeuvres!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 16, 'Je le dis encore: que personne ne me regarde comme un insensé; ou bien, acceptez-moi comme tel, et laissez-moi me glorifier un peu, moi aussi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 17, 'Ce que je vais dire, quand je me glorifie avec une telle assurance, je ne le dis pas sous l\'inspiration du Seigneur, mais comme si j\'avais perdu tout bon sens.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 18, 'Puisque plusieurs se glorifient selon la chair, moi aussi, je vais me glorifier.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 19, 'Car vous supportez volontiers les insensés, vous qui êtes des sages.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 20, 'Oui, vous supportez qu\'on vous asservisse, qu\'on vous dévore, qu\'on vous pille, qu\'on vous traite avec hauteur, qu\'on vous frappe au visage.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 21, 'Je le dis à notre honte, nous avons montré de la faiblesse. Et cependant, si quelqu\'un ose se vanter de quelque chose — je parle en insensé! — moi aussi, je l\'oserai.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 22, 'Ils sont Hébreux? Moi aussi. Ils sont Israélites? Moi aussi. Ils sont de la postérité d\'Abraham? Moi aussi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 23, 'Ils sont ministres de Christ? Eh bien, — je parle comme un insensé! — je le suis davantage. J\'ai eu à supporter plus de travaux, plus d\'emprisonnements, infiniment plus de coups. Souvent, j\'ai été en danger de mort;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 24, 'cinq fois, j\'ai reçu des Juifs «quarante coups de fouet moins un»;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 25, 'j\'ai été battu de verges trois fois; j\'ai été lapidé une fois; j\'ai fait naufrage trois fois. J\'ai passé un jour et une nuit dans l\'abîme.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 26, 'J\'ai été souvent en voyage, en danger sur les rivières, en danger parmi les voleurs, en danger au milieu de ma nation, en danger parmi les Païens, en danger dans les villes, en danger dans les déserts, en danger sur la mer, en danger parmi les faux frères;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 27, 'dans le travail et la peine, souvent dans les veilles, dans la faim, la soif, les jeûnes multipliés, dans le froid, dans le dénuement.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 28, 'Sans parler de tout le reste, chaque jour je suis assiégé par le souci de toutes les Églises.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 29, 'Qui est faible, que je ne sois faible moi-même? Qui vient à broncher, que je n\'en sois tout brûlant de fièvre?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 30, 'S\'il faut se glorifier, je me glorifierai de ma faiblesse.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 31, 'Dieu, qui est le Père du Seigneur Jésus, et qui est béni éternellement, sait que je ne mens point.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 32, 'A Damas, le gouverneur du roi Arétas faisait garder la ville des Damascéniens, pour s\'emparer de moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 33, 'On me descendit par une fenêtre, dans une corbeille, le long de la muraille, et c\'est ainsi que j\'échappai de ses mains.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 1, 'Faut-il se glorifier? Cela n\'est pas bon sans doute; mais j\'en viendrai pourtant aux visions et aux révélations du Seigneur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 2, 'Je connais un homme en Christ, qui fut, il y a quatorze ans, ravi jusqu\'au troisième ciel — si ce fut en son corps, je ne sais; si ce fut hors de son corps, je ne sais: Dieu le sait! —');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 3, 'Je sais que cet homme — si ce fut en son corps, ou sans son corps, je ne sais: Dieu le sait!...!!-');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 4, 'fut ravi jusque dans le paradis et y entendit des paroles ineffables, qu\'il n\'est pas permis à un homme de révéler.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 5, 'En ce qui concerne cet homme-là, oui, je puis me glorifier; mais en ce qui concerne exclusivement ma personne, je ne me glorifierai que de mes infirmités.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 6, 'Si je voulais me glorifier, je ne serais pas un insensé; car je dirais la vérité. Mais je m\'en abstiens, afin qu\'aucun homme ne se fasse de moi une idée supérieure à ce qu\'il voit en moi, ou à ce qu\'il m\'entend dire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 7, 'C\'est pourquoi, de peur que je ne fusse enflé d\'orgueil par l\'extraordinaire grandeur de ces révélations, il m\'a été imposé une écharde dans la chair, un ange de Satan pour me souffleter et m\'empêcher de m\'enorgueillir.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 8, 'Trois fois, j\'ai prié le Seigneur de l\'éloigner de moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 9, 'Mais il m\'a dit: Ma grâce te suffit; car ma force s\'accomplit dans la faiblesse. Je me glorifierai donc bien plus volontiers de mes faiblesses, afin que la force du, Christ habite en moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 10, 'C\'est pourquoi je me complais dans les faiblesses, dans les outrages, dans les détresses, dans les persécutions, dans les afflictions extrêmes pour Christ; car, lorsque je suis faible, c\'est alors que je suis fort!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 11, 'J\'ai été insensé: vous m\'y avez contraint! C\'était à vous de faire mon éloge; car je n\'ai été inférieur en rien à ces incomparables apôtres, quoique je ne sois rien.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 12, 'Les preuves de mon apostolat ont éclaté parmi vous par une patience à toute épreuve, par des signes, des prodiges et des miracles.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 13, 'Et, en effet, en quoi avez-vous été moins bien traités que les autres Églises, si ce n\'est que moi-même je ne vous ai pas été à charge? Pardonnez-moi cette injustice!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 14, 'Voici la troisième fois que je suis prêt à aller chez vous, et je ne vous serai point à charge, car ce ne sont pas vos biens que je recherche, c\'est vous-mêmes. Et en effet, ce n\'est pas aux enfants à amasser des trésors pour leurs parents, mais plutôt aux parents pour leurs enfants.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 15, 'Pour moi, je dépenserai très volontiers, et je me dépenserai moi-même entièrement pour vos âmes, dussé-je, en vous aimant davantage, être moins aimé de vous!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 16, 'Soit, je ne vous ai pas été à charge; mais en homme astucieux, je vous aurais pris par la ruse!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 17, '— Ai-je donc tiré profit de vous par aucun de ceux que je vous ai envoyés?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 18, 'J\'ai prié Tite d\'aller vous voir, et avec lui j\'ai envoyé l\'un de nos frères. Est-ce que Tite a tiré profit de vous? N\'avons-nous pas marché dans le même esprit, suivi les mêmes traces?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 19, 'Depuis longtemps, vous croyez que nous cherchons à nous justifier devant vous. C\'est devant Dieu, en Christ, que nous parlons; et tout cela, mes bien-aimés, pour votre édification.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 20, 'Car je crains qu\'à mon arrivée je ne vous trouve pas tels que je voudrais, et que, de votre côté, vous ne me trouviez tout autre que vous ne voudriez. Je crains qu\'il n\'y ait parmi vous des querelles, de la jalousie, des animosités, des dissensions, des médisances, des insinuations, de l\'orgueil, des troubles.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 21, 'Est-ce qu\'à mon arrivée chez vous, mon Dieu m\'humiliera de nouveau à votre sujet, et aurai-je à pleurer sur plusieurs de ceux qui ont péché précédemment, et qui ne se seront pas repentis de l\'impureté, de l\'impudicité et des désordres auxquels ils se sont livrés?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 1, 'C\'est la troisième fois que je vais aller chez vous. Sur la déclaration de deux ou trois témoins, toute affaire sera décidée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 2, 'Je l\'ai déjà dit et je le dis encore d\'avance, aujourd\'hui que je suis absent, comme lors de mon second séjour parmi vous; je déclare à ceux qui ont péché précédemment et à tous les autres, que si je reviens, je n\'userai d\'aucun ménagement,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 3, '— puisqu\'il vous faut une preuve que Christ parle par moi, lui qui, loin d\'être faible à votre égard, est puissant au milieu de vous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 4, 'Car, s\'il a été crucifié dans sa faiblesse, il vit néanmoins par la puissance de Dieu; nous, de même, si nous sommes faibles en lui, nous vivrons pourtant avec lui par la puissance de Dieu pour agir au milieu de vous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 5, 'Examinez-vous vous-mêmes, pour voir si vous êtes dans la foi. Éprouvez-vous vous-mêmes: ne reconnaissez-vous pas que Jésus-Christ est en vous? — à moins, peut-être, que l\'épreuve ne tourne à votre détriment.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 6, 'Mais j\'espère que vous reconnaîtrez qu\'elle ne tourne pas contre nous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 7, 'Cependant, nous demandons à Dieu que vous ne fassiez aucun mal, non pas pour paraître nous-mêmes victorieux dans l\'épreuve, mais afin que vous fassiez ce qui est bien, dussions-nous passer ensuite pour vaincus dans l\'épreuve.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 8, 'En effet, nous n\'avons pas de puissance contre la vérité; nous n\'en avons que pour la vérité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 9, 'Aussi nous réjouissons-nous, quand nous sommes dans la faiblesse, pourvu que vous soyez forts; et ce que nous demandons, c\'est votre parfait affermissement.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 10, 'C\'est pourquoi, j\'écris ces choses, étant absent, afin que, lorsque je serai présent, je n\'aie pas à user de rigueur, selon le pouvoir que le Seigneur m\'a donné pour édifier, et non pour détruire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 11, 'Au reste, frères, soyez joyeux. Tendez à la perfection; consolez-vous; soyez animés des mêmes sentiments; vivez en paix; et le Dieu d\'amour et de paix sera avec vous!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 12, 'Saluez-vous les uns les autres par un saint baiser.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 13, 'Tous les saints vous saluent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 14, 'Que la grâce du Seigneur Jésus-Christ, l\'amour de Dieu et la communion du Saint-Esprit soient avec vous tous!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 1, 'Paul, apôtre — non de la part des hommes, ni par l\'intermédiaire d\'aucun homme, mais par Jésus-Christ et par Dieu, le Père, qui l\'a ressuscité des morts,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 2, '— ainsi que tous les frères qui sont avec moi, — aux Églises de Galatie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 3, 'Que la grâce et la paix vous soient données de la part de Dieu, le Père, et de notre Seigneur Jésus-Christ,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 4, 'qui s\'est donné lui-même pour nos péchés, afin de nous arracher à la corruption de ce siècle suivant la volonté de Dieu, notre Père,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 5, 'auquel soit la gloire aux siècles des siècles! Amen.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 6, 'Je m\'étonne que vous abandonniez si vite celui qui vous a appelés par la grâce de Jésus-Christ, pour passer à un autre Évangile.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 7, 'Non pas qu\'il y ait un autre Évangile; mais il y a des gens qui vous troublent et qui veulent renverser l\'Évangile du Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 8, 'Eh bien, si jamais quelqu\'un, — fût-ce nous-même ou un ange du ciel! — venait à vous annoncer un autre Évangile que celui que nous vous avons annoncé, qu\'il soit anathème!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 9, 'Je l\'ai déjà dit, et je le dis encore maintenant: Si quelqu\'un vous annonce un autre évangile que celui que vous avez reçu, qu\'il soit anathème!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 10, 'Est-ce l\'approbation des hommes que je cherche, en ce moment, ou celle de Dieu? Ou bien, est-ce aux hommes que je veux plaire? Si j\'en étais encore à plaire aux hommes, je ne serais pas serviteur de Christ!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 11, 'Je vous le déclare, frères, l\'Évangile que j\'ai annoncé ne vient pas de l\'homme;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 12, 'car je ne l\'ai reçu ni appris d\'aucun homme, mais je l\'ai reçu par une révélation de Jésus-Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 13, 'Vous avez entendu dire, en effet, quelle était autrefois ma conduite dans le judaïsme, et avec quel emportement je persécutais et ravageais l\'Église de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 14, 'J\'allais même plus loin dans le judaïsme que beaucoup de ceux de mon âge et de ma nation, étant le zélateur le plus ardent des traditions de mes pères.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 15, 'Mais quand il plut à Celui qui m\'a mis à part dès le sein de ma mère, et qui m\'a appelé par sa grâce,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 16, 'de révéler son Fils en moi, en me chargeant de l\'annoncer parmi les Païens, — j\'obéis aussitôt, sans consulter ni la chair, ni le sang.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 17, 'Je ne montai pas non plus à Jérusalem auprès de ceux qui avaient été apôtres avant moi, mais je m\'en allai en Arabie; puis, je revins encore à Damas.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 18, 'Ensuite, au bout de trois ans, je montai à Jérusalem, pour faire connaissance avec Céphas, et je demeurai auprès de lui quinze jours;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 19, 'mais je ne vis aucun des apôtres, sinon Jacques, le frère du Seigneur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 20, 'Oui, je l\'affirme devant Dieu, ce que je vous écris n\'est pas un mensonge.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 21, 'J\'allai ensuite dans les contrées de la Syrie et de la Cilicie,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 22, 'et j\'étais inconnu de visage aux Églises de Judée qui sont en Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 23, 'Seulement, elles avaient entendu dire: Celui qui nous persécutait jadis, annonce maintenant la foi qu\'il s\'efforçait alors de détruire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 24, 'Et elles glorifiaient Dieu à mon sujet.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 1, 'Quatorze ans après, je montai de nouveau à Jérusalem avec Barnabas, et je pris aussi Tite avec moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 2, 'J\'y montai par suite d\'une révélation, et j\'exposai aux frères l\'Évangile que je prêche parmi les Païens; je l\'exposai en particulier à ceux qui sont les plus considérés, de peur de courir ou d\'avoir couru en vain.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 3, 'Mais Tite, qui m\'accompagnait et qui était Grec, ne fut pas même contraint de se faire circoncire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 4, 'Or, nous agîmes ainsi à cause des faux frères, qui s\'étaient introduits furtivement parmi nous pour épier la liberté que nous avons en Jésus-Christ, afin de nous réduire en servitude.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 5, 'Nous ne leur cédâmes pas un instant, refusant de nous placer sous leur dépendance, afin que la vérité de l\'Évangile fût maintenue parmi vous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 6, 'Quant à ceux qu\'on tient en si haute estime — ce qu\'ils ont pu être jadis m\'importe peu: Dieu ne fait pas acception de personnes! — ces hommes, si estimés, ne m\'imposèrent rien de plus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 7, 'Au contraire, voyant que la mission de prêcher l\'Évangile aux incirconcis m\'avait été confiée, comme à Pierre celle de le prêcher aux circoncis');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 8, '— car Celui qui a agi en Pierre pour le faire apôtre des Circoncis, a également agi en moi pour me faire apôtre des Païens —');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 9, 'et reconnaissant la grâce qui m\'avait été accordée, Jacques, Céphas et Jean, qui sont considérés comme des colonnes, nous donnèrent, à Barnabas et à moi, la main d\'association, afin que nous allions vers les Païens, et eux vers les Circoncis.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 10, 'Ils nous recommandèrent seulement de nous souvenir des pauvres, ce qu\'aussi j\'ai eu soin de faire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 11, 'Mais, lorsque Céphas vint à Antioche, je lui résistai en face, parce qu\'il méritait d\'être repris.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 12, 'Car, avant l\'arrivée de quelques personnes venues d\'auprès de Jacques, il mangeait avec les Païens; et dès qu\'elles furent arrivées, il se retira et se tint à l\'écart, craignant ceux de la circoncision.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 13, 'Les autres Juifs usèrent de la même dissimulation, de sorte que Barnabas lui-même fut entraîné par leur hypocrisie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 14, 'Alors, voyant qu\'ils ne marchaient pas droit selon la vérité de l\'Évangile, je dis à Céphas en présence de tous: Si toi qui es Juif, tu vis à la façon des Païens, et non comme les Juifs, pourquoi obliges-tu les Païens à judaïser?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 15, 'Pour nous, nous sommes des Juifs de naissance, et non des pécheurs d\'origine païenne.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 16, 'Néanmoins, ayant connu que ce n\'est point par les oeuvres de la loi, mais par la foi en Jésus-Christ, que l\'homme est justifié, nous avons nous-mêmes cru en Jésus-Christ, afin d\'être justifiés par la foi en Christ, et non par les oeuvres de la loi; car personne ne sera justifié par les oeuvres de la loi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 17, 'Mais si, en cherchant à être justifiés par Christ, nous étions nous-mêmes trouvés pécheurs, Christ serait donc ministre du péché! Non, certes!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 18, 'En effet, si je rebâtissais ce que j\'ai détruit, je me constituerais moi-même transgresseur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 19, 'Or, par la loi je suis mort à la loi, afin de vivre pour Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 20, 'J\'ai été crucifié avec Christ: si je vis, ce n\'est plus moi qui vis, c\'est Christ qui vit en moi; et si je vis encore dans la chair, je vis dans la foi au Fils de Dieu qui m\'a aimé, et qui s\'est livré lui-même pour moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 21, 'Je ne veux pas anéantir la grâce de Dieu; car, si la justice s\'obtient par la loi, Christ est donc mort en vain!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 1, 'Galates dépourvus de sens, qui vous a ensorcelés, vous aux yeux desquels a été si vivement dépeint Jésus-Christ crucifié?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 2, 'Je vous ferai une seule question: Est-ce par les oeuvres de la loi que vous avez reçu l\'Esprit, ou par la prédication de la foi?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 3, 'Êtes-vous donc si dépourvus de sens? Après avoir commencé par l\'Esprit, finiriez-vous maintenant par la chair?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 4, 'Avez-vous fait en vain de telles expériences? — et encore si c\'était en vain!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 5, 'Celui qui vous accorde l\'Esprit et qui opère des miracles parmi vous, le fait-il par les oeuvres de la loi, ou par la prédication de la foi?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 6, 'De même qu\'Abraham crut à Dieu, et que cela lui fut imputé à justice,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 7, 'de même, reconnaissez-le, ce sont ceux qui ont la foi qui sont les vrais enfants d\'Abraham.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 8, 'Aussi l\'Écriture, prévoyant que Dieu justifierait les Païens par la foi, a-t-elle annoncé d\'avance à Abraham cette bonne nouvelle: «Toutes les nations seront bénies en toi.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 9, 'Ainsi, ceux qui croient sont bénis avec Abraham, le croyant.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 10, 'Car tous ceux qui s\'attachent aux oeuvres de la loi, sont sous la malédiction, puisqu\'il est écrit: «Maudit est quiconque n\'observe pas avec persévérance tout ce qui est écrit dans le livre de la loi!»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 11, 'Que nul ne soit justifié devant Dieu par la loi, cela est évident, puisque «le juste vivra par la foi.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 12, 'Or, la loi n\'est pas du même ordre que la foi; mais elle dit: «Celui qui observe les commandements, vivra par eux.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 13, 'Christ nous a rachetés de la malédiction de la loi, ayant été fait malédiction pour nous; — car il est écrit: «Maudit est quiconque est pendu au bois», —');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 14, 'afin que la bénédiction accordée à Abraham se répandît sur les Païens par Jésus-Christ, et que nous reçussions par la foi l\'Esprit qui avait été promis.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 15, 'Frères, je parle d\'après les usages des hommes: le testament, même d\'un homme, quand il est en bonne forme, personne ne peut l\'annuler et l\'on ne peut rien y ajouter.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 16, 'Or, les promesses ont été faites à Abraham et à sa postérité. Il n\'est pas dit: «Et à ses postérités», comme s\'il s\'agissait de plusieurs; mais, comme pour parler d\'une seule: «Et à ta postérité», c\'est-à-dire Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 17, 'Je dis donc: Une alliance, que Dieu a auparavant conclue en bonne forme, n\'a pu être annulée, ni la promesse abolie par la loi, qui n\'est venue que quatre cent trente ans après.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 18, 'Car, si l\'héritage était donné par la loi, il ne le serait plus par la promesse. Or, Dieu l\'a donné à Abraham par la promesse.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 19, 'Pourquoi donc la loi? Elle a été ajoutée, à cause des transgressions, jusqu\'à ce que vînt la postérité à qui la promesse avait été faite; et elle fut promulguée par des anges et par l\'entremise d\'un médiateur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 20, 'Or, un médiateur suppose toujours deux parties, tandis qu\'ici, Dieu est seul.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 21, 'La loi est-elle donc contraire aux promesses de Dieu? Non, certes! Car, s\'il avait été donné une loi qui pût produire la vie, la justice viendrait réellement de la loi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 22, 'Mais l\'Écriture a tout enfermé sous le péché, afin que, par la foi en Jésus-Christ, ce qui avait été promis fût donné à ceux qui croient.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 23, 'Avant que la foi fût venue, nous étions enfermés sous la garde de la loi, en attendant la foi qui devait être révélée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 24, 'Ainsi, la loi a été comme un pédagogue pour nous conduire à Christ, afin que nous fussions justifiés par la foi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 25, 'Mais la foi étant venue, nous ne sommes plus soumis à ce pédagogue.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 26, 'Car vous êtes tous fils de Dieu par la foi en Jésus-Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 27, 'En effet, vous tous qui avez été baptisés en Christ, vous avez revêtu Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 28, 'Il n\'y a plus ici ni Juif, ni Grec; il n\'y a plus ni esclave, ni libre; il n\'y a plus ni homme, ni femme; car tous, vous êtes un en Jésus-Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 29, 'Et si vous êtes en Christ, vous êtes donc la postérité d\'Abraham, héritiers selon la promesse.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 1, 'Or, je dis que l\'héritier, aussi longtemps qu\'il est enfant, ne diffère en rien de l\'esclave, quoiqu\'il soit le maître de tout;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 2, 'mais il est soumis à des tuteurs et à des curateurs jusqu\'au temps marqué par le père.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 3, 'Nous aussi de même, lorsque nous étions enfants, nous étions asservis aux rudiments du monde.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 4, 'Mais, lorsque les temps ont été accomplis, Dieu a envoyé son Fils, né d\'une femme, né sous la loi,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 5, 'afin de racheter ceux qui étaient sous la loi, et de nous faire obtenir l\'adoption filiale.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 6, 'Et parce que vous êtes fils, Dieu a envoyé dans vos coeurs l\'Esprit de son Fils, lequel crie: Abba! — c\'est-à-dire: Père! —');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 7, 'Ainsi, tu n\'es plus esclave, mais fils; et si tu es fils, tu es aussi héritier, par la grâce de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 8, 'Autrefois, quand vous ne connaissiez pas Dieu, vous serviez des dieux qui ne le sont pas de leur nature.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 9, 'Mais maintenant que vous connaissez Dieu, ou plutôt que vous avez été connus de Dieu, comment retournez-vous encore à ces faibles et pauvres rudiments, auxquels vous voulez vous assujettir de nouveau?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 10, 'Vous observez les jours, les mois, les temps, les années!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 11, 'Je crains pour vous d\'avoir travaillé en vain au milieu de vous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 12, 'Soyez comme moi, frères, je vous en supplie; car, moi aussi, je suis comme vous. Vous ne m\'avez fait aucun tort.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 13, 'Vous savez que ce fut dans l\'infirmité de la chair que je vous annonçai pour la première fois l\'Évangile;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 14, 'et, malgré l\'épreuve que vous causait cette infirmité de ma chair, vous ne m\'avez ni méprisé, ni repoussé, mais vous m\'avez reçu comme un ange de Dieu, comme Jésus-Christ même.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 15, 'Qu\'est donc devenu votre bonheur? Car je vous rends ce témoignage que, s\'il eût été possible, vous vous seriez arraché les yeux pour me les donner.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 16, 'Suis-je devenu votre ennemi, en vous disant la vérité?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 17, 'Le zèle que ces gens ont pour vous n\'est pas de bon aloi; mais ils veulent vous détacher de nous, afin que vous soyez zélés pour eux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 18, 'Il est beau d\'avoir du zèle pour ce qui est bien, en tout temps, et non pas seulement lorsque je suis présent parmi vous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 19, 'Mes enfants, pour qui je souffre de nouveau les douleurs de l\'enfantement jusqu\'à ce que Christ soit formé en vous,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 20, 'je voudrais être en ce moment avec vous et changer de langage; car je suis dans une grande perplexité à votre sujet.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 21, 'Dites-moi, vous qui voulez être sous la loi, ne comprenez-vous pas la loi?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 22, 'Car il est écrit qu\'Abraham eut deux fils: un de la femme esclave, et un de celle qui était libre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 23, 'Mais celui qu\'il eut de l\'esclave, naquit selon la chair, et celui de la femme libre naquit en vertu de la promesse.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 24, 'Tout cela a un sens allégorique: ces femmes sont deux alliances, l\'une, celle du mont Sinaï, enfante pour la servitude, et c\'est Agar.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 25, 'En effet, Agar c\'est le mont Sinaï, en Arabie: elle correspond à la Jérusalem actuelle qui est esclave avec ses enfants.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 26, 'Mais la Jérusalem d\'en haut est libre, et c\'est notre mère.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 27, 'En effet, il est écrit: «Réjouis-toi, stérile, toi qui n\'enfantais point. Pousse des cris de joie et d\'allégresse, toi qui n\'avais pas connu les douleurs de l\'enfantement, car les enfants de l\'épouse délaissée seront plus nombreux que les enfants de celle qui avait un mari.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 28, 'Pour vous, frères, vous êtes, comme Isaac, les enfants de la promesse.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 29, 'Mais, de même que celui qui était né selon la chair persécutait alors celui qui était né selon l\'Esprit, il en est encore ainsi maintenant.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 30, 'Mais, que dit l\'Écriture? «Chasse l\'esclave et son fils; car le fils de l\'esclave n\'héritera pas avec le fils de la femme libre.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 31, 'Ainsi, frères, nous ne sommes pas les enfants de l\'esclave, mais ceux de la femme libre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 1, 'C\'est pour la liberté que Christ nous a affranchis; demeurez donc fermes, et ne vous remettez pas de nouveau sous le joug de la servitude.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 2, 'C\'est moi, Paul, qui vous le déclare: si vous vous faites circoncire, Christ ne vous servira de rien.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 3, 'Et je déclare encore à tout homme qui se fait circoncire, qu\'il est obligé d\'observer toute la loi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 4, 'Vous êtes séparés de Christ, vous tous qui voulez être justifiés par la loi; vous êtes déchus de la grâce.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 5, 'Pour nous, c\'est de la foi que nous attendons, par l\'Esprit, l\'espérance de la justice.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 6, 'Car, en Jésus-Christ, ce qui a de la valeur, ce n\'est ni la circoncision, ni l\'incirconcision, mais la foi qui est agissante par la charité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 7, 'Vous couriez bien; qui vous a arrêtés, pour vous empêcher d\'obéir à la vérité?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 8, 'Cette suggestion ne vient pas de Celui qui vous appelle.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 9, 'Un peu de levain fait lever toute la pâte.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 10, 'J\'ai, dans le Seigneur, cette confiance à votre égard, que vous ne serez pas d\'un autre sentiment; mais celui qui vous trouble, quel qu\'il soit, en portera la peine.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 11, 'Et pour moi, frères, si je prêchais encore la circoncision, pourquoi serais-je encore persécuté? Le scandale de la croix ne serait-il pas aboli?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 12, 'Qu\'ils se mutilent donc plutôt eux-mêmes, ceux qui jettent le trouble parmi vous!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 13, 'Frères, vous avez été appelés à la liberté; seulement, que cette liberté ne soit pas pour vous une occasion de vivre selon la chair, mais soyez par la charité les serviteurs les uns des autres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 14, 'Car toute la loi se résume dans cette seule parole: «Tu aimeras ton prochain comme toi-même.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 15, 'Mais si vous vous mordez et vous dévorez les uns les autres, prenez garde que vous ne soyez détruits les uns par les autres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 16, 'Je dis donc: Marchez selon l\'Esprit, et n\'accomplissez point les désirs de la chair.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 17, 'Car la chair a des désirs contraires à ceux de l\'Esprit, et l\'Esprit en a de contraires à ceux de la chair; il y a entre eux une telle opposition, que vous ne faites pas ce que vous voudriez.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 18, 'Mais, si vous êtes conduits par l\'Esprit, vous n\'êtes point sous la loi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 19, 'Or, les oeuvres de la chair sont manifestes: ce sont l\'impudicité, l\'impureté, le dérèglement,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 20, 'l\'idolâtrie, la sorcellerie, les inimitiés, les querelles, les jalousies, les animosités, les disputes, les divisions, les sectes,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 21, 'l\'envie, l\'ivrognerie, les orgies et autres choses semblables. Je vous le déclare d\'avance, comme je l\'ai déjà fait: ceux qui commettent de tels péchés n\'hériteront pas le royaume de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 22, 'Mais le fruit de l\'Esprit, c\'est l\'amour, la joie, la paix, la patience, la bienveillance, la bonté, la fidélité, la douceur, la tempérance;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 23, 'la loi n\'est pas contre de telles choses!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 24, 'Or, ceux qui sont à Jésus-Christ ont crucifié la chair avec ses passions et ses convoitises.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 25, 'Si nous vivons par l\'Esprit, marchons aussi selon l\'Esprit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 26, 'Ne recherchons point la vaine gloire, en nous provoquant les uns les autres, et en nous portant envie les uns aux autres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 1, 'Frères, si un homme vient à être surpris en quelque faute, vous qui avez l\'Esprit, redressez-le dans un esprit de douceur; et prends garde à toi-même, de peur que, toi aussi, tu ne sois tenté!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 2, 'Portez les fardeaux les uns des autres, et vous accomplirez ainsi la loi de Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 3, 'Car, si quelqu\'un pense être quelque chose, bien qu\'il ne soit rien, il se séduit lui-même.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 4, 'Que chacun examine son oeuvre, et alors il pourra se glorifier, par rapport à lui-même seulement, et non par rapport aux autres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 5, 'Chacun, en effet, portera son propre fardeau.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 6, 'Que celui à qui on enseigne la parole, fasse, dans tous ses biens, une part pour celui qui l\'enseigne.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 7, 'Ne vous abusez point: on ne se moque pas de Dieu; car ce que l\'homme aura semé, il le moissonnera aussi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 8, 'Celui qui sème pour sa chair, moissonnera de la chair la corruption; mais celui qui sème pour l\'Esprit, moissonnera de l\'Esprit la vie éternelle.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 9, 'Ne nous lassons pas de faire le bien; car nous moissonnerons au temps convenable, si nous ne nous relâchons point.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 10, 'Ainsi donc, pendant que nous en avons l\'occasion, faisons du bien à tous, mais principalement à nos frères en la foi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 11, 'Voyez en quels gros caractères je vous ai écrit de ma propre main.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 12, 'Tous ceux qui vous contraignent d\'être circoncis, veulent plaire aux hommes, d\'une façon toute charnelle, uniquement afin qu\'ils ne soient pas persécutés pour la croix du Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 13, 'Car ceux-là mêmes qui sont circoncis n\'observent point la loi; mais ils veulent que vous soyez circoncis, afin de se glorifier en votre chair.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 14, 'Pour moi, Dieu me garde de me glorifier, si ce n\'est en la croix de notre Seigneur Jésus-Christ, par laquelle le monde est crucifié à mon égard, et moi à l\'égard du monde!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 15, 'Car ce qui importe, ce n\'est pas la circoncision ni l\'incirconcision, c\'est d\'être une nouvelle créature.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 16, 'Et pour tous ceux qui suivront cette règle, que la paix et la miséricorde repose sur eux, et sur l\'Israël de Dieu!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 17, 'Que désormais personne ne me fasse de la peine, car je porte en mon corps les stigmates de Jésus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 18, 'Frères, que la grâce de notre Seigneur Jésus-Christ soit avec votre esprit! Amen.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 1, 'Paul, apôtre de Jésus-Christ par la volonté de Dieu, aux saints qui sont à Éphèse, aux fidèles en Jésus-Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 2, 'Que la grâce et la paix vous soient données de la part de Dieu, notre Père, et du Seigneur Jésus-Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 3, 'Béni soit Dieu, le Père de notre Seigneur Jésus-Christ, qui nous a comblés en Christ de toutes sortes de bénédictions spirituelles dans les lieux célestes,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 4, 'nous qu\'il a élus en lui, avant la création du monde, pour que nous soyons saints et irrépréhensibles devant Dieu,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 5, 'nous ayant prédestinés, dans son amour, à devenir ses enfants d\'adoption par Jésus-Christ, selon le bon plaisir de sa volonté,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 6, 'à la louange de la grâce magnifique qu\'il nous a gratuitement accordée en son Fils bien-aimé!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 7, 'C\'est en lui que nous avons la rédemption par son rang, la rémission des péchés, selon les richesses de sa grâce');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 8, 'que Dieu a répandue abondamment sur nous, avec toute sorte de sagesse et d\'intelligence,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 9, 'en nous faisant connaître le mystère de sa volonté, suivant le dessein que, dans sa bienveillance, il avait d\'avance formé en lui-même, —');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 10, 'pour en assurer l\'exécution, quand les temps seraient accomplis, — de réunir toutes choses en Christ, aussi bien celles qui sont dans les cieux que celles qui sont sur la terre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 11, 'C\'est en lui aussi que nous avons été rendus participants de l\'héritage, comme nous y avions été prédestinés, suivant le dessein de Celui qui opère toutes choses conformément à la décision de sa volonté,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 12, 'afin que nous servions à célébrer sa gloire, nous qui avons, les premiers, espéré en Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 13, 'C\'est en lui que vous aussi, après avoir entendu la parole de la vérité, l\'Évangile de votre salut, — c\'est en lui que vous avez cru et que vous avez été scellés du Saint-Esprit qui avait été promis,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 14, 'lequel est un gage de notre héritage, jusqu\'à la rédemption de ceux qu\'il s\'est acquis pour célébrer sa gloire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 15, 'C\'est pourquoi, ayant entendu parler, moi aussi, de votre foi au Seigneur Jésus et de votre charité envers tous les saints,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 16, 'je ne cesse de rendre grâces pour vous, faisant mention de vous dans mes prières.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 17, 'Je prie le Dieu de notre Seigneur Jésus-Christ, le Père de gloire, de vous accorder un esprit de sagesse et de révélation qui vous apprenne à le connaître,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 18, 'et d\'illuminer les yeux de votre coeur afin que vous sachiez quelle est l\'espérance que fait naître en nous son appel, quelles sont, pour les saints, les richesses de son glorieux héritage,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 19, 'et quelle est, envers nous qui croyons, l\'infinie grandeur de sa puissance qui agit par la vertu souveraine de sa force.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 20, 'C\'est cette puissance qu\'il a déployée dans le Christ, en le ressuscitant des morts et en le faisant asseoir à sa droite dans les lieux célestes,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 21, 'au-dessus de tout pouvoir, de toute autorité, de toute puissance, de toute souveraineté, de tout nom qui puisse être nommé, non seulement dans ce siècle, mais aussi dans celui qui est à venir.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 22, 'Il a mis toutes choses sous ses pieds, et il l\'a donné pour chef suprême à l\'Église,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 23, 'qui est son corps, la plénitude de Celui qui remplit tout en tous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 1, 'Pour vous, vous étiez morts par vos fautes, par les péchés');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 2, 'auxquels vous vous êtes abandonnés autrefois, selon le train de ce monde, suivant le prince de la puissance de l\'air, cet esprit qui agit maintenant dans les enfants de rébellion.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 3, 'Nous tous aussi, nous étions de ce nombre, nous qui vivions autrefois suivant nos convoitises charnelles, accomplissant les volontés de notre chair et de nos pensées; et nous étions, par nature, des enfants de colère, comme le reste des hommes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 4, 'Mais Dieu, qui est riche en miséricorde, à cause du grand amour dont il nous a aimés,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 5, 'lorsque nous étions morts par nos fautes, nous a vivifiés avec le Christ — c\'est par grâce que vous êtes sauvés! —');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 6, 'Il nous a ressuscités ensemble, il nous a fait asseoir ensemble dans les lieux célestes en Jésus-Christ,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 7, 'pour faire éclater, dans les siècles à venir, l\'immense richesse de sa grâce, par la bonté dont il a usé envers nous en Jésus-Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 8, 'En effet, c\'est par la grâce que vous êtes sauvés, par le moyen de la foi, et cela ne vient pas de vous, c\'est le don de Dieu!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 9, 'Ce n\'est point par les oeuvres, afin que personne ne se glorifie;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 10, 'car nous sommes son ouvrage, ayant été créés en Jésus-Christ pour les bonnes oeuvres que Dieu a préparées d\'avance afin que nous les pratiquions.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 11, 'Souvenez-vous donc que vous, qui étiez jadis Païens par la naissance, et qui êtes appelés incirconcis par ceux qui s\'appellent les circoncis, à cause d\'une circoncision faite dans la chair par la main des hommes,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 12, 'vous étiez en ce temps-là sans Christ, privés du droit de cité en Israël, étrangers aux alliances de la promesse, sans espérance et sans Dieu dans le monde.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 13, 'Mais maintenant, en Jésus-Christ, vous qui étiez autrefois éloignés, vous avez été rapprochés par le sang du Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 14, 'Car c\'est lui qui est notre paix, lui qui des deux peuples en a fait un seul, ayant détruit le mur de séparation, l\'inimitié qui les divisait,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 15, 'en abolissant par sa propre chair la loi, avec ses prescriptions et ses commandements. Il a voulu ainsi, en faisant la paix, créer en lui-même avec les deux peuples une humanité nouvelle,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 16, 'et, après les avoir réunis en un seul corps, les réconcilier l\'un et l\'autre avec Dieu, par sa croix, ayant fait mourir par elle leur inimitié.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 17, 'Il est venu annoncer la paix à vous qui étiez loin, et la paix à ceux qui étaient près;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 18, 'car c\'est par lui que les uns et les autres nous avons accès auprès du Père, dans un même Esprit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 19, 'Ainsi, vous n\'êtes plus des étrangers, ni des gens du dehors; mais vous êtes concitoyens des saints et membres de la famille de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 20, 'Vous avez été édifiés sur le fondement des apôtres et des prophètes, Jésus-Christ lui-même étant la pierre de l\'angle,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 21, 'sur laquelle tout l\'édifice, bien coordonné, s\'élève pour être un temple saint dans le Seigneur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 22, 'C\'est par lui que, vous aussi, vous faites partie de cet édifice, pour devenir, en esprit, une maison où Dieu habite.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 1, 'C\'est à cause de cela que moi, Paul, je suis le prisonnier de Jésus-Christ pour vous, les Païens.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 2, '— En effet, vous avez dû apprendre la dispensation de Dieu à mon égard et la grâce qu\'il m\'a confiée en votre faveur;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 3, 'comment, par révélation, j\'ai eu connaissance du mystère que je viens de vous exposer en quelques mots.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 4, 'Vous pouvez comprendre, en les lisant, l\'intelligence que j\'ai du mystère de Christ,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 5, 'mystère qui n\'a pas été manifesté en d\'autres âges aux enfants des hommes, comme il a été révélé maintenant, par l\'Esprit, à ses saints apôtres et prophètes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 6, 'Ce mystère, c\'est que les Païens sont cohéritiers, membres du même corps, participant avec nous à la promesse qui a été faite en Jésus-Christ par l\'Évangile;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 7, 'et je suis devenu ministre de cet Evangile en vertu du don de la grâce de Dieu, qui m\'a été accordée par l\'efficacité de sa puissance.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 8, 'Oui, à moi, le moindre de tous les saints, cette grâce a été donnée, d\'annoncer aux Païens les richesses insondables du Christ,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 9, 'et de les éclairer sur cette dispensation du mystère caché de toute éternité en Dieu, le créateur de toutes choses.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 10, 'C\'est ainsi que, maintenant, la sagesse de Dieu, infiniment diverse, est manifestée par l\'Eglise aux dominations et aux puissances dans les lieux célestes,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 11, 'suivant son dessein éternel, qu\'il a réalisé en Jésus-Christ, notre Seigneur,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 12, 'en qui nous avons, par la foi en lui, la liberté de nous approcher de Dieu avec confiance.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 13, 'Aussi, je vous demande de ne point vous laisser décourager par les afflictions que j\'endure pour vous: elles sont votre gloire!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 14, 'C\'est à cause de cela que je fléchis les genoux devant le Père,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 15, 'duquel toute famille, dans les cieux et sur la terre, tire son nom,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 16, 'lui demandant que, selon les richesses de sa gloire, il vous donne d\'être puissamment fortifiés par son Esprit dans votre être intérieur;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 17, 'en sorte que le Christ habite dans vos coeurs par la foi, et qu\'étant enracinés et fondés dans l\'amour,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 18, 'vous puissiez comprendre, avec tous les saints, quelle en est la largeur, la longueur, la profondeur et la hauteur,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 19, 'et connaître l\'amour du Christ, qui surpasse toute connaissance, afin que vous soyez remplis de toute la plénitude de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 20, 'Or, à Celui qui peut, par la puissance qui opère en nous, faire infiniment au delà de tout ce que nous demandons et pensons,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 21, 'à Lui la gloire dans l\'Église et en Jésus-Christ, dans tous les âges, aux siècles des siècles! Amen.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 1, 'Je vous exhorte donc, — moi qui suis prisonnier dans le Seigneur, — à vous conduire d\'une manière digne de la vocation qui vous a été adressée,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 2, 'en toute humilité et en toute douceur, avec patience, vous supportant avec charité les uns les autres,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 3, 'et vous appliquant à conserver l\'unité de l\'esprit par le lien de la paix.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 4, 'Il y a un seul corps et un seul Esprit, de même que vous avez été appelés à une seule espérance par la vocation qui vous a été adressée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 5, 'Il y a un seul Seigneur, une seule foi, un seul baptême;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 6, 'il y a un seul Dieu et Père de tous, qui est au-dessus de tous, et parmi tous, et en tous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 7, 'Mais à chacun de nous la grâce a été donnée, selon la mesure du don de Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 8, 'C\'est pourquoi, il est dit: «Étant monté en haut, il a emmené en captivité une multitude de captifs, et il a comblé les hommes de ses dons.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 9, 'Or, que signifient ces mots: «Il est monté» si ce n\'est qu\'il est aussi descendu dans les régions inférieures de la terre?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 10, 'Celui qui est descendu est le même qui est monté au-dessus de tous les cieux, afin qu\'il remplît toutes choses.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 11, 'C\'est lui qui a donné les uns comme apôtres, les autres comme prophètes, d\'autres comme évangélistes, d\'autres comme pasteurs et docteurs,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 12, 'pour le perfectionnement des saints, en vue de l\'oeuvre du ministère et de l\'édification du corps de Christ,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 13, 'jusqu\'à ce que nous soyons tous parvenus à l\'unité de la foi et de la connaissance du Fils de Dieu, à l\'état d\'hommes faits, à la mesure de la stature parfaite du Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 14, 'Il a voulu que nous ne soyons plus des enfants, flottants et emportés à tout vent de doctrine par la tromperie des hommes et par leur habileté à rendre l\'erreur séduisante,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 15, 'mais que, professant la vérité dans la charité, nous croissions à tous égards en celui qui est le chef, Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 16, 'C\'est de lui que le corps tout entier, bien coordonné et fortement uni par toutes les jointures qui font communiquer ses parties, tire son développement, selon la force mesurée à chacune d\'elles, et s\'édifie lui-même dans la charité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 17, 'Voici donc ce que je dis et ce que je déclare, au nom du Seigneur: c\'est que vous ne devez plus vous conduire comme des Païens, qui suivent la vanité de leurs pensées,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 18, 'ayant l\'intelligence obscurcie, étant étrangers à la vie de Dieu, à cause de l\'ignorance qui est en eux, par suite de l\'endurcissement de leur coeur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 19, 'Ils ont perdu tout sentiment, et ils se sont abandonnés à une vie de désordre, pour commettre toute espèce d\'impureté avec une ardeur insatiable.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 20, 'Mais vous, ce n\'est pas ainsi qu\'on vous a appris à connaître le Christ,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 21, 'puisque vous avez entendu sa parole et qu\'on vous a enseigné en lui — suivant la vérité qui est en Jésus —');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 22, 'à vous dépouiller, en ce qui concerne votre vie passée, du vieil homme corrompu par les convoitises trompeuses,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 23, 'à être renouvelés dans l\'esprit qui inspire vos pensées,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 24, 'et à vous revêtir du nouvel homme, créé à l\'image de Dieu dans la justice et la sainteté que produit la vérité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 25, 'Ainsi donc, que chacun de vous, renonçant au mensonge, parle avec vérité à son prochain; car nous sommes membres les uns des autres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 26, 'Si vous vous mettez en colère, ne péchez point; que le soleil ne se couche pas sur votre colère,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 27, 'et ne donnez aucune prise au Diable.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 28, 'Que celui qui dérobait, ne dérobe plus; mais qu\'il s\'applique plutôt à faire de ses propres mains quelque travail honnête, pour avoir de quoi donner à celui qui est dans le besoin.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 29, 'Qu\'aucune mauvaise parole ne sorte de votre bouche; mais, s\'il y a lieu, dites quelque bonne parole qui serve à l\'édification et fasse du bien à ceux qui l\'entendent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 30, 'N\'attristez point le Saint-Esprit de Dieu, par lequel vous avez été scellés pour le jour de la rédemption.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 31, 'Que toute aigreur, que l\'animosité et la colère, les cris et les injures, soient bannis du milieu de vous, ainsi que toute méchanceté.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 32, 'Soyez bons les uns envers les autres, pleins de compassion, vous pardonnant réciproquement, comme Dieu aussi vous a pardonné en Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 1, 'Devenez donc les imitateurs de Dieu, comme ses enfants bien-aimés;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 2, 'et marchez dans la charité, à l\'exemple du Christ qui vous a aimés et qui s\'est donné lui-même à Dieu pour nous en offrande et en sacrifice, comme un parfum d\'agréable odeur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 3, 'Que ni la débauche, ni aucune impureté, ni l\'avarice, ne soient même nommées parmi vous, comme il convient à des saints.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 4, 'Point de paroles déshonnêtes, point de bouffonneries, point de plaisanteries frivoles, — toutes choses qui sont malséantes, — mais bien plutôt des actions de grâces.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 5, 'Car, sachez-le bien, ni le débauché, ni l\'impur, ni l\'avare, — qui est un idolâtre, — ne peuvent avoir part à l\'héritage du royaume du Christ et de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 6, 'Que personne ne vous séduise par de vains discours; car c\'est à cause de tout cela que la colère de Dieu vient sur les enfants de rébellion.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 7, 'N\'ayez donc rien de commun avec ces gens-là.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 8, 'Autrefois, en effet, vous étiez ténèbres, mais à présent, vous êtes lumière dans le Seigneur. Marchez comme des enfants de lumière;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 9, 'car le fruit de la lumière consiste en toute sorte de bonté, de justice et de vérité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 10, 'Examinez ce qui est agréable au Seigneur,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 11, 'et ne prenez aucune part aux oeuvres stériles des ténèbres, mais plutôt réprouvez-les;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 12, 'car on a honte même de dire ce que ces gens-là font en secret.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 13, 'Mais toutes ces choses, étant ainsi réprouvées, sont manifestées par la lumière; et tout ce qui est manifesté devient lumière.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 14, 'C\'est pourquoi il est dit: Réveille-toi, toi qui dors, et relève-toi d\'entre les morts, et le Christ t\'éclairera!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 15, 'Ainsi, veillez avec soin sur votre conduite, et comportez-vous non comme des insensés, mais comme des hommes sages.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 16, 'Rachetez le temps; car les jours sont mauvais.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 17, 'Ne soyez donc pas sans intelligence, mais comprenez bien quelle est la volonté du Seigneur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 18, 'Ne vous enivrez pas de vin; car le vin porte à la dissolution. Mais soyez remplis de l\'Esprit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 19, 'Édifiez-vous par le chant de psaumes, d\'hymnes et de cantiques spirituels, louant et célébrant de tout votre coeur le nom du Seigneur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 20, 'Rendez grâces en tout temps pour toutes choses à Dieu, notre Père, au nom de notre Seigneur Jésus-Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 21, 'Soumettez-vous les uns aux autres dans la crainte de Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 22, 'Femmes, soyez soumises à vos maris, comme au Seigneur,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 23, 'parce que le mari est le chef de la femme, comme aussi le Christ est le chef de l\'Église, qui est son corps, et dont il est le Sauveur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 24, 'Ainsi, de même que l\'Église est soumise au Christ, de même les femmes doivent l\'être à leurs maris en toutes choses.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 25, 'Maris, aimez vos femmes, comme le Christ a aimé l\'Église et s\'est livré lui-même pour elle,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 26, 'afin de la sanctifier, après l\'avoir purifiée par le baptême d\'eau et par la parole,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 27, 'pour faire paraître devant lui cette Église pleine de gloire, sans tache, ni ride, ni rien de semblable, mais sainte et irrépréhensible.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 28, 'De même, le mari doit aimer sa femme comme son propre corps. Celui qui aime sa femme, s\'aime lui-même.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 29, 'En effet, jamais un homme n\'a haï sa propre chair; mais il la nourrit et en prend soin, comme le Christ le fait pour l\'Église,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 30, 'parce que nous sommes membres de son corps.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 31, '«C\'est pourquoi, l\'homme quittera son père et sa mère pour s\'attacher à sa femme, et les deux ne feront qu\'une seule chair.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 32, 'Ce mystère est grand: je dis cela par rapport à Christ et à l\'Église.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 33, 'Ainsi donc, que chacun de vous aime sa femme comme lui-même; et que la femme respecte son mari.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 1, 'Enfants, obéissez à vos parents selon le Seigneur; car cela est juste.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 2, '«Honore ton père et ta mère — c\'est le premier commandement accompagné d\'une promesse,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 3, '— afin que tu sois heureux et que tu vives longtemps sur la terre»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 4, 'Et vous, pères, n\'irritez pas vos enfants, mais élevez-les en les instruisant et en les avertissant selon le Seigneur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 5, 'Serviteurs, obéissez avec crainte et avec respect, dans la simplicité de votre coeur, à ceux qui sont vos maîtres selon la chair, comme au Christ,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 6, 'ne les servant pas seulement sous leurs yeux, comme si vous cherchiez à plaire aux hommes, mais comme des serviteurs du Christ, qui font de bon coeur la volonté de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 7, 'Servez-les avec affection, comme si vous serviez le Seigneur lui-même, et non pas les hommes,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 8, 'sachant que chacun, soit esclave, soit libre, recevra du Seigneur sa récompense, selon le bien qu\'il aura fait.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 9, 'Quant à vous, maîtres, agissez de même à l\'égard de vos serviteurs, et abstenez-vous de menaces, sachant que vous avez, vous et eux, le même maître dans le ciel, et que devant lui il n\'y a point d\'acception de personnes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 10, 'Au reste, fortifiez-vous dans le Seigneur, et, par sa force toute-puissante.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 11, 'Revêtez-vous de toutes les armes de Dieu, afin de pouvoir tenir ferme contre les embûches du Diable.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 12, 'En effet, ce n\'est pas contre la chair et le sang que nous avons à combattre, mais contre les dominations, contre les puissances. contre les princes de ce monde de ténèbres, contre les esprits mauvais qui sont dans les régions célestes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 13, 'C\'est pourquoi, prenez toutes les armes de Dieu, afin que vous puissiez résister dans le mauvais jour, et qu\'ayant tout surmonté, vous demeuriez fermes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 14, 'Oui, tenez ferme, ayant la vérité pour ceinture de vos reins, étant revêtus de la cuirasse de la justice,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 15, 'ayant pour chaussures les bonnes dispositions que donne l\'Évangile de paix.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 16, 'Prenez, par-dessus tout, le bouclier de la foi, au moyen duquel vous pourrez éteindre tous les traits enflammés du Malin.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 17, 'Prenez aussi le casque du salut et l\'épée de l\'Esprit, c\'est-à-dire la Parole de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 18, 'Faites en tout temps, par l\'Esprit, toutes sortes de prières et de supplications. Veillez à cela avec une entière persévérance, et priez pour tous les saints.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 19, 'Priez aussi pour moi, afin qu\'il me soit donné, quand j\'ouvre la bouche, de faire connaître en toute liberté le mystère de l\'Évangile,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 20, '— pour lequel je remplis les fonctions d\'ambassadeur dans les chaînes, — afin, dis-je, que j\'en parle avec hardiesse, comme je dois en parler.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 21, 'Pour que vous sachiez, vous aussi, ce qui me concerne et ce que je fais, Tychique, notre frère bien-aimé, qui est un fidèle ministre du Seigneur, vous mettra au courant de tout.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 22, 'Je vous l\'ai envoyé tout exprès, afin que vous appreniez quelle est notre situation, et pour qu\'il console vos coeurs.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 23, 'Que la paix soit donnée aux frères, ainsi que l\'amour avec la foi, de la part de Dieu, le Père, et du Seigneur Jésus-Christ!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 24, 'Que la grâce soit avec tous ceux qui aiment notre Seigneur Jésus-Christ d\'un amour inaltérable!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 1, 'Paul et Timothée, serviteurs de Jésus-Christ, à tous les saints en Jésus-Christ, qui sont à Philippes, ainsi qu\'aux évêques et aux diacres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 2, 'Que la grâce et la paix vous soient données de la part de Dieu, notre Père, et du Seigneur Jésus-Christ!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 3, 'Je rends grâces à mon Dieu, toutes les fois que je me souviens de vous;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 4, 'et, dans toutes les prières que je fais pour vous tous, je prie toujours avec joie,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 5, 'à cause de la part que vous avez prise aux progrès de l\'Évangile, depuis le premier jour jusqu\'à maintenant,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 6, '— étant persuadé que celui qui a commencé en vous cette bonne oeuvre, en poursuivra l\'achèvement jusqu\'au jour de Jésus-Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 7, 'Il est bien juste que j\'éprouve au sujet de vous tous de tels sentiments; car je vous porte dans mon coeur, vous qui, soit dans mes liens, soit dans la défense et la confirmation de l\'Évangile, avez tous participé à la grâce qui m\'a été accordée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 8, 'Aussi Dieu m\'est-il témoin que je vous chéris tous avec la tendresse de Jésus-Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 9, 'Et ce que je demande dans mes prières, c\'est que votre charité abonde encore de plus en plus, avec la connaissance et tout le discernement nécessaire,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 10, 'pour bien apprécier la différence des choses, afin que vous soyez purs et irrépréhensibles pour le jour de Christ,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 11, 'portant en abondance les fruits de la justice, qui viennent de Jésus-Christ, à la gloire et à la louange de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 12, 'Or, je veux que vous sachiez, frères, que ce qui m\'est arrivé a plutôt contribué aux progrès de l\'Évangile,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 13, 'au point que, dans tout le prétoire et partout ailleurs, il est devenu manifeste. que je suis prisonnier pour Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 14, 'Et la plupart des frères, ayant, à cause de mes liens, une plus grande hardiesse dans le Seigneur, osent annoncer sans crainte la parole de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 15, 'Quelques-uns, il est vrai, prêchent le Christ dans un esprit d\'envie et de dispute; mais d\'autres aussi le font dans des dispositions bienveillantes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 16, 'Ceux-ci agissent par affection; ils savent que je suis établi pour la défense de l\'Évangile.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 17, 'Ceux-là, poussés par l\'esprit de parti, annoncent le Christ dans des intentions qui ne sont pas pures, croyant ajouter un surcroît d\'affliction à mes liens.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 18, 'Qu\'importe! De quelque manière que ce soit, avec un zèle apparent ou avec sincérité. Christ est annoncé: c\'est de quoi je me réjouis, et je m\'en réjouirai encore.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 19, 'Car je sais que cela tournera à mon salut, grâce à vos prières et au secours de l\'Esprit de Jésus-Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 20, 'J\'ai cette ferme espérance que je ne serai rendu confus en rien, mais que, maintenant comme toujours, je parlerai avec une entière liberté, et qu\'ainsi Christ sera glorifié dans mon corps, soit par ma vie, soit par ma mort.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 21, 'Car Christ est ma vie, et la mort m\'est un gain.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 22, 'S\'il vaut la peine pour moi de continuer à vivre dans la chair, et ce que je dois préférer, je ne saurais le dire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 23, 'Je suis pressé des deux côtés, mon désir étant de partir pour être avec Christ, ce qui est de beaucoup préférable;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 24, 'mais il est nécessaire pour vous que je demeure dans ce corps.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 25, 'C\'est là ma ferme confiance; aussi ai-je la certitude que je resterai et que je demeurerai avec vous tous, pour le progrès et la joie de votre foi,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 26, 'afin que, à mon retour auprès de vous, vous ayez toujours plus sujet, par rapport à moi, de vous glorifier en Jésus-Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 27, 'Seulement, conduisez-vous d\'une manière digne de l\'Évangile du Christ, afin que, soit que je vienne vous voir ou que je sois absent, j\'apprenne que vous demeurez fermes dans un même esprit, combattant d\'une même âme pour la foi de l\'Évangile,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 28, 'sans vous laisser intimider en rien par les adversaires: ce qui est un signe de perdition pour eux, mais de salut pour vous. Et cela est voulu de Dieu,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 29, 'lui qui vous a fait la grâce, par rapport à Christ, non seulement de croire en lui, mais encore de souffrir pour lui,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 30, 'en soutenant le même combat que vous m\'avez vu soutenir, et que je soutiens encore, comme vous l\'avez appris.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 1, 'S\'il y a donc quelque consolation en Christ, s\'il y a quelque soulagement dans la charité, s\'il y a quelque communion d\'esprit, s\'il y a quelque affection cordiale et quelque compassion,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 2, 'rendez ma joie parfaite en vivant en bonne intelligence, en ayant un même amour, une même âme, une seule et même pensée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 3, 'Ne faites rien par esprit de contestation, ni par vaine gloire; mais considérez les autres, par humilité, comme supérieurs à vous-mêmes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 4, 'Que chacun de vous, au lieu de ne regarder qu\'à son propre intérêt, regarde aussi à celui des autres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 5, 'Ayez les mêmes sentiments que Jésus-Christ a eus,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 6, 'lui qui, étant en forme de Dieu, n\'a pas voulu se prévaloir de son égalité avec Dieu,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 7, 'mais qui s\'est anéanti lui-même, prenant la forme d\'un serviteur et devenant semblable aux hommes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 8, 'Ayant paru comme un simple homme, il s\'est abaissé lui-même, se rendant obéissant jusqu\'à la mort, même jusqu\'à la mort de la croix.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 9, 'C\'est pourquoi aussi, Dieu l\'a souverainement élevé et lui a donné le nom qui est au-dessus de tout nom,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 10, 'afin qu\'au nom de Jésus, tout genou fléchisse dans les cieux, sur la terre et sous la terre,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 11, 'et que toute langue confesse que Jésus-Christ est le Seigneur, à la gloire de Dieu, le Père.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 12, 'Ainsi, mes bien-aimés, comme vous avez toujours obéi, travaillez à votre salut avec crainte et tremblement, non seulement comme vous le faisiez en ma présence, mais bien plus encore, maintenant que je suis absent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 13, 'Car c\'est Dieu qui opère en vous et la volonté et l\'exécution, en vertu de son bon plaisir.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 14, 'Faites toutes choses sans murmures et sans hésitations,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 15, 'afin que vous soyez sans reproche et sans tache, des enfants de Dieu irrépréhensibles au milieu d\'une génération dépravée et perverse, au sein de laquelle vous brillez comme des flambeaux dans le monde,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 16, 'portant la parole de vie; en sorte qu\'au jour du Christ, je puisse me glorifier de n\'avoir pas couru en vain, ni travaillé en vain.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 17, 'Et même, si mon sang doit servir d\'aspersion sur le sacrifice et l\'offrande de votre foi, j\'en ai de la joie, et je m\'en réjouis avec vous tous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 18, 'Vous aussi, ayez-en de la joie, et réjouissez-vous-en avec moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 19, 'Or j\'espère, par la grâce du Seigneur Jésus, vous envoyer bientôt Timothée, afin d\'être encouragé, à mon tour, par les nouvelles que j\'aurai de vous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 20, 'En effet, je n\'ai personne qui partage comme lui mes sentiments, pour s\'intéresser sincèrement à ce qui vous regarde:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 21, 'tous cherchent leur propre intérêt, et non celui de Jésus-Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 22, 'Mais vous connaissez sa fidélité éprouvée; vous savez qu\'il s\'est dévoué avec moi au service de l\'Évangile, comme un enfant auprès de son père.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 23, 'J\'espère donc vous l\'envoyer, dès que je serai au clair sur ma situation;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 24, 'et j\'ai cette confiance dans le Seigneur que je viendrai bientôt moi-même.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 25, 'En attendant, j\'ai cru nécessaire de vous envoyer Épaphrodite, mon frère, le compagnon de mes travaux et de mes combats, que vous avez délégué auprès de moi pour subvenir à mes besoins.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 26, 'Car il désirait ardemment vous voir tous, étant très tourmenté parce que vous aviez appris qu\'il était malade.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 27, 'En effet, il a été malade, et tout près de la mort; mais Dieu a eu pitié de lui, et non seulement de lui, mais aussi de moi, pour que je n\'eusse pas tristesse sur tristesse.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 28, 'Je l\'ai donc envoyé avec d\'autant plus d\'empressement, afin qu\'en le revoyant vous ayez de la joie, et que j\'aie moins de tristesse.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 29, 'Ainsi, recevez-le dans le Seigneur avec une joie entière, et honorez de tels hommes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 30, 'Car c\'est pour l\'oeuvre de Christ qu\'il a été près de la mort, ayant exposé sa vie pour suppléer aux services que vous ne pouviez me rendre vous-mêmes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 1, 'Au reste, mes frères, réjouissez-vous dans le Seigneur! Il ne m\'est pas pénible de vous répéter les mêmes choses; et pour vous, cela vous est avantageux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 2, 'Gardez-vous des chiens; gardez-vous des mauvais ouvriers; gardez-vous de la fausse circoncision.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 3, 'Car c\'est nous qui sommes la vraie circoncision, nous qui servons Dieu par l\'Esprit de Dieu, qui nous glorifions en Jésus-Christ et qui ne mettons point notre confiance dans la chair.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 4, 'Ce n\'est pas que je n\'eusse sujet, moi aussi, de me confier en la chair. Si d\'autres croient pouvoir se confier en la chair, je le puis bien davantage,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 5, 'moi, circoncis le huitième jour, de la race d\'Israël, de la tribu de Benjamin, Hébreu, fils d\'Hébreux; quant à la loi, Pharisien;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 6, 'quant au zèle, persécuteur de l\'Église; quant à la justice de la loi, exempt de tout reproche.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 7, 'Mais, ce qui était pour moi un gain, je l\'ai considéré comme une perte, à cause du Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 8, 'Certainement, je considère toutes ces choses comme une perte, à cause de la connaissance infiniment plus précieuse de Jésus-Christ, mon Seigneur, pour qui je me suis privé de tous ces avantages. Oui, je les considère comme des balayures, afin de gagner Christ,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 9, 'et d\'être trouvé en lui, — ayant non pas ma justice, celle qui vient de la loi, mais celle qui s\'obtient par la foi en Christ, la justice qui vient de Dieu et qui est fondée sur la foi, —');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 10, 'en sorte que je le connaisse, lui et la puissance de sa résurrection et la communion de ses souffrances, me rendant conforme à lui en sa mort,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 11, 'dans l\'espoir de parvenir aussi à la résurrection des morts.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 12, 'Ce n\'est pas que j\'aie déjà remporté le prix, ou que je sois déjà parvenu à la perfection, mais je cours afin de le saisir, puisque j\'ai été moi-même saisi par Jésus-Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 13, 'Frères, pour moi, je ne crois pas avoir encore atteint le but, mais je fais une chose: oubliant ce qui est derrière moi, et m\'élançant vers ce qui est devant moi,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 14, 'je cours vers le but, pour obtenir le prix de la vocation céleste de Dieu en Jésus-Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 15, 'Que ce soit donc là notre pensée, à nous tous qui sommes des hommes faits; et si sur quelque point vous pensez autrement. Dieu vous éclairera aussi là-dessus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 16, 'Seulement, au point où nous sommes arrivés, marchons ensemble.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 17, 'Soyez mes imitateurs, frères, et prenez exemple sur ceux qui se conduisent suivant le modèle que vous avez en nous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 18, 'Car je vous l\'ai dit souvent, et je vous le dis encore en pleurant: il y en a plusieurs qui ont une conduite telle, qu\'ils sont les ennemis de la croix du Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 19, 'Leur fin est la perdition; ils font de leur ventre leur Dieu, et ils mettent leur gloire dans ce qui fait leur honte, n\'ayant de pensées que pour les choses de la terre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 20, 'Mais nous, nous sommes citoyens des cieux; et c\'est de là que nous attendons notre Sauveur, le Seigneur Jésus-Christ,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 21, 'qui transformera notre corps misérable pour le rendre semblable à son corps glorifié, par le pouvoir qu\'il a de s\'assujettir toutes choses.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 1, 'Ainsi donc, mes bien-aimés et très chers frères, ma joie et ma couronne, demeurez fermes dans le Seigneur, mes bien-aimés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 2, 'J\'exhorte Évodie et j\'exhorte Syntyche à avoir un même sentiment dans le Seigneur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 3, 'Je te prie aussi, fidèle collègue, de leur venir en aide, parce qu\'elles ont combattu pour l\'Evangile avec moi, ainsi que Clément et mes autres compagnons d\'oeuvre, dont les noms sont dans le livre de vie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 4, 'Réjouissez-vous toujours dans le Seigneur. Oui, je le dirai encore: Réjouissez-vous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 5, 'Que votre douceur soit connue de tous les hommes. Le Seigneur est proche!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 6, 'Ne vous inquiétez de rien, mais, en toute occasion, présentez vos demandes à Dieu par des prières et des supplications, avec des actions de grâces.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 7, 'Et la paix de Dieu, qui surpasse toute intelligence, gardera vos coeurs et vos pensées en Jésus-Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 8, 'Au reste, mes frères, que tout ce qui est vrai, tout ce qui est honorable, tout ce qui est juste, tout ce qui est pur, tout ce qui est aimable, tout ce qui a bonne réputation, tout ce qui est vertueux et digne de louange, que toutes ces choses occupent vos pensées.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 9, 'Ce que vous avez appris, reçu, entendu de moi, ce que vous avez vu en moi, faites-le, et le Dieu de paix sera avec vous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 10, 'J\'ai éprouvé une grande joie, dans le Seigneur, de ce que votre intérêt pour moi a enfin porté de nouveaux fruits; vous y pensiez bien, mais l\'occasion vous manquait.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 11, 'Non pas que je veuille parler de mes besoins; car j\'ai appris à être content de l\'état où je me trouve.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 12, 'Je sais être dans la pauvreté, je sais aussi être dans l\'abondance. En tout et partout, j\'ai appris à être rassasié comme à avoir faim, à être dans l\'abondance comme à être dans la disette.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 13, 'Je puis tout par Celui qui me fortifie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 14, 'Néanmoins, vous avez bien fait de prendre part à mon affliction.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 15, 'Vous le savez aussi, vous Philippiens, lorsque je commençai à prêcher l\'Evangile, en quittant la Macédoine, aucune Eglise, si ce n\'est la vôtre, n\'entra en rapport avec moi pour établir entre nous un échange de dons;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 16, 'car, à Thessalonique déjà, et par deux fois, vous m\'avez envoyé de quoi subvenir à mes besoins.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 17, 'Ce n\'est pas que je recherche des présents, mais je recherche le fruit abondant qui vous en revient.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 18, 'J\'ai donc tout reçu, et je suis dans l\'abondance; je suis comblé, ayant reçu d\'Épaphrodite ce que vous m\'avez envoyé, comme un parfum de bonne odeur, un sacrifice que Dieu accepte et qui lui est agréable.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 19, 'Mon Dieu pourvoira aussi à tous vos besoins, selon sa richesse et avec gloire, par Jésus-Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 20, 'A Dieu, notre Père, soit la gloire aux siècles des siècles! Amen.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 21, 'Saluez tous les saints en Jésus-Christ. Les frères qui se trouvent avec moi vous saluent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 22, 'Tous les saints vous saluent, et principalement ceux qui sont de la maison de César.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 23, 'Que la grâce du Seigneur Jésus-Christ soit avec votre esprit!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 1, 'Paul, apôtre de Jésus-Christ par la volonté de Dieu, et Timothée, notre frère, à nos frères en Christ,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 2, 'les saints et les fidèles qui sont à Colosses. Que la grâce et la paix vous soient données de la part de Dieu, le Père!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 3, 'Nous rendons grâces à Dieu, le Père de notre Seigneur Jésus-Christ, dans les prières que nous faisons sans cesse pour vous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 4, 'En effet, nous avons entendu parler de votre foi en Jésus-Christ et de la charité que vous avez pour tous les saints,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 5, 'en vue de l\'espérance qui vous est réservée dans les cieux, et dont vous avez eu connaissance par la prédication de la vérité, c\'est-à-dire de l\'Évangile.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 6, 'Cet Évangile est au milieu de vous, comme il est dans le monde entier: il y porte des fruits et il y fait des progrès, comme il en a fait parmi vous, depuis le jour où vous avez entendu annoncer la grâce de Dieu et où vous avez appris à la connaître véritablement,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 7, 'telle que vous l\'a enseignée Épaphras, notre cher compagnon de service, qui nous seconde comme un fidèle ministre du Christ,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 8, 'et qui nous a dépeint la charité dont vous êtes animés par l\'Esprit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 9, 'C\'est pourquoi, nous aussi, depuis le jour où nous avons reçu ces nouvelles, nous ne cessons de prier pour vous et de demander à Dieu que vous soyez remplis de la connaissance de sa volonté, avec toute sorte de sagesse et d\'intelligence spirituelle,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 10, 'afin que vous vous conduisiez d\'une manière digne du Seigneur, pour lui plaire en toutes choses, produisant toute espèce de bonnes oeuvres, croissant dans la connaissance de Dieu,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 11, 'et étant fortifiés à tous égards par sa force glorieuse, pour tout supporter avec patience et avec joie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 12, 'Bénissez le Père, qui vous a rendus capables d\'avoir part à l\'héritage des saints dans la lumière:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 13, 'il nous a délivrés de la puissance des ténèbres et nous a fait passer dans le royaume de son Fils bien-aimé,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 14, 'en qui nous avons la rédemption, la rémission des péchés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 15, 'C\'est lui qui est l\'image du Dieu invisible, le premier-né de toute la création.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 16, 'Car c\'est en lui qu\'ont été créées toutes choses dans les cieux et sur la terre, les visibles et les invisibles, soit les trônes, soit les dominations, soit les autorités, soit les puissances: tout a été créé par lui et pour lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 17, 'Il est avant toutes choses, et toutes choses subsistent en lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 18, 'C\'est lui aussi qui est la tête du corps, le chef de l\'Église. Il est le commencement, le premier-né d\'entre les morts, afin qu\'en toutes choses il tienne le premier rang.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 19, 'Car il a plu à Dieu de faire habiter en lui toute sa plénitude,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 20, 'et de réconcilier par lui toutes choses avec lui-même, aussi bien celles qui sont sur la terre que celles qui sont dans les cieux, ayant fait la paix par le sang de sa croix.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 21, 'Quant à vous, qui étiez autrefois éloignés de Dieu et ses ennemis par vos pensées et par vos mauvaises oeuvres,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 22, 'il vous a maintenant réconciliés avec lui, par la mort que son Fils a soufferte en son corps, dans sa chair, pour vous faire comparaître en sa présence, saints, sans tache, irrépréhensibles,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 23, '— si du moins vous demeurez dans la foi, fermes, inébranlables, sans jamais vous écarter de l\'espérance proclamée par l\'Evangile, que vous avez entendu, qui a été prêché à toute créature sous le ciel, et dont moi, Paul, je suis devenu le ministre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 24, 'Je me réjouis maintenant des souffrances mêmes que j\'endure pour vous, et j\'achève de souffrir dans ma propre chair ce qui manque aux douleurs du Christ pour son corps, qui est l\'Église.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 25, 'C\'est de cette Église que je suis devenu le ministre, par la dispensation de Dieu qui m\'a confié la mission de vous annoncer pleinement la parole de Dieu,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 26, 'le mystère caché de tout temps et dans tous les âges, mais maintenant manifesté à ses saints.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 27, 'Car Dieu a voulu leur faire connaître quelles sont les glorieuses richesses de ce mystère parmi les Païens, c\'est-à-dire Christ en vous, l\'espérance de la gloire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 28, 'C\'est lui que nous annonçons, avertissant tout homme et instruisant tout homme en toute sagesse, afin de présenter à Dieu tout homme devenu parfait en Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 29, 'C\'est à cela que je travaille, en combattant avec le secours de sa force qui agit puissamment en moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 1, 'Je veux, en effet, que vous sachiez combien est grand le combat que je soutiens pour vous et pour ceux qui sont à Laodicée, comme pour tous ceux qui ne me connaissent pas de visage,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 2, 'afin que leurs coeurs soient consolés et qu\'ils soient unis dans la charité, pour être enrichis d\'une pleine certitude de l\'intelligence, de manière à connaître le mystère de Dieu, le Christ,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 3, 'dans lequel sont cachés tous les trésors de la sagesse et de la science.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 4, 'Je dis cela, afin que personne ne vous abuse par des discours séduisants.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 5, 'Car, bien qu\'absent de corps, je suis avec vous en esprit, et je me réjouis de voir le bon ordre qui règne parmi vous et la fermeté de votre foi en Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 6, 'Ainsi, comme vous avez reçu le Seigneur Jésus-Christ, marchez unis à lui;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 7, 'soyez enracinés et fondés en lui, affermis par la foi, telle qu\'elle vous a été enseignée, et abondez en actions de grâces.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 8, 'Prenez garde de ne pas vous laisser séduire par la philosophie et par de vaines subtilités, s\'inspirant des traditions humaines et des rudiments du monde, et non des enseignements du Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 9, 'Car en lui habite corporellement toute la plénitude de la divinité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 10, 'Et vous, vous avez tout pleinement en lui, qui est le chef de toute souveraineté et de toute puissance.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 11, 'En lui aussi vous avez été circoncis, non d\'une circoncision faite par la main de l\'homme, mais de la circoncision du Christ, qui consiste dans le dépouillement de notre être charnel.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 12, 'Ayant été ensevelis avec lui par le baptême, vous êtes aussi ressuscités avec lui, par la foi en la puissance de Dieu qui l\'a ressuscité des morts.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 13, 'Lorsque vous étiez morts par vos fautes et dans l\'incirconcision de votre chair, il vous a fait revivre avec lui; car il nous a pardonné toutes nos fautes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 14, 'Il a effacé l\'acte qui était rédigé contre nous et dont les dispositions nous étaient contraires, et il l\'a supprimé, en le clouant à la croix;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 15, 'il a dépouillé les dominations et les puissances, et il les a publiquement livrées en spectacle, en triomphant d\'elles par la croix.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 16, 'Ainsi donc, que personne ne porte un jugement sur vous à propos de ce que vous mangez ou buvez, ou à propos d\'une fête, d\'une nouvelle lune, ou d\'un sabbat;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 17, 'tout cela n\'est que l\'ombre des choses qui devaient venir, mais le corps est en Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 18, 'Ne vous laissez pas enlever de prix de la course par ces gens qui, sous prétexte d\'humilité, veulent rendre un culte aux anges. S\'abandonnant à leurs propres visions, enflés d\'un vain orgueil par leur sens charnel,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 19, 'ils ne demeurent pas attachés au chef, de qui tout le corps, soutenu et fortement uni par ses jointures et ses articulations, reçoit le développement qui vient de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 20, 'Si vous êtes morts avec Christ aux rudiments du monde, pourquoi vous laissez-vous imposer ces prescriptions, comme si vous viviez encore dans le monde:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 21, 'Ne prends pas, ne goûte pas, ne touche pas?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 22, 'Toutes ces prescriptions sont pernicieuses par l\'abus qu\'on en fait, et elles ne s\'inspirent que de préceptes et de commandements humains,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 23, 'bien qu\'elles se donnent des apparences de sagesse, par un culte volontaire et par une certaine humilité, en n\'épargnant pas le corps et en n\'ayant point égard à la satisfaction de la chair.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 1, 'Si donc vous êtes ressuscités avec le Christ, cherchez les choses qui sont en haut, où le Christ est assis à la droite de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 2, 'Attachez- vous aux choses qui sont en haut, et non à celles qui sont sur la terre;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 3, 'car vous êtes morts, et votre vie est cachée avec le Christ en Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 4, 'Lorsque le Christ, qui est votre vie, paraîtra, — alors, vous aussi, vous paraîtrez avec lui dans la gloire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 5, 'Faites donc mourir ce qui, dans vos membres, est terrestre, la débauche, l\'impureté, les passions, la mauvaise convoitise et l\'avarice, qui est une idolâtrie:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 6, 'voilà ce qui attire la colère de Dieu;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 7, 'et c\'est ainsi que vous vous conduisiez vous-mêmes autrefois, lorsque vous viviez dans ces vices.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 8, 'Mais maintenant rejetez, vous aussi, toutes ces choses, la colère, l\'animosité, la méchanceté. Qu\'aucune calomnie, aucune parole déshonnête ne sorte de votre bouche.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 9, 'Ne mentez point les uns aux autres, ayant dépouillé le vieil homme avec ses oeuvres,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 10, 'et ayant revêtu l\'homme nouveau, qui se renouvelle à l\'image de Celui qui l\'a créé, pour parvenir à la pleine connaissance.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 11, 'Il n\'y a ici ni Grec, ni Juif, ni circoncis, ni incirconcis, ni Barbare, ni Scythe, ni esclave, ni homme libre; mais Christ est tout et en tous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 12, 'Ayez donc, comme les élus de Dieu, ses saints et ses bien-aimés, des entrailles de miséricorde. Revêtez-vous de bonté, d\'humilité, de douceur, de patience,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 13, 'vous supportant les uns les autres, et vous pardonnant réciproquement, si l\'un de vous a quelque sujet de plainte contre l\'autre: comme le Seigneur vous a pardonné, vous aussi, pardonnez de même.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 14, 'Mais, par-dessus tout, revêtez-vous de la charité, qui est le lien de la perfection.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 15, 'Que la paix du Christ, à laquelle vous avez été appelés pour former un seul corps, règne dans vos coeurs. Soyez reconnaissants.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 16, 'Que la parole du Christ habite pleinement en vous et vous enrichisse de toute sagesse. Instruisez-vous et exhortez-vous les uns les autres par des psaumes, des hymnes, des cantiques spirituels; chantez de tout votre coeur à la gloire de Dieu, étant remplis de sa grâce.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 17, 'Quoi que vous fassiez, en parole ou en oeuvre, faites tout au nom du Seigneur Jésus, en rendant grâces par lui à Dieu; le Père.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 18, 'Femmes, soyez soumises à vos maris, comme cela se doit selon le Seigneur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 19, 'Maris, aimez vos femmes, et ne vous aigrissez pas contre elles.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 20, 'Enfants, obéissez à vos parents en toutes choses; car cela est agréable au Seigneur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 21, 'Pères, n\'irritez point vos enfants, de peur qu\'ils ne perdent courage.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 22, 'Serviteurs, obéissez en toutes choses à ceux qui sont vos maîtres selon la chair, ne les servant pas seulement sous leurs yeux, comme si vous cherchiez à plaire aux hommes, mais avec simplicité de coeur, dans la crainte du Seigneur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 23, 'Quelque travail que vous fassiez, faites-le de bon coeur, comme pour le Seigneur, et non pour les hommes,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 24, 'sachant que vous obtiendrez du Seigneur son héritage pour récompense. Servez Christ, le Seigneur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 25, 'Car celui qui agit injustement recevra le salaire de son injustice: il n\'y a point d\'acception de personnes!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 1, 'Maîtres, accordez à vos serviteurs ce qui est juste et équitable, sachant que vous avez, vous aussi, un Maître dans le ciel.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 2, 'Soyez persévérants et vigilants dans la prière, en y joignant l\'action de grâces.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 3, 'Priez également pour nous, demandant à Dieu qu\'il ouvre une porte à notre prédication, afin que je puisse annoncer le mystère du Christ, mystère pour lequel je suis dans les chaînes,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 4, 'et que je le fasse connaître, comme je dois en parler.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 5, 'Conduisez-vous avec sagesse à l\'égard de ceux du dehors. Rachetez le temps!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 6, 'Que votre parole soit toujours accompagnée de grâce et assaisonnée de sel, en sorte que vous sachiez répondre à chacun comme il convient.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 7, 'Tychique, notre frère bien-aimé, qui est un fidèle ministre du Seigneur et mon compagnon de service, vous mettra au courant de tout ce qui me concerne.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 8, 'Je vous l\'ai envoyé tout exprès, pour que vous appreniez quelle est notre situation, et pour qu\'il console vos coeurs.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 9, 'Avec lui est Onésime, notre fidèle et bien-aimé frère, qui est votre compatriote. Ils vous informeront de tout ce qui se passe ici.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 10, 'Aristarque, mon compagnon de captivité, vous salue, ainsi que Marc, le cousin de Barnabas, au sujet duquel vous avez reçu des instructions: s\'il va chez vous, accueillez-le bien.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 11, 'Jésus, surnommé Justus, vous salue aussi. Ce sont les seuls, parmi les circoncis, qui travaillent avec moi pour le royaume de Dieu: ils ont été pour moi une consolation.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 12, 'Épaphras, votre compatriote, serviteur de Jésus-Christ, vous salue. Il ne cesse de combattre pour vous dans ses prières, afin que vous deveniez parfaits et que vous demeuriez pleinement soumis à toute la volonté de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 13, 'Car je lui rends ce témoignage, qu\'il s\'emploie avec un grand zèle pour vous, et pour ceux de Laodicée et d\'Hiérapolis.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 14, 'Luc, le médecin bien-aimé, vous salue, ainsi que Démas.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 15, 'Saluez les frères qui sont à Laodicée, et Nymphas, et l\'Église qui se réunit dans sa maison.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 16, 'Après que cette lettre aura été lue parmi vous, ayez soin de la faire lire aussi dans l\'Église des Laodicéens, et de lire vous-mêmes celle qui viendra de Laodicée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 17, 'Enfin, dites à Archippe: Prends garde au ministère que tu as reçu au nom du Seigneur, afin de bien le remplir.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 18, 'La salutation est de ma main, à moi, Paul. Souvenez-vous de mes liens. Que la grâce soit avec vous!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 1, 'Paul des Thessaloniciens, qui est en Dieu, le Père, et en Jésus-Christ, notre Seigneur. Que la grâce et la paix vous soient données!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 2, 'Nous rendons grâces à Dieu en tout temps pour vous tous, faisant mention de vous dans nos prières;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 3, 'car nous nous souvenons sans cesse devant Dieu, notre Père, de l\'oeuvre de votre foi, du travail de votre charité, et de la fermeté de votre espérance en notre Seigneur Jésus-Christ:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 4, 'nous savons, frères aimés de Dieu, que vous avez été élus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 5, 'Notre Évangile, en effet, ne vous a pas été annoncé avec des paroles seulement, mais aussi avec puissance, avec l\'Esprit saint, et avec la force d\'une pleine conviction. Car vous savez bien ce que nous avons été parmi vous et pour l\'amour de vous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 6, 'Vous-mêmes, vous avez été nos imitateurs et ceux du Seigneur, en recevant la Parole au milieu de beaucoup d\'afflictions, avec la joie du Saint-Esprit;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 7, 'aussi avez-vous servi de modèle à tous les croyants de la Macédoine et de l\'Achaïe.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 8, 'Car, non seulement la parole du Seigneur a retenti de chez vous jusque dans la Macédoine et dans l\'Achaïe, mais la foi que vous avez en Dieu s\'est fait connaître en tous lieux, si bien que nous n\'avons pas besoin d\'en parler.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 9, 'Tous, en effet, racontent quel accueil nous avons trouvé auprès de vous, et comment vous vous êtes convertis à Dieu, abandonnant les idoles pour servir le Dieu vivant et vrai,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 10, 'et pour attendre des cieux son Fils qu\'il a ressuscité des morts, Jésus, qui nous délivre de la colère à venir.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 1, 'Vous le savez bien vous-mêmes, frères, ce n\'est pas en vain que nous sommes venus chez vous;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 2, 'mais, après avoir souffert et avoir été outragés à Philippes, comme vous le savez, nous ne laissâmes pas, nous confiant en notre Dieu, de vous annoncer hardiment l\'Évangile de Dieu au milieu de grands combats.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 3, 'Car notre prédication ne procède ni de l\'erreur, ni de motifs impurs, et elle n\'a pas recours à la fraude.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 4, 'Mais puisque Dieu nous a jugés dignes de nous confier la prédication de l\'Évangile, nous parlons, non pour plaire aux hommes, mais pour plaire à Dieu qui sonde nos coeurs.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 5, 'Jamais, vous le savez, nous n\'avons usé de paroles flatteuses; jamais nous n\'avons eu de motifs intéressés. Dieu en est témoin.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 6, 'Nous n\'avons pas non plus cherché la gloire qui vient des hommes, ni auprès de vous, ni auprès des autres, et cela, quoique nous eussions pu nous imposer, comme étant apôtres de Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 7, 'Mais nous avons été doux au milieu de vous, comme une nourrice qui prend un tendre soin de ses propres enfants.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 8, 'Ainsi, dans notre grande affection pour vous, nous souhaitions de vous donner, non seulement l\'Évangile de Dieu, mais aussi notre vie elle-même, tant vous nous étiez devenus chers.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 9, 'Vous vous souvenez, frères, de nos labeurs et de nos fatigues; c\'est en travaillant nuit et jour, pour n\'être à charge à aucun de vous, que nous vous avons prêché l\'Évangile de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 10, 'Vous êtes témoins, — et Dieu l\'est aussi, — que notre conduite, envers vous qui croyez, a été pure, juste, irréprochable;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 11, 'et vous savez que nous avons agi avec chacun de vous, comme un père avec ses enfants, vous exhortant, vous consolant, et vous conjurant');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 12, 'de vous conduire d\'une manière digne de Dieu, qui vous appelle à son royaume et à sa gloire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 13, 'C\'est pourquoi, nous ne cessons, nous aussi, de rendre grâces à Dieu de ce qu\'en recevant la parole de Dieu que nous vous annoncions, vous l\'avez accueillie, non comme une parole d\'homme, mais comme la parole de Dieu, — ce qu\'elle est véritablement: aussi agit-elle efficacement en vous qui croyez.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 14, 'En effet, mes frères, vous êtes devenus les imitateurs des Églises de Dieu, qui, dans la Judée, sont en Jésus-Christ. Vous avez souffert, de la part de vos propres compatriotes, ce qu\'elles ont souffert elles-mêmes de la part de ces Juifs,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 15, 'qui ont fait mourir et le Seigneur Jésus et les prophètes, et qui nous ont persécutés; qui déplaisent à Dieu et sont ennemis de tous les hommes;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 16, 'qui nous empêchent de parler aux Païens pour qu\'ils soient sauvés, et qui comblent sans cesse la mesure de leurs péchés. Mais la colère divine a fini par les atteindre!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 17, 'Pour nous, frères, séparés de vous pour quelque temps, de corps, mais non de coeur, nous avons cherché avec d\'autant plus d\'empressement à satisfaire notre vif désir de revoir votre visage.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 18, 'Aussi, par deux fois, avons-nous voulu aller vous trouver, — moi, du moins, Paul; mais Satan nous en a empêchés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 19, 'En effet, qui donc — sinon vous-mêmes — sera notre espérance, ou notre joie, ou la couronne dont nous nous glorifierons, en présence de notre Seigneur Jésus, à son avènement?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 20, 'Oui, vous êtes notre gloire et notre joie!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 1, 'C\'est pourquoi, ne pouvant plus attendre, nous avons mieux aimé rester seuls à Athènes,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 2, 'et vous envoyer Timothée, notre frère, serviteur de Dieu et ministre de l\'Évangile du Christ, pour vous affermir et vous encourager dans votre foi,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 3, 'afin qu\'aucun de vous ne soit ébranlé par de telles afflictions; car, vous le savez vous-mêmes, c\'est à cela que nous sommes destinés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 4, 'Et lorsque nous étions auprès de vous, nous vous avons dit d\'avance que nous aurions des afflictions à souffrir, comme cela est arrivé, et vous le savez bien.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 5, 'Ne pouvant donc attendre plus longtemps, j\'envoyai Timothée pour être informé de l\'état de votre foi, craignant que le Tentateur ne vous eût tentés et que notre travail ne fût devenu inutile.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 6, 'Mais Timothée, qui vient d\'arriver ici de chez vous, nous a donné de bonnes nouvelles de votre foi et de votre charité. Il nous a dit le bon souvenir que vous gardez toujours de nous, et le désir que vous avez de nous voir, comme nous désirons aussi vous voir nous-mêmes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 7, 'Ainsi, frères, au milieu de toutes nos peines et de toutes nos afflictions, vous avez été pour nous, par votre foi, un sujet de consolation.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 8, 'Car nous vivons maintenant, puisque vous demeurez fermes dans le Seigneur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 9, 'Et comment pourrions-nous assez rendre grâces à Dieu à votre sujet, pour toute la joie dont nous sommes comblés à cause de vous, en la présence de notre Dieu?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 10, 'Nous lui demandons nuit et jour, très instamment, de nous permettre de vous revoir, et d\'ajouter ce qui manque encore à votre foi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 11, 'Que Dieu lui-même, notre Père, et Jésus, notre Seigneur, dirigent nos pas vers vous!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 12, 'Et que le Seigneur fasse croître et abonder votre charité les uns pour les autres et à l\'égard de tous, comme il en est de nous-mêmes à votre égard,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 13, 'afin que vos coeurs soient affermis, et qu\'ils soient irrépréhensibles dans la sainteté devant Dieu, notre Père, lorsque notre Seigneur Jésus viendra avec tous ses saints!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 1, 'Au reste, frères, puisque vous avez appris de nous comment il faut vous conduire pour plaire à Dieu, — ce que vous faites d\'ailleurs, — nous vous demandons et vous conjurons, par le Seigneur Jésus, de marcher toujours plus dans cette voie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 2, 'Vous savez bien quels commandements nous vous avons donnés, de la part du Seigneur Jésus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 3, 'Car la volonté de Dieu, c\'est votre sanctification: il veut que vous vous absteniez de l\'impureté,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 4, 'et que chacun de vous sache posséder son corps dans la sainteté et dans l\'honnêteté,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 5, 'sans jamais vous livrer à des passions déréglées, comme le font les Païens qui ne connaissent pas Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 6, 'Que personne ne trompe son frère, ou ne lui fasse tort en quoi que ce soit, parce que le Seigneur fait justice de toutes choses, comme nous l\'avons déjà dit et attesté.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 7, 'En effet, Dieu ne nous a point appelés à la souillure, mais à la sanctification.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 8, 'C\'est pourquoi, celui qui rejette ce que nous disons ne rejette pas un homme, mais Dieu, qui a mis en vous son Saint-Esprit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 9, 'Quant à l\'amour fraternel, vous n\'avez pas besoin qu\'on vous écrive à ce sujet, car vous avez vous-mêmes appris de Dieu à vous aimer les uns les autres;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 10, 'et cet amour, vous le témoignez à l\'égard de tous les frères, dans toute la Macédoine. Mais nous vous prions, frères, de le témoigner toujours plus,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 11, 'et de mettre votre honneur à vivre paisiblement, à vous occuper de vos propres affaires et à travailler de vos mains, comme nous vous l\'avons recommandé,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 12, 'afin que vous vous conduisiez honnêtement vis-à-vis de ceux du dehors et que vous n\'ayez besoin de personne.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 13, 'Nous ne voulons pas, frères, que vous soyez dans l\'ignorance au sujet de ceux qui sont morts, — afin que vous ne vous affligiez pas, comme font les autres hommes qui n\'ont point d\'espérance.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 14, 'En effet, si nous croyons que Jésus est mort et qu\'il est ressuscité, nous devons croire aussi que Dieu ramènera par Jésus et avec lui ceux qui sont morts.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 15, 'Voici, en effet, ce que nous vous déclarons par la parole du Seigneur: nous, les vivants, qui serons restés jusqu\'à l\'avènement du Seigneur, nous ne devancerons pas ceux qui seront morts.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 16, 'Car le Seigneur lui-même, à un signal donné, à la voix d\'un archange et au son de la trompette de Dieu, descendra du ciel; et ceux qui seront morts en Christ ressusciteront premièrement.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 17, 'Ensuite nous, les vivants, restés sur la terre, nous serons enlevés tous ensemble avec eux au milieu des nuées, à la rencontre du Seigneur, dans les airs; et ainsi nous serons toujours avec le Seigneur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 18, 'Consolez-vous donc les uns les autres par ces paroles.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 1, 'Pour ce qui regarde les temps et les moments, vous n\'avez pas besoin, frères, qu\'on vous écrive à ce sujet;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 2, 'car vous savez fort bien vous-mêmes que le jour du Seigneur viendra comme un voleur dans la nuit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 3, 'Au moment où les hommes diront: Paix et sûreté! — c\'est alors qu\'une ruine soudaine les surprendra, comme les douleurs surprennent une femme enceinte, et ils n\'échapperont point.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 4, 'Mais vous, frères, vous n\'êtes pas dans les ténèbres; de sorte que ce jour-là ne vous surprendra pas comme un voleur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 5, 'Vous êtes tous enfants de la lumière et enfants du jour; nous ne sommes pas les enfants de la nuit ni des ténèbres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 6, 'Ne dormons donc pas comme les autres, mais veillons et soyons sobres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 7, 'Car ceux qui dorment, dorment la nuit; et ceux qui s\'enivrent, s\'enivrent la nuit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 8, 'Mais nous, qui sommes enfants du jour, soyons sobres, ayant revêtu la cuirasse de la foi et de la charité, et pris pour casque l\'espérance du salut.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 9, 'En effet, Dieu ne nous a pas destinés à la colère, mais à la possession du salut par notre Seigneur Jésus-Christ,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 10, 'qui est mort pour nous, afin que, soit que nous veillions, soit que nous dormions, nous vivions ensemble avec lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 11, 'Ainsi donc, exhortez-vous les uns les autres et édifiez-vous mutuellement, comme vous le faites aussi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 12, 'Nous vous demandons, frères, d\'avoir de la considération pour ceux qui travaillent parmi vous, qui vous dirigent selon le Seigneur et qui vous exhortent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 13, 'Ayez pour eux le plus grand amour, à cause de l\'oeuvre qu\'ils accomplissent. Soyez en paix entre vous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 14, 'Cependant, nous vous en prions, frères, avertissez ceux qui vivent dans le désordre. Consolez ceux qui ont le coeur abattu, soutenez les faibles, soyez patients envers tous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 15, 'Prenez garde à ce que personne ne rende à autrui le mal pour le mal; mais recherchez toujours ce qui est bien, soit entre vous, soit envers tout le monde.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 16, 'Soyez toujours joyeux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 17, 'Priez sans cesse.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 18, 'Rendez grâces pour toutes choses; car telle est, à votre égard, la volonté de Dieu en Jésus-Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 19, 'N\'éteignez point l\'Esprit;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 20, 'ne méprisez pas les prophéties;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 21, 'éprouvez toutes choses, et retenez ce qui est bon.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 22, 'Abstenez-vous du mal sous toutes ses formes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 23, 'Que le Dieu de paix vous sanctifie lui-même parfaitement; et que tout ce qui est en vous, l\'esprit, l\'âme et le corps, soit conservé irrépréhensible pour l\'avènement de notre Seigneur Jésus-Christ!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 24, 'Celui qui vous a appelés est fidèle, et c\'est lui qui accomplira cette oeuvre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 25, 'Frères, priez pour nous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 26, 'Saluez tous les frères par un saint baiser.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 27, 'Je vous en conjure par le Seigneur, que cette lettre soit lue à tous les frères.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 28, 'Que la grâce de notre Seigneur Jésus-Christ soit avec vous!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 1, 'Paul, Silvain et Timothée, à l\'Église des Thessaloniciens, qui est en Dieu, notre Père, et en Jésus-Christ, le Seigneur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 2, 'Que la grâce et la paix vous soient données de la part de Dieu, notre Père, et du Seigneur Jésus-Christ!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 3, 'Nous devons, frères, rendre sans cesse grâces à Dieu à votre sujet; et cela est bien juste, puisque votre foi fait de grands progrès, et que l\'amour que vous avez tous les uns pour les autres augmente de plus en plus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 4, 'Aussi, nous nous glorifions à votre sujet auprès des Eglises de Dieu, à cause de votre patience et de votre foi dans toutes les persécutions et les afflictions que vous endurez.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 5, 'Il y a là une preuve du juste jugement de Dieu, qui veut vous rendre dignes de son royaume, pour lequel vous souffrez.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 6, 'N\'est-il pas, en effet, conforme à la justice de Dieu, de rendre l\'affliction à ceux qui vous affligent,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 7, 'et de vous donner, à vous qui êtes affligés, du repos avec nous,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 8, 'lorsque le Seigneur Jésus apparaîtra, venant du ciel, avec les anges de sa puissance, au milieu des flammes de feu, pour faire justice de ceux qui ne connaissent point Dieu et qui n\'obéissent pas à l\'Évangile de notre Seigneur Jésus-Christ?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 9, 'Ils seront punis d\'une perdition éternelle, loin de la face du Seigneur et de la gloire de sa puissance,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 10, 'quand il viendra, en ce jour-là, pour être glorifié dans ses saints et admiré dans tous ceux qui auront cru; car vous avez cru au témoignage que nous avons rendu devant vous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 11, 'C\'est pourquoi, nous prions sans cesse pour vous, afin que notre Dieu vous rende dignes de l\'appel qu\'il vous a adressé, et qu\'il accomplisse en vous, avec puissance, tous les miséricordieux desseins de sa bonté et l\'oeuvre de la foi;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 12, 'en sorte que le nom de notre Seigneur Jésus soit glorifié en vous, et vous en lui, selon la grâce de notre Dieu et du Seigneur Jésus-Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 1, 'En ce qui concerne l\'avènement de notre Seigneur-Jésus-Christ et notre réunion avec lui, nous vous en prions, frères,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 2, 'ne vous laissez pas si promptement troubler l\'esprit, ni alarmer par une prétendue inspiration, par quelque parole ou quelque lettre qui nous serait attribuée, comme si le jour du Seigneur était proche.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 3, 'Que personne ne vous séduise en aucune manière. Car il faut qu\'auparavant l\'apostasie soit arrivée, et qu\'on ait vu paraître l\'homme de l\'iniquité, le fils de la perdition,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 4, 'l\'adversaire qui, s\'élevant au-dessus de tout ce qu\'on appelle Dieu ou qu\'on adore, va jusqu\'à s\'asseoir dans le temple de Dieu, se faisant passer lui-même pour Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 5, 'Ne vous souvient-il pas que je vous disais ces choses, lorsque j\'étais encore auprès de vous?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 6, 'Et maintenant, vous savez bien ce qui lui fait obstacle, pour qu\'il ne soit manifesté qu\'en son temps.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 7, 'Car déjà le mystère de l\'iniquité est à l\'oeuvre; seulement, il faut que celui qui lui fait encore obstacle soit écarté.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 8, 'Et alors sera manifesté l\'impie, que le Seigneur Jésus détruira par le souffle de sa bouche, et qu\'il anéantira par l\'éclat de son avènement.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 9, 'Cet impie apparaîtra avec la puissance de Satan, opérant toutes sortes de miracles, de signes et de prodiges menteurs,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 10, 'et recourant à toutes les séductions de l\'injustice pour la perte de ceux qui périssent, parce qu\'ils n\'ont pas ouvert leur coeur à l\'amour de la vérité, qui les aurait sauvés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 11, 'C\'est pour cela que Dieu leur envoie une puissance d\'égarement qui les fait croire au mensonge,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 12, 'afin que tous ceux qui n\'ont pas cru à la vérité, mais qui ont pris plaisir à l\'injustice, soient soumis à son jugement.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 13, 'Quant à nous, frères aimés du Seigneur, nous devons sans cesse rendre grâces à Dieu à votre sujet, parce qu\'il vous a choisis, dès le commencement, pour vous donner le salut, par la sanctification de l\'Esprit et par la foi en la vérité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 14, 'C\'est à cela aussi qu\'il vous a appelés par notre Évangile, pour que vous possédiez la gloire de notre Seigneur Jésus-Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 15, 'Ainsi donc, frères, demeurez fermes, et retenez les enseignements que nous vous avons transmis, soit de vive voix, soit par notre lettre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 16, 'Que notre Seigneur Jésus-Christ lui-même, et Dieu, notre Père, qui nous a aimés et nous a donnés par sa grâce une consolation éternelle et une bonne espérance,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 17, 'consolent vos coeurs et vous affermissent en toute bonne oeuvre et en toute bonne parole!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 1, 'Au reste, frères, priez pour nous, afin que la parole du Seigneur se répande librement, qu\'elle soit glorifiée partout, comme elle l\'est parmi vous,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 2, 'et que nous soyons délivrés des hommes fâcheux et méchants; car tous n\'ont pas la foi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 3, 'Le Seigneur est fidèle; il vous affermira et vous gardera du Malin.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 4, 'Nous avons à votre égard cette confiance dans le Seigneur, que vous faites et que vous ferez les choses que nous vous recommandons.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 5, 'Que le Seigneur dispose vos coeurs à aimer Dieu et à attendre patiemment Jésus-Christ!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 6, 'Frères, nous vous recommandons, au nom de notre Seigneur Jésus-Christ, de vous tenir à l\'écart de tout frère qui ne sait pas régler sa conduite, et qui ne suit pas les enseignements que vous avez reçus de nous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 7, 'Vous savez vous-mêmes ce que vous devez faire pour nous imiter; car c\'est une vie bien réglée que nous avons menée parmi vous,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 8, 'et nous n\'avons mangé gratuitement le pain de personne, mais nous avons travaillé nuit et jour, dans la fatigue et dans la peine, pour n\'être à charge à aucun de vous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 9, 'Non pas que nous n\'en eussions le droit, mais nous avons voulu nous donner à vous en exemple, afin que vous nous imitiez.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 10, 'Aussi bien, lorsque nous étions auprès de vous, nous vous le déclarions expressément: si quelqu\'un ne veut pas travailler, il ne doit pas non plus manger.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 11, 'Nous apprenons, en effet, que certains d\'entre vous ont une conduite irrégulière et qu\'au lieu de travailler, ils se mêlent de choses qui ne les regardent pas.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 12, 'Nous invitons ces gens-là et nous les exhortons, au nom du Seigneur Jésus-Christ, à travailler paisiblement, afin de manger le pain qu\'ils ont eux-mêmes gagné.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 13, 'Pour vous, frères, ne vous lassez pas de faire le bien.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 14, 'Et si quelqu\'un n\'obéit pas à ce que nous vous disons dans cette lettre, notez-le, et n\'ayez aucune relation avec lui, afin qu\'il en ait de la confusion.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 15, 'Toutefois, ne le regardez pas comme un ennemi, mais avertissez-le comme un frère.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 16, 'Que le Seigneur de la paix vous donne lui-même la paix en tout temps, de toute manière! Que le Seigneur soit avec vous tous!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 17, 'La salutation est de ma main, à moi, Paul. C\'est là ma signature dans toutes mes lettres: c\'est ainsi que j\'écris.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 18, 'Que la grâce de notre Seigneur Jésus-Christ soit avec vous tous!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 1, 'Paul, apôtre de Jésus-Christ, suivant l\'ordre de Dieu, notre Sauveur, et de Jésus-Christ, notre espérance, —');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 2, 'à Timothée, mon vrai fils en la foi. Que la grâce, la miséricorde et la paix te soient données de la part de Dieu, le Père, et de Jésus-Christ, notre Seigneur!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 3, 'Je te rappelle la recommandation que je te fis, en partant pour la Macédoine, de rester à Éphèse, afin d\'avertir certaines personnes de ne pas enseigner une autre doctrine,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 4, 'et de ne pas s\'attacher à des fables et à des généalogies sans fin, qui provoquent des disputes, au lieu de contribuer au développement de l\'oeuvre de Dieu, qui s\'accomplit par la foi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 5, 'La recommandation que je t\'adresse a pour but de t\'exhorter à la charité qui procède d\'un coeur pur, d\'une bonne conscience et d\'une foi sincère.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 6, 'Quelques-uns, ayant perdu ces choses de vue, se sont égarés dans de vains discours:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 7, 'ils veulent être docteurs de la loi, et ils ne comprennent ni ce qu\'ils disent, ni ce qu\'ils affirment.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 8, 'Or, nous savons que la loi est bonne pour celui qui en fait un usage légitime,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 9, 'et qui sait bien que la loi n\'a pas été établie pour le juste, mais pour les injustes et les rebelles, pour les impies et les pécheurs, les gens sans religion et les profanes, les meurtriers de père ou de mère et les homicides;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 10, 'pour les impudiques, les infâmes, les voleurs d\'hommes, les menteurs, les parjures, et pour quiconque s\'oppose à la saine doctrine:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 11, 'c\'est là ce qu\'enseigne le glorieux Évangile du Dieu bienheureux, dont la prédication m\'a été confiée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 12, 'Je rends grâces à celui qui m\'a fortifié, Jésus-Christ, notre Seigneur, de ce qu\'il m\'a jugé fidèle et m\'a établi dans le ministère,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 13, 'moi, qui étais auparavant un blasphémateur, un persécuteur, un homme violent; mais j\'ai obtenu miséricorde, parce que j\'ai agi par ignorance, étant dans l\'incrédulité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 14, 'Et la grâce de notre Seigneur a surabondé en moi avec la foi et la charité qui est en Jésus-Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 15, 'C\'est une parole certaine et digne d\'être reçue avec une entière confiance, que Jésus-Christ est venu dans le monde pour sauver les pécheurs, dont je suis le premier.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 16, 'Mais j\'ai obtenu miséricorde, afin qu\'en moi, le premier, Jésus-Christ manifestât toute sa clémence, et qu\'il me fît servir d\'exemple à ceux qui croiront en lui pour avoir la vie éternelle.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 17, 'Au Roi des siècles, immortel, invisible, seul Dieu, soient honneur et gloire aux siècles des siècles! Amen.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 18, 'La recommandation que je t\'adresse, Timothée, mon enfant, selon les prophéties qui ont été faites à ton sujet, c\'est que, soutenu par elles, tu combattes le bon combat,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 19, 'en gardant la foi et une bonne conscience. Quelques-uns ayant renoncé à cette bonne conscience, leur foi a fait naufrage:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 20, 'de ce nombre sont Hyménée et Alexandre, que j\'ai livrés à Satan, afin qu\'ils apprennent à ne plus blasphémer.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 1, 'Je recommande donc, avant toutes choses, qu\'on fasse des requêtes, des prières, des supplications et des actions de grâces pour tous les hommes,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 2, 'pour les rois et pour tous ceux qui exercent l\'autorité, afin que nous puissions mener une vie paisible et tranquille, en toute piété et en toute honnêteté.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 3, 'C\'est là une chose bonne et agréable aux yeux de Dieu, notre Sauveur,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 4, 'qui veut que tous les hommes soient sauvés et parviennent à la connaissance de la vérité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 5, 'En effet, il y a un seul Dieu, et un seul Médiateur entre Dieu et les hommes, Jésus-Christ, homme,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 6, 'qui s\'est donné lui-même en rançon pour tous. Tel est le témoignage qui a été rendu en son temps,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 7, 'et pour lequel — je dis la vérité, je ne mens point. — j\'ai été établi prédicateur, apôtre et docteur des Païens, afin de les instruire dans la foi et dans la vérité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 8, 'Je veux donc que les hommes prient en tout lieu, élevant au ciel des mains pures, sans colère et sans contestation.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 9, 'Je veux aussi que les femmes s\'habillent d\'une manière décente, qu\'avec pudeur et modestie elles se parent, non de tresses ou d\'or, de perles ou de vêtements somptueux,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 10, 'mais de bonnes oeuvres, comme il convient à des femmes qui font profession de piété.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 11, 'Que la femme écoute l\'instruction en silence, avec une entière soumission.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 12, 'Je ne permets pas à la femme d\'enseigner, ni de prendre autorité sur l\'homme; mais elle doit demeurer dans le silence.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 13, 'Car Adam fut formé le premier, et Eve ensuite.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 14, 'Et ce n\'est pas Adam qui fut séduit; mais la femme, ayant été séduite, tomba dans la transgression.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 15, 'Cependant, elle sera sauvée en devenant mère, si elle persévère sagement dans la foi, dans la charité et dans la sanctification.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 1, 'Cette parole est certaine: si quelqu\'un aspire à être évêque, il désire une charge excellente.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 2, 'Il faut donc que l\'évêque soit irrépréhensible, mari d\'une seule femme, sobre, prudent, digne, hospitalier, capable d\'enseigner.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 3, 'Qu\'il ne soit ni adonné au vin, ni violent, mais doux et pacifique; qu\'il ne soit pas attaché à l\'argent;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 4, 'qu\'il gouverne bien sa propre maison, et qu\'il tienne ses enfants dans la soumission et dans une parfaite honnêteté.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 5, 'En effet, si quelqu\'un ne sait pas gouverner sa propre maison, comment pourra-t-il s\'occuper de l\'Église de Dieu?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 6, 'Qu\'il ne soit pas nouvellement converti, de peur qu\'enflé d\'orgueil, il ne tombe sous la condamnation du Diable.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 7, 'Il faut aussi que ceux du dehors lui rendent un bon témoignage, pour qu\'il ne soit point exposé à l\'opprobre et ne tombe pas dans les pièges du Diable.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 8, 'De même, que les diacres soient graves; qu\'ils ne soient ni doubles dans leur langage, ni adonnés aux excès du vin, ni âpres au gain,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 9, 'mais qu\'ils gardent le mystère de la foi dans une conscience pure.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 10, 'Aussi faut-il qu\'ils soient d\'abord mis à l\'épreuve, et qu\'ils n\'obtiennent la charge de diacre que s\'ils sont trouvés sans reproche.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 11, 'Que leurs femmes soient graves, point médisantes, sobres, fidèles en toutes choses.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 12, 'Que les diacres soient maris d\'une seule femme; qu\'ils gouvernent bien leurs enfants et leur propre maison.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 13, 'En effet, ceux qui auront bien rempli leur ministère, acquerront un rang honorable et une grande assurance dans la foi en Jésus-Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 14, 'Je t\'écris ceci, tout en espérant aller te voir bientôt,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 15, 'afin que, si je tarde, tu saches comment il faut se conduire dans la maison de Dieu, qui est l\'Église du Dieu vivant, la colonne et l\'appui de la vérité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 16, 'Oui, de l\'aveu de tous, le mystère de la piété est grand: Celui qui a été manifesté en chair, a été justifié par l\'Esprit, vu des anges, prêché aux Païens, cru dans le monde, élevé dans la gloire!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 1, 'Or, l\'Esprit dit expressément que, dans les temps à venir, quelques-uns se détourneront de la foi pour s\'attacher à des esprits séducteurs et à des doctrines de démons,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 2, 'étant égarés par l\'hypocrisie de faux docteurs, qui auront la conscience cautérisée,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 3, 'qui défendront de se marier, et qui commanderont de s\'abstenir d\'aliments que Dieu a créés pour que les fidèles, qui connaissent la vérité, en usent avec actions de grâces.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 4, 'En effet, tout ce ce que Dieu a créé est bon, et rien n\'est à rejeter, pourvu qu\'on le prenne avec actions de grâces;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 5, 'car cela est sanctifié par la parole de Dieu et par la prière.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 6, 'En exposant ces choses aux frères, tu seras un bon ministre de Jésus-Christ, nourri des paroles de la foi et de la bonne doctrine à laquelle tu t\'es attaché.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 7, 'Rejette les fables profanes, ces contes de vieilles femmes. Exerce-toi à la piété.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 8, 'En effet, l\'exercice corporel est utile à peu de chose, tandis que la piété est utile à toutes choses, ayant la promesse de la vie présente et de celle qui est à venir.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 9, 'C\'est là une parole certaine et digne d\'être reçue avec une entière confiance.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 10, 'Car, si nous travaillons et si nous luttons, c\'est que nous avons mis notre espérance dans le Dieu vivant, qui est le Sauveur de tous les hommes, et principalement des fidèles.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 11, 'Voilà ce que tu dois annoncer et enseigner.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 12, 'Que personne ne méprise ta jeunesse; mais sois le modèle des fidèles dans tes paroles, dans ta conduite, par ta charité, ta foi, ta pureté.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 13, 'Jusqu\'à mon arrivée, applique-toi à la lecture, à l\'exhortation, à l\'enseignement.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 14, 'Ne néglige pas le don qui est en toi, que tu as reçu par le ministère des prophètes avec l\'imposition des mains de l\'assemblée des anciens.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 15, 'Occupe-toi de ces choses, donne-toi entièrement à elles, afin que tout le monde voie tes progrès.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 16, 'Prends garde à toi-même et à ton enseignement; persévère dans toutes ces choses, car, en agissant ainsi, tu te sauveras, toi et ceux qui t\'écoutent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 1, 'Ne reprends pas rudement un vieillard; mais exhorte-le comme un père, les jeunes gens, comme des frères,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 2, 'les femmes âgées comme des mères, les jeunes comme des soeurs, avec une entière pureté.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 3, 'Honore les veuves qui sont véritablement veuves.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 4, 'Mais si une veuve a des enfants ou des petits-enfants, qu\'ils apprennent avant tout à exercer leur piété envers leur propre famille, et à payer de retour leurs parents; car cela est agréable à Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 5, 'Celle qui est véritablement veuve et qui est demeurée seule, a mis son espérance en Dieu, et elle persévère nuit et jour dans les prières et les supplications.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 6, 'Mais, pour celle qui vit dans les plaisirs, quoique vivante, elle est morte.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 7, 'Rappelle-leur ces choses, afin qu\'elles soient sans reproche.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 8, 'Si quelqu\'un n\'a pas soin des siens et principalement de ceux de sa famille, il a renié la foi, et il est pire qu\'un infidèle.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 9, 'Pour être inscrite sur le rôle des veuves, il faut qu\'une femme n\'ait pas moins de soixante ans, qu\'elle n\'ait eu qu\'un mari,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 10, 'qu\'elle se soit rendue recommandable par ses bonnes oeuvres, qu\'elle ait élevé des enfants, exercé l\'hospitalité, lavé les pieds des saints, secouru les malheureux, pratiqué toutes sortes de bonnes oeuvres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 11, 'Mais refuse les veuves plus jeunes; car lorsque l\'attrait du plaisir les a détachées du Christ, elles veulent se marier,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 12, 'et elles s\'attirent ainsi le reproche d\'avoir violé leur premier engagement.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 13, 'Avec cela, étant oisives, elles prennent l\'habitude de courir de maison en maison; et non seulement elles sont oisives, mais encore elles sont bavardes et indiscrètes, parlant de choses dont on ne doit point parler.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 14, 'Je veux donc que les jeunes veuves se marient, qu\'elles aient des enfants, qu\'elles dirigent leur maison, et qu\'elles ne donnent à l\'adversaire aucune occasion de médire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 15, 'Car déjà quelques-unes se sont détournées pour suivre Satan.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 16, 'Si quelque fidèle a des veuves dans sa famille, qu\'il les assiste, et que l\'Église n\'en ait point la charge, afin qu\'elle puisse venir en aide à celles qui sont véritablement veuves.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 17, 'Que les anciens, qui dirigent bien l\'Église, soient estimés dignes d\'un double honneur, surtout ceux qui sont chargés de la prédication et de l\'enseignement.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 18, 'Car l\'Écriture dit: «Tu n\'emmuselleras pas le boeuf qui foule le grain»; et aussi: «L\'ouvrier est digne de son salaire.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 19, 'Ne reçois aucune accusation contre un ancien, si ce n\'est sur la déposition de deux ou trois témoins.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 20, 'Ceux qui sont en faute, reprends-les devant tous, afin d\'inspirer de la crainte aux autres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 21, 'Je te conjure devant Dieu, devant Jésus-Christ et devant les anges élus, d\'observer ces recommandations, sans agir avec prévention et avec partialité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 22, 'N\'impose les mains à personne avec précipitation; ne participe point aux péchés d\'autrui; conserve-toi pur toi-même.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 23, 'Ne continue pas à ne boire que de l\'eau; mais prends un peu de vin, à cause de ton estomac et de tes fréquentes indispositions.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 24, 'Les péchés de certains hommes sont manifestes et les désignent d\'avance au jugement; tandis que, chez d\'autres, on ne les découvre que plus tard.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 25, 'Il en est de même pour les bonnes oeuvres: il y en a qui sont manifestes, et celles qui ne le sont pas ne sauraient demeurer cachées.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 1, 'Que tous ceux qui sont sous le joug de la servitude regardent leurs maîtres comme dignes de tout respect, afin que le nom de Dieu et sa doctrine ne soient l\'objet d\'aucune calomnie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 2, 'Que ceux qui ont des fidèles pour maîtres ne les méprisent pas, sous prétexte que ce sont des frères, mais qu\'ils les servent d\'autant mieux que ce sont des fidèles et des bien-aimés qui reçoivent leurs bons offices. Voilà ce que tu dois enseigner et recommander.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 3, 'Si quelqu\'un donne un autre enseignement, et s\'il n\'adhère point aux paroles salutaires de notre Seigneur Jésus-Christ et à la doctrine qui produit la piété,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 4, 'il est enflé d\'orgueil, il ne sait rien; mais il a la maladie des questions oiseuses et des disputes de mots, d\'où naissent l\'envie, les querelles, les médisances, les mauvais soupçons,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 5, 'les vaines discussions de gens qui ont l\'esprit corrompu, qui sont privés de la vérité et regardent la piété comme une source de gain.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 6, 'Oui, c\'est un grand gain que la piété, unie au contentement d\'esprit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 7, 'En effet, nous n\'avons rien apporté dans ce monde, et nous n\'en pouvons rien emporter.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 8, 'Ainsi, pourvu que nous ayons la nourriture et le vêtement, nous devons nous en contenter;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 9, 'tandis que ceux qui veulent devenir riches tombent dans la tentation, dans le piège, et dans beaucoup de désirs insensés et pernicieux qui plongent les hommes dans la ruine et la perdition.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 10, 'Car l\'amour de l\'argent est la racine de tous les maux, et quelques-uns, pour s\'y être adonnés, se sont détournés de la foi et se sont attiré beaucoup de tourments.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 11, 'Mais toi, homme de Dieu, fuis ces choses et recherche la justice, la piété, la foi, la charité, la patience, la douceur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 12, 'Combats le bon combat de la foi. Saisis la vie éternelle à laquelle tu as été appelé, et pour laquelle tu as fait ta belle confession en présence de plusieurs témoins.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 13, 'Je t\'adjure devant Dieu qui donne la vie à toutes choses, et devant Jésus-Christ qui fit une si belle confession devant Ponce-Pilate,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 14, 'd\'observer le commandement, en demeurant sans tache et sans reproche, jusqu\'à l\'apparition de notre Seigneur Jésus-Christ,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 15, 'que manifestera en son temps le bienheureux et seul Souverain, le Roi des rois et le Seigneur des seigneurs,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 16, 'Celui qui seul possède l\'immortalité et qui habite une lumière inaccessible. Celui que nul homme n\'a vu ni ne peut voir, et à qui appartiennent l\'honneur et la puissance éternelle! Amen.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 17, 'Recommande aux riches de ce monde de n\'être pas orgueilleux et de ne point mettre leur espérance dans les richesses incertaines, mais de la placer en Dieu, qui nous fournit toutes choses en abondance pour que nous puissions en jouir.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 18, 'Recommande-leur de faire du bien, d\'être riches en bonnes oeuvres, prompts à donner et à faire part de ce qu\'ils possèdent,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 19, 'amassant ainsi pour l\'avenir un bon et solide trésor, afin d\'obtenir la vie véritable.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 20, 'Timothée, garde le dépôt qui t\'a été confié; évite les discours vains et profanes, et les objections d\'une science faussement ainsi nommée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 21, 'C\'est pour s\'être réclamés de cette science, que quelques-uns se sont détournés de la foi. Que la grâce soit avec vous!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 1, 'Paul, apôtre de Jésus-Christ par la volonté de Dieu, — pour annoncer la promesse de la vie qui est en Jésus-Christ, —');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 2, 'à Timothée, mon enfant bien-aimé. Que la grâce, la miséricorde et la paix te soient données de la part de Dieu, le Père, et de Jésus-Christ, notre Seigneur!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 3, 'Je rends grâces à Dieu que je sers, comme mes ancêtres l\'ont fait, avec une conscience pure, faisant mention de toi sans cesse, nuit et jour, dans mes prières.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 4, 'Car je me souviens de tes larmes, et j\'ai un grand désir de te voir, afin d\'être rempli de joie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 5, 'Je garde aussi le souvenir de ta foi sincère, la foi qui demeura d\'abord en Lois, ton aïeule, et en Eunice, ta mère, et qui, j\'en suis persuadé, demeure aussi en toi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 6, 'C\'est pourquoi, je te recommande de rallumer le don de Dieu, que tu as reçu par l\'imposition de mes mains.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 7, 'Car Dieu ne nous a pas donné un esprit de timidité, mais un esprit de force, d\'amour et de prudence.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 8, 'N\'aie donc pas honte du témoignage que tu dois rendre à notre Seigneur, ni de moi, qui suis son prisonnier; mais souffre avec moi pour l\'Évangile, par la force que Dieu donne.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 9, 'C\'est lui qui nous a sauvés et qui nous a appelés, par une vocation sainte, non pas selon nos oeuvres, mais selon son propre dessein, selon la grâce qui nous a été donnée en Jésus-Christ avant tous les siècles,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 10, 'et qui a été maintenant manifestée par l\'apparition de notre Sauveur Jésus-Christ, lequel a détruit la mort et mis en évidence la vie et l\'immortalité par l\'Évangile.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 11, 'C\'est pour cet Évangile que j\'ai été établi prédicateur, apôtre et docteur;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 12, 'et telle est la cause des maux que j\'endure. Mais je n\'en ai point honte; car je sais en qui j\'ai cru, et je suis persuadé qu\'il a la puissance de garder mon dépôt jusqu\'au grand jour.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 13, 'Conserve, dans la foi et dans la charité qui est en Jésus-Christ, le modèle des saines instructions que tu as reçues de moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 14, 'Garde le bon dépôt, par le Saint-Esprit qui habite en nous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 15, 'Tu sais que tous ceux qui sont en Asie m\'ont abandonné; de ce nombre sont Phygelle et Hermogène.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 16, 'Que le Seigneur fasse miséricorde à la famille d\'Onésiphore; car il m\'a souvent réconforté, et il n\'a pas eu honte de mes chaînes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 17, 'Bien plus, dès son arrivée à Rome, il m\'a cherché avec empressement, et il m\'a trouvé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 18, 'Que le Seigneur lui-même lui donne de trouver miséricorde auprès du Seigneur, au grand jour! Tu sais aussi, mieux que personne, tous les services qu\'il m\'a rendus à Éphèse.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 1, 'Toi donc, mon enfant, fortifie-toi dans la grâce qui est en Jésus-Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 2, 'Ce que tu as appris de moi en présence de plusieurs témoins, confie-le à des hommes fidèles, qui soient capables de l\'enseigner aussi à d\'autres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 3, 'Souffre Jésus-Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 4, 'Quand un homme part pour la guerre, il ne s\'embarrasse point des affaires de la vie, et cela, pour plaire à celui qui l\'a enrôlé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 5, 'De même, un athlète n\'est couronné que s\'il a combattu suivant les règles.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 6, 'Le laboureur qui travaille doit être le premier à recueillir les fruits.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 7, 'Comprends bien ce que je te dis; et le Seigneur lui-même te donnera de l\'intelligence en toutes choses.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 8, 'Souviens-toi que Jésus-Christ, né de la race de David, est ressuscité des morts, selon mon Évangile,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 9, 'pour lequel je souffre jusqu\'à être lié comme un malfaiteur; mais la parole de Dieu n\'est point liée!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 10, 'C\'est pourquoi, je supporte tout à cause des élus, afin qu\'eux aussi obtiennent le salut qui est en Jésus-Christ, avec la gloire éternelle.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 11, 'Cette parole est certaine: Si nous mourons avec lui, nous vivrons aussi avec lui;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 12, 'si nous endurons l\'épreuve, nous régnerons aussi avec lui; si nous le renions, il nous reniera aussi;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 13, 'si nous sommes infidèles, lui, il demeure fidèle, car il ne peut se renier lui-même.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 14, 'Voilà ce que tu dois rappeler, en attestant devant Dieu qu\'il faut éviter les disputes de mots: elles ne servent à rien qu\'à la ruine de ceux qui les écoutent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 15, 'Applique-toi à te rendre approuvé de Dieu, comme un ouvrier sans reproche, dispensant avec droiture la parole de la vérité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 16, 'Mais rejette les discours vains et profanes; car ceux qui les tiennent iront toujours plus loin dans l\'impiété,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 17, 'et leur parole rongera comme la gangrène. Tels sont Hyménée et Philète,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 18, 'qui se sont détournés de la vérité, en disant que la résurrection est déjà arrivée, et qui renversent ainsi la foi de quelques-uns.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 19, 'Toutefois, le solide fondement posé par Dieu demeure, ayant comme sceau ces paroles: Le Seigneur connaît ceux qui sont à lui. Et encore: Que tout homme qui invoque le nom du Seigneur, s\'éloigne de l\'iniquité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 20, 'Dans une grande maison, il n\'y a pas seulement des vases d\'or et d\'argent, il y en a aussi de bois et de terre, les uns servant à un usage noble, les autres à un usage vulgaire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 21, 'Ainsi, celui qui se préservera de ces souillures sera comme un vase d\'honneur, consacré, utile à son maître, et préparé pour toute bonne oeuvre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 22, 'Fuis les passions de la jeunesse, et recherche la justice, la foi, la charité, la paix avec ceux qui invoquent le Seigneur d\'un coeur pur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 23, 'Repousse les questions folles et absurdes, sachant qu\'elles n\'engendrent que des querelles.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 24, 'Or, il ne faut pas que le serviteur du Seigneur aime les querelles; mais il doit être bon envers tous, capable d\'enseigner, patient,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 25, 'instruisant avec douceur ceux qui sont d\'un avis contraire, dans l\'espoir que Dieu les amènera à la repentance pour les conduire à la connaissance de la vérité,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 26, 'et qu\'ils se réveilleront et se dégageront des pièges du Diable, qui les a surpris pour les assujettir à sa volonté.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 1, 'Sache que, dans les derniers jours, il surviendra des temps difficiles.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 2, 'En effet, les hommes seront épris d\'eux-mêmes, attachés à l\'argent, vaniteux, arrogants, médisants, rebelles à leurs parents, ingrats, profanes,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 3, 'durs, implacables, calomniateurs, intempérants, cruels, ennemis des gens de bien,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 4, 'traîtres, emportés, enflés d\'orgueil, amis du plaisir plutôt que de Dieu,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 5, 'gardant l\'apparence de la piété, mais ayant renié ce qui en fait la force. Éloigne-toi aussi de ces gens-là.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 6, 'Il en est parmi eux qui s\'introduisent dans les maisons, et qui captivent l\'esprit de certaines femmes chargées de péchés, possédées de diverses convoitises,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 7, 'apprenant toujours, sans pouvoir jamais parvenir à la connaissance de la vérité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 8, 'Et comme Jannès et Jambrès s\'opposèrent à Moïse, de même ces hommes s\'opposent à la vérité: leur esprit est corrompu, et leur foi incapable de résister à l\'épreuve.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 9, 'Mais ils ne réussiront pas dans leurs desseins; car leur folie sera rendue manifeste pour tout le monde, comme le fut celle de ces deux hommes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 10, 'Pour toi, tu t\'es attaché à me suivre dans mon enseignement, ma conduite, mes projets, dans ma foi, ma patience, ma charité, ma constance,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 11, 'dans les persécutions et les afflictions qui me sont survenues à Antioche, à Iconie, à Lystre. Ces persécutions, je les ai toutes supportées, et toujours le Seigneur m\'en a délivré.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 12, 'Aussi bien, tous ceux qui veulent vivre pieusement en Jésus-Christ seront persécutés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 13, 'Mais les hommes méchants et les imposteurs s\'enfonceront toujours plus dans le mal, égarant les autres en s\'égarant eux-mêmes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 14, 'Pour toi, demeure ferme dans les choses que tu as apprises et reçues avec une conviction entière. Tu sais, en effet, de qui tu les as apprises;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 15, 'et, depuis ton enfance, tu connais les saintes lettres, qui peuvent te rendre sage à salut par la foi en Jésus-Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 16, 'Toute l\'Écriture est divinement inspirée, et utile pour enseigner, pour convaincre, pour corriger, pour instruire dans la justice,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 17, 'afin que l\'homme de Dieu soit accompli et bien préparé pour toute bonne oeuvre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 1, 'Je t\'en conjure devant Dieu et devant Jésus-Christ, qui doit juger les vivants et les morts, et au nom de son avènement et de son règne:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 2, 'prêche la parole, insiste en temps et hors de temps, reprends, exhorte, censure avec une grande patience, et sans jamais cesser d\'instruire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 3, 'Car il viendra un temps où les hommes ne souffriront pas la saine doctrine; mais, ayant la démangeaison d\'entendre des choses agréables, ils rassembleront autour d\'eux des docteurs selon leurs propres désirs,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 4, 'et ils fermeront l\'oreille à la vérité pour se tourner vers des fables.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 5, 'Mais toi, sois sobre en toutes choses, endure la souffrance, fais l\'oeuvre d\'un évangéliste, acquitte-toi de tous les devoirs de ton ministère.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 6, 'Pour moi, je vais être immolé, et le temps de mon départ approche.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 7, 'J\'ai combattu le bon combat, j\'ai achevé la course, j\'ai gardé la foi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 8, 'Et maintenant, la couronne de justice m\'est réservée. Le Seigneur, juste juge, me la donnera en ce jour-là, et non seulement à moi, mais aussi à tous ceux qui auront aimé son avènement.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 9, 'Tâche de venir me rejoindre bientôt;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 10, 'car Démas m\'a abandonné, ayant aimé le présent siècle, et il est parti pour Thessalonique. Crescens est allé en Galicie, et Tite en Dalmatie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 11, 'Luc seul est avec moi. Prends Marc et amène-le avec toi, car il m\'est fort utile pour le ministère.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 12, 'J\'ai envoyé Tychique à Éphèse.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 13, 'Quand tu viendras, apporte le manteau que j\'ai laissé à Troas chez Carpus, et les livres, surtout les parchemins.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 14, 'Alexandre, l\'ouvrier en cuivre, m\'a fait beaucoup de mal; le Seigneur lui rendra selon ses oeuvres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 15, 'Toi aussi, sois en garde contre lui; car il s\'est fortement opposé à nos paroles.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 16, 'Dans ma première défense, personne ne m\'a assisté; tous m\'ont abandonné. Que cela ne leur soit pas imputé!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 17, 'Mais le Seigneur m\'a assisté et m\'a fortifié, afin que l\'Évangile fût pleinement annoncé par moi et que tous les Païens l\'entendissent; et j\'ai été délivré de la gueule du lion.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 18, 'Le Seigneur me délivrera de tout mal et me sauvera dans son royaume céleste. A lui soit la gloire, aux siècles des siècles! Amen.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 19, 'Salue Prisca et Aquilas, et la famille d\'Onésiphore.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 20, 'Éraste est resté à Corinthe, et j\'ai laissé Trophine malade à Milet.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 21, 'Tâche de venir avant l\'hiver. Eubulus, Pudens, Linus, Claudia et tous les frères te saluent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 22, 'Que le Seigneur soit avec ton esprit! Que la grâce soit avec vous!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 1, 'Paul, serviteur de Dieu et apôtre de Jésus-Christ, — pour amener les élus de Dieu à la foi et à la connaissance de la vérité qui produit la piété,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 2, 'dans l\'espérance de la vie éternelle, promise avant tous les siècles par le Dieu qui ne peut mentir,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 3, 'et mise en évidence, au temps voulu, par sa parole, dont la prédication m\'a été confiée sur l\'ordre même de Dieu, notre Sauveur, —');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 4, 'à Tite, mon vrai fils dans la foi qui nous est commune. Que la grâce et la paix te soient données de la part de Dieu, le Père, et de Jésus-Christ, notre Sauveur!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 5, 'Je t\'ai laissé en Crète pour que tu mettes en ordre tout ce qui reste à régler, et que tu établisses, comme je te l\'ai prescrit, des anciens dans chaque ville.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 6, 'Que chacun d\'eux soit irréprochable, mari d\'une seule femme; que ses enfants soient fidèles, et ne puissent être accusés ni d\'inconduite, ni d\'insubordination.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 7, 'En effet, il faut que l\'évêque soit irréprochable, étant l\'administrateur de la maison de Dieu. Qu\'il ne soit ni arrogant, ni colère, ni adonné au vin, ni violent, ni âpre au gain;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 8, 'mais qu\'il soit hospitalier, ami des gens de bien, prudent, juste, saint, tempérant,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 9, 'attaché à la vraie parole, telle qu\'elle a été enseignée, afin d\'être capable d\'exhorter suivant la saine doctrine, et de réfuter les contradicteurs.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 10, 'Il y en a plusieurs, en effet, surtout parmi ceux de la circoncision, qui ne veulent point se soumettre, vains parleurs, séducteurs d\'âmes, auxquels il faut fermer la bouche.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 11, 'Ils bouleversent des familles entières, enseignant pour un gain honteux ce qu\'on ne doit pas enseigner.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 12, 'L\'un d\'entre eux, leur propre prophète, a dit: «Crétois, toujours menteurs, méchantes bêtes, ventres paresseux.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 13, 'Ce témoignage est vrai. Reprends-les donc sévèrement, afin qu\'ils aient une foi saine,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 14, 'et qu\'ils ne s\'attachent pas à des fables judaïques et à des commandements d\'hommes qui se détournent de la vérité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 15, 'Tout est pur pour ceux qui sont purs; mais, pour ceux qui sont souillés et infidèles, rien n\'est pur; au contraire, leur esprit et leur conscience sont souillés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 16, 'Ils font profession de connaître Dieu; mais ils le renient par leurs oeuvres, étant abominables, rebelles, incapables d\'aucune bonne oeuvre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 1, 'Mais toi, enseigne ce qui est conforme à la saine doctrine.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 2, 'Que les vieillards soient sobres, graves, prudents, ayant une foi, une charité et une patience parfaitement saines.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 3, 'De même, que les femmes âgées aient un maintien qui respire la sainteté; qu\'elles ne soient point médisantes, ni adonnées aux excès de vin;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 4, 'qu\'elles donnent de sages instructions; qu\'elles apprennent aux jeunes femmes à aimer leurs maris et leurs enfants,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 5, 'à être modestes, chastes, occupées dans leurs maisons, à être bonnes, soumises à leurs maris, afin que la parole de Dieu ne soit exposée à aucun blâme.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 6, 'Exhorte aussi les jeunes gens à vivre dans la tempérance.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 7, 'Offre-leur à tous, en ta personne, le modèle des bonnes oeuvres et apporte, dans ton enseignement, de la pureté, de la gravité,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 8, 'une parole saine, irréprochable, afin que l\'adversaire soit confus, n\'ayant à dire aucun mal de nous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 9, 'Exhorte les serviteurs à être soumis à leurs maîtres, à leur complaire en toutes choses, à n\'être point contredisants,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 10, 'à ne rien détourner, mais à se montrer toujours d\'une parfaite fidélité, afin de faire honorer en tout la doctrine de Dieu, notre Sauveur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 11, 'En effet, la grâce de Dieu, salutaire à tous les hommes, a été manifestée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 12, 'Elle nous enseigne à renoncer à l\'impiété et aux convoitises mondaines, et à vivre, dans le siècle présent, selon la tempérance, la justice et la piété,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 13, 'en attendant la réalisation de notre bienheureuse espérance, la glorieuse apparition de notre grand Dieu et Sauveur Jésus-Christ,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 14, 'qui s\'est donné lui-même pour nous, afin de nous racheter de toute iniquité et de nous purifier, pour faire de nous un peuple qui lui appartienne en propre et qui soit zélé pour les bonnes oeuvres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 15, 'Enseigne ces choses; exhorte et reprends avec une pleine autorité. Que personne ne te méprise.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 1, 'Rappelle aux fidèles qu\'ils doivent être soumis aux autorités, aux magistrats, leur obéir, être prêts à toute bonne oeuvre,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 2, 'ne médire de personne, éviter les querelles, être conciliants, et se montrer d\'une parfaite douceur envers tous les hommes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 3, 'Car nous étions autrefois, nous aussi, insensés, rebelles, égarés, asservis toutes sortes de convoitises et à la volupté, vivant dans la méchanceté et dans l\'envie, dignes d\'être haïs et nous haïssant les uns les autres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 4, 'Mais, lorsque la bonté de Dieu, notre Sauveur, et son amour envers les hommes, ont été manifestés,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 5, '— il nous a sauvés, non pas à cause des oeuvres de justice que nous aurions accomplies, mais en vertu de sa miséricorde, par le baptême de la régénération et le renouvellement du Saint-Esprit');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 6, 'qu\'il a répandu sur nous avec abondance, par Jésus-Christ, notre Sauveur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 7, 'C\'est ainsi que, justifiés par sa grâce, nous sommes devenus, en espérance, les héritiers de la vie éternelle.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 8, 'Cette parole est certaine, et je veux que tu établisses fortement ces choses, afin que ceux qui ont cru en Dieu aient soin de s\'appliquer à de bonnes oeuvres: voilà ce qui est bon et utile aux hommes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 9, 'Mais écarte les questions folles, les généalogies, les querelles et les disputes au sujet de la loi; car elles sont inutiles et vaines.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 10, 'Évite l\'hérétique après un premier et second avertissement,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 11, 'sachant qu\'un tel homme est perverti et qu\'il pèche, étant condamné par sa propre conscience.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 12, 'Lorsque je t\'aurai envoyé Artémas ou Tychique, hâte-toi de venir me rejoindre à Nicopolis; car j\'ai résolu d\'y passer l\'hiver.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 13, 'Veille avec soin à ce que Zénas, le docteur de la loi, ainsi qu\'Apollos, ne manquent de rien à leur départ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 14, 'Les nôtres aussi doivent apprendre à s\'appliquer à de bonnes oeuvres pour subvenir aux besoins urgents, afin de ne pas demeurer stériles.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 15, 'Tous ceux qui sont avec moi te saluent. Salue ceux qui nous aiment dans la foi. Que la grâce soit avec vous tous!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 1, 'Paul, prisonnier de Jésus-Christ, et Timothée, notre frère, — à Philémon, notre bien-aimé et notre compagnon d\'oeuvre,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 2, 'ainsi qu\'à Appie, notre soeur, à Archippe, notre compagnon d\'armes, et à l\'Église qui se réunit dans ta maison.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 3, 'Que la grâce et la paix vous soient données de la part de Dieu, notre Père, et du Seigneur Jésus-Christ!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 4, 'Je rends sans cesse grâces à mon Dieu, en faisant mention de toi dans mes prières;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 5, 'car j\'entends parler de ta foi au Seigneur Jésus, et de la charité que tu témoignes à tous les saints.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 6, 'Je lui demande que cette foi, qui nous est commune, se montre efficace, en faisant reconnaître tout le bien qui s\'accomplit parmi nous pour Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 7, 'J\'ai éprouvé, en effet, une grande joie et une grande consolation à cause de ta charité, parce que, grâce à toi, frère, le coeur des saints a été soulagé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 8, 'C\'est pourquoi, bien que j\'aie en Christ toute liberté de te prescrire ce qui convient,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 9, 'j\'aime mieux faire appel à ta charité. Étant ce que je suis, moi Paul, un vieillard, et, de plus, aujourd\'hui le prisonnier de Jésus-Christ,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 10, 'je te prie pour mon fils que j\'ai engendré dans les chaînes, pour Onésime,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 11, 'qui autrefois t\'a été inutile, mais qui maintenant te sera très utile, et à moi aussi:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 12, 'je te le renvoie, lui qui est comme une partie de moi-même.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 13, 'J\'aurais désiré le retenir auprès de moi, pour qu\'il me servît, à ta place, dans les liens où je suis pour l\'Évangile.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 14, 'Mais je n\'ai rien voulu faire sans ton consentement, afin que le bien que tu feras ne soit pas forcé, mais volontaire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 15, 'Peut-être, en effet, n\'a-t-il été séparé de toi pour un temps, qu\'afin que tu le recouvres pour toujours,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 16, 'non plus comme un esclave, mais comme au-dessus d\'un esclave, comme un frère bien-aimé, tout particulièrement aimé de moi, et bien plus encore de toi, selon la chair et selon le Seigneur!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 17, 'Si donc tu me tiens pour ton ami, reçois-le comme moi-même.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 18, 'Que s\'il t\'a fait quelque tort, ou s\'il te doit quelque chose, porte-le-moi en compte.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 19, 'Moi Paul, j\'écris ceci de ma propre main: je te le rendrai — pour ne pas te rappeler que tu te dois toi-même à moi. —');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 20, 'Oui, frère, que je reçoive de toi cette joie dans le Seigneur; procure à mon coeur ce soulagement en Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 21, 'Je t\'écris, persuadé de ton obéissance, sachant que tu feras même plus que je ne dis!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 22, 'En même temps, prépare-toi à me donner aussi l\'hospitalité; car j\'espère vous être rendu, grâce à vos prières.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 23, 'Épaphras, qui est mon compagnon de captivité en Jésus-Christ, te salue,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 24, 'ainsi que Marc, Aristarque, Démas et Luc, mes compagnons d\'oeuvre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 25, 'Que la grâce du Seigneur Jésus-Christ soit avec votre esprit!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 1, 'Après avoir autrefois parlé à nos pères, à plusieurs reprises et de plusieurs manières, par les prophètes,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 2, 'Dieu nous a parlé dans ces derniers temps par le Fils, celui qu\'il a établi héritier de toutes choses et par lequel il a fait le monde,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 3, 'celui qui, étant le rayonnement de sa gloire, l\'empreinte même de sa personne, soutient toutes choses par sa parole puissante, et qui, après avoir accompli la purification des péchés, s\'est assis à la droite de la majesté divine dans les lieux très hauts:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 4, 'aussi est-il devenu d\'autant supérieur aux anges, qu\'il a hérité d\'un nom plus éminent que le leur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 5, 'Auquel des anges, en effet, Dieu a-t-il jamais dit: «Tu es mon Fils, je t\'ai engendré aujourd\'hui»? Et encore: «Je serai son Père, et il sera mon Fils»?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 6, 'Et, quand il introduit dans le monde son Fils premier-né, il dit encore: «Que tous les anges de Dieu l\'adorent!»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 7, 'A l\'égard des anges, il dit: «Il fait de ses anges des vents, et de ses serviteurs une flamme de feu.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 8, 'Mais il a dit à l\'égard du Fils: «Dieu, ton trône demeure aux siècles des siècles, et le sceptre de ta royauté est un sceptre d\'équité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 9, 'Tu as aimé la justice, et haï l\'iniquité; c\'est pourquoi, ô Dieu, ton Dieu t\'a oint d\'une huile de joie, de préférence à tes pareils»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 10, 'Et ailleurs: «C\'est toi, Seigneur, qui, au commencement, as fondé la terre; et les cieux sont l\'oeuvre de tes mains.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 11, 'Ils périront, mais toi, tu subsistes! Ils vieilliront tous comme un vêtement.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 12, 'Tu les rouleras comme un manteau, et ils seront transformés; mais toi, tu restes le même, et tes années ne finiront point.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 13, 'Auquel des anges Dieu a-t-il jamais dit: «Assieds-toi à ma droite, jusqu\'à ce que j\'aie mis tes ennemis sous tes pieds, pour te servir de marchepied»?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 14, 'Les anges ne sont-ils pas tous des esprits au service de Dieu, envoyés par lui pour exercer un ministère en faveur de ceux qui doivent recevoir en héritage le salut?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 1, 'C\'est pourquoi nous devons nous attacher d\'autant plus à ce que nous avons entendu, de peur que nous ne soyons entraînés à notre perte.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 2, 'En effet, si la parole annoncée par des anges a eu son accomplissement, si toute transgression, toute désobéissance, a reçu sa juste rétribution,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 3, 'comment échapperons-nous, si nous négligeons un si grand salut? — salut qui, annoncé d\'abord par le Seigneur, nous a été confirmé par ceux qui l\'avaient entendu,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 4, 'Dieu appuyant leur témoignage par des signes, des prodiges et toutes sortes de miracles, et par les dons du Saint-Esprit, qu\'il a distribués selon sa volonté.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 5, 'En effet, ce n\'est pas à des anges qu\'il a soumis le monde à venir dont nous parlons.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 6, 'Mais quelqu\'un a rendu quelque part ce témoignage: «Qu\'est-ce que l\'homme, pour que tu te souviennes de lui? ou le fils de l\'homme, pour que tu en prennes soin?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 7, 'Tu l\'as fait, pour un peu de temps, inférieur aux anges; tu l\'as couronné de gloire et d\'honneur;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 8, 'tu as mis toutes choses sous ses pieds» En lui soumettant ainsi toutes choses, Dieu n\'a rien laissé qui ne lui fût soumis; cependant, nous ne voyons pas encore que toutes choses lui soient soumises.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 9, 'Mais ce Jésus, qui a été fait, pour un peu de temps, inférieur aux anges, nous le voyons, à cause de la mort qu\'il a soufferte, couronné de gloire et d\'honneur. C\'est ainsi que, par la grâce de Dieu, il a goûté la mort pour tous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 10, 'En effet, il convenait que Celui pour qui et par qui sont toutes choses, voulant amener beaucoup de fils à la gloire, élevât à la perfection, par les souffrances, l\'auteur et le chef de leur salut.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 11, 'Car celui qui sanctifie et ceux qui sont sanctifiés, sont tous issus du même Père. C\'est pourquoi, il ne dédaigne pas de donner à ceux-ci le nom de frères,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 12, 'quand il dit: «J\'annoncerai ton nom à mes frères; je te louerai au milieu de l\'assemblée.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 13, 'Il dit ailleurs: «Je me confierai en lui.» Et encore: «Me voici, moi et les enfants que Dieu m\'a donnés.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 14, 'Ainsi donc, puisque les enfants participent au sang et à la chair, il y a aussi participé lui-même, afin que, par sa mort, il anéantît la puissance de celui qui avait l\'empire de la mort, je veux dire le Diable,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 15, 'et qu\'il délivrât tous ceux qui, par la crainte de la mort, étaient toute leur vie retenus dans la servitude.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 16, 'Car ce n\'est pas aux anges, assurément, qu\'il vient en aide, c\'est à la postérité d\'Abraham.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 17, 'Aussi fallait-il qu\'il fût rendu semblable en toutes choses à ses frères, afin d\'être, auprès de Dieu, un souverain sacrificateur miséricordieux et fidèle, pour expier les péchés du peuple.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 18, 'En effet, comme il a souffert lui-même et qu\'il a été tenté, il peut secourir ceux qui sont tentés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 1, 'En conséquence, frères saints, vous qui avez part à la vocation céleste, considérez bien l\'apôtre et le souverain sacrificateur de la foi que nous professons,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 2, 'Jésus, qui a été fidèle à Celui qui l\'a établi, comme Moïse aussi l\'a été dans toute sa maison.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 3, 'En effet, il a été jugé digne d\'une gloire d\'autant supérieure à celle de Moïse, que le constructeur d\'une maison est plus admiré que la maison même.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 4, 'Il n\'y a pas de maison, en effet, qui n\'ait été construite par quelqu\'un; or, celui qui a construit toutes choses, c\'est Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 5, 'Quant à Moïse, il a été fidèle dans toute sa maison, comme un serviteur appelé à rendre témoignage de ce qui devait être annoncé plus tard.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 6, 'Mais Christ l\'est comme un fils à la tête de sa maison; et sa maison, c\'est nous, pourvu que nous retenions fermement, jusqu\'à la fin, la confiance et l\'espérance dont nous nous glorifions.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 7, 'C\'est pourquoi, ainsi parle le Saint-Esprit: «Aujourd\'hui, si vous entendez sa voix,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 8, 'n\'endurcissez pas vos coeurs, comme il arriva au jour de la révolte, au jour de la tentation dans le désert,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 9, 'lorsque vos pères me tentèrent pour me mettre à l\'épreuve, eux qui avaient vu mes oeuvres pendant quarante ans!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 10, 'Aussi ai-je été irrité contre cette génération, et j\'ai dit: Leur coeur s\'égare toujours, et ils n\'ont pas suivi mes voies.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 11, 'Et voici le serment que j\'ai fait dans ma colère: Jamais ils n\'entreront dans mon repos!»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 12, 'Frères, prenez garde que quelqu\'un de vous n\'ait un coeur mauvais et incrédule, et ne se sépare du Dieu vivant.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 13, 'Mais exhortez-vous les uns les autres chaque jour, aussi longtemps qu\'on peut dire: «Aujourd\'hui», afin qu\'aucun d\'entre vous ne s\'endurcisse, étant séduit par le péché.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 14, 'En effet, nous avons été rendus participants du Christ, à la condition de tenir ferme jusqu\'à la fin notre assurance première,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 15, 'pendant qu\'il est dit encore: «Aujourd\'hui, si vous entendez sa voix, n\'endurcissez pas vos coeurs, comme il arriva au jour de la révolte»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 16, 'Qui sont, en effet, ceux qui se révoltèrent, après avoir entendu sa voix, sinon tous ceux qui étaient sortis d\'Égypte, sous la conduite de Moïse?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 17, 'Et contre qui Dieu fut-il indigné pendant quarante ans? N\'est-ce pas contre ceux qui avaient péché et dont les corps tombèrent dans le désert?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 18, 'Et à qui jura-t-il qu\'ils n\'entreraient pas dans son repos? N\'est-ce pas à ceux qui avaient refusé de croire?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 19, 'Nous voyons, en effet, qu\'ils ne purent y entrer, à cause de leur incrédulité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 1, 'Craignons donc, alors que la promesse «d\'entrer dans son repos» subsiste encore, que quelqu\'un d\'entre nous ne vienne à en être exclu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 2, 'Car cette bonne nouvelle nous a été annoncée comme à eux; mais la parole qu\'ils ont entendue ne leur a servi de rien, parce que, en l\'entendant, ils ne se la sont pas appropriée par la foi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 3, 'Pour nous, qui avons cru, nous entrons dans le repos dont Dieu a parlé, quand il a dit: «Voici le serment que j\'ai fait dans ma colère: Jamais ils n\'entreront dans mon repos!» Et cependant, ses oeuvres étaient achevées depuis la création du monde.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 4, 'Car il est dit quelque part, à propos du septième jour: «Dieu se reposa de toutes ses oeuvres le septième jour.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 5, 'Et, d\'un autre côté, dans ce passage: «Jamais ils n\'entreront dans mon repos»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 6, 'Ainsi, puisqu\'il est réservé à quelques-uns d\'y entrer, et que ceux qui avaient reçu les premiers cette bonne nouvelle, n\'y sont pas entrés à cause de leur incrédulité,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 7, 'Dieu fixe de nouveau un jour qu\'il appelle «Aujourd\'hui», et il le fait dans un psaume de David, bien longtemps après, comme il est dit plus haut: «Aujourd\'hui, si vous entendez sa voix, n\'endurcissez pas vos coeurs!»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 8, 'En effet, si Josué leur avait donné le repos, Dieu ne parlerait pas après cela d\'un autre jour.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 9, 'Il reste donc un repos pour le peuple de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 10, 'Car celui qui entre dans le repos de Dieu, se repose de ses oeuvres, comme Dieu s\'est reposé des siennes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 11, 'Efforçons-nous donc d\'entrer dans ce repos, afin qu\'aucun de nous ne vienne à tomber, en donnant le même exemple d\'incrédulité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 12, 'Car la parole de Dieu est vivante et efficace, plus pénétrante qu\'aucune épée à deux tranchants; elle atteint jusqu\'à la division de l\'âme et de l\'esprit, des jointures et des moelles; elle est le juge des intentions et des pensées du coeur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 13, 'Aucune créature n\'est cachée devant lui, mais tout est à nu et à découvert aux yeux de Celui à qui nous devons rendre compte.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 14, 'Ainsi donc, puisque nous avons un grand et souverain sacrificateur, qui a pénétré les cieux, Jésus, le Fils de Dieu, demeurons fermes dans la profession de notre foi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 15, 'Car nous n\'avons pas un souverain sacrificateur qui ne puisse compatir à nos faiblesses, puisqu\'il a été tenté comme nous en toutes choses, sans commettre aucun péché.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 16, 'Approchons-nous donc avec assurance du trône de la grâce, afin d\'obtenir miséricorde et de trouver grâce, pour être secourus au moment convenable.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 1, 'Tout souverain sacrificateur, pris parmi les hommes, est établi pour les hommes dans le service de Dieu, afin d\'offrir des dons et des sacrifices pour les péchés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 2, 'Il peut témoigner de la compassion à ceux qui sont dans l\'ignorance et dans l\'égarement, puisque lui-même est sujet à la faiblesse.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 3, 'Et c\'est à cause de cette faiblesse qu\'il doit offrir des sacrifices pour ses péchés, aussi bien que pour ceux du peuple.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 4, 'Du reste, personne ne s\'arroge cette dignité; il faut y être appelé de Dieu, comme le fut Aaron.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 5, 'De même aussi, le Christ ne s\'est pas attribué à lui-même la gloire d\'être souverain sacrificateur; mais il la tient de celui qui lui a dit: «Tu es mon Fils; je t\'ai engendré aujourd\'hui.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 6, 'Et ailleurs encore, il lui dit: «Tu es sacrificateur pour l\'éternité, selon l\'ordre de Melchisédec.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 7, 'C\'est lui qui, dans les jours de sa chair, a offert, avec de grands cris et avec des larmes, des prières et des supplications à Celui qui pouvait le sauver de la mort, et qui a été exaucé à cause de sa piété.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 8, 'Tout Fils qu\'il est, il a appris l\'obéissance par les choses qu\'il a souffertes;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 9, 'et, après avoir été élevé à la perfection, il est devenu l\'auteur d\'un salut éternel pour tous ceux qui lui obéissent,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 10, 'Dieu l\'ayant déclaré souverain sacrificateur, selon l\'ordre de Melchisédec.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 11, 'Nous aurions à ce sujet beaucoup à dire, et des choses difficiles à expliquer, parce que vous êtes devenus lents à comprendre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 12, 'Vous, qui devriez être depuis longtemps des maîtres, vous avez encore besoin qu\'on vous enseigne les premiers éléments des oracles de Dieu: vous en êtes à avoir besoin de lait, au lieu d\'une nourriture solide!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 13, 'Or, celui qui ne se nourrit que de lait, ne saurait comprendre la parole de la justice; il n\'est encore qu\'un enfant.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 14, 'Mais la nourriture solide est pour les hommes faits, pour ceux qui ont le sens exercé, par l\'usage, au discernement du bien et du mal.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 1, 'Ainsi donc, laissant les premiers enseignements de l\'Évangile du Christ, tendons à ce qui est parfait, sans poser de nouveau les vérités élémentaires, c\'est-à-dire le renoncement aux oeuvres mortes et la foi en Dieu,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 2, 'la doctrine des baptêmes et l\'imposition des mains, la résurrection des morts et le jugement éternel:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 3, 'c\'est là ce que nous ferons, si Dieu le permet.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 4, 'Pour ceux qui ont été une fois éclairés, qui ont goûté le don céleste, qui ont eu part à l\'Esprit saint,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 5, 'qui ont goûté la bonne parole de Dieu et les puissances du siècle à venir,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 6, 'il n\'est pas possible, s\'ils viennent à retomber, de les amener à une nouvelle repentance, puisqu\'ils crucifient de nouveau, pour leur part, le Fils de Dieu, et l\'exposent à l\'ignominie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 7, 'En effet, lorsqu\'une terre, abreuvée par les pluies fréquentes, produit des plantes utiles à ceux pour qui elle est cultivée, elle a part à la bénédiction de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 8, 'Mais celle qui ne porte que des épines et des chardons est considérée comme sans valeur; elle est près d\'être maudite, et l\'on finit par y mettre le feu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 9, 'Cependant, mes bien-aimés, quoique nous parlions ainsi, nous sommes persuadés, en ce qui vous concerne, que vous continuerez à suivre la voie bien meilleure qui conduit au salut.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 10, 'Dieu n\'est pas injuste pour oublier votre travail, l\'amour que vous avez montré pour son nom par les services que vous avez rendus et que vous rendez encore aux saints.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 11, 'Toutefois, nous désirons que chacun de vous montre le même zèle pour conserver une pleine espérance jusqu\'à la fin;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 12, 'en sorte que vous ne vous relâchiez point, mais que vous imitiez ceux qui, par la foi et la patience, sont devenus les héritiers des promesses.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 13, 'Lorsque Dieu fit la promesse à Abraham, ne pouvant jurer par un plus grand que Lui, il jura par lui-même,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 14, 'et il dit: «Certainement, je te bénirai abondamment, et je multiplierai beaucoup ta postérité»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 15, 'C\'est ainsi qu\'Abraham, ayant attendu avec patience, obtint ce qui lui avait été promis.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 16, 'Les hommes prêtent serment au nom d\'un plus grand qu\'eux, et le serment est une garantie qui met fin à tous leurs différends.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 17, 'De même, Dieu, voulant montrer encore mieux aux héritiers de la promesse la fermeté immuable de sa résolution, fit intervenir le serment,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 18, 'afin que, par ces deux choses immuables et dans lesquelles il est impossible que Dieu mente, nous trouvions un puissant, encouragement, dont le seul refuge a été de saisir l\'espérance qui nous était proposée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 19, 'Cette espérance, nous la gardons comme l\'ancre de notre âme, ferme et solide, qui pénètre au delà du voile, dans le sanctuaire');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 20, 'où Jésus est entré pour nous comme notre précurseur, étant devenu souverain sacrificateur pour l\'éternité, selon l\'ordre de Melchisédec.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 1, 'En effet, ce Melchisédec, roi de Salem, sacrificateur du Dieu Très-Haut, qui alla au-devant d\'Abraham, lorsqu\'il revenait de la défaite des rois, et qui le bénit;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 2, 'auquel Abraham donna la dîme de tout; qui, d\'après la signification de son nom, était, premièrement roi de justice, et qui, de plus, était, roi de Salem, c\'est-à-dire, roi de paix;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 3, 'sans père, sans mère, sans généalogie; qui n\'a ni commencement de jours, ni fin de vie, et qui est ainsi rendu semblable au Fils de Dieu, — ce Melchisédec demeure sacrificateur à perpétuité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 4, 'Considérez combien grand est celui à qui Abraham lui-même, le patriarche, donna une dîme prise sur le meilleur du butin.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 5, 'Ceux des fils de Lévi qui reçoivent la sacrificature, ont, l\'ordre, d\'après la loi, de lever la dîme sur le peuple, c\'est-à-dire sur leurs frères, qui pourtant sont issus eux-mêmes d\'Abraham.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 6, 'Mais lui, qui n\'était pas de la même famille, reçut d\'Abraham la dîme et bénit celui qui possédait les promesses.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 7, 'Or, sans contredit, c\'est l\'inférieur qui est béni par le supérieur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 8, 'De plus, ici, ce sont des hommes mortels qui prélèvent la dîme; là, c\'est celui au sujet duquel l\'Écriture atteste qu\'il est, vivant.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 9, 'Et l\'on peut dire que ce Lévi, qui prélève la dîme, l\'a payée lui-même dans la personne d\'Abraham;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 10, 'car il était encore dans les reins de son père, lorsque Melchisédec vint au-devant du patriarche.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 11, 'Si la perfection avait pu être atteinte par le sacerdoce lévitique — car la législation donnée au peuple a pour base ce sacerdoce, — qu\'était-il encore besoin qu\'il parût un autre sacrificateur, institué selon l\'ordre de Melchisédec, et non selon l\'ordre d\'Aaron?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 12, 'Le sacerdoce étant changé, il doit y avoir nécessairement, un changement de loi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 13, 'En effet, celui à qui s\'appliquent ces paroles appartient, à une autre tribu, dont aucun membre n\'a été attaché au service de l\'autel.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 14, 'Car il est notoire que notre Seigneur est issu de Juda, tribu dont, Moïse n\'a rien dit, en ce qui touche le sacerdoce.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 15, 'Tout cela devient encore plus évident, quand nous voyons s\'élever, à la ressemblance de Melchisédec, un autre sacrificateur,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 16, 'établi non d\'après la règle d\'une ordonnance charnelle, mais par la puissance d\'une vie impérissable.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 17, 'Voici, en effet, le témoignage qui lui est rendu: «Tu es sacrificateur pour l\'éternité, selon l\'ordre de Melchisédec.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 18, 'Ainsi, l\'ordonnance antérieure a été abolie à cause de son impuissance et de son inutilité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 19, 'En effet, la loi n\'a rien amené à la perfection, et à sa place a été introduite une meilleure espérance, grâce à laquelle nous nous approchons de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 20, 'De plus, ce changement ne s\'est pas accompli sans serment.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 21, 'Les autres sacrificateurs furent institués sans serment; mais lui, il l\'a été avec serment, par celui qui lui a dit: «Le Seigneur l\'a juré, et il ne s\'en repentira point: tu es sacrificateur pour l\'éternité!»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 22, 'Aussi Jésus est-il devenu le garant d\'une alliance de beaucoup supérieure à la première.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 23, 'En outre, il y a eu un grand nombre de sacrificateurs, parce que la mort les empêchait de conserver toujours leurs fonctions.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 24, 'Mais lui, parce qu\'il subsiste éternellement, possède le sacerdoce qui ne se transforme point.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 25, 'Et c\'est pour cela qu\'il peut sauver parfaitement ceux qui s\'approchent de Dieu par lui, étant toujours vivant pour intercéder en leur faveur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 26, 'C\'était bien là le souverain sacrificateur qu\'il nous fallait, saint, innocent, exempt de souillure, séparé des pécheurs, et élevé au-dessus des cieux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 27, 'Il n\'a pas besoin, comme les autres souverains sacrificateurs, d\'offrir tous les jours des sacrifices, d\'abord pour ses propres péchés, ensuite pour ceux du peuple: il a fait cela une fois pour toutes, en s\'offrant lui-même.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 28, 'Car la loi établit comme souverains sacrificateurs des hommes sujets à la faiblesse; mais la parole du serment qui a été fait après la loi, établit le Fils, qui est parvenu pour toujours à la perfection.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 1, 'Le point capital de ce que nous venons de dire, c\'est que nous avons un souverain sacrificateur, qui s\'est assis à la droite du trône de la majesté divine dans les cieux,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 2, 'comme ministre du sanctuaire et du véritable tabernacle dressé par le Seigneur, et non par un homme.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 3, 'Tout souverain sacrificateur est établi pour offrir des dons et des sacrifices; il faut donc que celui-là aussi ait quelque chose à offrir.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 4, 'S\'il était sur la terre, il ne serait pas même sacrificateur, puisqu\'il s\'y trouve des sacrificateurs chargés d\'offrir des dons prescrits par la loi');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 5, 'et de célébrer un culte, qui n\'est que l\'image et l\'ombre des choses célestes, comme Moïse en fut divinement instruit, lorsqu\'il allait dresser le tabernacle; Aie soin, lui fut-il dit, de tout exécuter suivant le modèle qui t\'a été montré sur la montagne.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 6, 'Mais notre souverain sacrificateur a obtenu un ministère d\'autant plus excellent, qu\'il est médiateur d\'une meilleure alliance, établie sur de meilleures promesses.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 7, 'Car si la première alliance avait été sans défaut, il n\'y aurait pas eu lieu d\'en établir une seconde.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 8, 'Or, il y a bien un reproche dans ces paroles que Dieu adresse aux Juifs: «Voici que les jours viennent, dit le Seigneur, où je traiterai avec la maison d\'Israël et la maison de Juda une alliance nouvelle,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 9, 'non pas une alliance comme celle que je fis avec leurs pères, au jour où je les pris par la main pour les retirer du pays d\'Egypte. Puisqu\'ils n\'ont pas persévéré dans mon alliance, moi, je les ai abandonnés, dit le Seigneur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 10, 'Voici l\'alliance que je traiterai avec la maison d\'Israël après ces jours-là, dit le Seigneur: Je mettrai mes lois dans leur esprit, et je les graverai dans leur coeur; je serai leur Dieu, et ils seront mon peuple.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 11, 'Aucun d\'eux n\'instruira son concitoyen, ni aucun son frère, en disant: Connais le Seigneur! Car tous me connaîtront, depuis le plus petit d\'entre eux jusqu\'au plus grand,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 12, 'parce que je pardonnerai leurs iniquités, et je ne me souviendrai plus de leurs péchés,»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 13, 'En appelant nouvelle cette alliance, il a déclaré ancienne la première; or, ce qui est devenu ancien, ce qui a vieilli, est près de disparaître.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 1, 'La première alliance avait aussi des règles pour le culte et un sanctuaire terrestre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 2, 'En effet, un tabernacle avait été établi: dans la première partie, appelée le lieu saint, étaient le chandelier, la table et les pains de proposition;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 3, 'puis, derrière le second voile, était la partie appelée le lieu très saint,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 4, 'où se trouvaient un encensoir d\'or et l\'arche de l\'alliance, entièrement recouverte d\'or. Dans l\'arche étaient une urne d\'or renfermant la manne, la verge d\'Aaron qui avait fleuri, et les tables de l\'alliance;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 5, 'au-dessus, les chérubins glorieux, couvrant de leur ombre le propitiatoire. Mais ce n\'est pas le moment de parler de tout cela en détail.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 6, 'Les choses étant ainsi disposées, les sacrificateurs entrent tous les jours dans la première partie du tabernacle, pour y faire le service;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 7, 'mais, dans la seconde, le souverain sacrificateur, seul, entre une fois par an, et non sans y porter du sang, qu\'il offre pour lui-même et pour les péchés du peuple.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 8, 'Le Saint-Esprit fait voir par là que le chemin du lieu très saint n\'était pas ouvert, tant que subsistait la première partie du tabernacle.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 9, 'C\'était un symbole en vue du temps présent, pour montrer que les dons et les sacrifices offerts sont incapables de rendre parfait, au regard de la conscience, celui qui célèbre un tel culte.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 10, 'Il ne s\'agit là que de prescriptions charnelles, concernant la nourriture, la boisson, les ablutions diverses, et qui n\'ont été imposées que jusqu\'à une époque de réforme.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 11, 'Mais Christ est apparu, comme souverain sacrificateur des biens à venir; il a traversé le tabernacle plus grand et plus parfait, qui n\'a pas été construit de main d\'homme, c\'est-à-dire qui n\'appartient pas à cette création;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 12, 'et, après nous avoir acquis une rédemption éternelle, il est entré une fois pour toutes dans le lieu très saint, en offrant non pas le sang des boucs et des veaux, mais son propre sang.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 13, 'En effet, si le sang des boucs et des taureaux et la cendre d\'une génisse, dont on asperge ceux qui sont souillés, les sanctifient, en leur procurant du moins la pureté de la chair,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 14, 'combien plus le sang du Christ qui, par l\'Esprit éternel, s\'est offert lui-même sans tache à Dieu, purifiera-t-il votre conscience des oeuvres mortes, pour que vous serviez le Dieu vivant!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 15, 'Voilà pourquoi il est le médiateur d\'un testament nouveau, afin que, sa mort étant intervenue pour racheter les transgressions commises sous le premier testament, ceux qui sont appelés reçoivent l\'héritage éternel qui leur a été promis.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 16, 'Car où il y a testament, il est nécessaire que la mort du testateur soit constatée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 17, 'Un testament n\'est valable qu\'après la mort, puisqu\'il n\'a point d\'effet tant que le testateur est en vie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 18, 'C\'est ainsi que la première alliance elle-même n\'a pas été inaugurée sans effusion de sang.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 19, 'Lorsque Moïse eut exposé à tout le peuple tous les commandements de la loi, il prit le sang des veaux et des boucs, avec de l\'eau, de la laine écarlate et de l\'hysope, et il en aspergea le livre lui-même et tout le peuple,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 20, 'en disant: «Ceci est le sang de l\'alliance que Dieu a commandé de conclure avec nous.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 21, 'Puis, il aspergea également avec ce sang le tabernacle et tous les ustensiles du culte.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 22, 'Et en général, selon la loi, tout est purifié avec du sang: sans effusion de sang, il n\'y a pas de pardon.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 23, 'Si donc les images des choses du ciel ont dû être purifiées de cette manière, les choses célestes elles-mêmes devaient l\'être par des sacrifices plus précieux encore.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 24, 'En effet, Christ n\'est pas entré dans un sanctuaire fait de main d\'homme, imitation du vrai sanctuaire; mais il est entré dans le ciel même, afin de comparaître maintenant pour nous devant la face de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 25, 'Et ce n\'est pas pour s\'offrir plusieurs fois lui-même, comme le souverain sacrificateur qui entre dans le lieu très saint, chaque année, avec un autre sang que le sien;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 26, 'autrement, il aurait fallu qu\'il souffrît plusieurs fois depuis le commencement du monde. Mais il a paru une seule fois, à la fin des âges, pour abolir le péché par son sacrifice.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 27, 'Et de même qu\'il est réservé aux hommes de mourir une fois, après quoi vient le jugement,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 28, 'de même le Christ s\'est offert une seule fois pour ôter les péchés de plusieurs; et il apparaîtra une seconde fois, non plus pour ôter le péché, mais pour donner le salut à ceux qui l\'attendent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 1, 'En effet, la loi, n\'ayant que l\'ombre des biens à venir, et non la forme réelle des choses, ne peut jamais, par les mêmes sacrifices qu\'on offre chaque année à perpétuité, amener à la perfection ceux qui s\'approchent ainsi de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 2, 'Autrement, n\'aurait-on pas cessé de les offrir, puisque ceux qui rendent ce culte, une fois purifiés, n\'auraient plus eu leur conscience chargée de péchés?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 3, 'Au contraire, le souvenir des péchés est renouvelé chaque année par ces sacrifices.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 4, 'Car il est impossible que le sang des taureaux et des boucs ôte les péchés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 5, 'C\'est pourquoi le Christ, entrant dans le monde, dit: «Tu n\'as voulu ni sacrifice, ni offrande, mais tu m\'as formé un corps.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 6, 'Tu n\'as agréé ni les holocaustes, ni les offrandes pour le péché.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 7, 'Alors j\'ai dit: Je viens — il est parlé de moi dans le Livre — oui, je viens, ô Dieu, pour faire ta volonté.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 8, 'Après avoir dit d\'abord: «Tu n\'as voulu, tu n\'as agréé ni sacrifices, ni offrandes, ni holocaustes, ni oblations pour le péché», — ce qui pourtant est prescrit par la loi, —');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 9, 'il ajoute: «Me voici: Je viens pour faire ta volonté.» Il abolit ainsi le premier ordre de sacrifices pour établir le second.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 10, 'C\'est en vertu de cette volonté que nous avons été sanctifiés, par le sacrifice que Jésus-Christ a fait, une fois pour toutes, de son propre corps.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 11, 'De plus, tandis que tout sacrificateur se présente, chaque jour, pour faire le service et offrir plusieurs fois les mêmes sacrifices qui ne peuvent jamais ôter les péchés,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 12, 'celui-ci, après avoir offert un seul sacrifice pour les péchés, s\'est assis pour toujours à la droite de Dieu,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 13, 'attendant désormais que ses ennemis soient mis sous ses pieds, pour lui servir de marchepied.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 14, 'En effet, par une seule oblation, il a amené pour toujours à la perfection ceux qui sont sanctifiés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 15, 'Et c\'est aussi ce que nous atteste le Saint-Esprit; car, après avoir dit:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 16, '«Voici l\'alliance que je traiterai avec eux après ces jours-là, dit le Seigneur: Je mettrai mes lois dans leurs coeurs, et je les graverai dans leur esprit», — il ajoute:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 17, '«Et je ne me souviendrai plus de leurs péchés ni de leurs iniquités.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 18, 'Or, là où il y a pardon, il n\'est plus besoin d\'oblation pour le péché.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 19, 'Ainsi donc, frères, puisque nous avons un libre accès dans le lieu très saint, grâce au sang de Jésus,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 20, 'par le chemin nouveau et vivant qu\'il nous a frayé à travers le voile, c\'est-à-dire à travers sa propre chair,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 21, 'et puisque nous avons un grand sacrificateur établi sur la maison de Dieu,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 22, 'approchons-nous avec un coeur sincère, avec une foi pleine et entière, le coeur purifié des souillures d\'une mauvaise conscience, et le corps lavé d\'une eau pure.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 23, 'Retenons fermement la profession de notre espérance, car Celui qui a fait les promesses est fidèle.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 24, 'Veillons les uns sur les autres pour nous exciter à la charité et aux bonnes oeuvres,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 25, 'et n\'abandonnons pas nos assemblées, comme quelques-uns ont coutume de faire, mais exhortons-nous les uns les autres, et cela d\'autant plus que vous voyez approcher le grand jour.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 26, 'En effet, si nous péchons volontairement, après avoir reçu la connaissance de la vérité, il ne reste plus de sacrifice pour les péchés,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 27, 'mais seulement la terrible attente du jugement et le feu ardent, qui doit dévorer les rebelles.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 28, 'Celui qui a violé la loi de Moïse, meurt sans miséricorde, sur la déposition de deux ou trois témoins.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 29, 'Ne pensez-vous pas qu\'il sera jugé digne d\'un châtiment bien plus sévère, celui qui aura foulé aux pieds le Fils de Dieu, qui aura tenu pour vil le sang de l\'alliance par lequel il a été sanctifié, et qui aura outragé l\'Esprit de la grâce?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 30, 'Car nous connaissons celui qui a dit: «C\'est à moi qu\'appartient la vengeance; c\'est moi qui rétribuerai», — dit le Seigneur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 31, 'Et ailleurs: «Le Seigneur jugera son peuple.» C\'est une chose terrible que de tomber entre les mains du Dieu vivant!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 32, 'Rappelez-vous ces premiers temps, où, après avoir été éclairés, vous avez soutenu un grand combat de souffrances:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 33, 'd\'un côté, vous avez été exposés comme en spectacle aux opprobres et aux afflictions, de l\'autre, vous avez pris part aux maux de ceux qui subissaient les mêmes traitements.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 34, 'Car vous avez eu compassion des prisonniers, et vous avez accepté avec joie qu\'on vous ravît vos biens, sachant que vous en avez de meilleurs et qui durent toujours.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 35, 'N\'abandonnez donc pas votre confiance, à laquelle une grande récompense est réservée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 36, 'Car vous avez besoin de persévérance, afin qu\'après avoir fait la volonté de Dieu, vous obteniez ce qui vous a été promis.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 37, 'Encore un peu, bien peu de temps, et celui qui doit venir, viendra; il ne tardera point.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 38, '«Et mon juste vivra par la foi; mais s\'il se retire, mon âme ne prend point plaisir en lui.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 39, 'Pour nous, nous ne sommes pas de ceux qui se retirent pour leur perte, mais de ceux qui gardent la foi pour sauver leur âme.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 1, 'Or, la foi est une ferme assurance des choses qu\'on espère, une démonstration de celles qu\'on ne voit pas.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 2, 'C\'est grâce à elle que les anciens ont obtenu un bon témoignage.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 3, 'C\'est par la foi que nous savons que le monde, a été formé par la parole de Dieu; en sorte que les choses qui se voient ne proviennent pas de choses visibles.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 4, 'C\'est par la foi qu\'Abel offrit à Dieu un sacrifice meilleur que celui de Caïn. Par elle, il fut déclaré juste. Dieu ayant attesté qu\'il agréait ses offrandes; et par elle, quoique mort, il parle encore.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 5, 'C\'est par la foi qu\'Hénoc fut enlevé et qu\'il ne vit point la mort; on ne le trouva plus, parce que Dieu l\'avait enlevé; car, avant son enlèvement, il avait obtenu le témoignage d\'être agréable à Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 6, 'Or, sans la foi, il est impossible de lui être agréable; car il faut que celui qui s\'approche de Dieu, croie que Dieu existe et qu\'il est le rémunérateur de ceux qui le cherchent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 7, 'C\'est par la foi que Noé, divinement averti des choses qu\'on ne voyait pas encore et pénétré d\'une pieuse crainte, bâtit l\'arche pour sauver sa famille; par elle, il condamna le monde, et il devint héritier de la justice qui vient de la foi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 8, 'C\'est par la foi qu\'Abraham obéit à l\'appel de Dieu et partit pour le pays qu\'il devait recevoir en héritage: il partit, sans savoir où il allait.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 9, 'C\'est par la foi qu\'il séjourna dans la terre qui lui avait été promise comme dans une terre étrangère, habitant sous des tentes, ainsi qu\'Isaac et Jacob, héritiers avec lui de la même promesse.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 10, 'Car il attendait la cité qui a de solides fondements, et dont Dieu est l\'architecte et le fondateur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 11, 'C\'est aussi par la foi que Sara fut rendue capable, malgré son âge, d\'avoir une postérité, parce qu\'elle crut que Celui qui lui en avait fait la promesse était fidèle.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 12, 'C\'est aussi pour cela qu\'il est né d\'un seul homme, et d\'un homme usé par l\'âge, une multitude aussi nombreuse que les étoiles du ciel, ou que les grains de sable qui sont au bord de la mer et qu\'on ne peut compter.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 13, 'Tous ceux-là sont morts dans la foi, sans avoir reçu les choses qui leur avaient été promises; ils les ont seulement vues et saluées de loin, ayant fait profession d\'être étrangers et voyageurs sur la terre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 14, 'Ceux qui parlent ainsi montrent bien qu\'ils cherchent une patrie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 15, 'S\'ils avaient songé à celle d\'où ils étaient sortis, ils auraient eu le temps d\'y retourner,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 16, 'mais ils désiraient une patrie meilleure, la patrie céleste; aussi Dieu n\'a-t-il pas honte de s\'appeler leur Dieu, car il leur a préparé une cité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 17, 'C\'est par la foi qu\'Abraham, mis à l\'épreuve, offrit Isaac. Oui, il offrit son fils unique, lui qui avait reçu les promesses');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 18, 'et auquel il avait été dit: «C\'est en Isaac que tu auras une postérité appelée de ton nom.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 19, 'Il se disait que Dieu a le pouvoir même de ressusciter un mort; aussi le recouvra-t-il par une sorte de résurrection.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 20, 'C\'est par la foi qu\'Isaac donna à Jacob et à Ésaü une bénédiction qui avait en vue l\'avenir.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 21, 'C\'est par la foi que Jacob mourant bénit chacun des fils de Joseph et adora, appuyé sur le haut de son bâton.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 22, 'C\'est par la foi que Joseph, près de sa fm, fit mention de la sortie des enfants d\'Israël et donna des ordres au sujet de sa dépouille mortelle.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 23, 'C\'est par la foi que Moïse, à sa naissance, fut caché trois mois par ses parents, parce qu\'ils voyaient que c\'était un bel enfant; et ils ne se laissèrent pas effrayer par l\'édit du roi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 24, 'C\'est par la foi que Moïse, devenu grand, renonça au titre de fils de la fille de Pharaon,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 25, 'aimant mieux être maltraité avec le peuple de Dieu, que de jouir, pour un peu de temps, des délices du péché:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 26, 'il considérait l\'opprobre du Christ comme une richesse plus grande que les trésors de l\'Egypte, parce qu\'il regardait à la rémunération.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 27, 'C\'est par la foi qu\'il quitta l\'Egypte, sans craindre la colère du roi; car il tint ferme, comme s\'il eût vu celui qui est invisible.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 28, 'C\'est par la foi qu\'il célébra la Pâque et fit l\'aspersion du sang, afin que l\'exterminateur ne touchât point aux premiers-nés des Israélites.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 29, 'C\'est par la foi qu\'ils traversèrent la mer Rouge, comme une terre sèche, tandis que les Égyptiens, qui tentèrent le passage, y furent engloutis.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 30, 'C\'est par la foi que les murailles de Jéricho tombèrent, après qu\'on en eut fait le tour pendant sept jours.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 31, 'C\'est par la foi que Rahab, la femme de mauvaise vie, ne périt pas avec les incrédules, parce qu\'elle avait reçu les espions avec bienveillance.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 32, 'Et que dirai-je encore? Car le temps me manquerait, si je voulais parler de Gédéon, de Barac, de Samson, de Jephté, de David, de Samuel et des prophètes,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 33, 'qui, par la foi, ont conquis des royaumes, exercé la justice, obtenu des promesses, fermé la gueule des lions,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 34, 'éteint l\'ardeur du feu, échappé au tranchant de l\'épée, triomphé de la maladie, montré leur vaillance à la guerre, mis en fuite des armées ennemies.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 35, 'Des femmes ont recouvré leurs morts par la résurrection. D\'autres ont été cruellement tourmentés, refusant la délivrance, afin d\'obtenir une résurrection meilleure;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 36, 'd\'autres encore ont eu à subir les moqueries et le fouet, et même les fers et la prison.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 37, 'Ils ont été lapidés, torturés, sciés; ils ont été tués par le tranchant de l\'épée. Ils ont erré çà et là, vêtus de peaux de brebis et de peaux de chèvres, dénués de tout, opprimés, maltraités,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 38, 'eux dont le monde n\'était pas digne; ils ont erré dans les déserts, les montagnes, les cavernes, les antres de la terre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 39, 'Et tous ceux-là, bien qu\'ayant obtenu un bon témoignage, à cause de leur foi, n\'ont point reçu ce qui leur avait été promis.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 40, 'En effet, Dieu avait en vue pour nous quelque chose de meilleur, car il ne voulait pas qu\'ils parvinssent à la perfection sans nous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 1, 'Nous donc aussi, puisque nous sommes environnés d\'une si grande nuée de témoins, rejetant tout fardeau et le péché qui nous enveloppe si facilement, courons avec persévérance dans la carrière qui nous est ouverte,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 2, 'regardant à Jésus, le chef et le consommateur de la foi, lui qui, en vue de la joie qui lui était offerte, a souffert la croix, méprisant l\'ignominie, et s\'est assis à la droite du trône de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 3, 'Considérez donc celui qui a supporté une si grande opposition de la part des pécheurs, afin que vous ne vous laissiez pas abattre en perdant courage.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 4, 'Vous n\'avez pas encore résisté jusqu\'au sang, en combattant contre le péché;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 5, 'et vous avez oublié l\'exhortation qui vous est adressée, comme à des fils: «Mon Fils, ne méprise pas le châtiment du Seigneur, et ne perds pas courage, lorsqu\'il te reprend;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 6, 'car le Seigneur châtie celui qu\'il aime, et il frappe de ses verges tous ceux qu\'il reconnaît pour ses enfants»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 7, 'Si vous avez à endurer le châtiment, Dieu vous traite comme des fils; car quel est le fils que son père ne châtie pas?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 8, 'Mais si vous êtes exempts du châtiment auquel tous ont part, alors vous êtes des enfants illégitimes; vous n\'êtes pas de vrais fils.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 9, 'Et puisque nos pères selon la chair nous ont châtiés, et que, néanmoins, nous avons eu du respect pour eux, ne serons-nous pas, à bien plus forte raison, soumis au Père des esprits, pour avoir la vie?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 10, 'Ceux-là, en effet, nous châtiaient pour un peu de temps, comme ils le trouvaient bon; mais Dieu nous châtie pour notre bien, afin de nous rendre participants de sa sainteté.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 11, 'Il est vrai que tout châtiment semble, au premier abord, un sujet de tristesse, et non pas de joie; mais ensuite il produit un fruit de justice et de paix pour ceux qui ont été ainsi exercés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 12, 'Relevez donc vos mains défaillantes, et vos genoux qui fléchissent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 13, 'Dirigez vos pas dans le droit chemin, afin que le pied qui est boiteux, au lieu de se démettre entièrement, soit guéri.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 14, 'Recherchez la paix avec tous, et la sanctification, sans laquelle nul ne verra le Seigneur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 15, 'Veillez à ce que personne ne se prive de la grâce de Dieu, à ce qu\'il ne vienne pas à pousser quelque racine d\'amertume qui pourrait entraver et infecter la plupart d\'entre vous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 16, 'Veillez à ce qu\'il n\'y ait parmi vous aucun impur, ni aucun profane comme Ésaü, qui, uniquement pour un plat, vendit son droit d\'aînesse.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 17, 'Vous savez, en effet, que plus tard, voulant obtenir la bénédiction paternelle, il fut repoussé; car, bien qu\'il l\'eût demandée avec larmes, il ne put faire changer son père de résolution.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 18, 'Vous ne vous êtes pas approchés d\'une montagne qu\'on pût toucher, ni du feu ardent, ni de l\'obscurité, ni des ténèbres, ni de la tempête,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 19, 'ni de l\'éclat de la trompette, ni de la voix qui parlait, voix si redoutable, que ceux qui l\'entendirent demandèrent instamment que la parole ne leur fût plus adressée;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 20, 'car ils ne pouvaient supporter cette menace: «Même l\'animal qui aura touché cette montagne sera lapidé.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 21, 'Et le spectacle était si terrible, que Moïse dit: «Je suis épouvanté et tout tremblant.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 22, 'Mais vous vous êtes approchés de la montagne de Sion, de la cité du Dieu vivant, la Jérusalem céleste, des myriades qui forment l\'assemblée des anges,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 23, 'de l\'Église des premiers-nés inscrits dans les cieux, de Dieu, le juge de tous, des esprits des justes parvenus à la perfection,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 24, 'de Jésus, le médiateur de la nouvelle alliance, et du sang de l\'aspersion, qui proclame de meilleures choses que celui d\'Abel.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 25, 'Gardez-vous de repousser Celui qui vous parle; car si ceux-là n\'ont pas échappé au châtiment, pour avoir repoussé Celui qui se révélait sur la terre, à plus forte raison n\'échapperons-nous pas, si nous le repoussons quand il parle du haut des cieux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 26, 'Lui dont la voix ébranla alors la terre, et qui maintenant fait cette déclaration: «J\'ébranlerai encore une fois non seulement la terre, mais aussi le ciel.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 27, 'Or, ces mots: «encore une fois» indiquent la transformation des choses qui, par cela même qu\'elles ont été créées, seront un jour ébranlées, afin que subsiste ce qui est inébranlable.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 28, 'Ainsi, puisque nous avons en partage un royaume inébranlable, gardons fidèlement la grâce afin de servir Dieu d\'une manière qui lui soit agréable, avec respect et avec crainte;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 29, 'car notre Dieu est aussi un feu consumant.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 1, 'Que l\'amour fraternel règne parmi vous. N\'oubliez pas l\'hospitalité;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 2, 'c\'est en la pratiquant que quelques-uns ont logé des anges sans le savoir.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 3, 'Souvenez-vous de ceux qui sont en prison, comme si vous étiez prisonniers avec eux, et de ceux qui sont maltraités, puisque vous avez un corps semblable au leur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 4, 'Que le mariage soit respecté par tous, et le lit conjugal sans souillure; car Dieu jugera les impurs et les adultères.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 5, 'Que votre conduite ne soit pas inspirée par l\'amour de l\'argent; contentez-vous de ce que vous avez, car Dieu lui-même a dit: «Je ne te délaisserai pas; je ne t\'abandonnerai point.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 6, 'Aussi pouvons-nous dire avec confiance: «Le Seigneur vient à mon aide; je ne craindrai rien. Que pourrait me faire l\'homme?»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 7, 'Souvenez-vous de vos conducteurs, qui vous ont annoncé la parole de Dieu; considérez quelle a été la fin de leur vie, et imitez leur foi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 8, 'Jésus-Christ est le même, hier, aujourd\'hui, éternellement!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 9, 'Ne vous laissez pas entraîner par toutes sortes de doctrines étrangères; car il est bon que le coeur soit affermi par la grâce, et non par l\'usage d\'aliments qui ne servent de rien à ceux qui observent de telles pratiques.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 10, 'Nous avons un autel, dont ceux qui célèbrent le culte dans le tabernacle n\'ont pas le droit de se nourrir.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 11, 'En effet, les corps des animaux, dont le sang est porté par le souverain sacrificateur dans le sanctuaire pour l\'expiation du péché, sont brûlés hors du camp.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 12, 'C\'est pour cela que Jésus lui-même, afin de sanctifier le peuple par son propre sang, a souffert hors des portes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 13, 'Ainsi, sortons hors du camp, pour aller à lui, en portant son opprobre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 14, 'En effet, nous n\'avons point ici-bas de cité permanente, mais nous cherchons celle qui est à venir.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 15, 'Offrons donc sans cesse à Dieu par lui un sacrifice de louanges, c\'est-à-dire l\'hommage de lèvres qui confessent son nom.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 16, 'N\'oubliez pas non plus la bienfaisance et la libéralité, car c\'est à de tels sacrifices que Dieu prend plaisir.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 17, 'Obéissez à vos conducteurs et soyez-leur soumis, — car ils veillent au salut de vos âmes, dont ils auront à rendre compte, — afin qu\'ils s\'acquittent de leur ministère avec joie, et non en gémissant, ce qui ne serait pas à votre avantage.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 18, 'Priez pour nous, car nous sommes assurés d\'avoir une bonne conscience, étant résolus à nous bien conduire en toutes choses.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 19, 'Je vous demande instamment de le faire, afin que je vous sois plus tôt rendu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 20, 'Que le Dieu de paix, — qui a ramené du milieu des morts notre Seigneur Jésus, devenu, par le sang d\'une alliance éternelle, le grand Pasteur des brebis, —');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 21, 'vous rende capables de toute bonne oeuvre, pour l\'accomplissement de sa volonté, opérant en vous ce qui lui est agréable, par Jésus-Christ, auquel soit la gloire, aux siècles des siècles! Amen.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 22, 'Frères, je vous prie de faire bon accueil à ces paroles d\'exhortation; c\'est en peu de mots que je vous ai écrit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 23, 'Sachez que notre frère Timothée a été mis en liberté; s\'il vient bientôt, j\'irai vous voir avec lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 24, 'Saluez tous vos conducteurs et tous les saints. Ceux d\'Italie vous saluent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 25, 'Que la grâce soit avec vous tous!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 1, 'Jacques, serviteur de Dieu et du Seigneur Jésus-Christ, aux douze tribus qui sont dispersées, salut!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 2, 'Mes frères, considérez comme le sujet d\'une parfaite joie les épreuves diverses qui vous surviennent,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 3, 'sachant que l\'épreuve, à laquelle est soumise votre foi, produit la patience.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 4, 'Mais il faut que la patience ait accompli parfaitement son oeuvre, pour que vous soyez vous-mêmes parfaits et accomplis, et qu\'il ne vous manque rien.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 5, 'Si l\'un de vous manque de sagesse, qu\'il la demande à Dieu, qui donne à tous libéralement, sans rien reprocher; et elle lui sera donnée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 6, 'Mais qu\'il demande avec foi, sans douter; car celui qui doute est semblable au flot de la mer, qui est agité et poussé ça et là par le vent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 7, 'Que cet homme-là ne s\'attende point à recevoir quelque chose de la part du Seigneur:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 8, 'c\'est un homme au coeur partagé, inconstant dans toute sa conduite.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 9, 'Que le frère qui est de condition humble se glorifie de son élévation,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 10, 'et que le riche se glorifie de son humiliation, car il passera comme la fleur de l\'herbe.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 11, 'Le soleil s\'est levé avec sa brûlante chaleur; l\'herbe a séché, sa fleur est tombée, et l\'éclat de sa beauté a péri: ainsi se flétrira le riche, au milieu même de ses entreprises.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 12, 'Heureux l\'homme qui endure la tentation; car, après qu\'il aura été mis à l\'épreuve, il recevra la couronne de vie que Dieu a promise à ceux qui l\'aiment.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 13, 'Que personne, lorsqu\'il est tenté, ne dise: C\'est Dieu qui me tente; car Dieu ne peut être tenté par aucun mal, et lui-même ne tente personne.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 14, 'Mais chacun est tenté, quand il est attiré et amorcé par sa propre convoitise.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 15, 'Puis la convoitise, ayant conçu, donne naissance au péché; et le péché, lorsqu\'il est consommé, enfante la mort.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 16, 'Mes frères bien-aimés, ne vous y trompez pas:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 17, 'toute grâce excellente et tout don parfait viennent d\'en haut et descendent du Père des lumières, en qui il n\'y a aucune variation ni aucune ombre de changement.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 18, 'C\'est lui qui, de sa libre volonté, nous a engendrés par la parole de vérité, afin que nous soyons comme les prémices de ses créatures.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 19, 'Vous le savez, mes frères bien-aimés, il faut que tout homme soit prompt à écouter, lent à parler, lent à se mettre en colère;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 20, 'car la colère de l\'homme n\'accomplit pas la justice de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 21, 'Rejetez donc toute souillure et tout reste de méchanceté, et recevez avec douceur la parole qui a été plantée en vous, et qui peut sauver vos âmes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 22, 'Mettez en pratique la parole, et ne vous contentez pas de l\'écouter, en vous abusant vous-mêmes par de faux raisonnements.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 23, 'En effet, si quelqu\'un écoute la parole et ne la met pas en pratique, il est semblable à un homme qui regarde dans un miroir son visage naturel,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 24, 'et qui, après s\'être regardé, s\'en va et oublie aussitôt comment il est.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 25, 'Mais celui qui aura plongé ses regards dans la loi parfaite, la loi de la liberté, et qui l\'aura contemplée avec persévérance, n\'étant pas un auditeur oublieux, mais un fidèle observateur de ses préceptes, celui-là trouvera son bonheur dans son obéissance.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 26, 'Si un homme, qui se croit religieux, ne tient pas sa langue en bride et se trompe ainsi lui-même, la religion d\'un tel homme est vaine.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 27, 'La religion pure et sans tache devant Dieu, notre Père, consiste à visiter les orphelins et les veuves dans leurs afflictions, et à se préserver des souillures du monde.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 1, 'Mes frères, que votre foi en Jésus-Christ, notre glorieux Seigneur, soit exempte de toute acception de personnes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 2, 'Supposez qu\'il entre dans votre assemblée un homme portant un anneau d\'or et des habits magnifiques, et qu\'il y entre aussi un pauvre misérablement vêtu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 3, 'Si, tournant vos regards vers celui qui porte les habits magnifiques, vous lui dites: Toi, assieds-toi ici, à cette bonne place; et que vous disiez au pauvre: Toi, tiens-toi là debout, ou assieds-toi au-dessous de mon marchepied, —');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 4, 'n\'établissez-vous pas en vous-mêmes des distinctions, et vos jugements ne sont-ils pas inspirés par de mauvaises pensées?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 5, 'Écoutez, mes frères bien-aimés: Dieu n\'a-t-il pas choisi les pauvres selon le monde pour les rendre riches en la foi et héritiers du royaume qu\'il a promis à ceux qui l\'aiment?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 6, 'Et vous, vous avez méprisé le pauvre, alors que ce sont les riches qui vous oppriment et qui vous traînent devant les tribunaux;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 7, 'et ce sont eux aussi qui blasphèment le beau nom qui a été invoqué sur vous!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 8, 'Sans doute, si vous accomplissez la loi royale, selon l\'Écriture: «Tu aimeras ton prochain comme toi-même»— vous agissez bien.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 9, 'Mais si vous faites acception de personnes, vous commettez un péché, et la loi vous condamne comme transgresseurs.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 10, 'Car celui qui observe la loi tout entière, mais qui en viole un seul commandement, est coupable comme s\'il les avait tous violés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 11, 'En effet, celui qui a dit: «Tu ne commettras point d\'adultère» a dit aussi: «Tu ne tueras point.» Si donc tu ne commets pas d\'adultère, mais que tu commettes un meurtre, tu es transgresseur de la loi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 12, 'Parlez et agissez comme devant être jugés par une loi de liberté.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 13, 'Le jugement est sans miséricorde pour celui qui n\'a pas fait miséricorde; mais la miséricorde triomphe du jugement.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 14, 'Mes frères, que sert-il à un homme de dire qu\'il a la foi, s\'il n\'a pas les oeuvres? Cette foi peut-elle le sauver?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 15, 'Si un frère ou une soeur sont dans le dénuement, s\'ils manquent de la nourriture de chaque jour,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 16, 'et que l\'un de nous leur dise: Allez en paix, chauffez-vous, rassasiez-vous. — et cela, sans leur donner ce qui est nécessaire pour la vie du corps, — à quoi cela sert-il?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 17, 'Il en est de même de la foi: si elle ne produit pas d\'oeuvres, elle est morte en elle-même.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 18, 'Ou bien encore, quelqu\'un dira; Tu as la foi, et moi, j\'ai les oeuvres. Montre-moi ta foi sans les oeuvres, et moi, je te montrerai ma foi par mes oeuvres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 19, 'Tu crois qu\'il y a un seul Dieu, tu fais bien; les démons le croient aussi, et ils tremblent!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 20, 'Mais veux-tu te convaincre, ô homme vain, que la foi sans les oeuvres est inutile?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 21, 'Abraham, notre père, ne fut-il pas justifié par les oeuvres, lorsqu\'il lui offrit sur l\'autel son fils Isaac?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 22, 'Tu vois que la foi agissait avec ses oeuvres, et que par ses oeuvres sa foi fut rendue parfaite.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 23, 'Ainsi s\'accomplit ce que dit l\'Écriture: «Abraham crut à Dieu, et cela lui fut imputé à justice»; et il fut appelé ami de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 24, 'Vous voyez que l\'homme est justifié par les oeuvres, et non par la foi seulement.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 25, 'De même aussi, Rahab, la femme de mauvaise vie, ne fut-elle pas justifiée par les oeuvres, pour avoir reçu les messagers et les avoir fait partir par un autre chemin?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 26, 'En effet, comme le corps sans âme est mort, ainsi la foi sans les oeuvres est morte.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 1, 'Mes frères, n\'ayez parmi vous qu\'un petit nombre de gens qui s\'érigent en docteurs; car vous savez qu\'on s\'expose ainsi à un jugement plus sévère.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 2, 'Nous bronchons tous de bien des manières. Si quelqu\'un ne bronche pas dans ses paroles, c\'est un homme parfait, capable de tenir tout son corps en bride.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 3, 'Nous mettons un mors dans la bouche des chevaux pour nous en faire obéir, et ainsi nous dirigeons tout leur corps.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 4, 'Voyez aussi les navires: quelque grands qu\'ils soient, et bien que poussés par des vents violents, ils sont dirigés par un très petit gouvernail, suivant la volonté de celui qui les gouverne.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 5, 'De même, la langue est un petit membre; mais de quelles grandes choses elle peut se vanter! Voyez quelle grande forêt un petit feu peut embraser.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 6, 'La langue aussi est un feu; c\'est le monde de l\'iniquité. La langue, placée comme elle l\'est parmi nos membres, souille tout le corps et enflamme tout le cours de la vie, étant elle-même enflammée du feu de la Géhenne.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 7, 'Toutes les espèces de bêtes sauvages, d\'oiseaux, de reptiles et d\'animaux marins peuvent être et ont été domptés par l\'espèce humaine.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 8, 'Mais la langue, aucun homme ne peut la dompter; c est un mal qu\'on ne peut réprimer: elle est pleine d\'un venin mortel.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 9, 'Par elle nous bénissons le Seigneur, notre Père, et par elle nous maudissons les hommes, faits à l\'image de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 10, 'De la même bouche sortent la bénédiction et la malédiction! Il ne faut pas, mes frères, qu\'il en soit ainsi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 11, 'Est-ce qu\'une fontaine jette par la même ouverture de l\'eau douce et de l\'eau amère?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 12, 'Mes frères, un figuier peut-il donner des olives, ou une vigne des figues? Une source d\'eau salée ne peut pas non plus donner de l\'eau douce.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 13, 'Y a-t-il parmi vous quelque homme sage et intelligent? Qu\'il montre, par sa bonne conduite, qu\'une sagesse pleine de douceur inspire ses oeuvres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 14, 'Mais si vous avez dans votre coeur un zèle amer et un esprit de dispute, ne vous glorifiez pas et ne mentez pas contre la vérité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 15, 'Cette sagesse-là n\'est point celle qui vient d\'en haut; au contraire, elle est terrestre, charnelle, diabolique.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 16, 'Car partout où il y a ce zèle et cet esprit de dispute, il y a du désordre et toute espèce de mal.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 17, 'Mais la sagesse qui vient d\'en haut est premièrement pure, ensuite pacifique, modérée, conciliante, pleine de miséricorde et de bons fruits, exempte de duplicité et d\'hypocrisie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 18, 'Or, le fruit de la justice se sème dans la paix, pour ceux qui procurent la paix.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 1, 'D\'où viennent les luttes et d\'où viennent les querelles parmi vous? N\'est-ce pas de vos passions, qui combattent dans vos membres?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 2, 'Vous convoitez, et vous n\'obtenez pas; vous êtes meurtriers et jaloux; vous ne pouvez parvenir à rien; vous avez des querelles et des luttes; vous n\'obtenez pas, parce que vous ne demandez pas.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 3, 'Vous demandez et vous ne recevez pas, parce que vous demandez mal, pour tout dépenser dans vos plaisirs.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 4, 'Ames adultères, ne savez-vous pas que l\'amour du monde est inimitié contre Dieu? Ainsi, celui qui veut être l\'ami du monde devient l\'ennemi de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 5, 'Ou bien, pensez-vous que l\'Écriture parle en vain? L\'Esprit que Dieu a fait habiter en nous, nous réclame avec jalousie;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 6, 'mais il nous accorde une grâce plus grande encore. C\'est pourquoi l\'Écriture dit: «Dieu résiste aux orgueilleux, mais il fait grâce aux humbles.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 7, 'Soumettez-vous donc à Dieu; résistez au Diable, et il fuira loin de vous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 8, 'Approchez-vous de Dieu, et il s\'approchera de vous. Pécheurs, nettoyez vos mains, et vous dont l\'âme est partagée, purifiez vos coeurs!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 9, 'Sentez votre misère; soyez dans le deuil, et pleurez! Que votre rire se change en deuil, et votre joie en tristesse!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 10, 'Humiliez-vous devant le Seigneur, et il vous élèvera.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 11, 'Mes frères, ne médisez pas les uns des autres. Celui qui médit de son frère ou qui juge son frère, médit de la loi et juge la loi. Or, si tu juges la loi, tu n\'es pas observateur de la loi, tu t\'en rends le juge.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 12, 'Un seul est législateur et juge, Celui qui peut sauver et qui peut perdre. Mais qui es-tu, toi qui juges ton prochain?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 13, 'A vous maintenant, qui dites: Nous irons aujourd\'hui ou demain dans telle ville, nous y passerons une année, nous ferons des affaires et nous gagnerons de l\'argent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 14, '— vous qui ne savez pas ce que sera demain! En effet, qu\'est-ce que votre vie? Vous n\'êtes qu\'une vapeur, qui paraît un instant et qui s\'évanouit ensuite.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 15, 'Vous devriez dire, au contraire: Si le Seigneur le veut, nous serons en vie, et nous ferons telle ou telle chose.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 16, 'Mais voici maintenant que votre orgueil éclate dans vos paroles présomptueuses! Or, toute vanterie de ce genre est mauvaise.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 17, 'Ainsi donc, celui qui sait faire le bien et qui ne le fait pas, commet un péché.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 1, 'A vous maintenant, riches! Pleurez, jetez des cris à cause des malheurs qui vont tomber sur vous!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 2, 'Vos richesses sont pourries, et vos vêtements sont mangés par les vers.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 3, 'Votre or et votre argent sont rouillés, et leur rouille s\'élèvera en témoignage contre vous; et, comme un feu, elle dévorera votre chair. Vous avez amassé vos trésors dans les derniers jours!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 4, 'Il crie contre vous, le salaire des ouvriers qui ont moissonné vos champs, et duquel vous les avez frustrés; et les cris de ces moissonneurs sont parvenus jusqu\'aux oreilles du Seigneur des armées.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 5, 'Vous avez vécu sur la terre dans les voluptés et dans les délices; vous avez rassasié vos coeurs au jour du carnage;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 6, 'vous avez condamné, vous avez tué le juste: il ne vous résiste pas!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 7, 'Prenez donc patience, frères, jusqu\'à l\'avènement du Seigneur. Voyez le laboureur: il attend patiemment le précieux fruit de la terre, jusqu\'à ce qu\'il ait reçu les pluies de la première et celles de la dernière saison.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 8, 'Vous aussi, prenez patience et affermissez vos coeurs; car l\'avènement du Seigneur est proche.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 9, 'Frères, ne vous plaignez pas les uns des autres, pour que vous ne soyez pas jugés; voici que le juge est à la porte.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 10, 'Frères, prenez pour modèles de souffrance et de patience les prophètes qui ont parlé au nom du Seigneur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 11, 'Vous savez que nous déclarons bienheureux ceux qui ont souffert avec constance. Vous avez entendu parler de la constance de Job, et vous avez vu la fin que le Seigneur lui a donnée; car le Seigneur est plein de miséricorde et de compassion.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 12, 'Avant tout, mes frères, ne jurez point, ni par le ciel, ni par la terre, ni par aucun autre serment; mais que votre oui soit oui, et votre non, non, afin que vous n\'ayez à encourir aucun jugement.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 13, 'Quelqu\'un parmi vous souffre-t-il? Qu\'il prie. Quelqu\'un est-il dans la joie? Qu\'il chante des cantiques.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 14, 'Quelqu\'un parmi vous est-il malade? Qu\'il appelle les anciens de l\'Église, et que ceux-ci prient pour lui, après l\'avoir oint d\'huile au nom du Seigneur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 15, 'La prière de la foi sauvera le malade, et le Seigneur le relèvera; et, s\'il a commis des péchés, ils lui seront pardonnés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 16, 'Confessez donc vos péchés les uns aux autres, et priez les uns pour les autres, afin que vous soyez guéris: la prière du juste, faite avec ferveur, a une grande puissance.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 17, 'Élie était un homme sujet aux mêmes faiblesses que nous. Il pria, demandant avec instance qu\'il ne plût pas; et il ne plut pas sur la terre pendant trois ans et demi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 18, 'Puis, il pria de nouveau; et le ciel donna de la pluie, et la terre produisit ses fruits.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 19, 'Mes frères, si l\'un de vous s\'est égaré loin de la vérité et qu\'un autre le ramène,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 20, 'qu\'il sache que celui qui ramène un pécheur de la voie où il s\'égare, sauvera une âme de la mort et couvrira une multitude de péchés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 1, 'Pierre, apôtre de Jésus-Christ, aux élus qui sont étrangers et dispersés dans le Pont, la Galatie, la Cappadoce, l\'Asie et la Bithynie;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 2, 'qui sont élus selon la prescience de Dieu, le Père, et sanctifiés par l\'Esprit, pour obéir à Jésus-Christ et pour avoir part à l\'aspersion de son sang: Que la grâce et la paix vous soient multipliées');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 3, 'Béni soit Dieu, le Père de notre Seigneur Jésus-Christ, qui, dans sa grande miséricorde, nous a fait renaître, pour que nous ayons, par la résurrection de Jésus-Christ d\'entre les morts, une espérance vivante,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 4, 'un héritage qui ne peut être ni corrompu, ni souillé, ni flétri, et qui vous est réservé dans les cieux,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 5, 'à vous que la puissance de Dieu garde par la foi, pour le salut qui est prêt à être manifesté dans les derniers temps!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 6, 'Vous vous en réjouissez, quoique maintenant, puisqu\'il le faut, vous soyez, pour un peu de temps, attristés par diverses épreuves;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 7, 'afin que l\'épreuve de votre foi, — beaucoup plus précieuse que l\'or périssable qui pourtant est éprouvé par le feu, — tourne à votre louange, à votre honneur et à votre gloire, lorsque Jésus-Christ paraîtra,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 8, 'lui que vous aimez, sans l\'avoir vu, en qui vous croyez, sans le voir encore. Et vous vous réjouissez d\'une joie ineffable et glorieuse,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 9, 'remportant le prix de votre foi, le salut de vos âmes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 10, 'Ce salut a été l\'objet des recherches et des investigations des prophètes, qui ont prophétisé touchant la grâce qui vous était destinée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 11, 'Ils cherchaient à découvrir l\'époque et les circonstances marquées par l\'Esprit de Christ, qui était en eux, et qui rendait à l\'avance témoignage aux souffrances de Christ et aux gloires qui devaient les suivre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 12, 'Il leur fut révélé que ce n\'était pas pour eux-mêmes, mais pour vous, qu\'ils étaient dispensateurs de ces choses, que vous ont maintenant annoncées ceux qui vous ont prêché l\'Évangile, par l\'Esprit saint envoyé du ciel, et au fond desquelles les anges désirent plonger leurs regards.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 13, 'Vous donc, ayant ceint les reins de votre esprit, étant sobres, attendez avec une parfaite espérance la grâce qui doit vous être dispensée, lorsque Jésus-Christ paraîtra.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 14, 'Comme des enfants obéissants, ne vous conformez pas aux convoitises qui régnaient autrefois en vous, au temps de votre ignorance.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 15, 'Mais, de même que celui qui vous a appelés est saint, vous aussi, soyez saints dans toute votre conduite,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 16, 'puisqu\'il est écrit: «Soyez saints, car je suis saint»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 17, 'Et si vous invoquez comme Père celui qui, sans acception de personnes, juge chacun selon son oeuvre, conduisez-vous avec crainte pendant le temps de votre séjour sur la terre,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 18, 'sachant que ce n\'est point par des choses périssables, comme l\'argent ou l\'or, que vous avez été rachetés de la vaine manière de vivre que vos pères vous avaient transmise,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 19, 'mais par le précieux sang de Christ, l\'Agneau sans défaut et sans tache,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 20, 'déjà prédestiné avant la création du monde et manifesté à la fin des temps à cause de vous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 21, 'Par lui aussi, vous croyez en Dieu qui l\'a ressuscité des morts et qui l\'a glorifié, de telle sorte que c\'est en Dieu que reposent votre foi et votre espérance.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 22, 'Quant à vous, en obéissant à la vérité, vous avez purifié vos âmes: ayez donc un sincère amour fraternel; aimez-vous ardemment les uns les autres, du fond du coeur,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 23, 'vous qui avez été régénérés, non par une semence corruptible, mais par une semence incorruptible, par la parole de Dieu, qui est vivante et qui dure éternellement!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 24, 'Car toute créature est comme l\'herbe, et toute sa gloire comme la fleur de l\'herbe. L\'herbe sèche, et sa fleur tombe,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 25, 'mais la parole du Seigneur demeure éternellement. C\'est cette parole qui vous a été annoncée par l\'Évangile.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 1, 'Rejetez donc toute malice, toute ruse, toute espèce de dissimulation, d\'envie et de médisance,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 2, 'et désirez avec ardeur, comme des enfants nouveau-nés, le lait pur de la Parole, qui vous fera grandir pour le salut,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 3, '— si vous avez goûté que le Seigneur est bon.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 4, 'C\'est en vous approchant de lui, comme de la pierre vivante, rejetée par les hommes, mais choisie et précieuse devant Dieu,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 5, 'que vous aussi, comme des pierres vivantes, vous formez une maison spirituelle, un saint sacerdoce, pour offrir des sacrifices spirituels, agréables à Dieu par Jésus-Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 6, 'Car il est dit dans l\'Écriture: «Voyez! Je pose en Sion la pierre angulaire, choisie et précieuse; et celui qui croit en elle ne sera pas confus.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 7, 'Ainsi donc, pour vous, les croyants, l\'honneur; mais pour les incrédules, la pierre, rejetée par ceux qui bâtissaient, est devenue la pierre de l\'angle, une pierre d\'achoppement, un rocher, qui fait tomber:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 8, 'ils s\'y heurtent, parce qu\'ils n\'obéissent pas à la parole; et c\'est à cela qu\'ils étaient destinés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 9, 'Mais vous, vous êtes la race élue, le sacerdoce royal, la nation sainte, le peuple que Dieu s\'est acquis, afin que vous annonciez les vertus de Celui qui vous a appelés des ténèbres à sa merveilleuse lumière,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 10, 'vous qui autrefois n\'étiez pas un peuple, et qui êtes maintenant le peuple de Dieu, vous qui n\'aviez pas obtenu miséricorde, et qui avez maintenant obtenu miséricorde.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 11, 'Mes bien-aimés, je vous exhorte, comme des étrangers et des voyageurs, à vous abstenir des convoitises charnelles, qui font la guerre à l\'âme.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 12, 'Ayez une bonne conduite au milieu des Païens, afin que, pour les faits mêmes dont ils vous accusent, comme si vous étiez des malfaiteurs, ils rendent gloire à Dieu le jour où il les visitera, quand ils auront vu vos bonnes oeuvres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 13, 'Soyez soumis, à cause du Seigneur, à toute institution humaine, soit au roi, comme souverain,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 14, 'soit aux gouverneurs, comme envoyés de sa part pour punir les malfaiteurs et pour honorer les gens de bien.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 15, 'Car c\'est la volonté de Dieu, qu\'en faisant le bien, vous réduisiez au silence l\'ignorance des insensés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 16, 'Conduisez-vous comme des hommes libres, non pour faire de la liberté un voile qui couvre la méchanceté, mais comme des serviteurs de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 17, 'Honorez tous les hommes; aimez vos frères; craignez Dieu; rendez honneur au roi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 18, 'Serviteurs, soyez soumis avec le plus grand respect à vos maîtres, non seulement à ceux qui sont bons et humains, mais aussi à ceux qui sont d\'humeur difficile.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 19, 'Car c\'est une grâce, d\'endurer des peines et de souffrir injustement, par motif de conscience, pour obéir à Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 20, 'En effet, quelle gloire y aurait-il à supporter patiemment d\'être battu pour avoir fait le mal? Mais si, en faisant le bien, vous êtes maltraités, et que vous supportiez patiemment l\'épreuve, c\'est là une grâce aux yeux de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 21, 'Or, c\'est à cela que vous avez été appelés; car Christ aussi a souffert pour vous, vous laissant un exemple, afin que vous suiviez ses traces.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 22, 'lui qui n\'a point commis de péché, et dans la bouche duquel il ne s\'est trouvé aucune fraude;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 23, 'lui qui, outragé, ne rendait pas l\'outrage; qui, maltraité, ne faisait point de menaces, mais s\'en remettait à Celui qui juge justement;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 24, 'qui a porté lui-même nos péchés en son corps sur le bois, afin qu\'étant morts à nos péchés, nous vivions pour la justice; lui, enfin, par les meurtrissures duquel vous avez été guéris.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 25, 'Car vous étiez comme des brebis errantes; mais vous êtes maintenant retournés au Pasteur et à l\'Évêque de vos âmes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 1, 'Vous aussi, femmes, soyez soumises à vos maris, afin que, s\'il y en a qui n\'obéissent point à la Parole, ils soient gagnés, sans le secours de la Parole, par la conduite de leurs femmes,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 2, 'en considérant combien votre conduite est pure et respectueuse.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 3, 'Recherchez, non la parure extérieure qui consiste à se tresser les cheveux, à porter des ornements d\'or ou des vêtements somptueux,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 4, 'mais la parure intérieure et cachée dans le coeur, la pureté incorruptible d\'un esprit doux et paisible, qui est d\'un si grand prix devant Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 5, 'En effet, c\'est ainsi que se paraient autrefois les saintes femmes qui espéraient en Dieu, étant soumises à leurs maris,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 6, 'comme Sara, qui obéissait à Abraham, l\'appelant son seigneur, elle dont vous êtes devenues les filles en faisant le bien, sans vous laisser troubler par aucune crainte.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 7, 'Vous, de même, maris, montrez de la sagesse dans vos rapports avec vos femmes, comme avec un sexe plus faible; et, puisqu\'elles doivent hériter avec vous la grâce de la vie, ayez des égards pour elles, afin que rien ne trouble vos prières.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 8, 'Enfin, soyez tous d\'un même sentiment, pleins de compassion et d\'amour fraternel, miséricordieux et humbles.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 9, 'Ne rendez pas le mal pour le mal, ni l\'injure pour l\'injure; au contraire, bénissez, car c\'est à cela que vous avez été appelés pour hériter vous-mêmes la bénédiction.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 10, 'En effet, que celui qui veut aimer la vie et voir des jours heureux, garde sa langue du mal et ses lèvres de toute parole trompeuse.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 11, 'Qu\'il se détourne du mal et fasse le bien, qu\'il cherche la paix et la poursuive.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 12, 'Car les yeux du Seigneur sont sur les justes, et ses oreilles sont attentives à leurs prières; mais la face du Seigneur est contre ceux qui font le mal.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 13, 'Qui donc peut vous faire du mal, si vous êtes zélés pour le bien?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 14, 'Si même vous avez à souffrir pour la justice, vous êtes heureux! Ne craignez pas ce qu\'ils craignent, et ne soyez pas troublés;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 15, 'mais sanctifiez dans vos coeurs le Christ, le Seigneur. Soyez toujours prêts à répondre pour votre défense, — mais avec douceur et respect, — à tous ceux qui vous demandent raison de l\'espérance qui est en vous,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 16, 'ayant une bonne conscience, afin que, pour les faits mêmes dont vous êtes accusés, ceux qui décrient votre bonne conduite en Christ soient couverts de confusion;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 17, 'car il vaut mieux souffrir, si telle est la volonté de Dieu, en faisant le bien, qu\'en faisant le mal.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 18, 'En effet, Christ aussi est mort une fois pour les péchés, lui juste pour les injustes, afin de nous amener à Dieu, ayant été mis à mort quant à la chair, mais rendu à la vie quant à l\'Esprit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 19, 'C\'est par ce même Esprit qu\'il est allé prêcher aux esprits retenus en prison, qui furent autrefois rebelles,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 20, 'lorsque, du temps de Noé, la patience de Dieu attendait, et que se construisait l\'arche, dans laquelle un petit nombre, savoir, huit personnes, furent sauvées à travers l\'eau.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 21, 'C\'était une figure du baptême qui, maintenant, vous sauve, et qui consiste, non dans la purification des souillures du corps, mais dans l\'engagement d\'une bonne conscience envers Dieu, par la résurrection de Jésus-Christ,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 22, 'lequel est à la droite de Dieu, étant monté au ciel, et à qui les anges, les principautés et les puissances sont assujettis.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 1, 'Ainsi donc, puisque Christ a souffert dans la chair, vous aussi, armez-vous de cette pensée, que celui qui a souffert dans la chair a rompu avec le péché,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 2, 'pour vivre — pendant le temps qui lui reste à passer dans la chair, — non plus suivant les convoitises des hommes, mais selon la volonté de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 3, 'C\'est bien assez d\'avoir, dans le passé, accompli la volonté des Païens, en vivant dans le dérèglement, les convoitises, l\'ivrognerie, les excès de table, les orgies, et les idolâtries criminelles.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 4, 'Ils trouvent étrange que vous ne couriez plus avec eux à ce débordement de dissolution, et ils vous outragent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 5, 'Mais ils rendront compte à celui qui est prêt à juger les vivants et les morts.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 6, 'Car c\'est pour cela que l\'Évangile a été aussi annoncé aux morts, afin qu\'après avoir été jugés selon les hommes, quant à la chair, ils vivent selon Dieu, quant à l\'esprit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 7, 'La fin de toutes choses est proche; soyez donc sobres et vigilants pour vous livrer à la prière.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 8, 'Ayez avant tout les uns pour les autres une ardente charité; car la charité couvre une multitude de péchés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 9, 'Exercez, sans murmurer, l\'hospitalité les uns envers les autres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 10, 'Que chacun de vous emploie au service des autres le don qu\'il a reçu, comme doivent le faire de bons administrateurs des diverses grâces de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 11, 'Si quelqu\'un parle, que ce soit comme annonçant les oracles de Dieu; si quelqu\'un exerce quelque ministère, que ce soit avec la force que Dieu donne, afin qu\'en toutes choses Dieu soit glorifié par Jésus-Christ, auquel appartiennent la gloire et la puissance, aux siècles des siècles! Amen.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 12, 'Mes bien-aimés, ne trouvez pas étrange d\'être dans la fournaise de l\'épreuve, comme s\'il vous arrivait quelque chose d\'extraordinaire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 13, 'Mais réjouissez-vous dans la mesure même où vous avez part aux souffrances du Christ, afin que, le jour où sa gloire sera manifestée, vous soyez aussi dans la joie et l\'allégresse.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 14, 'Si l\'on vous dit des injures pour le nom de Christ, vous êtes heureux; car l\'Esprit de gloire, l\'Esprit de Dieu, repose sur vous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 15, 'Que nul de vous n\'ait à souffrir comme meurtrier, comme voleur, comme malfaiteur, ou pour avoir convoité les biens d\'autrui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 16, 'Mais si quelqu\'un souffre comme chrétien, qu\'il n\'en ait point de honte; que plutôt il glorifie Dieu pour ce nom même.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 17, 'Car le moment est venu où le jugement va commencer par la maison de Dieu; or, s\'il commence par nous, quelle sera la fin de ceux qui désobéissent à l\'Évangile de Dieu?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 18, 'Et si le juste n\'est sauvé que difficilement, que deviendront l\'impie et le pécheur?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 19, 'Que ceux donc qui souffrent selon la volonté de Dieu, recommandent leurs âmes au fidèle Créateur, en faisant le bien.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 1, 'J\'adresse cette exhortation aux anciens qui sont parmi vous, moi qui suis ancien avec eux et témoin des souffrances du Christ, et qui ai part aussi à la gloire qui doit être manifestée:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 2, 'Paissez le troupeau de Dieu qui vous est confié: faites-le, non par contrainte, mais de bon gré, non pour un gain sordide, mais par dévouement,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 3, 'non en dominant sur ceux qui vous sont échus en partage, mais en vous rendant les modèles du troupeau.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 4, 'Et lorsque le souverain Pasteur paraîtra, vous remporterez la couronne de gloire, qui ne se flétrit jamais.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 5, 'De même, jeunes gens, soyez soumis aux anciens. Et tous, soyez ornés d\'humilité les uns à l\'égard des autres; car Dieu résiste aux orgueilleux, mais il fait grâce aux humbles.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 6, 'Humiliez-vous donc sous la puissante main de Dieu, afin qu\'il vous élève quand il en sera temps;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 7, 'et déchargez-vous sur lui de tous vos soucis, parce qu\'il a soin de vous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 8, 'Soyez sobres, veillez! Votre adversaire, le Diable, rôde autour de vous comme un lion rugissant, cherchant qui il pourra dévorer.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 9, 'Résistez-lui, en demeurant fermes dans la foi, sachant que vos frères, répandus dans le monde, souffrent les mêmes afflictions que vous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 10, 'Le Dieu de toute grâce, qui vous a appelés en Christ à sa gloire éternelle, après que vous aurez souffert un peu de temps, vous perfectionnera lui-même, vous affermira, vous fortifiera.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 11, 'A lui soit la puissance, aux siècles des siècles! Amen.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 12, 'Je vous ai écrit ces quelques mots par Silvain, que j\'estime être un frère fidèle, pour vous exhorter, et pour vous attester que c\'est à la vraie grâce de Dieu que vous êtes attachés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 13, 'L\'Église des élus, qui est à Babylone, vous salue, ainsi que Marc, mon fils.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 14, 'Saluez-vous les uns les autres par un baiser fraternel. Que la paix soit avec vous tous qui êtes en Christ!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 1, 'Simon Pierre, serviteur et apôtre de Jésus-Christ, à ceux qui, par la justice de notre Dieu et du Sauveur Jésus-Christ, ont reçu en partage une foi de même prix que la nôtre:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 2, 'Que la grâce et la paix vous soient multipliées par la connaissance de Dieu et de Jésus, notre Seigneur!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 3, 'Sa divine puissance nous a fait don de tout ce qui contribue à la vie et à la piété, en nous faisant connaître Celui, qui nous a appelés par sa gloire et par sa vertu;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 4, '— et, par elles, nous avons été mis en possession des plus précieuses et des plus grandes promesses, afin que, par leur moyen, vous deveniez participants de la nature divine, en fuyant la corruption qui règne dans le monde par la convoitise.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 5, 'Faites donc aussi, de votre côté, tous vos efforts pour joindre à votre foi la vertu, à la vertu la science,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 6, 'à la science la tempérance, à la tempérance la patience, à la patience la piété,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 7, 'à la piété l\'amour fraternel, et à l\'amour fraternel la charité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 8, 'En effet, si ces grâces se trouvent en vous et si elles y abondent, elles ne vous laisseront ni oisifs, ni stériles dans la connaissance de notre Seigneur Jésus-Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 9, 'Mais celui à qui elles manquent est un homme qui a la vue courte, un aveugle; il a oublié la purification de ses péchés d\'autrefois.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 10, 'Appliquez-vous donc, frères, à affermir votre vocation et votre élection. En faisant cela, vous ne broncherez jamais;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 11, 'et ainsi vous sera largement accordée l\'entrée dans le royaume éternel de notre Seigneur et Sauveur Jésus-Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 12, 'Voilà pourquoi je ne cesserai pas de vous faire ressouvenir de ces choses, quoique vous les connaissiez bien et que vous soyez affermis dans la vérité présente.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 13, 'Je regarde néanmoins comme mon devoir, aussi longtemps que je suis dans cette tente, de vous tenir en éveil par mes avertissements;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 14, 'car je sais que je dois bientôt quitter cette tente, comme notre Seigneur Jésus-Christ me l\'a déclaré.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 15, 'Mais j\'aurai soin qu\'après mon départ, vous puissiez toujours conserver le souvenir de ce que je vous ai dit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 16, 'En effet, ce n\'est pas en suivant des fables habilement composées, que nous vous avons fait connaître la puissance et l\'avènement de notre Seigneur Jésus-Christ; c\'est pour avoir vu sa majesté de nos propres yeux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 17, 'Car il reçut honneur et gloire de la part de Dieu, son Père, lorsque la Majesté suprême lui adressa cette parole: «Celui-ci est mon Fils bien-aimé, en qui j\'ai mis toute mon affection.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 18, 'Nous-mêmes, nous avons entendu cette voix venant du ciel, quand nous étions avec lui sur la sainte montagne.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 19, 'Et nous tenons pour d\'autant plus certaine la parole des prophètes, — à laquelle vous faites bien de prêter attention, comme à une lampe qui brille dans un lieu obscur, jusqu\'à ce que le jour commence à luire et que l\'étoile du matin se lève dans vos coeurs.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 20, 'Avant tout, sachez bien que nulle prophétie de l\'Écriture n\'est affaire d\'interprétation privée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 21, 'Car jamais aucune prophétie n\'est procédée de la volonté d\'un homme; mais c\'est poussés par l\'Esprit saint que des hommes ont parlé de la part de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 1, 'Cependant, il y eut aussi de faux prophètes parmi le peuple, et il y aura de même parmi vous de faux docteurs, qui introduiront sourdement des hérésies pernicieuses, et qui, reniant le Maître qui les a rachetés, attireront sur eux-mêmes une ruine soudaine.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 2, 'Plusieurs les suivront dans leurs dérèglements, et la voie de la vérité sera calomniée à cause d\'eux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 3, 'Dans leur cupidité, ils vous exploiteront par des paroles artificieuses; mais le jugement depuis longtemps prononcé contre eux ne restera pas sans effet, et leur ruine ne tardera pas.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 4, 'Si Dieu, en effet, n\'a pas épargné les anges qui avaient péché, mais s\'il les a précipités dans l\'abîme, où les ténèbres les tiennent prisonniers et où ils sont gardés pour le jugement;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 5, 's\'il n\'a pas épargné l\'ancien monde, et n\'a préservé que Noé, ce prédicateur de la justice, avec sept autres personnes, lorsqu\'il a fait venir le déluge sur ce monde d\'impies;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 6, 's\'il a condamné à la destruction et réduit en cendres les villes de Sodome et de Gomorrhe, pour les faire servir d\'exemples aux impies de l\'avenir;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 7, 'si, enfin, il a délivré le juste Lot, qui était outré de la conduite déréglée de ces pervers');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 8, '— car ce juste, qui demeurait parmi eux, sentait son âme juste tourmentée, chaque jour, de ce qu\'il voyait et entendait de leurs oeuvres criminelles, —');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 9, 'c\'est que le Seigneur sait délivrer de l\'épreuve les hommes pieux, et châtier les injustes, en les gardant pour le jour du jugement,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 10, 'ceux-là surtout qui, dans leurs impures convoitises, courent après les jouissances de la chair et méprisent l\'autorité souveraine. Audacieux, arrogants, ils ne craignent pas de parler injurieusement des Gloires,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 11, 'tandis que des anges, leurs supérieurs en force et en puissance, ne prononcent point contre elles, devant le Seigneur, de jugement injurieux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 12, 'Mais eux, pareils à des animaux destitués de raison, nés pour une vie purement physique et destinés à être pris et détruits, injuriant ce qu\'ils ignorent, ils périront aussi de la mort des bêtes, et ils recevront ainsi le salaire de leur iniquité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 13, 'Ils trouvent leur bonheur à se livrer à la débauche en plein jour. Hommes tarés et souillés, ils se délectent de leurs fourberies, lorsqu\'ils font bonne chère à vos repas.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 14, 'Ils ont les yeux pleins d\'adultère; ils sont insatiables de péché; ils séduisent les âmes mal affermies; ils ont le coeur exercé à la cupidité: ce sont des enfants de malédiction.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 15, 'Ils ont quitté le droit chemin; ils se sont égarés en suivant la voie de Balaam, fils de Bosor, qui aima le salaire de l\'iniquité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 16, 'Mais il fut repris pour sa désobéissance; car un animal muet, s\'étant mis à parler d\'une voix humaine, réprima la démence du prophète.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 17, 'Ces gens-là sont des fontaines sans eau, des nuées qu\'emporte un tourbillon, et l\'obscurité des ténèbres leur est réservée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 18, 'Avec leurs discours pompeux et vides, ils séduisent, par les convoitises de la chair et par l\'impudicité, ceux qui viennent à peine d\'échapper aux hommes qui suivent la voie de l\'erreur,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 19, 'en leur promettant la liberté, alors qu\'ils sont eux-mêmes esclaves de la corruption; car on est esclave de ce qui vous a vaincu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 20, 'En effet, si, après avoir échappé aux souillures du monde par la connaissance de notre Seigneur et Sauveur Jésus-Christ, ils se laissent vaincre en s\'y engageant de nouveau, leur dernière condition devient pire que la première.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 21, 'Il leur eût mieux valu n\'avoir pas connu la voie de la justice, que de se détourner, après l\'avoir connue, du saint commandement qui leur avait été transmis.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 22, 'Il leur est arrivé ce que dit avec raison le proverbe: «Le chien est retourné à ce qu\'il avait vomi; et la truie, après avoir été lavée, s\'est vautrée dans le bourbier.»');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 1, 'Voici déjà, bien-aimés, la seconde lettre que je vous écris. Dans l\'une et dans l\'autre, je cherche à éveiller en vous une saine intelligence,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 2, 'en faisant appel à votre mémoire, pour que vous vous souveniez des prédictions faites par les saints prophètes, et du commandement de notre Seigneur et Sauveur, transmis par vos apôtres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 3, 'Sachez d\'abord que, dans les derniers jours, il viendra des moqueurs pleins de raillerie, vivant au gré de leurs propres convoitises;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 4, 'et ils diront: Où est la promesse de son avènement? Car, depuis que nos pères sont morts, toutes choses demeurent dans le même état que depuis le commencement du monde.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 5, 'Ils oublient volontairement qu\'il a existé autrefois des cieux et une terre, tirée de l\'eau et formée au moyen de l\'eau par la parole de Dieu:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 6, 'c\'est ainsi que le monde d\'alors périt, submergé par l\'eau du déluge.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 7, 'Mais les cieux et la terre d\'à présent sont gardés par cette même parole et réservés pour le feu, qui doit les consumer au jour du jugement et de la destruction des hommes impies.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 8, 'Pour vous, bien-aimés, ce que vous ne devez pas oublier, c\'est que, devant le Seigneur, un jour est comme mille ans, et mille ans sont comme un jour.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 9, 'Le Seigneur ne retarde point l\'exécution de sa promesse, comme quelques-uns se l\'imaginent; mais il use de patience envers vous, voulant que personne ne périsse, mais que tous, au contraire, viennent à la repentance.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 10, 'Cependant, le jour du Seigneur viendra comme un voleur. Alors les cieux passeront avec fracas, les éléments embrasés se dissoudront, et la terre, avec les oeuvres qu\'elle renferme, sera consumée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 11, 'Puisque toutes ces choses doivent se dissoudre, combien ne devez-vous pas être saints et pieux dans votre conduite,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 12, 'attendant et hâtant la venue du jour de Dieu, ce jour dans lequel les cieux enflammés seront dissous, et les éléments embrasés se fondront!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 13, 'Or, nous attendons, selon sa promesse, de nouveaux cieux et une nouvelle terre où la justice habite.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 14, 'C\'est pourquoi, bien-aimés, dans cette attente, faites tous vos efforts, pour qu\'il vous trouve sans tache et sans reproche, dans la paix.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 15, 'Et reconnaissez que la longue patience de notre Seigneur sert à votre salut, comme Paul, notre frère bien-aimé, vous l\'a aussi écrit, avec la sagesse qui lui a été donnée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 16, 'C\'est ce qu\'il fait dans toutes les lettres où il parle de ces choses, et où se trouvent des passages difficiles à comprendre, dont les esprits ignorants et mal affermis tordent le sens, comme ils le font à l\'égard des autres Écritures, pour leur propre perdition.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 17, 'Vous donc, bien aimés, puisque vous êtes prévenus, tenez-vous sur vos gardes, de peur que vous ne soyez entraînés, vous aussi, dans l\'égarement de ces pervers, et que vous ne veniez à déchoir de votre fermeté.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 18, 'Croissez dans la grâce et dans la connaissance de notre Seigneur et Sauveur Jésus-Christ. A lui soit la gloire, maintenant et jusqu\'au jour de l\'éternité!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 1, 'Ce qui était dès le commencement, ce que nous avons entendu, ce que nous avons vu de nos yeux, ce que nous avons contemplé et que nos mains ont touché, concernant la Parole de vie,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 2, '— car la vie a été manifestée; nous l\'avons vue, et nous lui rendons témoignage, et nous vous annonçons la vie éternelle, qui était auprès du Père et qui nous a été manifestée. —');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 3, 'ce que nous avons vu et entendu, nous vous l\'annonçons, à vous aussi, afin que vous soyez vous-mêmes en communion avec nous. Or, nous sommes en communion avec le Père et avec son Fils Jésus-Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 4, 'Et nous vous écrivons ces choses, afin que notre joie soit parfaite.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 5, 'Voici le message que nous avons entendu de lui et que nous vous annonçons, c\'est que Dieu est lumière, et qu\'il n\'y a point en lui de ténèbres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 6, 'Si nous disons que nous sommes en communion avec lui et que nous marchions dans les ténèbres, nous mentons et nous ne pratiquons pas la vérité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 7, 'Mais, si nous marchons dans la lumière, comme il est lui-même dans la lumière, nous sommes en communion les uns avec les autres; et le sang de Jésus, son Fils, nous purifie de tout péché.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 8, 'Si nous disons que nous n\'avons point de péché, nous nous séduisons nous-mêmes, et la vérité n\'est point en nous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 9, 'Si nous confessons nos péchés, il est fidèle et juste pour nous les pardonner, et pour nous purifier de toute iniquité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 10, 'Si nous disons que nous n\'avons pas péché, nous le faisons menteur, et sa parole n\'est point en nous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 1, 'Mes petits enfants, je vous écris ces choses, afin que vous ne péchiez point. Si quelqu\'un a péché, nous avons un avocat auprès du Père, Jésus-Christ le Juste.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 2, 'C\'est lui qui est la victime de propitiation pour nos péchés, et non seulement pour les nôtres, mais aussi pour ceux du monde entier.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 3, 'Nous reconnaissons que nous l\'avons connu, quand nous gardons ses commandements.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 4, 'Celui qui dit: Je l\'ai connu, et qui ne garde pas ses commandements, est un menteur, et la vérité n\'est point en lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 5, 'Mais en celui qui garde sa parole, l\'amour de Dieu est véritablement parfait. Par là, nous savons que nous sommes en lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 6, 'Celui qui dit qu\'il demeure en lui, doit aussi marcher comme il a marché lui-même.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 7, 'Mes bien-aimés, ce n\'est pas un commandement nouveau que je vous écris, mais un commandement ancien, celui que vous avez reçu dès le commencement; ce commandement ancien, c\'est la parole que vous avez entendue.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 8, 'Pourtant, c\'est aussi un commandement nouveau que je vous écris, vraiment nouveau et en lui et en vous, parce que les ténèbres se dissipent et que la vraie lumière luit déjà.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 9, 'Celui qui dit qu\'il est dans la lumière et qui hait son frère, est encore dans les ténèbres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 10, 'Celui qui aime son frère, demeure dans la lumière, et il n\'y a rien en lui qui le fasse broncher.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 11, 'Mais celui qui hait son frère est dans les ténèbres et marche dans les ténèbres, et il ne sait où il va, parce que les ténèbres ont aveuglé ses yeux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 12, 'Mes petits enfants, je vous écris, parce que vos péchés vous sont pardonnés à cause de son nom.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 13, 'Pères, je vous écris, parce que vous avez connu celui qui est dès le commencement. Jeunes gens, je vous écris, parce que vous avez vaincu le Malin. Enfants, je vous ai écrit, parce que vous avez connu le Père.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 14, 'Pères, je vous ai écrit, parce que vous avez connu celui qui est dès le commencement. Jeunes gens, je vous ai écrit, parce que vous êtes forts, et que la parole de Dieu demeure en vous, et que vous avez vaincu le Malin.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 15, 'N\'aimez pas le monde, ni les choses qui sont dans le monde; si quelqu\'un aime le monde, l\'amour du Père n\'est point en lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 16, 'En effet, tout ce qui est dans le monde, la convoitise de la chair, la convoitise des yeux et l\'orgueil de la vie, ne vient pas du Père, mais vient du monde.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 17, 'Or, le monde passe, avec sa convoitise, mais celui qui fait la volonté de Dieu demeure éternellement.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 18, 'Mes enfants, c\'est ici la dernière heure. Vous avez entendu dire que l\'Antéchrist doit venir. Et dès maintenant, il y a plusieurs antéchrists; par là, nous connaissons que c\'est la dernière heure.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 19, 'Ils sont sortis du milieu de nous, mais ils n\'étaient pas des nôtres; car s\'ils avaient été des nôtres, ils seraient demeurés avec nous. Mais cela est arrivé, afin qu\'il devînt manifeste que tous ne sont pas des nôtres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 20, 'Pour vous, vous avez reçu l\'onction de la part de Celui qui est saint, et vous avez tous de la connaissance.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 21, 'Je vous ai écrit, non parce que vous ne connaissez pas la vérité, mais parce que vous la connaissez et que vous savez qu\'aucun mensonge ne vient de la vérité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 22, 'Qui est le menteur, sinon celui qui nie que Jésus est le Christ? Voilà l\'Antéchrist, celui qui nie le Père et le Fils!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 23, 'Quiconque nie le Fils, n\'a pas non plus le Père: celui qui confesse le Fils, a aussi le Père.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 24, 'Pour vous, que ce que vous avez entendu dès le commencement demeure en vous. Si ce que vous avez entendu dès le commencement demeure en vous, vous demeurerez aussi dans le Fils et dans le Père.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 25, 'Et la promesse que lui-même nous a faite, c\'est la vie éternelle.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 26, 'Je vous ai écrit ces choses au sujet de ceux qui vous égarent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 27, 'Pour vous, l\'onction que vous avez reçue de lui demeure en vous, et vous n\'avez pas besoin que personne vous instruise; mais, comme son onction vous instruit de toutes choses, et qu\'elle est vraie, qu\'elle n\'est pas un mensonge, demeurez en lui, selon l\'instruction que vous avez reçue.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 28, 'Maintenant donc, mes petits enfants, demeurez en lui, afin que, s\'il vient à paraître, nous soyons pleins d\'assurance et que nous ne soyons pas confondus et rejetés loin de lui, à son avènement.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 29, 'Si vous savez qu\'il est juste, reconnaissez que quiconque pratique la justice est né de lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 1, 'Voyez quel amour le Père nous a témoigné, que nous soyons appelés enfants de Dieu! Nous le sommes, en effet: c\'est pour cela que le monde ne nous connaît point, parce qu\'il ne l\'a pas connu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 2, 'Mes bien-aimés, nous sommes dès à présent enfants de Dieu, et ce que nous serons n\'a pas encore été manifesté. Nous savons que, lorsqu\'il paraîtra, nous lui serons semblables, parce que nous le verrons tel qu\'il est.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 3, 'Et quiconque a cette espérance en lui, se purifie lui-même, comme lui aussi est pur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 4, 'Quiconque commet le péché, transgresse la loi; et le péché est la transgression de la loi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 5, 'Or, vous savez que Jésus-Christ a paru pour ôter les péchés, et qu\'il n\'y a point de péché en lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 6, 'Quiconque demeure en lui, ne pèche pas; quiconque pèche, ne l\'a pas vu et ne l\'a pas connu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 7, 'Mes petits enfants, que personne ne vous séduise; celui qui pratique la justice, est juste, comme lui-même est juste.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 8, 'Celui qui commet le péché, est du Diable; car le Diable pèche depuis le commencement. Or, le Fils de Dieu a paru pour détruire les oeuvres du Diable.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 9, 'Quiconque est né de Dieu, ne commet point le péché, parce que la semence de Dieu demeure en lui; et il ne peut pécher parce qu\'il est Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 10, 'A ceci l\'on reconnaît les enfants de Dieu et les enfants du Diable: quiconque ne pratique pas la justice, n\'est point de Dieu; il ne l\'est pas non plus, celui qui n\'aime pas son frère.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 11, 'En effet, le message que vous avez entendu dès le commencement, c\'est que nous nous aimions les uns les autres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 12, 'Ne soyons pas comme Caïn, qui était du Malin et qui tua son frère. Et pourquoi le tua-t-il? Parce que ses oeuvres étaient mauvaises, et que celles de son frère étaient justes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 13, 'Mes frères, ne vous étonnez pas si le monde vous hait.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 14, 'Pour nous, nous savons que nous sommes passés de la mort à la vie, parce que nous aimons nos frères. Celui qui n\'aime pas, demeure dans la mort.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 15, 'Quiconque hait son frère, est un meurtrier; et vous savez qu\'aucun meurtrier n\'a la vie éternelle demeurant en lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 16, 'A ceci nous avons connu l\'amour, c\'est qu\'il a donné sa vie pour nous; nous aussi, nous devons donner notre vie pour nos frères.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 17, 'Si quelqu\'un possède les biens de ce monde et que, voyant son frère dans le besoin, il lui ferme ses entrailles, comment l\'amour de Dieu demeurerait-il en lui?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 18, 'Mes petits enfants, n\'aimons pas en paroles et avec la langue mais en action et en vérité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 19, 'Par là, nous connaîtrons que nous sommes de la vérité, et nous assurerons nos coeurs devant lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 20, 'Car si notre coeur nous condamne. Dieu est plus grand que notre coeur, et il connaît toutes choses.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 21, 'Mes bien-aimés, si notre coeur ne nous condamne pas, nous avons une grande assurance pour nous approcher de Dieu;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 22, 'et quoi que nous demandions, nous le recevons de lui, parce que nous gardons ses commandements et que nous faisons ce qui lui est agréable.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 23, 'Or, voici son commandement: c\'est que nous croyions au nom de son Fils Jésus-Christ, et que nous nous aimions les uns les autres, comme il nous l\'a commandé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 24, 'Celui qui garde ses commandements, demeure en Dieu, et Dieu en lui; et nous connaissons qu\'il demeure en nous, par l\'Esprit qu\'il nous a donné.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 1, 'Mes bien-aimés, ne vous fiez pas à tout esprit; mais éprouvez les esprits, pour savoir s\'ils viennent de Dieu; car plusieurs faux prophètes ont paru dans le monde.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 2, 'Et voici comment vous reconnaîtrez l\'Esprit de Dieu: tout esprit qui confesse Jésus-Christ venu en chair, est de Dieu;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 3, 'et tout esprit qui ne confesse pas Jésus, n\'est pas de Dieu. C\'est là l\'esprit de l\'Antéchrist, dont vous avez entendu annoncer la venue; et déjà maintenant il est dans le monde.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 4, 'Pour vous, mes petits enfants, vous êtes venus de Dieu, et vous avez vaincu ces faux prophètes, parce que celui qui est en vous, est plus grand que celui qui est dans le monde.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 5, 'Ils sont du monde; voilà pourquoi ils parlent selon le monde, et le monde les écoute.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 6, 'Nous, nous sommes de Dieu: celui qui connaît Dieu, nous écoute; celui qui n\'est point de Dieu ne nous écoute pas. C\'est par là que nous reconnaissons l\'esprit de vérité et l\'esprit d\'erreur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 7, 'Mes bien-aimés, aimons-nous les uns les autres; car l\'amour vient de Dieu, et quiconque aime, est né de Dieu et connaît Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 8, 'Celui qui n\'aime pas, n\'a pas connu Dieu; car Dieu est amour.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 9, 'L\'amour de Dieu pour nous a été manifesté en ceci: Dieu a envoyé son Fils unique dans le monde, afin que nous ayons la vie par lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 10, 'Voici en quoi consiste l\'amour: ce n\'est pas nous qui avons aimé Dieu, mais c\'est lui qui nous a aimés, et qui a envoyé son Fils comme victime de propitiation pour nos péchés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 11, 'Mes bien-aimés, si Dieu nous a ainsi aimés, nous aussi nous devons nous aimer les uns les autres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 12, 'Personne n\'a jamais vu Dieu; si nous nous aimons les uns les autres, Dieu demeure en nous, et son amour est parfait en nous.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 13, 'A ceci nous connaissons que nous demeurons en lui et lui en nous, c\'est qu\'il nous a donné de son Esprit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 14, 'Et nous avons vu, et nous rendons témoignage que le Père a envoyé le Fils pour être le Sauveur du monde.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 15, 'Si quelqu\'un confesse que Jésus est le Fils de Dieu, Dieu demeure en lui, et lui en Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 16, 'Et nous avons connu l\'amour que Dieu a pour nous, et nous y avons cru. Dieu est amour; et celui qui demeure dans l\'amour, demeure en Dieu, et Dieu demeure en lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 17, 'Voici comment l\'amour est accompli en nous, pour nous donner une pleine assurance au jour du jugement, c\'est que tel Il est, tels nous sommes aussi dans ce monde.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 18, 'Il n\'y a point de crainte dans l\'amour, mais l\'amour parfait bannit la crainte; car la crainte suppose le châtiment, et celui qui craint n\'est pas parfait dans l\'amour.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 19, 'Nous aimons, parce qu\'il nous a aimés le premier.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 20, 'Si quelqu\'un dit: J\'aime Dieu, et si cet homme-là hait son frère, il est menteur; car celui\'qui n\'aime pas son frère qu\'il voit, ne peut aimer Dieu qu\'il ne voit pas.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 21, 'Et nous avons reçu de lui ce commandement: Que celui qui aime Dieu aime aussi son frère.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 1, 'Quiconque croit que Jésus est le Christ, est né de Dieu, et quiconque aime Dieu qui l\'a fait naître, aime aussi ceux qui sont nés de lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 2, 'Nous connaissons que nous aimons les enfants de Dieu, lorsque nous aimons Dieu et que nous accomplissons ses commandements.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 3, 'Car voici en quoi consiste l\'amour de Dieu, c\'est que nous gardions ses commandements. Or, ses commandements ne sont pas pénibles,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 4, 'parce que tout ce qui est né de Dieu est victorieux du monde; et la victoire par laquelle le monde a été vaincu, c\'est notre foi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 5, 'Quel est celui qui est victorieux du monde, sinon celui qui croit que Jésus est le Fils de Dieu?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 6, 'C\'est lui, Jésus-Christ, qui est venu avec l\'eau et le sang, non pas avec l\'eau seulement, mais avec l\'eau et avec le sang; et c\'est l\'Esprit qui en rend témoignage, parce que l\'Esprit est la vérité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 7, 'Car il y en a trois qui rendent témoignage:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 8, 'l\'Esprit, l\'eau et le sang; et ces trois sont unanimes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 9, 'Si nous recevons le témoignage des hommes, le témoignage de Dieu est plus grand encore; or, le témoignage de Dieu, c\'est celui qu\'il a rendu à son Fils.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 10, 'Celui qui croit au Fils de Dieu, a ce témoignage en lui-même; celui qui ne croit pas Dieu, le fait menteur, parce qu\'il ne croit pas au témoignage que Dieu a rendu à son Fils.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 11, 'Et voici ce témoignage: c\'est que Dieu nous a donné la vie éternelle, et que cette vie est dans son Fils.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 12, 'Celui qui a le Fils, a la vie; celui qui n\'a pas le Fils de Dieu, n\'a pas la vie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 13, 'Je vous ai écrit ces choses, à vous qui croyez au nom du Fils de Dieu, afin que vous sachiez que vous avez la vie éternelle.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 14, 'C\'est ici la confiance que nous avons en lui, que si nous demandons quelque chose selon sa volonté, il nous exauce.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 15, 'Et si nous savons qu\'il nous exauce, quoi que nous lui demandions, — nous le savons, parce que nous avons reçu ce que nous lui avons demandé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 16, 'Si quelqu\'un voit son frère commettre un péché qui ne va pas à la mort, qu\'il prie, et Dieu lui donnera la vie; il la donnera à ceux qui ont commis un péché n\'allant pas à la mort. Il y a un péché qui va à la mort; ce n\'est pas pour ce péché-là que je dis de prier.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 17, 'Toute iniquité est un péché; et il y a tel péché qui ne va pas à la mort.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 18, 'Nous savons que quiconque est né de Dieu, ne pèche point; mais celui qui est né de Dieu se garde lui-même, et le Malin n\'a aucune prise sur lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 19, 'Nous savons que nous sommes de Dieu, et que le monde entier est soumis à la puissance du Malin.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 20, 'Mais nous savons que le Fils de Dieu est venu, et il nous a donné l\'intelligence nécessaire pour connaître Celui qui est le Véritable; et nous sommes dans le Véritable, en son Fils Jésus-Christ. C\'est lui qui est le Dieu véritable et la vie éternelle.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 21, 'Mes petits enfants, gardez-vous des idoles!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 1, 'L\'ancien, à la dame élue et à ses enfants que j\'aime véritablement, — et ce n\'est pas moi seul qui les aime, mais aussi tous ceux qui ont connu la vérité;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 2, 'et cela, à cause de la vérité même qui demeure en nous, et qui sera avec nous éternellement.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 3, 'Que la grâce, la miséricorde et la paix soient avec nous, de la part de Dieu, le Père, et de la part de Jésus-Christ, le Fils du Père, dans la vérité et la charité!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 4, 'J\'ai éprouvé une grande joie à trouver quelques-uns de tes enfants marchant dans la vérité, selon le commandement que nous avons reçu du Père.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 5, 'Et maintenant, dame élue, ce que je te demande, non pour te prescrire un commandement nouveau, mais pour te rappeler celui que nous avons reçu dès le commencement, c\'est que nous nous aimions les uns les autres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 6, 'Or, l\'amour consiste à suivre les commandements de Dieu. Tel est le commandement que vous avez reçu dès le commencement, afin que vous y conformiez votre conduite.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 7, 'Il s\'est répandu dans le monde beaucoup de séducteurs, qui ne confessent pas Jésus-Christ venu en chair: c\'est bien là le séducteur et l\'Antéchrist.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 8, 'Prenez garde à vous-mêmes, afin que vous ne perdiez pas le fruit de votre travail, mais que vous en receviez pleinement la récompense.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 9, 'Quiconque marche à l\'aventure et ne persévère pas dans la doctrine du Christ, n\'a point Dieu. Celui qui persévère dans cette doctrine, celui-là a le Père et le Fils.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 10, 'Si quelqu\'un vient à vous et n\'apporte pas cette doctrine, ne le recevez pas dans votre maison, et ne lui donnez pas le salut fraternel.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 11, 'Car celui qui lui donne ce salut, participe à ses mauvaises oeuvres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 12, 'J\'aurais bien des choses à vous dire: je ne veux pas le faire avec le papier et l\'encre; mais j\'espère aller vous voir et vous entretenir de vive voix, afin que notre joie soit parfaite.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 13, 'Les enfants de ta soeur, l\'élue, te saluent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 1, 'L\'ancien à Gaïus le bien-aimé, que j\'aime véritablement.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 2, 'Bien-aimé, je souhaite que tu prospères en toutes choses, et que la santé de ton corps soit aussi bonne que celle de ton âme.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 3, 'En effet, j\'ai éprouvé une grande joie en voyant arriver des frères qui ont rendu témoignage à ton attachement à la vérité, et à la manière dont tu marches dans cette vérité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 4, 'Je n\'ai pas de plus grande joie que d\'apprendre que mes enfants marchent dans la vérité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 5, 'Bien-aimé, tu agis fidèlement dans tout ce que tu fais pour les frères, et même pour des frères étrangers.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 6, 'Ils ont rendu témoignage à ta charité en présence de l\'Eglise. Tu feras bien de pourvoir à leur voyage d\'une manière digne de Dieu;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 7, 'car c\'est pour le nom de Jésus-Christ qu\'ils se sont mis en route, sans rien recevoir des Païens.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 8, 'Aussi devons-nous accueillir de tels hommes, afin que nous travaillions avec eux pour la vérité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 9, 'J\'ai écrit quelques mots à l\'Église; mais Diotrèphe, qui aime à y tenir le premier rang, ne veut pas nous recevoir.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 10, 'C\'est pourquoi, si je viens, je signalerai le mal qu\'il fait, en tenant contre nous de méchants propos. Non content de cela, il ne reçoit pas les frères; et ceux qui voudraient le faire, il les en empêche et les chasse de l\'Église.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 11, 'Bien-aimé, n\'imite pas le mal, mais imite le bien. Celui qui fait le bien, est de Dieu; celui qui fait le mal, n\'a point vu Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 12, 'Tous rendent un bon témoignage à Démétrius, et la vérité elle-même le lui rend; nous y joignons notre propre témoignage, et tu sais qu\'il est conforme à la vérité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 13, 'J\'aurais bien des choses à te dire; mais je ne veux pas le faire avec l\'encre et la plume.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 14, 'J\'espère te voir bientôt, et nous nous entretiendrons de vive voix. Que la paix soit avec toi! Les amis te saluent. Salue les amis, chacun en particulier.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 1, 'Jude, serviteur de Jésus-Christ et frère de Jacques, à ceux qui ont été appelés, qui sont aimés en Dieu, le Père, et gardés pour Jésus-Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 2, 'Que la miséricorde, la paix et l\'amour vous soient multipliés!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 3, 'Bien-aimés, comme j\'avais fort à coeur de vous écrire au sujet de notre salut commun, je me suis senti obligé de le faire, afin de vous exhorter à combattre pour la foi qui a été jadis transmise aux saints.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 4, 'En effet, il s\'est glissé parmi nous certains hommes, dont la condamnation est écrite depuis longtemps, des impies qui font servir à leurs désordres la grâce de notre Dieu, et qui renient notre seul Maître et Seigneur, Jésus-Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 5, 'Je veux vous rappeler, bien que vous soyez déjà instruits de tout cela, que le Seigneur, ayant délivré son peuple du pays d\'Egypte, détruisit ensuite ceux qui furent incrédules;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 6, 'qu\'il a réservé pour le jugement du grand jour, enchaînés éternellement dans les ténèbres, les anges qui n\'ont pas gardé leur rang et qui ont abandonné leur propre demeure;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 7, 'que Sodome et Gomorrhe, et les villes voisines qui se livrèrent aux mêmes impuretés et à des vices contre nature, sont placées devant nous comme un exemple, subissant la peine d\'un feu éternel.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 8, 'Cependant les hommes dont je parle les imitent; dans leurs rêveries, ils souillent leur chair, méprisent l\'autorité souveraine et profèrent des injures contre les Gloires.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 9, 'Or, l\'archange Michel lui-même, lorsqu\'il contestait avec le Diable et lui disputait le corps de Moïse, n\'osa pas prononcer contre lui une sentence injurieuse; il dit seulement: Que le Seigneur te punisse!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 10, 'Mais ceux-ci injurient tout ce qu\'ils ignorent; et les choses elles-mêmes qu\'ils connaissent naturellement comme les bêtes privées de raison, ils les font tourner à leur propre perte.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 11, 'Malheur à eux, car ils ont suivi la voie de Caïn! Ils se sont jetés, par amour du gain, dans l\'égarement de Balaam; ils se sont perdus par la révolte de Coré.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 12, 'Ces gens-là font tache dans vos agapes, où ils ne songent qu\'à faire bonne chère et à se repaître sans pudeur. Nuées sans eau, emportées çà et là par les vents! Arbres flétris par l\'automne, sans fruits, deux fois morts, déracinés!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 13, 'Vagues furieuses de la mer, qui jettent l\'écume de leurs impuretés! Astres errants, auxquels l\'obscurité des ténèbres est réservée pour l\'éternité!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 14, 'C\'est pour eux aussi qu\'a prophétisé Enoch, le septième patriarche depuis Adam, quand il a dit: Voici que le Seigneur est venu avec ses saintes myriades,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 15, 'pour exercer le jugement contre tous, et pour convaincre tous les impies de toutes les oeuvres d\'impiété qu\'ils ont commises et de toutes les paroles insultantes que ces pécheurs impies ont proférées contre lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 16, 'Ce sont des mécontents qui se plaignent sans cesse de leur sort, qui vivent suivant leurs convoitises, qui ont la bouche pleine de discours arrogants, et qui flattent les autres dans des vues intéressées.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 17, 'Mais vous, bien-aimés, souvenez-vous de ce qui a été prédit par les apôtres de notre Seigneur Jésus-Christ.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 18, 'Ils vous disaient que, dans les derniers temps, il y aurait des moqueurs, vivant au gré de leurs convoitises impies.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 19, 'Ce sont eux qui provoquent des divisions, êtres sensuels, étrangers à la vie de l\'Esprit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 20, 'Pour vous, bien-aimés, vous édifiant vous-mêmes sur le fondement de votre très sainte foi, et priant par le Saint-Esprit,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 21, 'maintenez-vous dans l\'amour de Dieu, attendant de la miséricorde de notre Seigneur Jésus-Christ, la vie éternelle.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 22, 'Reprenez, les uns, ceux qui sont hésitants;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 23, 'sauvez-en, d\'autres, en les arrachant du feu; pour d\'autres encore, ayez une pitié mêlée de crainte, haïssant jusqu\'au vêtement souillé par la chair.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 24, 'Or, à celui qui peut vous préserver de toute chute et vous faire paraître irréprochables et joyeux en sa glorieuse présence,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 25, 'au Dieu unique, notre Sauveur par Jésus-Christ notre Seigneur, soient gloire, grandeur, force et puissance, de toute éternité, maintenant et dans tous les siècles! Amen.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 1, 'Révélation de Jésus-Christ, que Dieu lui a donnée pour montrer à ses serviteurs les choses qui doivent arriver bientôt: il les a fait connaître en envoyant son ange à Jean, son serviteur,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 2, 'qui a annoncé la parole de Dieu et le témoignage de Jésus-Christ, et toutes les choses qu\'il a vues.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 3, 'Heureux celui qui lit et ceux qui entendent la parole de cette prophétie, et qui observent ce qui s\'y trouve écrit! Car le temps est proche.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 4, 'Jean, aux sept Églises d\'Asie. Que la grâce et la paix vous soient données de la part de celui qui est, qui était, et qui vient, de la part des sept esprits qui sont devant son trône,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 5, 'et de la part de Jésus-Christ, le témoin fidèle, le premier-né d\'entre les morts, le prince des rois de la terre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 6, 'A celui qui nous aime, qui nous a lavés de nos péchés par son sang, et qui nous a faits rois et sacrificateurs pour Dieu son Père, à lui soient la gloire et la force, aux siècles des siècles! Amen.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 7, 'Le voici qui vient au milieu des nuées! Tout oeil le verra, même ceux qui l\'ont percé; et toutes les tribus de la terre se lamenteront à cause de lui. Oui, amen!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 8, 'Je suis l\'Alpha et l\'Oméga, dit le Seigneur Dieu, celui qui est, qui était, et qui vient, le Tout-Puissant!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 9, 'Moi Jean, qui suis votre frère et votre compagnon d\'affliction, de royauté et de patience en Jésus, j\'étais dans l\'île appelée Patmos, à cause de la parole de Dieu et du témoignage de Jésus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 10, 'Je fus ravi en esprit, le jour du Seigneur, et j\'entendis derrière moi une voix éclatante, pareille au son d\'une trompette,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 11, 'qui disait: Ce que tu vois, écris-le dans un livre, et envoie-le aux sept Églises, à Éphèse, à Smyrne, à Pergame, à Thyatire, à Sardes, à Philadelphie et à Laodicée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 12, 'Alors je me retournai pour savoir quelle était la voix qui me parlait; et, m\'étant retourné, je vis sept chandeliers d\'or,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 13, 'et au milieu des chandeliers, quelqu\'un qui ressemblait à un fils d\'homme, vêtu d\'une longue robe, et ceint à la hauteur de la poitrine d\'une ceinture d\'or.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 14, 'Sa tête et ses cheveux étaient blancs comme de la laine blanche, comme de la neige; ses yeux étaient comme une flamme de feu;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 15, 'ses pieds étaient semblables à de l\'airain rougi dans une fournaise, et sa voix était comme le bruit des grosses eaux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 16, 'Il avait dans sa main droite sept étoiles; de sa bouche sortait une épée aiguë à deux tranchants, et son visage était comme le soleil, quand il brille dans sa force.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 17, 'En le voyant, je tombai à ses pieds comme mort; mais il posa sa main droite sur moi, et il me dit: Ne crains point. Je suis le premier et le dernier, le Vivant!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 18, 'J\'ai été mort, mais je suis vivant aux siècles des siècles; et je tiens les clefs de la mort et du Sépulcre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 19, 'Écris donc les choses que tu as vues, celles qui sont et celles qui doivent arriver après celles-ci,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 20, 'le mystère des sept étoiles que tu as vues dans ma main droite, et des sept chandeliers d\'or. Les sept étoiles sont les anges des sept Églises, et les sept chandeliers sont les sept Églises.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 1, 'Écris à l\'ange de l\'Église d\'Éphèse: Voici ce que dit celui qui tient les sept étoiles dans sa main droite, celui qui marche au milieu des sept chandeliers d\'or:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 2, 'Je connais tes oeuvres, et ton labeur, et ta patience. Je sais que tu ne peux souffrir les méchants, que tu as mis à l\'épreuve ceux qui se disent apôtres et ne le sont pas, et que tu les as trouvés menteurs.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 3, 'Tu as de la patience; tu as souffert pour mon nom, et tu ne t\'es point lassé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 4, 'Mais ce que j\'ai contre toi, c\'est que tu as abandonné ton premier amour.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 5, 'Souviens-toi donc de l\'état duquel tu es déchu, repens-toi, et fais de nouveau tes premières oeuvres. Sinon, je viendrai à toi, et j\'ôterai ton chandelier de sa place, si tu ne te repens point.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 6, 'Cependant, tu as ceci de bon, c\'est que tu hais les oeuvres des Nicolaïtes, que je hais, moi aussi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 7, 'Que celui qui a des oreilles, entende ce que l\'Esprit dit aux Églises: A celui qui vaincra, je donnerai à manger de l\'arbre de vie, qui est dans le paradis de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 8, 'Écris aussi à l\'ange de l\'Église de Smyrne: Voici ce que dit le Premier et le Dernier, celui qui a été mort et qui est revenu à la vie:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 9, 'je connais ton affliction, ta pauvreté, — bien que tu sois riche, — et les calomnies de ceux qui se disent Juifs et qui ne le sont pas, mais qui sont une synagogue de Satan.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 10, 'Ne crains point ce que tu auras à souffrir. Voici que le Diable va jeter en prison plusieurs d\'entre vous, afin que vous soyez mis à l\'épreuve; et vous aurez une affliction de dix jours. Sois fidèle jusqu\'à la mort, et jeté donnerai la couronne de vie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 11, 'Que celui qui a des oreilles, entende ce que l\'Esprit dit aux Églises: Celui qui vaincra n\'aura rien à souffrir de la seconde mort.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 12, 'Écris aussi à l\'ange de l\'Église de Pergame: Voici ce que dit celui qui tient le glaive aigu à deux tranchants:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 13, 'Je sais où tu habites; c\'est là qu\'est le trône de Satan. Tu es fermement attaché à mon nom; tu n\'as point renié ma foi, même dans ces jours où Antipas, mon fidèle témoin, fut mis à mort chez vous, là où Satan habite.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 14, 'Mais j\'ai quelque chose contre toi; tu as là des gens attachés à la doctrine de Balaam, qui enseignait à Balac à mettre une pierre d\'achoppement devant les fils d\'Israël, pour leur faire manger des viandes sacrifiées aux idoles et les entraîner dans l\'impureté.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 15, 'De même aussi, tu as des gens qui s\'attachent à la doctrine des Nicolaïtes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 16, 'Repens-toi donc; autrement je viendrai bientôt à toi, et je combattrai contre eux avec le glaive de ma bouche.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 17, 'Que celui qui a des oreilles, entende ce que l\'Esprit dit aux Églises: A celui qui vaincra, je donnerai de la manne cachée, et je lui donnerai un caillou blanc, et sur ce caillou est écrit un nouveau nom, que personne ne connaît, excepté celui qui le reçoit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 18, 'Écris aussi à l\'ange de l\'Église de Thyatire: Voici ce que dit le Fils de Dieu, celui qui a les yeux comme une flamme de feu, et dont les pieds sont semblables à de l\'airain brillant:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 19, 'Je connais tes oeuvres, ton amour, ta foi, ton fidèle service, ta patience et tes dernières oeuvres, plus nombreuses que les premières.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 20, 'Mais ce que j\'ai contre toi, c\'est que tu laisses faire Jezabel, cette femme qui se dit prophétesse, qui enseigne, et qui séduit mes serviteurs, pour les entraîner dans l\'impureté et leur faire manger des viandes sacrifiées aux idoles.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 21, 'Je lui ai donné du temps pour se repentir; mais elle ne veut pas se repentir de son impureté!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 22, 'Voici que je vais la jeter sur un lit de souffrance, et plonger dans une grande affliction ceux qui commettent l\'adultère avec elle, s\'ils ne se repentent pas d\'imiter ses actions.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 23, 'Je frapperai de mort ses enfants; toutes les Églises connaîtront que je suis celui qui sonde les reins et les coeurs; et je rendrai à chacun de vous selon ses oeuvres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 24, 'Mais à tous les autres, à vous, fidèles de Thyatire, qui n\'acceptez pas cette doctrine et qui n\'avez pas connu les profondeurs de Satan, comme ils disent, je déclare que je ne vous impose pas d\'autre charge.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 25, 'Seulement, tenez ferme ce que vous avez, jusqu\'à ce que je vienne.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 26, 'A celui qui vaincra et qui accomplira mes oeuvres jusqu\'à la fin, je donnerai tout pouvoir sur les nations:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 27, 'il gouvernera avec un sceptre de fer, et il les brisera comme des vases d\'argile, ainsi que j\'en ai moi-même reçu le pouvoir de mon Père.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 28, 'Je lui donnerai aussi l\'étoile du matin.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 29, 'Que celui qui a des oreilles entende ce que l\'Esprit dit aux Églises!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 1, 'Écris aussi à l\'ange de l\'Église de Sardes: Voici ce que dit celui qui a les sept esprits de Dieu et les sept étoiles: Je connais tes oeuvres; tu as la réputation d\'être vivant, mais tu es mort.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 2, 'Sois vigilant, et affermis le reste qui est près de mourir; car je n\'ai pas trouvé tes oeuvres parfaites devant mon Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 3, 'Rappelle-toi donc comment tu as reçu et entendu la parole; garde-la, et repens-toi! Si tu ne veilles pas, je viendrai comme un voleur, et tu ne sauras pas à quelle heure je viendrai te surprendre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 4, 'Toutefois, tu as à Sardes quelques personnes qui n\'ont pas souillé leurs vêtements: elles marcheront avec moi en vêtements blancs; car elles en sont dignes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 5, 'Celui qui vaincra, sera ainsi revêtu de vêtements blancs. Je n\'effacerai pas son nom du livre de vie, et je confesserai son nom devant mon Père et devant ses anges.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 6, 'Que celui qui a des oreilles, entende ce que l\'Esprit dit aux Églises!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 7, 'Écris aussi à l\'ange de l\'Église de Philadelphie: Voici ce que dit le Saint, le Véritable, celui qui a la clef de David, celui qui ouvre, — et personne ne fermera, — qui ferme, — et personne n\'ouvrira —:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 8, 'Je connais tes oeuvres. J\'ai ouvert devant toi une porte que personne ne peut fermer; parce que toi, qui as peu de force, tu as gardé ma parole et n\'as point renié mon nom.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 9, 'Je te livre quelques-uns de ceux de la synagogue de Satan, qui se disent juifs et qui ne le sont pas, mais qui mentent; et je les ferai venir pour qu\'ils se prosternent à tes pieds, et qu\'ils sachent que je t\'ai aimé.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 10, 'Parce que tu as gardé ma parole avec patience, je te garderai aussi de l\'heure de l\'épreuve, qui va venir sur le monde entier, pour éprouver les habitants de la terre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 11, 'Je viens bientôt! Tiens ferme ce que tu as, afin que personne ne prenne ta couronne.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 12, 'Celui qui vaincra, je ferai de lui une colonne dans le temple de mon Dieu, et il n\'en sortira plus. J\'écrirai sur lui le nom de mon Dieu, et le nom de la cité de mon Dieu, de la nouvelle Jérusalem, qui descend du ciel, d\'auprès de mon Dieu, ainsi que mon nouveau nom.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 13, 'Que celui qui a des oreilles, entende ce que l\'Esprit dit aux Églises!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 14, 'Écris aussi à l\'ange de l\'Église de Laodicée: Voici ce que dit l\'Amen, le témoin. fidèle et véritable, le principe de la création de Dieu:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 15, 'Je connais tes oeuvres; tu n\'es ni froid ni bouillant. Plût à Dieu que tu fusses froid ou bouillant!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 16, 'Ainsi, parce que tu es tiède et que tu n\'es ni bouillant ni froid, je te vomirai de ma bouche.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 17, 'En effet, tu dis: Je suis riche, je me suis enrichi, et je n\'ai besoin de rien. Et tu ne sais pas que tu es malheureux, et misérable, et pauvre, et aveugle et nu!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 18, 'Je te conseille d\'acheter de moi de l\'or éprouvé par le feu, afin que tu deviennes riche; des vêtements blancs, afin que tu sois vêtu et que la honte de ta nudité ne paraisse point; et un collyre pour oindre tes yeux, afin que tu voies.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 19, 'Je reprends et je châtie tous ceux que j\'aime; aie donc du zèle, et repens-toi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 20, 'Me voici! Je me tiens à la porte, et je frappe; si quelqu\'un entend ma voix et m\'ouvre la porte, j\'entrerai chez lui, je souperai avec lui, et lui avec moi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 21, 'Celui qui vaincra, je le ferai asseoir avec moi sur mon trône, comme moi-même j\'ai vaincu et me suis assis avec mon Père sur son trône.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 22, 'Que celui qui à des oreilles, entende ce que l\'Esprit dit aux Églises!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 1, 'Après cela, je regardai, et voici qu\'une porte était ouverte dans le ciel; et la première voix que j\'avais entendue me parler comme si c\'était le son d\'une trompette, me dit: Monte ici, et je te ferai voir ce qui doit arriver dans la suite.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 2, 'Aussitôt, je fus ravi en esprit; je vis un trône dressé dans le ciel, et sur ce trône quelqu\'un était assis.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 3, 'Celui qui était assis avait l\'éclat d\'une pierre de jaspe et de sardoine; et le trône était environné d\'un arc-en-ciel ayant un aspect semblable à celui de l\'émeraude.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 4, 'Autour de ce trône, il y avait vingt-quatre trônes; et sur ces trônes, je vis vingt-quatre vieillards assis, vêtus de vêtements blancs, et sur leurs têtes des couronnes d\'or.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 5, 'Du trône sortent des éclairs, des voix et des tonnerres; et sept lampes ardentes brûlent devant le trône: ce sont les sept esprits de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 6, 'Devant le trône il y a comme une mer transparente, semblable à du cristal, et au milieu du trône et autour du trône, quatre animaux ayant des yeux partout, devant et derrière.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 7, 'Le premier animal ressemble à un lion; le second ressemble à un taureau; le troisième a le visage semblable à celui d\'un homme; et le quatrième ressemble à un aigle qui vole.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 8, 'Ces quatre animaux ont chacun six ailes, et sont couverts d\'yeux tout à l\'entour et au-dedans; et ils ne cessent de dire, jour et nuit: Saint, saint, saint est le Seigneur Dieu, le Tout-Puissant, qui était, qui est, et qui vient!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 9, 'Pendant que les animaux rendent gloire, honneur et actions de grâces à celui qui est assis sur le trône, et qui vit aux siècles des siècles, —');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 10, 'les vingt-quatre vieillards se prosternent devant Celui qui est assis sur le trône, et adorent Celui qui vit aux siècles des siècles; et ils jettent leurs couronnes devant le trône, en disant:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 11, 'Tu es digne, toi, notre Seigneur et notre Dieu, de recevoir la gloire, l\'honneur et la puissance; car tu as créé toutes choses, et c\'est par ta volonté qu\'elles existent et qu\'elles ont été créées.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 1, 'Puis je vis, dans la main droite de celui qui était assis sur le trône, un livre écrit en dedans et en dehors, scellé de sept sceaux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 2, 'Je vis aussi un ange puissant, qui criait d\'une voix forte: Qui est digne d\'ouvrir le livre et d\'en rompre les sceaux?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 3, 'Mais il n\'y avait personne, ni dans le ciel, ni sur la terre, ni sous la terre, qui pût ouvrir le livre, ni le regarder.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 4, 'Et je pleurais beaucoup, parce qu\'il ne s\'était trouvé personne qui fût digne d\'ouvrir le livre, ni de le regarder.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 5, 'Alors l\'un des vieillards me dit: Ne pleure pas! Voici qu\'il a vaincu, le lion de la tribu de Juda, le rejeton de David: il a le pouvoir d\'ouvrir le livre et d\'en rompre les sept sceaux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 6, 'Puis je vis, au milieu du trône et des quatre animaux et au milieu des vieillards, un Agneau qui était là comme immolé; il avait sept cornes et sept yeux, qui sont les sept esprits de Dieu envoyés par toute la terre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 7, 'Il s\'avança et prit le livre de la main droite de Celui qui était assis sur le trône.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 8, 'Et quand il prit le livre, les quatre animaux et les vingt-quatre vieillards se prosternèrent devant l\'Agneau, ayant chacun une harpe et des coupes d\'or pleines de parfum: ce sont les prières des saints.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 9, 'Ils chantaient un cantique nouveau, et ils disaient: Tu es digne de prendre le livre et d\'en ouvrir les sceaux; car tu as été immolé, et tu as racheté pour Dieu, par ton sang, des hommes de toute tribu, de toute langue, de tout peuple et de toute nation.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 10, 'Tu les as faits rois et sacrificateurs pour notre Dieu; et ils régneront sur la terre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 11, 'Puis je regardai, et j\'entendis, autour du trône, autour des animaux et des vieillards, la voix d\'une multitude d\'anges. Il y en avait des myriades de myriades, des milliers de milliers,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 12, 'qui disaient d\'une voix forte: L\'Agneau qui a été immolé est digne de recevoir la puissance, la richesse, la sagesse, la force, l\'honneur, la gloire et la louange!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 13, 'J\'entendis aussi toutes les créatures, dans le ciel, sur la terre, sous la terre, sur la mer, et toutes les choses qui s\'y trouvent, qui disaient: A celui qui est assis sur le trône et à l\'Agneau, soient la louange, l\'honneur, la gloire et la force, aux siècles des siècles!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 14, 'Et les quatre animaux disaient: Amen! Alors les vieillards se prosternèrent et adorèrent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 1, 'Je regardai, quand l\'Agneau ouvrit le premier des sept sceaux, et j\'entendis l\'un des quatre animaux qui disait d\'une voix de tonnerre: Viens!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 2, 'Je regardai, et je vis un cheval blanc. Celui qui le montait avait un arc; on lui donna une couronne, et il partit en vainqueur, pour remporter la victoire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 3, 'Quand l\'Agneau ouvrit le deuxième sceau, j\'entendis le deuxième animal qui disait: Viens!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 4, 'Alors il parut un autre cheval, qui était roux. Celui qui le montait reçut le pouvoir d\'ôter de la terre la paix, afin que les hommes fussent entraînés à s\'égorger les uns les autres; on lui donna une grande épée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 5, 'Quand l\'Agneau ouvrit le troisième sceau, j\'entendis le troisième animal qui disait: Viens! Je regardai, et je vis un cheval noir. Celui qui le montait avait une balance à la main.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 6, 'Puis j\'entendis, au milieu des quatre animaux, comme une voix qui disait: Une mesure de froment pour un denier! Trois mesures d\'orge pour un denier! Et ne touche ni à l\'huile, ni au vin.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 7, 'Quand l\'Agneau ouvrit le quatrième sceau, j\'entendis la voix du quatrième animal, qui disait: Viens!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 8, 'Je regardai et je vis paraître un cheval jaunâtre. Celui qui le montait se nommait la Mort, et le Sépulcre le suivait. On leur donna pouvoir sur le quart de la terre, pour en faire périr les habitants par l\'épée, par la famine, par la mortalité, et par les bêtes féroces de la terre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 9, 'Quand l\'Agneau ouvrit le cinquième sceau, je vis sous l\'autel les âmes de ceux qui avaient été immolés pour la parole de Dieu et pour le témoignage qu\'ils avaient rendu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 10, 'Ils crièrent d\'une voix forte, et ils dirent: Jusques à quand, ô Maître saint et véritable, différeras-tu de juger, et de venger notre sang sur ceux qui habitent la terre?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 11, 'Alors on leur donna à chacun une robe blanche, et on leur dit de demeurer en repos encore un peu de temps, jusqu\'à ce que fût au complet le nombre de leurs compagnons de service et de leurs frères, qui devaient être mis à mort comme eux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 12, 'Je regardai, lorsque l\'Agneau ouvrit le sixième sceau; et il se fit un grand tremblement de terre. Le soleil devint noir comme un sac de crin, et la lune tout entière devint comme du sang.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 13, 'Les étoiles du ciel tombèrent sur la terre, comme les fruits verts que laisse tomber un figuier secoué par un grand vent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 14, 'Le ciel se retira comme un livre qu\'on roule; toutes les montagnes et toutes les îles furent jetées hors de leurs places.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 15, 'Les rois de la terre, les grands, les capitaines, les riches, les puissants, tous les esclaves et tous les hommes libres, se cachèrent dans les cavernes et dans les rochers des montagnes;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 16, 'et ils dirent aux montagnes et aux rochers: Tombez sur nous; dérobez-nous à la vue de Celui qui est assis sûr le trône, et à la colère de l\'Agneau!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 17, 'Car il est venu, le grand jour de sa colère! Et qui pourrait subsister?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 1, 'Après cela, je vis quatre anges, debout aux quatre coins de la terre, qui retenaient les quatre vents, afin qu\'il ne soufflât aucun vent sur la terre, ni sur la mer, ni sur aucun arbre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 2, 'Je vis aussi un autre ange qui montait du côté du soleil levant, et qui tenait le sceau du Dieu vivant. Il cria d\'une voix forte aux quatre anges qui avaient reçu le pouvoir de faire du mal à la terre et à la mer;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 3, 'et il leur dit: Ne faites point de mal à la terre, ni à la mer, ni aux arbres, jusqu\'à ce que nous ayons posé le sceau sur le front des serviteurs de notre Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 4, 'Puis j\'entendis annoncer le nombre de ceux qui avaient été marqués: cent quarante-quatre mille étaient marqués parmi toutes les tribus des fils d\'Israël.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 5, 'De la tribu de Juda, douze mille étaient marqués; de la tribu de Ruben, douze mille; de la tribu de Gad, douze mille;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 6, 'de la tribu d\'Asser, douze mille; de la tribu de Nephthali, douze mille; de la tribu de Manassé, douze mille;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 7, 'de la tribu de Siméon, douze mille; de la tribu de Lévi, douze mille; de la tribu d\'Issacar, douze mille;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 8, 'de la tribu de Zabulon, douze mille; de la tribu de Joseph, douze mille; de la tribu de Benjamin, douze mille, tous marqués du sceau.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 9, 'Après cela, je regardai, et je vis une grande multitude, que personne ne pouvait compter, de toute nation, de toute tribu, de tout peuple et de toute langue. Ils se tenaient devant le trône et devant l\'Agneau, vêtus de robes blanches, des palmes à la main,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 10, 'et ils criaient d\'une voix forte et disaient: Le salut appartient à notre Dieu, qui est assis sur le trône, et à l\'Agneau.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 11, 'Tous les anges se tenaient en cercle autour du trône, autour des vieillards, et des quatre animaux. Ils se prosternèrent sur leurs visages, devant le trône, et adorèrent Dieu');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 12, 'en disant Amen! Louange, gloire, sagesse, actions de grâces, honneurs, puissance et force soient à notre Dieu, aux siècles des siècles! Amen!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 13, 'Alors un des vieillards prit la parole et me dit: Ceux qui sont revêtus de robes blanches, qui sont-ils, et d\'où sont-ils venus?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 14, 'Je lui répondis: Mon Seigneur, tu le sais! Il me dit: Ce sont ceux qui viennent de la grande tribulation; ils ont lavé leurs robes et ils les ont blanchies dans le sang de l\'Agneau.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 15, 'C\'est pour cela qu\'ils sont devant le trône de Dieu, et qu\'ils le servent jour et nuit dans son temple; et celui qui est assis sur le trône, les abritera sous sa tente.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 16, 'Ils n\'auront plus faim; ils n\'auront plus soif; ni le soleil, ni la chaleur ardente ne les frappera plus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 17, 'Car l\'Agneau qui est au milieu du trône les paîtra, et il les conduira aux sources des eaux vives; et Dieu essuiera toute larme de leurs yeux!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 1, 'Quand l\'Agneau ouvrit le septième sceau, il se fit dans le ciel un silence d\'environ une demi-heure.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 2, 'Alors je vis les sept anges qui se tiennent devant Dieu, et on leur donna sept trompettes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 3, 'Puis il vint un autre ange, qui se tint près de l\'autel: il avait un encensoir d\'or, et on lui donna beaucoup de parfums pour les offrir, avec les prières de tous les saints, sur l\'autel d\'or qui est devant le trône.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 4, 'Et la fumée des parfums s\'éleva de la main de l\'ange, devant Dieu, avec les prières des saints.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 5, 'L\'ange prit l\'encensoir, le remplit du feu de l\'autel, et le jeta sur la terre: il y eut des tonnerres, des voix, des éclairs, et la terre trembla.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 6, 'Alors les sept anges, qui avaient les sept trompettes, se préparèrent à en sonner.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 7, 'Le premier sonna de la trompette; et il y eut de la grêle et du feu mêlés de sang, qui furent jetés sur la terre. Le tiers de la terre fut brûlé; le tiers des arbres fut brûlé; toute herbe verte fut aussi brûlée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 8, 'Le second ange sonna de la trompette; et une masse, pareille à une grande montagne toute en feu, fut jetée dans la mer. Le tiers de la mer devint du sang;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 9, 'le tiers des créatures vivantes qui étaient dans la mer mourut, et le tiers des navires fut détruit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 10, 'Le troisième ange sonna de la trompette; et il tomba du ciel une grande étoile, enflammée comme une torche; elle tomba sur le tiers des fleuves et sur les sources d\'eau.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 11, 'Le nom de cette étoile est Absinthe. Le tiers des eaux fut changé en absinthe, et ces eaux firent périr un grand nombre d\'hommes, parce qu\'elles étaient devenues amères.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 12, 'Le quatrième ange sonna de la trompette; et le tiers du soleil fut frappé, ainsi que le tiers de la lune et le tiers des étoiles, en sorte que le tiers de ces astres fut rendu obscur, et que le jour perdit le tiers de sa clarté, aussi bien que la nuit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 13, 'Alors je regardai, et j\'entendis un aigle qui volait au milieu du ciel, disant d\'une voix forte: Malheur! Malheur! Malheur aux habitants de la terre, à cause du son des trompettes que les trois autres anges doivent encore faire entendre!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 1, 'Le cinquième ange sonna de la trompette; et je vis une étoile qui était tombée du ciel sur la terre, et la clef du puits de l\'abîme lui fut donnée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 2, 'Elle ouvrit le puits de l\'abîme, et il monta du puits une fumée, comme la fumée d\'une grande fournaise; et le soleil et l\'air furent obscurcis par la fumée du puits.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 3, 'De cette fumée il sortit des sauterelles, qui se répandirent sur la terre; et on leur donna un pouvoir semblable à celui qu\'ont les scorpions de la terre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 4, 'Il leur fut commandé de ne faire de mal ni à l\'herbe de la terre, ni à aucune verdure, ni à aucun arbre, mais seulement aux hommes qui n\'avaient pas le sceau de Dieu sur leur front.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 5, 'Il leur fut donné, non de les tuer, mais de les tourmenter pendant cinq mois, et ce tourment ressemblait au tourment que cause à l\'homme la piqûre du scorpion.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 6, 'En ces jours-là, les hommes chercheront la mort et ils ne la trouveront pas; ils désireront mourir, et la mort fuira loin d\'eux!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 7, 'Ces sauterelles ressemblaient à des chevaux préparés pour le combat: sur leur tête, il y avait comme des couronnes qui semblaient être en or, et leurs visages étaient comme des visages d\'hommes;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 8, 'elles avaient des chevelures semblables à celles des femmes, et leurs dents étaient comme des dents de lions.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 9, 'Elles avaient des cuirasses pareilles à des cuirasses de fer; et le bruit de leurs ailes était comme le bruit de plusieurs chars à plusieurs chevaux qui courent au combat.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 10, 'Elles avaient des queues armées de dards, comme des scorpions, et c\'est dans ces queues que se trouvait leur pouvoir de nuire aux hommes pendant cinq mois.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 11, 'Elles avaient à leur tête un roi, l\'ange de l\'abîme, appelé en hébreu Abaddon, et en grec Apollyon.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 12, 'Le premier «Malheur» est passé; en voici encore deux autres qui viennent après celui-là.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 13, 'Le sixième ange sonna de la trompette; et j\'entendis une voix qui venait des quatre cornes de l\'autel d\'or, placé devant Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 14, 'Elle disait au sixième ange qui avait la trompette: Délie les quatre anges, enchaînés au bord du grand fleuve de l\'Euphrate.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 15, 'Alors furent déliés les quatre anges, qui étaient prêts pour l\'heure, le jour, le mois et l\'année, afin qu\'ils fissent périr le tiers des hommes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 16, 'Le nombre des cavaliers de l\'armée était de deux cents millions; j\'en entendis le nombre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 17, 'Et voici comment, dans la vision, je vis les chevaux et ceux qui les montaient: ceux-ci avaient des cuirasses couleur de feu, d\'hyacinthe et de soufre; les têtes des chevaux étaient comme des têtes de lions, et de leurs bouches il sortait du feu, de la fumée et du soufre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 18, 'Le tiers des hommes fut tué par ces fléaux, par le feu, par la fumée et par le soufre qui sortaient de leur bouche.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 19, 'Car le pouvoir de ces chevaux est dans leurs bouches et dans leurs queues; ces queues ressemblent à des serpents; elles ont des têtes, au moyen desquelles elles font du mal.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 20, 'Les autres hommes qui n\'avaient pas été tués par ces fléaux, ne se repentirent pas des oeuvres de leurs mains, et ils ne cessèrent pas d\'adorer les démons et les idoles d\'or, d\'argent, d\'airain, de pierre et de bois, qui ne peuvent ni voir, ni entendre, ni marcher.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 21, 'Ils ne se repentirent ni de leurs meurtres, ni de leurs maléfices, ni de leurs impuretés, ni de leurs rapines.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 1, 'Puis, je vis descendre du ciel un autre ange plein de force, qui était enveloppé d\'un nuage. Au-dessus de sa tête était l\'arc-en-ciel; son visage était comme le soleil, et ses pieds comme des colonnes de feu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 2, 'Il tenait à la main un petit livre ouvert: il posa son pied droit sur la mer, le gauche sur la terre,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 3, 'et il jeta un grand cri, pareil au rugissement d\'un lion; quand il eut jeté ce cri, les sept tonnerres firent entendre leurs voix.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 4, 'Quand les sept tonnerres eurent fait entendre leurs voix, j\'allais écrire, mais j\'entendis une voix venant du ciel, qui disait: Tiens secrètes les choses que les sept tonnerres ont dites, et ne les écris point.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 5, 'Alors l\'ange, que j\'avais vu debout sur la mer et sur la terre, leva sa main droite vers le ciel');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 6, 'et il jura — par Celui qui vit aux siècles des siècles, qui a créé le ciel et les choses qui y sont, la terre et tout ce qu\'elle renferme, la mer et les choses qui s\'y trouvent, — qu\'il n\'y aurait plus aucun délai;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 7, 'mais qu\'aux jours où le septième ange ferait entendre sa voix et sonnerait de la trompette, le mystère de Dieu s\'accomplirait, comme il l\'avait annoncé à ses serviteurs, les prophètes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 8, 'La voix que j\'avais entendue venant du ciel, me parla encore et me dit: Va, prends le petit livre ouvert, dans la main de l\'ange qui se tient debout sur la mer et sur la terre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 9, 'J\'allai donc vers l\'ange, et je lui demandai de me donner le petit livre. Il me dit: Prends-le et dévore-le! Il sera amer à tes entrailles; mais dans ta bouche il sera doux comme du miel.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 10, 'Je pris le petit livre de la main de l\'ange, et je le dévorai. Dans ma bouche il fut doux comme du miel; mais quand je l\'eus dévoré, je ressentis de l\'amertume dans mes entrailles.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 11, 'Puis on me dit: Il faut que tu prophétises encore au sujet de beaucoup de peuples, de nations, de langues et de rois.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 1, 'Alors on me donna un roseau semblable à un bâton, et l\'on me dit: Lève-toi, mesure le temple de Dieu, l\'autel, et ceux qui adorent dans le temple.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 2, 'Quant au parvis extérieur du temple, laisse-le en dehors, et ne le mesure pas; car il est abandonné aux Païens, qui fouleront aux pieds la cité sainte pendant quarante-deux mois.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 3, 'Je donnerai à mes deux témoins mission de prophétiser; et ils prophétiseront, revêtus de sacs, pendant douze cent soixante jours.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 4, 'Ces témoins sont les deux oliviers et les deux chandeliers, qui se tiennent devant le Seigneur de la terre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 5, 'Et si quelqu\'un veut leur faire du mal, il sort de leur bouche un feu qui dévore leurs ennemis: ainsi doit périr celui qui veut leur faire du mal.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 6, 'Ils ont le pouvoir de fermer le ciel, afin qu\'il ne tombe pas de pluie pendant les jours de leur prophétie; ils ont aussi le pouvoir de changer l\'eau en sang et de frapper la terre de toutes sortes de plaies, toutes les fois qu\'ils le voudront.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 7, 'Quand ils auront achevé de rendre leur témoignage, la bête qui monte de l\'abîme leur fera la guerre; elle les vaincra et les tuera.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 8, 'Et leurs cadavres resteront sur la place de la grande cité, qui est appelée allégoriquement Sodome et Egypte, où leur Seigneur aussi a été crucifié.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 9, 'Des hommes de tout peuple, de toute tribu, de toute langue et de toute nation, verront leurs cadavres pendant trois jours et demi, et ils ne permettront pas que ces cadavres soient mis dans le tombeau.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 10, 'Les habitants de la terre se réjouiront à leur sujet; ils seront dans l\'allégresse, et ils s\'enverront des présents les uns aux autres, parce que ces deux prophètes auront tourmenté les habitants de la terre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 11, 'Mais, après ces trois jours et demi, un esprit de vie, venant de Dieu, entra en eux: ils se relevèrent sur leurs pieds, et une grande crainte s\'empara de ceux qui les regardaient.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 12, 'Ils entendirent une voix forte qui venait du ciel, et qui leur dit: Montez ici! Ils montèrent au ciel dans la nuée, et leurs ennemis les virent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 13, 'A cette même heure, il se fit un grand tremblement de terre. La dixième partie de la ville tomba; sept mille hommes périrent dans ce tremblement de terre, et les autres, saisis d\'effroi, donnèrent gloire au Dieu du ciel.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 14, 'Le second «Malheur» est passé; voici que le troisième «Malheur» vient bientôt!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 15, 'Le septième ange sonna de la trompette; de grandes voix se firent entendre dans le ciel, et elles disaient: L\'empire du monde appartient désormais à notre Seigneur et à son Christ, et il régnera aux siècles des siècles.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 16, 'Puis les vingt-quatre vieillards, qui sont devant Dieu, sur leurs trônes, se prosternèrent sur leurs visages et adorèrent Dieu,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 17, 'en disant: Nous te rendons grâces. Seigneur, Dieu tout-puissant, — toi qui es, et qui étais, — de ce que tu as pris en main ta puissance souveraine, et de ce que tu es entré dans ton règne.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 18, 'Les nations s\'étaient irritées; mais ta colère est venue! Il est venu, le moment de juger les morts, de donner leur récompense à tes serviteurs, les prophètes, aux saints, à ceux qui craignent ton nom, aux petits et aux grands, et de détruire ceux qui détruisent la terre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 19, 'Alors s\'ouvrit dans le ciel le temple de Dieu; l\'arche de l\'alliance apparut dans son temple, et il y eut des éclairs, des voix, des tonnerres, un tremblement de terre, et une forte grêle.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 1, 'Puis il parut un grand signe dans le ciel: c\'était une femme enveloppée du soleil, ayant la lune sous ses pieds, et sur sa tête une couronne de douze étoiles.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 2, 'Elle était enceinte, et elle jetait des cris, pendant qu\'elle était en proie aux souffrances et aux douleurs de l\'enfantement.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 3, 'Il parut aussi un autre signe dans le ciel: c\'était un grand dragon rouge, qui avait sept têtes et dix cornes, et sur ces têtes, sept diadèmes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 4, 'Sa queue entraînait le tiers des étoiles du ciel, et elle les jeta sur la terre; et le dragon se tint devant la femme qui allait enfanter, afin de dévorer son enfant, quand elle l\'aurait mis au monde.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 5, 'Elle mit au monde un enfant mâle, qui doit gouverner toutes les nations avec un sceptre de fer; et son enfant fut enlevé auprès de Dieu et de son trône.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 6, 'Quant à la femme, elle s\'enfuit dans le désert, où elle avait une retraite préparée par Dieu, pour y être nourrie pendant douze cent soixante jours.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 7, 'Alors il y eut un combat dans le ciel: Michel et ses anges combattaient contre le dragon, et le dragon combattait contre eux avec ses anges;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 8, 'mais ils ne furent pas les plus forts, et leur place même ne se retrouva plus dans le ciel.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 9, 'Puis il fut précipité, le grand dragon, le serpent ancien, appelé le Diable et Satan, celui qui séduit le monde entier; il fut précipité sur la terre, et ses anges furent précipités avec lui.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 10, 'J\'entendis dans le ciel une grande voix, qui disait: Maintenant est venu le salut, ainsi que la puissance et le règne de notre Dieu, et le pouvoir de son Christ; car il a été précipité, l\'accusateur de nos frères, qui les accusait jour et nuit devant notre Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 11, 'Ils l\'ont vaincu par le sang de l\'Agneau et par la parole de leur témoignage; ils n\'ont point aimé leur vie, ils n\'ont pas reculé devant la mort.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 12, 'C\'est pourquoi, réjouissez-vous, ô cieux, et vous qui en êtes les habitants! Malheur à la terre et à la mer! Car le Diable est descendu vers vous, rempli de fureur, sachant qu\'il ne lui reste que peu de temps.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 13, 'Quand le dragon vit qu\'il avait été précipité sur la terre, il poursuivit la femme qui avait mis au monde l\'enfant mâle.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 14, 'Mais les deux ailes du grand aigle furent données à la femme, pour s\'envoler au désert, vers sa retraite; c\'est là qu\'elle doit être nourrie un temps, et des temps, et la moitié d\'un temps, loin de la présence du serpent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 15, 'Alors le serpent lança de sa gueule après la femme, de l\'eau comme un fleuve, afin que le fleuve l\'emportât dans ses eaux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 16, 'Mais la terre vint au secours de la femme; car la terre ouvrit sa bouche et engloutit le fleuve que le dragon avait lancé de sa gueule.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 17, 'Puis le dragon, furieux contre la femme, s\'en alla faire la guerre au reste de ses enfants, qui observent les commandements de Dieu et qui gardent le témoignage de Jésus. Et il se tint debout sur le sable de la mer.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 1, 'Ensuite, je vis monter de la mer une bête qui avait dix cornes et sept têtes, et sur ses cornes dix diadèmes, et sur les sept têtes des noms blasphématoires.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 2, 'La bête que je vis ressemblait au léopard; ses pieds étaient comme ceux de l\'ours, et sa gueule comme celle du lion; et le dragon lui donna sa puissance, son trône, et une grande autorité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 3, 'L\'une de ses têtes était comme blessée à mort; mais cette blessure mortelle fut guérie, et la terre entière, saisie d\'admiration, suivit la bête.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 4, 'On se mit à adorer le dragon, parce qu\'il avait donné le pouvoir à la bête; et l\'on adora la bête elle-même, en disant: Qui est semblable à la bête, et qui peut combattre contre elle?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 5, 'Une bouche lui fut donnée, qui proférait des paroles orgueilleuses et des blasphèmes; et il lui fut donné le pouvoir d\'agir pendant quarante-deux mois.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 6, 'La bête ouvrit donc la bouche pour proférer des blasphèmes contre Dieu, pour blasphémer son nom, son tabernacle et ceux qui habitent dans le ciel.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 7, 'Il lui fut donné de faire la guerre aux saints et de les vaincre. Le pouvoir lui fut aussi accordé sur toute tribu, sur tout peuple, sur toute langue et sur toute nation.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 8, 'Tous les habitants de la terre l\'adorèrent, tous ceux dont les noms ne sont pas écrits dans le livre de la vie de l\'Agneau, qui a été immolé dès la fondation du monde.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 9, 'Que celui qui a des oreilles, entende!...');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 10, 'Celui qui emmène avec lui des captifs, sera lui-même captif; celui qui tue avec l\'épée, doit périr lui-même par l\'épée. Ici se montrent la patience et la foi des saints.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 11, 'Je vis encore monter de la terre une autre bête, qui avait deux cornes semblables à celles d\'un agneau, et qui parlait comme un dragon.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 12, 'Elle exerçait tout le pouvoir de la première bête en sa présence, et elle obligeait la terre et ses habitants à adorer la première bête, dont la blessure mortelle avait été guérie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 13, 'Elle opérait de grands prodiges, jusqu\'à faire descendre le feu du ciel sur la terre, à la vue des hommes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 14, 'Elle séduisait les habitants de la terre par les prodiges qu\'il lui avait été donné d\'accomplir en présence de la bête; elle disait aux habitants de la terre de faire une image en honneur de la bête, qui avait été blessée par l\'épée et qui était revenue à la vie.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 15, 'Il lui fut donné aussi d\'animer l\'image de la bête, afin que cette image parlât, et qu\'elle fît mettre à mort tous ceux qui n\'adoraient pas l\'image de la bête.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 16, 'Elle entraînait tous les hommes, petits et grands, riches et pauvres, libres et esclaves, à prendre une marque sur leur main droite ou sur leur front,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 17, 'en sorte que personne ne pouvait acheter ni vendre, sans avoir cette marque, c\'est-à-dire le nom de la bête ou le nombre de son nom.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 18, 'Ici se montre la sagesse: Que celui qui a de l\'intelligence calcule le nombre de la bête, car c\'est un nombre d\'hommes; et son nombre est six cent soixante-six.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 1, 'Je regardai, et je vis l\'Agneau qui se tenait sur la montagne de Sion, et avec lui cent quarante-quatre mille personnes, qui avaient son nom et le nom de son Père écrits sur leurs fronts.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 2, 'Puis j\'entendis une voix qui venait du ciel, semblable au bruit des grosses eaux et au bruit d\'un grand tonnerre; et la voix que j\'entendis était comme le son des harpes touchées par des harpistes:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 3, 'ils chantent un cantique nouveau devant le trône et devant les quatre animaux et les vieillards. Et personne ne pouvait apprendre ce cantique, si ce n\'est les cent quarante-quatre mille, qui ont été rachetés de la terre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 4, 'Ceux-là ne se sont point souillés avec des femmes; car ils sont vierges. Ceux-là suivent l\'Agneau partout où il va. Ils ont été rachetés parmi les hommes, comme des prémices consacrées à Dieu et à l\'Agneau;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 5, 'et dans leur bouche, il ne s\'est point trouvé de mensonge, car ils sont sans tache.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 6, 'Après cela, je vis un autre ange, qui volait au milieu du ciel, portant l\'Évangile éternel, pour l\'annoncer à ceux qui habitent sur la terre, à toute nation, à toute tribu, à toute langue et à tout peuple.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 7, 'Il disait d\'une voix forte: Craignez Dieu, et donnez-lui gloire; car l\'heure de son jugement est venue. Adorez Celui qui a fait le ciel, la terre, la mer et les sources d\'eaux!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 8, 'Un autre ange, un second, le suivit, qui disait: Elle est tombée, elle est tombée, Babylone la grande, qui a abreuvé toutes les nations du vin de son impudicité effrénée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 9, 'Un autre ange, un troisième, les suivit, disant d\'une voix forte: Si quelqu\'un adore la bête et son image, et qu\'il en prenne la marque sur le front ou sur la main,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 10, 'il boira, lui aussi, du vin du courroux de Dieu, versé pur dans la coupe de sa colère, et il sera tourmenté dans le feu et le soufre, en présence des saints anges et en présence de l\'Agneau.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 11, 'Et la fumée de leur tourment monte aux siècles des siècles. Jour et nuit, il n\'y aura aucun repos, ni pour ceux qui adorent la bête et son image, ni pour ceux qui prennent la marque de son nom.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 12, 'Ici se montre la patience des saints: ils gardent les commandements de Dieu et la foi en Jésus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 13, 'J\'entendis une voix venant du ciel, qui disait: Écris: Heureux, dès à présent, les morts qui meurent dans le Seigneur! Oui, dit l\'Esprit; car ils se reposent de leurs travaux, et leurs oeuvres les suivent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 14, 'Je regardai, et je vis une nuée blanche, et sur cette nuée était assis quelqu\'un qui ressemblait à un fils d\'homme: il avait sur la tête une couronne d\'or, et à la main une faucille tranchante.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 15, 'Un autre ange sortit du temple, criant d\'une voix forte à celui qui était assis sur la nuée: Lance ta faucille et moissonne; car le temps de moissonner est venu, la moisson de la terre est mûre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 16, 'Alors celui qui était assis sur la nuée lança sa faucille sur la terre, et la terre fut moissonnée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 17, 'Un autre ange sortit du temple qui est dans le ciel, tenant, lui aussi, une faucille tranchante.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 18, 'Un autre ange qui avait pouvoir sur le feu, sortit de l\'autel. Il cria, d\'une voix forte, à celui qui tenait la faucille tranchante, et il lui dit: Lance ta faucille tranchante, et vendange les grappes de la vigne de la terre; car ses raisins sont mûrs.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 19, 'L\'ange lança sa faucille sur la terre et vendangea la vigne de la terre; et il jeta la vendange dans la grande cuve de la colère de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 20, 'La cuve fut foulée hors de la ville; et de la cuve il sortit du sang qui montait jusqu\'aux freins des chevaux, sur un espace de mille six cents stades.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 1, 'Je vis dans le ciel un autre prodige, grand et admirable: sept anges portaient sept fléaux, les derniers; car c\'est par ces fléaux que doit se consommer le courroux de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 2, 'Puis je vis comme une mer de verre, mêlée de feu, et ceux qui avaient vaincu la bête et son image et le nombre de son nom, debout sur cette mer de verre, tenant les harpes de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 3, 'Ils chantent le cantique de Moïse, serviteur de Dieu, et le cantique de l\'Agneau, en disant: Tes oeuvres sont grandes et admirables, Seigneur, Dieu tout-puissant! Tes voies sont justes et véritables, ô Roi des nations!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 4, 'Qui ne craindrait Seigneur, et qui ne glorifierait ton nom? Car seul tu es saint; et toutes les nations viendront se prosterner devant toi, parce que tes jugements ont été manifestés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 5, 'Après cela, je vis s\'ouvrir dans le ciel le sanctuaire du tabernacle du témoignage.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 6, 'Les sept anges, qui tenaient les sept fléaux, sortirent du temple, vêtus d\'un lin pur et éclatant, et ceints, sur la poitrine, de ceintures d\'or.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 7, 'L\'un des quatre animaux donna aux sept anges sept coupes d\'or, pleines de la colère du Dieu qui vit aux siècles des siècles.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 8, 'Le temple fut rempli de fumée par la gloire de Dieu et par sa puissance; et personne ne pouvait entrer dans le temple, jusqu\'à ce que les sept fléaux des sept anges fussent accomplis.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 1, 'Alors j\'entendis une grande voix qui venait du temple, et qui disait aux sept anges: Allez, et versez sur la terre les sept coupes de la colère de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 2, 'Le premier ange s\'en alla et versa sa coupe sur la terre; et un ulcère malin et douloureux frappa les hommes qui avaient la marque de la bête, et qui adoraient son image.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 3, 'Le deuxième ange versa sa coupe dans la mer; et la mer devint du sang, comme le sang d\'un mort; et tous les êtres vivants, qui se trouvaient dans la mer, moururent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 4, 'Le troisième ange versa sa coupe dans les fleuves et les sources des eaux; et les eaux devinrent du sang.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 5, 'Alors j\'entendis l\'ange des eaux, qui disait: Tu es juste, toi qui es, et qui étais, toi le Saint, parce que tu as exercé ce jugement.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 6, 'Car ils ont répandu le sang des saints et des prophètes, et tu leur as donné du sang à boire: ils sont dignes d\'un tel châtiment.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 7, 'Et j\'entendis l\'autel, qui disait: Oui, Seigneur, Dieu tout-puissant, tes jugements sont vrais et justes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 8, 'Le quatrième ange versa sa coupe sur le soleil; et il lui fut donné de brûler les hommes par le feu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 9, 'Les hommes furent consumés par une chaleur extrême; ils blasphémèrent le nom de Dieu, qui a ces fléaux en son pouvoir, et ils ne se repentirent pas pour lui donner gloire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 10, 'Le cinquième ange versa sa coupe sur le trône de la bête; son royaume fut plongé dans les ténèbres, et les hommes se mordaient la langue de douleur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 11, 'Ils blasphémèrent contre le Dieu du ciel à cause de leurs douleurs et de leurs ulcères; et ils ne se repentirent pas de leurs mauvaises actions.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 12, 'Le sixième ange versa sa coupe sur le grand fleuve de l\'Euphrate; et le fleuve fut mis à sec, pour livrer passage aux rois venant de l\'Orient.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 13, 'Je vis sortir de la bouche du dragon et de la bouche de la bête, ainsi que de la bouche du faux prophète, trois esprits impurs, semblables à des grenouilles.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 14, 'Ce sont des esprits de démons qui font des prodiges, et qui vont trouver les rois de toute la terre, afin de les rassembler pour la bataille du grand jour du Dieu tout-puissant.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 15, 'Me voici! Je viens comme un voleur. Heureux celui qui veille et qui garde ses vêtements, pour ne pas aller nu et ne pas laisser voir sa honte! —');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 16, 'Puis ils furent rassemblés dans le lieu qui s\'appelle, en hébreu, Harmaguédon.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 17, 'Le septième ange versa sa coupe dans l\'air; et il sortit du temple une grande voix, qui venait du trône et qui disait: C\'en est fait!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 18, 'Il y eut des éclairs, des voix, des tonnerres, et un grand tremblement de terre, un tremblement tel, qu\'il n\'y en eut jamais de si grand depuis qu\'il y a des hommes sur la terre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 19, 'La grande ville fut divisée en trois parties, et les villes des nations s\'écroulèrent; et Dieu se souvint de la grande Babylone, pour lui faire boire la coupe du vin de son ardent courroux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 20, 'Toutes les îles s\'enfuirent, et les montagnes disparurent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 21, 'Des grêlons énormes, du poids d\'un talent, tombèrent du ciel sur les hommes; et les hommes blasphémèrent contre Dieu à cause du fléau de la grêle; car c\'était un fléau terrible.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 1, 'Alors l\'un des sept anges qui tenaient les sept coupes s\'approcha; et, m\'adressant la parole, il me dit: Viens, je te montrerai le jugement de la grande prostituée, qui est assise sur de grandes eaux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 2, 'C\'est avec elle que les rois de la terre se sont livrés à l\'impudicité, et du vin de son impudicité les habitants de la terre ont été enivrés.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 3, 'Il me transporta en esprit dans un désert; et je vis une femme assise sur une bête de couleur écarlate, couverte de noms blasphématoires, et qui avait sept têtes et dix cornes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 4, 'Cette femme était vêtue, de pourpre et d\'écarlate, parée d\'or, de pierres précieuses et de perles; elle tenait à la main une coupe d\'or, pleine des abominations et de la souillure de ses impudicités.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 5, 'Sur son front était écrit un nom, un nom mystérieux: Babylone la grande, la mère des impudiques et de toutes les infamies de la terre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 6, 'Je vis cette femme enivrée du sang des saints et du sang des martyrs de Jésus; et en la voyant, je fus saisi d\'un grand étonnement.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 7, 'L\'ange me dit: Pourquoi t\'étonnes-tu? Je t\'expliquerai le mystère de la femme et de la bête qui la porte, et qui a sept têtes et dix cornes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 8, 'La bête que tu as vue était, et elle n\'est plus; elle doit monter de l\'abîme et s\'en aller à la perdition. Et les habitants de la terre, dont le nom n\'est pas écrit dans le livre de vie depuis la fondation du monde, s\'étonneront en voyant la bête, parce qu\'elle était et qu\'elle n\'est plus, et qu\'elle reparaîtra.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 9, 'C\'est ici qu\'il faut une intelligence guidée par la sagesse. Les sept têtes sont sept montagnes, sur lesquelles la femme est assise.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 10, 'Elles ont aussi sept rois; les cinq premiers sont tombés, l\'un existe, et l\'autre n\'est pas encore venu; quand il sera venu, il ne doit durer que peu de temps.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 11, 'Et la bête qui était, et qui n\'est plus, est elle-même un huitième roi; elle est en même temps du nombre des sept, et elle s\'en va à la perdition.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 12, 'Et les dix cornes que tu as vues, sont dix rois qui n\'ont pas encore reçu de royaume; mais ils reçoivent le pouvoir royal, pour une heure, avec la bête.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 13, 'Ils ont un seul et même dessein, et ils donnent à la bête leur puissance et leur autorité.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 14, 'Ils combattront contre l\'Agneau, et l\'Agneau les vaincra, parce qu\'il est le Seigneur des Seigneurs et le Roi des rois; et les appelés, les élus et les fidèles qui sont avec lui, les vaincront aussi.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 15, 'Puis il me dit: Les eaux que tu as vues, sur lesquelles est assise la prostituée, ce sont des peuples, des multitudes, des nations, et des langues.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 16, 'Les dix cornes que tu as vues, et la bête elle-même, haïront la prostituée, la dépouilleront et la mettront à nu, mangeront ses chairs et la consumeront par le feu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 17, 'Car Dieu leur a mis au coeur d\'exécuter son dessein, d\'avoir une même pensée, et de donner leur royaume à la bête, jusqu\'à ce que les paroles de Dieu soient accomplies.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 18, 'Et la femme que tu as vue, c\'est la grande ville, qui exerce la royauté sur les rois de la terre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 1, 'Après cela, je vis descendre du ciel un autre ange, qui avait une grande puissance; et la terre fut illuminée de sa gloire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 2, 'Il cria d\'une voix forte et dit: Elle est tombée, elle est tombée, Babylone la grande! Elle est devenue la demeure des démons, la prison de tout esprit impur, la prison de tout oiseau immonde et odieux,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 3, 'parce que toutes les nations ont bu du vin de son impudicité effrénée, parce que les rois de la terre se sont livrés à l\'impudicité avec elle, et que les marchands de la terre se sont enrichis de l\'abondance de son luxe.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 4, 'J\'entendis une autre voix, venant du ciel, qui disait: Sortez de Babylone, ô mon peuple, de peur qu\'en participant à ses péchés, vous n\'ayez aussi part à ses plaies;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 5, 'car ses péchés se sont accumulés jusqu\'au ciel, et Dieu s\'est souvenu de ses iniquités.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 6, 'Faites-lui ce qu\'elle a fait aux autres; rendez-lui le double de ses oeuvres; versez-lui à boire au double, dans la coupe où elle a fait boire les autres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 7, 'Autant elle s\'est glorifiée et s\'est plongée dans les délices, autant donnez-lui de tourment et d\'affliction. Car elle dit en son coeur: Je suis une reine sur son trône; je ne suis pas veuve, et je ne connaîtrai point le deuil.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 8, 'C\'est pourquoi, dans un même jour, viendront sur elle ces fléaux, la mort, le deuil, la famine, et elle sera consumée par le feu; car c\'est un puissant Seigneur que le Dieu qui l\'a jugée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 9, 'Les rois de la terre, qui se sont livrés à l\'impudicité et qui ont vécu dans les délices avec elle, pleureront sur elle et se lamenteront, lorsqu\'ils verront la fumée de son embrasement.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 10, 'Se tenant à distance, dans la crainte de partager son tourment, ils diront: Malheur! Malheur! Babylone, grande ville, ville puissante! En une heure, est venu ton jugement!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 11, 'Les marchands de la terre pleurent aussi et s\'affligent sur elle, parce que personne n\'achète plus leurs marchandises:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 12, 'marchandises d\'or et d\'argent, pierres précieuses, perles, fin lin, pourpre, soie, écarlate; bois odoriférants de tous genres; objets de toute espèce en ivoire, en bois précieux, en airain, en fer et en marbre;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 13, 'cinnamome, myrrhe, parfums, huiles aromatiques, encens; vin, huile, fleur de farine, blé; boeufs, moutons, chevaux, chariots, corps et âmes d\'hommes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 14, 'Ces fruits que convoitait ton âme te sont enlevés; toutes ces splendeurs et ces magnificences sont perdues pour toi! On ne les retrouvera plus jamais.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 15, 'Ces marchands, qui se sont enrichis avec Babylone, se tiendront à distance, dans la crainte de partager son tourment. Ils pleureront et s\'affligeront,');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 16, 'en disant: Malheur! Malheur! Cette grande ville, qui était vêtue de lin fin, de pourpre et d\'écarlate, toute brillante d\'or, de pierreries et de perles! En une heure ont été détruites toutes ces grandes richesses!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 17, 'Tous les pilotes, tous les navigateurs et tous les matelots, tous ceux qui trafiquent sur mer, se tenaient à distance;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 18, 'et ils s\'écriaient, en voyant la fumée de son embrasement: Quelle ville était semblable à cette grande ville?');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 19, 'Ils jetaient de la poussière sur leurs têtes, ils criaient en pleurant et en se lamentant, et ils disaient: Malheur! Malheur! Cette grande ville, qui enrichissait de son opulence tous ceux qui avaient des vaisseaux sur la mer, en une heure elle a été réduite en désert!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 20, 'Ciel, réjouis-toi de sa ruine, et vous, les saints, les apôtres, les prophètes, réjouissez-vous aussi; car, en la jugeant. Dieu vous a fait justice.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 21, 'Alors un ange puissant prit une pierre semblable à une grande meule, et il la jeta dans la mer, en disant: Ainsi sera précipitée avec violence Babylone, la grande ville, et on ne la retrouvera plus!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 22, 'On n\'entendra plus chez toi les sons des joueurs de harpe, des musiciens, des joueurs de flûte et de trompette. On n\'y trouvera plus aucun artisan d\'un métier quelconque; et le bruit de la meule ne s\'y fera plus entendre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 23, 'La lumière de la lampe n\'y brillera plus, et on n\'y entendra plus la voix de l\'époux et de l\'épouse, parce que tes marchands étaient les grands de la terre, parce que toutes les nations ont été séduites par tes maléfices.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 24, 'C\'est dans cette ville qu\'a été trouvé le sang des prophètes et des saints, et de tous ceux qui ont été égorgés sur la terre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 1, 'Après cela, j\'entendis dans le ciel comme la grande voix d\'une foule immense qui disait: Alléluia! Le salut, la gloire et la puissance appartiennent à notre Dieu!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 2, 'Car ses jugements sont vrais et justes: Il a jugé la grande prostituée, qui corrompait la terre par ses impudicités, et il a exercé sa vengeance contre elle, dont la main avait répandu le sang de ses serviteurs.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 3, 'Et pour la seconde fois ils dirent: Alléluia! Sa fumée monte, aux siècles des siècles.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 4, 'Alors les vingt-quatre vieillards et les quatre animaux se prosternèrent et adorèrent Dieu, Celui qui est assis sur le trône, et ils disaient: Amen, Alléluia!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 5, 'Et il vint du trône une voix qui disait: Louez notre Dieu, vous tous, ses serviteurs qui le craignez, petits et grands!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 6, 'Puis, j\'entendis comme la voix d\'une foule immense, telle que le bruit de grandes eaux ou le bruit de violents tonnerres, qui disait: Alléluia! Car il est entré dans son règne, le Seigneur, notre Dieu, le Tout-Puissant.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 7, 'Réjouissons-nous, faisons éclater notre joie, et rendons-lui gloire; car les noces de l\'Agneau sont venues, et son épouse s\'est parée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 8, 'Il lui a été donné de se vêtir de fin lin, éclatant et pur. — Le fin lin, ce sont les oeuvres de justice des saints.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 9, 'L\'ange me dit: Écris: Heureux ceux qui sont invités au banquet des noces de l\'Agneau! Il me dit encore: Ce sont là les véritables paroles de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 10, 'Alors je me jetai à ses pieds pour l\'adorer; mais il me dit: Garde-toi de le faire; je suis ton compagnon de service et celui de tes frères qui gardent le témoignage de Jésus. Adore Dieu! — Le témoignage de Jésus, c\'est l\'esprit de la prophétie. —');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 11, 'Alors je vis le ciel ouvert, et il parut un cheval blanc: celui qui le montait s\'appelle le «Fidèle» et le «Véritable»; il juge et combat avec justice.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 12, 'Ses yeux sont une flamme de feu; sur sa tête il y a plusieurs diadèmes, et il porte un nom écrit, que personne ne connaît que lui-même.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 13, 'Il est revêtu d\'un manteau teint de sang, et il est appelé de ce nom: La Parole de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 14, 'Les armées qui sont dans le ciel le suivaient, montées sur des chevaux blancs et vêtues de fin lin, blanc et pur.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 15, 'De sa bouche sort une épée tranchante, dont il va frapper les nations, et il les gouvernera avec un sceptre de fer. Il foule la cuve du vin de l\'indignation et de la colère du Dieu tout puissant.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 16, 'Sur son manteau et sur sa cuisse, il porte ce nom écrit: Roi des rois et Seigneur des seigneurs.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 17, 'Alors je vis un ange debout dans le soleil. Il cria d\'une voix forte à tous les oiseaux qui volaient dans le milieu du ciel: Venez, rassemblez-vous pour le grand festin de Dieu;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 18, 'venez manger la chair des rois, la chair des capitaines, la chair dés puissants, la chair des chevaux et de ceux qui les montent, et la chair de tous les hommes, libres et esclaves, petits et grands.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 19, 'Puis je vis la bête, et les rois de la terre, et leurs armées, rassemblés pour faire la guerre à celui qui était monté sur le cheval et son armée.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 20, 'Mais la bête fut saisie, et avec elle le faux prophète, qui avait accompli devant elle les prodiges par lesquels il avait séduit ceux qui avaient pris la marque de la bête et qui adoraient son image; tous deux furent jetés vivants dans l\'étang ardent de feu et de soufre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 21, 'Les autres furent tués par l\'épée qui sortait de la bouche de celui qui était monté sur le cheval; et tous les oiseaux se rassasièrent de leur chair.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 1, 'Puis je vis descendre du ciel un ange, qui tenait à la main la clef de l\'abîme et une grande chaîne.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 2, 'Il saisit le dragon, le serpent ancien, qui est le Diable, Satan, et il l\'enchaîna pour mille ans.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 3, 'Il le jeta dans l\'abîme et il en ferma l\'entrée, qu\'il scella sur lui, afin qu\'il ne séduisît plus les nations, jusqu\'à ce que les mille ans fussent accomplis. Après cela, il faut que Satan soit délié pour un peu de temps.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 4, 'Je vis ensuite des trônes, et à ceux qui s\'assirent sur ces trônes fut donné le pouvoir d\'exercer le jugement. Je vis aussi les âmes de ceux qui avaient été décapités pour avoir rendu témoignage à Jésus et pour avoir cru à la parole de Dieu, et les âmes de tous ceux qui n\'avaient pas adoré la bête, ni son image, et qui n\'avaient pas pris sa marque, ni sur leur front, ni sur leurs mains. Ils revinrent à la vie et régnèrent avec le Christ pendant mille ans.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 5, 'Les autres morts ne revinrent pas à la vie avant que les mille ans fussent accomplis. C\'est la première résurrection.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 6, 'Heureux et saints, ceux qui ont part à la première résurrection! La seconde mort n\'a aucun pouvoir sur eux; mais ils seront sacrificateurs de Dieu et du Christ, et ils régneront avec lui pendant les mille ans.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 7, 'Quand les mille ans seront accomplis, Satan sera délié;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 8, 'il sortira de sa prison pour séduire les peuples qui sont aux quatre coins de la terre, Gog et Magog. Il les rassemblera pour combattre, aussi nombreux que le sable de la mer.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 9, 'Ils montèrent sur toute l\'étendue de la terre, et ils investiront le camp des saints et la cité bien-aimée. Mais il descendit du ciel un feu qui les dévora.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 10, 'Le Diable, qui les séduisait, fut jeté dans l\'étang de feu et de soufre, où sont aussi la bête et le faux prophète. Et ils seront tourmentés jour et nuit, aux siècles des siècles.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 11, 'Alors je vis un grand trône blanc ainsi que celui qui était assis sur ce trône; devant sa face la terre et le ciel s\'enfuirent, et il n\'y eut plus de place pour eux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 12, 'Puis, je vis les morts, grands et petits, debout devant le trône, et des livres furent ouverts. On ouvrit aussi un autre livre, qui est le livre de vie; et les morts furent jugés selon leurs oeuvres, d\'après ce qui était écrit dans ces livres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 13, 'La mer rendit les morts qu\'elle renfermait. La Mort et le Sépulcre rendirent aussi leurs morts. Et ils furent jugés, chacun selon ses oeuvres.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 14, 'Ensuite la Mort et le Sépulcre furent jetés dans l\'étang de feu. Cet étang de feu, c\'est la seconde mort.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 15, 'Quiconque ne fut pas trouvé inscrit dans le livre de vie, fut jeté dans l\'étang de feu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 1, 'Puis, je vis un ciel nouveau et une terre nouvelle; car le premier ciel et la première terre avaient disparu, et la mer n\'était plus.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 2, 'Je vis aussi la cité sainte, la Jérusalem nouvelle, qui descendait du ciel, d\'auprès de Dieu, prête comme une épouse qui s\'est parée pour son époux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 3, 'Et j\'entendis une voix forte qui venait du trône, et qui disait: Voici le Tabernacle de Dieu au milieu des hommes! Il habitera avec eux, et ils seront son peuple; Dieu lui-même sera avec eux.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 4, 'Il essuiera toute larme de leurs yeux; la mort ne sera plus, et il n\'y aura plus ni deuil, ni cri, ni souffrance; car les premières choses auront disparu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 5, 'Celui qui était assis sur le trône dit: ô Je vais renouveler toutes choses. Puis il ajouta: Écris; car ces paroles sont certaines et véritables.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 6, 'Il me dit encore: C\'en est fait! Je suis l\'Alpha et l\'Oméga, le commencement et la fin. A celui qui a soif, je donnerai gratuitement de la source de l\'eau vive.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 7, 'Celui qui vaincra, héritera ces choses; et je serai son Dieu, et il sera mon fils.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 8, 'Quant aux lâches, aux incrédules, aux abominables, aux meurtriers, aux impudiques, aux magiciens, aux idolâtres et à tous les menteurs, leur part est dans l\'étang ardent de feu et de soufre: c\'est la seconde mort.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 9, 'L\'un des sept anges qui avaient tenu les sept coupes, pleines des sept derniers fléaux, vint à moi et me dit: Viens; je te montrerai la fiancée, l\'épouse de l\'Agneau.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 10, 'Il me transporta en esprit sur une grande et haute montagne, et il me montra la cité sainte, Jérusalem, qui descendait du ciel, d\'auprès de Dieu, resplendissante de la gloire de Dieu.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 11, 'Son éclat était semblable à celui d\'une pierre précieuse, d\'une pierre de jaspe cristallin.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 12, 'Elle avait une grande et haute muraille, avec douze portes, et sur les portes étaient douze anges, et des noms écrits, qui sont les noms des douze tribus des enfants d\'Israël:');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 13, 'à l\'Orient, trois portes; au Nord, trois portes; au Midi, trois portes; à l\'Occident, trois portes.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 14, 'La muraille de la ville avait douze fondements, sur lesquels étaient douze noms, les noms des douze apôtres de l\'Agneau.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 15, 'Celui qui me parlait tenait une mesure, un roseau d\'or pour mesurer la ville, ses portes et sa muraille.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 16, 'La ville est disposée en carré, et sa longueur est égale à sa largeur. Il mesura la ville avec le roseau; elle avait douze mille stades; sa longueur, sa largeur et sa hauteur étaient égales.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 17, 'Il mesura aussi la muraille: elle avait cent quarante-quatre coudées, mesure d\'homme, qui était celle de l\'ange.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 18, 'La muraille était bâtie en jaspe, et la ville était d\'un or pur, semblable à un pur cristal.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 19, 'Les fondements de la muraille de la ville étaient ornés de pierres précieuses de toute espèce. Le premier était de jaspe; le second, de saphir; le troisième, de calcédoine; le quatrième, d\'émeraude;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 20, 'le cinquième, de sardoine; le sixième, de cornaline; le septième, de chrysolithe; le huitième, de béryl; le neuvième, de topaze; le dixième, de chrysoprase; le onzième, d\'hyacinthe; le douzième, d\'améthyste.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 21, 'Les douze portes étaient douze perles, chaque porte formée d\'une seule perle. Et la place de la ville était en or pur, semblable à un cristal transparent.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 22, 'Je n\'y vis point de temple; car le Seigneur Dieu tout-puissant en est le temple, ainsi que l\'Agneau.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 23, 'La ville n\'a besoin ni de soleil, ni de lune, pour l\'éclairer; car la gloire de Dieu l\'éclairé, et l\'Agneau est son flambeau.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 24, 'Les nations marcheront à sa lumière, et les rois de la terre y apporteront leur gloire.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 25, 'Ses portes ne se fermeront jamais pendant le jour; et là, il n\'y aura plus de nuit.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 26, 'On y apportera la gloire et les richesses des nations;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 27, 'il n\'y entrera rien de souillé, ni personne qui se livre à l\'abomination et au mensonge, mais ceux-là seuls qui sont inscrits dans le livre de vie de l\'Agneau.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 1, 'Puis, l\'ange me montra le fleuve de l\'eau de la vie, clair comme du cristal, qui sortait du trône de Dieu et de l\'Agneau.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 2, 'Au milieu de la place de la ville et sur les deux bords du fleuve se trouve l\'arbre de vie, qui donne douze récoltes, produisant ses fruits chaque mois; et les feuilles de cet arbre sont pour la guérison des nations.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 3, 'Il n\'y aura plus d\'anathème; le trône de Dieu et de l\'Agneau sera dans la ville; ses serviteurs le serviront;');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 4, 'ils verront sa face, et son nom sera sur leurs fronts.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 5, 'La nuit ne sera plus. Ils n\'auront besoin ni de la lumière d\'une lampe, ni de la lumière du soleil, parce que le Seigneur Dieu les éclairera; et ils régneront aux siècles des siècles.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 6, 'Alors l\'ange me dit: Ces paroles sont certaines et véritables, et le Seigneur, le Dieu des esprits des prophètes, a envoyé son ange pour montrer à ses serviteurs ce qui doit bientôt arriver.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 7, 'Me voici: Je viens bientôt. Heureux celui qui garde les paroles de la prophétie de ce livre!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 8, 'C\'est moi, Jean, qui ai vu et entendu ces choses. Après les avoir entendues et vues, je me jetai aux pieds de l\'ange qui me les montrait, pour l\'adorer.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 9, 'Mais il me dit: Garde-toi de le faire! Je suis ton compagnon de service, et celui de tes frères, les prophètes, et de ceux qui gardent les paroles de ce livre. Adore Dieu!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 10, 'Il me dit ensuite: Ne scelle pas les paroles de la prophétie de ce livre; car le temps est proche.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 11, 'Que celui qui est injuste, soit encore injuste, et que celui qui est souillé, se souille encore; que celui qui est juste, pratique encore la justice, et que celui qui est saint, se sanctifie encore!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 12, 'Me voici: Je viens bientôt, et j\'apporte avec moi la rétribution: je rendrai à chacun selon son oeuvre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 13, 'Je suis l\'Alpha et l\'Oméga, le premier et le dernier, le commencement et la fin.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 14, 'Heureux ceux qui lavent leurs robes, pour avoir droit à l\'arbre de la vie, et pour entrer par les portes dans la ville!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 15, 'Dehors seront les chiens, les magiciens, les impudiques, les meurtriers, les idolâtres, tous ceux qui aiment et pratiquent le mensonge!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 16, 'Moi, Jésus, j\'ai envoyé mon ange pour vous rendre témoignage de ces choses devant les Eglises. Je suis le rejeton et la postérité de David, l\'étoile brillante du matin.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 17, 'L\'Esprit et l\'Épouse disent: Viens! Que celui qui l\'entend, dise aussi: Viens! Que celui qui a soif, vienne. Que celui qui le veut, reçoive gratuitement de l\'eau vive!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 18, 'Je le déclare à quiconque entend les paroles de la prophétie de ce livre: Si quelqu\'un y ajoute quelque chose, Dieu fera venir sur lui les fléaux décrits dans ce livre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 19, 'Si quelqu\'un retranche quelque chose des paroles du livre de cette prophétie, Dieu retranchera sa part de l\'arbre de vie et de la ville sainte, qui sont décrits dans ce livre.');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 20, 'Celui qui rend témoignage de ces choses, dit: Oui, je viens bientôt. — Amen! — Viens, Seigneur Jésus!');
INSERT INTO `FreSynodale1921_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 21, 'Que la grâce du Seigneur Jésus soit avec tous!');
